/**
 * Badge Affordance
 *
 * Matte corner badge with optional breathing dot.
 * Refined presence — visible but not demanding.
 *
 * Uses anime.js for subtle dot pulse.
 */

import { useEffect, useRef } from 'react'
import { animate } from 'animejs'
import type { BadgeableData } from '@/lib/capabilities/types'
import { COLORS, GEOMETRY, TYPOGRAPHY, TIMING, EASING } from '@/lib/capabilities/tokens'

export interface BadgeProps extends BadgeableData {
  className?: string
}

const POSITION_STYLES: Record<NonNullable<BadgeableData['position']>, React.CSSProperties> = {
  'top-right': { top: GEOMETRY.badge.offsetY, right: GEOMETRY.badge.offsetX },
  'top-left': { top: GEOMETRY.badge.offsetY, left: GEOMETRY.badge.offsetX },
  'bottom-right': { bottom: GEOMETRY.badge.offsetY, right: GEOMETRY.badge.offsetX },
  'bottom-left': { bottom: GEOMETRY.badge.offsetY, left: GEOMETRY.badge.offsetX },
}

export function Badge({
  text,
  color = 'cyan',
  position = 'top-right',
  dot,
  className = '',
}: BadgeProps) {
  const dotRef = useRef<HTMLDivElement>(null)
  const colorValues = COLORS.accent[color] ?? COLORS.accent.cyan

  useEffect(() => {
    if (!dot || !dotRef.current) return

    // Slow, meditative breathing for dot
    const animation = animate(dotRef.current, {
      scale: TIMING.badge.dotScale,
      opacity: [0.6, 1, 0.6],
      duration: TIMING.badge.dotPeriod,
      ease: EASING.anime.breathing,
      loop: true,
    })

    return () => animation.pause()
  }, [dot])

return () => animation.pause()
  }, [dot])

  if (dot) {
    return (
      <div
        ref={dotRef}
        className={`absolute pointer-events-none ${className}`}
        style={{
          ...POSITION_STYLES[position],
          width: 6,
          height: 6,
          borderRadius: GEOMETRY.radius.full,
          backgroundColor: colorValues.solid,
          // Subtle glow, not harsh
          boxShadow: `0 0 6px 0 ${colorValues.glow}`,
          transformOrigin: 'center',
        }}
      />
    )
  }

  return (
    <div
      className={`absolute pointer-events-none ${className}`}
      style={{
        ...POSITION_STYLES[position],
        minWidth: GEOMETRY.badge.minWidth,
        padding: '2px 6px',
        fontSize: TYPOGRAPHY.fontSize.xxs,
        fontFamily: TYPOGRAPHY.fontFamily.mono,
        fontWeight: TYPOGRAPHY.fontWeight.medium,
        letterSpacing: '0.05em',
        textTransform: 'uppercase',
        // Matte background — barely there
        backgroundColor: colorValues.muted,
        border: `1px solid ${colorValues.border}`,
        color: colorValues.base,
        borderRadius: GEOMETRY.radius.sm,
        textAlign: 'center',
      }}
    >
      {text}
    </div>
  )
}

export default Badge

/**
 * CapabilityRenderer
 *
 * Centralizes ALL capability rendering logic.
 * No more scattered conditionals — this is the single system.
 *
 * Consumer just needs: <CapabilityRenderer entityId={id} hovered={hovered} />
 */

import { useEntity } from '@/lib/capabilities/registry'
import type { EntityComponents } from '@/lib/capabilities/types'
import { GlowRing } from './GlowRing'
import { Tooltip } from './Tooltip'
import { Badge } from './Badge'
import { DraggableAffordance } from './DraggableAffordance'
import { SelectionRing } from './SelectionRing'

export interface CapabilityRendererProps {
  /** Entity ID to render capabilities for */
  entityId: string

  /** Hover state for tooltip visibility */
  hovered?: boolean

  /** Focus state (future use) */
  focused?: boolean

  /** Additional className for wrapper */
  className?: string
}

/**
 * Renders all attached capabilities for an entity.
 *
 * This is the "System" in ECS terms — it processes all components
 * and renders the appropriate affordances.
 */
export function CapabilityRenderer({
  entityId,
  hovered = false,
  focused = false,
  className = '',
}: CapabilityRendererProps) {
  const entity = useEntity(entityId)

  // No capabilities attached? Render nothing.
  if (Object.keys(entity).length === 0) {
    return null
  }

  return (
    <div className={`contents ${className}`}>
      {/* Glowable: ring effect */}
      {entity.glowable && <GlowRing {...entity.glowable} />}

      {/* Tooltippable: hover tooltip */}
      {entity.tooltippable && (
        <Tooltip {...entity.tooltippable} visible={hovered} />
      )}

      {/* Badgeable: corner badge */}
      {entity.badgeable && <Badge {...entity.badgeable} />}

      {/* Draggable: drag handle affordance */}
      {entity.draggable && <DraggableAffordance {...entity.draggable} />}

{/* Draggable: drag handle affordance */}
      {entity.draggable && <DraggableAffordance {...entity.draggable} />}

      {/* Pulsable: handled via glowable.animated for now */}
      {/* Future: dedicated pulse wrapper */}

      {/* Clickable: cursor handled by withCapable */}

      {/* Selectable: selection ring */}
      {entity.selectable && <SelectionRing {...entity.selectable} />}

      {/* Focusable: future focus ring */}
    </div>
  )
}

/**
 * Standalone version that also provides the entity data
 * Useful when you need entity data outside the renderer
 */
export function useCapabilityRenderer(entityId: string) {
  const entity = useEntity(entityId)

  const render = (hovered = false, focused = false) => (
    <CapabilityRenderer
      entityId={entityId}
      hovered={hovered}
      focused={focused}
    />
  )

  return {
    entity,
    render,
    hasCapabilities: Object.keys(entity).length > 0,
  }
}

export default CapabilityRenderer

/**
 * Renders draggable affordance — positioned at top-left corner.
 *
 * Uses @dnd-kit setActivatorNodeRef pattern:
 * - Wrapper is just visual indicator
 * - Actual drag activation happens via parent's drag handle ref
 */
export function DraggableAffordance({
  showHandle = true,
  axis = 'both',
  dragEffect = 'ghost',
  className = '',
}: DraggableAffordanceProps) {
  // Hide if showHandle is false
  if (!showHandle) {
    return null
  }

  return (
    <div
      className={`
        absolute top-1 left-1 z-10
        flex items-center justify-center
        w-4 h-6 rounded
        cursor-grab active:cursor-grabbing
        transition-colors duration-150
        hover:bg-white/10
        ${className}
      `}
      style={{
        color: COLORS.neutral[500],
      }}
      data-drag-handle
      data-drag-axis={axis}
      data-drag-effect={dragEffect}
    >
      <GripIcon axis={axis} />
    </div>
  )
}

/**
 * Props interface for components integrating with @dnd-kit
 * Use with useDraggable hook:
 *
 * ```tsx
 * const { listeners, setActivatorNodeRef } = useDraggable({ id })
 *
 * <DraggableAffordanceHandle
 *   ref={setActivatorNodeRef}
 *   {...listeners}
 *   {...draggableData}
 * />
 * ```
 */
export interface DraggableAffordanceHandleProps extends DraggableAffordanceProps {
  /** Forward ref for @dnd-kit setActivatorNodeRef */
  onPointerDown?: React.PointerEventHandler
  onKeyDown?: React.KeyboardEventHandler
}

/**
 * Interactive drag handle that integrates with @dnd-kit.
 * Use this when you need the handle to be the drag activator.
 */
import { forwardRef } from 'react'

/**
 * Interactive drag handle that integrates with @dnd-kit.
 * Use this when you need the handle to be the drag activator.
 */
import { forwardRef } from 'react'

export const DraggableAffordanceHandle = forwardRef<
  HTMLDivElement,
  DraggableAffordanceHandleProps
>(function DraggableAffordanceHandle(
  {
    showHandle = true,
    axis = 'both',
    dragEffect = 'ghost',
    className = '',
    onPointerDown,
    onKeyDown,
    ...props
  },
  ref
) {
  if (!showHandle) {
    return null
  }

  return (
    <div
      ref={ref}
      className={`
        absolute top-1 left-1 z-10
        flex items-center justify-center
        w-4 h-6 rounded
        cursor-grab active:cursor-grabbing
        transition-colors duration-150
        hover:bg-white/10
        focus:outline-none focus:ring-1 focus:ring-cyan-500/50
        ${className}
      `}
      style={{
        color: COLORS.neutral[500],
      }}
      onPointerDown={onPointerDown}
      onKeyDown={onKeyDown}
      tabIndex={0}
      role="button"
      aria-label="Drag handle"
      data-drag-handle
      data-drag-axis={axis}
      data-drag-effect={dragEffect}
      {...props}
    >
      <GripIcon axis={axis} />
    </div>
  )
})

export default DraggableAffordance

/**
 * GlowRing Affordance
 *
 * Matte border ring with optional breathing animation.
 * Stillness with potential — slow, meditative presence.
 *
 * Uses anime.js for smooth, interruptible animations.
 */

import { useEffect, useRef } from 'react'
import { animate } from 'animejs'
import type { GlowableData } from '@/lib/capabilities/types'
import { COLORS, TIMING, EASING } from '@/lib/capabilities/tokens'

export interface GlowRingProps extends GlowableData {
  className?: string
}

export function GlowRing({ color = 'cyan', intensity = 'md', animated, className = '' }: GlowRingProps) {
  const ringRef = useRef<HTMLDivElement>(null)
  const animationRef = useRef<ReturnType<typeof animate> | null>(null)
  const colorValues = COLORS.accent[color] ?? COLORS.accent.cyan

  // Intensity maps to border thickness and subtle glow
  const intensityStyles = {
    sm: { borderWidth: 1, glowSpread: 4 },
    md: { borderWidth: 1, glowSpread: 8 },
    lg: { borderWidth: 2, glowSpread: 12 },
  }

  const { borderWidth, glowSpread } = intensityStyles[intensity]

  useEffect(() => {
    if (!animated || !ringRef.current) return

    // Choose timing based on animation type
    const timing = animated ? TIMING.activePulse : TIMING.breathing

    animationRef.current = animate(ringRef.current, {
      opacity: timing.opacity,
      scale: timing.scale,
      duration: timing.period,
      ease: EASING.anime.breathing,
      loop: true,
    })

    return () => {
      animationRef.current?.pause()
    }
  }, [animated])

return () => {
      animationRef.current?.pause()
    }
  }, [animated])

  return (
    <div
      ref={ringRef}
      className={`absolute inset-0 rounded pointer-events-none ${className}`}
      style={{
        border: `${borderWidth}px solid ${colorValues.border}`,
        // Subtle glow — not harsh, just a soft presence
        boxShadow: `0 0 ${glowSpread}px 0 ${colorValues.glow}`,
        opacity: animated ? 0.7 : 0.85,
        transformOrigin: 'center',
      }}
    />
  )
}

export default GlowRing

/**
 * SelectionRing
 *
 * Visual affordance for selected items.
 * Renders as an animated border ring around the target element.
 *
 * @pattern Capability affordance (like GlowRing, Badge)
 * @module
 */

import { useRef, useEffect } from 'react'
import { COLORS, TIMING, EASING } from '@/lib/capabilities/tokens'
import type { SelectableData, AccentColor } from '@/lib/capabilities/types'

// =============================================================================
// Props
// =============================================================================

export interface SelectionRingProps extends Partial<SelectableData> {
  className?: string
}

// =============================================================================
// Component
// =============================================================================

/**
 * Selection ring affordance.
 *
 * Renders an animated border ring that indicates selection state.
 * Supports multiple visual styles: ring, background, border.
 *
 * @example
 * ```tsx
 * <div className="relative">
 *   <Card>Content</Card>
 *   <SelectionRing selected={true} style="ring" color="cyan" />
 * </div>
 * ```
 */
export function SelectionRing({
  selected = false,
  style = 'ring',
  color = 'cyan',
  className = '',
}: SelectionRingProps) {
  const ringRef = useRef<HTMLDivElement>(null)

  // Get color tokens - access via COLORS.accent[color]
  const colorTokens = COLORS.accent[color as AccentColor] ?? COLORS.accent.cyan

  // Animate on selection change
  useEffect(() => {
    const ring = ringRef.current
    if (!ring) return

    if (selected) {
      // Animate in
      ring.style.opacity = '0'
      ring.style.transform = 'scale(1.02)'

if (selected) {
      // Animate in
      ring.style.opacity = '0'
      ring.style.transform = 'scale(1.02)'

      requestAnimationFrame(() => {
        ring.style.transition = `opacity ${TIMING.fast}ms ${EASING.css.out}, transform ${TIMING.fast}ms ${EASING.css.out}`
        ring.style.opacity = '1'
        ring.style.transform = 'scale(1)'
      })
    } else {
      // Animate out
      ring.style.transition = `opacity ${TIMING.fast}ms ${EASING.css.out}`
      ring.style.opacity = '0'
    }
  }, [selected])

  if (!selected) return null

  // Style variants
  const getStyleProps = (): React.CSSProperties => {
    switch (style) {
      case 'ring':
        return {
          border: `2px solid ${colorTokens.solid}`,
          boxShadow: `
            0 0 0 1px ${colorTokens.border},
            0 0 12px ${colorTokens.glow},
            inset 0 0 8px ${colorTokens.glow}
          `,
        }
      case 'background':
        return {
          backgroundColor: colorTokens.muted,
          border: `1px solid ${colorTokens.border}`,
        }
      case 'border':
        return {
          border: `2px solid ${colorTokens.border}`,
        }
      default:
        return {}
    }
  }

return (
    <div
      ref={ringRef}
      className={`absolute inset-0 pointer-events-none rounded ${className}`}
      style={{
        ...getStyleProps(),
        zIndex: 1,
      }}
      aria-hidden="true"
    >
      {/* Corner accents for TMNL aesthetic */}
      {style === 'ring' && (
        <>
          <Corner position="tl" color={colorTokens.solid} />
          <Corner position="tr" color={colorTokens.solid} />
          <Corner position="bl" color={colorTokens.solid} />
          <Corner position="br" color={colorTokens.solid} />
        </>
      )}
    </div>
  )
}

