/**
 * TMNL Fader Controller
 *
 * Vertical fader control for parameter adjustment.
 * Extracted from tmnl-ui.tsx for modular encapsulation.
 */

import { useRef, useCallback } from 'react';

// =============================================================================
// FADER
// =============================================================================

export interface FaderProps {
  value: number;
  min?: number;
  max?: number;
  step?: number;
  onChange: (value: number) => void;
  label?: string;
  height?: number;
}

export function Fader({
  value,
  min = 0,
  max = 100,
  step = 1,
  onChange,
  label,
  height = 60,
}: FaderProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const percent = ((value - min) / (max - min)) * 100;

  const handleInteraction = useCallback(
    (clientY: number) => {
      if (!trackRef.current) return;
      const rect = trackRef.current.getBoundingClientRect();
      const pct =
        1 - Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      const rawValue = min + pct * (max - min);
      const steppedValue = Math.round(rawValue / step) * step;
      onChange(Math.max(min, Math.min(max, steppedValue)));
    },
    [min, max, step, onChange]
  );

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      handleInteraction(e.clientY);

      const onMove = (ev: PointerEvent) => handleInteraction(ev.clientY);
      const onUp = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
      };
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    },
    [handleInteraction]
  );

return (
    <div className="flex flex-col items-center gap-0.5">
      {label && (
        <span
          className="font-mono uppercase text-neutral-500 tracking-wider"
          style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.6)' }}
        >
          {label}
        </span>
      )}
      <div
        className="relative w-5 cursor-pointer touch-none flex justify-center"
        style={{ height }}
        onPointerDown={handlePointerDown}
      >
        <div
          ref={trackRef}
          className="absolute top-0 bottom-0 w-1 bg-neutral-900 border border-neutral-800"
        >
          <div
            className="absolute left-0 right-0 bottom-0 bg-neutral-600"
            style={{ height: `${percent}%` }}
          />
        </div>
        <div
          className="absolute w-4 h-2.5 bg-neutral-800 border border-neutral-600"
          style={{ bottom: `${percent}%`, transform: 'translateY(50%)' }}
        >
          <div className="absolute inset-0.5 bg-neutral-700 flex items-center justify-center">
            <div className="w-2 h-0.5 bg-white/50" />
          </div>
        </div>
      </div>
      <span
        className="font-mono text-neutral-400 tabular-nums"
        style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.7)' }}
      >
        {value.toFixed(1)}
      </span>
    </div>
  );
}

/**
 * TMNL Knob Controller
 *
 * Rotary control for parameter adjustment.
 * Extracted from tmnl-ui.tsx for modular encapsulation.
 */

import { useRef, useCallback } from 'react';

// =============================================================================
// KNOB
// =============================================================================

export interface KnobProps {
  value: number;
  min?: number;
  max?: number;
  onChange: (value: number) => void;
  size?: number;
  label?: string;
}

export function Knob({
  value,
  min = 0,
  max = 100,
  onChange,
  size = 36,
  label,
}: KnobProps) {
  const isDragging = useRef(false);
  const startY = useRef(0);
  const startValue = useRef(value);
  const rotation = ((value - min) / (max - min)) * 270 - 135;

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      isDragging.current = true;
      startY.current = e.clientY;
      startValue.current = value;

      const onMove = (ev: PointerEvent) => {
        if (!isDragging.current) return;
        const delta = startY.current - ev.clientY;
        const range = max - min;
        const newValue = Math.max(
          min,
          Math.min(max, startValue.current + (delta / 100) * range)
        );
        onChange(newValue);
      };

      const onUp = () => {
        isDragging.current = false;
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
      };

      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    },
    [value, min, max, onChange]
  );

window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    },
    [value, min, max, onChange]
  );

  return (
    <div className="flex flex-col items-center gap-0.5">
      {label && (
        <span
          className="font-mono uppercase text-neutral-500 tracking-wider"
          style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.6)' }}
        >
          {label}
        </span>
      )}
      <div
        className="relative cursor-pointer touch-none"
        style={{ width: size, height: size }}
        onPointerDown={handlePointerDown}
      >
        {/* Outer ring */}
        <div className="absolute inset-0 rounded-full bg-neutral-950 border border-neutral-700">
          {/* Inner ring */}
          <div className="absolute inset-[3px] rounded-full bg-black border border-neutral-800">
            {/* Knob face */}
            <div
              className="absolute inset-[2px] rounded-full bg-neutral-900 border border-neutral-700 flex items-center justify-center"
              style={{ transform: `rotate(${rotation}deg)` }}
            >
              {/* Indicator line */}
              <div className="absolute top-1 w-0.5 h-1.5 bg-white rounded-full" />
              {/* Center dot */}
              <div className="w-1 h-1 rounded-full bg-neutral-600" />
            </div>
          </div>
        </div>
      </div>
      <span
        className="font-mono text-neutral-400 tabular-nums"
        style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.7)' }}
      >
        {typeof value === 'number'
          ? value < 10
            ? value.toFixed(2)
            : value.toFixed(1)
          : value}
      </span>
    </div>
  );
}

/**
 * TMNL Slider Controller
 *
 * Horizontal slider control for parameter adjustment.
 * Extracted from tmnl-ui.tsx for modular encapsulation.
 */

import { useRef, useCallback } from 'react';

// =============================================================================
// SLIDER
// =============================================================================

export interface SliderProps {
  value: number;
  min?: number;
  max?: number;
  step?: number;
  onChange: (value: number) => void;
  label?: string;
}

export function Slider({
  value,
  min = 0,
  max = 100,
  step = 1,
  onChange,
  label,
}: SliderProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const percent = ((value - min) / (max - min)) * 100;

  const handleInteraction = useCallback(
    (clientX: number) => {
      if (!trackRef.current) return;
      const rect = trackRef.current.getBoundingClientRect();
      const pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const rawValue = min + pct * (max - min);
      const steppedValue = Math.round(rawValue / step) * step;
      onChange(Math.max(min, Math.min(max, steppedValue)));
    },
    [min, max, step, onChange]
  );

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      handleInteraction(e.clientX);

      const onMove = (ev: PointerEvent) => handleInteraction(ev.clientX);
      const onUp = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
      };
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    },
    [handleInteraction]
  );

return (
    <div className="flex flex-col gap-0.5 w-full">
      {label && (
        <div className="flex justify-between">
          <span
            className="font-mono uppercase text-neutral-500 tracking-wider"
            style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.6)' }}
          >
            {label}
          </span>
          <span
            className="font-mono text-neutral-400 tabular-nums"
            style={{ fontSize: 'calc(var(--tmnl-text-xs, 12px) * 0.6)' }}
          >
            {value.toFixed(1)}
          </span>
        </div>
      )}
      <div
        className="relative h-4 cursor-pointer touch-none flex items-center"
        onPointerDown={handlePointerDown}
      >
        <div
          ref={trackRef}
          className="absolute left-0 right-0 h-1 bg-neutral-900 border border-neutral-800"
        >
          <div
            className="absolute top-0 left-0 bottom-0 bg-neutral-600"
            style={{ width: `${percent}%` }}
          />
        </div>
        <div
          className="absolute w-3 h-3 -translate-x-1/2 bg-neutral-800 border border-neutral-600"
          style={{ left: `${percent}%` }}
        >
          <div className="absolute inset-0.5 bg-neutral-700 flex items-center justify-center">
            <div className="w-0.5 h-1.5 bg-white/50" />
          </div>
        </div>
      </div>
    </div>
  );
}

