  power?: number
  intent?: 'cooperative' | 'hostile' | 'ambient' | 'unknown'
}

/** Extended row data with CEW actor properties */
export interface ActorRow extends DataGridRow {
  type: 'actor'
  affiliation?: 'blue' | 'red' | 'neutral' | 'unknown'
