/**
 * useStaggeredEntrance
 *
 * Hook for triggering staggered row entrance animation in DataGrid.
 * Works with AG-Grid's virtualization by animating only visible rows.
 */

import { useState, useCallback, useRef } from 'react'
import type { RowClassParams } from 'ag-grid-community'

// Import stagger CSS (side effect)
import './stagger.css'

// =============================================================================
// TYPES
// =============================================================================

export interface UseStaggeredEntranceOptions {
  /** Max rows to animate (prevents performance issues) */
  maxRows?: number
  /** Duration before auto-clearing stagger class (ms) */
  clearAfter?: number
}

export interface UseStaggeredEntranceResult {
  /** Add to grid container className */
  containerClassName: string
  /** Pass to AG-Grid getRowClass */
  getRowClass: (params: RowClassParams) => string
  /** Trigger the stagger animation */
  triggerStagger: () => void
  /** Whether stagger is currently active */
  isStaggering: boolean
}

// =============================================================================
// HOOK
// =============================================================================

export function useStaggeredEntrance(
  options: UseStaggeredEntranceOptions = {}
): UseStaggeredEntranceResult {
  const { maxRows = 20, clearAfter = 1500 } = options

  const [isStaggering, setIsStaggering] = useState(false)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  /**
   * AG-Grid row class callback
   * Assigns index-based class for CSS stagger delay
   */
  const getRowClass = useCallback(
    (params: RowClassParams): string => {
      if (!isStaggering) return ''

      // Use rowIndex modulo maxRows to keep within our CSS class range
      const visibleIndex = params.rowIndex % maxRows
      return `dg-row-${visibleIndex}`
    },
    [isStaggering, maxRows]
  )

/**
   * Trigger the stagger animation
   */
  const triggerStagger = useCallback(() => {
    // Clear any existing timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }

    setIsStaggering(true)

    // Auto-clear after animation completes
    timeoutRef.current = setTimeout(() => {
      setIsStaggering(false)
    }, clearAfter)
  }, [clearAfter])

  const containerClassName = `dg-stagger-container ${isStaggering ? 'dg-stagger-active' : ''}`

  return {
    containerClassName,
    getRowClass,
    triggerStagger,
    isStaggering,
  }
}

/**
 * useTypewriterReveal
 *
 * Anime.js-powered typewriter reveal for AG-Grid rows.
 * Rows reveal left-to-right like terminal text.
 */

import { useRef, useCallback } from 'react'
import { animate, stagger } from 'animejs'
import { FUI_TIMING } from '@/lib/fui'

// =============================================================================
// TYPES
// =============================================================================

export interface UseTypewriterRevealOptions {
  /** Stagger delay between rows (ms) */
  staggerDelay?: number
  /** Duration for each row reveal (ms) */
  duration?: number
  /** Container selector or ref */
  containerRef?: React.RefObject<HTMLElement>
}

export interface UseTypewriterRevealResult {
  /** Trigger the typewriter reveal animation */
  triggerReveal: () => void
  /** Container ref to attach */
  containerRef: React.RefObject<HTMLDivElement>
}

// =============================================================================
// HOOK
// =============================================================================

export function useTypewriterReveal(
  options: UseTypewriterRevealOptions = {}
): UseTypewriterRevealResult {
  const {
    staggerDelay = FUI_TIMING.rowStagger,
    duration = FUI_TIMING.rowReveal,
  } = options

  const internalRef = useRef<HTMLDivElement>(null)
  const containerRef = options.containerRef ?? internalRef

  const triggerReveal = useCallback(() => {
    const container = containerRef.current
    if (!container) return

    // Select all AG-Grid rows within the container
    const rows = container.querySelectorAll('.ag-row')
    if (rows.length === 0) return

    // Reset rows to hidden state
    rows.forEach((row) => {
      const el = row as HTMLElement
      el.style.clipPath = 'inset(0 100% 0 0)'
      el.style.opacity = '1'
    })

// Animate with typewriter reveal
    animate(rows, {
      clipPath: ['inset(0 100% 0 0)', 'inset(0 0% 0 0)'],
      duration,
      delay: stagger(staggerDelay, { from: 'first' }),
      easing: 'linear',
    })
  }, [containerRef, staggerDelay, duration])

  return {
    triggerReveal,
    containerRef: containerRef as React.RefObject<HTMLDivElement>,
  }
}

