// Export
// =============================================================================

export interface Docs3DSceneProps {
  cards?: readonly DocCard[]
  searchQuery?: string
  categoryFilter?: string | null
  onSelectCard?: (card: DocCard) => void
}

export interface Docs3DSceneProps {
