  color = '#f59e0b', // amber-500
  bins = 20,
}: D3HistogramProps) {
  const svgRef = useRef<SVGSVGElement>(null)
  const initialized = useRef(false)

  // Computed dimensions
  const innerWidth = width - MARGIN.left - MARGIN.right
  const innerHeight = height - MARGIN.top - MARGIN.bottom

  // Compute histogram bins
  const histogramData = useMemo(() => {
    if (data.length === 0) return []

    const [min, max] = d3.extent(data) as [number, number]
    const xScale = d3.scaleLinear().domain([min, max]).nice()

    const histogram = d3
      .bin<number, number>()
      .domain(xScale.domain() as [number, number])
      .thresholds(bins)

    return histogram(data)
  }, [data, bins])

// Bars
    const bars = g.select('.bars').selectAll<SVGRectElement, d3.Bin<number, number>>('rect').data(histogramData)

    // Enter
    bars
      .enter()
      .append('rect')
      .attr('x', (d) => xScale(d.x0 ?? 0) + 1)
      .attr('width', (d) => Math.max(0, xScale(d.x1 ?? 0) - xScale(d.x0 ?? 0) - 2))
      .attr('y', innerHeight)
      .attr('height', 0)
      .attr('fill', color)
      .attr('fill-opacity', 0.7)
      .merge(bars)
      .transition()
      .duration(200)
      .attr('x', (d) => xScale(d.x0 ?? 0) + 1)
      .attr('width', (d) => Math.max(0, xScale(d.x1 ?? 0) - xScale(d.x0 ?? 0) - 2))
      .attr('y', (d) => yScale(d.length))
      .attr('height', (d) => innerHeight - yScale(d.length))

    // Exit
    bars.exit().transition().duration(200).attr('height', 0).attr('y', innerHeight).remove()
  }, [histogramData, innerWidth, innerHeight, color])

  return (
    <svg
      ref={svgRef}
      width={width}
      height={height}
      className="bg-neutral-900/50 rounded"
    />
  )
}

export default D3Histogram

/**
 * D3 Line Chart
 *
 * Throughput-over-time visualization with real-time updates.
 *
 * Pattern:
 * - useEffect #1: Initialize SVG structure once (on dimensions change)
 * - useEffect #2: Update data (scales, line, axes)
 *
 * @module
 */

import { useRef, useEffect, useMemo } from 'react'
import * as d3 from 'd3'

// =============================================================================
// TYPES
// =============================================================================

export interface TimeseriesPoint {
  timestamp: number
  value: number
}

export interface D3LineChartProps {
  /** Data points to visualize */
  data: TimeseriesPoint[]
  /** Chart width */
  width?: number
  /** Chart height */
  height?: number
  /** Y-axis label */
  yLabel?: string
  /** Line color */
  color?: string
  /** Show area fill */
  showArea?: boolean
  /** Animation duration in ms */
  animationDuration?: number
}

// =============================================================================
// CONSTANTS
// =============================================================================

const MARGIN = { top: 20, right: 20, bottom: 30, left: 50 }

// =============================================================================
// D3 LINE CHART
// =============================================================================

/**
 * Real-time line chart using D3.
 *
 * Features:
 * - Smooth line interpolation
 * - Optional area fill
 * - Auto-scaling axes
 * - Animated transitions
 */
export function D3LineChart({
  data,
  width = 400,
  height = 200,
  yLabel = 'Value',
  color = '#22d3ee', // cyan-400
  showArea = true,
  animationDuration = 300,
}: D3LineChartProps) {
  const svgRef = useRef<SVGSVGElement>(null)
  const initialized = useRef(false)

  // Computed dimensions
  const innerWidth = width - MARGIN.left - MARGIN.right
  const innerHeight = height - MARGIN.top - MARGIN.bottom

// Computed dimensions
  const innerWidth = width - MARGIN.left - MARGIN.right
  const innerHeight = height - MARGIN.top - MARGIN.bottom

  // Memoize scales
  const { xScale, yScale } = useMemo(() => {
    const xExtent = d3.extent(data, (d) => d.timestamp) as [number, number]
    const yMax = d3.max(data, (d) => d.value) ?? 100

    return {
      xScale: d3
        .scaleTime()
        .domain(xExtent[0] ? xExtent : [Date.now() - 60000, Date.now()])
        .range([0, innerWidth]),
      yScale: d3
        .scaleLinear()
        .domain([0, yMax * 1.1])
        .range([innerHeight, 0]),
    }
  }, [data, innerWidth, innerHeight])

  // Initialize structure
  useEffect(() => {
    if (!svgRef.current) return

    const svg = d3.select(svgRef.current)

    // Clear and setup
    svg.selectAll('*').remove()

    // Create groups
    const g = svg
      .append('g')
      .attr('transform', `translate(${MARGIN.left},${MARGIN.top})`)

    // X axis
    g.append('g')
      .attr('class', 'x-axis')
      .attr('transform', `translate(0,${innerHeight})`)
      .call(
        d3
          .axisBottom(xScale)
          .ticks(5)
          .tickFormat((d) => d3.timeFormat('%H:%M:%S')(d as Date))
      )
      .selectAll('text')
      .style('fill', '#737373')
      .style('font-size', '10px')
      .style('font-family', 'monospace')

    g.selectAll('.x-axis path, .x-axis line').style('stroke', '#404040')

// Update line
    g.select('.line')
      .datum(data)
      .transition()
      .duration(animationDuration)
      .attr('d', line)

    // Update area
    if (showArea) {
      const area = d3
        .area<TimeseriesPoint>()
        .x((d) => newXScale(d.timestamp))
        .y0(innerHeight)
        .y1((d) => newYScale(d.value))
        .curve(d3.curveMonotoneX)

      g.select('.area')
        .datum(data)
        .transition()
        .duration(animationDuration)
        .attr('d', area)
    }
  }, [data, innerWidth, innerHeight, showArea, animationDuration])

  return (
    <svg
      ref={svgRef}
      width={width}
      height={height}
      className="bg-neutral-900/50 rounded"
    />
  )
}

