export type ArrowDirection =
  | 'right'
  | 'left'
  | 'up'
  | 'down'
  | 'diag-up-right'
  | 'diag-down-right'
  | 'diag-up-left'
  | 'diag-down-left'

export interface TransitionArrowProps {
