// =============================================================================

const ARROW_CHARS: Record<ArrowDirection, string> = {
  right: '→',
  left: '←',
  up: '↑',
  down: '↓',
  'diag-up-right': '↗',
  'diag-down-right': '↘',
  'diag-up-left': '↖',
  'diag-down-left': '↙',
}

const SIZE_FONTS = {
  sm: 'var(--tmnl-text-sm, 14px)',
  md: 'var(--tmnl-text-lg, 18px)',
  lg: 'var(--tmnl-text-xl, 20px)',
}

const LABEL_FONTS = {
  sm: 'var(--tmnl-text-xs, 12px)',
  md: 'var(--tmnl-text-xs, 12px)',
