/**
 * Splash Screen
 *
 * Orchestrates the boot sequence:
 * 1. Static burst (CRT power-on)
 * 2. Terminal init sequence (staccato log lines)
 * 3. Logo reveal (TMNL letter→word)
 * 4. Morph/dissolve to app
 *
 * Q-Branch Brutalist aesthetic:
 * - Warm gray, scanlines, mechanical timing
 * - Bond-style choreographed reveals
 * - Timeline guides focus
 *
 * Uses our Animatable system for smooth transitions.
 */

import { useState, useCallback, useEffect, useRef } from 'react'
import {
  animatable,
  useAnimatable,
  gsapDriver,
  Animatable,
} from '@/lib/animation'
import { CRTEffect } from './CRTEffect'
import { TerminalInit } from './TerminalInit'
import { LogoReveal } from './LogoReveal'
import { SPLASH_TIMING, SPLASH_COLORS, SPLASH_TYPOGRAPHY } from './tokens'

// Set GSAP driver for precision timing
Animatable.setDriver(gsapDriver)

type SplashPhase =
  | 'static'      // Initial static burst
  | 'boot'        // Terminal init sequence
  | 'logo'        // Logo reveal
  | 'transition'  // Morphing to app
  | 'complete'    // Done, app visible

interface SplashProps {
  /** Callback when splash completes */
  onComplete?: () => void
  /** Allow skip on click/key */
  skippable?: boolean
}

// Create animatable atoms outside component for stable references
const containerOpacityAtoms = animatable(1, {
  duration: SPLASH_TIMING.transition.morphDuration,
  ease: 'power2.inOut',
})

const scanlineOpacityAtoms = animatable(1, {
  duration: SPLASH_TIMING.crt.scanlineFade,
  ease: 'power2.out',
})

export function Splash({ onComplete, skippable = true }: SplashProps) {
  const [phase, setPhase] = useState<SplashPhase>('static')
  const onCompleteRef = useRef(onComplete)

export function Splash({ onComplete, skippable = true }: SplashProps) {
  const [phase, setPhase] = useState<SplashPhase>('static')
  const onCompleteRef = useRef(onComplete)

  // Keep callback ref updated
  useEffect(() => {
    onCompleteRef.current = onComplete
  }, [onComplete])

  // Use our animatable hooks for transitions
  const containerOpacity = useAnimatable(containerOpacityAtoms)
  const scanlineOpacity = useAnimatable(scanlineOpacityAtoms)

  // Phase transitions
  const handleStaticComplete = useCallback(() => {
    setPhase('boot')
  }, [])

  const handleBootComplete = useCallback(() => {
    // Small pause before logo
    setTimeout(() => {
      setPhase('logo')
    }, 200)
  }, [])

  const handleLogoComplete = useCallback(() => {
    // Begin transition
    setTimeout(() => {
      setPhase('transition')
    }, 300)
  }, [])

  // Transition phase: fade out using animatable
  useEffect(() => {
    if (phase !== 'transition') return

    // Fade out scanlines first
    scanlineOpacity.to(0)

    // Then fade out the whole splash after overlap delay
    const timer = setTimeout(() => {
      containerOpacity.to(0)
    }, SPLASH_TIMING.transition.fadeOverlap)

    return () => clearTimeout(timer)
  }, [phase, scanlineOpacity, containerOpacity])

  // Watch for container fade completion
  useEffect(() => {
    if (
      phase === 'transition' &&
      containerOpacity.state === 'completed' &&
      containerOpacity.value === 0
    ) {
      setPhase('complete')
      onCompleteRef.current?.()
    }
  }, [phase, containerOpacity.state, containerOpacity.value])

  // Skip handler
  const handleSkip = useCallback(() => {
    if (!skippable) return
    if (phase === 'complete' || phase === 'transition') return

    // Immediately transition
    setPhase('transition')
  }, [skippable, phase])

// Immediately transition
    setPhase('transition')
  }, [skippable, phase])

  // Keyboard skip
  useEffect(() => {
    if (!skippable) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter') {
        handleSkip()
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [skippable, handleSkip])

  // Don't render if complete
  if (phase === 'complete') {
    return null
  }

  return (
    <div
      className="fixed inset-0 flex items-center justify-center"
      style={{
        backgroundColor: SPLASH_COLORS.bg.primary,
        opacity: containerOpacity.value,
        zIndex: 10000,
        cursor: skippable ? 'pointer' : 'default',
      }}
      onClick={handleSkip}
    >
      {/* CRT Effects Layer */}
      <CRTEffect
        isActive={phase !== 'complete'}
        showStatic={phase === 'static'}
        showScanlines={scanlineOpacity.value > 0.01}
        onStaticComplete={handleStaticComplete}
      />

      {/* Content Container */}
      <div
        className="relative z-10 p-8 max-w-lg"
        style={{
          fontFamily: SPLASH_TYPOGRAPHY.fontFamily,
        }}
      >
        {/* Terminal Init - visible during boot phase */}
        {(phase === 'boot' || phase === 'logo' || phase === 'transition') && (
          <div
            className="mb-8"
            style={{
              opacity: phase === 'boot' ? 1 : 0.3,
              transition: 'opacity 300ms',
            }}
          >
            <TerminalInit
              isActive={phase === 'boot'}
              includeWit={true}
              onComplete={handleBootComplete}
            />
          </div>
        )}

{/* Logo Reveal - visible during logo phase */}
        {(phase === 'logo' || phase === 'transition') && (
          <div className="mt-8">
            <LogoReveal
              isActive={phase === 'logo'}
              onComplete={handleLogoComplete}
            />
          </div>
        )}
      </div>

      {/* Skip hint */}
      {skippable && phase !== 'transition' && (
        <div
          className="absolute bottom-8 left-1/2 -translate-x-1/2"
          style={{
            color: SPLASH_COLORS.text.dim,
            fontSize: SPLASH_TYPOGRAPHY.size.xs,
            fontFamily: SPLASH_TYPOGRAPHY.fontFamily,
          }}
        >
          press any key to skip
        </div>
      )}
    </div>
  )
}

export default Splash

/**
 * Terminal Init Sequence
 *
 * Displays the boot log with:
 * - Staccato rhythm (pause-burst-pause)
 * - Variable text entry (instant vs typed)
 * - Color shift on completion (using animatable)
 * - Mixed typography weights
 *
 * Uses our Animatable system for smooth color transitions.
 */

import { useEffect, useState, useRef, useMemo } from 'react'
import { gsap } from 'gsap'
import {
  INIT_LINES,
  WIT_LINE,
  SPLASH_TIMING,
  SPLASH_COLORS,
  SPLASH_TYPOGRAPHY,
  type InitLine,
} from './tokens'

interface TerminalInitProps {
  /** Whether to start the sequence */
  isActive: boolean
  /** Include the wit line */
  includeWit?: boolean
  /** Callback when all lines complete */
  onComplete?: () => void
}

interface LineState {
  line: InitLine
  isVisible: boolean
  isComplete: boolean
  typedText: string
  labelRef: React.RefObject<HTMLSpanElement>
}

export function TerminalInit({
  isActive,
  includeWit = true,
  onComplete,
}: TerminalInitProps) {
  // Create refs for each line's label (for GSAP color animation)
  const lineRefs = useRef<React.RefObject<HTMLSpanElement>[]>([])

  // Memoize the lines configuration
  const allLines = useMemo(() => {
    const lines = includeWit
      ? [...INIT_LINES.slice(0, 5), WIT_LINE, INIT_LINES[5]]
      : INIT_LINES

    // Ensure we have refs for each line
    if (lineRefs.current.length !== lines.length) {
      lineRefs.current = lines.map(() => ({ current: null }))
    }

    return lines
  }, [includeWit])

  const [lines, setLines] = useState<LineState[]>([])
  const [allComplete, setAllComplete] = useState(false)
  const timeoutsRef = useRef<NodeJS.Timeout[]>([])

const [lines, setLines] = useState<LineState[]>([])
  const [allComplete, setAllComplete] = useState(false)
  const timeoutsRef = useRef<NodeJS.Timeout[]>([])

  // Initialize line states
  useEffect(() => {
    setLines(
      allLines.map((line, index) => ({
        line,
        isVisible: false,
        isComplete: false,
        typedText: '',
        labelRef: lineRefs.current[index],
      }))
    )
  }, [allLines])

  // Run the sequence
  useEffect(() => {
    if (!isActive || lines.length === 0) return

    // Clear any existing timeouts
    timeoutsRef.current.forEach(clearTimeout)
    timeoutsRef.current = []

    let completedCount = 0
    const totalLines = lines.length

    lines.forEach((lineState, index) => {
      const { line, labelRef } = lineState

      // Schedule line appearance
      const showTimeout = setTimeout(() => {
        setLines((prev) =>
          prev.map((l, i) => (i === index ? { ...l, isVisible: true } : l))
        )

        if (line.mode === 'instant') {
          // Instant mode: show immediately, then mark complete with color shift
          setLines((prev) =>
            prev.map((l, i) =>
              i === index ? { ...l, typedText: line.status, isComplete: true } : l
            )
          )

          // Animate color shift using GSAP (our driver uses GSAP)
          if (labelRef.current) {
            gsap.to(labelRef.current, {
              color: SPLASH_COLORS.text.success,
              duration: SPLASH_TIMING.boot.colorShiftDuration / 1000,
              ease: 'power2.out',
            })
          }

completedCount++
          if (completedCount === totalLines) {
            setAllComplete(true)
            onComplete?.()
          }
        } else {
          // Typed mode: character by character
          const chars = line.status.split('')
          chars.forEach((char, charIndex) => {
            const charTimeout = setTimeout(() => {
              setLines((prev) =>
                prev.map((l, i) =>
                  i === index
                    ? { ...l, typedText: line.status.slice(0, charIndex + 1) }
                    : l
                )
              )

              // Mark complete on last char
              if (charIndex === chars.length - 1) {
                setTimeout(() => {
                  setLines((prev) =>
                    prev.map((l, i) =>
                      i === index ? { ...l, isComplete: true } : l
                    )
                  )

                  // Animate color shift
                  if (labelRef.current) {
                    gsap.to(labelRef.current, {
                      color: SPLASH_COLORS.text.success,
                      duration: SPLASH_TIMING.boot.colorShiftDuration / 1000,
                      ease: 'power2.out',
                    })
                  }

                  completedCount++
                  if (completedCount === totalLines) {
                    setAllComplete(true)
                    onComplete?.()
                  }
                }, 50)
              }
            }, charIndex * SPLASH_TIMING.boot.lineTypeDuration)

            timeoutsRef.current.push(charTimeout as unknown as NodeJS.Timeout)
          })
        }
      }, line.delay)

      timeoutsRef.current.push(showTimeout as unknown as NodeJS.Timeout)
    })

    return () => {
      timeoutsRef.current.forEach(clearTimeout)
    }
  }, [isActive, lines.length, onComplete])

  if (!isActive && lines.every((l) => !l.isVisible)) {
    return null
  }

return () => {
      timeoutsRef.current.forEach(clearTimeout)
    }
  }, [isActive, lines.length, onComplete])

  if (!isActive && lines.every((l) => !l.isVisible)) {
    return null
  }

  return (
    <div
      className="font-mono text-left space-y-1"
      style={{
        fontFamily: SPLASH_TYPOGRAPHY.fontFamily,
      }}
    >
      {lines.map((lineState, index) => {
        if (!lineState.isVisible) return null

        const { line, isComplete, typedText } = lineState
        const isWit = line.isWit

        return (
          <div
            key={`${line.label}-${index}`}
            className="flex items-center gap-2 transition-opacity duration-200"
            style={{
              opacity: lineState.isVisible ? 1 : 0,
            }}
          >
            {/* Timestamp - dim */}
            <span
              style={{
                color: SPLASH_COLORS.text.dim,
                fontSize: SPLASH_TYPOGRAPHY.size.xs,
                fontWeight: SPLASH_TYPOGRAPHY.weight.light,
              }}
            >
              [{String(index).padStart(2, '0')}]
            </span>

            {/* Label - heavier weight, animated color */}
            <span
              ref={(el) => {
                if (lineRefs.current[index]) {
                  (lineRefs.current[index] as { current: HTMLSpanElement | null }).current = el
                }
              }}
              style={{
                color: SPLASH_COLORS.text.primary, // Initial color, GSAP animates to success
                fontSize: SPLASH_TYPOGRAPHY.size.sm,
                fontWeight: SPLASH_TYPOGRAPHY.weight.medium,
                minWidth: '4rem',
              }}
            >
              [{line.label}]
            </span>

{/* Status text - light weight */}
            <span
              style={{
                color: isWit
                  ? SPLASH_COLORS.text.success
                  : SPLASH_COLORS.text.secondary,
                fontSize: SPLASH_TYPOGRAPHY.size.sm,
                fontWeight: SPLASH_TYPOGRAPHY.weight.light,
                fontStyle: isWit ? 'italic' : 'normal',
              }}
            >
              {typedText}
              {!isComplete && line.mode === 'typed' && (
                <span
                  className="inline-block w-2 h-4 ml-0.5 animate-pulse"
                  style={{ backgroundColor: SPLASH_COLORS.text.primary }}
                />
              )}
            </span>
          </div>
        )
      })}
    </div>
  )
}

export default TerminalInit

