})
export type Session = typeof Session.Type

// ─────────────────────────────────────────────────────────────
// Error Reasons
// ─────────────────────────────────────────────────────────────

/**
 * Authentication failure reasons
 */
export const AuthFailureReason = Schema.Literal(
  "invalid_credentials",
  "account_locked",
  "account_disabled",
  "session_expired",
  "mfa_required",
  "biometric_failed",
  "facial_not_recognized",
  "gesture_mismatch",
  "rate_limited",
  "network_error",
  "unknown"
)
