// --- TACTICAL CONTROLS ---

function TacticalKnob({
  value,
  min = 0,
  max = 100,
  onChange,
  size = 40,
  label,
}: { value: number; min?: number; max?: number; onChange: (v: number) => void; size?: number; label?: string }) {
  const isDragging = useRef(false)
  const startY = useRef(0)
  const startValue = useRef(value)
  const rotation = ((value - min) / (max - min)) * 270 - 135

const handleStart = useCallback(
    (clientY: number) => {
      isDragging.current = true
      startY.current = clientY
      startValue.current = value
    },
    [value],
  )
  const handleMove = useCallback(
    (clientY: number) => {
      if (!isDragging.current) return
      const delta = startY.current - clientY
      const newValue = Math.max(min, Math.min(max, startValue.current + (delta / 100) * (max - min)))
      onChange(newValue)
    },
    [min, max, onChange],
  )
  const handleEnd = useCallback(() => {
    isDragging.current = false
  }, [])

return (
    <div className="flex flex-col items-center gap-1">
      {label && <span className="font-mono uppercase text-neutral-500 tracking-widest" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{label}</span>}
      <div
        className="relative cursor-pointer touch-none"
        style={{ width: size + 16, height: size + 16 }}
        onPointerDown={(e) => {
          e.preventDefault()
          handleStart(e.clientY)
          const onMove = (ev: PointerEvent) => handleMove(ev.clientY)
          const onUp = () => {
            handleEnd()
            window.removeEventListener("pointermove", onMove)
            window.removeEventListener("pointerup", onUp)
          }
          window.addEventListener("pointermove", onMove)
          window.addEventListener("pointerup", onUp)
        }}
      >
        <div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-neutral-950 border border-neutral-800"
          style={{ width: size, height: size }}
        >
          <div className="absolute top-1 left-1 right-1 bottom-1 rounded-full bg-black border border-neutral-700">
            <div
              className="absolute top-1 left-1 right-1 bottom-1 rounded-full bg-neutral-900 border border-neutral-600 flex items-center justify-center transition-transform"
              style={{ transform: `rotate(${rotation}deg)` }}
            >
              <div className="absolute top-1.5 w-0.5 h-2 bg-white rounded-full" />
              <div className="w-1.5 h-1.5 rounded-full bg-neutral-700" />
            </div>
          </div>
        </div>
      </div>
      <span className="font-mono text-neutral-400 tabular-nums" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{Math.round(value)}</span>
    </div>
  )
}

function TacticalSlider({
  value,
  min = 0,
  max = 100,
  step = 1,
  onChange,
  label,
}: { value: number; min?: number; max?: number; step?: number; onChange: (v: number) => void; label?: string }) {
  const trackRef = useRef<HTMLDivElement>(null)
  const handleInteraction = useCallback(
    (clientX: number) => {
      if (!trackRef.current) return
      const rect = trackRef.current.getBoundingClientRect()
      const percent = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width))
      const rawValue = min + percent * (max - min)
      onChange(Math.max(min, Math.min(max, Math.round(rawValue / step) * step)))
    },
    [min, max, step, onChange],
  )
  const percent = ((value - min) / (max - min)) * 100

return (
    <div className="flex flex-col gap-1 w-full">
      {label && (
        <div className="flex justify-between">
          <span className="font-mono uppercase text-neutral-500 tracking-widest" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{label}</span>
          <span className="font-mono text-neutral-400 tabular-nums" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{value.toFixed(1)}</span>
        </div>
      )}
      <div
        className="relative h-6 cursor-pointer touch-none flex items-center"
        onPointerDown={(e) => {
          e.preventDefault()
          handleInteraction(e.clientX)
          const onMove = (ev: PointerEvent) => handleInteraction(ev.clientX)
          const onUp = () => {
            window.removeEventListener("pointermove", onMove)
            window.removeEventListener("pointerup", onUp)
          }
          window.addEventListener("pointermove", onMove)
          window.addEventListener("pointerup", onUp)
        }}
      >
        <div ref={trackRef} className="absolute left-0 right-0 h-1 bg-neutral-900 border border-neutral-800">
          <div
            className="absolute top-0 left-0 bottom-0 bg-neutral-600 border-r border-neutral-500"
            style={{ width: `${percent}%` }}
          />
        </div>
        <div
          className="absolute w-4 h-4 -translate-x-1/2 bg-neutral-950 border border-neutral-700"
          style={{ left: `${percent}%` }}
        >
          <div className="absolute inset-0.5 bg-neutral-800 border border-neutral-600">
            <div className="absolute inset-0.5 bg-neutral-700 flex items-center justify-center">
              <div className="w-0.5 h-2 bg-white/40" />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function TacticalFader({
  value,
  min = 0,
  max = 100,
  step = 1,
  onChange,
  label,
  height = 80,
}: {
  value: number
  min?: number
  max?: number
  step?: number
  onChange: (v: number) => void
  label?: string
  height?: number
}) {
  const trackRef = useRef<HTMLDivElement>(null)
  const handleInteraction = useCallback(
    (clientY: number) => {
      if (!trackRef.current) return
      const rect = trackRef.current.getBoundingClientRect()
      const percent = 1 - Math.max(0, Math.min(1, (clientY - rect.top) / rect.height))
      const rawValue = min + percent * (max - min)
      onChange(Math.max(min, Math.min(max, Math.round(rawValue / step) * step)))
    },
    [min, max, step, onChange],
  )
  const percent = ((value - min) / (max - min)) * 100

return (
    <div className="flex flex-col items-center gap-1">
      {label && <span className="font-mono uppercase text-neutral-500 tracking-widest" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{label}</span>}
      <div
        className="relative w-6 cursor-pointer touch-none flex justify-center"
        style={{ height }}
        onPointerDown={(e) => {
          e.preventDefault()
          handleInteraction(e.clientY)
          const onMove = (ev: PointerEvent) => handleInteraction(ev.clientY)
          const onUp = () => {
            window.removeEventListener("pointermove", onMove)
            window.removeEventListener("pointerup", onUp)
          }
          window.addEventListener("pointermove", onMove)
          window.addEventListener("pointerup", onUp)
        }}
      >
        <div ref={trackRef} className="absolute top-0 bottom-0 w-1 bg-neutral-900 border border-neutral-800">
          <div
            className="absolute left-0 right-0 bottom-0 bg-neutral-600 border-t border-neutral-500"
            style={{ height: `${percent}%` }}
          />
        </div>
        <div
          className="absolute w-5 h-3 bg-neutral-950 border border-neutral-700"
          style={{ bottom: `${percent}%`, transform: `translateY(50%)` }}
        >
          <div className="absolute inset-0.5 bg-neutral-800 border border-neutral-600 flex items-center justify-center">
            <div className="w-3 h-0.5 bg-white/40" />
          </div>
        </div>
      </div>
      <span className="font-mono text-neutral-400 tabular-nums" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>{value.toFixed(1)}</span>
    </div>
  )
}

