interface DocumentPickerProps {
  isOpen: boolean;
  currentDocId: string;
  onSelectDoc: (docId: string, petName: string) => void;
  onClose: () => void;
  onNewDoc: () => void;
}

function DocumentPicker({
  isOpen,
  currentDocId,
  onSelectDoc,
  onClose,
  onNewDoc,
}: DocumentPickerProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [manualDocId, setManualDocId] = useState('');

// @ts-expect-error — version mismatch in monorepo, works at runtime
  const recentDocs = useAtomValue(recentDocsAtom) as readonly RecentDoc[];
  const removeFromRecentDocs = useAtomSet(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    collaborationOps.removeFromRecentDocs as any
  );
  const loadRecentDocs = useAtomSet(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    collaborationOps.loadRecentDocs as any
  );

  // Load recent docs on mount
  useEffect(() => {
    if (isOpen) {
      loadRecentDocs(undefined);
    }
  }, [isOpen, loadRecentDocs]);

  // Filter docs by search
  const filteredDocs = useMemo(() => {
    if (!searchQuery.trim()) return recentDocs;
    const q = searchQuery.toLowerCase();
    return recentDocs.filter(
      (doc) =>
        doc.petName.toLowerCase().includes(q) ||
        doc.docId.toLowerCase().includes(q)
    );
  }, [recentDocs, searchQuery]);

  const handleDelete = (docId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    removeFromRecentDocs({ docId });
  };

  const handleConnectManual = () => {
    if (manualDocId.trim()) {
      const petName = generatePetName();
      onSelectDoc(manualDocId.trim(), petName);
      setManualDocId('');
    }
  };

  const formatTime = (timestamp: number) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ago`;
    if (hours > 0) return `${hours}h ago`;
    return 'Just now';
  };

  if (!isOpen) return null;

  return (
    <div
      style={{
        position: 'fixed',

color: colors.text.primary,
                fontFamily: typography.fontFamily,
                fontSize: typography.sizes.lg,
                fontWeight: typography.weights.semibold,
              }}
            >
              Documents
            </h2>
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'none',
              border: 'none',
              color: colors.text.tertiary,
              cursor: 'pointer',
              padding: '4px',
              borderRadius: '4px',
              display: 'flex',
            }}
          >
            <IconX size={18} />
          </button>
        </div>

        {/* Search & Actions */}
        <div
          style={{
            padding: '12px 20px',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px',
            borderBottom: `1px solid ${colors.border.subtle}`,
          }}
        >
          {/* Search Input */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
              padding: '10px 12px',
              background: colors.bg.base,
              borderRadius: '8px',
              border: `1px solid ${colors.border.subtle}`,
            }}
          >
            <IconSearch size={16} />
            <input
              type="text"
              placeholder="Search documents..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                flex: 1,
                background: 'none',
                border: 'none',
                outline: 'none',
                color: colors.text.primary,
                fontFamily: typography.fontFamily,
                fontSize: typography.sizes.sm,
              }}
            />
          </div>

{/* Connect by ID */}
          <div
            style={{
              display: 'flex',
              gap: '8px',
            }}
          >
            <input
              type="text"
              placeholder="Enter document ID..."
              value={manualDocId}
              onChange={(e) => setManualDocId(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleConnectManual()}
              style={{
                flex: 1,
                padding: '10px 12px',
                background: colors.bg.base,
                border: `1px solid ${colors.border.subtle}`,
                borderRadius: '8px',
                color: colors.text.primary,
                fontFamily: typography.fontMono,
                fontSize: typography.sizes.xs,
                outline: 'none',
              }}
            />
            <Button
              onClick={handleConnectManual}
              disabled={!manualDocId.trim()}
              size="md"
            >
              Connect
            </Button>
          </div>

          {/* New Document */}
          <Button
            onClick={onNewDoc}
            variant="primary"
            icon={<IconPlus size={14} />}
          >
            New Document
          </Button>
        </div>

        {/* Document List */}
        <div
          style={{
            flex: 1,
            overflow: 'auto',
            padding: '8px',
          }}
        >
          {filteredDocs.length === 0 ? (
            <div
              style={{
                textAlign: 'center',
                padding: '40px 20px',
                color: colors.text.tertiary,
                fontFamily: typography.fontFamily,
                fontSize: typography.sizes.sm,
              }}
            >
              {searchQuery
                ?

'No documents match your search'
                : 'No recent documents'}
            </div>
          ) : (
            <div
              style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}
            >
              {filteredDocs.map((doc) => {
                const isActive = doc.docId === currentDocId;
                return (
                  <div
                    key={doc.docId}
                    onClick={() => onSelectDoc(doc.docId, doc.petName)}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '12px',
                      padding: '12px 14px',
                      background: isActive
                        ? colors.accent.cyanMuted
                        : 'transparent',
                      border: `1px solid ${
                        isActive ? colors.accent.cyan : 'transparent'
                      }`,
                      borderRadius: '8px',
                      cursor: 'pointer',
                      transition: 'all 0.1s ease',
                    }}
                  >
                    <div
                      style={{
                        color: isActive
                          ? colors.accent.cyan
                          : colors.text.tertiary,
                      }}
                    >
                      <IconDocument size={18} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div
                        style={{
                          color: isActive
                            ?

colors.accent.cyan
                            : colors.text.primary,
                          fontFamily: typography.fontFamily,
                          fontSize: typography.sizes.sm,
                          fontWeight: typography.weights.medium,
                          marginBottom: '2px',
                        }}
                      >
                        {doc.petName}
                      </div>
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '8px',
                        }}
                      >
                        <span
                          style={{
                            color: colors.text.muted,
                            fontFamily: typography.fontMono,
                            fontSize: typography.sizes.xs,
                          }}
                        >
                          {doc.docId.slice(-12)}
                        </span>
                        <span
                          style={{
                            color: colors.text.muted,
                            fontSize: typography.sizes.xs,
                          }}
                        >
                          ·
                        </span>
                        <span
                          style={{
                            color: colors.text.muted,
                            fontFamily: typography.fontFamily,
                            fontSize: typography.sizes.xs,
                          }}
                        >
                          {formatTime(doc.lastAccessed)}
                        </span>
                      </div>
                    </div>
                    <button
                      onClick={(e) => handleDelete(doc.docId, e)}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: colors.text.muted,
                        cursor: 'pointer',
                        padding: '6px',
                        borderRadius: '4px',
                        display: 'flex',
                        opacity: 0.6,
                        transition: 'opacity 0.1s',
                      }}
                      title="Remove from recent"
                    >
                      <IconTrash size={14} />
                    </button>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

