  const [expanded, setExpanded] = useState(false)
  const hasData = entry.data !== undefined

function LogEntryRow({ entry }: { entry: TestbedLogEntry }) {
  const config = LEVEL_CONFIG[entry.level]
  const [expanded, setExpanded] = useState(false)
  const hasData = entry.data !== undefined

  return (
    <motion.div
      initial={{ opacity: 0, x: 10 }}
