  { id: "1", tagId: "FIC-101", priority: "high", message: "Flow rate high", timestamp: Date.now() - 5000 },
  { id: "2", tagId: "TIC-201", priority: "medium", message: "Temperature deviation", timestamp: Date.now() - 10000 },
