/**
 * Effect-Based Testbed Logging Atoms
 *
 * Schema-backed logging system for testbed components.
 * Uses Effect.Schema for type-safe log entries and effect-atom for React integration.
 *
 * Pattern: withEventLogCollector approach, adapted for testbed use.
 *
 * @module testbed/atoms/testbed-log
 */

import { Schema } from "effect"
import { Atom } from "@effect-atom/atom"
import { overlayRegistry } from "@/lib/overlays/atoms"

// =============================================================================
// LOG LEVEL SCHEMA
// =============================================================================

/**
 * Log level using Schema.Literal for runtime + type safety.
 */
export const LogLevel = Schema.Literal("info", "warn", "error", "success", "debug")
export type LogLevel = typeof LogLevel.Type

// =============================================================================
// LOG ENTRY SCHEMA (TaggedClass)
// =============================================================================

/**
 * Single log entry with source, level, message, and optional data.
 * Uses Schema.TaggedClass for discriminated union support + methods.
 */
export class TestbedLogEntry extends Schema.TaggedClass<TestbedLogEntry>()(
  "TestbedLogEntry",
  {
    /** Unique ID for React keys */
    id: Schema.String,
    /** Log level */
    level: LogLevel,
    /** Component/test source */
    source: Schema.String,
    /** Human-readable message */
    message: Schema.String,
    /** Timestamp (ms since epoch) */
    timestamp: Schema.Number,
    /** Optional structured data payload */
    data: Schema.optional(Schema.Unknown),
  }
) {
  /**
   * Format timestamp for display.
   */
  get formattedTime(): string {
    return new Date(this.timestamp).toISOString().slice(11, 23)
  }

  /**
   * Format for console output.
   */
  get consoleFormat(): string {
    return `[${this.formattedTime}] [${this.level.toUpperCase()}] ${this.source}: ${this.message}`
  }
}

// =============================================================================
// STATE ATOMS
// =============================================================================

// =============================================================================
// STATE ATOMS
// =============================================================================

/**
 * Log entries atom — the primary state.
 * Module-level for stable reference.
 */
export const logsAtom = Atom.make<readonly TestbedLogEntry[]>([])

/**
 * Maximum log entries to retain (prevent memory bloat).
 */
const MAX_LOGS = 500

/**
 * Log count derived atom.
 */
export const logCountAtom = Atom.make((get) => get(logsAtom).length)

/**
 * Filtered logs by level.
 */
export const filteredLogsAtom = Atom.family((level: LogLevel | "all") =>
  Atom.make((get) => {
    const logs = get(logsAtom)
    if (level === "all") return logs
    return logs.filter((log) => log.level === level)
  })
)

/**
 * Logs grouped by source.
 */
export const logsBySourceAtom = Atom.make((get) => {
  const logs = get(logsAtom)
  const grouped = new Map<string, TestbedLogEntry[]>()

  for (const log of logs) {
    const existing = grouped.get(log.source) ?? []
    grouped.set(log.source, [...existing, log])
  }

  return grouped
})

// =============================================================================
// OPERATIONS
// =============================================================================

let logIdCounter = 0

/**
 * Generate unique log ID.
 */
const generateLogId = (): string => {
  logIdCounter++
  return `log-${Date.now()}-${logIdCounter}`
}

/**
 * Add a log entry.
 * Uses Atom.set directly (Atom-as-State pattern).
 */
export const appendLog = (
  level: LogLevel,
  source: string,
  message: string,
  data?: unknown
): TestbedLogEntry => {
  const entry = new TestbedLogEntry({
    id: generateLogId(),
    level,
    source,
    message,
    timestamp: Date.now(),
    data,
  })

overlayRegistry.update(logsAtom, (prev) => {
    const updated = [...prev, entry]
    // Trim to max logs
    if (updated.length > MAX_LOGS) {
      return updated.slice(-MAX_LOGS)
    }
    return updated
  })

  return entry
}

/**
 * Clear all logs.
 */
export const clearLogs = (): void => {
  overlayRegistry.set(logsAtom, [])
}

/**
 * Clear logs for a specific source.
 */
export const clearLogsForSource = (source: string): void => {
  overlayRegistry.update(logsAtom, (prev) => prev.filter((log) => log.source !== source))
}

// =============================================================================
// LOGGER FACTORY
// =============================================================================

/**
 * Logger interface for source-scoped logging.
 */
export interface TestbedLogger {
  info: (message: string, data?: unknown) => TestbedLogEntry
  warn: (message: string, data?: unknown) => TestbedLogEntry
  error: (message: string, data?: unknown) => TestbedLogEntry
  success: (message: string, data?: unknown) => TestbedLogEntry
  debug: (message: string, data?: unknown) => TestbedLogEntry
  clear: () => void
}

/**
 * Create a source-scoped logger.
 * Returns stable object for memoization.
 */
export const createLogger = (source: string): TestbedLogger => ({
  info: (message, data) => appendLog("info", source, message, data),
  warn: (message, data) => appendLog("warn", source, message, data),
  error: (message, data) => appendLog("error", source, message, data),
  success: (message, data) => appendLog("success", source, message, data),
  debug: (message, data) => appendLog("debug", source, message, data),
  clear: () => clearLogsForSource(source),
})

// =============================================================================
// REACT HOOK
// =============================================================================

// =============================================================================
// REACT HOOK
// =============================================================================

import { useMemo } from "react"
import { useAtomValue } from "@effect-atom/atom-react"

/**
 * Hook for source-scoped logging.
 * Returns a stable logger instance.
 */
export function useTestbedLogger(source: string): TestbedLogger {
  return useMemo(() => createLogger(source), [source])
}

/**
 * Hook for reading all logs.
 */
export function useTestbedLogs(): readonly TestbedLogEntry[] {
  return useAtomValue(logsAtom)
}

/**
 * Hook for log count.
 */
export function useTestbedLogCount(): number {
  return useAtomValue(logCountAtom)
}

/**
 * AVA Graph Visualization
 *
 * D3 force-directed graph showing view dependencies,
 * channel relationships, and data flow.
 *
 * @pattern D3 + React integration
 * @module
 */

import { useEffect, useRef, useMemo } from 'react'
import * as d3 from 'd3'

import { useStxData } from '@/lib/stx'
import { getAvaStx, type ViewSummary, type ViewArtifact } from '@/lib/ava/atoms/ava-stx'

// =============================================================================
// Types
// =============================================================================

interface GraphNode {
  id: string
  label: string
  type: 'view' | 'channel' | 'source'
  x?: number
  y?: number
  fx?: number | null
  fy?: number | null
}

interface GraphLink {
  source: string | GraphNode
  target: string | GraphNode
  type: 'binding' | 'dependency' | 'subscription'
}

// =============================================================================
// Helpers
// =============================================================================

const buildGraphData = (
  views: readonly ViewSummary[],
  artifact: ViewArtifact | null
): { nodes: GraphNode[]; links: GraphLink[] } => {
  const nodes: GraphNode[] = []
  const links: GraphLink[] = []
  const nodeIds = new Set<string>()

  // Add view nodes
  views.forEach(view => {
    if (!nodeIds.has(view.id)) {
      nodes.push({
        id: view.id,
        label: view.name,
        type: 'view',
      })
      nodeIds.add(view.id)
    }
  })

  // If we have an artifact, add channel bindings
  if (artifact) {
    artifact.channel_bindings.forEach(binding => {
      // Add channel node
      if (!nodeIds.has(binding.channel_id)) {
        nodes.push({
          id: binding.channel_id,
          label: binding.channel_id,
          type: 'channel',
        })
        nodeIds.add(binding.channel_id)
      }

// Add source node if present
      if (binding.source_id && !nodeIds.has(binding.source_id)) {
        nodes.push({
          id: binding.source_id,
          label: binding.source_id,
          type: 'source',
        })
        nodeIds.add(binding.source_id)
      }

      // Link view to channel
      links.push({
        source: artifact.view_id,
        target: binding.channel_id,
        type: 'binding',
      })

      // Link channel to source if present
      if (binding.source_id) {
        links.push({
          source: binding.channel_id,
          target: binding.source_id,
          type: 'dependency',
        })
      }
    })
  }

  return { nodes, links }
}

const getNodeColor = (type: GraphNode['type']): string => {
  switch (type) {
    case 'view':
      return '#22d3ee' // cyan
    case 'channel':
      return '#a855f7' // purple
    case 'source':
      return '#22c55e' // green
    default:
      return '#a3a3a3'
  }
}

const getLinkColor = (type: GraphLink['type']): string => {
  switch (type) {
    case 'binding':
      return '#525252'
    case 'dependency':
      return '#713f12'
    case 'subscription':
      return '#0e7490'
    default:
      return '#404040'
  }
}

// =============================================================================
// Component
// =============================================================================

export function GraphVisualization() {
  const svgRef = useRef<SVGSVGElement>(null)
  const ava = getAvaStx()

  // Subscribe to state
  const views = useStxData(ava, d => d.views.get())
  const artifact = useStxData(ava, d => d.artifact.get())

  // Build graph data
  const graphData = useMemo(
    () => buildGraphData(views, artifact),
    [views, artifact]
  )

// Build graph data
  const graphData = useMemo(
    () => buildGraphData(views, artifact),
    [views, artifact]
  )

  // D3 force simulation
  useEffect(() => {
    if (!svgRef.current || graphData.nodes.length === 0) return

    const svg = d3.select(svgRef.current)
    const width = svgRef.current.clientWidth || 400
    const height = svgRef.current.clientHeight || 300

    // Clear previous
    svg.selectAll('*').remove()

    // Create container group
    const g = svg.append('g')

    // Add zoom behavior
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on('zoom', (event) => {
        g.attr('transform', event.transform)
      })

    svg.call(zoom)

    // Create force simulation
    const simulation = d3.forceSimulation<GraphNode>(graphData.nodes as GraphNode[])
      .force('link', d3.forceLink<GraphNode, GraphLink>(graphData.links)
        .id(d => d.id)
        .distance(80))
      .force('charge', d3.forceManyBody().strength(-200))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(30))

    // Create links
    const link = g.append('g')
      .attr('class', 'links')
      .selectAll('line')
      .data(graphData.links)
      .join('line')
      .attr('stroke', d => getLinkColor(d.type))
      .attr('stroke-width', 1.5)
      .attr('stroke-opacity', 0.6)

// Create nodes
    const node = g.append('g')
      .attr('class', 'nodes')
      .selectAll('g')
      .data(graphData.nodes)
      .join('g')
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart()
          d.fx = d.x
          d.fy = d.y
        })
        .on('drag', (event, d) => {
          d.fx = event.x
          d.fy = event.y
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0)
          d.fx = null
          d.fy = null
        }) as any)

    // Node circles
    node.append('circle')
      .attr('r', d => d.type === 'view' ? 20 : 12)
      .attr('fill', d => getNodeColor(d.type))
      .attr('stroke', '#0a0a0a')
      .attr('stroke-width', 2)
      .attr('opacity', 0.9)

    // Node labels
    node.append('text')
      .attr('dy', d => d.type === 'view' ? 35 : 25)
      .attr('text-anchor', 'middle')
      .attr('fill', '#a3a3a3')
      .attr('font-size', '10px')
      .attr('font-family', 'monospace')
      .text(d => d.label.length > 12 ? d.label.slice(0, 12) + '...' : d.label)

// Node type icons
    node.append('text')
      .attr('dy', 4)
      .attr('text-anchor', 'middle')
      .attr('fill', '#0a0a0a')
      .attr('font-size', d => d.type === 'view' ? '12px' : '8px')
      .attr('font-weight', 'bold')
      .text(d => d.type === 'view' ? 'V' : d.type === 'channel' ? 'C' : 'S')

    // Update positions on tick
    simulation.on('tick', () => {
      link
        .attr('x1', d => (d.source as GraphNode).x ?? 0)
        .attr('y1', d => (d.source as GraphNode).y ?? 0)
        .attr('x2', d => (d.target as GraphNode).x ?? 0)
        .attr('y2', d => (d.target as GraphNode).y ?? 0)

      node.attr('transform', d => `translate(${d.x ?? 0},${d.y ?? 0})`)
    })

    // Cleanup
    return () => {
      simulation.stop()
    }
  }, [graphData])

{/* Graph */}
      <div className="flex-1 relative">
        {graphData.nodes.length === 0 ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <span
              className="text-neutral-600 font-mono"
              style={{ fontSize: 'var(--tmnl-text-sm, 14px)' }}
            >
              No views registered. Click "Register" to add a test view.
            </span>
          </div>
        ) : (
          <svg
            ref={svgRef}
            className="w-full h-full"
            style={{ background: 'transparent' }}
          />
        )}
      </div>

      {/* Footer */}
      <div className="px-3 py-1 border-t border-neutral-800 bg-neutral-900/30">
        <span
          className="font-mono text-neutral-600"
          style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
        >
          {graphData.nodes.length} nodes • {graphData.links.length} links • Drag to reposition, scroll to zoom
        </span>
      </div>
    </div>
  )
}

/**
 * AVA REPL Console
 *
 * Interactive command-line interface for ad-hoc AVA operations.
 * Uses testbed-stx for state management.
 *
 * @pattern stx tri-library composition
 * @module
 */

import { useState, useRef, useEffect, useCallback } from 'react'
import { Effect } from 'effect'

import { useStxData, useStx } from '@/lib/stx'
import { getTestbedStx, type ReplHistoryEntry } from './testbed-stx'

// =============================================================================
// Component
// =============================================================================

export function ReplConsole() {
  // Local input state (ephemeral, doesn't need stx)
  const [input, setInput] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)
  const outputRef = useRef<HTMLDivElement>(null)

  // Testbed stx state
  const testbed = getTestbedStx()
  const { runEffect } = useStx(testbed)

  // Fine-grained subscriptions via Legend-State
  const history = useStxData(testbed, d => d.replHistory.get())
  const historyIndex = useStxData(testbed, d => d.replHistoryIndex.get())
  const commandHistory = useStxData(testbed, d => d.replCommandHistory.get())

  // Auto-scroll to bottom
  useEffect(() => {
    if (outputRef.current) {
      outputRef.current.scrollTop = outputRef.current.scrollHeight
    }
  }, [history])

  // Execute command
  const executeCommand = useCallback(async (cmdLine: string) => {
    const trimmed = cmdLine.trim()
    if (!trimmed) return

    await runEffect('executeCommand', trimmed)
    setInput('')
  }, [runEffect])

await runEffect('executeCommand', trimmed)
    setInput('')
  }, [runEffect])

  // Handle key events
  const handleKeyDown = useCallback(async (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      await executeCommand(input)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      const cmd = await runEffect('navigateHistory', 'up') as string
      if (cmd) setInput(cmd)
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      const cmd = await runEffect('navigateHistory', 'down') as string
      setInput(cmd)
    } else if (e.key === 'Tab') {
      e.preventDefault()
      // Tab completion
      if (input.startsWith('!')) {
        const partial = input.slice(1).toLowerCase()
        const commands = ['help', 'list', 'connect', 'disconnect', 'ping', 'subscribe', 'select', 'register', 'status', 'clear', 'json']
        const matches = commands.filter(c => c.startsWith(partial))
        if (matches.length === 1) {
          setInput(`!${matches[0]} `)
        } else if (matches.length > 1) {
          // Show completions via a synthetic history entry
          await runEffect('executeCommand', `!help`)
        }
      }
    } else if (e.key === 'l' && e.ctrlKey) {
      e.preventDefault()
      await runEffect('clearRepl')
    }
  }, [input, executeCommand, runEffect])

return (
    <div className="flex flex-col h-full bg-neutral-950 border border-neutral-800 rounded overflow-hidden">
      {/* Output Area */}
      <div
        ref={outputRef}
        className="flex-1 overflow-y-auto p-3 font-mono"
        style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
      >
        {/* Welcome message */}
        {history.length === 0 && (
          <div className="text-neutral-500 mb-2">
            AVA REPL Console. Type !help for commands. Ctrl+L to clear.
          </div>
        )}

        {/* History */}
        {history.map((entry: ReplHistoryEntry) => (
          <div key={entry.id} className="mb-2">
            <div className="text-cyan-400">
              <span className="text-neutral-500 mr-2">{'>'}</span>
              {entry.input}
            </div>
            <pre className={`whitespace-pre-wrap ml-4 ${entry.isError ? 'text-red-400' : 'text-neutral-300'}`}>
              {entry.output}
            </pre>
          </div>
        ))}
      </div>

      {/* Input Area */}
      <div className="flex items-center border-t border-neutral-800 bg-neutral-900/50">
        <span className="text-cyan-400 px-3 font-mono" style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}>
          {'>'}
        </span>
        <input
          ref={inputRef}
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="!help for commands..."
          className="flex-1 bg-transparent border-none outline-none text-neutral-100 font-mono py-2 pr-3"
          style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
          autoFocus
        />
      </div>
    </div>
  )
}

