  type ScenarioStepStatus,
} from './testbed-stx'

// =============================================================================
// Helpers
// =============================================================================

const getStatusColor = (status: ScenarioStatus | ScenarioStepStatus): string => {
  switch (status) {
    case 'passed':
      return '#22c55e' // green
    case 'failed':
      return '#ef4444' // red
    case 'running':
      return '#22d3ee' // cyan
    case 'paused':
      return '#f59e0b' // amber
    case 'skipped':
      return '#737373' // gray
    default:
      return '#525252' // neutral
  }
}

const getStatusIcon = (status: ScenarioStepStatus): string => {
  switch (status) {
    case 'passed':
      return '✓'
    case 'failed':
      return '✗'
    case 'running':
      return '●'
    case 'skipped':
      return '○'
    default:
      return '○'
  }
}

