/**
 * AVA Sequence Diagram
 *
 * Visualizes the message flow between client and server.
 * UML-style sequence diagram with swimlanes.
 *
 * @pattern stx tri-library composition
 * @module
 */

import { useEffect, useRef } from 'react'

import { useStxData, useStx } from '@/lib/stx'
import { getAvaStx, type MessageLogEntry } from '@/lib/ava/atoms/ava-stx'
import { getTestbedStx, type SequenceEvent } from './testbed-stx'

// =============================================================================
// Constants
// =============================================================================

const LANE_WIDTH = 120
const LANE_GAP = 200
const EVENT_HEIGHT = 40
const HEADER_HEIGHT = 50
const PADDING = 20

// =============================================================================
// Component
// =============================================================================

export function SequenceDiagram() {
  const ava = getAvaStx()
  const testbed = getTestbedStx()
  const containerRef = useRef<HTMLDivElement>(null)

  // Message log from ava-stx
  const messageLog = useStxData(ava, d => d.messageLog.get())
  const sequenceEvents = useStxData(testbed, d => d.sequenceEvents.get())
  const autoScroll = useStxData(testbed, d => d.sequenceAutoScroll.get())
  const { runEffect } = useStx(testbed)

  // Convert message log entries to sequence events format
  const events: SequenceEvent[] = messageLog.map((entry: MessageLogEntry, idx: number) => ({
    id: entry.id,
    timestamp: entry.timestamp,
    source: entry.direction === 'out' ? 'client' as const : 'server' as const,
    target: entry.direction === 'out' ? 'server' as const : 'client' as const,
    type: entry.type,
    label: entry.type,
    duration: undefined,
  }))

// Auto-scroll to bottom when new events arrive
  useEffect(() => {
    if (autoScroll && containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight
    }
  }, [events.length, autoScroll])

  // Calculate SVG dimensions
  const svgHeight = Math.max(300, HEADER_HEIGHT + events.length * EVENT_HEIGHT + PADDING * 2)
  const svgWidth = LANE_WIDTH * 2 + LANE_GAP + PADDING * 2

  // Lane centers
  const clientX = PADDING + LANE_WIDTH / 2
  const serverX = PADDING + LANE_WIDTH + LANE_GAP + LANE_WIDTH / 2

  // Color mapping for event types
  const getEventColor = (type: string): string => {
    const colors: Record<string, string> = {
      artifact: '#22c55e',    // green
      delta: '#22d3ee',       // cyan
      subscribe: '#3b82f6',   // blue
      unsubscribe: '#737373', // gray
      ping: '#f59e0b',        // amber
      pong: '#f59e0b',        // amber
      session: '#a855f7',     // purple
      error: '#ef4444',       // red
      status: '#eab308',      // yellow
    }
    return colors[type] ?? '#a3a3a3'
  }

{/* Diagram */}
      <div
        ref={containerRef}
        className="flex-1 overflow-auto"
      >
        {events.length === 0 ? (
          <div className="flex items-center justify-center h-full text-neutral-600">
            <span
              className="font-mono"
              style={{ fontSize: 'var(--tmnl-text-sm, 14px)' }}
            >
              No messages yet
            </span>
          </div>
        ) : (
          <svg
            width={svgWidth}
            height={svgHeight}
            className="min-w-full"
          >
            {/* Swimlane Headers */}
            <g>
              {/* Client Lane */}
              <rect
                x={PADDING}
                y={10}
                width={LANE_WIDTH}
                height={30}
                rx={4}
                fill="#171717"
                stroke="#525252"
              />
              <text
                x={clientX}
                y={30}
                textAnchor="middle"
                fill="#a3a3a3"
                style={{ fontSize: '12px', fontFamily: 'monospace' }}
              >
                CLIENT
              </text>

              {/* Server Lane */}
              <rect
                x={PADDING + LANE_WIDTH + LANE_GAP}
                y={10}
                width={LANE_WIDTH}
                height={30}
                rx={4}
                fill="#171717"
                stroke="#525252"
              />
              <text
                x={serverX}
                y={30}
                textAnchor="middle"
                fill="#a3a3a3"
                style={{ fontSize: '12px', fontFamily: 'monospace' }}
              >
                SERVER
              </text>
            </g>

{/* Lifelines */}
            <line
              x1={clientX}
              y1={HEADER_HEIGHT}
              x2={clientX}
              y2={svgHeight - PADDING}
              stroke="#404040"
              strokeDasharray="4 4"
            />
            <line
              x1={serverX}
              y1={HEADER_HEIGHT}
              x2={serverX}
              y2={svgHeight - PADDING}
              stroke="#404040"
              strokeDasharray="4 4"
            />

            {/* Events */}
            {events.map((event, idx) => {
              const y = HEADER_HEIGHT + idx * EVENT_HEIGHT + 20
              const isOutbound = event.source === 'client'
              const fromX = isOutbound ? clientX : serverX
              const toX = isOutbound ? serverX : clientX
              const color = getEventColor(event.type)
              const midX = (fromX + toX) / 2

              return (
                <g key={event.id}>
                  {/* Arrow line */}
                  <line
                    x1={fromX}
                    y1={y}
                    x2={toX}
                    y2={y}
                    stroke={color}
                    strokeWidth={1.5}
                    markerEnd={`url(#arrow-${event.type})`}
                  />

                  {/* Arrow head */}
                  <polygon
                    points={
                      isOutbound
                        ? `${toX - 8},${y - 4} ${toX},${y} ${toX - 8},${y + 4}`
                        : `${toX + 8},${y - 4} ${toX},${y} ${toX + 8},${y + 4}`
                    }
                    fill={color}
                  />

                  {/* Event label */}
                  <text
                    x={midX}
                    y={y - 6}
                    textAnchor="middle"
                    fill={color}
                    style={{ fontSize: '10px', fontFamily: 'monospace', fontWeight: 'bold' }}
                  >
                    {event.type.toUpperCase()}
                  </text>

{/* Timestamp */}
                  <text
                    x={isOutbound ? fromX - 5 : fromX + 5}
                    y={y + 4}
                    textAnchor={isOutbound ? 'end' : 'start'}
                    fill="#525252"
                    style={{ fontSize: '8px', fontFamily: 'monospace' }}
                  >
                    {new Date(event.timestamp).toLocaleTimeString()}
                  </text>
                </g>
              )
            })}
          </svg>
        )}
      </div>

      {/* Footer */}
      <div className="px-3 py-1 border-t border-neutral-800 bg-neutral-900/30">
        <span
          className="font-mono text-neutral-600"
          style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
        >
          {events.length} event(s)
        </span>
      </div>
    </div>
  )
}

/**
 * AVA State Machine Inspector
 *
 * Visualizes the XState machine state from ava-stx.
 * Shows state nodes, current state, and transition history.
 *
 * @pattern stx tri-library composition
 * @module
 */

import { useEffect, useState, useCallback } from 'react'
import { Effect } from 'effect'

import { useStxData, useStxMatches, useStx } from '@/lib/stx'
import { getAvaStx } from '@/lib/ava/atoms/ava-stx'
import { getTestbedStx, type InspectorNode } from './testbed-stx'

// =============================================================================
// Types
// =============================================================================

interface TransitionEntry {
  id: string
  from: string
  to: string
  timestamp: number
  event?: string
}

// =============================================================================
// Component
// =============================================================================

export function StateInspector() {
  const ava = getAvaStx()
  const testbed = getTestbedStx()

  // Machine state matching
  const isDisconnected = useStxMatches(ava, 'disconnected')
  const isConnecting = useStxMatches(ava, 'connecting')
  const isConnected = useStxMatches(ava, 'connected')
  const isError = useStxMatches(ava, 'error')

  // Derive current state string
  const currentState = isConnected
    ? 'connected'
    : isConnecting
      ? 'connecting'
      : isError
        ? 'error'
        : 'disconnected'

  // Inspector nodes from testbed-stx
  const inspectorNodes = useStxData(testbed, d => d.inspectorNodes.get())
  const { runEffect } = useStx(testbed)

  // Local transition history for visualization
  const [transitions, setTransitions] = useState<TransitionEntry[]>([])
  const [previousState, setPreviousState] = useState<string | null>(null)

// Local transition history for visualization
  const [transitions, setTransitions] = useState<TransitionEntry[]>([])
  const [previousState, setPreviousState] = useState<string | null>(null)

  // Track state transitions
  useEffect(() => {
    if (previousState && previousState !== currentState) {
      setTransitions(prev => [
        {
          id: `trans-${Date.now()}`,
          from: previousState,
          to: currentState,
          timestamp: Date.now(),
        },
        ...prev.slice(0, 9), // Keep last 10 transitions
      ])
    }
    setPreviousState(currentState)
  }, [currentState, previousState])

  // Sync inspector nodes on state change
  useEffect(() => {
    runEffect('syncInspector').catch(() => {})
  }, [currentState, runEffect])

  // State node definitions
  const stateNodes = [
    { id: 'disconnected', label: 'Disconnected', x: 50, y: 100 },
    { id: 'connecting', label: 'Connecting', x: 200, y: 100 },
    { id: 'connected', label: 'Connected', x: 350, y: 100 },
    { id: 'error', label: 'Error', x: 200, y: 200 },
  ]

  // Edge definitions (transitions)
  const edges = [
    { from: 'disconnected', to: 'connecting', label: 'CONNECT' },
    { from: 'connecting', to: 'connected', label: 'WS_OPEN' },
    { from: 'connecting', to: 'error', label: 'WS_ERROR' },
    { from: 'connected', to: 'disconnected', label: 'DISCONNECT' },
    { from: 'connected', to: 'error', label: 'WS_ERROR' },
    { from: 'error', to: 'disconnected', label: 'RESET' },
  ]

return (
    <div className="flex flex-col h-full bg-neutral-950 border border-neutral-800 rounded overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-neutral-800 bg-neutral-900/50">
        <span
          className="font-mono text-neutral-400"
          style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
        >
          STATE MACHINE
        </span>
        <span
          className="font-mono text-cyan-400"
          style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
        >
          {currentState.toUpperCase()}
        </span>
      </div>

      {/* State Diagram */}
      <div className="flex-1 p-3">
        <svg
          viewBox="0 0 450 280"
          className="w-full h-full"
          style={{ maxHeight: '180px' }}
        >
          {/* Edges */}
          {edges.map((edge, i) => {
            const fromNode = stateNodes.find(n => n.id === edge.from)
            const toNode = stateNodes.find(n => n.id === edge.to)
            if (!fromNode || !toNode) return null

            const isActive =
              (previousState === edge.from && currentState === edge.to)

            // Calculate edge path
            const dx = toNode.x - fromNode.x
            const dy = toNode.y - fromNode.y
            const midX = fromNode.x + dx / 2
            const midY = fromNode.y + dy / 2

// Simple straight line for now
            return (
              <g key={`edge-${i}`}>
                <line
                  x1={fromNode.x + 50}
                  y1={fromNode.y}
                  x2={toNode.x - 50}
                  y2={toNode.y}
                  stroke={isActive ? '#22d3ee' : '#525252'}
                  strokeWidth={isActive ? 2 : 1}
                  markerEnd="url(#arrowhead)"
                  className={isActive ? 'animate-pulse' : ''}
                />
                <text
                  x={midX}
                  y={midY - 8}
                  textAnchor="middle"
                  fill={isActive ? '#22d3ee' : '#737373'}
                  style={{ fontSize: '9px', fontFamily: 'monospace' }}
                >
                  {edge.label}
                </text>
              </g>
            )
          })}

          {/* Arrowhead marker */}
          <defs>
            <marker
              id="arrowhead"
              markerWidth="10"
              markerHeight="7"
              refX="9"
              refY="3.5"
              orient="auto"
            >
              <polygon
                points="0 0, 10 3.5, 0 7"
                fill="#525252"
              />
            </marker>
          </defs>

          {/* State Nodes */}
          {stateNodes.map(node => {
            const isCurrent = currentState === node.id
            const wasRecent = transitions.some(
              t => t.to === node.id && Date.now() - t.timestamp < 2000
            )

return (
              <g key={node.id} transform={`translate(${node.x - 45}, ${node.y - 20})`}>
                {/* Node background */}
                <rect
                  width={90}
                  height={40}
                  rx={6}
                  fill={isCurrent ? '#0a0a0a' : '#171717'}
                  stroke={isCurrent ? '#22d3ee' : '#525252'}
                  strokeWidth={isCurrent ? 2 : 1}
                  className={wasRecent && !isCurrent ? 'animate-pulse' : ''}
                />

                {/* Active indicator */}
                {isCurrent && (
                  <circle
                    cx={10}
                    cy={20}
                    r={4}
                    fill="#22d3ee"
                    className="animate-pulse"
                  />
                )}

                {/* Node label */}
                <text
                  x={45}
                  y={24}
                  textAnchor="middle"
                  fill={isCurrent ? '#22d3ee' : '#a3a3a3'}
                  style={{ fontSize: '11px', fontFamily: 'monospace' }}
                >
                  {node.label}
                </text>
              </g>
            )
          })}
        </svg>
      </div>

/**
 * AVA Testbed UI State with stx
 *
 * Separate stx instance for testbed UI concerns (REPL, inspector, etc.)
 * Keeps domain state (ava-stx) separate from UI state.
 *
 * @pattern stx tri-library composition
 * @pattern Effect Schema for all types
 * @module
 */

import { Effect, Schema, Cause } from 'effect'
import { setup, assign } from 'xstate'

import { stx, type StxInstance, Result } from '@/lib/stx'
import { getAvaStx, type AvaStx } from '@/lib/ava/atoms/ava-stx'

// =============================================================================
// Effect Helpers
// =============================================================================

/**
 * Wrap a stx-wrapped effect (returns Promise<Result>) into a proper Effect.
 * Uses Effect.tryPromise with object form to handle both Promise rejection
 * and Result failures (which carry Cause<E>).
 *
 * effect-atom Result is a tagged union:
 * - { _tag: "Success", value: A }
 * - { _tag: "Failure", cause: Cause<E> }
 * - { _tag: "Initial" }
 *
 * @pattern Effect.tryPromise object form for Promise<Result>
 */
const fromStxEffect = <A>(
  fn: () => Promise<Result.Result<A, unknown>>
): Effect.Effect<A, Error> =>
  Effect.tryPromise({
    try: async () => {
      const result = await fn()
      if (Result.isFailure(result)) {
        // Extract the actual error from Cause using squash
        throw Cause.squash(result.cause)
      }
      if (Result.isInitial(result)) {
        throw new Error('Effect returned Initial result')
      }
      return result.value
    },
    catch: (err) =>
      err instanceof Error ? err : new Error(String(err)),
  })

