  // ---------------------------------------------------------------------------
  const lastTokenRef = useRef<ClientToken | null>(null);

  // Cache the last valid token for reconnect resilience
  if (clientToken) {
    lastTokenRef.current = clientToken;
  }

// Cache the last valid token for reconnect resilience
