    lastTokenRef.current = clientToken;
  }

  const effectiveToken = clientToken ?? lastTokenRef.current;
  const isReconnecting =
    status === 'connecting' && lastTokenRef.current !== null;

  // ---------------------------------------------------------------------------
  // Connection Handlers
