    }

    // Fallback: use loaded files if no discovered files yet
    return fileList.map((mapping: FileMapping) => ({
      path: mapping.path,
      name: mapping.path.split('/').pop()?.replace(/\.md$/, '') ?? 'Untitled',
      modifiedAt: mapping.updatedAt ?? new Date(),
      size: 0,
      mapping,
    }));
  }, [fileIndex.files, fileList]);

  // ---------------------------------------------------------------------------
