const ADJECTIVES = [
  'swift',
  'calm',
  'bold',
  'bright',
  'deep',
  'quick',
  'warm',
  'cool',
  'sharp',
  'soft',
];
const NOUNS = [
  'fox',
  'owl',
  'river',
  'peak',
  'wave',
  'spark',
  'cloud',
  'stone',
  'leaf',
  'wind',
];

export function generatePetName(): string {
  const adj = ADJECTIVES[Math.floor(Math.random() * ADJECTIVES.length)];
