interface ManagedPanelProps {
  id: string
  title: string
  initialPosition: { x: number; y: number }
  initialDimensions: { width: number; height: number }
  constraints?: DimensionConstraints
  show: boolean
  children: ReactNode
}

// =============================================================================
// Managed Panel Wrapper
// =============================================================================

function ManagedPanel({
  id,
  title,
  initialPosition,
  initialDimensions,
  constraints,
  show,
  children,
}: ManagedPanelProps) {
  const stx = getFloatingStx()
  const panelsMap = useSelector(stx.data.panels, (p) => p)
  const panel = panelsMap.get(id)

  useEffect(() => {
    if (show) {
      const existingPanel = getFloatingStx().data.panels.get().get(id)
      if (!existingPanel) {
        registerPanel({
          id,
          title,
          initialPosition,
          initialDimensions,
          constraints,
        })
      }
    } else {
      unregisterPanel(id)
    }

return () => {
      if (show) {
        unregisterPanel(id)
      }
    }
  }, [show, id, title, initialPosition, initialDimensions, constraints])

  if (!show || !panel) {
    return null
  }

  return (
    <FloatingPanel id={id} title={title}>
      {children}
    </FloatingPanel>
  )
}

