// =============================================================================

interface CameraInfo {
  camera: THREE.Camera
  size: { width: number; height: number }
}

function CameraBridge({ onCameraReady }: { onCameraReady: (info: CameraInfo) => void }) {
  const { camera, size } = useThree()

  useEffect(() => {
    onCameraReady({ camera, size })
  }, [camera, size, onCameraReady])

  return null
}

