      const idx = scenarios.findIndex((s) => s.id === scenarioId)

      if (idx === -1) return

      // Reset scenario
      const scenario: Scenario = {
        ...scenarios[idx],
        status: "running",
        currentStepIndex: 0,
        startedAt: Date.now(),
        completedAt: undefined,
        steps: scenarios[idx].steps.map((s) => ({
          ...s,
