// NEW: Unified DataGrid from lib/data-grid
import {
  Tmnl,
  tmnlDenseDark,
  tmnlUltraOps,
  type GridVariantType,
  IdCellRenderer,
  StatusCellRenderer,
  ValueCellRenderer,
  DragHandleRenderer,
} from '@/lib/data-grid'

