/**
 * Cosmo Controller Capability
 * Pattern: pepr-excellent-examples/pepr-operator
 */

import { Capability, a, Log } from 'pepr'
import { CosmoRouter, CosmoSubgraph } from '../crd/types'
import { CosmoRouterCRD } from '../crd/source/cosmo-router.crd'
import { CosmoSubgraphCRD } from '../crd/source/cosmo-subgraph.crd'
import { RegisterCRDs } from '../crd/register'
import { reconcileRouter, reconcileSubgraph } from './reconciler'
import Deploy from './generators'

// Import register to trigger self-executing registration
import '../crd/register'

export const CosmoController = new Capability({
  name: 'cosmo-controller',
  description: 'Manages Cosmo GraphQL Federation resources',
  namespaces: [],
})

const { When, Store } = CosmoController

// =============================================================================
// COSMO ROUTER
// =============================================================================

When(CosmoRouter)
  .IsCreatedOrUpdated()
  .Reconcile(async instance => {
    try {
      Store.setItem(instance.metadata!.name!, JSON.stringify(instance))
      await reconcileRouter(instance)
    } catch (error) {
      Log.error(error, 'Error reconciling CosmoRouter')
    }
  })

When(CosmoRouter)
  .IsDeleted()
  .Mutate(async instance => {
    await Store.removeItemAndWait(instance.Raw.metadata!.name!)
  })

// =============================================================================
// COSMO SUBGRAPH
// =============================================================================

When(CosmoSubgraph)
  .IsCreatedOrUpdated()
  .Reconcile(async instance => {
    try {
      Store.setItem(instance.metadata!.name!, JSON.stringify(instance))
      await reconcileSubgraph(instance)
    } catch (error) {
      Log.error(error, 'Error reconciling CosmoSubgraph')
    }
  })

When(CosmoSubgraph)
  .IsDeleted()
  .Mutate(async instance => {
    await Store.removeItemAndWait(instance.Raw.metadata!.name!)
  })

// =============================================================================
// CRD RECOVERY
// =============================================================================

When(CosmoSubgraph)
  .IsDeleted()
  .Mutate(async instance => {
    await Store.removeItemAndWait(instance.Raw.metadata!.name!)
  })

// =============================================================================
// CRD RECOVERY
// =============================================================================

When(a.CustomResourceDefinition)
  .IsDeleted()
  .WithName(CosmoRouterCRD.metadata.name)
  .Watch(() => {
    RegisterCRDs()
  })

When(a.CustomResourceDefinition)
  .IsDeleted()
  .WithName(CosmoSubgraphCRD.metadata.name)
  .Watch(() => {
    RegisterCRDs()
  })

// =============================================================================
// OWNED RESOURCE RECOVERY
// =============================================================================

When(a.Deployment)
  .IsDeleted()
  .WithLabel('app.kubernetes.io/managed-by', 'cosmo-operator')
  .Watch(async deploy => {
    const stored = Store.getItem(deploy.metadata!.labels!['app.kubernetes.io/instance'])
    if (stored) {
      const instance = JSON.parse(stored) as CosmoRouter
      await Deploy(instance)
    }
  })

When(a.Service)
  .IsDeleted()
  .WithLabel('app.kubernetes.io/managed-by', 'cosmo-operator')
  .Watch(async svc => {
    const stored = Store.getItem(svc.metadata!.labels!['app.kubernetes.io/instance'])
    if (stored) {
      const instance = JSON.parse(stored) as CosmoRouter
      await Deploy(instance)
    }
  })

When(a.ConfigMap)
  .IsDeleted()
  .WithLabel('app.kubernetes.io/managed-by', 'cosmo-operator')
  .Watch(async cm => {
    const stored = Store.getItem(cm.metadata!.labels!['app.kubernetes.io/instance'])
    if (stored) {
      const instance = JSON.parse(stored) as CosmoRouter
      await Deploy(instance)
    }
  })

/**
 * GraphQL Introspection for Pepr Operator
 *
 * Introspects live GraphQL endpoints and extracts schema information.
 * Used by the CosmoSubgraph reconciler when schema.introspection.url is set.
 *
 * @module
 */

import { Log } from 'pepr'
import {
  getIntrospectionQuery,
  buildClientSchema,
  printSchema,
  type IntrospectionQuery,
  type IntrospectionType,
  type IntrospectionOutputTypeRef,
  type IntrospectionNamedTypeRef,
} from 'graphql'

// =============================================================================
// INTROSPECTION CLIENT
// =============================================================================

const INTROSPECTION_QUERY = getIntrospectionQuery()

export interface IntrospectionResult {
  success: boolean
  sdl?: string
  types?: ExtractedType[]
  error?: string
}

export interface ExtractedType {
  name: string
  kind: 'OBJECT' | 'INPUT_OBJECT' | 'ENUM' | 'SCALAR' | 'INTERFACE' | 'UNION'
  description?: string
  fields?: ExtractedField[]
}

export interface ExtractedField {
  name: string
  type: string
  isNullable: boolean
  isList: boolean
  description?: string
}

/**
 * Introspect a GraphQL endpoint and return SDL + type information
 */
export async function introspectEndpoint(url: string): Promise<IntrospectionResult> {
  Log.info({ url }, 'Introspecting GraphQL endpoint')

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({ query: INTROSPECTION_QUERY }),
    })

    if (!response.ok) {
      return {
        success: false,
        error: `HTTP ${response.status}: ${response.statusText}`,
      }
    }

    const json = (await response.json()) as {
      data?: IntrospectionQuery
      errors?: Array<{ message: string }>
    }

const json = (await response.json()) as {
      data?: IntrospectionQuery
      errors?: Array<{ message: string }>
    }

    if (json.errors?.length) {
      return {
        success: false,
        error: json.errors.map((e) => e.message).join('; '),
      }
    }

    if (!json.data) {
      return {
        success: false,
        error: 'No data in introspection response',
      }
    }

    // Build schema from introspection and print SDL
    const schema = buildClientSchema(json.data)
    const sdl = printSchema(schema)

    // Extract types for further processing
    const types = extractTypes(json.data)

    Log.info({ url, typeCount: types.length }, 'Introspection successful')

    return {
      success: true,
      sdl,
      types,
    }
  } catch (error) {
    Log.error({ url, error }, 'Introspection failed')
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    }
  }
}

/**
 * Extract object types from introspection (excluding builtins)
 */
function extractTypes(introspection: IntrospectionQuery): ExtractedType[] {
  return introspection.__schema.types
    .filter(
      (t) =>
        !t.name.startsWith('__') &&
        t.name !== 'Query' &&
        t.name !== 'Mutation' &&
        t.name !== 'Subscription' &&
        (t.kind === 'OBJECT' || t.kind === 'INPUT_OBJECT' || t.kind === 'ENUM')
    )
    .map((t) => extractType(t))
}

function extractType(type: IntrospectionType): ExtractedType {
  const extracted: ExtractedType = {
    name: type.name,
    kind: type.kind as ExtractedType['kind'],
    description: (type as { description?: string }).description,
  }

if (type.kind === 'OBJECT' || type.kind === 'INPUT_OBJECT') {
    const withFields = type as { fields?: Array<{ name: string; type: IntrospectionOutputTypeRef; description?: string }> }
    const inputWithFields = type as { inputFields?: Array<{ name: string; type: IntrospectionOutputTypeRef; description?: string }> }

    const fields = withFields.fields ?? inputWithFields.inputFields ?? []

    extracted.fields = fields.map((f) => {
      const { baseName, isNullable, isList } = unwrapType(f.type)
      return {
        name: f.name,
        type: baseName,
        isNullable,
        isList,
        description: f.description,
      }
    })
  }

  return extracted
}

function unwrapType(typeRef: IntrospectionOutputTypeRef): {
  baseName: string
  isNullable: boolean
  isList: boolean
} {
  let current: IntrospectionOutputTypeRef = typeRef
  let isNullable = true
  let isList = false

  while (current.kind === 'NON_NULL' || current.kind === 'LIST') {
    if (current.kind === 'NON_NULL') {
      isNullable = false
      current = current.ofType
    } else if (current.kind === 'LIST') {
      isList = true
      current = current.ofType
    }
  }

  return {
    baseName: (current as IntrospectionNamedTypeRef).name,
    isNullable,
    isList,
  }
}

// =============================================================================
// EFFECT SCHEMA GENERATION
// =============================================================================

/**
 * Generate Effect Schema code from extracted types
 *
 * This is useful for code generation / registry integration
 */
export function generateEffectSchemaCode(types: ExtractedType[]): string {
  const lines: string[] = [
    "import { Schema } from 'effect'",
    '',
  ]

  for (const type of types) {
    if (type.kind !== 'OBJECT' && type.kind !== 'INPUT_OBJECT') continue
    if (!type.fields?.length) continue

for (const type of types) {
    if (type.kind !== 'OBJECT' && type.kind !== 'INPUT_OBJECT') continue
    if (!type.fields?.length) continue

    lines.push(`export const ${type.name}Schema = Schema.Struct({`)

    for (const field of type.fields) {
      const schemaType = mapFieldToSchema(field)
      const description = field.description ? `.annotations({ title: '${field.description.replace(/'/g, "\\'")}' })` : ''
      lines.push(`  ${field.name}: ${schemaType}${description},`)
    }

    lines.push('})')
    lines.push('')
  }

  return lines.join('\n')
}

function mapFieldToSchema(field: ExtractedField): string {
  let base: string

  switch (field.type) {
    case 'String':
    case 'ID':
      base = 'Schema.String'
      break
    case 'Int':
      base = 'Schema.Number.pipe(Schema.int())'
      break
    case 'Float':
      base = 'Schema.Number'
      break
    case 'Boolean':
      base = 'Schema.Boolean'
      break
    default:
      base = 'Schema.Unknown'
  }

  if (field.isList) {
    base = `Schema.Array(${base})`
  }

  if (field.isNullable) {
    base = `Schema.optional(${base})`
  }

  return base
}

/**
 * Reconciler
 * Pattern: pepr-excellent-examples/pepr-operator
 */

import { K8s, Log } from 'pepr'
import { CosmoRouter, CosmoSubgraph, CosmoRouterStatus, CosmoSubgraphStatus, COSMO_GROUP, COSMO_VERSION, ROUTER_KIND, SUBGRAPH_KIND } from '../crd/types'
import Deploy from './generators'
import { introspectEndpoint, type IntrospectionResult } from './introspection'

// =============================================================================
// ROUTER RECONCILIATION
// =============================================================================

export async function reconcileRouter(router: CosmoRouter): Promise<void> {
  const name = router.metadata!.name!
  const namespace = router.metadata!.namespace!
  const key = `${namespace}/${name}`
  const generation = router.metadata!.generation

  // Skip if already reconciled this generation
  if (router.status?.observedGeneration === generation) {
    Log.debug({ key, generation }, 'Skipping - already reconciled this generation')
    return
  }

  Log.info({ key, generation }, 'Reconciling CosmoRouter')

  try {
    // Update status to Composing
    await updateRouterStatus(router, { phase: 'Composing' })

    // Deploy resources
    await Deploy(router)

    // Update status to Running
    await updateRouterStatus(router, {
      phase: 'Running',
      observedGeneration: router.metadata!.generation,
      subgraphCount: router.spec.subgraphs?.length ?? 0,
    })

    Log.info({ key }, 'CosmoRouter reconciled successfully')
  } catch (error) {
    Log.error({ key, error }, 'Failed to reconcile CosmoRouter')
    await updateRouterStatus(router, {
      phase: 'Failed',
      conditions: [
        {
          type: 'Ready',
          status: 'False',
          reason: 'ReconcileFailed',
          message: String(error),
        },
      ],
    })
    throw error
  }
}

async function updateRouterStatus(
  router: CosmoRouter,
  status: Partial<CosmoRouterStatus>
): Promise<void> {
  const name = router.metadata!.name!
  const namespace = router.metadata!.namespace!

  try {
    const api = K8s(CosmoRouter)
    await api.PatchStatus({
      metadata: { name, namespace },
      status: { ...router.status, ...status },
    } as CosmoRouter)
  } catch (error) {
    Log.warn({ name, namespace, error }, 'Failed to update router status')
  }
}

// =============================================================================
// SUBGRAPH RECONCILIATION
// =============================================================================

export async function reconcileSubgraph(subgraph: CosmoSubgraph): Promise<void> {
  const name = subgraph.metadata!.name!
  const namespace = subgraph.metadata!.namespace!
  const key = `${namespace}/${name}`
  const generation = subgraph.metadata!.generation

  // Skip if already reconciled this generation
  if (subgraph.status?.observedGeneration === generation) {
    Log.debug({ key, generation }, 'Skipping - already reconciled this generation')
    return
  }

  Log.info({ key, generation }, 'Reconciling CosmoSubgraph')

  try {
    // Update status to Validating
    await updateSubgraphStatus(subgraph, { phase: 'Validating' })

    // Validate schema exists
    const hasSchema =
      subgraph.spec.schema.inline ||
      subgraph.spec.schema.configMapRef ||
      subgraph.spec.schema.introspection

    if (!hasSchema) {
      throw new Error('No schema source specified')
    }

    // Handle introspection-based schema discovery
    let sdl: string | undefined
    let introspectionResult: IntrospectionResult | undefined

    if (subgraph.spec.schema.introspection?.url) {
      Log.info({ key, url: subgraph.spec.schema.introspection.url }, 'Introspecting subgraph endpoint')
      introspectionResult = await introspectEndpoint(subgraph.spec.schema.introspection.url)

if (!introspectionResult.success) {
        throw new Error(`Introspection failed: ${introspectionResult.error}`)
      }

      sdl = introspectionResult.sdl
      Log.info(
        { key, typeCount: introspectionResult.types?.length ?? 0 },
        'Introspection successful - SDL extracted'
      )
    } else if (subgraph.spec.schema.inline) {
      sdl = subgraph.spec.schema.inline
    }
    // TODO: Handle configMapRef case

    // TODO: Validate SDL syntax (parse with graphql-js)
    // TODO: Trigger router recomposition (regenerate router.json)

    // Update status to Ready
    await updateSubgraphStatus(subgraph, {
      phase: 'Ready',
      observedGeneration: subgraph.metadata!.generation,
    })

    Log.info({ key }, 'CosmoSubgraph reconciled successfully')
  } catch (error) {
    Log.error({ key, error }, 'Failed to reconcile CosmoSubgraph')
    await updateSubgraphStatus(subgraph, {
      phase: 'Failed',
      conditions: [
        {
          type: 'Ready',
          status: 'False',
          reason: 'ValidationFailed',
          message: String(error),
        },
      ],
    })
    throw error
  }
}

async function updateSubgraphStatus(
  subgraph: CosmoSubgraph,
  status: Partial<CosmoSubgraphStatus>
): Promise<void> {
  const name = subgraph.metadata!.name!
  const namespace = subgraph.metadata!.namespace!

  try {
    const api = K8s(CosmoSubgraph)
    await api.PatchStatus({
      metadata: { name, namespace },
      status: { ...subgraph.status, ...status },
    } as CosmoSubgraph)
  } catch (error) {
    Log.warn({ name, namespace, error }, 'Failed to update subgraph status')
  }
}

