}) {
  /**
   * All inventory assets must be able to tell which inventory "type"
   * they belong to (physical, digital, virtual, etc.).
   */
  abstract getInventoryType(): string

  hasTag(tag: string): boolean {
    return this.tags.includes(tag)
  }
}

