  key: PropertyKey,
  /** Previous value (null if new property) */
  previousValue: Schema.NullOr(PropertyValue),
  /** New value */
  newValue: PropertyValue,
  /** Provenance of new value */
  provenance: Provenance,
  /** Identity of changer */
  changedBy: IdentityId,
  /** When changed */
  changedAt: CreatedAt,
}) {}

