// Helper to emit event if EventLog is available
    const maybeEmit = <T>(
      tag: Parameters<NonNullable<typeof writeEvent>>[0],
      payload: Parameters<NonNullable<typeof writeEvent>>[1]
    ) =>
      writeEvent
        ? writeEvent(tag, payload).pipe(Effect.catchAll(() => Effect.void))
        : Effect.void

    return {
      // ─────────────────────────────────────────────────────────────────────────
      // Command Handlers (with event emission)
      // ─────────────────────────────────────────────────────────────────────────

      CreateAsset: (envelope) =>
        Effect.gen(function* () {
          const asset = yield* state.create({
            siteId: envelope.payload.siteId,
            kind: envelope.payload.kind,
            label: envelope.payload.label,
            description: envelope.payload.description,
            status: envelope.payload.status,
            sectorId: envelope.payload.sectorId,
            containerId: envelope.payload.containerId,
            baseProperties: envelope.payload.baseProperties,
            tags: envelope.payload.tags,
            createdBy: envelope.payload.createdBy,
          })

          // Emit AssetCreated event (use envelope payload for identity info)
          yield* maybeEmit(
            'AssetCreated',
            new AssetCreatedPayload({
              assetId: asset.id,
              siteId: asset.siteId,
              sectorId: asset.sectorId,
              containerId: asset.containerId,
              kind: asset.kind,
              label: asset.label,
              description: asset.description,
              status: asset.status,
              tags: asset.tags,
              createdBy: envelope.payload.createdBy,
              createdAt: asset.createdAt,
            })
          )

          return asset
        }),

      UpdateAsset: (envelope) =>
        Effect.gen(function* () {
          // Get asset before update for diff
          const before = yield* state.findById(envelope.payload.assetId)

return asset
        }),

      UpdateAsset: (envelope) =>
        Effect.gen(function* () {
          // Get asset before update for diff
          const before = yield* state.findById(envelope.payload.assetId)

          const asset = yield* state.update({
            assetId: envelope.payload.assetId,
            label: envelope.payload.label,
            description: envelope.payload.description,
            status: envelope.payload.status,
            tags: envelope.payload.tags,
            expectedVersion: envelope.payload.expectedVersion,
            updatedBy: envelope.payload.updatedBy,
          })

          // Emit AssetUpdated event
          yield* maybeEmit(
            'AssetUpdated',
            new AssetUpdatedPayload({
              assetId: asset.id,
              previousLabel: before.label !== asset.label ? before.label : undefined,
              newLabel: before.label !== asset.label ? asset.label : undefined,
              previousDescription:
                before.description !== asset.description ? before.description : undefined,
              newDescription:
                before.description !== asset.description ? asset.description : undefined,
              previousStatus: before.status !== asset.status ? before.status : undefined,
              newStatus: before.status !== asset.status ? asset.status : undefined,
              previousTags:
                JSON.stringify(before.tags) !== JSON.stringify(asset.tags) ? before.tags : undefined,
              newTags:
                JSON.stringify(before.tags) !== JSON.stringify(asset.tags) ? asset.tags : undefined,
              updatedBy: envelope.payload.updatedBy,
              updatedAt: DateTime.unsafeNow() as CreatedAt,
              // version not available from Asset - tracked internally by AssetState
            })
          )

          return asset
        }),

      MoveAsset: (envelope) =>
        Effect.gen(function* () {
          // Get asset before move
          const before = yield* state.findById(envelope.payload.assetId)

return asset
        }),

      MoveAsset: (envelope) =>
        Effect.gen(function* () {
          // Get asset before move
          const before = yield* state.findById(envelope.payload.assetId)

          const result = yield* state.move({
            assetId: envelope.payload.assetId,
            toSiteId: envelope.payload.toSiteId,
            toSectorId: envelope.payload.toSectorId,
            toContainerId: envelope.payload.toContainerId,
            reason: envelope.payload.reason,
            movedBy: envelope.payload.movedBy,
          })

          // Emit AssetMoved event
          yield* maybeEmit(
            'AssetMoved',
            new AssetMovedPayload({
              assetId: envelope.payload.assetId,
              fromSiteId: before.siteId,
              fromSectorId: before.sectorId,
              fromContainerId: before.containerId,
              toSiteId: envelope.payload.toSiteId,
              toSectorId: envelope.payload.toSectorId,
              toContainerId: envelope.payload.toContainerId,
              reason: envelope.payload.reason,
              movedBy: envelope.payload.movedBy,
              movedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      SetAssetProperty: (envelope) =>
        Effect.gen(function* () {
          // Get previous value if exists
          const prevValue = yield* state
            .getProperty({
              assetId: envelope.payload.assetId,
              key: envelope.payload.key,
            })
            .pipe(Effect.option)

          const result = yield* state.setProperty({
            assetId: envelope.payload.assetId,
            key: envelope.payload.key,
            value: envelope.payload.value,
            provenance: envelope.payload.provenance,
            changedBy: envelope.payload.changedBy,
          })

// Emit PropertyChanged event
          yield* maybeEmit(
            'PropertyChanged',
            new PropertyChangedPayload({
              assetId: envelope.payload.assetId,
              key: envelope.payload.key,
              previousValue: Option.isSome(prevValue) ? prevValue.value.value : null,
              newValue: envelope.payload.value,
              provenance: envelope.payload.provenance,
              changedBy: envelope.payload.changedBy,
              changedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      RemoveAssetProperty: (envelope) =>
        Effect.gen(function* () {
          // Get current value before removal
          const current = yield* state.getProperty({
            assetId: envelope.payload.assetId,
            key: envelope.payload.key,
          })

          const result = yield* state.removeProperty({
            assetId: envelope.payload.assetId,
            key: envelope.payload.key,
            reason: envelope.payload.reason,
            removedBy: envelope.payload.removedBy,
          })

          // Emit PropertyRemoved event
          yield* maybeEmit(
            'PropertyRemoved',
            new PropertyRemovedPayload({
              assetId: envelope.payload.assetId,
              key: envelope.payload.key,
              removedValue: current.value,
              reason: envelope.payload.reason,
              removedBy: envelope.payload.removedBy,
              removedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      AddAssetTrait: (envelope) =>
        Effect.gen(function* () {
          const result = yield* state.addTrait({
            assetId: envelope.payload.assetId,
            traitId: envelope.payload.traitId,
            config: envelope.payload.config,
            addedBy: envelope.payload.addedBy,
          })

// Emit TraitAdded event
          yield* maybeEmit(
            'TraitAdded',
            new TraitAddedPayload({
              assetId: envelope.payload.assetId,
              traitId: envelope.payload.traitId,
              config: envelope.payload.config,
              addedBy: envelope.payload.addedBy,
              addedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      RemoveAssetTrait: (envelope) =>
        Effect.gen(function* () {
          const result = yield* state.removeTrait({
            assetId: envelope.payload.assetId,
            traitId: envelope.payload.traitId,
            reason: envelope.payload.reason,
            removedBy: envelope.payload.removedBy,
          })

          // Emit TraitRemoved event
          yield* maybeEmit(
            'TraitRemoved',
            new TraitRemovedPayload({
              assetId: envelope.payload.assetId,
              traitId: envelope.payload.traitId,
              reason: envelope.payload.reason,
              removedBy: envelope.payload.removedBy,
              removedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      DeleteAsset: (envelope) =>
        Effect.gen(function* () {
          const hardDelete = envelope.payload.hardDelete ?? false

          const result = yield* state.delete({
            assetId: envelope.payload.assetId,
            hardDelete,
            reason: envelope.payload.reason,
            deletedBy: envelope.payload.deletedBy,
          })

          // Emit AssetDeleted event
          yield* maybeEmit(
            'AssetDeleted',
            new AssetDeletedPayload({
              assetId: envelope.payload.assetId,
              reason: envelope.payload.reason,
              hardDelete,
              deletedBy: envelope.payload.deletedBy,
              deletedAt: DateTime.unsafeNow() as CreatedAt,
            })
          )

          return result
        }),

      // ─────────────────────────────────────────────────────────────────────────
      // Query Handlers (no event emission)
      // ─────────────────────────────────────────────────────────────────────────

CountAssetsBySite: (envelope) => state.countBySite(envelope.payload.siteId),

      CountAssetsByStatus: (envelope) => state.countByStatus(envelope.payload.status),

      CountAssetsByKind: (envelope) => state.countByKind(envelope.payload.kind),
    }
  }),
  { defectRetryPolicy: Schedule.exponential('100 millis', 2).pipe(Schedule.upTo('10 seconds')) }
)

/**
 * Asset Entity Layer (Test)
 *
 * Uses in-memory AssetState for fast testing.
 */
export const AssetEntityLayer = AssetEntityHandlers.pipe(
  Layer.provide(AssetState.Default)
)

// Fold all events for this primaryKey
      for (const event of events) {
        switch (event._tag) {
          case 'AssetCreated': {
            const payload = event.payload as AssetCreatedPayload
            currentState = {
              ...currentState,
              siteId: payload.siteId,
              sectorId: payload.sectorId,
              containerId: payload.containerId,
              kind: payload.kind,
              label: payload.label,
              description: payload.description,
              status: payload.status,
              tags: payload.tags,
              createdBy: payload.createdBy,
              createdAt: payload.createdAt,
              version: 1,
            }
            break
          }
          case 'AssetUpdated': {
            const payload = event.payload as AssetUpdatedPayload
            currentState = {
              ...currentState,
              label: payload.newLabel ?? currentState.label,
              description: payload.newDescription ?? currentState.description,
              status: payload.newStatus ?? currentState.status,
              tags: payload.newTags ?? currentState.tags,
              version: payload.version,
            }
            break
          }
          case 'AssetMoved': {
            const payload = event.payload as AssetMovedPayload
            currentState = {
              ...currentState,
              siteId: payload.toSiteId,
              sectorId: payload.toSectorId,
              containerId: payload.toContainerId,
            }
            break
          }
          case 'AssetDeleted': {
            const payload = event.payload as { deletedBy: string; deletedAt: unknown; hardDelete: boolean }
            currentState = {
              ...currentState,
              deleted: true,
              deletedBy: payload.deletedBy,
              deletedAt: payload.deletedAt,
              hardDelete: payload.hardDelete,
            }
            break
          }
          // PropertyChanged, TraitAdded, TraitRemoved don't affect core asset state
          default:
            break
        }
      }

// Write compacted snapshot
      if (currentState.deleted && currentState.hardDelete) {
        // Hard-deleted assets: write deletion marker only
        yield* write('AssetDeleted', {
          assetId: primaryKey,
          reason: 'compacted',
          hardDelete: true,
          deletedBy: currentState.deletedBy!,
          deletedAt: currentState.deletedAt!,
        } as any)
      } else if (currentState.siteId && currentState.kind && currentState.label) {
        // Active or soft-deleted assets: write full state snapshot
        yield* write('AssetCreated', {
          assetId: primaryKey,
          siteId: currentState.siteId,
          sectorId: currentState.sectorId,
          containerId: currentState.containerId,
          kind: currentState.kind,
          label: currentState.label,
          description: currentState.description,
          status: currentState.deleted ? 'retired' : currentState.status,
          tags: currentState.tags,
          createdBy: currentState.createdBy!,
          createdAt: currentState.createdAt!,
        } as any)
      }

      yield* Effect.log(`[Compaction] Compacted ${events.length} events for asset ${primaryKey}`)
    })
)

/**
 * Asset Event Handlers
 *
 * EventLog.group handlers that process events and update read models.
 * These handlers run when events are written to the journal.
 *
 * @module @gbg/tmnl/ams/v2/base/handlers/event-handlers
 */

import { Effect } from 'effect'
import * as EventLog from '@effect/experimental/EventLog'
import { AssetEvents } from '../events/asset'
import { AssetState } from '../services/asset-state'

// ─────────────────────────────────────────────────────────────────────────────
// Event Handlers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Asset Event Handlers Layer
 *
 * Processes asset events and updates the read model (AssetState).
 * Each handler receives { payload, entry, conflicts } and returns success/error.
 */
export const AssetEventHandlers = EventLog.group(AssetEvents, (handlers) =>
  Effect.gen(function* () {
    const state = yield* AssetState

    return handlers
      .handle('AssetCreated', ({ payload }) =>
        Effect.gen(function* () {
          // Event already reflects creation - state was updated by command handler
          // This handler can trigger side effects like notifications, indexing, etc.

yield* Effect.log(`[EventLog] Asset created: ${payload.assetId}`)
          return void 0
        })
      )
      .handle('AssetUpdated', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(`[EventLog] Asset updated: ${payload.assetId} v${payload.version}`)
          return void 0
        })
      )
      .handle('AssetMoved', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(
            `[EventLog] Asset moved: ${payload.assetId} from ${payload.fromSiteId} to ${payload.toSiteId}`
          )
          return void 0
        })
      )
      .handle('PropertyChanged', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(
            `[EventLog] Property changed: ${payload.assetId}.${payload.key} = ${payload.newValue}`
          )
          return void 0
        })
      )
      .handle('PropertyRemoved', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(`[EventLog] Property removed: ${payload.assetId}.${payload.key}`)
          return void 0
        })
      )
      .handle('TraitAdded', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(`[EventLog] Trait added: ${payload.assetId} <- ${payload.traitId}`)
          return void 0
        })
      )
      .handle('TraitRemoved', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(`[EventLog] Trait removed: ${payload.assetId} x ${payload.traitId}`)
          return void 0
        })
      )
      .handle('AssetDeleted', ({ payload }) =>
        Effect.gen(function* () {
          yield* Effect.log(
            `[EventLog] Asset deleted: ${payload.assetId} (hard=${payload.hardDelete})`
          )
          return void 0
        })
      )
  })
)

/**
 * Asset Event Reactivity
