  payload: {
    /** Search query text */
    query: Schema.String.pipe(Schema.minLength(1)),
    /** Scope search to site (optional) */
    siteId: Schema.optional(SiteId),
    /** Filter by status (optional) */
    status: Schema.optional(AssetStatus),
