/**
 * Asset count result
 */
export const AssetCount = Schema.Struct({
  _tag: Schema.Literal('AssetCount'),
  count: Schema.Number,
  groupBy: Schema.optional(Schema.String),
  groupValue: Schema.optional(Schema.String),
})
export type AssetCount = typeof AssetCount.Type

/**
