/**
 * Union of all asset queries for pattern matching
 */
export const AssetQuery = Schema.Union(
  GetAsset,
  GetAssetSummary,
  AssetExists,
  ListAssetsBySite,
  ListAssetsBySector,
  ListAssetsByContainer,
  SearchAssets,
  ListAssetsByTag,
  ListAssetsByKind,
  ListAssetsByStatus,
  GetAssetProperty,
  GetAssetProperties,
  CountAssetsBySite,
  CountAssetsByStatus,
  CountAssetsByKind
)
export type AssetQuery = typeof AssetQuery.Type

