// EASING PRESETS
// =============================================================================

/**
 * Common easing presets for GSAP.
 *
 * These are just strings that GSAP understands.
 * Use them for consistency across the app.
 */
export const GSAP_EASE = {
  // Standard
  linear: 'none',

/**
