 */
export const GSAP_EASE = {
  // Standard
  linear: 'none',

  // Power easings (most common)
  easeOut: 'power2.out',
  easeIn: 'power2.in',
  easeInOut: 'power2.inOut',

  // Snappy
  snapOut: 'power3.out',
  snapIn: 'power3.in',

  // Bouncy
  backOut: 'back.out(1.7)',
  backIn: 'back.in(1.7)',

  // Elastic
  elasticOut: 'elastic.out(1, 0.3)',
  elasticIn: 'elastic.in(1, 0.3)',

