// =============================================================================

/** Parse hex color to RGB */
const parseHex = (hex: string): { r: number; g: number; b: number } => {
  const h = hex.replace('#', '')
  return {
    r: parseInt(h.slice(0, 2), 16),
    g: parseInt(h.slice(2, 4), 16),
    b: parseInt(h.slice(4, 6), 16),
  }
}

/** Convert number to 2-digit hex */
const toHex = (n: number): string =>
  Math.round(Math.max(0, Math.min(255, n)))
    .toString(16)
    .padStart(2, '0')

/** Interpolate hex colors */
export const lerpColor: Interpolator<ColorValue> = (from, to, t) => {
  const c1 = parseHex(from)
  const c2 = parseHex(to)

  const r = lerpNumber(c1.r, c2.r, t)
  const g = lerpNumber(c1.g, c2.g, t)
  const b = lerpNumber(c1.b, c2.b, t)

  return `#${toHex(r)}${toHex(g)}${toHex(b)}` as ColorValue
}

// =============================================================================
// REGISTRY
// =============================================================================

/** All interpolators in one registry */
export const interpolators: InterpolatorRegistry = {
  number: lerpNumber,
  vector: lerpVector,
  object: lerpObject,
  color: lerpColor,
}

// =============================================================================
// AUTO-DETECT INTERPOLATOR
// =============================================================================

/** Detect the correct interpolator based on value type */
export function getInterpolator<T extends AnimationValue>(
  sample: T
): Interpolator<T> {
  if (typeof sample === 'number') {
    return lerpNumber as Interpolator<T>
  }

  if (Array.isArray(sample)) {
    return lerpVector as Interpolator<T>
  }

  if (typeof sample === 'string' && sample.startsWith('#')) {
    return lerpColor as Interpolator<T>
  }

  if (typeof sample === 'object' && sample !== null) {
    return lerpObject as Interpolator<T>
  }

  // Fallback: step function (instant transition at t=1)
  return ((from: T, to: T, t: number) => (t < 1 ? from : to)) as Interpolator<T>
}

/**
 * Animation Library v2 - XState Machine
 *
 * State machine for animation lifecycle management.
 * Handles state transitions, guards, and side effects.
 */

import { createMachine, assign, type MachineConfig } from 'xstate'
import type { AnimationValue, AnimationContext, AnimationEvent } from './types'

// =============================================================================
// MACHINE CONTEXT FACTORY
// =============================================================================

/** Create initial context for a given value type */
export function createInitialContext<T extends AnimationValue>(
  initial: T,
  duration: number = 300,
  ease: string = 'power2.out'
): AnimationContext<T> {
  return {
    current: initial,
    target: initial,
    from: initial,
    progress: 1,
    duration,
    ease,
    startTime: null,
    cancel: null,
  }
}

// =============================================================================
// MACHINE DEFINITION
// =============================================================================

/**
 * Animation state machine.
 *
 * States:
 * - idle: No animation running, value is stable
 * - running: Animation in progress, receiving TICK events
 * - paused: Animation paused, can resume or cancel
 * - completed: Animation finished, can start new animation
 *
 * Events:
 * - START: Begin animating to a new target
 * - TICK: Update current value (from animation driver)
 * - PAUSE: Pause the current animation
 * - RESUME: Resume a paused animation
 * - COMPLETE: Animation finished naturally
 * - CANCEL: Stop animation and reset
 * - SNAP: Immediately set value without animation
 */
export function createAnimationMachine<T extends AnimationValue>(
  initial: T,
  options: { duration?: number; ease?: string } = {}
) {
  const { duration = 300, ease = 'power2.out' } = options

  return createMachine({
    id: 'animation',
    initial: 'idle',
    context: createInitialContext(initial, duration, ease),

return createMachine({
    id: 'animation',
    initial: 'idle',
    context: createInitialContext(initial, duration, ease),

    states: {
      idle: {
        on: {
          START: {
            target: 'running',
            actions: assign(({ context, event }) => ({
              from: context.current,
              target: (event as Extract<AnimationEvent<T>, { type: 'START' }>).to,
              duration: (event as Extract<AnimationEvent<T>, { type: 'START' }>).duration ?? context.duration,
              ease: (event as Extract<AnimationEvent<T>, { type: 'START' }>).ease ?? context.ease,
              progress: 0,
              startTime: performance.now(),
            })),
          },
          SNAP: {
            actions: assign(({ event }) => {
              const snapEvent = event as Extract<AnimationEvent<T>, { type: 'SNAP' }>
              return {
                current: snapEvent.value,
                target: snapEvent.value,
                from: snapEvent.value,
                progress: 1,
              }
            }),
          },
        },
      },

running: {
        on: {
          TICK: {
            actions: assign(({ event }) => {
              const tickEvent = event as Extract<AnimationEvent<T>, { type: 'TICK' }>
              return {
                current: tickEvent.value,
                progress: tickEvent.progress,
              }
            }),
          },
          PAUSE: {
            target: 'paused',
            actions: assign(({ context }) => {
              // Call cancel to stop the animation driver
              context.cancel?.()
              return { cancel: null }
            }),
          },
          COMPLETE: {
            target: 'completed',
            actions: assign(({ context }) => ({
              current: context.target,
              progress: 1,
              cancel: null,
            })),
          },
          CANCEL: {
            target: 'idle',
            actions: assign(({ context }) => {
              context.cancel?.()
              return {
                target: context.current, // Keep current value
                progress: 1,
                cancel: null,
              }
            }),
          },
          // Allow starting a new animation while one is running
          START: {
            target: 'running',
            actions: assign(({ context, event }) => {
              // Cancel current animation
              context.cancel?.()
              const startEvent = event as Extract<AnimationEvent<T>, { type: 'START' }>
              return {
                from: context.current, // Start from current interpolated position
                target: startEvent.to,
                duration: startEvent.duration ?? context.duration,
                ease: startEvent.ease ?? context.ease,
                progress: 0,
                startTime: performance.now(),
                cancel: null,
              }
            }),
          },
          SNAP: {
            target: 'idle',
            actions: assign(({ context, event }) => {
              context.cancel?.()
              const snapEvent = event as Extract<AnimationEvent<T>, { type: 'SNAP' }>
              return {
                current: snapEvent.value,
                target: snapEvent.value,
                from: snapEvent.value,
                progress: 1,
                cancel: null,
              }
            }),
          },
        },
      },

paused: {
        on: {
          RESUME: {
            target: 'running',
            actions: assign(() => ({
              startTime: performance.now(),
            })),
          },
          CANCEL: {
            target: 'idle',
            actions: assign(({ context }) => ({
              target: context.current,
              progress: 1,
            })),
          },
          START: {
            target: 'running',
            actions: assign(({ context, event }) => {
              const startEvent = event as Extract<AnimationEvent<T>, { type: 'START' }>
              return {
                from: context.current,
                target: startEvent.to,
                duration: startEvent.duration ?? context.duration,
                ease: startEvent.ease ?? context.ease,
                progress: 0,
                startTime: performance.now(),
              }
            }),
          },
          SNAP: {
            target: 'idle',
            actions: assign(({ event }) => {
              const snapEvent = event as Extract<AnimationEvent<T>, { type: 'SNAP' }>
              return {
                current: snapEvent.value,
                target: snapEvent.value,
                from: snapEvent.value,
                progress: 1,
              }
            }),
          },
        },
      },

      completed: {
        on: {
          START: {
            target: 'running',
            actions: assign(({ context, event }) => {
              const startEvent = event as Extract<AnimationEvent<T>, { type: 'START' }>
              return {
                from: context.current,
                target: startEvent.to,
                duration: startEvent.duration ?? context.duration,
                ease: startEvent.ease ?? context.ease,
                progress: 0,
                startTime: performance.now(),
              }
            }),
          },
          SNAP: {
            target: 'idle',
            actions: assign(({ event }) => {
              const snapEvent = event as Extract<AnimationEvent<T>, { type: 'SNAP' }>
              return {
                current: snapEvent.value,
                target: snapEvent.value,
                from: snapEvent.value,
                progress: 1,
              }
            }),
          },
        },
      },
    },
  })
}

// =============================================================================
// TYPE HELPERS
// =============================================================================

/** Extract the state value from a machine state */
export type AnimationMachineState = 'idle' | 'running' | 'paused' | 'completed'

/** Type for the machine returned by createAnimationMachine */
export type AnimationMachine<T extends AnimationValue> = ReturnType<
  typeof createAnimationMachine<T>
>

/**
 * Animation Library v2 - Core Types
 *
 * Pure type definitions with no dependencies.
 * These form the foundation for XState machines and effect-atom integration.
 */

// =============================================================================
// VALUE TYPES
// =============================================================================

/** Numeric value (most common) */
export type NumericValue = number

/** Vector value (x, y, etc.) */
export type VectorValue = readonly number[]

/** Object with numeric properties */
export type ObjectValue = Readonly<Record<string, number>>

/** Color as hex string */
export type ColorValue = `#${string}`

/** Union of all animatable value types */
export type AnimationValue = NumericValue | VectorValue | ObjectValue | ColorValue

// =============================================================================
// STATE MACHINE TYPES
// =============================================================================

/** Animation lifecycle states */
export type AnimationState = 'idle' | 'running' | 'paused' | 'completed'

/** Events that can be sent to the animation machine */
export type AnimationEvent<T extends AnimationValue = AnimationValue> =
  | { readonly type: 'START'; readonly to: T; readonly duration?: number; readonly ease?: string }
  | { readonly type: 'PAUSE' }
  | { readonly type: 'RESUME' }
  | { readonly type: 'COMPLETE' }
  | { readonly type: 'CANCEL' }
  | { readonly type: 'SNAP'; readonly value: T }
  | { readonly type: 'TICK'; readonly value: T; readonly progress: number }

/** Context stored by the animation machine */
export interface AnimationContext<T extends AnimationValue = AnimationValue> {
  /** Current interpolated value */
  readonly current: T
  /** Target value we're animating toward */
  readonly target: T
  /** Starting value of this animation */
  readonly from: T
  /** Animation progress 0-1 */
  readonly progress: number
  /** Duration in milliseconds */
  readonly duration: number
  /** Easing function name or custom function */
  readonly ease: string | ((t: number) => number)
  /** Timestamp when animation started */
  readonly startTime: number | null
  /** Cancel function for current animation */
  readonly cancel: (() => void) | null
}

// =============================================================================
// CONFIGURATION TYPES
// =============================================================================

/** Options for creating an animation */
export interface AnimationOptions {
  /** Default duration in ms */
  readonly duration?: number
  /** Default easing */
  readonly ease?: string | ((t: number) => number)
  /** Callback on each tick */
  readonly onTick?: (value: AnimationValue, progress: number) => void
  /** Callback on completion */
  readonly onComplete?: () => void
  /** Callback on cancel */
  readonly onCancel?: () => void
}

/** Options for a single animation call */
export interface AnimateToOptions {
  /** Override default duration */
  readonly duration?: number
  /** Override default easing */
  readonly ease?: string | ((t: number) => number)
}

// =============================================================================
// INTERPOLATION TYPES
// =============================================================================

/** Function that interpolates between two values */
export type Interpolator<T extends AnimationValue> = (
  from: T,
  to: T,
  progress: number
) => T

/** Registry of interpolators by value type */
export interface InterpolatorRegistry {
  readonly number: Interpolator<NumericValue>
  readonly vector: Interpolator<VectorValue>
  readonly object: Interpolator<ObjectValue>
  readonly color: Interpolator<ColorValue>
}

// =============================================================================
// DRIVER TYPES
// =============================================================================

// =============================================================================
// DRIVER TYPES
// =============================================================================

/**
 * Animation driver - executes the actual animation.
 *
 * Unlike v1, this is a simple interface that just runs animations.
 * No timeline abstraction - use GSAP/anime.js directly for complex sequences.
 */
export interface AnimationDriver {
  /**
   * Run an animation from current to target.
   *
   * @param config Animation configuration
   * @returns Cancel function
   */
  readonly run: <T extends AnimationValue>(config: {
    readonly from: T
    readonly to: T
    readonly duration: number
    readonly ease: string | ((t: number) => number)
    readonly onTick: (value: T, progress: number) => void
    readonly onComplete: () => void
  }) => () => void
}

// =============================================================================
// ATOM TYPES (effect-atom integration)
// =============================================================================

/**
 * The public API for an animation atom.
 *
 * Read-only atoms for value/state/progress.
 * Action atoms for to/snap/pause/resume/cancel.
 */
export interface AnimationAtomApi<T extends AnimationValue> {
  // Read-only subscriptions
  readonly value$: unknown // Atom.Atom<T> - typed loosely to avoid import
  readonly state$: unknown // Atom.Atom<AnimationState>
  readonly progress$: unknown // Atom.Atom<number>

  // Actions
  readonly to: (target: T, options?: AnimateToOptions) => void
  readonly snap: (value: T) => void
  readonly pause: () => void
  readonly resume: () => void
  readonly cancel: () => void
}

// =============================================================================
// HOOK RETURN TYPE
// =============================================================================

// =============================================================================
// HOOK RETURN TYPE
// =============================================================================

/**
 * Return type for useAnimation hook
 */
export interface UseAnimationResult<T extends AnimationValue> {
  /** Current interpolated value */
  readonly value: T
  /** Current animation state */
  readonly state: AnimationState
  /** Animation progress 0-1 */
  readonly progress: number
  /** Animate to a new value */
  readonly to: (target: T, options?: AnimateToOptions) => void
  /** Snap immediately to a value */
  readonly snap: (value: T) => void
  /** Pause the current animation */
  readonly pause: () => void
  /** Resume a paused animation */
  readonly resume: () => void
  /** Cancel the current animation */
  readonly cancel: () => void
}

