let serverAvailable = false;

async function checkServerHealth(): Promise<boolean> {
  try {
    const response = await fetch(`${AVA_BASE_URL}/api/v1/views`, {
      method: 'GET',
      signal: AbortSignal.timeout(3000),
    });
    return response.ok || response.status === 404;
  } catch {
    return false;
  }
}

