// =============================================================================
// Types
// =============================================================================

export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error'

export interface MessageLogEntry {
  readonly id: string
  readonly timestamp: number
  readonly direction: 'in' | 'out'
  readonly type: string
  readonly payload: string
}

export interface HypothesisState {
  readonly id: string
  readonly label: string
  readonly status: 'pending' | 'validating' | 'passed' | 'failed'
  readonly evidence?: string
}

export interface AvaTestbedConfig {
  readonly baseUrl: string
  readonly useMock: boolean
}

// =============================================================================
// Machine Definition
// =============================================================================

type ConnectionContext = {
  fiber: Fiber.RuntimeFiber<void, unknown> | null
  errorMessage: string | null
}

type ConnectionEvents =
  | { type: 'CONNECT' }
  | { type: 'CONNECTED' }
  | { type: 'DISCONNECT' }
  | { type: 'ERROR'; message: string }

type ConnectionEvents =
  | { type: 'CONNECT' }
  | { type: 'CONNECTED' }
  | { type: 'DISCONNECT' }
  | { type: 'ERROR'; message: string }

const connectionMachine = setup({
  types: {
    context: {} as ConnectionContext,
    events: {} as ConnectionEvents,
  },
  actions: {
    clearError: assign({ errorMessage: null }),
    setError: assign({
      errorMessage: (_, params: { message: string }) => params.message,
    }),
    clearFiber: assign({ fiber: null }),
  },
}).createMachine({
  id: 'avaConnection',
  initial: 'disconnected',
  context: {
    fiber: null,
    errorMessage: null,
  },
  states: {
    disconnected: {
      entry: 'clearError',
      on: {
        CONNECT: 'connecting',
      },
    },
    connecting: {
      on: {
        CONNECTED: 'connected',
        ERROR: {
          target: 'error',
          actions: {
            type: 'setError',
            params: ({ event }) => ({ message: event.message }),
          },
        },
        DISCONNECT: 'disconnected',
      },
    },
    connected: {
      on: {
        DISCONNECT: {
          target: 'disconnected',
          actions: 'clearFiber',
        },
        ERROR: {
          target: 'error',
          actions: {
            type: 'setError',
            params: ({ event }) => ({ message: event.message }),
          },
        },
      },
    },
    error: {
      on: {
        CONNECT: 'connecting',
        DISCONNECT: 'disconnected',
      },
    },
  },
})

