	message: string;
}};

/** Channel-related errors */
export type ChannelError = 
	| { error: "notFound", content: {
	channel_id: ChannelId;
}}
	| { error: "invalidPipeline", content: {
	channel_id: ChannelId;
	message: string;
}}
	| { error: "sourceUnavailable", content: {
	channel_id: ChannelId;
	source_id: SourceId;
}}
	| { error: "executionFailed", content: {
	channel_id: ChannelId;
	message: string;
}};

/** Action produced by the reconciler's tick */
export type FiberAction = 
	| { action: "compile", content: {
	view_id: ViewId;
	spec: ViewProfileSpec;
}}
	| { action: "mount", content: {
	view_id: ViewId;
}}
	| { action: "update", content: {
	view_id: ViewId;
	delta: ViewDelta;
}}
	| { action: "unmount", content: {
	view_id: ViewId;
	reason: UnmountReason;
}}
	| { action: "suspend", content: {
	view_id: ViewId;
}}
	| { action: "resume", content: {
	view_id: ViewId;
}}
	| { action: "noop", content?: undefined };

/** Join type */
export enum JoinType {
	Inner = "inner",
	Left = "left",
	Right = "right",
	Full = "full",
	Cross = "cross",
}

/** Priority lane for reconciler scheduling */
export enum Lane {
	HardRealTime = "hardRealTime",
	SoftRealTime = "softRealTime",
	Background = "background",
}

/** Reconciler errors */
export type ReconcilerError = 
	| { error: "eventLogCorrupted", content: {
	message: string;
}}
	| { error: "replayFailed", content: {
	sequence: number;
	message: string;
}}
	| { error: "fiberPanic", content: {
	view_id: ViewId;
	message: string;
}}
	| { error: "resourceExhausted", content: {
	resource: string;
}};

/** Source adapter errors */
export type SourceError = 
	| { error: "notFound", content: {
	source_id: SourceId;
}}
	| { error: "connectionFailed", content: {
	source_id: SourceId;
	message: string;
}}
	| { error: "queryFailed", content: {
	source_id: SourceId;
	message: string;
}}
	| { error: "subscriptionFailed", content: {
