/**
 * TMNL Charting v1 - RingBuffer
 *
 * Circular buffer for real-time streaming data.
 * High-performance, zero-allocation after initialization.
 *
 * @experimental v1 API may change.
 */

import { BufferState, type BufferSnapshot } from "../types"

// ─────────────────────────────────────────────────────────────────────────────
// RingBuffer
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Circular buffer for streaming data
 *
 * @example
 * ```ts
 * const buffer = new RingBuffer(512)
 * buffer.push(1.0)
 * buffer.push(2.0)
 * const snapshot = buffer.snapshot()
 * ```
 */
export class RingBuffer {
  private readonly buffer: Float32Array
  private head = 0
  private count = 0

  constructor(public readonly capacity: number) {
    if (capacity <= 0 || !Number.isInteger(capacity)) {
      throw new Error(`RingBuffer capacity must be positive integer, got: ${capacity}`)
    }
    this.buffer = new Float32Array(capacity)
  }

  /**
   * Push a single value
   */
  push(value: number): void {
    // Coerce NaN/Infinity to 0
    const safe = Number.isFinite(value) ? value : 0
    this.buffer[this.head] = safe
    this.head = (this.head + 1) % this.capacity
    if (this.count < this.capacity) this.count++
  }

  /**
   * Push multiple values
   */
  pushBatch(values: readonly number[]): void {
    for (let i = 0; i < values.length; i++) {
      this.push(values[i])
    }
  }

  /**
   * Get immutable snapshot of current data
   */
  snapshot(): BufferSnapshot {
    const length = this.count
    const data = new Float32Array(length)

/**
   * Get immutable snapshot of current data
   */
  snapshot(): BufferSnapshot {
    const length = this.count
    const data = new Float32Array(length)

    for (let i = 0; i < length; i++) {
      const idx = (this.head - length + i + this.capacity) % this.capacity
      data[i] = this.buffer[idx]
    }

    return {
      data,
      length,
      state:
        length === 0
          ? BufferState.Empty
          : length < this.capacity
            ? BufferState.Partial
            : BufferState.Full,
    }
  }

  /**
   * Clear buffer
   */
  clear(): void {
    this.head = 0
    this.count = 0
    this.buffer.fill(0)
  }

  /**
   * Get current fill level (0-1)
   */
  get fillLevel(): number {
    return this.count / this.capacity
  }

  /**
   * Get current count
   */
  get size(): number {
    return this.count
  }

  /**
   * Check if buffer is full
   */
  get isFull(): boolean {
    return this.count === this.capacity
  }

  /**
   * Get value at index (0 = oldest, count-1 = newest)
   */
  at(index: number): number | undefined {
    if (index < 0 || index >= this.count) return undefined
    const idx = (this.head - this.count + index + this.capacity) % this.capacity
    return this.buffer[idx]
  }

  /**
   * Get newest value
   */
  get latest(): number | undefined {
    if (this.count === 0) return undefined
    const idx = (this.head - 1 + this.capacity) % this.capacity
    return this.buffer[idx]
  }

/**
   * Get oldest value
   */
  get oldest(): number | undefined {
    if (this.count === 0) return undefined
    const idx = (this.head - this.count + this.capacity) % this.capacity
    return this.buffer[idx]
  }
}

/**
 * TMNL Charting v1 - SignalGenerator
 *
 * Procedural signal synthesis for testing and demos.
 * Replaces COSS (Composite Orthobasis Stress Signal) with cleaner API.
 *
 * @experimental v1 API may change.
 */

import type { ChartDatum, ChartSeries } from "../types"
import { createDatum } from "../types"
import { RingBuffer } from "./RingBuffer"

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Signal generator function signature
 */
export type GeneratorFunction = (time: number, phase: number, index: number) => number

/**
 * Signal configuration
 */
export interface SignalConfig {
  /** Number of points to generate */
  readonly pointCount: number
  /** Frequency of primary oscillation */
  readonly frequency: number
  /** Amplitude of primary oscillation */
  readonly amplitude: number
  /** Phase offset */
  readonly phase: number
  /** Noise factor (0-1) */
  readonly noise: number
  /** Linear trend slope */
  readonly trend: number
  /** Series identifier */
  readonly series?: string
  /** Group identifier */
  readonly group?: string
  /** Trigger interval (every Nth point is highlighted) */
  readonly triggerInterval?: number
}

const DEFAULT_CONFIG: SignalConfig = {
  pointCount: 256,
  frequency: 2,
  amplitude: 1,
  phase: 0,
  noise: 0.1,
  trend: 0,
  series: undefined,
  group: undefined,
  triggerInterval: 0,
}

// ─────────────────────────────────────────────────────────────────────────────
// Signal Generators
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Signal Generators
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Generate a composite signal (sine + cosine + noise + trend)
 *
 * @example
 * ```ts
 * const data = generateSignal({
 *   pointCount: 512,
 *   frequency: 3,
 *   amplitude: 0.9,
 *   noise: 0.05,
 * })
 * ```
 */
export function generateSignal(config: Partial<SignalConfig> = {}): ChartSeries {
  const cfg: SignalConfig = { ...DEFAULT_CONFIG, ...config }
  const {
    pointCount,
    frequency,
    amplitude,
    phase,
    noise,
    trend,
    series,
    group,
    triggerInterval,
  } = cfg

  const points: ChartDatum[] = []

  for (let i = 0; i < pointCount; i++) {
    const t = i
    const normalizedX = i / pointCount

    // Composite signal: sine + cosine harmonic + trend + noise
    const primaryOsc = Math.sin(normalizedX * frequency * Math.PI * 2 + phase) * amplitude
    const secondaryOsc =
      Math.cos(normalizedX * frequency * Math.PI * 4 + phase) * amplitude * 0.3
    const trendComponent = trend * normalizedX
    const noiseComponent = (Math.random() - 0.5) * noise * 2

    const x = i
    const y = primaryOsc + secondaryOsc + trendComponent + noiseComponent

    const highlight = triggerInterval && triggerInterval > 0 && i % triggerInterval === 0

    points.push(createDatum(t, x, y, { series, group, highlight }))
  }

  return points
}

