/**
 * TMNL Commands — Persistence
 *
 * localStorage persistence for keybinding overrides.
 * Uses effect-atom subscription to auto-save changes.
 */

import { useEffect, useContext, useRef } from 'react'
import { RegistryContext } from '@effect-atom/atom-react'
import { bindingOverridesAtom } from './service'
import type { KeyBindingOverride } from './types'

// ─────────────────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────────────────

const STORAGE_KEY = 'tmnl:keybinding-overrides'
const STORAGE_VERSION = 1

interface StoredData {
  version: number
  overrides: KeyBindingOverride[]
}

// ─────────────────────────────────────────────────────────────────────────────
// Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Load keybinding overrides from localStorage
 */
export function loadOverrides(): KeyBindingOverride[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []

    const data: StoredData = JSON.parse(raw)

    // Version check for future migrations
    if (data.version !== STORAGE_VERSION) {
      console.warn('[commands/persistence] Version mismatch, resetting overrides')
      localStorage.removeItem(STORAGE_KEY)
      return []
    }

    return data.overrides ?? []
  } catch (err) {
    console.error('[commands/persistence] Failed to load overrides:', err)
    return []
  }
}

/**
 * Save keybinding overrides to localStorage
 */
export function saveOverrides(overrides: readonly KeyBindingOverride[]): void {
  try {
    const data: StoredData = {
      version: STORAGE_VERSION,
      overrides: [...overrides],
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
  } catch (err) {
    console.error('[commands/persistence] Failed to save overrides:', err)
  }
}

/**
 * Clear all persisted overrides
 */
export function clearPersistedOverrides(): void {
  try {
    localStorage.removeItem(STORAGE_KEY)
  } catch (err) {
    console.error('[commands/persistence] Failed to clear overrides:', err)
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// React Hook
// ─────────────────────────────────────────────────────────────────────────────

export interface UseKeybindingPersistenceOptions {
  /** Enable debug logging */
  debug?: boolean
  /** Disable auto-load on mount */
  skipLoad?: boolean
  /** Disable auto-save on change */
  skipSave?: boolean
}

export interface UseKeybindingPersistenceResult {
  /** Whether initial load has completed */
  isLoaded: boolean
  /** Number of loaded overrides */
  loadedCount: number
}

/**
 * React hook that handles keybinding persistence.
 *
 * - Loads saved overrides into bindingOverridesAtom on mount
 * - Subscribes to changes and persists to localStorage
 *
 * @example
 * ```tsx
 * function App() {
 *   const { isLoaded } = useKeybindingPersistence()
 *
 *   if (!isLoaded) return <Loading />
 *   return <YourApp />
 * }
 * ```
 */
export function useKeybindingPersistence(
  options: UseKeybindingPersistenceOptions = {}
): UseKeybindingPersistenceResult {
  const { debug = false, skipLoad = false, skipSave = false } = options
  const registry = useContext(RegistryContext)
  const isLoadedRef = useRef(false)
  const loadedCountRef = useRef(0)

  // Load on mount
  useEffect(() => {
    if (skipLoad || isLoadedRef.current) return

    const overrides = loadOverrides()
    if (overrides.length > 0) {
      registry.set(bindingOverridesAtom, overrides)
      loadedCountRef.current = overrides.length
      if (debug) {
        console.log(`[commands/persistence] Loaded ${overrides.length} overrides`)
      }
    }
    isLoadedRef.current = true
  }, [registry, skipLoad, debug])

// Subscribe to changes and save
  useEffect(() => {
    if (skipSave) return

    // Skip first emission (it's the current value)
    let isFirst = true

    const unsubscribe = registry.subscribe(bindingOverridesAtom, (overrides) => {
      if (isFirst) {
        isFirst = false
        return
      }

      saveOverrides(overrides)
      if (debug) {
        console.log(`[commands/persistence] Saved ${overrides.length} overrides`)
      }
    })

    return unsubscribe
  }, [registry, skipSave, debug])

  return {
    isLoaded: isLoadedRef.current,
    loadedCount: loadedCountRef.current,
  }
}

/**
 * TMNL Commands — Effect Service
 *
 * Provides command execution and binding management as an Effect service.
 */

import { Context, Effect, Layer, Option } from 'effect'
import { Atom } from '@effect-atom/atom'
import type {
  Command,
  GlobalCommand,
  EntityCommand,
  CommandError,
  CommandContext,
  KeyBinding,
  KeyBindingOverride,
  KeyBindingsConfig,
  CommandScope,
} from './types'
import { getRegisteredCommands, getDefaultBindings } from './decorators'
import { ops } from '../minibuffer/v2'
import { COMMAND_PROVIDER_ID } from './CommandProvider'

// ─────────────────────────────────────────────────────────────────────────────
// Atoms (Reactive State)
// ─────────────────────────────────────────────────────────────────────────────

/** All registered commands */
export const commandsAtom = Atom.make<ReadonlyMap<string, Command>>(new Map())

/** User keybinding overrides */
export const bindingOverridesAtom = Atom.make<readonly KeyBindingOverride[]>([])

/** Computed effective bindings (defaults + overrides) */
export const effectiveBindingsAtom = Atom.make((get) => {
  const overrides = get(bindingOverridesAtom)
  const defaults = getDefaultBindings()

  // Build override lookup
  const overrideMap = new Map<string, KeyBindingOverride>()
  for (const override of overrides) {
    overrideMap.set(override.commandId, override)
  }

  // Apply overrides to defaults
  const effective: KeyBinding[] = []
  for (const binding of defaults) {
    const override = overrideMap.get(binding.commandId)
    if (override) {
      // null keys means unbind
      if (override.keys !== null) {
        effective.push({
          ...binding,
          keys: override.keys,
          scope: override.scope ?? binding.scope,
        })
      }
      // If keys is null, we skip (unbind)
    } else {
      effective.push(binding)
    }
  }

  return effective as readonly KeyBinding[]
})

// ─────────────────────────────────────────────────────────────────────────────
// Service Definition
// ─────────────────────────────────────────────────────────────────────────────

return effective as readonly KeyBinding[]
})

// ─────────────────────────────────────────────────────────────────────────────
// Service Definition
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Options for executeInteractive (M-x)
 */
export interface ExecuteInteractiveOptions {
  /** Animation style for the minibuffer drawer */
  readonly animate?: 'slide' | 'none'
}

export interface CommandServiceImpl {
  /** Get a command by ID */
  readonly get: (id: string) => Effect.Effect<Option.Option<Command>>

  /** Execute a global command */
  readonly execute: (id: string) => Effect.Effect<void, CommandError>

  /** Execute an entity command with context */
  readonly executeEntity: <T>(
    id: string,
    entity: T,
    ctx?: Partial<CommandContext<T>>
  ) => Effect.Effect<void, CommandError>

  /**
   * Execute interactive command selection (M-x).
   *
   * Opens the minibuffer with command completions, waits for user selection,
   * then executes the selected command.
   *
   * This is the canonical M-x implementation. Hotkeys should call this,
   * NOT call minibuffer directly.
   *
   * @param options - Animation and display options
   * @returns Effect that completes when command finishes (or is cancelled)
   */
  readonly executeInteractive: (options?: ExecuteInteractiveOptions) => Effect.Effect<void>

  /** List all commands */
  readonly list: () => Effect.Effect<readonly Command[]>

  /** List commands by scope */
  readonly listByScope: (scope: CommandScope) => Effect.Effect<readonly Command[]>

  /** Get effective keybindings */
  readonly getBindings: () => Effect.Effect<readonly KeyBinding[]>

/** Get effective keybindings */
  readonly getBindings: () => Effect.Effect<readonly KeyBinding[]>

  /** Override a keybinding */
  readonly overrideBinding: (
    registry: { get: <A>(atom: Atom.Atom<A>) => A; set: <A>(atom: Atom.Writable<A, A>, value: A) => void },
    commandId: string,
    keys: string | null,
    scope?: CommandScope
  ) => Effect.Effect<void>

  /** Reset a keybinding to default */
  readonly resetBinding: (
    registry: { get: <A>(atom: Atom.Atom<A>) => A; set: <A>(atom: Atom.Writable<A, A>, value: A) => void },
    commandId: string
  ) => Effect.Effect<void>

  /** Reset all keybindings to defaults */
  readonly resetAllBindings: (
    registry: { set: <A>(atom: Atom.Writable<A, A>, value: A) => void }
  ) => Effect.Effect<void>
}

export class CommandService extends Context.Tag('tmnl/commands/CommandService')<
  CommandService,
  CommandServiceImpl
>() {
  static Default = Layer.succeed(
    this,
    CommandService.of({
      get: (id) =>
        Effect.sync(() => {
          const commands = getRegisteredCommands()
          return Option.fromNullable(commands.get(id))
        }),

      execute: (id) =>
        Effect.gen(function* () {
          const commands = getRegisteredCommands()
          const command = commands.get(id)

          if (!command) {
            return yield* Effect.fail({ _tag: 'NotFound', commandId: id } as CommandError)
          }

          if (command.type !== 'global') {
            return yield* Effect.fail({
              _tag: 'InvalidContext',
              reason: `Command ${id} requires an entity context`,
            } as CommandError)
          }

          yield* (command as GlobalCommand).execute
        }),

yield* (command as GlobalCommand).execute
        }),

      executeEntity: <T>(id: string, entity: T, ctx?: Partial<CommandContext<T>>) =>
        Effect.gen(function* () {
          const commands = getRegisteredCommands()
          const command = commands.get(id)

          if (!command) {
            return yield* Effect.fail({ _tag: 'NotFound', commandId: id } as CommandError)
          }

          if (command.type !== 'entity') {
            return yield* Effect.fail({
              _tag: 'InvalidContext',
              reason: `Command ${id} is not an entity command`,
            } as CommandError)
          }

          const fullCtx: CommandContext<T> = {
            scope: ctx?.scope ?? command.scope,
            entity,
            args: ctx?.args,
          }

          yield* (command as EntityCommand<T>).execute(entity, fullCtx)
        }),

      executeInteractive: (_options) =>
        Effect.sync(() => {
          // v2: Open minibuffer in command mode
          // Execution happens via the execution stream when user selects
          ops.openCommand(COMMAND_PROVIDER_ID)
        }),

      list: () =>
        Effect.sync(() => Array.from(getRegisteredCommands().values())),

      listByScope: (scope) =>
        Effect.sync(() =>
          Array.from(getRegisteredCommands().values()).filter((c) => c.scope === scope)
        ),

      getBindings: () =>
        Effect.sync(() => getDefaultBindings()),

      overrideBinding: (registry, commandId, keys, scope) =>
        Effect.sync(() => {
          const prev = registry.get(bindingOverridesAtom)
          const filtered = prev.filter((o) => o.commandId !== commandId)
          const override: KeyBindingOverride = { commandId, keys, scope }
          registry.set(bindingOverridesAtom, [...filtered, override])
        }),

      resetBinding: (registry, commandId) =>
        Effect.sync(() => {
          const prev = registry.get(bindingOverridesAtom)
          registry.set(
            bindingOverridesAtom,
            prev.filter((o) => o.commandId !== commandId)
          )
        }),

resetAllBindings: (registry) =>
        Effect.sync(() => {
          registry.set(bindingOverridesAtom, [])
        }),
    })
  )
}

/**
 * TMNL Commands — Type Definitions
 *
 * Two command classes:
 * 1. Global commands - operate without entity context (save, palette, navigation)
 * 2. Entity commands - require a target entity (delete row, format selection)
 */

import { Effect } from 'effect'

// ─────────────────────────────────────────────────────────────────────────────
// Core Types
// ─────────────────────────────────────────────────────────────────────────────

/** Scope determines when a command is available */
export type CommandScope = 'global' | 'editor' | 'grid' | 'tldraw' | 'modal'

/** Command categories for organization */
export type CommandCategory =
  | 'file'
  | 'edit'
  | 'view'
  | 'navigation'
  | 'selection'
  | 'grid'
  | 'canvas'
  | 'system'

/** Base command metadata */
export interface CommandMeta {
  readonly id: string
  readonly name: string
  readonly description?: string
  readonly category: CommandCategory
  readonly scope: CommandScope
  readonly icon?: string
  readonly when?: string // Conditional expression (future: monaco-style)
}

/** Keybinding definition */
export interface KeyBinding {
  readonly keys: string // e.g., 'ctrl+s', 'g i'
  readonly commandId: string
  readonly scope: CommandScope
  readonly when?: string
  readonly args?: Record<string, unknown>
}

/** Command execution context */
export interface CommandContext<TEntity = unknown> {
  readonly scope: CommandScope
  readonly entity?: TEntity
  readonly args?: Record<string, unknown>
}

/** Command error types */
export type CommandError =
  | { readonly _tag: 'NotFound'; readonly commandId: string }
  | { readonly _tag: 'InvalidContext'; readonly reason: string }
  | { readonly _tag: 'ExecutionFailed'; readonly cause: unknown }

// ─────────────────────────────────────────────────────────────────────────────
// Command Definitions
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Command Definitions
// ─────────────────────────────────────────────────────────────────────────────

/** Global command - no entity required */
export interface GlobalCommand extends CommandMeta {
  readonly type: 'global'
  readonly execute: Effect.Effect<void, CommandError>
}

/** Entity command - requires target entity */
export interface EntityCommand<TEntity = unknown> extends CommandMeta {
  readonly type: 'entity'
  readonly entityType: string // e.g., 'grid.row', 'tldraw.shape'
  readonly execute: (entity: TEntity, ctx: CommandContext<TEntity>) => Effect.Effect<void, CommandError>
}

/** Union of all command types */
export type Command = GlobalCommand | EntityCommand

// ─────────────────────────────────────────────────────────────────────────────
// Registry Types
// ─────────────────────────────────────────────────────────────────────────────

/** User keybinding override */
export interface KeyBindingOverride {
  readonly commandId: string
  readonly keys: string | null // null = unbind
  readonly scope?: CommandScope
}

/** Keybindings configuration */
export interface KeyBindingsConfig {
  readonly defaults: readonly KeyBinding[]
  readonly overrides: readonly KeyBindingOverride[]
}

/** Command registry state */
export interface CommandRegistryState {
  readonly commands: ReadonlyMap<string, Command>
  readonly bindings: KeyBindingsConfig
}

/**
 * TMNL Commands — React Hook for Command Wiring
 *
 * Wires all commands and keybindings to the hotkey system on mount.
 * Uses Effect for error handling — no try/catch blocks.
 */

import { useContext, useEffect, useRef, useState, useCallback } from 'react'
import { Effect, Data } from 'effect'
import { RegistryContext, type Registry } from '@effect-atom/atom-react'
import {
  wireCommandsEffect,
  unwireCommandsEffect,
  type WireResult,
  type RegistryLike,
} from './wire'
import { registerCommandProvider } from './CommandProvider'

// ─────────────────────────────────────────────────────────────────────────────
// Error Types (Tagged for Effect.catchTag)
// ─────────────────────────────────────────────────────────────────────────────

/** Error during CommandProvider registration */
export class ProviderRegistrationError extends Data.TaggedError('ProviderRegistrationError')<{
  readonly cause: unknown
}> {}

// ─────────────────────────────────────────────────────────────────────────────
// Effect-Based Provider Registration
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Register CommandProvider with minibuffer.
 * Wrapped in Effect.try for consistent error handling.
 */
const registerProviderEffect: Effect.Effect<void, ProviderRegistrationError> = Effect.try({
  try: () => registerCommandProvider(),
  catch: (cause) => new ProviderRegistrationError({ cause }),
})

export interface UseCommandWireOptions {
  /**
   * Enable debug logging
   * @default false
   */
  debug?: boolean

  /**
   * Called when wiring is complete
   */
  onWired?: (result: WireResult) => void

  /**
   * Called on wiring errors
   */
  onError?: (errors: WireResult['errors']) => void
}

export interface UseCommandWireResult {
  /**
   * Whether commands have been wired
   */
  isWired: boolean

  /**
   * The wiring result (null until wired)
   */
  result: WireResult | null

export interface UseCommandWireResult {
  /**
   * Whether commands have been wired
   */
  isWired: boolean

  /**
   * The wiring result (null until wired)
   */
  result: WireResult | null

  /**
   * Re-wire commands (useful after dynamic command registration)
   */
  rewire: () => void

  /**
   * Clear all wired commands
   */
  clear: () => void
}

/**
 * Hook that wires command system commands to the hotkey system.
 *
 * Call this once at the root of your app, after importing command definitions.
 *
 * @example
 * ```tsx
 * import '@/lib/commands' // Import to register commands
 *
 * function App() {
 *   const { isWired, result } = useCommandWire({
 *     debug: true,
 *     onWired: (r) => console.log(`Wired ${r.commandsRegistered} commands`),
 *   })
 *
 *   if (!isWired) return <div>Loading...</div>
 *
 *   return <YourApp />
 * }
 * ```
 */
export function useCommandWire(options: UseCommandWireOptions = {}): UseCommandWireResult {
  const { debug = false, onWired, onError } = options
  const registry = useContext(RegistryContext)
  const [isWired, setIsWired] = useState(false)
  const [result, setResult] = useState<WireResult | null>(null)
  const hasWired = useRef(false)

  useEffect(() => {
    // Only wire once
    if (hasWired.current) return
    hasWired.current = true

    // Effect-based wiring pipeline — no try/catch
    const wireEffect = Effect.gen(function* () {
      // Register CommandProvider with minibuffer FIRST
      // This ensures M-x completion works via CommandService.executeInteractive()
      yield* registerProviderEffect

      if (debug) {
        yield* Effect.log('[useCommandWire] Registered CommandProvider with minibuffer')
      }

if (debug) {
        yield* Effect.log('[useCommandWire] Registered CommandProvider with minibuffer')
      }

      // Then wire commands to hotkey system
      const wireResult = yield* wireCommandsEffect(registry as RegistryLike)

      if (debug) {
        yield* Effect.log('[useCommandWire] Wired commands:', {
          commands: wireResult.commandsRegistered,
          bindings: wireResult.bindingsRegistered,
          errors: wireResult.errors,
        })
      }

      return wireResult
    }).pipe(
      // Handle provider registration errors
      Effect.catchTag('ProviderRegistrationError', (err) =>
        Effect.gen(function* () {
          yield* Effect.logError('[useCommandWire] Failed to register CommandProvider', err.cause)
          // Return empty result on provider failure
          return { commandsRegistered: 0, bindingsRegistered: 0, errors: [] } as WireResult
        })
      ),
      // Handle any unexpected errors
      Effect.catchAll((err) =>
        Effect.gen(function* () {
          yield* Effect.logError('[useCommandWire] Unexpected error during wiring', err)
          return { commandsRegistered: 0, bindingsRegistered: 0, errors: [] } as WireResult
        })
      )
    )

    // Run the Effect and handle the result
    Effect.runPromise(wireEffect).then((wireResult) => {
      setResult(wireResult)
      setIsWired(true)

      onWired?.(wireResult)

      if (wireResult.errors.length > 0 && onError) {
        onError(wireResult.errors)
      }
    })

    // No cleanup - commands stay registered for app lifetime
  }, [registry, debug, onWired, onError])

  const rewire = useCallback(() => {
    // Effect-based rewiring
    const rewireEffect = Effect.gen(function* () {
      yield* unwireCommandsEffect(registry as RegistryLike)
      const wireResult = yield* wireCommandsEffect(registry as RegistryLike)

if (debug) {
        yield* Effect.log('[useCommandWire] Re-wired commands:', wireResult)
      }

      return wireResult
    })

    Effect.runPromise(rewireEffect).then((wireResult) => {
      setResult(wireResult)
    })
  }, [registry, debug])

  const clear = useCallback(() => {
    // Effect-based clearing
    Effect.runSync(unwireCommandsEffect(registry as RegistryLike))

    setIsWired(false)
    setResult(null)
    hasWired.current = false

    if (debug) {
      console.log('[useCommandWire] Cleared all commands')
    }
  }, [registry, debug])

  return { isWired, result, rewire, clear }
}

/**
 * HOC version for class components or non-hook contexts.
 */
export function withCommandWire<P extends object>(
  Component: React.ComponentType<P>,
  options?: UseCommandWireOptions
): React.FC<P> {
  return function WithCommandWire(props: P) {
    const { isWired } = useCommandWire(options)

    if (!isWired) {
      return null // Or a loading spinner
    }

    return <Component {...props} />
  }
}

/**
 * TMNL Commands — Hotkey Wire
 *
 * Bridges the command system (src/lib/commands) with the hotkey system (src/lib/hotkeys).
 *
 * Call `wireCommandsEffect(registry)` at app initialization to register all commands
 * and their default keybindings with the hotkey system.
 *
 * ERROR HANDLING:
 * Uses Effect for error handling. Wiring errors are accumulated (not fail-fast)
 * so partial wiring is possible. Use `WireError` tagged errors for specific handling.
 */

import { Effect, Data, Ref, Array as A } from 'effect'
import { Atom } from '@effect-atom/atom'
import * as Result from '@effect-atom/atom/Result'
import { getRegisteredCommands, getDefaultBindings } from './decorators'
import type { GlobalCommand, EntityCommand, Command } from './types'
import {
  hotkeyActions,
  hotkeyOps,
  hotkeyRuntimeAtom,
  commandsSourceAtom,
  bindingsSourceAtom,
  type Binding,
  type Command as HotkeyCommand,
  type CommandConfig,
  type ScopeId,
  Scopes,
} from '../hotkeys'

// ─────────────────────────────────────────────────────────────────────────────
// Error Types (Tagged for Effect.catchTag)
// ─────────────────────────────────────────────────────────────────────────────

/** Error during command registration */
export class CommandRegistrationError extends Data.TaggedError('CommandRegistrationError')<{
  readonly commandId: string
  readonly cause: unknown
}> {}

/** Error during keybinding parsing/registration */
export class BindingRegistrationError extends Data.TaggedError('BindingRegistrationError')<{
  readonly commandId: string
  readonly keys: string
  readonly cause: unknown
}> {}

/** Aggregate of all wiring errors (non-fatal, accumulated) */
export class WireError extends Data.TaggedError('WireError')<{
  readonly errors: readonly (CommandRegistrationError | BindingRegistrationError)[]
}> {}

// ─────────────────────────────────────────────────────────────────────────────
// Type Mapping
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Type Mapping
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Maps command system scope to hotkey system scope.
 * Both use the same string IDs, so this is identity + validation.
 */
function mapScope(scope: string): ScopeId {
  const validScopes = Object.values(Scopes) as string[]
  if (validScopes.includes(scope)) {
    return scope as ScopeId
  }
  // Default to global for unknown scopes
  return Scopes.GLOBAL
}

/**
 * Adapts a command from the command system to the hotkey system.
 */
function adaptCommandToHotkey(cmd: Command): HotkeyCommand {
  // For global commands, use execute directly
  // For entity commands, wrap in a handler that logs (entity commands need special handling)
  const handler =
    cmd.type === 'global'
      ? (cmd as GlobalCommand).execute
      : Effect.gen(function* () {
          yield* Effect.log(`Entity command ${cmd.id} triggered - requires entity context`)
        })

  return {
    id: cmd.id,
    name: cmd.name,
    description: cmd.description,
    category: cmd.category,
    icon: cmd.icon,
    handler,
    // Note: cmd.when is a string expression (future: monaco-style)
    // The hotkey system expects a function. For now, skip conversion.
    // TODO: Implement when-expression evaluator
    when: undefined,
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Wire Function
// ─────────────────────────────────────────────────────────────────────────────

export interface WireResult {
  readonly commandsRegistered: number
  readonly bindingsRegistered: number
  readonly errors: readonly (CommandRegistrationError | BindingRegistrationError)[]
}

/**
 * Registry interface needed for wiring.
 */
export interface RegistryLike {
  get: <A>(atom: Atom.Atom<A>) => A
  set: <A>(atom: Atom.Writable<A, A>, value: A) => void
}

// ─────────────────────────────────────────────────────────────────────────────
// Effect-Based Wiring (Primary API)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Register a single command with the hotkey system.
 * Returns the command ID on success.
 */
const registerSingleCommand = (
  registry: RegistryLike,
  id: string,
  cmd: Command
): Effect.Effect<string, CommandRegistrationError> =>
  Effect.try({
    try: () => {
      const hotkeyCmd = adaptCommandToHotkey(cmd)
      hotkeyActions.registerCommand(
        registry,
        {
          id: hotkeyCmd.id,
          name: hotkeyCmd.name,
          description: hotkeyCmd.description,
          category: hotkeyCmd.category,
          icon: hotkeyCmd.icon,
          when: hotkeyCmd.when,
        },
        hotkeyCmd.handler
      )
      return id
    },
    catch: (cause) => new CommandRegistrationError({ commandId: id, cause }),
  })

/**
 * Register a single keybinding with the hotkey system.
 * Returns the command ID on success.
 */
const registerSingleBinding = (
  registry: RegistryLike,
  binding: { keys: string; commandId: string; scope: string }
): Effect.Effect<string, BindingRegistrationError> =>
  Effect.try({
    try: () => {
      // Use the runtime atom to parse keys
      // hotkeyOps.parseKeys is an AtomResultFn - set triggers execution, get retrieves Result
      registry.set(hotkeyOps.parseKeys, binding.keys)
      const parseResult = registry.get(hotkeyOps.parseKeys)

      // Unwrap the Result - throw if not success
      if (!Result.isSuccess(parseResult)) {
        throw new Error(`Failed to parse keys "${binding.keys}": ${Result.isFailure(parseResult) ? String(parseResult.cause) : 'Initial/Waiting state'}`)
      }

      const parsedKeys = parseResult.value

// Use Ref to accumulate errors without fail-fast
    const errorsRef = yield* Ref.make<(CommandRegistrationError | BindingRegistrationError)[]>([])
    const commandCountRef = yield* Ref.make(0)
    const bindingCountRef = yield* Ref.make(0)

    // Register all commands (accumulate errors)
    for (const [id, cmd] of commands) {
      yield* registerSingleCommand(registry, id, cmd).pipe(
        Effect.tap(() => Ref.update(commandCountRef, (n) => n + 1)),
        Effect.catchAll((err) =>
          Ref.update(errorsRef, (errs) => [...errs, err])
        )
      )
    }

    // Register all keybindings (accumulate errors)
    for (const binding of bindings) {
      yield* registerSingleBinding(registry, binding).pipe(
        Effect.tap(() => Ref.update(bindingCountRef, (n) => n + 1)),
        Effect.catchAll((err) =>
          Ref.update(errorsRef, (errs) => [...errs, err])
        )
      )
    }

    const errors = yield* Ref.get(errorsRef)
    const commandsRegistered = yield* Ref.get(commandCountRef)
    const bindingsRegistered = yield* Ref.get(bindingCountRef)

    // Log if there were errors
    if (errors.length > 0) {
      yield* Effect.logWarning(`Wire completed with ${errors.length} errors`)
    }

    return { commandsRegistered, bindingsRegistered, errors }
  })

/**
 * Wire commands synchronously (convenience wrapper).
 *
 * DEPRECATED: Prefer `wireCommandsEffect` for proper error handling.
 * This wrapper uses Effect.runSync which will throw on async operations.
 *
 * @param registry - The effect-atom registry
 * @returns WireResult
 */
export function wireCommands(registry: RegistryLike): WireResult {
  return Effect.runSync(wireCommandsEffect(registry))
}

/**
 * Clear all commands and bindings from the hotkey system.
 * Returns Effect for composition.
 */
export const unwireCommandsEffect = (registry: RegistryLike): Effect.Effect<void> =>
  Effect.sync(() => {
    registry.set(commandsSourceAtom, new Map())
    registry.set(bindingsSourceAtom, [])
  })

/**
 * Clear all commands and bindings from the hotkey system.
 * Synchronous convenience wrapper.
 */
export function unwireCommands(registry: RegistryLike): void {
  Effect.runSync(unwireCommandsEffect(registry))
}

