  withStatus(status: ViewStatus): ViewArtifact {
    return new ViewArtifact({ ...this, status });
  }

withStatus(status: ViewStatus): ViewArtifact {
    return new ViewArtifact({ ...this, status });
  }

  withPayload(payload: unknown, version: number): ViewArtifact {
    return new ViewArtifact({
      ...this,
      payload,
      version,
      status: 'ready',
      hydratedAt: new Date(),
    });
  }
}

