/**
 * Port Status Schemas
 *
 * Effect Schema definitions for connection and stream status tracking.
 *
 * @module connection-ports/schemas/status
 */

import { Schema } from 'effect';
import type { StreamId } from './connection';

// =============================================================================
// Connection Status
// =============================================================================

/**
 * Connection state enumeration.
 */
export const ConnectionState = Schema.Literal(
  'disconnected',
  'connecting',
  'connected',
  'reconnecting',
  'error'
);
export type ConnectionState = typeof ConnectionState.Type;

/**
 * Port-level status for NATS or Durable Streams.
 */
export class PortStatus extends Schema.TaggedClass<PortStatus>()('PortStatus', {
  /** Current connection state */
  state: ConnectionState,

  /** Connected since timestamp (null if not connected) */
  connectedSince: Schema.NullOr(Schema.DateFromSelf),

  /** Last error message (null if no error) */
  lastError: Schema.NullOr(Schema.String),

  /** Number of reconnection attempts */
  reconnectAttempts: Schema.Number,

  /** Latency in milliseconds (from last ping) */
  latencyMs: Schema.NullOr(Schema.Number),
}) {
  static readonly Disconnected = new PortStatus({
    state: 'disconnected',
    connectedSince: null,
    lastError: null,
    reconnectAttempts: 0,
    latencyMs: null,
  });

  isConnected(): boolean {
    return this.state === 'connected';
  }

  isHealthy(): boolean {
    return this.state === 'connected' && this.lastError === null;
  }

  withState(state: ConnectionState): PortStatus {
    return new PortStatus({
      ...this,
      state,
      connectedSince: state === 'connected' ? new Date() : this.connectedSince,
    });
  }

  withError(error: string): PortStatus {
    return new PortStatus({
      ...this,
      state: 'error',
      lastError: error,
    });
  }
}

// =============================================================================
// Stream Status
// =============================================================================

withError(error: string): PortStatus {
    return new PortStatus({
      ...this,
      state: 'error',
      lastError: error,
    });
  }
}

// =============================================================================
// Stream Status
// =============================================================================

/**
 * Stream subscription state enumeration.
 */
export const StreamState = Schema.Literal(
  'idle',
  'subscribing',
  'active',
  'paused',
  'error',
  'closed'
);
export type StreamState = typeof StreamState.Type;

/**
 * Individual stream subscription status.
 */
export class StreamStatus extends Schema.TaggedClass<StreamStatus>()(
  'StreamStatus',
  {
    /** Stream identifier */
    streamId: Schema.String,

    /** Current stream state */
    state: StreamState,

    /** Total messages received */
    messagesReceived: Schema.Number,

    /** Bytes received */
    bytesReceived: Schema.Number,

    /** Last message timestamp */
    lastMessageAt: Schema.NullOr(Schema.DateFromSelf),

    /** Current offset (for durable streams) */
    currentOffset: Schema.NullOr(Schema.String),

    /** Last error message */
    lastError: Schema.NullOr(Schema.String),

    /** Subscription started timestamp */
    startedAt: Schema.NullOr(Schema.DateFromSelf),
  }
) {
  static empty(streamId: string): StreamStatus {
    return new StreamStatus({
      streamId,
      state: 'idle',
      messagesReceived: 0,
      bytesReceived: 0,
      lastMessageAt: null,
      currentOffset: null,
      lastError: null,
      startedAt: null,
    });
  }

  isActive(): boolean {
    return this.state === 'active';
  }

  withMessage(bytes: number, offset?: string): StreamStatus {
    return new StreamStatus({
      ...this,
      messagesReceived: this.messagesReceived + 1,
      bytesReceived: this.bytesReceived + bytes,
      lastMessageAt: new Date(),
      currentOffset: offset ?? this.currentOffset,
    });
  }

withState(state: StreamState): StreamStatus {
    return new StreamStatus({
      ...this,
      state,
      startedAt: state === 'active' ? new Date() : this.startedAt,
    });
  }

  withError(error: string): StreamStatus {
    return new StreamStatus({
      ...this,
      state: 'error',
      lastError: error,
    });
  }
}

// =============================================================================
// Aggregate Status
// =============================================================================

/**
 * Combined status for all connection ports.
 */
export class ConnectionPortsStatus extends Schema.TaggedClass<ConnectionPortsStatus>()(
  'ConnectionPortsStatus',
  {
    /** NATS port status */
    nats: PortStatus,

    /** Durable Streams port status */
    durableStreams: PortStatus,

    /** Active stream subscriptions */
    streams: Schema.Record({ key: Schema.String, value: StreamStatus }),

    /** Last status update */
    updatedAt: Schema.DateFromSelf,
  }
) {
  static readonly Initial = new ConnectionPortsStatus({
    nats: PortStatus.Disconnected,
    durableStreams: PortStatus.Disconnected,
    streams: {},
    updatedAt: new Date(),
  });

  isFullyConnected(): boolean {
    return this.nats.isConnected() && this.durableStreams.isConnected();
  }

  activeStreamCount(): number {
    return Object.values(this.streams).filter((s) => s.isActive()).length;
  }
}

/**
 * ConnectionBus Orchestrator Service
 *
 * Unified service combining NatsPort and DurableStreamsPort
 * with intelligent routing and stream management.
 *
 * @module connection-ports/services/ConnectionBus
 */

import { Context, Effect, Layer, Stream, Schema, Ref } from 'effect';
import { NatsPort, type NatsPortShape } from './NatsPort';
import { DurableStreamsPort, type DurableStreamsPortShape } from './DurableStreamsPort';
import { ConnectionPortsStatus, PortStatus, StreamStatus } from '../schemas/status';
import {
  ConnectionBusNotInitializedError,
  type NatsError,
  type DurableStreamsError,
} from '../schemas/errors';

// =============================================================================
// Subscription Options
// =============================================================================

/**
 * Options for stream subscription.
 */
export interface SubscribeOptions {
  /** Enable historical replay from durable streams */
  readonly replay?: boolean;

  /** Starting offset for replay (default: 'earliest') */
  readonly fromOffset?: string;

  /** Prefer NATS for live updates even with replay enabled */
  readonly preferNats?: boolean;

  /** Buffer size for stream processing */
  readonly bufferSize?: number;
}

// =============================================================================
// Service Interface
// =============================================================================

/**
 * ConnectionBus service interface.
 * Orchestrates NATS and Durable Streams for unified data access.
 */
export interface ConnectionBusShape {
  /**
   * Get aggregate status of all ports.
   */
  readonly status: Effect.Effect<ConnectionPortsStatus>;

  /**
   * Subscribe to a stream with optional replay.
   * Automatically routes to NATS or Durable Streams based on options.
   */
  readonly subscribe: <A>(
    streamId: string,
    schema: Schema.Schema<A>,
    options?: SubscribeOptions
  ) => Stream.Stream<A, NatsError | DurableStreamsError>;

/**
   * Publish a message to a stream.
   * Uses NATS for live distribution, optionally appends to durable stream.
   */
  readonly publish: <A>(
    streamId: string,
    value: A,
    schema: Schema.Schema<A>,
    durable?: boolean
  ) => Effect.Effect<void, NatsError | DurableStreamsError>;

  /**
   * Get direct access to NatsPort.
   */
  readonly nats: () => NatsPortShape;

  /**
   * Get direct access to DurableStreamsPort.
   */
  readonly durable: () => DurableStreamsPortShape;

  /**
   * Initialize connections to all ports.
   */
  readonly connect: Effect.Effect<void, NatsError | DurableStreamsError>;

  /**
   * Disconnect from all ports.
   */
  readonly disconnect: Effect.Effect<void>;

  /**
   * Check if bus is fully connected.
   */
  readonly isConnected: Effect.Effect<boolean>;

  /**
   * Get status of a specific stream subscription.
   */
  readonly getStreamStatus: (
    streamId: string
  ) => Effect.Effect<StreamStatus | null>;
}

// =============================================================================
// Context Tag
// =============================================================================

export class ConnectionBus extends Context.Tag('tmnl/ports/ConnectionBus')<
  ConnectionBus,
  ConnectionBusShape
>() {}

// =============================================================================
// Implementation
// =============================================================================

/**
 * ConnectionBus implementation layer.
 * Combines NatsPort and DurableStreamsPort with intelligent routing.
 */
export const ConnectionBusLive = Layer.effect(
  ConnectionBus,
  Effect.gen(function* () {
    const natsPort = yield* NatsPort;
    const durablePort = yield* DurableStreamsPort;

    // Track active stream subscriptions
    const streamStatuses = yield* Ref.make<Map<string, StreamStatus>>(new Map());

// Track active stream subscriptions
    const streamStatuses = yield* Ref.make<Map<string, StreamStatus>>(new Map());

    const updateStreamStatus = (streamId: string, updater: (s: StreamStatus) => StreamStatus) =>
      Ref.update(streamStatuses, (map) => {
        const current = map.get(streamId) ?? StreamStatus.empty(streamId);
        const updated = updater(current);
        const next = new Map(map);
        next.set(streamId, updated);
        return next;
      });

    return {
      status: Effect.gen(function* () {
        const natsStatus = yield* natsPort.status;
        const durableStatus = yield* durablePort.status;
        const streams = yield* Ref.get(streamStatuses);

        return new ConnectionPortsStatus({
          nats: natsStatus,
          durableStreams: durableStatus,
          streams: Object.fromEntries(streams),
          updatedAt: new Date(),
        });
      }).pipe(Effect.withSpan('ConnectionBus.status')),

      subscribe: <A>(
        streamId: string,
        schema: Schema.Schema<A>,
        options: SubscribeOptions = {}
      ) => {
        const { replay = false, fromOffset = 'earliest', preferNats = false } = options;

        // Track subscription state
        const trackMessage = (data: A) =>
          updateStreamStatus(streamId, (s) =>
            s.withMessage(JSON.stringify(data).length)
          );

        if (replay && !preferNats) {
          // Use durable streams for replay + live tail
          return Stream.unwrap(
            Effect.gen(function* () {
              yield* updateStreamStatus(streamId, (s) => s.withState('subscribing'));

              const durableStreamUrl = `streams/${streamId}`;

