        const healthUrl = `${config.baseUrl.replace(/\/$/, '')}/health`;

// Verify server is reachable by checking health endpoint
        const healthUrl = `${config.baseUrl.replace(/\/$/, '')}/health`;

        const result = yield* httpFetch(healthUrl).pipe(
          Effect.map(() => true),
          Effect.catchAll(() => Effect.succeed(false))
