const ISLAND_CONFIG = {
  sizes: SIZE_PRESETS,
  defaultSize: 'minimal' as const,
  physics: {
    mass: 1,
    tension: 280,
    friction: 24,
    velocity: 0,
  },
  drag: {
    enabled: true,
