            </PromptInputButton>
          </PromptInputTools>

          <PromptInputSubmit
            disabled={isStreaming}
            className="transition-colors"
            style={{
              background: !isStreaming
                ? 'oklch(0.7 0.15 160)'
                : 'oklch(0.2 0 0)',
              color: !isStreaming ? 'oklch(0.1 0 0)' : 'oklch(0.4 0 0)',
