export * from './tools'

// Hooks
export { useCursorPersistence } from './hooks'

// Components
export { Cursor } from './components/Cursor'
export { DynamicIsland, DynamicIslandProvider, useDynamicIsland } from './components/DynamicIsland'
export { ChatContent } from './components/ChatContent'
export { PillIndicator } from './components/PillIndicator'
export { ResizeHandles } from './components/ResizeHandles'

/**
 * Cursor State Machine
 *
 * XState machine for AI chat cursor lifecycle:
 * - pill: Collapsed indicator
 * - expanding: Transition to chat
 * - chat: Full chat interface
 * - collapsing: Transition to pill
 * - repositioning: Moving to new corner
 *
 * Uses stx pattern: XState → snapshotAtom bridge → effect-atom consumers
 */

import { setup, assign, type SnapshotFrom } from 'xstate'
import type { CornerPreset } from '../schemas/position'

// -----------------------------------------------------------------------------
// Context & Event Types
// -----------------------------------------------------------------------------

export interface CursorMachineContext {
  /** Current size preset key */
  sizeKey: string
  /** Current corner position */
  currentCorner: CornerPreset
  /** Has unread messages while in pill state */
  hasUnread: boolean
  /** AI status */
  aiStatus: 'idle' | 'thinking' | 'streaming'
}

export type CursorMachineEvent =
  | { type: 'EXPAND' }
  | { type: 'COLLAPSE' }
  | { type: 'MOVE_TO'; corner: CornerPreset }
  | { type: 'REPOSITION_COMPLETE' }
  | { type: 'AI_THINKING' }
  | { type: 'AI_STREAMING' }
  | { type: 'AI_IDLE' }
  | { type: 'MESSAGE_RECEIVED' }
  | { type: 'MESSAGES_READ' }

// -----------------------------------------------------------------------------
// Timing Constants
// -----------------------------------------------------------------------------

const TIMING = {
  /** Duration for expand/collapse animation */
  transition: 200,
  /** Duration for reposition trajectory */
  reposition: 300,
} as const

// -----------------------------------------------------------------------------
// Machine Definition
// -----------------------------------------------------------------------------

export const cursorMachine = setup({
  types: {
    context: {} as CursorMachineContext,
    events: {} as CursorMachineEvent,
  },
  actions: {
    setSizeMinimal: assign({ sizeKey: 'minimal' }),
    setSizeDefault: assign({ sizeKey: 'default' }),
    setSizeExpanded: assign({ sizeKey: 'expanded' }),

},
  actions: {
    setSizeMinimal: assign({ sizeKey: 'minimal' }),
    setSizeDefault: assign({ sizeKey: 'default' }),
    setSizeExpanded: assign({ sizeKey: 'expanded' }),
    setAiThinking: assign({ aiStatus: 'thinking' }),
    setAiStreaming: assign({ aiStatus: 'streaming' }),
    setAiIdle: assign({ aiStatus: 'idle' }),
    markUnread: assign({ hasUnread: true }),
    clearUnread: assign({ hasUnread: false }),
    updateCorner: assign({
      currentCorner: ({ event }) => {
        if (event.type === 'MOVE_TO') {
          return event.corner
        }
        return 'bottom-right' // fallback
      },
    }),
  },
  guards: {
    hasMessages: ({ context }) => context.hasUnread,
  },
}).createMachine({
  id: 'cursor',
  initial: 'pill',
  context: {
    sizeKey: 'minimal',
    currentCorner: 'bottom-right',
    hasUnread: false,
    aiStatus: 'idle',
  },
  states: {
    pill: {
      entry: ['setSizeMinimal', 'setAiIdle'],
      on: {
        EXPAND: { target: 'expanding' },
        AI_THINKING: { actions: 'setAiThinking' },
        AI_STREAMING: { target: 'expanding' }, // Auto-expand when AI starts streaming
        MESSAGE_RECEIVED: { actions: 'markUnread' },
      },
    },
    expanding: {
      entry: 'setSizeDefault',
      after: {
        [TIMING.transition]: { target: 'chat' },
      },
      on: {
        // Allow interrupting expansion
        COLLAPSE: { target: 'collapsing' },
      },
    },
    chat: {
      entry: 'clearUnread',

},
      on: {
        // Allow interrupting expansion
        COLLAPSE: { target: 'collapsing' },
      },
    },
    chat: {
      entry: 'clearUnread',
      on: {
        COLLAPSE: { target: 'collapsing' },
        MOVE_TO: {
          target: 'repositioning',
          actions: 'updateCorner',
        },
        AI_THINKING: { actions: 'setAiThinking' },
        AI_STREAMING: { actions: 'setAiStreaming' },
        AI_IDLE: { actions: 'setAiIdle' },
        MESSAGES_READ: { actions: 'clearUnread' },
      },
    },
    collapsing: {
      entry: 'setSizeMinimal',
      after: {
        [TIMING.transition]: { target: 'pill' },
      },
      on: {
        // Allow interrupting collapse
        EXPAND: { target: 'expanding' },
        AI_STREAMING: { target: 'expanding' }, // Auto-expand if AI starts responding
      },
    },
    repositioning: {
      // Position animation in progress
      // Uses existing DynamicIsland physics for trajectory
      after: {
        [TIMING.reposition]: { target: 'chat' },
      },
      on: {
        REPOSITION_COMPLETE: { target: 'chat' },
        COLLAPSE: { target: 'collapsing' },
      },
    },
  },
})

// -----------------------------------------------------------------------------
// Type Exports
// -----------------------------------------------------------------------------

export type CursorMachineSnapshot = SnapshotFrom<typeof cursorMachine>

export type CursorMachineState =
  | 'pill'
  | 'expanding'
  | 'chat'
  | 'collapsing'
  | 'repositioning'

/**
 * Extract current state value from snapshot
 */
export function getCursorState(snapshot: CursorMachineSnapshot): CursorMachineState {
  return snapshot.value as CursorMachineState
}

/**
 * Extract current state value from snapshot
 */
export function getCursorState(snapshot: CursorMachineSnapshot): CursorMachineState {
  return snapshot.value as CursorMachineState
}

/**
 * Check if cursor is in an interactive state (not transitioning)
 */
export function isCursorInteractive(snapshot: CursorMachineSnapshot): boolean {
  const state = getCursorState(snapshot)
  return state === 'pill' || state === 'chat'
}

/**
 * Check if cursor is expanded (chat or transitioning to chat)
 */
export function isCursorExpanded(snapshot: CursorMachineSnapshot): boolean {
  const state = getCursorState(snapshot)
  return state === 'chat' || state === 'expanding' || state === 'repositioning'
}

/**
 * Position Schemas for Cursor System
 *
 * Native positioning model using component's { x, y } schema.
 * Corner presets computed from bounds at runtime.
 */

import { Schema } from 'effect'

// -----------------------------------------------------------------------------
// Core Position Types
// -----------------------------------------------------------------------------

export const Position = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
})
export type Position = typeof Position.Type

export const CornerPreset = Schema.Literal(
  'bottom-right',
  'bottom-left',
  'top-right',
  'top-left',
  'center'
)
export type CornerPreset = typeof CornerPreset.Type

export const Bounds = Schema.Struct({
  width: Schema.Number,
  height: Schema.Number,
})
export type Bounds = typeof Bounds.Type

export const IslandSize = Schema.Struct({
  width: Schema.Number,
  height: Schema.Number,
})
export type IslandSize = typeof IslandSize.Type

// -----------------------------------------------------------------------------
// Drag Constraints (from Dynamic Island component)
// -----------------------------------------------------------------------------

export const DragConstraints = Schema.Struct({
  left: Schema.optional(Schema.Number),
  right: Schema.optional(Schema.Number),
  top: Schema.optional(Schema.Number),
  bottom: Schema.optional(Schema.Number),
})
export type DragConstraints = typeof DragConstraints.Type

// -----------------------------------------------------------------------------
// Position Computation
// -----------------------------------------------------------------------------

const DEFAULT_PADDING = 16

// -----------------------------------------------------------------------------
// Position Computation
// -----------------------------------------------------------------------------

const DEFAULT_PADDING = 16

/**
 * Compute absolute position from corner preset
 */
export const computeCornerPosition = (
  preset: CornerPreset,
  bounds: Bounds,
  islandSize: IslandSize,
  padding = DEFAULT_PADDING
): Position => {
  switch (preset) {
    case 'bottom-right':
      return {
        x: bounds.width - islandSize.width - padding,
        y: bounds.height - islandSize.height - padding,
      }
    case 'bottom-left':
      return {
        x: padding,
        y: bounds.height - islandSize.height - padding,
      }
    case 'top-right':
      return {
        x: bounds.width - islandSize.width - padding,
        y: padding,
      }
    case 'top-left':
      return {
        x: padding,
        y: padding,
      }
    case 'center':
      return {
        x: (bounds.width - islandSize.width) / 2,
        y: (bounds.height - islandSize.height) / 2,
      }
  }
}

/**
 * Compute drag constraints from bounds
 */
export const computeConstraints = (
  bounds: Bounds,
  islandSize: IslandSize,
  padding = DEFAULT_PADDING
): DragConstraints => ({
  left: padding,
  right: bounds.width - islandSize.width - padding,
  top: padding,
  bottom: bounds.height - islandSize.height - padding,
})

// Position to specific sides (without corner specified)
  { pattern: /(?:move|position|place)\s+(?:myself\s+)?(?:to\s+)?the\s+left/i, corner: 'bottom-left' },
  { pattern: /(?:move|position|place)\s+(?:myself\s+)?(?:to\s+)?the\s+right/i, corner: 'bottom-right' },
  { pattern: /(?:move|position|place)\s+(?:myself\s+)?(?:to\s+)?the\s+top/i, corner: 'top-right' },
  { pattern: /(?:move|position|place)\s+(?:myself\s+)?(?:to\s+)?the\s+bottom/i, corner: 'bottom-right' },
]

/**
 * Patterns that indicate AI wants to collapse/minimize
 */
const MINIMIZE_PATTERNS: ReadonlyArray<RegExp> = [
  /\bminimiz(?:e|ing)\b/i,
  /\bcollaps(?:e|ing)\b/i,
  /\bget\s+(?:out\s+of\s+)?(?:the\s+)?way\s+(?:for\s+now|temporarily)\b/i,
  /\bhide\s+(?:for\s+now|temporarily)\b/i,
  /\bstep\s+back\b/i,
]

/**
 * Patterns that indicate AI wants to expand/show
 */
const EXPAND_PATTERNS: ReadonlyArray<RegExp> = [
  /\bexpand(?:ing)?\b/i,
  /\bshow(?:ing)?\s+(?:myself|more)\b/i,
  /\bopen(?:ing)?\s+(?:up|chat)\b/i,
  /\blet\s+me\s+show\s+you\b/i,
]

// -----------------------------------------------------------------------------
// Intent Types
// -----------------------------------------------------------------------------

export type PositionIntent = {
  readonly _tag: 'move'
  readonly corner: CornerPreset
}

export type VisibilityIntent = {
  readonly _tag: 'minimize' | 'expand'
}

export type Intent = PositionIntent | VisibilityIntent

export type VisibilityIntent = {
  readonly _tag: 'minimize' | 'expand'
}

export type Intent = PositionIntent | VisibilityIntent

// -----------------------------------------------------------------------------
// Service Interface
// -----------------------------------------------------------------------------

export interface IntentParserShape {
  /**
   * Parse text for position intent (move to corner)
   */
  readonly parsePositionIntent: (text: string) => Option.Option<PositionIntent>

  /**
   * Parse text for visibility intent (minimize/expand)
   */
  readonly parseVisibilityIntent: (text: string) => Option.Option<VisibilityIntent>

  /**
   * Parse text for any intent
   */
  readonly parseIntent: (text: string) => Option.Option<Intent>
}

// -----------------------------------------------------------------------------
// Service Tag
// -----------------------------------------------------------------------------

export class IntentParser extends Context.Tag('tmnl/cursor/IntentParser')<
  IntentParser,
  IntentParserShape
>() {}

// -----------------------------------------------------------------------------
// Implementation
// -----------------------------------------------------------------------------

const intentParserImpl: IntentParserShape = {
  parsePositionIntent: (text: string): Option.Option<PositionIntent> => {
    for (const { pattern, corner } of MOVE_PATTERNS) {
      if (pattern.test(text)) {
        return Option.some({ _tag: 'move', corner })
      }
    }
    return Option.none()
  },

  parseVisibilityIntent: (text: string): Option.Option<VisibilityIntent> => {
    // Check minimize patterns first
    for (const pattern of MINIMIZE_PATTERNS) {
      if (pattern.test(text)) {
        return Option.some({ _tag: 'minimize' })
      }
    }

    // Then check expand patterns
    for (const pattern of EXPAND_PATTERNS) {
      if (pattern.test(text)) {
        return Option.some({ _tag: 'expand' })
      }
    }

    return Option.none()
  },

  parseIntent: (text: string): Option.Option<Intent> => {
    // Position intent takes precedence
    const positionIntent = intentParserImpl.parsePositionIntent(text)
    if (Option.isSome(positionIntent)) {
      return positionIntent
    }

// Then visibility intent
    return intentParserImpl.parseVisibilityIntent(text)
  },
}

// -----------------------------------------------------------------------------
// Layer
// -----------------------------------------------------------------------------

export const IntentParserLive = Layer.succeed(IntentParser, intentParserImpl)

export const IntentParserDefault = IntentParserLive

// -----------------------------------------------------------------------------
// Utility Functions (for direct use without Effect runtime)
// -----------------------------------------------------------------------------

/**
 * Direct function to parse position intent (no Effect runtime needed)
 */
export function parsePositionIntent(text: string): Option.Option<PositionIntent> {
  return intentParserImpl.parsePositionIntent(text)
}

/**
 * Direct function to parse any intent (no Effect runtime needed)
 */
export function parseIntent(text: string): Option.Option<Intent> {
  return intentParserImpl.parseIntent(text)
}

/**
 * PositionService
 *
 * Stateless computation service for cursor positioning.
 * State is managed by atoms (Atom-as-State doctrine).
 * This service provides utilities for position calculations.
 */

import { Effect, Layer, Context } from 'effect'
import {
  type Position,
  type Bounds,
  type IslandSize,
  type CornerPreset,
  type DragConstraints,
  computeCornerPosition,
  computeConstraints,
} from '../schemas/position'

// -----------------------------------------------------------------------------
// Service Interface
// -----------------------------------------------------------------------------

export interface PositionServiceShape {
  /** Compute position for a corner preset */
  readonly computeCornerPosition: (
    preset: CornerPreset,
    bounds: Bounds,
    islandSize: IslandSize,
    padding?: number
  ) => Position

  /** Compute drag constraints from bounds */
  readonly computeConstraints: (
    bounds: Bounds,
    islandSize: IslandSize,
    padding?: number
  ) => DragConstraints

  /** Set position (returns Effect for consistency, but is sync) */
  readonly setPosition: (pos: Position) => Effect.Effect<void>

  /** Set bounds (returns Effect for consistency, but is sync) */
  readonly setBounds: (bounds: Bounds) => Effect.Effect<void>

  /** Move to a corner preset (convenience method) */
  readonly moveToCorner: (
    preset: CornerPreset,
    bounds: Bounds,
    islandSize: IslandSize,
    padding?: number
  ) => Effect.Effect<Position>
}

// -----------------------------------------------------------------------------
// Service Tag
// -----------------------------------------------------------------------------

export class PositionService extends Context.Tag('tmnl/cursor/PositionService')<
  PositionService,
  PositionServiceShape
>() {}

// -----------------------------------------------------------------------------
// Default Implementation
// -----------------------------------------------------------------------------

const DEFAULT_PADDING = 16

const positionServiceImpl: PositionServiceShape = {
  computeCornerPosition: (
    preset: CornerPreset,
    bounds: Bounds,
    islandSize: IslandSize,
    padding = DEFAULT_PADDING
  ): Position => computeCornerPosition(preset, bounds, islandSize, padding),

computeConstraints: (
    bounds: Bounds,
    islandSize: IslandSize,
    padding = DEFAULT_PADDING
  ): DragConstraints => computeConstraints(bounds, islandSize, padding),

  setPosition: (_pos: Position) =>
    // No-op - actual state update happens in atoms via ctx.set()
    Effect.void,

  setBounds: (_bounds: Bounds) =>
    // No-op - actual state update happens in atoms via ctx.set()
    Effect.void,

  moveToCorner: (
    preset: CornerPreset,
    bounds: Bounds,
    islandSize: IslandSize,
    padding = DEFAULT_PADDING
  ) =>
    Effect.sync(() => computeCornerPosition(preset, bounds, islandSize, padding)),
}

// -----------------------------------------------------------------------------
// Layer
// -----------------------------------------------------------------------------

export const PositionServiceLive = Layer.succeed(PositionService, positionServiceImpl)

export const PositionServiceDefault = PositionServiceLive

