/**
 * DataGrid A/B Testing
 *
 * Utilities for switching between legacy and unified DataGrid implementations.
 *
 * @example
 * ```tsx
 * // Enable unified implementation
 * setDataGridVariant('unified')
 *
 * // Use wrapper that auto-switches
 * <DataGridAB id="emitters" variant={tmnlDenseDark} rowData={data}>
 *   <DataGrid.Header>...</DataGrid.Header>
 *   <DataGrid.Body />
 * </DataGridAB>
 * ```
 *
 * @module
 */

import { createContext, useContext, useState, type ReactNode } from 'react'

// =============================================================================
// VARIANT TYPES
// =============================================================================

export type DataGridImplementation = 'legacy' | 'unified'

// =============================================================================
// GLOBAL STATE
// =============================================================================

/** Current global implementation (can be overridden per-instance) */
let globalImplementation: DataGridImplementation = 'legacy'

/**
 * Set the global DataGrid implementation.
 * Affects all grids that don't specify an explicit implementation.
 */
export function setDataGridImplementation(impl: DataGridImplementation): void {
  globalImplementation = impl
}

/**
 * Get the current global DataGrid implementation.
 */
export function getDataGridImplementation(): DataGridImplementation {
  return globalImplementation
}

// =============================================================================
// CONTEXT
// =============================================================================

interface DataGridABContextValue {
  implementation: DataGridImplementation
  setImplementation: (impl: DataGridImplementation) => void
}

const DataGridABContext = createContext<DataGridABContextValue | null>(null)

// =============================================================================
// PROVIDER
// =============================================================================

export interface DataGridABProviderProps {
  /** Initial implementation (defaults to global) */
  defaultImplementation?: DataGridImplementation
  /** Children */
  children: ReactNode
}

/**
 * DataGridABProvider
 *
 * Provides A/B testing context for DataGrid implementations.
 * Wrap your app or a section to enable switching.
 */
export function DataGridABProvider({
  defaultImplementation,
  children,
}: DataGridABProviderProps) {
  const [implementation, setImplementation] = useState<DataGridImplementation>(
    defaultImplementation ?? globalImplementation
  )

return (
    <DataGridABContext.Provider value={{ implementation, setImplementation }}>
      {children}
    </DataGridABContext.Provider>
  )
}

// =============================================================================
// HOOKS
// =============================================================================

/**
 * useDataGridAB
 *
 * Access the current DataGrid implementation and setter.
 */
export function useDataGridAB(): DataGridABContextValue {
  const ctx = useContext(DataGridABContext)

  if (!ctx) {
    // No provider - use global
    return {
      implementation: globalImplementation,
      setImplementation: setDataGridImplementation,
    }
  }

  return ctx
}

/**
 * useIsUnifiedDataGrid
 *
 * Quick check if unified implementation is active.
 */
export function useIsUnifiedDataGrid(): boolean {
  const { implementation } = useDataGridAB()
  return implementation === 'unified'
}

// =============================================================================
// DISPLAY NAMES
// =============================================================================

DataGridABProvider.displayName = 'DataGridABProvider'

/**
 * useCanvasDrop Hook
 *
 * Handles ghost shape creation and canvas drop for tldraw integration.
 * Bridges GridDragService to tldraw editor.
 *
 * @module
 */

import { useCallback, useRef } from 'react'
import type { Editor, TLShapeId } from 'tldraw'
import { createShapeId } from 'tldraw'
import type { GridRow, Point } from '../../types'

// =============================================================================
// TYPES
// =============================================================================

export interface UseCanvasDropOptions {
  /** tldraw editor instance */
  editor: Editor
  /** Source shape ID (for tracking) */
  sourceShapeId: string
  /** Callback to create the final shape on drop */
  onDrop?: (rowData: GridRow, canvasPos: Point) => void
}

export interface UseCanvasDropResult {
  /** Create a ghost shape at screen position */
  createGhost: (rowData: GridRow, screenPos: Point) => TLShapeId
  /** Update ghost position */
  updateGhost: (ghostId: TLShapeId, screenPos: Point) => void
  /** Remove ghost shape */
  removeGhost: (ghostId: TLShapeId) => void
  /** Convert screen to canvas coordinates */
  screenToCanvas: (screenPos: Point) => Point
}

// =============================================================================
// HOOK
// =============================================================================

export function useCanvasDrop(options: UseCanvasDropOptions): UseCanvasDropResult {
  const { editor, sourceShapeId, onDrop } = options

  // Track active ghosts
  const activeGhostsRef = useRef<Set<TLShapeId>>(new Set())

  // Convert screen coordinates to canvas coordinates
  const screenToCanvas = useCallback(
    (screenPos: Point): Point => {
      const canvasPos = editor.screenToPage(screenPos)
      return { x: canvasPos.x, y: canvasPos.y }
    },
    [editor]
  )

// Create ghost shape
  const createGhost = useCallback(
    (rowData: GridRow, screenPos: Point): TLShapeId => {
      const canvasPos = screenToCanvas(screenPos)
      const ghostId = createShapeId()

      // Create an acquire-ghost shape (or any ghost shape type you have)
      editor.createShape({
        id: ghostId,
        type: 'acquire-ghost',
        x: canvasPos.x - 30, // Center offset
        y: canvasPos.y - 30,
        props: {
          w: 60,
          h: 60,
          rowName: 'name' in rowData ? (rowData as any).name : rowData.id,
          status: 'status' in rowData ? (rowData as any).status : 'active',
        },
      })

      activeGhostsRef.current.add(ghostId)

      return ghostId
    },
    [editor, screenToCanvas]
  )

  // Update ghost position
  const updateGhost = useCallback(
    (ghostId: TLShapeId, screenPos: Point) => {
      const canvasPos = screenToCanvas(screenPos)
      const ghost = editor.getShape(ghostId)

      if (ghost) {
        editor.updateShape({
          id: ghostId,
          type: 'acquire-ghost',
          x: canvasPos.x - 30,
          y: canvasPos.y - 30,
        })
      }
    },
    [editor, screenToCanvas]
  )

  // Remove ghost shape
  const removeGhost = useCallback(
    (ghostId: TLShapeId) => {
      try {
        editor.deleteShape(ghostId)
        activeGhostsRef.current.delete(ghostId)
      } catch {
        // Shape may already be deleted
      }
    },
    [editor]
  )

  return {
    createGhost,
    updateGhost,
    removeGhost,
    screenToCanvas,
  }
}

/**
 * Base ColumnSchema Implementation
 *
 * Abstract base class providing common functionality for column schemas.
 * Extend this class to create payload-specific schemas.
 *
 * @module
 */

import type { ColDef, ICellRendererParams, ValueGetterParams } from 'ag-grid-community'
import type { GridVariantType } from '../schemas'
import type {
  ColumnSchema,
  SchemaMetadata,
  PayloadSummary,
  ColumnConfig,
  ColumnGroupConfig,
} from './types'

// =============================================================================
// ABSTRACT BASE CLASS
// =============================================================================

/**
 * BaseColumnSchema - Abstract base implementation.
 *
 * Provides:
 * - Metadata storage
 * - Column config → ColDef conversion
 * - Common styling utilities
 *
 * Subclasses must implement:
 * - detect() - Payload type detection
 * - generateColumns() - Column definition generation
 * - getPayloadRenderer() - Compact renderer component
 * - getSummary() - Payload summary extraction
 *
 * @typeParam TData - Row data type
 * @typeParam TPayload - Payload type this schema handles
 */
export abstract class BaseColumnSchema<TData = unknown, TPayload = unknown>
  implements ColumnSchema<TData, TPayload>
{
  readonly metadata: SchemaMetadata

  constructor(metadata: SchemaMetadata) {
    this.metadata = metadata
  }

  // ===========================================================================
  // ABSTRACT METHODS (must be implemented by subclasses)
  // ===========================================================================

  /**
   * Detect if payload matches this schema's format.
   */
  abstract detect(payload: unknown): payload is TPayload

  /**
   * Generate column definitions for this schema.
   */
  abstract generateColumns(variant: GridVariantType): Array<ColDef<TData>>

  /**
   * Get payload renderer component for compact display.
   */
  abstract getPayloadRenderer(variant: GridVariantType): React.ComponentType<ICellRendererParams<TData>>

  /**
   * Extract summary from payload.
   */
  abstract getSummary(payload: TPayload): PayloadSummary

  // ===========================================================================
  // UTILITY METHODS (available to subclasses)
  // ===========================================================================

/**
   * Extract summary from payload.
   */
  abstract getSummary(payload: TPayload): PayloadSummary

  // ===========================================================================
  // UTILITY METHODS (available to subclasses)
  // ===========================================================================

  /**
   * Convert ColumnConfig to AG-Grid ColDef.
   */
  protected toColDef(config: ColumnConfig<TData>, variant: GridVariantType): ColDef<TData> {
    const colDef: ColDef<TData> = {
      headerName: config.headerName,
      width: config.width,
      minWidth: config.minWidth,
      suppressSizeToFit: config.suppressSizeToFit,
      pinned: config.pinned,
      sortable: config.sortable ?? false,
      resizable: config.resizable ?? true,
    }

    if (config.field) {
      colDef.field = config.field
    }

    if (config.valueGetter) {
      colDef.valueGetter = config.valueGetter
    }

    if (config.valueFormatter) {
      colDef.valueFormatter = config.valueFormatter as ColDef<TData>['valueFormatter']
    }

    // Handle cell renderer
    if (config.cellRenderer) {
      if (typeof config.cellRenderer === 'function') {
        colDef.cellRenderer = config.cellRenderer
      } else {
        // CellRendererConfig - create wrapper component
        const rendererConfig = config.cellRenderer
        colDef.cellRenderer = (params: ICellRendererParams<TData>) => {
          const value = rendererConfig.getValue(params)
          const style = rendererConfig.getStyle(value, variant)
          return (
            <span style={style}>{rendererConfig.formatValue(value)}</span>
          )
        }
      }
    }

    // Handle cell style
    if (config.cellStyle) {
      colDef.cellStyle = config.cellStyle as ColDef<TData>['cellStyle']
    }

    return colDef
  }

// Handle cell style
    if (config.cellStyle) {
      colDef.cellStyle = config.cellStyle as ColDef<TData>['cellStyle']
    }

    return colDef
  }

  /**
   * Convert ColumnGroupConfig to AG-Grid ColDef with children.
   */
  protected toColDefGroup(config: ColumnGroupConfig<TData>, variant: GridVariantType): ColDef<TData> {
    return {
      headerName: config.headerName,
      headerClass: config.headerClass,
      marryChildren: config.marryChildren ?? true,
      children: config.children.map((child) => this.toColDef(child, variant)),
    } as ColDef<TData>
  }

  /**
   * Create a value cell style with monospace font and tabular nums.
   */
  protected valueStyle(variant: GridVariantType, color?: string): React.CSSProperties {
    return {
      color: color ?? variant.colors.signal.accent,
      fontFamily: 'monospace',
      fontVariantNumeric: 'tabular-nums',
      fontSize: variant.density.fontSize,
    }
  }

  /**
   * Create a label/muted cell style.
   */
  protected mutedStyle(variant: GridVariantType): React.CSSProperties {
    return {
      color: variant.colors.text.muted,
      fontSize: variant.density.fontSizeXs,
    }
  }

  /**
   * Create a secondary cell style.
   */
  protected secondaryStyle(variant: GridVariantType): React.CSSProperties {
    return {
      color: variant.colors.text.secondary,
      fontSize: variant.density.fontSizeXs,
      fontFamily: 'monospace',
    }
  }

  /**
   * Format a number with locale string.
   */
  protected formatNumber(value: unknown, decimals = 2): string {
    if (typeof value !== 'number') return '—'
    return value.toFixed(decimals)
  }

/**
   * Format a large number with K/M suffix.
   */
  protected formatCompact(value: unknown): string {
    if (typeof value !== 'number') return '—'
    if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`
    if (value >= 1_000) return `${(value / 1_000).toFixed(1)}k`
    return value.toFixed(1)
  }
}

