/**
 * Known sensor types with semantic styling
 */
const SENSOR_SEMANTICS: Record<string, { label: string; color: string }> = {
  temperature: { label: 'Temp', color: '#ef4444' },
  humidity: { label: 'Humidity', color: '#3b82f6' },
  pressure: { label: 'Pressure', color: '#8b5cf6' },
  voltage: { label: 'Voltage', color: '#f59e0b' },
  current: { label: 'Current', color: '#f59e0b' },
  power: { label: 'Power', color: '#ef4444' },
  luminosity: { label: 'Light', color: '#fbbf24' },
  co2: { label: 'CO₂', color: '#6b7280' },
  sound: { label: 'Sound', color: '#a855f7' },
  battery: { label: 'Battery', color: '#22c55e' },
  rssi: { label: 'RSSI', color: '#06b6d4' },
}

/** Primary sensors to show as column groups */
const PRIMARY_SENSORS = ['temperature', 'humidity', 'pressure', 'voltage']

// =============================================================================
// SCHEMA IMPLEMENTATION
// =============================================================================

/**
 * SenML Column Schema
 *
 * Detects SenML payloads (arrays with n/bn fields) and generates
 * semantic column groups for primary sensors.
 */
export class SenMLColumnSchema<TData extends { payload?: unknown } = { payload?: unknown }>
  extends BaseColumnSchema<TData, SenMLPayload>
{
  constructor() {
    super({
      id: 'senml',
      name: 'SenML',
      description: 'RFC 8428 Sensor Measurement Lists - IoT sensor data format',
      color: '#22c55e',
      icon: '📡',
    })
  }

/**
   * Detect SenML payload: array with records containing n or bn fields
   */
  detect(payload: unknown): payload is SenMLPayload {
    if (!Array.isArray(payload) || payload.length === 0) return false
    const first = payload[0]
    if (typeof first !== 'object' || first === null) return false
    return 'n' in first || 'bn' in first
  }

  /**
   * Generate column groups for primary sensors
   */
  generateColumns(variant: GridVariantType): Array<ColDef<TData>> {
    return PRIMARY_SENSORS.map((sensorName) => {
      const semantic = SENSOR_SEMANTICS[sensorName] ?? {
        label: sensorName,
        color: variant.colors.text.secondary,
      }

return this.toColDefGroup(
        {
          headerName: semantic.label,
          headerClass: 'ag-header-group-sensor',
          marryChildren: true,
          children: [
            {
              headerName: 'Value',
              width: 70,
              suppressSizeToFit: true,
              valueGetter: (params: ValueGetterParams<TData>) => {
                const payload = params.data?.payload as SenMLPayload | undefined
                if (!Array.isArray(payload)) return null
                const record = payload.find((r) => r.n === sensorName)
                return record?.v
              },
              cellStyle: {
                color: semantic.color,
                fontFamily: 'monospace',
                fontVariantNumeric: 'tabular-nums',
                fontSize: variant.density.fontSize,
              },
              valueFormatter: (params) =>
                params.value !== null && params.value !== undefined
                  ? (params.value as number).toFixed(1)
                  : '—',
            },
            {
              headerName: 'Unit',
              width: 50,
              suppressSizeToFit: true,
              valueGetter: (params: ValueGetterParams<TData>) => {
                const payload = params.data?.payload as SenMLPayload | undefined
                if (!Array.isArray(payload)) return null
                const record = payload.find((r) => r.n === sensorName)
                return record?.u
              },
              cellStyle: {
                color: variant.colors.text.muted,
                fontSize: variant.density.fontSizeXs,
              },
            },
          ],
        },
        variant
      )
    })
  }

  /**
   * Compact payload renderer showing first sensor + count
   */
  getPayloadRenderer(variant: GridVariantType): React.ComponentType<ICellRendererParams<TData>> {
    return function SenMLRenderer(params: ICellRendererParams<TData>) {
      const payload = params.data?.payload as SenMLPayload | undefined
      if (!payload || !Array.isArray(payload) || payload.length === 0) return null

const first = payload[0]
      const name = first.n || '—'
      const value = first.v !== undefined ? first.v.toFixed(2) : '—'
      const unit = first.u || ''

      return (
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <span style={{ color: variant.colors.text.muted, fontSize: variant.density.fontSizeXs }}>
            {name}
          </span>
          <span
            style={{
              color: variant.colors.signal.accent,
              fontFamily: 'monospace',
              fontVariantNumeric: 'tabular-nums',
            }}
          >
            {value}
          </span>
          <span style={{ color: variant.colors.text.muted, fontSize: variant.density.fontSizeXs }}>
            {unit}
          </span>
          {payload.length > 1 && (
            <span
              style={{
                color: variant.colors.text.muted,
                fontSize: variant.density.fontSizeXs,
                opacity: 0.6,
              }}
            >
              +{payload.length - 1}
            </span>
          )}
        </div>
      )
    }
  }

  /**
   * Extract summary from SenML payload
   */
  getSummary(payload: SenMLPayload): PayloadSummary {
    const first = payload[0]
    return {
      label: first?.n || first?.bn || 'unknown',
      value: first?.v ?? first?.vs ?? '—',
      unit: first?.u,
      count: payload.length,
    }
  }
}

/** Default SenML schema instance */
export const senmlSchema = new SenMLColumnSchema()

/**
 * ColumnSchema Types
 *
 * Generic, extensible column definition system for AG-Grid.
 * Allows payload-specific schemas to generate semantic column definitions.
 *
 * @module
 */

import type { ColDef, ICellRendererParams, ValueGetterParams } from 'ag-grid-community'
import type { GridVariantType } from '../schemas'

// =============================================================================
// CORE TYPES
// =============================================================================

/**
 * Cell renderer configuration extracted from column schema.
 * Allows schemas to define renderers without direct React component coupling.
 */
export interface CellRendererConfig<TData = unknown> {
  /** Unique renderer ID for registry */
  id: string
  /** Display name for debugging */
  name: string
  /** Value extractor from cell params */
  getValue: (params: ICellRendererParams<TData>) => unknown
  /** Style generator (receives variant + value) */
  getStyle: (value: unknown, variant: GridVariantType) => React.CSSProperties
  /** Format value for display */
  formatValue: (value: unknown) => string | React.ReactNode
}

/**
 * Column group definition for semantic grouping.
 * E.g., "Sensor" group with "Value" and "Unit" children.
 */
export interface ColumnGroupConfig<TData = unknown> {
  /** Group header name */
  headerName: string
  /** Header CSS class */
  headerClass?: string
  /** Keep children together when resizing */
  marryChildren?: boolean
  /** Child column definitions */
  children: ColumnConfig<TData>[]
}

/**
 * Single column configuration.
 * Abstraction over AG-Grid ColDef with schema-aware defaults.
 */
export interface ColumnConfig<TData = unknown> {
  /** Column field (for direct field mapping) */
  field?: string
  /** Header display name */
  headerName: string
  /** Column width */
  width?: number
  /** Minimum width */
  minWidth?: number
  /** Prevent auto-sizing */
  suppressSizeToFit?: boolean
  /** Pin to left/right */
  pinned?: 'left' | 'right'
  /** Value getter (for computed values) */
  valueGetter?: (params: ValueGetterParams<TData>) => unknown
  /** Value formatter (for display) */
  valueFormatter?: (params: { value: unknown }) => string
  /** Cell renderer (React component or renderer config) */
  cellRenderer?: React.ComponentType<ICellRendererParams<TData>> | CellRendererConfig<TData>
  /** Cell style object or function */
  cellStyle?: React.CSSProperties | ((params: ICellRendererParams<TData>) => React.CSSProperties)
  /** Sortable */
  sortable?: boolean
  /** Resizable */
  resizable?: boolean
}

/**
 * Schema metadata for registration and introspection.
 */
export interface SchemaMetadata {
  /** Unique schema ID (e.g., 'senml', 'opcua', 'prometheus') */
  id: string
  /** Human-readable name */
  name: string
  /** Description of the payload format */
  description: string
  /** Brand color (hex) */
  color: string
  /** Icon (emoji or component) */
  icon?: string
}

// =============================================================================
// COLUMN SCHEMA INTERFACE
// =============================================================================

/**
 * Payload summary for quick display in compact views.
 */
export interface PayloadSummary {
  /** Primary label (e.g., sensor name, metric name) */
  label: string
  /** Primary value */
  value: string | number
  /** Unit if applicable */
  unit?: string
  /** Count of items (e.g., "5 sensors", "3 metrics") */
  count?: number
  /** Additional context */
  context?: string
}

// =============================================================================
// REGISTRY TYPES
// =============================================================================

/**
 * Schema registry configuration.
 */
export interface ColumnSchemaRegistryConfig {
  /** Default schema ID to use when no match found */
  defaultSchemaId?: string
  /** Enable debug logging */
  debug?: boolean
}

/**
 * Column schema registry interface.
 */
export interface ColumnSchemaRegistry {
  /**
   * Register a schema.
   * @param schema - Schema to register
   */
  register<TData, TPayload>(schema: ColumnSchema<TData, TPayload>): void

  /**
   * Get schema by ID.
   * @param id - Schema ID
   * @returns Schema or undefined
   */
  get<TData = unknown, TPayload = unknown>(id: string): ColumnSchema<TData, TPayload> | undefined

  /**
   * Detect schema from payload.
   * @param payload - Payload to analyze
   * @returns Matching schema or undefined
   */
  detect<TData = unknown>(payload: unknown): ColumnSchema<TData, unknown> | undefined

  /**
   * Get all registered schemas.
   * @returns Array of registered schemas
   */
  getAll(): ReadonlyArray<ColumnSchema<unknown, unknown>>

  /**
   * Get schema IDs.
   * @returns Array of schema IDs
   */
  getIds(): ReadonlyArray<string>
}

