    (event: RowDragEnterEvent) => {
      const rowData = event.node.data as GridRow
      const mouseEvent = event.event as MouseEvent
      const startPos: Point = { x: mouseEvent.clientX, y: mouseEvent.clientY }

      const effect = Effect.gen(function* () {
        const service = yield* GridDragService
        yield* service.dispatch(gridDragStart(rowData, gridId, startPos))
        return yield* service.getState
      })

      stateRef.current = runtime.runSync(effect)
    },
    [gridId, runtime]
  )

  // AG-Grid: Row drag moving
  const onRowDragMove = useCallback(
    (event: RowDragMoveEvent) => {
      const state = stateRef.current
      if (state.phase === DragPhaseEnum.Idle) return

      const mouseEvent = event.event as MouseEvent
      const currentPos: Point = { x: mouseEvent.clientX, y: mouseEvent.clientY }

      // Check if cursor is outside grid bounds
      const containerRect = containerRef.current?.getBoundingClientRect()
      if (!containerRect) return

      const isInside =
        currentPos.x >= containerRect.left &&
        currentPos.x <= containerRect.right &&
        currentPos.y >= containerRect.top &&
        currentPos.y <= containerRect.bottom

      const effect = Effect.gen(function* () {
        const service = yield* GridDragService
        yield* service.dispatch(gridDragMove(currentPos, isInside))
        const newState = yield* service.getState

const effect = Effect.gen(function* () {
        const service = yield* GridDragService
        yield* service.dispatch(gridDragMove(currentPos, isInside))
        const newState = yield* service.getState

        // Fire callback when exiting grid
        if (!isInside && state.phase === DragPhaseEnum.GridInternal && newState.rowData) {
          onGridExit?.(newState.rowData, currentPos)
        }

        return newState
      })

      stateRef.current = runtime.runSync(effect)
    },
    [containerRef, runtime, onGridExit]
  )

  // AG-Grid: Row drag ended (internal)
  const onRowDragEnd = useCallback(
    (event: RowDragEndEvent) => {
      const state = stateRef.current

      // If we're tracking on canvas, let pointer handlers handle cleanup
      if (state.phase === DragPhaseEnum.CanvasTracking) {
        return
      }

      // Internal drop - reset state
      const effect = Effect.gen(function* () {
        const service = yield* GridDragService
        yield* service.reset
        return yield* service.getState
      })

      stateRef.current = runtime.runSync(effect)
    },
    [runtime]
  )

  // AG-Grid: Row drag leave
  const onRowDragLeave = useCallback(
    (_event: RowDragLeaveEvent) => {
      // Handled by onRowDragMove boundary detection
    },
    []
  )

  // Cancel drag
  const cancelDrag = useCallback(() => {
    const effect = Effect.gen(function* () {
      const service = yield* GridDragService
      yield* service.dispatch(cancel('user-cancelled'))
      onCancel?.('user-cancelled')
      return yield* service.getState
    })

    stateRef.current = runtime.runSync(effect)
  }, [runtime, onCancel])

  // Complete drop
  const completeDrop = useCallback(
    (canvasPos: Point) => {
      const state = stateRef.current

      const effect = Effect.gen(function* () {
        const service = yield* GridDragService

// Complete drop
  const completeDrop = useCallback(
    (canvasPos: Point) => {
      const state = stateRef.current

      const effect = Effect.gen(function* () {
        const service = yield* GridDragService

        if (state.rowData) {
          yield* service.dispatch(drop(canvasPos, state.rowData))
          onDrop?.(state.rowData, canvasPos)
        }

        return yield* service.getState
      })

      stateRef.current = runtime.runSync(effect)
    },
    [runtime, onDrop]
  )

  // Keyboard handler for escape
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && stateRef.current.phase !== DragPhaseEnum.Idle) {
        cancelDrag()
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [cancelDrag])

  // Pointer handlers for canvas tracking
  useEffect(() => {
    const state = stateRef.current
    if (state.phase !== DragPhaseEnum.CanvasTracking) return

    const handlePointerMove = (e: PointerEvent) => {
      const screenPos: Point = { x: e.clientX, y: e.clientY }
      const canvasPos = screenToCanvas(screenPos)

      const effect = Effect.gen(function* () {
        const service = yield* GridDragService
        yield* service.dispatch(canvasMove(screenPos, canvasPos))
        return yield* service.getState
      })

      stateRef.current = runtime.runSync(effect)
    }

    const handlePointerUp = (e: PointerEvent) => {
      const screenPos: Point = { x: e.clientX, y: e.clientY }
      const canvasPos = screenToCanvas(screenPos)
      completeDrop(canvasPos)
    }

    window.addEventListener('pointermove', handlePointerMove)
    window.addEventListener('pointerup', handlePointerUp)

/**
 * useMockStream Hook
 *
 * React hook for consuming Effect-based mock data streams.
 * Handles fiber lifecycle and cleanup automatically.
 */

import { useEffect, useState, useRef, useCallback } from 'react'
import { Effect, Stream, Fiber, Runtime, Exit } from 'effect'
import {
  createMockDataStream,
  type StreamEvent,
  type StreamConfig,
  type MockRow,
  type RowUpdate,
  DEFAULT_STREAM_CONFIG,
} from '../mocking'

// =============================================================================
// TYPES
// =============================================================================

export interface UseMockStreamOptions extends Partial<StreamConfig> {
  /** Start streaming immediately on mount */
  autoStart?: boolean
}

export interface UseMockStreamResult {
  /** Current row data */
  rows: readonly MockRow[]
  /** Updates from last tick (for flash tracking) */
  lastUpdates: readonly RowUpdate[]
  /** Current tick number */
  tick: number
  /** Whether stream is running */
  isStreaming: boolean
  /** Start the stream */
  start: () => void
  /** Stop the stream */
  stop: () => void
  /** Toggle streaming state */
  toggle: () => void
  /** Update stream config (restarts stream) */
  setConfig: (config: Partial<StreamConfig>) => void
  /** Current config */
  config: StreamConfig
}

// =============================================================================
// HOOK
// =============================================================================

export function useMockStream(
  options: UseMockStreamOptions = {}
): UseMockStreamResult {
  const { autoStart = true, ...configOverrides } = options

  const [config, setConfigState] = useState<StreamConfig>({
    ...DEFAULT_STREAM_CONFIG,
    ...configOverrides,
  })

  const [rows, setRows] = useState<readonly MockRow[]>([])
  const [lastUpdates, setLastUpdates] = useState<readonly RowUpdate[]>([])
  const [tick, setTick] = useState(0)
  const [isStreaming, setIsStreaming] = useState(false)

  const fiberRef = useRef<Fiber.RuntimeFiber<void, never> | null>(null)
  const runtimeRef = useRef(Runtime.defaultRuntime)

const fiberRef = useRef<Fiber.RuntimeFiber<void, never> | null>(null)
  const runtimeRef = useRef(Runtime.defaultRuntime)

  const stopStream = useCallback(() => {
    if (fiberRef.current) {
      Effect.runFork(Fiber.interrupt(fiberRef.current))
      fiberRef.current = null
      setIsStreaming(false)
    }
  }, [])

  const startStream = useCallback(() => {
    // Stop existing stream first
    stopStream()

    const stream = createMockDataStream(config)

    const program = Stream.runForEach(stream, (event: StreamEvent) =>
      Effect.sync(() => {
        setRows(event.rows)
        setLastUpdates(event.updates)
        setTick(event.tick)
      })
    )

    const fiber = Runtime.runFork(runtimeRef.current)(program)
    fiberRef.current = fiber
    setIsStreaming(true)
  }, [config, stopStream])

  const toggle = useCallback(() => {
    if (isStreaming) {
      stopStream()
    } else {
      startStream()
    }
  }, [isStreaming, startStream, stopStream])

  const setConfig = useCallback((newConfig: Partial<StreamConfig>) => {
    setConfigState((prev) => ({ ...prev, ...newConfig }))
  }, [])

  // Auto-start on mount if enabled
  useEffect(() => {
    if (autoStart) {
      startStream()
    }

    return () => {
      stopStream()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- mount-only effect
  }, [])

  // Restart stream when config changes (if currently streaming)
  useEffect(() => {
    if (isStreaming) {
      startStream()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- config change triggers restart
  }, [config])

  return {
    rows,
    lastUpdates,
    tick,
    isStreaming,
    start: startStream,
    stop: stopStream,
    toggle,
    setConfig,
    config,
  }
}

