/**
 * GridDragService
 *
 * Effect-based service for managing grid drag operations.
 * Handles the hybrid drag model: AG-Grid internal → pointer events on canvas.
 *
 * @module
 */

import * as Effect from 'effect/Effect'
import * as Context from 'effect/Context'
import * as Layer from 'effect/Layer'
import * as SubscriptionRef from 'effect/SubscriptionRef'
import type {
  DragState,
  GridDragEvent,
  GridRow,
  Point,
  GridDragStart,
  GridDragMove,
  GridExit,
  CanvasEnter,
  CanvasMove,
  Drop,
  Cancel,
} from '../types'
import { INITIAL_DRAG_STATE, DragPhaseEnum } from '../types'

// =============================================================================
// SERVICE INTERFACE
// =============================================================================

export interface GridDragServiceApi {
  /** Get current drag state */
  readonly getState: Effect.Effect<DragState>

  /** Dispatch a drag event (updates state based on event) */
  readonly dispatch: (event: GridDragEvent) => Effect.Effect<void>

  /** Subscribe to state changes */
  readonly subscribe: (
    handler: (state: DragState) => void
  ) => Effect.Effect<() => void>

  /** Reset to idle state */
  readonly reset: Effect.Effect<void>

  /** Check if currently dragging */
  readonly isDragging: Effect.Effect<boolean>

  /** Get the current phase */
  readonly getPhase: Effect.Effect<DragState['phase']>
}

// =============================================================================
// SERVICE TAG
// =============================================================================

export class GridDragService extends Context.Tag('tmnl/data-grid/GridDragService')<
  GridDragService,
  GridDragServiceApi
>() {}

// =============================================================================
// STATE REDUCER
// =============================================================================

export class GridDragService extends Context.Tag('tmnl/data-grid/GridDragService')<
  GridDragService,
  GridDragServiceApi
>() {}

// =============================================================================
// STATE REDUCER
// =============================================================================

/**
 * Handle a drag event and produce the next state.
 */
const handleEvent = (state: DragState, event: GridDragEvent): DragState => {
  switch (event._tag) {
    case 'GridDragStart':
      return {
        ...state,
        phase: DragPhaseEnum.GridInternal,
        rowData: event.rowData,
        gridId: event.gridId,
        startPos: event.startPos,
        currentPos: event.startPos,
      }

    case 'GridDragMove':
      return {
        ...state,
        currentPos: event.currentPos,
        // Transition to transitioning when exiting grid
        phase: event.isInsideGrid
          ? DragPhaseEnum.GridInternal
          : DragPhaseEnum.Transitioning,
      }

    case 'GridExit':
      return {
        ...state,
        phase: DragPhaseEnum.Transitioning,
        currentPos: event.exitPos,
      }

    case 'CanvasEnter':
      return {
        ...state,
        phase: DragPhaseEnum.CanvasTracking,
        ghostShapeId: event.ghostShapeId,
        currentPos: event.canvasPos,
      }

    case 'CanvasMove':
      return {
        ...state,
        currentPos: event.canvasPos,
      }

    case 'Drop':
      // Reset state after successful drop
      return INITIAL_DRAG_STATE

    case 'Cancel':
      // Reset state on cancel
      return INITIAL_DRAG_STATE

    default:
      return state
  }
}

// =============================================================================
// SERVICE IMPLEMENTATION
// =============================================================================

const makeGridDragService = Effect.gen(function* () {
  // SubscriptionRef allows subscribing to state changes
  const stateRef = yield* SubscriptionRef.make(INITIAL_DRAG_STATE)

  return GridDragService.of({
    getState: SubscriptionRef.get(stateRef),

return GridDragService.of({
    getState: SubscriptionRef.get(stateRef),

    dispatch: (event: GridDragEvent) =>
      Effect.gen(function* () {
        const currentState = yield* SubscriptionRef.get(stateRef)
        const nextState = handleEvent(currentState, event)

        // Log state transition for observability
        yield* Effect.logDebug(
          `[GridDrag] ${event._tag}: ${currentState.phase} → ${nextState.phase}`
        )

        yield* SubscriptionRef.set(stateRef, nextState)
      }),

    subscribe: (handler: (state: DragState) => void) =>
      Effect.gen(function* () {
        // Get the subscription stream
        const changes = yield* SubscriptionRef.changes(stateRef)

        // Create a fiber that runs the handler on each change
        const fiber = yield* Effect.fork(
          Effect.forEach(changes, (state) =>
            Effect.sync(() => handler(state))
          )
        )

        // Return unsubscribe function
        return () => {
          Effect.runFork(Effect.interruptWith(fiber, fiber.id()))
        }
      }),

    reset: SubscriptionRef.set(stateRef, INITIAL_DRAG_STATE),

    isDragging: Effect.gen(function* () {
      const state = yield* SubscriptionRef.get(stateRef)
      return state.phase !== DragPhaseEnum.Idle
    }),

    getPhase: Effect.gen(function* () {
      const state = yield* SubscriptionRef.get(stateRef)
      return state.phase
    }),
  })
})

// =============================================================================
// SERVICE LAYER
// =============================================================================

export const GridDragServiceLive = Layer.effect(GridDragService, makeGridDragService)

// =============================================================================
// EVENT CONSTRUCTORS
// =============================================================================

/** Create a GridDragStart event */
export const gridDragStart = (
  rowData: GridRow,
  gridId: string,
  startPos: Point
): GridDragStart => ({
  _tag: 'GridDragStart',
  rowData,
  gridId,
  startPos,
})

/** Create a GridDragMove event */
export const gridDragMove = (
  currentPos: Point,
  isInsideGrid: boolean
): GridDragMove => ({
  _tag: 'GridDragMove',
  currentPos,
  isInsideGrid,
})

/** Create a GridExit event */
export const gridExit = (exitPos: Point, rowData: GridRow): GridExit => ({
  _tag: 'GridExit',
  exitPos,
  rowData,
})

/** Create a CanvasEnter event */
export const canvasEnter = (
  canvasPos: Point,
  ghostShapeId: string
): CanvasEnter => ({
  _tag: 'CanvasEnter',
  canvasPos,
  ghostShapeId,
})

/** Create a CanvasMove event */
export const canvasMove = (screenPos: Point, canvasPos: Point): CanvasMove => ({
  _tag: 'CanvasMove',
  screenPos,
  canvasPos,
})

/** Create a Drop event */
export const drop = (canvasPos: Point, rowData: GridRow): Drop => ({
  _tag: 'Drop',
  canvasPos,
  rowData,
})

/** Create a Cancel event */
export const cancel = (reason: string): Cancel => ({
  _tag: 'Cancel',
  reason,
})

/**
 * Direct Theme Builder
 *
 * Creates AG-Grid themes directly from tokens.
 * Use this for cases that bypass the variant system.
 *
 * PREFER: composeAgGridTheme(variant) for most use cases.
 * USE THIS: For animation overlays, testing, or standalone grids.
 *
 * @module
 */

import { themeQuartz } from 'ag-grid-community'
import { TMNL_TOKENS, COLORS, TYPOGRAPHY, DIMENSIONS, SPACING } from './tokens'

// =============================================================================
// DIRECT THEME BUILDER
// =============================================================================

/**
 * Create an AG-Grid theme directly from tokens.
 *
 * @param overrides - Optional color overrides for animation
 * @returns AG-Grid theme
 *
 * @example
 * ```tsx
 * // Default theme
 * const theme = createDirectTheme()
 *
 * // With animation overlay (color shift)
 * const animatedTheme = createDirectTheme({
 *   accentPrimary: '#ff0000',
 * })
 * ```
 */
export function createDirectTheme(
  overrides: Partial<typeof COLORS> = {}
) {
  const colors = { ...COLORS, ...overrides }

  return themeQuartz.withParams({
    // Core colors
    backgroundColor: colors.backgroundPrimary,
    foregroundColor: colors.textPrimary,
    accentColor: colors.accentPrimary,

    // Chrome (headers, panels)
    chromeBackgroundColor: colors.backgroundTertiary,

    // Borders
    borderColor: colors.borderDefault,
    borderRadius: DIMENSIONS.borderRadius,
    wrapperBorder: false,
    wrapperBorderRadius: 0,

    // Typography
    fontFamily: TYPOGRAPHY.fontFamily,
    fontSize: TYPOGRAPHY.fontSizeMd,

// Typography
    fontFamily: TYPOGRAPHY.fontFamily,
    fontSize: TYPOGRAPHY.fontSizeMd,

    // Header styling
    headerBackgroundColor: colors.backgroundTertiary,
    headerTextColor: colors.textMuted,
    headerFontSize: TYPOGRAPHY.fontSizeXs,
    headerFontWeight: 600,
    headerHeight: DIMENSIONS.headerHeightNormal,
    headerVerticalPaddingScale: SPACING.headerPadding,
    headerRowBorder: { color: colors.borderDefault },
    headerColumnBorder: false,
    headerColumnResizeHandleColor: colors.borderSubtle,
    headerCellHoverBackgroundColor: colors.backgroundHover,

    // Cell styling
    cellTextColor: colors.textSecondary,
    cellHorizontalPaddingScale: SPACING.cellPadding,

    // Row styling
    rowHeight: DIMENSIONS.rowHeightNormal,
    rowVerticalPaddingScale: SPACING.rowPadding,
    rowBorder: { color: colors.borderMuted },
    oddRowBackgroundColor: colors.backgroundSecondary,
    rowHoverColor: colors.backgroundHover,
    selectedRowBackgroundColor: colors.backgroundSelected,

    // Range selection
    rangeSelectionBackgroundColor: colors.rangeBackground,
    rangeSelectionBorderColor: colors.rangeBorder,
    rangeSelectionBorderStyle: 'solid',

    // Column borders
    columnBorder: { color: colors.borderMuted },

    // Icons
    iconSize: DIMENSIONS.iconSize,

    // Spacing
    spacing: SPACING.unit,

    // Focus & interaction
    focusShadow: 'none',

    // Color scheme
    browserColorScheme: 'dark',

    // Cell editing
    cellEditingBorder: { color: colors.accentCyan },

    // Menu
    menuBackgroundColor: colors.backgroundTertiary,
    menuBorder: { color: colors.borderDefault },
    menuTextColor: colors.textSecondary,
  })
}

