// ─────────────────────────────────────────────────────────────────────────────
// DataManager Service
// ─────────────────────────────────────────────────────────────────────────────

/**
 * DataManager Service - Top-level data orchestrator
 *
 * Pattern: Effect.Service<>() with Effect.Ref for state
 *
 * @template T - Item type being managed
 */
export class DataManager<T = unknown> extends Effect.Service<DataManager<T>>()("tmnl/data-manager/DataManager", {
  effect: Effect.gen(function* () {
    // ─────────────────────────────────────────────────────────────────────────
    // Canonical State (Effect.Ref)
    // ─────────────────────────────────────────────────────────────────────────

    const stateRef = yield* Ref.make<DataManagerState<T>>(initialState<T>())

    // Search results (streaming, progressive)
    const resultsRef = yield* Ref.make<readonly SearchResult<T>[]>([])

    // Stream status
    const statusRef = yield* Ref.make<StreamStatus>("idle")

    // Stream stats
    const statsRef = yield* Ref.make<StreamStats>({ chunks: 0, items: 0, ms: 0 })

    // ─────────────────────────────────────────────────────────────────────────
    // Kernel Management
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Register a kernel
     */
    const registerKernel = (kernel: Kernel<unknown, unknown>): Effect.Effect<void> =>
      Ref.update(stateRef, (state) => ({
        ...state,
        kernels: new Map(state.kernels).set(kernel.type, kernel),
      }))

    /**
     * Get kernel by type
     */
    const getKernel = (type: KernelType): Effect.Effect<Kernel<unknown, unknown> | undefined> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        return state.kernels.get(type)
      })

    // ─────────────────────────────────────────────────────────────────────────
    // Dispatch Operations (Effect.fn pattern for tracing)
    // ─────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────
    // Dispatch Operations (Effect.fn pattern for tracing)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Dispatch task to kernel (traced, fiber)
     *
     * Use for: service methods, lifecycle ops, error paths
     */
    const dispatch = <R>(
      kernelType: KernelType,
      task: Task<R>
    ): Effect.Effect<KernelResult<R>> =>
      Effect.gen(function* () {
        const kernel = yield* getKernel(kernelType)

        if (!kernel) {
          return yield* Effect.fail(new Error(`Kernel not found: ${kernelType}`))
        }

        // Update queued count
        yield* Ref.update(stateRef, (s) => ({
          ...s,
          tasksQueued: s.tasksQueued + 1,
        }))

        // Execute with tracing
        const result = yield* kernel.execute(task as Task<unknown, unknown>) as Effect.Effect<KernelResult<R>>

        // Update completed stats
        yield* Ref.update(stateRef, (s) => ({
          ...s,
          tasksQueued: s.tasksQueued - 1,
          tasksCompleted: s.tasksCompleted + 1,
          totalDurationMs: s.totalDurationMs + result.durationMs,
        }))

        return result
      }).pipe(Effect.withSpan(`DataManager.dispatch.${kernelType}`))

    /**
     * Dispatch task (untraced, hot path)
     *
     * Use for: search execution, stream processing
     */
    const dispatchHot = <R>(
      kernelType: KernelType,
      task: Task<R>
    ): Effect.Effect<KernelResult<R>> =>
      Effect.gen(function* () {
        const kernel = yield* getKernel(kernelType)

        if (!kernel) {
          return yield* Effect.fail(new Error(`Kernel not found: ${kernelType}`))
        }

if (!kernel) {
          return yield* Effect.fail(new Error(`Kernel not found: ${kernelType}`))
        }

        // Execute without tracing (hot path)
        const result = yield* kernel.executeHot(task as Task<unknown, unknown>) as Effect.Effect<KernelResult<R>>

        // Update stats atomically (no tracing overhead)
        yield* Ref.update(stateRef, (s) => ({
          ...s,
          tasksCompleted: s.tasksCompleted + 1,
          totalDurationMs: s.totalDurationMs + result.durationMs,
        }))

        return result
      })

    /**
     * Dispatch to Web Worker (CPU-heavy operations)
     *
     * Use for: indexing 36K movies, batch transforms
     */
    const dispatchInWorker = <R>(
      kernelType: KernelType,
      task: Task<R>
    ): Effect.Effect<KernelResult<R>> =>
      Effect.gen(function* () {
        const kernel = yield* getKernel(kernelType)

        if (!kernel) {
          return yield* Effect.fail(new Error(`Kernel not found: ${kernelType}`))
        }

        // Update queued count
        yield* Ref.update(stateRef, (s) => ({
          ...s,
          tasksQueued: s.tasksQueued + 1,
        }))

        // Execute in worker
        const result = yield* kernel.executeInWorker(task as Task<unknown, unknown>) as Effect.Effect<KernelResult<R>>

        // Update completed stats
        yield* Ref.update(stateRef, (s) => ({
          ...s,
          tasksQueued: s.tasksQueued - 1,
          tasksCompleted: s.tasksCompleted + 1,
          totalDurationMs: s.totalDurationMs + result.durationMs,
        }))

        return result
      }).pipe(Effect.withSpan(`DataManager.dispatchInWorker.${kernelType}`))

    // ─────────────────────────────────────────────────────────────────────────
    // Search Operations
    // ─────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────
    // Search Operations
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Search with progressive streaming
     *
     * Updates atoms as stream progresses for reactive UI
     */
    const search = (query: SearchQuery): Stream.Stream<SearchResult<T>> =>
      Stream.unwrap(
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)
          const driver = state.drivers.active === "flex"
            ? state.drivers.flex
            : state.drivers.linear

          if (!driver) {
            return Stream.fail(new Error("No search driver available"))
          }

          // Reset state for new search
          yield* Ref.set(resultsRef, [])
          yield* Ref.set(statusRef, "streaming")
          yield* Ref.set(statsRef, { chunks: 0, items: 0, ms: 0 })
          yield* Ref.update(stateRef, (s) => ({ ...s, currentQuery: query.query }))

          const startTime = Date.now()

          // Create progressive stream with atom updates
          return driver.search(query).pipe(
            Stream.tap((result) =>
              Effect.gen(function* () {
                yield* Ref.update(resultsRef, (results) => [...results, result as SearchResult<T>])
                yield* Ref.update(statsRef, (stats) => ({
                  ...stats,
                  items: stats.items + 1,
                  ms: Date.now() - startTime,
                }))
              })
            ),
            Stream.onDone(() =>
              Effect.gen(function* () {
                yield* Ref.set(statusRef, "complete")
                yield* Ref.update(statsRef, (stats) => ({
                  ...stats,
                  ms: Date.now() - startTime,
                  throughput: stats.items / ((Date.now() - startTime) / 1000),
                }))
              })
            )
          ) as Stream.Stream<SearchResult<T>>
        })
      )

/**
     * Index items
     */
    const index = (
      items: readonly T[],
      fields: readonly string[]
    ): Effect.Effect<void> =>
      Effect.gen(function* () {
        yield* Ref.update(stateRef, (s) => ({ ...s, isIndexing: true }))

        // Dispatch to index kernel (via worker for CPU-heavy ops)
        yield* dispatchInWorker("index", {
          id: `index-${Date.now()}`,
          type: "index",
          payload: { items, fields },
          priority: "normal",
        })

        yield* Ref.update(stateRef, (s) => ({ ...s, isIndexing: false }))
      }).pipe(Effect.withSpan("DataManager.index"))

    // ─────────────────────────────────────────────────────────────────────────
    // Stats & Admin
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Get service stats
     */
    const getStats = (): Effect.Effect<DataManagerStats> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)

        return {
          kernelsActive: state.kernels.size,
          tasksQueued: state.tasksQueued,
          tasksCompleted: state.tasksCompleted,
          avgDurationMs: state.tasksCompleted > 0
            ? state.totalDurationMs / state.tasksCompleted
            : 0,
          workerPoolSize: 0, // TODO: Wire to actual worker pool
        }
      })

    // ─────────────────────────────────────────────────────────────────────────
    // Service-Scoped Atoms
    // ─────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────
    // Service-Scoped Atoms
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Create atoms tied to this service instance
     *
     * Lifecycle: created here, disposed when service is disposed
     */
    const atoms: DataManagerAtoms<T> = {
      results: Atom.make<readonly SearchResult<T>[]>([]),
      status: Atom.make<StreamStatus>("idle"),
      stats: Atom.make<StreamStats>({ chunks: 0, items: 0, ms: 0 }),
      drivers: Atom.make<DriverState<T>>({
        flex: null,
        linear: null,
        active: "flex",
      }),
      isIndexing: Atom.make<boolean>(false),
      query: Atom.make<string>(""),
      searchResult: Atom.make<Result.Result<readonly SearchResult<T>[], Error>>(
        Result.initial()
      ),
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Return Service Interface
    // ─────────────────────────────────────────────────────────────────────────

    return {
      // Kernel management (internal)
      registerKernel,
      getKernel,

      // Dispatch operations
      dispatch,
      dispatchHot,
      dispatchInWorker,

      // Search operations
      search,
      index,

      // Stats
      getStats,

      // Service-scoped atoms
      atoms,
    } as const satisfies DataManagerOps<T> & {
      registerKernel: typeof registerKernel
      getKernel: typeof getKernel
    }
  }),
}) {}

// ─────────────────────────────────────────────────────────────────────────────
// Layer Export
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Default DataManager layer
 *
 * Usage:
 * ```ts
 * const program = Effect.gen(function*() {
 *   const dm = yield* DataManager
 *   const results = yield* dm.dispatch("search", task)
 * })
 *
 * Effect.runPromise(program.pipe(Effect.provide(DataManager.Default)))
 * ```
 */
export const DataManagerLive = DataManager.Default

/**
 * TMNL DataManager v1 - Atoms (Materialized Views)
 *
 * These atoms represent the **materialized views** that DataManager publishes.
 * Components subscribe to these atoms; DataManager updates them during operations.
 *
 * Pattern:
 * - Atoms declared at module level (singleton, writable)
 * - Operation atoms use FnContext.set() to publish updates
 * - Components call useAtomValue() to subscribe
 * - Multiple components share the same view (same atom)
 *
 * Key insight: Inside runtimeAtom.fn((arg, get) => ...), the `get` parameter
 * is a FnContext with a `set` method: get.set(atom, value)
 *
 * @experimental v1 API may change. v2 when stable.
 */

import { Atom } from '@effect-atom/atom-react';
import * as Layer from 'effect/Layer';
import * as Effect from 'effect/Effect';
import * as Stream from 'effect/Stream';

import { SearchKernel } from '../kernels';
import type {
  SearchResult,
  SearchQuery,
  StreamStatus,
  StreamStats,
  DriverState,
} from '../types';

// ─────────────────────────────────────────────────────────────────────────────
// Materialized View Atoms (Module-Level Singletons)
// Must be Writable for FnContext.set() to work
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Search Results Atom
 *
 * Progressive search results from active stream.
 * Updated by searchOps.search as stream emits chunks.
 */
export const resultsAtom = Atom.make<readonly SearchResult<unknown>[]>([]);

/**
 * Stream Status Atom
 *
 * Current status: idle | streaming | complete | cancelled | error
 */
// PATTERN:PRIMITIVE_ATOM
export const statusAtom = Atom.make<StreamStatus>('idle');

/**
 * Stream Stats Atom
 *
 * Metrics: chunks processed, items received, duration in ms
 */
export const statsAtom = Atom.make<StreamStats>({ chunks: 0, items: 0, ms: 0 });

/**
 * Stream Stats Atom
 *
 * Metrics: chunks processed, items received, duration in ms
 */
export const statsAtom = Atom.make<StreamStats>({ chunks: 0, items: 0, ms: 0 });

/**
 * Drivers Atom
 *
 * Current driver state: flex/linear instances and active selection
 */
export const driversAtom = Atom.make<DriverState<unknown>>({
  flex: null,
  linear: null,
  active: 'flex',
});

/**
 * Is Indexing Atom
 *
 * True when index operation is in progress
 */
export const isIndexingAtom = Atom.make<boolean>(false);

/**
 * Current Query Atom
 *
 * The active search query string
 */
export const queryAtom = Atom.make<string>('');

// ─────────────────────────────────────────────────────────────────────────────
// Derived Atoms (Computed from Materialized Views)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Is Searching Atom
 *
 * Derived from status: true when streaming
 */
export const isSearchingAtom = Atom.make((get) => {
  const status = get(statusAtom);
  return status === 'streaming';
});

/**
 * Has Results Atom
 *
 * Derived from results: true when results exist
 */
export const hasResultsAtom = Atom.make((get) => {
  const results = get(resultsAtom);
  return results.length > 0;
});

/**
 * Result Count Atom
 *
 * Derived from results: current result count
 */
export const resultCountAtom = Atom.make((get) => {
  const results = get(resultsAtom);
  return results.length;
});

/**
 * Throughput Atom
 *
 * Derived from stats: items per second
 */
export const throughputAtom = Atom.make((get) => {
  const stats = get(statsAtom);
  if (stats.ms > 0) {
    return (stats.items / stats.ms) * 1000; // items per second
  }
  return 0;
});

// ─────────────────────────────────────────────────────────────────────────────
// Runtime Atom (For Effect Operations)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * DataManager Runtime Atom
 *
 * Provides Effect runtime for operations that need SearchKernel.
 * Used by operation atoms (searchOps, indexOps) to execute Effects.
 */
export const dataManagerRuntimeAtom = Atom.runtime(SearchKernel.Default);

// ─────────────────────────────────────────────────────────────────────────────
// Operation Atoms (Mutations via Effect)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Search Operations
 *
 * Mutation atoms for triggering search operations.
 * These update the materialized view atoms via FnContext.set()
 */
export const searchOps = {
  /**
   * Execute search and update materialized views
   *
   * Flow:
   * 1. Reset atoms (results=[], status=streaming)
   * 2. Execute search via SearchKernel
   * 3. Update resultsAtom with collected results
   * 4. Set status=complete when done
   *
   * Key: Use `ctx.set(atom, value)` to update materialized views
   */
  search: dataManagerRuntimeAtom.fn<SearchQuery>()((query, ctx) =>
    Effect.gen(function* () {
      console.log('[DataManager.search] Starting search', {
        query: query.query,
        limit: query.limit,
      });

      // Reset materialized views via FnContext.set()
      ctx.set(resultsAtom, []);
      ctx.set(statusAtom, 'streaming');
      ctx.set(statsAtom, { chunks: 0, items: 0, ms: 0 });
      ctx.set(queryAtom, query.query);

      const startTime = Date.now();
      const kernel = yield* SearchKernel;
      console.log('[DataManager.search] Got kernel instance');

const startTime = Date.now();
      const kernel = yield* SearchKernel;
      console.log('[DataManager.search] Got kernel instance');

      // Get driver instance for searching
      const driver = yield* kernel.getDriverInstance();
      console.log('[DataManager.search] Driver check:', {
        hasDriver: driver !== null,
        driverType: driver?.type,
        itemCount: driver?.itemCount,
      });

      if (!driver) {
        console.error(
          '[DataManager.search] No driver available - was data indexed?'
        );
        ctx.set(statusAtom, 'error');
        return yield* Effect.fail(
          new Error('No search driver available. Index data first.')
        );
      }

      // Collect all results from stream
      const allResults: SearchResult<unknown>[] = [];

      yield* Stream.runForEach(driver.search(query), (result) =>
        Effect.sync(() => {
          allResults.push(result as SearchResult<unknown>);

          // Progressive update every 50 results
          if (allResults.length % 50 === 0) {
            console.log(
              '[DataManager.search] Progressive update:',
              allResults.length,
              'results'
            );
            ctx.set(resultsAtom, [...allResults]);
            ctx.set(statsAtom, {
              chunks: Math.ceil(allResults.length / 50),
              items: allResults.length,
              ms: Date.now() - startTime,
            });
          }
        })
      );

      // Final update
      const finalMs = Date.now() - startTime;
      console.log('[DataManager.search] Complete:', {
        resultCount: allResults.length,
        durationMs: finalMs,
      });

      ctx.set(resultsAtom, allResults);
      ctx.set(statusAtom, 'complete');
      ctx.set(statsAtom, {
        chunks: Math.ceil(allResults.length / 50),
        items: allResults.length,
        ms: finalMs,
      });

return allResults;
    }).pipe(
      Effect.tapError((error) =>
        Effect.sync(() => {
          console.error('[DataManager.search] Error:', error);
          ctx.set(statusAtom, 'error');
        })
      )
    )
  ),

  /**
   * Set active driver (flex or linear)
   */
  setDriver: dataManagerRuntimeAtom.fn<'flex' | 'linear'>()((driver, ctx) =>
    Effect.gen(function* () {
      const kernel = yield* SearchKernel;
      yield* kernel.setActiveDriver(driver);
      ctx.set(driversAtom, { flex: null, linear: null, active: driver });
    })
  ),
};

/**
 * Index Operations
 *
 * Mutation atoms for indexing operations.
 */
export const indexOps = {
  /**
   * Index items into search drivers
   *
   * Updates isIndexingAtom during operation.
   * Returns: { indexed: boolean, itemCount: number }
   */
  index: dataManagerRuntimeAtom.fn<{
    items: readonly unknown[];
    fields: readonly string[];
  }>()(({ items, fields }, ctx) =>
    Effect.gen(function* () {
      console.log('[DataManager.index] Starting index operation', {
        itemCount: items.length,
        fields,
      });
      ctx.set(isIndexingAtom, true);

      const kernel = yield* SearchKernel;
      console.log('[DataManager.index] Got kernel instance');

      yield* kernel.index(items, {
        fields: fields as string[],
        getId: (item: unknown) => String((item as { id: unknown }).id),
      });

      console.log('[DataManager.index] Index complete, verifying driver...');

      // Verify indexing worked by checking driver instance
      const driver = yield* kernel.getDriverInstance();
      const success = driver !== null;

      console.log('[DataManager.index] Driver check:', {
        success,
        driverType: driver?.type,
        itemCount: driver?.itemCount,
      });

      ctx.set(isIndexingAtom, false);

console.log('[DataManager.index] Driver check:', {
        success,
        driverType: driver?.type,
        itemCount: driver?.itemCount,
      });

      ctx.set(isIndexingAtom, false);

      return { indexed: success, itemCount: driver?.itemCount ?? 0 };
    }).pipe(
      Effect.tapError((error) =>
        Effect.sync(() => {
          console.error('[DataManager.index] Error:', error);
          ctx.set(isIndexingAtom, false);
        })
      )
    )
  ),
};

