 * Effect.runPromise(program.pipe(Effect.provide(KernelRegistry.Default)))
 * ```
 */
export class KernelRegistry extends Effect.Service<KernelRegistry>()(
  "tmnl/data-manager/KernelRegistry",
  {
    effect: createKernelRegistry(),
  }
) {}

