/**
 * TMNL DataManager v1 - Namespace Types
 *
 * Type definitions for kernel namespacing, enabling reusable atom shapes
 * across different kernel types (search, senml, websocket, etc.)
 *
 * @experimental v1 API - additive extension to existing v1
 */

import type { Stream } from "effect"
import type { Atom } from "@effect-atom/atom"

// ─────────────────────────────────────────────────────────────────────────────
// Namespace Key
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Namespace key format: `${kernelType}:${instanceName}`
 *
 * Examples:
 * - "search:movies" - SearchKernel for movie data
 * - "search:users" - SearchKernel for user data
 * - "senml:telemetry" - SenML kernel for IoT telemetry
 * - "websocket:trading" - WebSocket kernel for trading data
 */
export type NamespaceKey = `${KernelType}:${string}`

/**
 * Kernel type discriminator (extensible)
 */
export type KernelType = "search" | "senml" | "websocket" | "transform"

/**
 * Parse namespace key into components
 */
export interface NamespaceParts {
  readonly type: KernelType
  readonly instance: string
}

// ─────────────────────────────────────────────────────────────────────────────
// Common Atom Shape
// ─────────────────────────────────────────────────────────────────────────────

/**
 * StreamStatus - universal across all streaming kernels
 */
export type StreamStatus = "idle" | "streaming" | "complete" | "cancelled" | "error"

/**
 * StreamStats - universal metrics for any stream
 */
export interface StreamStats {
  readonly chunks: number
  readonly items: number
  readonly ms: number
  readonly throughput?: number
}

/**
 * Generic result with score (search, relevance, confidence)
 */
export interface ScoredResult<T> {
  readonly item: T
  readonly score: number
  readonly metadata?: Record<string, unknown>
}

/**
 * Generic result with score (search, relevance, confidence)
 */
export interface ScoredResult<T> {
  readonly item: T
  readonly score: number
  readonly metadata?: Record<string, unknown>
}

/**
 * NamespaceAtoms - the common atom shape all kernels publish
 *
 * This is the "materialized view" contract that any kernel can fulfill.
 * Different kernel types may interpret these differently:
 *
 * - SearchKernel: results = search hits, score = relevance
 * - SenMLKernel: results = sensor readings, score = confidence
 * - WebSocketKernel: results = messages, score = priority
 *
 * @template T - Item type in the stream
 */
export interface NamespaceAtoms<T = unknown> {
  /** Progressive results from stream */
  readonly results: Atom.Atom<readonly ScoredResult<T>[]>

  /** Current stream status */
  readonly status: Atom.Atom<StreamStatus>

  /** Stream statistics */
  readonly stats: Atom.Atom<StreamStats>

  /** Current query/filter string */
  readonly query: Atom.Atom<string>

  /** Operation in progress (indexing, connecting, etc.) */
  readonly isProcessing: Atom.Atom<boolean>

  /** Last error if status === "error" */
  readonly lastError: Atom.Atom<Error | null>
}

// ─────────────────────────────────────────────────────────────────────────────
// Kernel Shape Interface
// ─────────────────────────────────────────────────────────────────────────────

/**
 * KernelShape - what a kernel instance provides
 *
 * Every kernel implements this interface plus kernel-specific extensions.
 * The atoms are created via the namespace family, ensuring proper scoping.
 *
 * @template T - Item type
 * @template Q - Query type (SearchQuery, SenMLFilter, etc.)
 */
export interface KernelShape<T = unknown, Q = unknown> {
  /** Kernel type identifier */
  readonly type: KernelType

  /** Instance name within the type namespace */
  readonly instance: string

  /** Full namespace key */
  readonly namespaceKey: NamespaceKey

/** Instance name within the type namespace */
  readonly instance: string

  /** Full namespace key */
  readonly namespaceKey: NamespaceKey

  /** Stream data matching query */
  readonly stream: (query: Q) => Stream.Stream<ScoredResult<T>>

  /** Atoms for this namespace (from family) */
  readonly atoms: NamespaceAtoms<T>
}

// ─────────────────────────────────────────────────────────────────────────────
// Kernel Config
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Base config for creating kernel instances
 */
export interface KernelConfig {
  /** Instance name (unique within kernel type) */
  readonly instance: string

  /** Optional: pre-warm the kernel on creation */
  readonly warmUp?: boolean

  /** Optional: dispose atoms when kernel is released */
  readonly autoDispose?: boolean
}

/**
 * SearchKernel specific config
 */
export interface SearchKernelConfig extends KernelConfig {
  readonly driver?: "flex" | "linear"
  readonly fields?: readonly string[]
}

/**
 * SenML kernel config (future)
 */
export interface SenMLKernelConfig extends KernelConfig {
  readonly endpoint: string
  readonly protocol?: "websocket" | "webtransport"
  readonly bufferSize?: number
}

/** Whether the kernel is initialized */
  readonly isReady: boolean

  /** Atom accessors for this namespace */
  readonly atoms: NamespaceAtoms<T>

  /** Derived atoms (computed) */
  readonly derived: {
    readonly isStreaming: Atom.Atom<boolean>
    readonly hasResults: Atom.Atom<boolean>
    readonly resultCount: Atom.Atom<number>
    readonly throughput: Atom.Atom<number>
  }
}

/**
 * Search kernel hook return
 */
export interface UseSearchKernel<T extends Indexable> extends UseKernelBase<T> {
  /** Index items into the kernel */
  readonly index: (items: readonly T[], config: IndexConfig<T>) => Promise<void>

  /** Execute search (updates atoms automatically) */
  readonly search: (query: SearchQuery) => Promise<readonly SearchResult<T>[]>

  /** Set active driver */
  readonly setDriver: (driver: "flex" | "linear") => Promise<void>

  /** The underlying kernel instance (for advanced use) */
  readonly kernel: SearchKernelInstance<T> | null
}

// ─────────────────────────────────────────────────────────────────────────────
// useKernel Hook (Generic)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Generic kernel hook - returns atoms only (no operations)
 *
 * Use when you only need to read kernel state, not trigger operations.
 *
 * @param type - Kernel type ("search", "senml", etc.)
 * @param instance - Instance name within type namespace
 */
export function useKernelAtoms<T = unknown>(
  type: KernelType,
  instance: string
): UseKernelBase<T> {
  const namespaceKey = useMemo(
    () => makeNamespaceKey(type, instance),
    [type, instance]
  )

  const atoms = useMemo(
    () => getNamespaceAtoms<T>(namespaceKey),
    [namespaceKey]
  )

  const derived = useMemo(
    () => getNamespaceDerivedAtoms(namespaceKey),
    [namespaceKey]
  )

const atoms = useMemo(
    () => getNamespaceAtoms<T>(namespaceKey),
    [namespaceKey]
  )

  const derived = useMemo(
    () => getNamespaceDerivedAtoms(namespaceKey),
    [namespaceKey]
  )

  // Check if kernel exists by reading status
  const status = useAtomValue(atoms.status)
  const isReady = status !== "idle" || Atom.get(atoms.isProcessing)

  return {
    namespaceKey,
    isReady,
    atoms,
    derived,
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// useSearchKernel Hook
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// useSearchKernel Hook
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Search kernel hook with full operations
 *
 * Creates/retrieves a SearchKernel instance for the given namespace.
 * Automatically initializes the kernel on mount.
 *
 * @param instance - Instance name (e.g., "movies", "users")
 * @param config - Optional kernel configuration
 *
 * @example
 * ```tsx
 * function MovieSearch() {
 *   const { atoms, search, index, isReady } = useSearchKernel<Movie>("movies")
 *
 *   useEffect(() => {
 *     // Index data on mount
 *     index(movies, { fields: ["title", "cast", "genres"] })
 *   }, [])
 *
 *   const handleSearch = async () => {
 *     await search({ query: inputValue, limit: 100 })
 *   }
 *
 *   const results = useAtomValue(atoms.results)
 *   const status = useAtomValue(atoms.status)
 *
 *   return (
 *     <div>
 *       <input onChange={...} />
 *       <button onClick={handleSearch}>Search</button>
 *       <ResultsList results={results} status={status} />
 *     </div>
 *   )
 * }
 * ```
 */
export function useSearchKernel<T extends Indexable>(
  instance: string,
  config?: Omit<SearchKernelConfig, "instance">
): UseSearchKernel<T> {
  const namespaceKey = useMemo(
    () => makeNamespaceKey("search", instance),
    [instance]
  )

  const atoms = useMemo(
    () => getNamespaceAtoms<T>(namespaceKey),
    [namespaceKey]
  )

  const derived = useMemo(
    () => getNamespaceDerivedAtoms(namespaceKey),
    [namespaceKey]
  )

  // Kernel instance state
  const [kernel, setKernel] = useState<SearchKernelInstance<T> | null>(null)
  const [isReady, setIsReady] = useState(false)

// Kernel instance state
  const [kernel, setKernel] = useState<SearchKernelInstance<T> | null>(null)
  const [isReady, setIsReady] = useState(false)

  // Initialize kernel on mount
  useEffect(() => {
    let mounted = true

    const initKernel = async () => {
      try {
        const program = Effect.gen(function* () {
          const registry = yield* KernelRegistry
          return yield* registry.getSearchKernel<T>({
            instance,
            ...config,
          })
        }).pipe(Effect.provide(KernelRegistry.Default))

        const kernelInstance = await Effect.runPromise(program)

        if (mounted) {
          setKernel(kernelInstance)
          setIsReady(true)
        }
      } catch (error) {
        console.error(`[useSearchKernel] Failed to initialize kernel: ${instance}`, error)
      }
    }

    initKernel()

    return () => {
      mounted = false
    }
  }, [instance, config?.driver, config?.warmUp, config?.autoDispose])

  // Memoized operations
  const index = useCallback(
    async (items: readonly T[], indexConfig: IndexConfig<T>) => {
      if (!kernel) {
        throw new Error(`Kernel not initialized: search:${instance}`)
      }
      await Effect.runPromise(kernel.index(items, indexConfig))
    },
    [kernel, instance]
  )

  const search = useCallback(
    async (query: SearchQuery) => {
      if (!kernel) {
        throw new Error(`Kernel not initialized: search:${instance}`)
      }
      return await Effect.runPromise(kernel.search(query))
    },
    [kernel, instance]
  )

  const setDriver = useCallback(
    async (driver: "flex" | "linear") => {
      if (!kernel) {
        throw new Error(`Kernel not initialized: search:${instance}`)
      }
      await Effect.runPromise(kernel.setDriver(driver))
    },
    [kernel, instance]
  )

return {
    namespaceKey,
    isReady,
    atoms,
    derived,
    kernel,
    index,
    search,
    setDriver,
  }
}

