const POSITION_OFFSETS: Record<PortPosition, { x: number; y: number }> = {
  left: { x: 0, y: 100 },
  right: { x: 200, y: 100 },
  top: { x: 100, y: 0 },
  bottom: { x: 100, y: 200 },
};

// =============================================================================
