        rounded-lg
        cursor-pointer
        transition-all duration-150
      "
      style={{
        backgroundColor: colors.bg,
        border: `2px solid ${colors.border}`,
        boxShadow: selected || isConnected ? colors.glow : 'none',
        minWidth: 80,
      }}
    >
      {/* Port label */}
      <div
        className="text-xs font-mono font-medium"
        style={{
          color: colors.border,
          fontSize: 'var(--tmnl-text-xs, 12px)',
