  // ---------------------------------------------------------------------------
  // Link Persistence
  // ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
  // Link Persistence
  // ---------------------------------------------------------------------------

  /**
   * Save a link to SQLite.
