  ) => Effect.Effect<void, DataplanePersistenceError>;

  /**
   * Save all links to SQLite.
   */
  readonly saveLinks: (
    links: ReadonlyArray<Link>
  ) => Effect.Effect<void, DataplanePersistenceError>;

  /**
   * Load all links from SQLite.
   */
  readonly loadLinks: () => Effect.Effect<
