/**
 * @fileoverview Dataplane Link Schemas
 *
 * Schema definitions for the linking system:
 * - Branded IDs (PortId, LinkId, PlaneId, BlockId)
 * - LinkDirection and LinkRelationship literals
 * - LinkPort and Link TaggedClasses
 * - Plane TaggedClass for bus abstraction
 */

import { Schema } from 'effect';

// =============================================================================
// Branded ID Types
// =============================================================================

/** Branded identifier for data ports */
export const PortId = Schema.String.pipe(
  Schema.brand('PortId'),
  Schema.minLength(1)
);
export type PortId = typeof PortId.Type;

/** Branded identifier for links between ports */
export const LinkId = Schema.String.pipe(
  Schema.brand('LinkId'),
  Schema.minLength(1)
);
export type LinkId = typeof LinkId.Type;

/** Branded identifier for planes (data buses) */
export const PlaneId = Schema.String.pipe(
  Schema.brand('PlaneId'),
  Schema.minLength(1)
);
export type PlaneId = typeof PlaneId.Type;

/** Branded identifier for editor blocks */
export const BlockId = Schema.String.pipe(
  Schema.brand('BlockId'),
  Schema.minLength(1)
);
export type BlockId = typeof BlockId.Type;

// =============================================================================
// Enums (Schema.Literal)
// =============================================================================

/** Direction of data flow through a link */
export const LinkDirection = Schema.Literal('unidirectional', 'bidirectional');
export type LinkDirection = typeof LinkDirection.Type;

/**
 * Relationship type defining how data flows through a link
 *
 * - `pipe`: Source → transform → Target (filter/map operations)
 * - `sync`: Bidirectional sync with conflict resolution (last-write-wins)
 * - `aggregate`: Many sources → single aggregated target (reduce)
 * - `mirror`: 1:1 copy without transformation
 */
export const LinkRelationship = Schema.Literal(
  'pipe',
  'sync',
  'aggregate',
  'mirror'
);
export type LinkRelationship = typeof LinkRelationship.Type;

/** Port direction for data flow */
export const PortDirection = Schema.Literal('in', 'out', 'inout');
export type PortDirection = typeof PortDirection.Type;

/** Visual position of port on block */
export const PortPosition = Schema.Literal('left', 'right', 'top', 'bottom');
export type PortPosition = typeof PortPosition.Type;

/** Data type transported through port */
export const PortDataType = Schema.Literal(
  'geojson',
  'table',
  'row',
  'cell',
  'json',
  'stream'
);
export type PortDataType = typeof PortDataType.Type;

// =============================================================================
// LinkPort Schema
// =============================================================================

/**
 * A data port attached to an EmbeddedBlockWrapper component.
 * Ports are connection points for dataplane links.
 */
export class LinkPort extends Schema.TaggedClass<LinkPort>()('LinkPort', {
  /** Unique port identifier */
  id: PortId,

  /** Block this port belongs to */
  blockId: BlockId,

  /** Direction of data flow (in, out, or bidirectional) */
  direction: PortDirection,

  /** Type of data this port handles */
  dataType: PortDataType,

  /** Visual position on the block */
  position: PortPosition,

  /** Optional human-readable label */
  label: Schema.optional(Schema.String),

  /** Parent block ID for nested blocks */
  parentBlockId: Schema.optional(BlockId),
}) {
  /** Check if port accepts incoming data */
  get acceptsInput(): boolean {
    return this.direction === 'in' || this.direction === 'inout';
  }

  /** Check if port produces outgoing data */
  get producesOutput(): boolean {
    return this.direction === 'out' || this.direction === 'inout';
  }
}

// =============================================================================
// Link Schema
// =============================================================================

/**
 * A connection between two LinkPorts defining data flow relationship.
 */
export class Link extends Schema.TaggedClass<Link>()('Link', {
  /** Unique link identifier */
  id: LinkId,

  /** Source port ID */
  sourcePort: PortId,

/** Source port ID */
  sourcePort: PortId,

  /** Target port ID */
  targetPort: PortId,

  /** Direction of data flow */
  direction: LinkDirection,

  /** Relationship type (pipe, sync, aggregate, mirror) */
  relationship: LinkRelationship,

  /** Optional transform expression (D2QL or JS arrow function) */
  transform: Schema.optional(Schema.String),

  /** Creation timestamp */
  createdAt: Schema.DateFromSelf,

  /** Optional metadata */
  metadata: Schema.optional(
    Schema.Record({ key: Schema.String, value: Schema.Unknown })
  ),
}) {
  /** Check if link is bidirectional */
  get isBidirectional(): boolean {
    return this.direction === 'bidirectional';
  }

  /** Check if link has a transform */
  get hasTransform(): boolean {
    return this.transform !== undefined && this.transform.length > 0;
  }
}

// =============================================================================
// Plane Schema (Bus Abstraction)
// =============================================================================

/**
 * A Plane is a grouping mechanism for linked blocks that acts as a data bus.
 * All ports in a plane share data via broadcast semantics.
 * Planes can be nested for hierarchical organization.
 */
export class Plane extends Schema.TaggedClass<Plane>()('Plane', {
  /** Unique plane identifier */
  id: PlaneId,

  /** Human-readable name */
  name: Schema.NonEmptyString,

  /** Parent plane ID for nesting (null for root planes) */
  parentPlaneId: Schema.NullOr(PlaneId),

  /** Member port IDs */
  portIds: Schema.Array(PortId),

  /** Creation timestamp */
  createdAt: Schema.DateFromSelf,

  /** Optional metadata */
  metadata: Schema.optional(
    Schema.Record({ key: Schema.String, value: Schema.Unknown })
  ),
}) {
  /** Check if plane is nested under another plane */
  get isNested(): boolean {
    return this.parentPlaneId !== null;
  }

  /** Check if plane has any members */
  get hasPorts(): boolean {
    return this.portIds.length > 0;
  }

/** Check if plane has any members */
  get hasPorts(): boolean {
    return this.portIds.length > 0;
  }

  /** Get member count */
  get memberCount(): number {
    return this.portIds.length;
  }
}

// =============================================================================
// Utility Schemas
// =============================================================================

/** Array of links */
export const Links = Schema.Array(Link);
export type Links = typeof Links.Type;

/** Array of ports */
export const LinkPorts = Schema.Array(LinkPort);
export type LinkPorts = typeof LinkPorts.Type;

/** Array of planes */
export const Planes = Schema.Array(Plane);
export type Planes = typeof Planes.Type;

/** Configuration for creating a new link */
export const CreateLinkConfig = Schema.Struct({
  sourcePort: PortId,
  targetPort: PortId,
  direction: LinkDirection,
  relationship: LinkRelationship,
  transform: Schema.optional(Schema.String),
});
export type CreateLinkConfig = typeof CreateLinkConfig.Type;

/** Configuration for creating a new port */
export const CreatePortConfig = Schema.Struct({
  blockId: BlockId,
  direction: PortDirection,
  dataType: PortDataType,
  position: PortPosition,
  label: Schema.optional(Schema.String),
  parentBlockId: Schema.optional(BlockId),
});
export type CreatePortConfig = typeof CreatePortConfig.Type;

/** Configuration for creating a new plane */
export const CreatePlaneConfig = Schema.Struct({
  name: Schema.NonEmptyString,
  parentPlaneId: Schema.optional(PlaneId),
});
export type CreatePlaneConfig = typeof CreatePlaneConfig.Type;

/**
 * @fileoverview Port Data Type Registry
 *
 * Layer 1 of BlockPortSchema architecture:
 * Canonical data types with Effect.Schema validation.
 *
 * Types are hierarchical:
 * - geojson (base geographic data)
 *   - geojson:point, geojson:line, geojson:polygon (specializations)
 * - table (tabular data)
 * - json (generic structured data)
 * - stream (continuous event stream)
 *
 * Future: deck.gl layer types (layer:scatterplot, layer:hexagon, etc.)
 *
 * @module dataplane/schemas/port-types
 */

import { Schema, Option } from 'effect';

// =============================================================================
// Port Data Type Hierarchy
// =============================================================================

/**
 * Base port data type categories.
 * These are the top-level types that ports can handle.
 */
export const PortDataTypeCategory = Schema.Literal(
  'geojson',
  'table',
  'json',
  'stream',
  'layer' // Future: deck.gl layer types
);
export type PortDataTypeCategory = typeof PortDataTypeCategory.Type;

/**
 * GeoJSON specializations.
 * Allows ports to accept specific geometry types.
 */
export const GeoJSONSubtype = Schema.Literal(
  'any', // Accepts any GeoJSON
  'point',
  'multipoint',
  'linestring',
  'multilinestring',
  'polygon',
  'multipolygon',
  'geometrycollection',
  'feature',
  'featurecollection'
);
export type GeoJSONSubtype = typeof GeoJSONSubtype.Type;

/**
 * Table specializations.
 * For row-level vs cell-level granularity.
 */
export const TableSubtype = Schema.Literal(
  'any', // Accepts any table data
  'row', // Single row
  'cell', // Single cell value
  'column' // Column array
);
export type TableSubtype = typeof TableSubtype.Type;

/**
 * Stream specializations.
 * For different streaming semantics.
 */
export const StreamSubtype = Schema.Literal(
  'any', // Any stream
  'discrete', // Event-based discrete values
  'continuous', // Continuous signal
  'batched' // Batched updates
);
export type StreamSubtype = typeof StreamSubtype.Type;

/**
 * Layer specializations (for future deck.gl integration).
 * Placeholder for typed layer connections.
 */
export const LayerSubtype = Schema.Literal(
  'any', // Any layer
  'scatterplot',
  'hexagon',
  'arc',
  'line',
  'polygon',
  'icon',
  'text',
  'heatmap'
);
export type LayerSubtype = typeof LayerSubtype.Type;

// =============================================================================
// Composite Port Data Type
// =============================================================================

/**
 * Full port data type specification.
 * Combines category with optional subtype for precise typing.
 *
 * @example
 * ```typescript
 * // Accept any GeoJSON
 * const anyGeo: PortDataTypeSpec = { category: 'geojson', subtype: Option.none() };
 *
 * // Accept only point features
 * const pointOnly: PortDataTypeSpec = { category: 'geojson', subtype: Option.some('point') };
 *
 * // Accept table rows
 * const rowData: PortDataTypeSpec = { category: 'table', subtype: Option.some('row') };
 * ```
 */
export class PortDataTypeSpec extends Schema.TaggedClass<PortDataTypeSpec>()(
  'PortDataTypeSpec',
  {
    /** Top-level data category */
    category: PortDataTypeCategory,

/**
     * Optional subtype within the category.
     * If None, accepts any subtype within the category.
     */
    subtype: Schema.OptionFromNullOr(Schema.String),
  }
) {
  /**
   * Check if this type spec accepts the given type.
   * A type accepts another if:
   * - Categories match AND
   * - Either this subtype is None (wildcard) OR subtypes match
   */
  accepts(other: PortDataTypeSpec): boolean {
    if (this.category !== other.category) return false;
    if (Option.isNone(this.subtype)) return true; // Wildcard
    if (Option.isNone(other.subtype)) return true; // Other is wildcard
    return Option.getOrThrow(this.subtype) === Option.getOrThrow(other.subtype);
  }

  /** Human-readable type string */
  get displayName(): string {
    const sub = Option.getOrElse(this.subtype, () => 'any');
    return sub === 'any' ? this.category : `${this.category}:${sub}`;
  }
}

// =============================================================================
// Factory Functions
// =============================================================================

/**
 * Create a GeoJSON port data type specification.
 */
export const geojsonType = (
  subtype?: GeoJSONSubtype
): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'geojson',
    subtype: subtype && subtype !== 'any' ? Option.some(subtype) : Option.none(),
  });

/**
 * Create a table port data type specification.
 */
export const tableType = (subtype?: TableSubtype): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'table',
    subtype: subtype && subtype !== 'any' ? Option.some(subtype) : Option.none(),
  });

/**
 * Create a JSON port data type specification.
 */
export const jsonType = (): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'json',
    subtype: Option.none(),
  });

/**
 * Create a JSON port data type specification.
 */
export const jsonType = (): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'json',
    subtype: Option.none(),
  });

/**
 * Create a stream port data type specification.
 */
export const streamType = (subtype?: StreamSubtype): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'stream',
    subtype: subtype && subtype !== 'any' ? Option.some(subtype) : Option.none(),
  });

/**
 * Create a layer port data type specification (future).
 */
export const layerType = (subtype?: LayerSubtype): PortDataTypeSpec =>
  new PortDataTypeSpec({
    category: 'layer',
    subtype: subtype && subtype !== 'any' ? Option.some(subtype) : Option.none(),
  });

// =============================================================================
// Type Guards
// =============================================================================

export const isGeoJSONType = (spec: PortDataTypeSpec): boolean =>
  spec.category === 'geojson';

export const isTableType = (spec: PortDataTypeSpec): boolean =>
  spec.category === 'table';

export const isJSONType = (spec: PortDataTypeSpec): boolean =>
  spec.category === 'json';

export const isStreamType = (spec: PortDataTypeSpec): boolean =>
  spec.category === 'stream';

export const isLayerType = (spec: PortDataTypeSpec): boolean =>
  spec.category === 'layer';

/**
 * @fileoverview DataTransferService - Effect.Service for actual data flow between ports
 *
 * BEDROCK LAYER: This handles the actual transfer of data between blocks.
 * - Each output port has an Effect.PubSub (broadcast to subscribers)
 * - Each input port has an Effect.Queue (buffer incoming data)
 * - Links wire source pubsub → target queue
 *
 * Simple block API:
 * - Output: push(data) → broadcasts to all linked inputs
 * - Input: stream → Effect.Stream of incoming data
 */

import { Effect, PubSub, Queue, Stream, Fiber, Ref, Layer, pipe, Scope } from 'effect';
import type { PortId, LinkId, BlockId } from '../schemas/link';

// =============================================================================
// Types
// =============================================================================

/** Configuration for creating a port's data channel */
export interface PortChannelConfig {
  readonly portId: PortId;
  readonly blockId: BlockId;
  readonly direction: 'in' | 'out' | 'inout';
  readonly capacity?: number; // Queue/PubSub capacity, default unbounded
}

/** Internal port channel state */
interface PortChannel<T = unknown> {
  readonly portId: PortId;
  readonly blockId: BlockId;
  readonly direction: 'in' | 'out' | 'inout';
  /** For output ports: PubSub to broadcast data */
  readonly pubsub: PubSub.PubSub<T> | null;
  /** For input ports: Queue to buffer incoming data */
  readonly queue: Queue.Queue<T> | null;
}

/** Active link wiring (fiber that pipes source → target) */
interface LinkWiring {
  readonly linkId: LinkId;
  readonly sourcePortId: PortId;
  readonly targetPortId: PortId;
  readonly fiber: Fiber.RuntimeFiber<void, never>;
}

/** Service state */
interface DataTransferState {
  readonly channels: ReadonlyMap<PortId, PortChannel>;
  readonly wirings: ReadonlyMap<LinkId, LinkWiring>;
}

/** Service state */
interface DataTransferState {
  readonly channels: ReadonlyMap<PortId, PortChannel>;
  readonly wirings: ReadonlyMap<LinkId, LinkWiring>;
}

const initialState: DataTransferState = {
  channels: new Map(),
  wirings: new Map(),
};

// =============================================================================
// Service Interface
// =============================================================================

export interface DataTransferServiceShape {
  /**
   * Create a data channel for a port.
   * - Output ports get a PubSub (broadcast)
   * - Input ports get a Queue (buffer)
   * - Inout ports get both
   */
  readonly createChannel: (config: PortChannelConfig) => Effect.Effect<void>;

  /**
   * Destroy a port's data channel.
   * Also removes any link wirings connected to this port.
   */
  readonly destroyChannel: (portId: PortId) => Effect.Effect<void>;

  /**
   * Push data to an output port.
   * Data is broadcast to all subscribers (linked input ports).
   */
  readonly push: <T>(portId: PortId, data: T) => Effect.Effect<void>;

  /**
   * Get a stream of data from an input port.
   * Returns Effect.Stream that yields data as it arrives.
   */
  readonly getInputStream: <T>(portId: PortId) => Effect.Effect<Stream.Stream<T, never, never>>;

  /**
   * Wire a link: subscribe source port's pubsub to target port's queue.
   * Data pushed to source will flow to target.
   */
  readonly wireLink: (
    linkId: LinkId,
    sourcePortId: PortId,
    targetPortId: PortId
  ) => Effect.Effect<void>;

  /**
   * Unwire a link: stop the data flow fiber.
   */
  readonly unwireLink: (linkId: LinkId) => Effect.Effect<void>;

  /**
   * Check if a port has a channel.
   */
  readonly hasChannel: (portId: PortId) => Effect.Effect<boolean>;

/**
   * Check if a port has a channel.
   */
  readonly hasChannel: (portId: PortId) => Effect.Effect<boolean>;

  /**
   * Get all active link wirings.
   */
  readonly getActiveWirings: () => Effect.Effect<ReadonlyArray<LinkWiring>>;
}

// =============================================================================
// Service Implementation
// =============================================================================

export class DataTransferService extends Effect.Service<DataTransferService>()(
  'tmnl/DataTransferService',
  {
    effect: Effect.gen(function* () {
      const stateRef = yield* Ref.make<DataTransferState>(initialState);
      const scope = yield* Scope.make();

      // -----------------------------------------------------------------------
      // Channel Management
      // -----------------------------------------------------------------------

      const createChannel = (config: PortChannelConfig) =>
        Effect.gen(function* () {
          const { portId, blockId, direction, capacity } = config;

          // Create PubSub for output capability
          const pubsub =
            direction === 'out' || direction === 'inout'
              ? yield* (capacity
                  ? PubSub.bounded<unknown>(capacity)
                  : PubSub.unbounded<unknown>())
              : null;

          // Create Queue for input capability
          const queue =
            direction === 'in' || direction === 'inout'
              ? yield* (capacity
                  ? Queue.bounded<unknown>(capacity)
                  : Queue.unbounded<unknown>())
              : null;

          const channel: PortChannel = {
            portId,
            blockId,
            direction,
            pubsub,
            queue,
          };

          yield* Ref.update(stateRef, (s) => ({
            ...s,
            channels: new Map([...s.channels, [portId, channel]]),
          }));
        });

      const destroyChannel = (portId: PortId) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const channel = state.channels.get(portId);

          if (!channel) return;

const destroyChannel = (portId: PortId) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const channel = state.channels.get(portId);

          if (!channel) return;

          // Shutdown PubSub and Queue
          if (channel.pubsub) {
            yield* PubSub.shutdown(channel.pubsub);
          }
          if (channel.queue) {
            yield* Queue.shutdown(channel.queue);
          }

          // Remove any wirings connected to this port
          const wiringIds = [...state.wirings.entries()]
            .filter(
              ([, w]) => w.sourcePortId === portId || w.targetPortId === portId
            )
            .map(([id]) => id);

          for (const linkId of wiringIds) {
            yield* unwireLink(linkId);
          }

          yield* Ref.update(stateRef, (s) => {
            const channels = new Map(s.channels);
            channels.delete(portId);
            return { ...s, channels };
          });
        });

      // -----------------------------------------------------------------------
      // Data Flow
      // -----------------------------------------------------------------------

      const push = <T>(portId: PortId, data: T) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const channel = state.channels.get(portId);

          if (!channel?.pubsub) {
            yield* Effect.logWarning(
              `[DataTransfer] Cannot push to port ${portId}: no pubsub (not an output port?)`
            );
            return;
          }

          yield* PubSub.publish(channel.pubsub, data);
        });

      const getInputStream = <T>(portId: PortId) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const channel = state.channels.get(portId);

const getInputStream = <T>(portId: PortId) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const channel = state.channels.get(portId);

          if (!channel?.queue) {
            yield* Effect.logWarning(
              `[DataTransfer] Cannot get stream from port ${portId}: no queue (not an input port?)`
            );
            // Return empty stream
            return Stream.empty as Stream.Stream<T, never, never>;
          }

          // Create stream from queue
          return Stream.fromQueue(channel.queue) as Stream.Stream<T, never, never>;
        });

      // -----------------------------------------------------------------------
      // Link Wiring
      // -----------------------------------------------------------------------

      const wireLink = (
        linkId: LinkId,
        sourcePortId: PortId,
        targetPortId: PortId
      ) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);

          // Check if already wired
          if (state.wirings.has(linkId)) {
            yield* Effect.logWarning(
              `[DataTransfer] Link ${linkId} already wired`
            );
            return;
          }

          const sourceChannel = state.channels.get(sourcePortId);
          const targetChannel = state.channels.get(targetPortId);

          if (!sourceChannel?.pubsub) {
            yield* Effect.logWarning(
              `[DataTransfer] Cannot wire link: source port ${sourcePortId} has no pubsub`
            );
            return;
          }

          if (!targetChannel?.queue) {
            yield* Effect.logWarning(
              `[DataTransfer] Cannot wire link: target port ${targetPortId} has no queue`
            );
            return;
          }

          // Subscribe to source pubsub
          const dequeue = yield* PubSub.subscribe(sourceChannel.pubsub);

          // Create fiber that pipes pubsub → queue
          const fiber = yield* pipe(
            Stream.fromQueue(dequeue),
            Stream.tap((data) => Queue.offer(targetChannel.queue!, data)),
            Stream.runDrain,
            Effect.forkIn(scope)
          );

const wiring: LinkWiring = {
            linkId,
            sourcePortId,
            targetPortId,
            fiber,
          };

          yield* Ref.update(stateRef, (s) => ({
            ...s,
            wirings: new Map([...s.wirings, [linkId, wiring]]),
          }));

          yield* Effect.log(
            `[DataTransfer] Wired link ${linkId}: ${sourcePortId} → ${targetPortId}`
          );
        });

      const unwireLink = (linkId: LinkId) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const wiring = state.wirings.get(linkId);

          if (!wiring) return;

          // Interrupt the piping fiber
          yield* Fiber.interrupt(wiring.fiber);

          yield* Ref.update(stateRef, (s) => {
            const wirings = new Map(s.wirings);
            wirings.delete(linkId);
            return { ...s, wirings };
          });

          yield* Effect.log(`[DataTransfer] Unwired link ${linkId}`);
        });

      // -----------------------------------------------------------------------
      // Queries
      // -----------------------------------------------------------------------

      const hasChannel = (portId: PortId) =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => s.channels.has(portId))
        );

      const getActiveWirings = () =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => Array.from(s.wirings.values()))
        );

      // -----------------------------------------------------------------------
      // Return Service Shape
      // -----------------------------------------------------------------------

      return {
        createChannel,
        destroyChannel,
        push,
        getInputStream,
        wireLink,
        unwireLink,
        hasChannel,
        getActiveWirings,
      } satisfies DataTransferServiceShape;
    }),
  }
) {}

// =============================================================================
// Layer
// =============================================================================

export const DataTransferServiceLive = DataTransferService.Default;

/**
 * @fileoverview DataplaneService - Effect.Service for d2ts graph management
 *
 * Core service managing:
 * - D2 differential dataflow graph lifecycle
 * - Port registration and input stream creation
 * - Link creation with pipeline wiring
 * - Plane (bus) management
 * - Data push and graph execution
 */

import { Effect, Ref, Context, Layer, pipe } from 'effect';
import { D2 } from '@electric-sql/d2ts';
import type { IStreamBuilder } from '@electric-sql/d2ts';
import { MultiSet } from '@electric-sql/d2ts';
import { nanoid } from 'nanoid';

import {
  type PortId,
  type LinkId,
  type PlaneId,
  type BlockId,
  LinkPort,
  Link,
  Plane,
  type CreateLinkConfig,
  type CreatePortConfig,
  type CreatePlaneConfig,
} from '../schemas/link';

// =============================================================================
// Types
// =============================================================================

/** State stored in Effect.Ref for the dataplane */
export interface DataplaneState {
  /** The d2ts graph instance */
  readonly graph: D2<number> | null;
  /** Map of port ID to d2ts input stream */
  readonly inputs: ReadonlyMap<PortId, IStreamBuilder<unknown>>;
  /** Map of port ID to LinkPort */
  readonly ports: ReadonlyMap<PortId, LinkPort>;
  /** Map of link ID to Link */
  readonly links: ReadonlyMap<LinkId, Link>;
  /** Map of plane ID to Plane */
  readonly planes: ReadonlyMap<PlaneId, Plane>;
  /** Current version counter for d2ts */
  readonly version: number;
}

/** Initial empty state */
const initialState: DataplaneState = {
  graph: null,
  inputs: new Map(),
  ports: new Map(),
  links: new Map(),
  planes: new Map(),
  version: 0,
};

// =============================================================================
// Service Interface
// =============================================================================

// =============================================================================
// Service Interface
// =============================================================================

/** DataplaneService interface */
export interface DataplaneServiceShape {
  // Graph lifecycle
  readonly initGraph: () => Effect.Effect<D2<number>>;
  readonly getGraph: () => Effect.Effect<D2<number> | null>;

  // Port management
  readonly registerPort: (
    config: CreatePortConfig
  ) => Effect.Effect<LinkPort>;
  readonly unregisterPort: (portId: PortId) => Effect.Effect<void>;
  readonly getPort: (portId: PortId) => Effect.Effect<LinkPort | null>;
  readonly getAllPorts: () => Effect.Effect<ReadonlyArray<LinkPort>>;

  // Link management
  readonly createLink: (config: CreateLinkConfig) => Effect.Effect<Link>;
  readonly removeLink: (linkId: LinkId) => Effect.Effect<void>;
  readonly getLink: (linkId: LinkId) => Effect.Effect<Link | null>;
  readonly getAllLinks: () => Effect.Effect<ReadonlyArray<Link>>;
  readonly getLinksForPort: (
    portId: PortId
  ) => Effect.Effect<ReadonlyArray<Link>>;

  // Plane (bus) management
  readonly createPlane: (config: CreatePlaneConfig) => Effect.Effect<Plane>;
  readonly removePlane: (planeId: PlaneId) => Effect.Effect<void>;
  readonly addToPlane: (
    planeId: PlaneId,
    portIds: ReadonlyArray<PortId>
  ) => Effect.Effect<void>;
  readonly removeFromPlane: (
    planeId: PlaneId,
    portIds: ReadonlyArray<PortId>
  ) => Effect.Effect<void>;
  readonly getPlane: (planeId: PlaneId) => Effect.Effect<Plane | null>;
  readonly getAllPlanes: () => Effect.Effect<ReadonlyArray<Plane>>;

// Data flow
  readonly pushData: <T>(
    portId: PortId,
    data: ReadonlyArray<T>
  ) => Effect.Effect<void>;
  readonly pushToPlane: <T>(
    planeId: PlaneId,
    data: ReadonlyArray<T>
  ) => Effect.Effect<void>;
  readonly runGraph: () => Effect.Effect<void>;

  // State access
  readonly getState: () => Effect.Effect<DataplaneState>;
}

// =============================================================================
// Service Implementation
// =============================================================================

/** DataplaneService Effect.Service */
export class DataplaneService extends Effect.Service<DataplaneService>()(
  'tmnl/DataplaneService',
  {
    effect: Effect.gen(function* () {
      // Internal state ref
      const stateRef = yield* Ref.make<DataplaneState>(initialState);

      // Helper to generate IDs
      const generateId = <T extends string>(prefix: string): T =>
        `${prefix}-${nanoid(8)}` as T;

      // =========================================================================
      // Graph Lifecycle
      // =========================================================================

      const initGraph = () =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          if (state.graph) {
            return state.graph;
          }

          const graph = new D2<number>({ initialFrontier: 0 });

          yield* Ref.update(stateRef, (s) => ({
            ...s,
            graph,
            version: 1,
          }));

          return graph;
        });

      const getGraph = () =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => s.graph)
        );

      // =========================================================================
      // Port Management
      // =========================================================================

      const registerPort = (config: CreatePortConfig) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);

// =========================================================================
      // Port Management
      // =========================================================================

      const registerPort = (config: CreatePortConfig) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);

          // Each port gets a unique ID — no idempotency check on blockId/position/direction.
          // Multiple ports with same position/direction on a block are allowed.
          // React Strict Mode double-mount is handled at atoms layer via ID check.

          // Ensure graph is initialized
          const graph = state.graph ?? (yield* initGraph());

          // Generate port ID
          const portId = generateId<PortId>('port');

          // Create LinkPort instance
          const port = new LinkPort({
            id: portId,
            blockId: config.blockId as BlockId,
            direction: config.direction,
            dataType: config.dataType,
            position: config.position,
            label: config.label,
            parentBlockId: config.parentBlockId as BlockId | undefined,
          });

          // Create d2ts input stream for this port
          const input = graph.newInput<unknown>();

          // Update state
          yield* Ref.update(stateRef, (s) => ({
            ...s,
            graph,
            ports: new Map([...s.ports, [portId, port]]),
            inputs: new Map([...s.inputs, [portId, input]]),
          }));

          return port;
        });

      const unregisterPort = (portId: PortId) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (s) => {
            const ports = new Map(s.ports);
            const inputs = new Map(s.inputs);
            ports.delete(portId);
            inputs.delete(portId);

            // Also remove any links connected to this port
            const links = new Map(
              [...s.links].filter(
                ([, link]) =>
                  link.sourcePort !== portId && link.targetPort !== portId
              )
            );

return { ...s, ports, inputs, links };
          });
        });

      const getPort = (portId: PortId) =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => s.ports.get(portId) ?? null)
        );

      const getAllPorts = () =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => Array.from(s.ports.values()))
        );

      // =========================================================================
      // Link Management
      // =========================================================================

      const createLink = (config: CreateLinkConfig) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);

          // Generate link ID
          const linkId = generateId<LinkId>('link');

          // Create Link instance
          const link = new Link({
            id: linkId,
            sourcePort: config.sourcePort,
            targetPort: config.targetPort,
            direction: config.direction,
            relationship: config.relationship,
            transform: config.transform,
            createdAt: new Date(),
          });

          // Get input streams for source and target
          const sourceInput = state.inputs.get(config.sourcePort);
          const targetInput = state.inputs.get(config.targetPort);

          if (sourceInput && targetInput) {
            // Wire up the pipeline based on relationship type
            // For now, simple pass-through; PipelineBuilder will handle complex cases
            yield* Effect.sync(() => {
              // Pipeline wiring will be implemented in PipelineBuilder service
              // This is a placeholder for the connection logic
            });
          }

          // Update state
          yield* Ref.update(stateRef, (s) => ({
            ...s,
            links: new Map([...s.links, [linkId, link]]),
          }));

          return link;
        });

      const removeLink = (linkId: LinkId) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (s) => {
            const links = new Map(s.links);
            links.delete(linkId);
            return { ...s, links };
          });
        });

const getLink = (linkId: LinkId) =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => s.links.get(linkId) ?? null)
        );

      const getAllLinks = () =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => Array.from(s.links.values()))
        );

      const getLinksForPort = (portId: PortId) =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) =>
            Array.from(s.links.values()).filter(
              (link) =>
                link.sourcePort === portId || link.targetPort === portId
            )
          )
        );

      // =========================================================================
      // Plane (Bus) Management
      // =========================================================================

      const createPlane = (config: CreatePlaneConfig) =>
        Effect.gen(function* () {
          const planeId = generateId<PlaneId>('plane');

          const plane = new Plane({
            id: planeId,
            name: config.name,
            parentPlaneId: config.parentPlaneId ?? null,
            portIds: [],
            createdAt: new Date(),
          });

          yield* Ref.update(stateRef, (s) => ({
            ...s,
            planes: new Map([...s.planes, [planeId, plane]]),
          }));

          return plane;
        });

      const removePlane = (planeId: PlaneId) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (s) => {
            const planes = new Map(s.planes);
            planes.delete(planeId);
            return { ...s, planes };
          });
        });

      const addToPlane = (planeId: PlaneId, portIds: ReadonlyArray<PortId>) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (s) => {
            const plane = s.planes.get(planeId);
            if (!plane) return s;

            const updatedPlane = new Plane({
              ...plane,
              portIds: [...plane.portIds, ...portIds],
            });

const updatedPlane = new Plane({
              ...plane,
              portIds: [...plane.portIds, ...portIds],
            });

            return {
              ...s,
              planes: new Map([...s.planes, [planeId, updatedPlane]]),
            };
          });
        });

      const removeFromPlane = (
        planeId: PlaneId,
        portIds: ReadonlyArray<PortId>
      ) =>
        Effect.gen(function* () {
          const portIdSet = new Set(portIds);

          yield* Ref.update(stateRef, (s) => {
            const plane = s.planes.get(planeId);
            if (!plane) return s;

            const updatedPlane = new Plane({
              ...plane,
              portIds: plane.portIds.filter((id) => !portIdSet.has(id)),
            });

            return {
              ...s,
              planes: new Map([...s.planes, [planeId, updatedPlane]]),
            };
          });
        });

      const getPlane = (planeId: PlaneId) =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => s.planes.get(planeId) ?? null)
        );

      const getAllPlanes = () =>
        pipe(
          Ref.get(stateRef),
          Effect.map((s) => Array.from(s.planes.values()))
        );

      // =========================================================================
      // Data Flow
      // =========================================================================

      const pushData = <T>(portId: PortId, data: ReadonlyArray<T>) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const input = state.inputs.get(portId);

          if (!input) {
            return; // Port not found, silently ignore
          }

          const version = state.version;

          // Convert array to MultiSet (each item has multiplicity 1)
          const multiSet = new MultiSet<T>(data.map((item) => [item, 1]));

const version = state.version;

          // Convert array to MultiSet (each item has multiplicity 1)
          const multiSet = new MultiSet<T>(data.map((item) => [item, 1]));

          // Send data to the input stream
          yield* Effect.sync(() => {
            input.sendData(version, multiSet as MultiSet<unknown>);
            input.sendFrontier(version + 1);
          });

          // Increment version
          yield* Ref.update(stateRef, (s) => ({
            ...s,
            version: s.version + 1,
          }));
        });

      const pushToPlane = <T>(planeId: PlaneId, data: ReadonlyArray<T>) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);
          const plane = state.planes.get(planeId);

          if (!plane) {
            return; // Plane not found
          }

          // Broadcast to all ports in the plane
          for (const portId of plane.portIds) {
            yield* pushData(portId, data);
          }
        });

      const runGraph = () =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef);

          if (state.graph) {
            yield* Effect.sync(() => {
              state.graph!.run();
            });
          }
        });

      // =========================================================================
      // State Access
      // =========================================================================

      const getState = () => Ref.get(stateRef);

      // Return service shape
      return {
        initGraph,
        getGraph,
        registerPort,
        unregisterPort,
        getPort,
        getAllPorts,
        createLink,
        removeLink,
        getLink,
        getAllLinks,
        getLinksForPort,
        createPlane,
        removePlane,
        addToPlane,
        removeFromPlane,
        getPlane,
        getAllPlanes,
        pushData,
        pushToPlane,
        runGraph,
        getState,
      } satisfies DataplaneServiceShape;
    }),
  }
) {}

