// =============================================================================
// Machine
// =============================================================================

export { dragMachine, type DragMachine } from './machines/drag-machine'

/**
 * Drag Orchestrator XState Machine
 *
 * Lifecycle state machine for centralized drag operations:
 * - idle: Ready for drag
 * - dragging: Active drag with velocity tracking
 *
 * This machine coordinates drag state across all consumers
 * (selection system, floating panels, custom draggables).
 *
 * @pattern XState v5 + stx integration
 * @module
 */

import { setup, assign } from 'xstate'
import type { Vector2D, DragSource, DragMachineContext, DragMachineEvent } from '../types'

// =============================================================================
// Machine Setup
// =============================================================================

export const dragMachine = setup({
  types: {
    context: {} as DragMachineContext,
    events: {} as DragMachineEvent,
  },
  actions: {
    setOperationId: assign({
      operationId: (_, params: { id: string }) => params.id,
    }),
    clearOperationId: assign({
      operationId: () => null,
    }),
  },
  guards: {
    hasActiveOperation: ({ context }) => context.operationId !== null,
    noActiveOperation: ({ context }) => context.operationId === null,
  },
}).createMachine({
  id: 'dragOrchestrator',
  initial: 'idle',
  context: {
    operationId: null,
  },
  states: {
    // =========================================================================
    // Idle State - Ready for drag operations
    // =========================================================================
    idle: {
      on: {
        START_DRAG: {
          target: 'dragging',
          guard: 'noActiveOperation',
          actions: {
            type: 'setOperationId',
            params: ({ event }) => ({ id: event.operation.id }),
          },
        },
      },
    },

// =========================================================================
    // Dragging State - Active drag with velocity tracking
    // =========================================================================
    dragging: {
      on: {
        UPDATE_POSITION: {
          // Stay in dragging, velocity updates happen in stx.data
        },
        ADD_ELEMENTS: {
          // Add elements to current drag (group expansion)
        },
        REMOVE_ELEMENTS: {
          // Remove elements from current drag
        },
        END_DRAG: {
          target: 'idle',
          actions: 'clearOperationId',
        },
        CANCEL_DRAG: {
          target: 'idle',
          actions: 'clearOperationId',
        },
      },
    },
  },
})

export type DragMachine = typeof dragMachine

/**
 * Drag Orchestrator Types
 *
 * Schema-based types for the centralized drag system.
 * Manages velocity tracking, blur strategy, and multi-element drags.
 *
 * @pattern Effect Schema + stx
 * @module
 */

import { Schema } from 'effect'

// =============================================================================
// Vector & Velocity
// =============================================================================

export const Vector2D = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
})
export type Vector2D = typeof Vector2D.Type

export const DragVelocity = Schema.Struct({
  /** Raw velocity vector */
  raw: Vector2D,
  /** Smoothed velocity (EMA) */
  smoothed: Vector2D,
  /** Velocity magnitude (speed) */
  magnitude: Schema.Number,
  /** Velocity angle in radians */
  angle: Schema.Number,
})
export type DragVelocity = typeof DragVelocity.Type

// =============================================================================
// Blur Strategy
// =============================================================================

export const BlurStrategy = Schema.Literal('individual', 'wrapper', 'none')
export type BlurStrategy = typeof BlurStrategy.Type

export const BlurConfig = Schema.Struct({
  /** Maximum blur in pixels */
  maxBlur: Schema.optionalWith(Schema.Number, { default: () => 6 }),
  /** Intensity multiplier */
  intensity: Schema.optionalWith(Schema.Number, { default: () => 0.08 }),
  /** Velocity threshold to activate blur */
  threshold: Schema.optionalWith(Schema.Number, { default: () => 2 }),
  /** Enable directional stretch */
  enableStretch: Schema.optionalWith(Schema.Boolean, { default: () => true }),
  /** Max stretch factor */
  maxStretch: Schema.optionalWith(Schema.Number, { default: () => 1.03 }),
  /** Element count threshold to switch to wrapper blur */
  wrapperThreshold: Schema.optionalWith(Schema.Number, { default: () => 5 }),
})
export type BlurConfig = typeof BlurConfig.Type

// =============================================================================
// Drag Operation
// =============================================================================

export const DragSource = Schema.Literal('selection', 'floating', 'custom')
export type DragSource = typeof DragSource.Type

// =============================================================================
// Drag Operation
// =============================================================================

export const DragSource = Schema.Literal('selection', 'floating', 'custom')
export type DragSource = typeof DragSource.Type

export const DragOperation = Schema.Struct({
  /** Unique operation ID */
  id: Schema.String,
  /** Source system initiating drag */
  source: DragSource,
  /** Primary dragged element ID */
  primaryId: Schema.String,
  /** All element IDs being dragged (includes group members) */
  elementIds: Schema.Array(Schema.String),
  /** Starting position */
  startPosition: Vector2D,
  /** Current position */
  currentPosition: Vector2D,
  /** Start timestamp */
  startTime: Schema.Number,
})
export type DragOperation = typeof DragOperation.Type

// =============================================================================
// Motion Blur Style Output
// =============================================================================

export interface MotionBlurOutput {
  /** CSS filter property */
  filter: string | undefined
  /** CSS transform for directional stretch */
  transform: string | undefined
  /** CSS transition (disabled during motion) */
  transition: string
  /** Whether blur is currently active */
  isActive: boolean
  /** Current blur amount in pixels */
  blurAmount: number
  /** Current blur strategy being used */
  strategy: BlurStrategy
}

// =============================================================================
// STX Data Shape
// =============================================================================

export interface DragStxData {
  /** Current active drag operation (null if not dragging) */
  activeDrag: DragOperation | null
  /** Current velocity state */
  velocity: DragVelocity
  /** Last position for velocity calculation */
  lastPosition: Vector2D | null
  /** Last timestamp for velocity calculation */
  lastTimestamp: number
  /** Blur configuration */
  blurConfig: BlurConfig
  /** Modifier keys state */
  modifiers: {
    shift: boolean
    ctrl: boolean
    alt: boolean
  }
}

// =============================================================================
// Machine Events
// =============================================================================

// =============================================================================
// Machine Events
// =============================================================================

export type DragMachineEvent =
  | { type: 'START_DRAG'; operation: DragOperation }
  | { type: 'UPDATE_POSITION'; position: Vector2D }
  | { type: 'ADD_ELEMENTS'; elementIds: string[] }
  | { type: 'REMOVE_ELEMENTS'; elementIds: string[] }
  | { type: 'END_DRAG' }
  | { type: 'CANCEL_DRAG' }

// =============================================================================
// Machine Context
// =============================================================================

export interface DragMachineContext {
  operationId: string | null
}

// =============================================================================
// Hook Return Types
// =============================================================================

export interface UseDragOrchestratorReturn {
  /** Whether a drag is currently active */
  isDragging: boolean
  /** Current drag operation */
  operation: DragOperation | null
  /** Current velocity */
  velocity: DragVelocity
  /** Computed motion blur style */
  blurStyle: MotionBlurOutput
  /** Start a drag operation */
  startDrag: (source: DragSource, primaryId: string, elementIds: string[], position: Vector2D) => void
  /** Update drag position */
  updatePosition: (position: Vector2D) => void
  /** Add elements to current drag (for group expansion) */
  addElements: (elementIds: string[]) => void
  /** End drag operation */
  endDrag: () => void
  /** Cancel drag operation */
  cancelDrag: () => void
  /** Update blur config */
  setBlurConfig: (config: Partial<BlurConfig>) => void
}

/**
 * Drawer Component
 *
 * The actual drawer surface with backdrop, content area, and close affordances.
 * Animates with rolodex effect on enter/exit.
 *
 * @module
 */

import { useRef, useEffect, useCallback, type ReactNode } from 'react'
import { createPortal } from 'react-dom'
import { X } from 'lucide-react'
import { useDrawerStack } from './DrawerStackContext'
import {
  cardStackIn,
  cardStackOut,
  resetCardStackStyles,
} from './animations'
import type { DrawerInstance, DrawerSide } from './types'

// =============================================================================
// STYLES
// =============================================================================

const getDrawerStyles = (
  side: DrawerSide,
  width: number | string,
  height: number | string,
  zIndex: number,
  isVisible: boolean
): React.CSSProperties => {
  const base: React.CSSProperties = {
    position: 'fixed',
    zIndex,
    // TMNL CEW: Pure black surface
    backgroundColor: 'black',
    borderColor: 'rgb(38, 38, 38)', // neutral-800
    borderWidth: 1,
    borderStyle: 'solid',
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden',
    // Smooth transition for stack depth changes (only when visible, not during enter/exit)
    transition: isVisible ? 'transform 200ms ease-out, opacity 200ms ease-out' : 'none',
  }

const closeButtonStyles: React.CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: 28,
  height: 28,
  borderRadius: 4,
  border: 'none',
  backgroundColor: 'transparent',
  // TMNL CEW: Muted text
  color: 'rgb(82, 82, 82)', // neutral-600
  cursor: 'pointer',
  transition: 'background-color 0.15s, color 0.15s',
}

const contentStyles: React.CSSProperties = {
  flex: 1,
  overflow: 'auto',
  padding: 16,
}

// =============================================================================
// DRAWER COMPONENT
// =============================================================================

interface DrawerProps {
  instance: DrawerInstance
  /** Portal container (from slot) */
  container: HTMLElement
  /** Position in stack (0 = bottom, stackSize-1 = top) */
  stackIndex: number
  /** Total drawers in stack */
  stackSize: number
}

export function Drawer({ instance, container, stackIndex, stackSize }: DrawerProps) {
  const { pop, setAnimationState } = useDrawerStack()
  const drawerRef = useRef<HTMLDivElement>(null)
  const backdropRef = useRef<HTMLDivElement>(null)

  const {
    id,
    content,
    side = 'right',
    width = 400,
    height = '50%',
    zIndex,
    showBackdrop = true,
    closeOnOverlayClick = true,
    closeOnEscape = true,
    animationState,
  } = instance

  // Compute stack depth (0 = top, 1+ = recessed)
  const stackDepth = stackSize - 1 - stackIndex

  // -------------------------------------------------------------------------
  // Close handler
  // -------------------------------------------------------------------------
  const handleClose = useCallback(() => {
    pop(id)
  }, [pop, id])

// -------------------------------------------------------------------------
  // Close handler
  // -------------------------------------------------------------------------
  const handleClose = useCallback(() => {
    pop(id)
  }, [pop, id])

  // -------------------------------------------------------------------------
  // Enter animation
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (animationState === 'entering' && drawerRef.current) {
      cardStackIn(drawerRef.current, side).then(() => {
        setAnimationState(id, 'visible')
      })
    }
  }, [animationState, id, side, setAnimationState])

  // -------------------------------------------------------------------------
  // Exit animation
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (animationState === 'exiting' && drawerRef.current) {
      cardStackOut(drawerRef.current, side).then(() => {
        setAnimationState(id, 'exited')
      })
    }
  }, [animationState, id, side, setAnimationState])

  // -------------------------------------------------------------------------
  // Stack depth styles - staggered panels with hairline borders
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (animationState === 'visible' && drawerRef.current) {
      const el = drawerRef.current

      if (stackDepth === 0) {
        // Top drawer: neutral position
        el.style.transform = ''
      } else {
        // Recessed: offset to show hairline edge peeking
        const offset = stackDepth * 12

        let x = 0, y = 0
        switch (side) {
          case 'right': x = -offset; break
          case 'left': x = offset; break
          case 'bottom': y = -offset; break
          case 'top': y = offset; break
        }

        el.style.transform = `translateX(${x}px) translateY(${y}px)`
      }
    }
  }, [animationState, stackDepth, side])

  // -------------------------------------------------------------------------
  // Escape key handler
  // -------------------------------------------------------------------------
  useEffect(() => {
    if (!closeOnEscape) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        handleClose()
      }
    }

const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        handleClose()
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [closeOnEscape, handleClose])

  // -------------------------------------------------------------------------
  // Click outside handler
  // -------------------------------------------------------------------------
  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => {
      if (closeOnOverlayClick && e.target === backdropRef.current) {
        handleClose()
      }
    },
    [closeOnOverlayClick, handleClose]
  )

  // -------------------------------------------------------------------------
  // Cleanup on unmount
  // -------------------------------------------------------------------------
  useEffect(() => {
    return () => {
      if (drawerRef.current) {
        resetCardStackStyles(drawerRef.current)
      }
    }
  }, [])

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  const drawerContent = (
    <>
      {/* Backdrop */}
      {showBackdrop && (
        <div
          ref={backdropRef}
          style={{ ...backdropStyles, zIndex: zIndex - 1 }}
          onClick={handleBackdropClick}
        />
      )}

      {/* Drawer surface */}
      <div
        ref={drawerRef}
        style={getDrawerStyles(side, width, height, zIndex, animationState === 'visible')}
        role="dialog"
        aria-modal="true"
      >
        {/* Header with close button */}
        <div style={headerStyles}>
          <button
            style={closeButtonStyles}
            onClick={handleClose}
            aria-label="Close drawer"
            onMouseEnter={(e) => {
              // TMNL CEW: Elevated hover state
              e.currentTarget.style.backgroundColor = 'rgb(23, 23, 23)' // neutral-900
              e.currentTarget.style.color = 'white'
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent'
              e.currentTarget.style.color = 'rgb(82, 82, 82)' // neutral-600
            }}
          >
            <X size={16} />
          </button>
        </div>

{/* Content */}
        <div style={contentStyles}>{content}</div>
      </div>
    </>
  )

  return createPortal(drawerContent, container)
}

// =============================================================================
// DRAWER RENDERER (renders all drawers for a slot)
// =============================================================================

interface DrawerRendererProps {
  slotId: string
  container: HTMLElement
}

export function DrawerRenderer({ slotId, container }: DrawerRendererProps) {
  const { getDrawersForSlot } = useDrawerStack()
  const drawers = getDrawersForSlot(slotId)
  const stackSize = drawers.length

  return (
    <>
      {drawers.map((instance, index) => (
        <Drawer
          key={instance.id}
          instance={instance}
          container={container}
          stackIndex={index}
          stackSize={stackSize}
        />
      ))}
    </>
  )
}

/**
 * Drawer Stack Context
 *
 * Provider for drawer stack management with z-index ordering,
 * slot registration, and animation coordination.
 *
 * @module
 */

import {
  createContext,
  useContext,
  useCallback,
  useRef,
  useMemo,
  type ReactNode,
} from 'react'
import { nanoid } from 'nanoid'
import { Atom, useAtom, useAtomValue } from '@effect-atom/atom-react'
import type {
  DrawerConfig,
  DrawerInstance,
  DrawerStackState,
  DrawerSlot,
  DrawerSlotType,
  DrawerAnimationState,
} from './types'
import { initialDrawerStackState, DEFAULT_DRAWER_CONFIG } from './types'

// =============================================================================
// ATOMS (Module-level for stable references)
// =============================================================================

const drawerStackAtom = Atom.make<DrawerStackState>(initialDrawerStackState)
const slotRegistryAtom = Atom.make<Map<DrawerSlotType, DrawerSlot>>(new Map())

// Base z-index for drawer system (above FloatingPanels)
const BASE_Z_INDEX = 10000
const Z_INDEX_GAP = 10

// =============================================================================
// CONTEXT
// =============================================================================

// Base z-index for drawer system (above FloatingPanels)
const BASE_Z_INDEX = 10000
const Z_INDEX_GAP = 10

// =============================================================================
// CONTEXT
// =============================================================================

interface DrawerStackContextValue {
  /** Current stack state (reactive) */
  state: DrawerStackState
  /** Push a new drawer onto the stack */
  push: (config: DrawerConfig) => string
  /** Pop a drawer by ID */
  pop: (id: string) => void
  /** Pop all drawers */
  popAll: () => void
  /** Replace a drawer (animated switch) */
  replace: (id: string, config: DrawerConfig) => string
  /** Bring a drawer to front */
  bringToFront: (id: string) => void
  /** Get drawer by ID */
  getDrawer: (id: string) => DrawerInstance | undefined
  /** Get drawers for a specific slot */
  getDrawersForSlot: (slotId: DrawerSlotType) => DrawerInstance[]
  /** Register a slot for portal targeting */
  registerSlot: (slot: DrawerSlot) => void
  /** Unregister a slot */
  unregisterSlot: (slotId: DrawerSlotType) => void
  /** Get registered slot */
  getSlot: (slotId: DrawerSlotType) => DrawerSlot | undefined
  /** Update drawer animation state */
  setAnimationState: (id: string, state: DrawerAnimationState) => void
}

const DrawerStackContext = createContext<DrawerStackContextValue | null>(null)

// =============================================================================
// PROVIDER
// =============================================================================

interface DrawerStackProviderProps {
  children: ReactNode
}

export function DrawerStackProvider({ children }: DrawerStackProviderProps) {
  const [state, setState] = useAtom(drawerStackAtom)
  const [slots, setSlots] = useAtom(slotRegistryAtom)

  // Track next z-index
  const nextZIndexRef = useRef(BASE_Z_INDEX)

// Track next z-index
  const nextZIndexRef = useRef(BASE_Z_INDEX)

  // -------------------------------------------------------------------------
  // Push drawer onto stack
  // -------------------------------------------------------------------------
  const push = useCallback(
    (config: DrawerConfig): string => {
      const id = config.id || nanoid()
      const zIndex = nextZIndexRef.current
      nextZIndexRef.current += Z_INDEX_GAP

      const instance: DrawerInstance = {
        ...DEFAULT_DRAWER_CONFIG,
        ...config,
        id,
        zIndex,
        animationState: 'entering',
        openedAt: Date.now(),
      }

      setState((prev) => ({
        ...prev,
        drawers: [...prev.drawers, instance],
        zOrder: [...prev.zOrder, id],
        transitioning: id,
      }))

      // Call onOpen callback
      config.onOpen?.()

      return id
    },
    [setState]
  )

  // -------------------------------------------------------------------------
  // Pop drawer from stack
  // -------------------------------------------------------------------------
  const pop = useCallback(
    (id: string): void => {
      const drawer = state.drawers.find((d) => d.id === id)
      if (!drawer) return

      // Set to exiting state (animation will handle removal)
      setState((prev) => ({
        ...prev,
        drawers: prev.drawers.map((d) =>
          d.id === id ? { ...d, animationState: 'exiting' as const } : d
        ),
        transitioning: id,
      }))

      // Call onClose callback
      drawer.onClose?.()
    },
    [state.drawers, setState]
  )

  // -------------------------------------------------------------------------
  // Pop all drawers
  // -------------------------------------------------------------------------
  const popAll = useCallback((): void => {
    setState((prev) => ({
      ...prev,
      drawers: prev.drawers.map((d) => ({
        ...d,
        animationState: 'exiting' as const,
      })),
      transitioning: 'all',
    }))
  }, [setState])

// -------------------------------------------------------------------------
  // Replace drawer (animated switch)
  // -------------------------------------------------------------------------
  const replace = useCallback(
    (id: string, config: DrawerConfig): string => {
      pop(id)
      // Stagger new drawer opening
      return push(config)
    },
    [pop, push]
  )

  // -------------------------------------------------------------------------
  // Bring drawer to front
  // -------------------------------------------------------------------------
  const bringToFront = useCallback(
    (id: string): void => {
      setState((prev) => {
        const drawer = prev.drawers.find((d) => d.id === id)
        if (!drawer) return prev

        const newZIndex = nextZIndexRef.current
        nextZIndexRef.current += Z_INDEX_GAP

        return {
          ...prev,
          drawers: prev.drawers.map((d) =>
            d.id === id ? { ...d, zIndex: newZIndex } : d
          ),
          zOrder: [...prev.zOrder.filter((i) => i !== id), id],
        }
      })
    },
    [setState]
  )

  // -------------------------------------------------------------------------
  // Get drawer by ID
  // -------------------------------------------------------------------------
  const getDrawer = useCallback(
    (id: string): DrawerInstance | undefined => {
      return state.drawers.find((d) => d.id === id)
    },
    [state.drawers]
  )

  // -------------------------------------------------------------------------
  // Get drawers for slot
  // -------------------------------------------------------------------------
  const getDrawersForSlot = useCallback(
    (slotId: DrawerSlotType): DrawerInstance[] => {
      return state.drawers
        .filter((d) => d.slot === slotId && d.animationState !== 'exited')
        .sort((a, b) => a.zIndex - b.zIndex)
    },
    [state.drawers]
  )

  // -------------------------------------------------------------------------
  // Register slot
  // -------------------------------------------------------------------------
  const registerSlot = useCallback(
    (slot: DrawerSlot): void => {
      setSlots((prev) => {
        const next = new Map(prev)
        next.set(slot.id, slot)
        return next
      })
    },
    [setSlots]
  )

// -------------------------------------------------------------------------
  // Unregister slot
  // -------------------------------------------------------------------------
  const unregisterSlot = useCallback(
    (slotId: DrawerSlotType): void => {
      setSlots((prev) => {
        const next = new Map(prev)
        next.delete(slotId)
        return next
      })
    },
    [setSlots]
  )

  // -------------------------------------------------------------------------
  // Get slot
  // -------------------------------------------------------------------------
  const getSlot = useCallback(
    (slotId: DrawerSlotType): DrawerSlot | undefined => {
      return slots.get(slotId)
    },
    [slots]
  )

  // -------------------------------------------------------------------------
  // Set animation state
  // -------------------------------------------------------------------------
  const setAnimationState = useCallback(
    (id: string, animState: DrawerAnimationState): void => {
      setState((prev) => {
        // If exited, remove from stack
        if (animState === 'exited') {
          const drawer = prev.drawers.find((d) => d.id === id)
          drawer?.onExited?.()

          return {
            ...prev,
            drawers: prev.drawers.filter((d) => d.id !== id),
            zOrder: prev.zOrder.filter((i) => i !== id),
            transitioning: prev.transitioning === id ? null : prev.transitioning,
          }
        }

        // If visible, call onEntered
        if (animState === 'visible') {
          const drawer = prev.drawers.find((d) => d.id === id)
          drawer?.onEntered?.()
        }

        return {
          ...prev,
          drawers: prev.drawers.map((d) =>
            d.id === id ? { ...d, animationState: animState } : d
          ),
          transitioning:
            animState === 'visible' && prev.transitioning === id
              ? null
              : prev.transitioning,
        }
      })
    },
    [setState]
  )

// -------------------------------------------------------------------------
  // Context value
  // -------------------------------------------------------------------------
  const value = useMemo(
    (): DrawerStackContextValue => ({
      state,
      push,
      pop,
      popAll,
      replace,
      bringToFront,
      getDrawer,
      getDrawersForSlot,
      registerSlot,
      unregisterSlot,
      getSlot,
      setAnimationState,
    }),
    [
      state,
      push,
      pop,
      popAll,
      replace,
      bringToFront,
      getDrawer,
      getDrawersForSlot,
      registerSlot,
      unregisterSlot,
      getSlot,
      setAnimationState,
    ]
  )

  return (
    <DrawerStackContext.Provider value={value}>
      {children}
    </DrawerStackContext.Provider>
  )
}

// =============================================================================
// HOOK
// =============================================================================

/**
 * Access drawer stack context.
 *
 * @throws Error if used outside DrawerStackProvider
 */
export function useDrawerStack(): DrawerStackContextValue {
  const context = useContext(DrawerStackContext)
  if (!context) {
    throw new Error('useDrawerStack must be used within DrawerStackProvider')
  }
  return context
}

/**
 * Safe version that returns null when no provider exists.
 * Use this for components that should gracefully no-op without provider.
 */
export function useDrawerStackSafe(): DrawerStackContextValue | null {
  return useContext(DrawerStackContext)
}

// =============================================================================
// SELECTORS (for optimized subscriptions)
// =============================================================================

/**
 * Get current drawer count.
 */
export function useDrawerCount(): number {
  const state = useAtomValue(drawerStackAtom)
  return state.drawers.length
}

/**
 * Check if any drawer is open.
 */
export function useHasOpenDrawers(): boolean {
  const state = useAtomValue(drawerStackAtom)
  return state.drawers.length > 0
}

/**
 * Get top drawer ID.
 */
export function useTopDrawerId(): string | null {
  const state = useAtomValue(drawerStackAtom)
  return state.zOrder[state.zOrder.length - 1] ?? null
}

/**
 * Get top drawer ID.
 */
export function useTopDrawerId(): string | null {
  const state = useAtomValue(drawerStackAtom)
  return state.zOrder[state.zOrder.length - 1] ?? null
}

// =============================================================================
// EXPORTS
// =============================================================================

export { drawerStackAtom, slotRegistryAtom }

/**
 * Global Slot Component
 *
 * Full-viewport drawer slot for app-wide overlays.
 * Renders above all FloatingPanels.
 *
 * @module
 */

import { useRef, useEffect } from 'react'
import { useDrawerStack } from './DrawerStackContext'
import { DrawerRenderer } from './Drawer'

// =============================================================================
// GLOBAL SLOT
// =============================================================================

const SLOT_ID = 'global' as const

const containerStyles: React.CSSProperties = {
  position: 'fixed',
  inset: 0,
  pointerEvents: 'none',
  zIndex: 9999, // Below drawer base z-index, container just for reference
}

export function GlobalSlot() {
  const { registerSlot, unregisterSlot, getDrawersForSlot } = useDrawerStack()
  const containerRef = useRef<HTMLDivElement>(null)

  // Register slot on mount
  useEffect(() => {
    if (containerRef.current) {
      registerSlot({
        id: SLOT_ID,
        containerRef: containerRef as React.RefObject<HTMLDivElement>,
      })
    }

    return () => {
      unregisterSlot(SLOT_ID)
    }
  }, [registerSlot, unregisterSlot])

  const drawers = getDrawersForSlot(SLOT_ID)
  const hasDrawers = drawers.length > 0

  return (
    <div
      ref={containerRef}
      style={{
        ...containerStyles,
        // Enable pointer events only when drawers are present
        pointerEvents: hasDrawers ? 'auto' : 'none',
      }}
      data-drawer-slot="global"
    >
      {containerRef.current && (
        <DrawerRenderer slotId={SLOT_ID} container={containerRef.current} />
      )}
    </div>
  )
}

// =============================================================================
// EXPORTS
// =============================================================================

export { SLOT_ID as GLOBAL_SLOT_ID }

/**
 * Panel Slot Component
 *
 * Per-panel drawer slot for panel-scoped overlays.
 * Clips to panel bounds via overflow:hidden.
 *
 * @module
 */

import { useRef, useEffect } from 'react'
import { useDrawerStackSafe } from './DrawerStackContext'
import { DrawerRenderer } from './Drawer'

// =============================================================================
// PANEL SLOT
// =============================================================================

interface PanelSlotProps {
  /** Panel ID this slot belongs to */
  panelId: string
  /** Optional custom styles */
  style?: React.CSSProperties
  /** Optional class name */
  className?: string
}

const containerStyles: React.CSSProperties = {
  position: 'absolute',
  inset: 0,
  pointerEvents: 'none',
  overflow: 'hidden', // Clip drawers to panel bounds
  zIndex: 100, // Above panel content, below other panels
}

export function PanelSlot({ panelId, style, className }: PanelSlotProps) {
  const context = useDrawerStackSafe()
  const containerRef = useRef<HTMLDivElement>(null)

  // Register slot on mount (only if provider exists)
  useEffect(() => {
    if (!context || !containerRef.current) return

    context.registerSlot({
      id: panelId,
      containerRef: containerRef as React.RefObject<HTMLDivElement>,
      bounds: containerRef.current.getBoundingClientRect(),
    })

    return () => {
      context.unregisterSlot(panelId)
    }
  }, [panelId, context])

  // Update bounds on resize (only if provider exists)
  useEffect(() => {
    if (!context || !containerRef.current) return

    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        context.registerSlot({
          id: panelId,
          containerRef: containerRef as React.RefObject<HTMLDivElement>,
          bounds: entry.target.getBoundingClientRect(),
        })
      }
    })

    observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [panelId, context])

  // No provider = no-op (gracefully render nothing)
  if (!context) {
    return null
  }

observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [panelId, context])

  // No provider = no-op (gracefully render nothing)
  if (!context) {
    return null
  }

  const drawers = context.getDrawersForSlot(panelId)
  const hasDrawers = drawers.length > 0

  return (
    <div
      ref={containerRef}
      style={{
        ...containerStyles,
        ...style,
        // Enable pointer events only when drawers are present
        pointerEvents: hasDrawers ? 'auto' : 'none',
      }}
      className={className}
      data-drawer-slot={panelId}
    >
      {containerRef.current && (
        <DrawerRenderer slotId={panelId} container={containerRef.current} />
      )}
    </div>
  )
}

/**
 * Card Stack Animation
 *
 * Clean, no-bullshit drawer animation.
 * Slide + subtle scale parallax. Stack depth awareness.
 *
 * @module
 */

import { animate } from 'animejs'
import type { DrawerSide } from '../types'

// =============================================================================
// CONFIG
// =============================================================================

export interface CardStackConfig {
  /** Animation duration (ms) */
  duration: number
  /** Scale factor at start (0.98 = subtle, 0.9 = dramatic) */
  scaleStart: number
  /** Easing function */
  ease: string
}

export interface StackDepthConfig {
  /** Offset per depth level (px) - how much each card peeks */
  offsetPerLevel: number
  /** Scale reduction per depth level */
  scalePerLevel: number
  /** Opacity reduction per depth level */
  opacityPerLevel: number
  /** Animation duration (ms) */
  duration: number
  /** Easing function */
  ease: string
}

export const DEFAULT_CARD_STACK_CONFIG: CardStackConfig = {
  duration: 250,
  scaleStart: 0.98,
  ease: 'outQuart',
}

export const DEFAULT_STACK_DEPTH_CONFIG: StackDepthConfig = {
  offsetPerLevel: 16,
  scalePerLevel: 0.03,
  opacityPerLevel: 0.15,
  duration: 200,
  ease: 'outQuart',
}

// =============================================================================
// HELPERS
// =============================================================================

/**
 * Get initial transform based on drawer side.
 */
function getOffscreenTransform(side: DrawerSide): { x: string; y: string } {
  switch (side) {
    case 'right':
      return { x: '100%', y: '0' }
    case 'left':
      return { x: '-100%', y: '0' }
    case 'bottom':
      return { x: '0', y: '100%' }
    case 'top':
      return { x: '0', y: '-100%' }
  }
}

// =============================================================================
// CARD STACK IN (Enter)
// =============================================================================

// =============================================================================
// CARD STACK IN (Enter)
// =============================================================================

/**
 * Animate drawer entering.
 * Slide from edge with subtle scale-up.
 */
export function cardStackIn(
  element: HTMLElement,
  side: DrawerSide = 'right',
  config: Partial<CardStackConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_CARD_STACK_CONFIG, ...config }
  const offset = getOffscreenTransform(side)

  // Set initial state: offscreen + scaled down
  element.style.transform = `translateX(${offset.x}) translateY(${offset.y}) scale(${c.scaleStart})`
  element.style.opacity = '1'

  return new Promise((resolve) => {
    animate(element, {
      translateX: '0%',
      translateY: '0%',
      scale: 1,
      duration: c.duration,
      ease: c.ease,
    })
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// CARD STACK OUT (Exit)
// =============================================================================

/**
 * Animate drawer exiting.
 * Slide to edge with subtle scale-down.
 */
export function cardStackOut(
  element: HTMLElement,
  side: DrawerSide = 'right',
  config: Partial<CardStackConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_CARD_STACK_CONFIG, ...config }
  const offset = getOffscreenTransform(side)

  return new Promise((resolve) => {
    animate(element, {
      translateX: offset.x,
      translateY: offset.y,
      scale: c.scaleStart,
      duration: c.duration,
      ease: c.ease,
    })
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// STACK DEPTH (Recessed card effect)
// =============================================================================

// =============================================================================
// STACK DEPTH (Recessed card effect)
// =============================================================================

/**
 * Get offset direction based on drawer side.
 * Cards recede in the opposite direction of the drawer edge.
 */
function getDepthOffset(
  side: DrawerSide,
  depth: number,
  offsetPerLevel: number
): { x: number; y: number } {
  const offset = depth * offsetPerLevel
  switch (side) {
    case 'right':
      return { x: -offset, y: 0 } // Peek left
    case 'left':
      return { x: offset, y: 0 } // Peek right
    case 'bottom':
      return { x: 0, y: -offset } // Peek up
    case 'top':
      return { x: 0, y: offset } // Peek down
  }
}

/**
 * Animate drawer to its stack depth position.
 * depth 0 = topmost (no recession), depth 1+ = recessed cards.
 */
export function animateStackDepth(
  element: HTMLElement,
  depth: number,
  side: DrawerSide = 'right',
  config: Partial<StackDepthConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_STACK_DEPTH_CONFIG, ...config }
  const { x, y } = getDepthOffset(side, depth, c.offsetPerLevel)

  const scale = Math.max(0.85, 1 - depth * c.scalePerLevel)
  const opacity = Math.max(0.4, 1 - depth * c.opacityPerLevel)

  return new Promise((resolve) => {
    animate(element, {
      translateX: `${x}px`,
      translateY: `${y}px`,
      scale,
      opacity,
      duration: c.duration,
      ease: c.ease,
    })
    setTimeout(resolve, c.duration)
  })
}

/**
 * Apply stack depth styles instantly (no animation).
 * Use for initial render of already-recessed cards.
 */
export function applyStackDepth(
  element: HTMLElement,
  depth: number,
  side: DrawerSide = 'right',
  config: Partial<StackDepthConfig> = {}
): void {
  const c = { ...DEFAULT_STACK_DEPTH_CONFIG, ...config }
  const { x, y } = getDepthOffset(side, depth, c.offsetPerLevel)

  const scale = Math.max(0.85, 1 - depth * c.scalePerLevel)
  const opacity = Math.max(0.4, 1 - depth * c.opacityPerLevel)

  element.style.transform = `translateX(${x}px) translateY(${y}px) scale(${scale})`
  element.style.opacity = `${opacity}`
}

// =============================================================================
// RESET
// =============================================================================

/**
 * Reset element styles to neutral state.
 */
export function resetCardStackStyles(element: HTMLElement): void {
  element.style.transform = ''
  element.style.opacity = ''
}

