/**
 * Parallax Lift Animation
 *
 * 3D card fan effect for stacked drawers.
 * Each layer lifts by decreasing amounts creating visual depth hierarchy.
 *
 * @module
 */

import { animate } from 'animejs'
import type { ParallaxConfig } from '../types'
import { DEFAULT_PARALLAX_CONFIG } from '../types'

// =============================================================================
// PARALLAX LIFT STACK
// =============================================================================

/**
 * Apply parallax lift effect to a stack of drawer elements.
 * Creates a 3D card fan with deeper layers appearing more recessed.
 *
 * @param drawers - Array of drawer elements (index 0 = bottom, last = top)
 * @param config - Animation configuration
 * @returns Promise that resolves when all animations complete
 */
export function parallaxLiftStack(
  drawers: HTMLElement[],
  config: Partial<ParallaxConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_PARALLAX_CONFIG, ...config }

  const animations = drawers.map((el, i) => {
    // depth: 0 = top (no effect), higher = further back
    const depth = drawers.length - i - 1

    return animate(el, {
      translateY: -depth * c.liftPerLayer,
      rotateX: -depth * c.rotatePerLayer,
      filter: `blur(${depth * c.blurPerLayer}px)`,
      opacity: 1 - depth * c.opacityDecay,
      duration: c.duration,
      ease: 'outQuart',
    })
  })

  return new Promise((resolve) => {
    // Wait for longest animation
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// PARALLAX COLLAPSE (Reset stack to flat)
// =============================================================================

return new Promise((resolve) => {
    // Wait for longest animation
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// PARALLAX COLLAPSE (Reset stack to flat)
// =============================================================================

/**
 * Collapse parallax stack back to flat state.
 * All drawers return to neutral position.
 *
 * @param drawers - Array of drawer elements
 * @param config - Animation configuration
 * @returns Promise that resolves when all animations complete
 */
export function parallaxCollapse(
  drawers: HTMLElement[],
  config: Partial<ParallaxConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_PARALLAX_CONFIG, ...config }

  drawers.forEach((el) => {
    animate(el, {
      translateY: 0,
      rotateX: 0,
      filter: 'blur(0px)',
      opacity: 1,
      duration: c.duration,
      ease: 'outQuart',
    })
  })

  return new Promise((resolve) => {
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// PARALLAX REORDER (Animate stack reordering)
// =============================================================================

/**
 * Animate stack reordering when bringing a drawer to front.
 * The target drawer rises while others compress down.
 *
 * @param drawers - Array of drawer elements in new order (last = top)
 * @param targetIndex - Index of the drawer being brought to front
 * @param config - Animation configuration
 * @returns Promise that resolves when animation completes
 */
export function parallaxReorder(
  drawers: HTMLElement[],
  targetIndex: number,
  config: Partial<ParallaxConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_PARALLAX_CONFIG, ...config }

  drawers.forEach((el, i) => {
    const depth = drawers.length - i - 1
    const isTarget = i === targetIndex

drawers.forEach((el, i) => {
    const depth = drawers.length - i - 1
    const isTarget = i === targetIndex

    animate(el, {
      // Target rises fully, others stay recessed
      translateY: isTarget ? 0 : -depth * c.liftPerLayer,
      rotateX: isTarget ? 0 : -depth * c.rotatePerLayer,
      filter: isTarget ? 'blur(0px)' : `blur(${depth * c.blurPerLayer}px)`,
      opacity: isTarget ? 1 : 1 - depth * c.opacityDecay,
      // Target animates faster for snappy response
      duration: isTarget ? c.duration * 0.7 : c.duration,
      ease: 'outQuart',
    })
  })

  return new Promise((resolve) => {
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// UTILITY: Apply static parallax styles (no animation)
// =============================================================================

/**
 * Apply parallax styles instantly without animation.
 * Useful for initial render of stack.
 *
 * @param drawers - Array of drawer elements
 * @param config - Parallax configuration
 */
export function applyParallaxStyles(
  drawers: HTMLElement[],
  config: Partial<ParallaxConfig> = {}
): void {
  const c = { ...DEFAULT_PARALLAX_CONFIG, ...config }

  drawers.forEach((el, i) => {
    const depth = drawers.length - i - 1

    el.style.transform = `translateY(${-depth * c.liftPerLayer}px) rotateX(${-depth * c.rotatePerLayer}deg)`
    el.style.filter = `blur(${depth * c.blurPerLayer}px)`
    el.style.opacity = `${1 - depth * c.opacityDecay}`
  })
}

/**
 * Reset parallax styles to neutral.
 */
export function resetParallaxStyles(drawers: HTMLElement[]): void {
  drawers.forEach((el) => {
    el.style.transform = ''
    el.style.filter = ''
    el.style.opacity = ''
  })
}

/**
 * Rolodex Animation
 *
 * Isometric card-stack transition using anime.js v4.
 * - Exit: lift + rotateX + blur + fade
 * - Enter: inverse rise + sharpen + hairline border strobe
 *
 * @module
 */

import { animate, createTimeline } from 'animejs'
import type { RolodexConfig } from '../types'
import { DEFAULT_ROLODEX_CONFIG } from '../types'

// =============================================================================
// ROLODEX OUT (Exit Animation)
// =============================================================================

/**
 * Animate drawer exiting with rolodex lift effect.
 *
 * Phase 1 (0-70%): Lift + blur + fade to 0.3
 * Phase 2 (70-100%): Complete fade to 0
 *
 * @param element - DOM element to animate
 * @param config - Animation configuration
 * @returns Promise that resolves when animation completes
 */
export function rolodexOut(
  element: HTMLElement,
  config: Partial<RolodexConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_ROLODEX_CONFIG, ...config }

  const timeline = createTimeline({
    defaults: { ease: 'outQuart' },
  })

  // Phase 1: Lift + blur + fade (0-70%)
  timeline.add(
    element,
    {
      translateY: -c.liftDistance,
      translateZ: -50,
      rotateX: c.rotateX,
      filter: `blur(${c.blurMax}px)`,
      opacity: [1, 0.3],
      duration: c.duration * 0.7,
    },
    0
  )

  // Phase 2: Complete fade (70-100%)
  timeline.add(
    element,
    {
      opacity: 0,
      duration: c.duration * 0.3,
    },
    c.duration * 0.7
  )

  return new Promise((resolve) => {
    timeline.play()
    // anime.js v4 doesn't have .finished, use setTimeout
    setTimeout(resolve, c.duration)
  })
}

return new Promise((resolve) => {
    timeline.play()
    // anime.js v4 doesn't have .finished, use setTimeout
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// ROLODEX IN (Enter Animation)
// =============================================================================

/**
 * Animate drawer entering with rolodex rise effect.
 *
 * Phase 1 (0-70%): Rise + sharpen + fade from 0.3
 * Phase 2 (70-100%): Hairline border strobe (cyan pulse)
 *
 * @param element - DOM element to animate
 * @param config - Animation configuration
 * @returns Promise that resolves when animation completes
 */
export function rolodexIn(
  element: HTMLElement,
  config: Partial<RolodexConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_ROLODEX_CONFIG, ...config }

  // Set initial state: below, rotated, blurred
  element.style.transform = `translateY(${c.liftDistance}px) translateZ(-50px) rotateX(${-c.rotateX}deg)`
  element.style.filter = `blur(${c.blurMax}px)`
  element.style.opacity = '0'

  const timeline = createTimeline({
    defaults: { ease: 'outQuart' },
  })

  // Phase 1: Rise + sharpen (0-70%)
  timeline.add(
    element,
    {
      translateY: 0,
      translateZ: 0,
      rotateX: 0,
      filter: 'blur(0px)',
      opacity: [0.3, 1],
      duration: c.duration * 0.7,
    },
    0
  )

// Phase 2: Hairline strobe (70-100%)
  timeline.add(
    element,
    {
      boxShadow: [
        '0 0 0 1px transparent',
        `0 0 0 1px ${c.strobeColor}`,
        '0 0 0 1px transparent',
      ],
      duration: c.strobeDuration,
    },
    c.duration * 0.7
  )

  return new Promise((resolve) => {
    timeline.play()
    setTimeout(resolve, c.duration)
  })
}

// =============================================================================
// ROLODEX SWITCH (Combined exit/enter for drawer replacement)
// =============================================================================

/**
 * Animate switching between two drawers with rolodex effect.
 * Runs exit and enter in parallel with slight stagger.
 *
 * @param exitElement - Element to animate out
 * @param enterElement - Element to animate in
 * @param config - Animation configuration
 * @returns Promise that resolves when both animations complete
 */
export async function rolodexSwitch(
  exitElement: HTMLElement,
  enterElement: HTMLElement,
  config: Partial<RolodexConfig> = {}
): Promise<void> {
  const c = { ...DEFAULT_ROLODEX_CONFIG, ...config }

  // Stagger enter by 30% of exit duration for overlap
  const stagger = c.duration * 0.3

  const exitPromise = rolodexOut(exitElement, c)
  const enterPromise = new Promise<void>((resolve) => {
    setTimeout(() => {
      rolodexIn(enterElement, c).then(resolve)
    }, stagger)
  })

  await Promise.all([exitPromise, enterPromise])
}

// =============================================================================
// UTILITY: Reset element styles after animation
// =============================================================================

/**
 * Reset element styles to neutral state after animation.
 */
export function resetRolodexStyles(element: HTMLElement): void {
  element.style.transform = ''
  element.style.filter = ''
  element.style.opacity = ''
  element.style.boxShadow = ''
}

