/**
 * Durable Streams Effect Bridge
 *
 * Effect-TS wrapper for @durable-streams/client protocol.
 * Provides service-based access to durable, resumable streams
 * for real-time sync (Telegram WebApp, collaborative editing, etc.)
 *
 * @see https://github.com/durable-streams/durable-streams
 * @example
 * ```typescript
 * import { DurableStreamClient, DurableStreamClientLive } from '@/lib/durable-streams';
 *
 * const program = Effect.gen(function* () {
 *   const client = yield* DurableStreamClient;
 *   const handle = yield* client.create({ url: '...', contentType: 'application/json' });
 *   yield* handle.append({ event: 'created', data: { ... } });
 * });
 * ```
 */

export * from './service';
export * from './schemas';

/**
 * Durable Streams Schemas
 *
 * Effect Schema definitions for the durable streams protocol.
 * Following Schema Discipline from CLAUDE.md.
 */

import { Schema } from 'effect';

// ============================================================================
// Offset (opaque string)
// ============================================================================

/**
 * Stream offset - opaque to the client.
 * Special value "-1" means start of stream.
 */
export const Offset = Schema.String.pipe(Schema.brand('DurableStreamOffset'));
export type Offset = typeof Offset.Type;

/**
 * Start of stream sentinel value
 */
export const OFFSET_START: Offset = '-1' as Offset;

// ============================================================================
// Live Mode
// ============================================================================

/**
 * Live mode for reading from a stream.
 * - false: Catch-up only, stop at first upToDate
 * - "auto": Behavior driven by consumption method
 * - "long-poll": Explicit long-poll for live updates
 * - "sse": Server-sent events for live updates
 */
export const LiveMode = Schema.Union(
  Schema.Literal(false),
  Schema.Literal('auto'),
  Schema.Literal('long-poll'),
  Schema.Literal('sse')
);
export type LiveMode = typeof LiveMode.Type;

// ============================================================================
// Stream Configuration
// ============================================================================

/**
 * Configuration for creating a stream
 */
export const StreamCreateConfig = Schema.Struct({
  /** Full URL to the durable stream endpoint */
  url: Schema.String,
  /** Content type (e.g., "application/json", "text/plain") */
  contentType: Schema.optional(Schema.String),
  /** Time-to-live in seconds */
  ttlSeconds: Schema.optional(Schema.Number),
  /** Expiration timestamp (ISO 8601) */
  expiresAt: Schema.optional(Schema.String),
  /** Initial body content */
  body: Schema.optional(Schema.Unknown),
});
export type StreamCreateConfig = typeof StreamCreateConfig.Type;

/**
 * Configuration for connecting to an existing stream
 */
export const StreamConnectConfig = Schema.Struct({
  /** Full URL to the durable stream endpoint */
  url: Schema.String,
  /** Optional authorization headers */
  headers: Schema.optional(Schema.Record({ key: Schema.String, value: Schema.String })),
});
export type StreamConnectConfig = typeof StreamConnectConfig.Type;

/**
 * Configuration for reading from a stream
 */
export const StreamReadConfig = Schema.Struct({
  /** Starting offset (defaults to "-1" for beginning) */
  offset: Schema.optional(Schema.String),
  /** Live mode */
  live: Schema.optional(LiveMode),
  /** Treat content as JSON */
  json: Schema.optional(Schema.Boolean),
});
export type StreamReadConfig = typeof StreamReadConfig.Type;

// ============================================================================
// Stream Metadata
// ============================================================================

/**
 * Metadata returned from HEAD request
 */
export const StreamMetadata = Schema.Struct({
  exists: Schema.Boolean,
  contentType: Schema.optional(Schema.String),
  offset: Schema.optional(Schema.String),
  etag: Schema.optional(Schema.String),
  cacheControl: Schema.optional(Schema.String),
});
export type StreamMetadata = typeof StreamMetadata.Type;

// ============================================================================
// JSON Batch (for subscribeJson)
// ============================================================================

/**
 * Batch of JSON items from a stream read
 */
export const JsonBatch = <T extends Schema.Schema.AnyNoContext>(itemSchema: T) =>
  Schema.Struct({
    items: Schema.Array(itemSchema),
    offset: Schema.String,
    upToDate: Schema.Boolean,
  });

/**
 * Generic JSON batch type
 */
export type JsonBatch<T> = {
  readonly items: readonly T[];
  readonly offset: string;
  readonly upToDate: boolean;
};

// ============================================================================
// Stream Events (for block system integration)
// ============================================================================

/**
 * Base stream event with timestamp
 */
export const StreamEventBase = Schema.Struct({
  timestamp: Schema.Number,
});

// ============================================================================
// Stream Events (for block system integration)
// ============================================================================

/**
 * Base stream event with timestamp
 */
export const StreamEventBase = Schema.Struct({
  timestamp: Schema.Number,
});

/**
 * Stream opened event
 */
export const StreamOpened = Schema.TaggedStruct('StreamOpened', {
  url: Schema.String,
  contentType: Schema.optional(Schema.String),
  timestamp: Schema.Number,
});
export type StreamOpened = typeof StreamOpened.Type;

/**
 * Stream closed event
 */
export const StreamClosed = Schema.TaggedStruct('StreamClosed', {
  url: Schema.String,
  reason: Schema.optional(Schema.String),
  timestamp: Schema.Number,
});
export type StreamClosed = typeof StreamClosed.Type;

/**
 * Stream error event
 */
export const StreamError = Schema.TaggedStruct('StreamError', {
  url: Schema.String,
  code: Schema.String,
  message: Schema.String,
  timestamp: Schema.Number,
});
export type StreamError = typeof StreamError.Type;

/**
 * Stream data received event
 */
export const StreamDataReceived = Schema.TaggedStruct('StreamDataReceived', {
  url: Schema.String,
  offset: Schema.String,
  itemCount: Schema.Number,
  upToDate: Schema.Boolean,
  timestamp: Schema.Number,
});
export type StreamDataReceived = typeof StreamDataReceived.Type;

/**
 * Union of all stream lifecycle events
 */
export const StreamLifecycleEvent = Schema.Union(
  StreamOpened,
  StreamClosed,
  StreamError,
  StreamDataReceived
);
export type StreamLifecycleEvent = typeof StreamLifecycleEvent.Type;

/**
 * Durable Streams Effect Service
 *
 * Effect-TS wrapper for @durable-streams/client.
 * Wraps Promise-based APIs in Effect for proper error handling,
 * interruption, and composition with other Effect services.
 *
 * @see Schema definitions in ./schemas.ts
 */

import { Context, Effect, Layer, Stream, PubSub, Queue, Scope, pipe } from 'effect';
import type {
  DurableStream as DurableStreamHandle,
  StreamResponse,
  DurableStreamOptions,
  CreateOptions,
  StreamOptions,
} from '@durable-streams/client';
import type {
  Offset,
  StreamCreateConfig,
  StreamConnectConfig,
  StreamReadConfig,
  StreamMetadata,
  JsonBatch,
} from './schemas';

// ============================================================================
// Error Types
// ============================================================================

/**
 * Durable stream error with code and context
 */
export class DurableStreamError extends Error {
  readonly _tag = 'DurableStreamError';
  constructor(
    readonly code: string,
    message: string,
    readonly url?: string
  ) {
    super(message);
    this.name = 'DurableStreamError';
  }
}

// ============================================================================
// Stream Handle (wrapped)
// ============================================================================

/**
 * Wrapped stream handle with Effect methods
 */
export interface EffectStreamHandle<T = unknown> {
  /** The underlying URL */
  readonly url: string;
  /** Content type (if known) */
  readonly contentType: string | undefined;

  /** Append data to the stream */
  readonly append: (data: T) => Effect.Effect<void, DurableStreamError>;

  /** Append multiple items */
  readonly appendBatch: (items: readonly T[]) => Effect.Effect<void, DurableStreamError>;

  /** Read from stream (catch-up or live) */
  readonly read: (
    config?: StreamReadConfig
  ) => Effect.Effect<JsonBatch<T>, DurableStreamError>;

/** Read from stream (catch-up or live) */
  readonly read: (
    config?: StreamReadConfig
  ) => Effect.Effect<JsonBatch<T>, DurableStreamError>;

  /** Subscribe to live updates as an Effect Stream */
  readonly subscribe: (
    config?: StreamReadConfig
  ) => Effect.Effect<Stream.Stream<JsonBatch<T>, DurableStreamError>, DurableStreamError, Scope.Scope>;

  /** Get stream metadata via HEAD */
  readonly head: () => Effect.Effect<StreamMetadata, DurableStreamError>;

  /** Delete the stream */
  readonly delete: () => Effect.Effect<void, DurableStreamError>;

  /** Get the raw handle (for advanced use) */
  readonly raw: () => DurableStreamHandle;
}

// ============================================================================
// Service Interface
// ============================================================================

/**
 * Durable Stream Client Service interface
 */
export interface DurableStreamClientShape {
  /**
   * Create a new stream (fails if exists)
   */
  readonly create: <T = unknown>(
    config: StreamCreateConfig
  ) => Effect.Effect<EffectStreamHandle<T>, DurableStreamError>;

  /**
   * Connect to an existing stream (fails if not exists)
   */
  readonly connect: <T = unknown>(
    config: StreamConnectConfig
  ) => Effect.Effect<EffectStreamHandle<T>, DurableStreamError>;

  /**
   * Get or create a stream (upsert semantics)
   */
  readonly getOrCreate: <T = unknown>(
    config: StreamCreateConfig
  ) => Effect.Effect<EffectStreamHandle<T>, DurableStreamError>;

  /**
   * Check if a stream exists
   */
  readonly exists: (url: string) => Effect.Effect<boolean, DurableStreamError>;

  /**
   * Delete a stream by URL
   */
  readonly delete: (url: string) => Effect.Effect<void, DurableStreamError>;
}

// ============================================================================
// Service Tag
// ============================================================================

/**
   * Delete a stream by URL
   */
  readonly delete: (url: string) => Effect.Effect<void, DurableStreamError>;
}

// ============================================================================
// Service Tag
// ============================================================================

export class DurableStreamClient extends Context.Tag('tmnl/durable-streams/DurableStreamClient')<
  DurableStreamClient,
  DurableStreamClientShape
>() {}

// ============================================================================
// Configuration Tag
// ============================================================================

export interface DurableStreamClientConfig {
  /** Base URL for streams (optional, can use full URLs) */
  baseUrl?: string;
  /** Default headers for all requests */
  headers?: Record<string, string>;
  /** Default content type for new streams */
  defaultContentType?: string;
}

export class DurableStreamClientConfigTag extends Context.Tag(
  'tmnl/durable-streams/DurableStreamClientConfig'
)<DurableStreamClientConfigTag, DurableStreamClientConfig>() {}

// ============================================================================
// Helper: Wrap Handle
// ============================================================================

const wrapHandle = <T>(handle: DurableStreamHandle): EffectStreamHandle<T> => ({
  url: handle.url,
  contentType: handle.contentType,

  append: (data: T) =>
    Effect.tryPromise({
      try: () => handle.append(data),
      catch: (e) =>
        new DurableStreamError(
          (e as any)?.code ?? 'APPEND_ERROR',
          (e as Error).message,
          handle.url
        ),
    }),

  appendBatch: (items: readonly T[]) =>
    Effect.forEach(items, (item) =>
      Effect.tryPromise({
        try: () => handle.append(item),
        catch: (e) =>
          new DurableStreamError(
            (e as any)?.code ?? 'APPEND_ERROR',
            (e as Error).message,
            handle.url
          ),
      })
    ).pipe(Effect.asVoid),

read: (config?: StreamReadConfig) =>
    Effect.tryPromise({
      try: async () => {
        const res = await handle.stream({
          offset: config?.offset ?? '-1',
          live: config?.live ?? false,
          json: config?.json ?? true,
        });
        const items = await res.json();
        return {
          items: items as readonly T[],
          offset: res.offset,
          upToDate: res.upToDate,
        };
      },
      catch: (e) =>
        new DurableStreamError(
          (e as any)?.code ?? 'READ_ERROR',
          (e as Error).message,
          handle.url
        ),
    }),

  subscribe: (config?: StreamReadConfig) =>
    Effect.gen(function* () {
      const pubsub = yield* PubSub.unbounded<JsonBatch<T>>();

      // Start the subscription in a fiber
      yield* Effect.forkScoped(
        Effect.tryPromise({
          try: async () => {
            const res = await handle.stream({
              offset: config?.offset ?? '-1',
              live: config?.live ?? 'auto',
              json: config?.json ?? true,
            });

            // Use subscribeJson for live updates
            res.subscribeJson(async (batch: { items: T[]; offset: string; upToDate: boolean }) => {
              await Effect.runPromise(
                PubSub.publish(pubsub, {
                  items: batch.items as readonly T[],
                  offset: batch.offset,
                  upToDate: batch.upToDate,
                })
              );
            });

            // Keep alive until aborted
            await new Promise(() => {});
          },
          catch: (e) =>
            new DurableStreamError(
              (e as any)?.code ?? 'SUBSCRIBE_ERROR',
              (e as Error).message,
              handle.url
            ),
        })
      );

      // Return a stream from the pubsub
      return pipe(
        Stream.fromPubSub(pubsub),
        Stream.mapError(
          () => new DurableStreamError('SUBSCRIBE_ERROR', 'PubSub error', handle.url)
        )
      );
    }),

head: () =>
    Effect.tryPromise({
      try: () => handle.head(),
      catch: (e) =>
        new DurableStreamError(
          (e as any)?.code ?? 'HEAD_ERROR',
          (e as Error).message,
          handle.url
        ),
    }),

  delete: () =>
    Effect.tryPromise({
      try: () => handle.delete(),
      catch: (e) =>
        new DurableStreamError(
          (e as any)?.code ?? 'DELETE_ERROR',
          (e as Error).message,
          handle.url
        ),
    }),

  raw: () => handle,
});

// ============================================================================
// Live Implementation
// ============================================================================

export const DurableStreamClientLive = Layer.effect(
  DurableStreamClient,
  Effect.gen(function* () {
    // Dynamic import to avoid bundling issues
    const { DurableStream } = yield* Effect.tryPromise({
      try: () => import('@durable-streams/client'),
      catch: () =>
        new DurableStreamError('IMPORT_ERROR', 'Failed to import @durable-streams/client'),
    });

    // Try to get config, default to empty if not provided
    const config = yield* Effect.serviceOption(DurableStreamClientConfigTag);
    const baseConfig = config.pipe(
      Effect.getOrElse(() => ({})),
      Effect.runSync
    );

    return {
      create: <T = unknown>(streamConfig: StreamCreateConfig) =>
        Effect.tryPromise({
          try: () =>
            DurableStream.create({
              url: streamConfig.url,
              contentType: streamConfig.contentType ?? baseConfig.defaultContentType,
              headers: baseConfig.headers,
              ttlSeconds: streamConfig.ttlSeconds,
              expiresAt: streamConfig.expiresAt,
              body: streamConfig.body,
            }),
          catch: (e) =>
            new DurableStreamError(
              (e as any)?.code ?? 'CREATE_ERROR',
              (e as Error).message,
              streamConfig.url
            ),
        }).pipe(Effect.map((handle) => wrapHandle<T>(handle))),

connect: <T = unknown>(streamConfig: StreamConnectConfig) =>
        Effect.tryPromise({
          try: () =>
            DurableStream.connect({
              url: streamConfig.url,
              headers: { ...baseConfig.headers, ...streamConfig.headers },
            }),
          catch: (e) =>
            new DurableStreamError(
              (e as any)?.code ?? 'CONNECT_ERROR',
              (e as Error).message,
              streamConfig.url
            ),
        }).pipe(Effect.map((handle) => wrapHandle<T>(handle))),

      getOrCreate: <T = unknown>(streamConfig: StreamCreateConfig) =>
        Effect.gen(function* () {
          // Try to connect first
          const connectResult = yield* Effect.tryPromise({
            try: () =>
              DurableStream.connect({
                url: streamConfig.url,
                headers: baseConfig.headers,
              }),
            catch: (e) => e as Error,
          }).pipe(Effect.either);

          if (connectResult._tag === 'Right') {
            return wrapHandle<T>(connectResult.right);
          }

          // If connect failed, try to create
          const handle = yield* Effect.tryPromise({
            try: () =>
              DurableStream.create({
                url: streamConfig.url,
                contentType: streamConfig.contentType ?? baseConfig.defaultContentType,
                headers: baseConfig.headers,
                ttlSeconds: streamConfig.ttlSeconds,
                expiresAt: streamConfig.expiresAt,
                body: streamConfig.body,
              }),
            catch: (e) =>
              new DurableStreamError(
                (e as any)?.code ?? 'GET_OR_CREATE_ERROR',
                (e as Error).message,
                streamConfig.url
              ),
          });

          return wrapHandle<T>(handle);
        }),

return wrapHandle<T>(handle);
        }),

      exists: (url: string) =>
        Effect.tryPromise({
          try: async () => {
            const handle = new DurableStream({ url, headers: baseConfig.headers });
            await handle.head();
            return true;
          },
          catch: (e) => {
            // If it's a 404, stream doesn't exist
            if ((e as any)?.code === 'NOT_FOUND') {
              return false;
            }
            throw new DurableStreamError(
              (e as any)?.code ?? 'EXISTS_ERROR',
              (e as Error).message,
              url
            );
          },
        }).pipe(
          Effect.catchAll((e) => {
            if (e === false) return Effect.succeed(false);
            return Effect.fail(e as DurableStreamError);
          })
        ),

      delete: (url: string) =>
        Effect.tryPromise({
          try: () => DurableStream.delete({ url, headers: baseConfig.headers }),
          catch: (e) =>
            new DurableStreamError(
              (e as any)?.code ?? 'DELETE_ERROR',
              (e as Error).message,
              url
            ),
        }),
    };
  })
);

