        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        className="w-full p-4 bg-neutral-950 font-mono text-sm text-neutral-200 outline-none resize-none min-h-[100px]"
        placeholder="// Enter code..."
        spellCheck={false}
