    tag: "SelectionChanged",
    primaryKey: (p) => p.documentId,
    payload: Schema.Struct({
      documentId: DocumentId,
      // Selection is complex, store as JSON for now
      selection: Schema.NullOr(Schema.Unknown),
      timestamp: Schema.Number,
    }),
  })

