/**
 * EventLog Handlers
 *
 * Event handlers that update EditorService state when events are processed.
 * Each handler receives { payload, entry, conflicts } and calls existing service methods.
 *
 * @module editor/events/handlers
 */

import { EventLog } from "@effect/experimental"
import * as Effect from "effect/Effect"
import { EditorService } from "../services/EditorService"
import { BlockEvents } from "./block"
import { DocumentEvents, HistoryEvents } from "./document"

// ─────────────────────────────────────────────────────────────
// Block Handlers
// ─────────────────────────────────────────────────────────────

/**
 * Handlers for BlockEvents.
 * Block CRUD operations that update document state.
 */
export const BlockHandlersLive = EventLog.group(BlockEvents, (handlers) =>
  handlers
    .handle("BlockAdded", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.addBlock(payload.block, payload.afterId ?? undefined)
      })
    )
    .handle("BlockUpdated", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.updateBlock(payload.id, () => payload.updated)
      })
    )
    .handle("BlockDeleted", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.deleteBlock(payload.id)
      })
    )
    .handle("BlockMoved", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.moveBlock(payload.id, payload.toAfterId)
      })
    )
)

// ─────────────────────────────────────────────────────────────
// Document Handlers
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Document Handlers
// ─────────────────────────────────────────────────────────────

/**
 * Handlers for DocumentEvents.
 * Document lifecycle operations.
 */
export const DocumentHandlersLive = EventLog.group(DocumentEvents, (handlers) =>
  handlers
    .handle("DocumentCreated", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.createNew(payload.title)
      })
    )
    .handle("DocumentLoaded", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.loadDocument(payload.document)
      })
    )
    .handle("ModeChanged", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.setMode(payload.current)
      })
    )
    .handle("SelectionChanged", ({ payload }) =>
      Effect.gen(function* () {
        const editor = yield* EditorService
        yield* editor.setSelection(payload.selection as any)
      })
    )
)

// ─────────────────────────────────────────────────────────────
// History Handlers
// ─────────────────────────────────────────────────────────────

/**
 * Handlers for HistoryEvents.
 * These are audit events - the actual undo/redo is handled differently.
 */
export const HistoryHandlersLive = EventLog.group(HistoryEvents, (handlers) =>
  handlers
    .handle("UndoPerformed", () =>
      // Audit event only - undo logic handled by service
      Effect.void
    )
    .handle("RedoPerformed", () =>
      // Audit event only - redo logic handled by service
      Effect.void
    )
)

/**
 * Editor EventLog Integration
 *
 * Event definitions, handlers, and reactivity for the block editor.
 * Enables event sourcing, undo/redo, and real-time sync.
 *
 * @module editor/events
 */

import { EventLog } from "@effect/experimental"

// Events
export * from "./block"
export * from "./document"

// Handlers
export * from "./handlers"

// Reactivity
export * from "./reactivity"

// ─────────────────────────────────────────────────────────────
// EventLog Schema
// ─────────────────────────────────────────────────────────────

import { BlockEvents } from "./block"
import { DocumentEvents, HistoryEvents } from "./document"

/**
 * Combined EventLog schema for all editor events.
 * Used to create the EventLog layer.
 */
export const EditorEventLogSchema = EventLog.schema(
  BlockEvents,
  DocumentEvents,
  HistoryEvents
)

/**
 * Reactivity Keys
 *
 * Keys for Reactivity.stream() auto-invalidation.
 * When events are processed, associated keys are invalidated,
 * causing subscribed atoms to refresh.
 *
 * @module editor/events/reactivity
 */

import { EventLog, Reactivity } from "@effect/experimental"
import { BlockEvents } from "./block"
import { DocumentEvents, HistoryEvents } from "./document"

// ─────────────────────────────────────────────────────────────
// Reactivity Keys
// ─────────────────────────────────────────────────────────────

export const Keys = {
  /** Invalidate when blocks change (add, update, delete, move) */
  blocks: "editor:blocks",

  /** Invalidate when document changes (create, load) */
  document: "editor:document",

  /** Invalidate when selection changes */
  selection: "editor:selection",

  /** Invalidate when mode changes */
  mode: "editor:mode",

  /** Invalidate when history changes (undo/redo) */
  history: "editor:history",
} as const

// ─────────────────────────────────────────────────────────────
// Reactivity Bindings
// ─────────────────────────────────────────────────────────────

/**
 * Block event reactivity.
 * All block events invalidate the blocks key.
 */
export const BlockReactivityLive = EventLog.groupReactivity(BlockEvents, (register) =>
  register
    .keys("BlockAdded", () => [Keys.blocks, Keys.document])
    .keys("BlockUpdated", () => [Keys.blocks])
    .keys("BlockDeleted", () => [Keys.blocks, Keys.document])
    .keys("BlockMoved", () => [Keys.blocks])
)

/**
 * Document event reactivity.
 */
export const DocumentReactivityLive = EventLog.groupReactivity(DocumentEvents, (register) =>
  register
    .keys("DocumentCreated", () => [Keys.document, Keys.blocks])
    .keys("DocumentLoaded", () => [Keys.document, Keys.blocks, Keys.selection, Keys.mode])
    .keys("ModeChanged", () => [Keys.mode])
    .keys("SelectionChanged", () => [Keys.selection])
)

