  focus: number
): TextSelection => ({
  _tag: "TextSelection",
  blockId,
  anchor,
  focus,
});

/**
 * Create a block selection
 */
export const createBlockSelection = (blockIds: BlockId[]): BlockSelection => ({
  _tag: "BlockSelection",
