);

/**
 * Create a custom runtime with specific config.
 */
export const createCollaborationRuntime = (config: CollaborationConfig) =>
  Atom.runtime(
    Layer.mergeAll(
      CollaborationService.Default.pipe(
        Layer.provide(CollaborationConfigTag.Custom(config))
      )
