interface ToolbarContentProps {
  editor: Editor;
  selectedStyle: 'highlight' | 'pill' | 'squiggle' | 'underline';
  selectedColor: string;
  onColorChange: (color: string) => void;
  onAnnotate?: AnnotationToolbarProps['onAnnotate'];
  className?: string;
