export function FileDrawer({
  isOpen,
  onClose,
  onSelectLocalFile,
  onSelectCloudDoc,
  onCreateNew,
  onBrowseFiles,
  onRefresh,
  localFiles = [],
  cloudDocs = [],
  currentPath,
  currentDocId,
  isLoading = false,
}: FileDrawerProps) {
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState<SourceTab>('all');

  // Transform local files to unified entries
  const localEntries = useMemo<UnifiedFileEntry[]>(() => {
    return localFiles.map((file) => ({
      id: `local:${file.path}`,
      type: file.mapping ? 'mapped' : 'local',
      title: file.name,
      subtitle: truncatePath(file.path),
      modifiedAt: file.modifiedAt,
      syncStatus: file.mapping?.syncStatus,
      localFile: file,
    }));
  }, [localFiles]);

  // Transform cloud docs to unified entries
  const cloudEntries = useMemo<UnifiedFileEntry[]>(() => {
    return cloudDocs.map((doc) => ({
      id: `cloud:${doc.id}`,
      type: 'cloud',
      title: doc.title,
      subtitle: (doc.id as string).slice(0, 16) + '...',
      modifiedAt: doc.updatedAt,
      createdAt: doc.createdAt,
      cloudDoc: doc,
    }));
  }, [cloudDocs]);

  // Combined and filtered entries
  const allEntries = useMemo<UnifiedFileEntry[]>(() => {
    let entries: UnifiedFileEntry[] = [];

    if (activeTab === 'all' || activeTab === 'local') {
      entries = [...entries, ...localEntries];
    }
    if (activeTab === 'all' || activeTab === 'cloud') {
      entries = [...entries, ...cloudEntries];
    }

// Filter by search
    if (search) {
      const lower = search.toLowerCase();
      entries = entries.filter(
        (e) =>
          e.title.toLowerCase().includes(lower) ||
          e.subtitle.toLowerCase().includes(lower)
      );
    }

    // Sort by modified date (newest first)
    entries.sort((a, b) => b.modifiedAt.getTime() - a.modifiedAt.getTime());

    return entries;
  }, [localEntries, cloudEntries, activeTab, search]);

  const handleSelect = useCallback(
    (entry: UnifiedFileEntry) => {
      if (entry.localFile) {
        onSelectLocalFile(entry.localFile.path);
      } else if (entry.cloudDoc) {
        onSelectCloudDoc(entry.cloudDoc.id as string);
      }
      onClose();
    },
    [onSelectLocalFile, onSelectCloudDoc, onClose]
  );

  const isEntryActive = useCallback(
    (entry: UnifiedFileEntry): boolean => {
      if (entry.localFile && currentPath) {
        return entry.localFile.path === currentPath;
      }
      if (entry.cloudDoc && currentDocId) {
        return entry.cloudDoc.id === currentDocId;
      }
      return false;
    },
    [currentPath, currentDocId]
  );

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            style={{
              position: 'absolute',
              inset: 0,
              backgroundColor: 'rgba(0, 0, 0, 0.4)',
              backdropFilter: 'blur(2px)',
              zIndex: 10,
            }}
          />

{/* Drawer */}
          <motion.div
            initial={{ x: '-100%', opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: '-100%', opacity: 0 }}
            transition={{ type: 'spring', stiffness: 400, damping: 35 }}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              bottom: 0,
              width: 320,
              backgroundColor: COLORS.bg.primary,
              borderRight: `1px solid ${COLORS.border}`,
              display: 'flex',
              flexDirection: 'column',
              zIndex: 20,
              fontFamily: 'Inter, system-ui, sans-serif',
            }}
          >
            {/* Header */}
            <div
              style={{
                padding: '12px 16px',
                borderBottom: `1px solid ${COLORS.border}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <FileText size={14} color={COLORS.accent.cyan} />
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: COLORS.text.primary,
                  }}
                >
                  Open File
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                {onRefresh && (
                  <button
                    onClick={onRefresh}
                    disabled={isLoading}
                    style={{
                      background: 'none',
                      border: 'none',
                      color: COLORS.text.muted,
                      cursor: 'pointer',
                      padding: 4,
                      display: 'flex',
                      opacity: isLoading ? 0.5 : 0.7,
                      transition: 'opacity 0.15s',
                    }}
                    title="Refresh"
                  >
                    <RefreshCw
                      size={14}
                      className={isLoading ?

0.5 : 0.7,
                      transition: 'opacity 0.15s',
                    }}
                    title="Refresh"
                  >
                    <RefreshCw
                      size={14}
                      className={isLoading ? 'animate-spin' : ''}
                    />
                  </button>
                )}
                <button
                  onClick={onClose}
                  style={{
                    background: 'none',
                    border: 'none',
                    color: COLORS.text.muted,
                    cursor: 'pointer',
                    padding: 4,
                    display: 'flex',
                    opacity: 0.7,
                  }}
                >
                  <X size={14} />
                </button>
              </div>
            </div>

            {/* Tabs */}
            <div
              style={{
                display: 'flex',
                borderBottom: `1px solid ${COLORS.border}`,
              }}
            >
              <TabButton
                active={activeTab === 'all'}
                onClick={() => setActiveTab('all')}
                icon={<FileText size={12} />}
                label="All"
                count={localEntries.length + cloudEntries.length}
              />
              <TabButton
                active={activeTab === 'local'}
                onClick={() => setActiveTab('local')}
                icon={<HardDrive size={12} />}
                label="Local"
                count={localEntries.length}
              />
              <TabButton
                active={activeTab === 'cloud'}
                onClick={() => setActiveTab('cloud')}
                icon={<Cloud size={12} />}
                label="Cloud"
                count={cloudEntries.length}
              />
            </div>

{/* Search */}
            <div style={{ padding: '12px 16px' }}>
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  padding: '8px 12px',
                  backgroundColor: COLORS.bg.input,
                  borderRadius: 6,
                  border: `1px solid ${COLORS.border}`,
                }}
              >
                <Search size={14} color={COLORS.text.muted} />
                <input
                  type="text"
                  placeholder="Search files..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  style={{
                    flex: 1,
                    background: 'none',
                    border: 'none',
                    outline: 'none',
                    color: COLORS.text.primary,
                    fontSize: 12,
                  }}
                />
                {search && (
                  <button
                    onClick={() => setSearch('')}
                    style={{
                      background: 'none',
                      border: 'none',
                      color: COLORS.text.muted,
                      cursor: 'pointer',
                      padding: 0,
                      display: 'flex',
                    }}
                  >
                    <X size={12} />
                  </button>
                )}
              </div>
            </div>

{/* File List */}
            <div
              style={{
                flex: 1,
                overflowY: 'hidden',
                padding: '0 16px 16px',
                display: 'flex',
                flexDirection: 'column',
              }}
            >
              {isLoading ? (
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 12,
                    padding: 32,
                    color: COLORS.text.muted,
                  }}
                >
                  <RefreshCw size={20} className="animate-spin" />
                  <span style={{ fontSize: 12 }}>Loading files...</span>
                </div>
              ) : allEntries.length === 0 ? (
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 12,
                    padding: 32,
                    color: COLORS.text.muted,
                  }}
                >
                  <CloudOff size={24} style={{ opacity: 0.5 }} />
                  <span style={{ fontSize: 12 }}>
                    {search ? 'No matching files' : 'No files yet'}
                  </span>
                </div>
              ) : (
                <VirtualizedFileList
                  entries={allEntries}
                  isEntryActive={isEntryActive}
                  onSelect={handleSelect}
                />
              )}
            </div>

{/* Footer hint */}
            <div
              style={{
                padding: '8px 16px',
                borderTop: `1px solid ${COLORS.border}`,
                backgroundColor: COLORS.bg.secondary,
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 12,
                  fontSize: 10,
                  color: COLORS.text.muted,
                }}
              >
                <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <HardDrive size={10} /> Local
                </span>
                <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <Cloud size={10} /> Cloud
                </span>
                <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <Link2 size={10} /> Mapped
                </span>
              </div>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

