/**
 * FormattingToolbar
 *
 * Text formatting toolbar for the block editor.
 * Stacks below ContextualToolbar to provide formatting controls.
 *
 * Uses VANTA design tokens and follows compound component pattern.
 *
 * @module editor/v3/components/FormattingToolbar
 */

import { forwardRef, createContext, useContext, type ReactNode } from 'react';
import { motion } from 'framer-motion';
import * as Tooltip from '@radix-ui/react-tooltip';
import type { Editor } from '@tiptap/core';

import {
  VANTA_COLORS,
  VANTA_TYPOGRAPHY,
  VANTA_SPACING,
  VANTA_BORDERS,
  VANTA_ANIMATION,
} from '@/components/portal/tokens';

// =============================================================================
// Context
// =============================================================================

interface FormattingToolbarContextValue {
  editor: Editor | null;
}

const FormattingToolbarContext =
  createContext<FormattingToolbarContextValue | null>(null);

function useFormattingToolbar() {
  const context = useContext(FormattingToolbarContext);
  if (!context) {
    throw new Error(
      'FormattingToolbar components must be used within FormattingToolbar.Root'
    );
  }
  return context;
}

// =============================================================================
// Root
// =============================================================================

interface FormattingToolbarRootProps {
  editor: Editor | null;
  children: ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const FormattingToolbarRoot = forwardRef<
  HTMLDivElement,
  FormattingToolbarRootProps
>(function FormattingToolbarRoot({ editor, children, className, style }, ref) {
  // Bail early if no editor or editor is destroyed — prevents wasted renders
  if (!editor || editor.isDestroyed) return null;

return (
    <FormattingToolbarContext.Provider value={{ editor }}>
      <Tooltip.Provider delayDuration={300}>
        <motion.div
          ref={ref}
          initial={{ opacity: 0, y: -4 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.15 }}
          className={className}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: VANTA_SPACING['1'],
            padding: `${VANTA_SPACING['1']} ${VANTA_SPACING['2']}`,
            backgroundColor: VANTA_COLORS.surface.elevated,
            borderRadius: VANTA_BORDERS.radius.md,
            border: VANTA_BORDERS.style.hairline,
            backdropFilter: 'blur(12px)',
            ...style,
          }}
        >
          {children}
        </motion.div>
      </Tooltip.Provider>
    </FormattingToolbarContext.Provider>
  );
});

// =============================================================================
// Button
// =============================================================================

interface FormattingButtonProps {
  icon: ReactNode;
  label: string;
  shortcut?: string;
  active?: boolean;
  disabled?: boolean;
  onClick?: () => void;
}

function FormattingButton({
  icon,
  label,
  shortcut,
  active = false,
  disabled = false,
  onClick,
}: FormattingButtonProps) {
  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>
        <motion.button
          whileHover={{ scale: disabled ? 1 : 1.05 }}
          whileTap={{ scale: disabled ? 1 : 0.95 }}
          onClick={disabled ? undefined : onClick}
          aria-label={label}
          aria-pressed={active}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 28,
            height: 28,
            padding: 0,
            borderRadius: VANTA_BORDERS.radius.sm,
            border: 'none',
            backgroundColor: active
              ? VANTA_COLORS.surface.raised
              : 'transparent',
            color: active
              ?

VANTA_COLORS.surface.raised
              : 'transparent',
            color: active
              ? VANTA_COLORS.accent.cyan
              : VANTA_COLORS.text.secondary,
            cursor: disabled ? 'not-allowed' : 'pointer',
            opacity: disabled ? 0.4 : 1,
            transition: VANTA_ANIMATION.transition.colors,
          }}
        >
          {icon}
        </motion.button>
      </Tooltip.Trigger>
      <Tooltip.Portal>
        <Tooltip.Content
          sideOffset={6}
          style={{
            padding: `${VANTA_SPACING['1']} ${VANTA_SPACING['2']}`,
            backgroundColor: VANTA_COLORS.surface.base,
            border: VANTA_BORDERS.style.default,
            borderRadius: VANTA_BORDERS.radius.sm,
            boxShadow: VANTA_BORDERS.shadow.elevated,
            ...VANTA_TYPOGRAPHY.preset.micro,
            color: VANTA_COLORS.text.primary,
            display: 'flex',
            alignItems: 'center',
            gap: VANTA_SPACING['2'],
            zIndex: 9999,
          }}
        >
          <span>{label}</span>
          {shortcut && (
            <span style={{ color: VANTA_COLORS.text.muted }}>{shortcut}</span>
          )}
        </Tooltip.Content>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

