import React, { useMemo, useCallback, useContext } from 'react';
import { useAtomValue, RegistryContext } from '@effect-atom/atom-react';
import {
  zoomLabelAtom,
  canZoomInAtom,
  canZoomOutAtom,
  createZoomOps,
} from '../atoms/viewport';

// =============================================================================
// Types
// =============================================================================

export interface ZoomControlsProps {
  /** Custom class name */
  className?: string;
  /** Custom styles */
  style?: React.CSSProperties;
  /** Compact mode (icon-only) */
  compact?: boolean;
}

// =============================================================================
// Styles
