      const popoverService = yield* AnnotationPopoverService;
      yield* popoverService.pin;

      ctx.set(activePopoverAtom, (prev) =>
        prev ? { ...prev, isPinned: true } : null
      );
    })
  ),

ctx.set(activePopoverAtom, (prev) =>
