const INTENT_TYPES = [
  { key: 'Hyperlink', label: 'Links', icon: '🔗' },
  { key: 'Ultralink', label: 'Docs', icon: '📄' },
  { key: 'Popover', label: 'Popovers', icon: '💬' },
  { key: 'Action', label: 'Actions', icon: '⚡' },
  { key: 'Citation', label: 'Citations', icon: '📚' },
