export function FilterPanel({
  className = '',
  defaultExpanded = false,
  onFilterChange,
  showVisibilityControls = true,
  showStats = true,
}: FilterPanelProps) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded);
  const [selectedIntentTypes, setSelectedIntentTypes] = useState<Set<string>>(new Set());
  const [selectedStyles, setSelectedStyles] = useState<Set<string>>(new Set());
  const [selectedCreatedBy, setSelectedCreatedBy] = useState<Set<string>>(new Set());
  const [tagInput, setTagInput] = useState('');
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  const stats = useAtomValue(markStatsAtom);
  const totalCount = useAtomValue(markCountAtom);
  const visibleIds = useAtomValue(visibleMarkIdsAtom);
  const activeQuery = useAtomValue(activeQueryAtom);
  const globalVisible = useAtomValue(globalVisibilityAtom);

  const visibleCount = visibleIds.size;
  const hiddenCount = totalCount - visibleCount;
  const hasActiveFilter = activeQuery !== null;

  // Build query from selections
  const buildQuery = useCallback((): AnnotationQuery | null => {
    const intentTypes = Array.from(selectedIntentTypes);
    const visualStyles = Array.from(selectedStyles);
    const createdBy = Array.from(selectedCreatedBy);

    if (
      intentTypes.length === 0 &&
      visualStyles.length === 0 &&
      createdBy.length === 0 &&
      selectedTags.length === 0
    ) {
      return null;
    }

    return {
      intentTypes: intentTypes.length > 0 ? intentTypes : undefined,
      visualStyles: visualStyles.length > 0 ? visualStyles : undefined,
      createdBy: createdBy.length > 0 ? (createdBy[0] as 'user' | 'agent' | 'system') : undefined,
      tags: selectedTags.length > 0 ? selectedTags : undefined,
    };
  }, [selectedIntentTypes, selectedStyles, selectedCreatedBy, selectedTags]);

// Apply filter
  const applyFilter = useCallback(async () => {
    const query = buildQuery();
    if (query) {
      await queryOps.applyFilter({ query });
    } else {
      await queryOps.clearFilter();
    }
    onFilterChange?.(query);
  }, [buildQuery, onFilterChange]);

  // Clear filter
  const clearFilter = useCallback(async () => {
    setSelectedIntentTypes(new Set());
    setSelectedStyles(new Set());
    setSelectedCreatedBy(new Set());
    setSelectedTags([]);
    await queryOps.clearFilter();
    onFilterChange?.(null);
  }, [onFilterChange]);

  // Toggle intent type
  const toggleIntentType = useCallback((type: string) => {
    setSelectedIntentTypes((prev) => {
      const next = new Set(prev);
      if (next.has(type)) {
        next.delete(type);
      } else {
        next.add(type);
      }
      return next;
    });
  }, []);

  // Toggle visual style
  const toggleStyle = useCallback((style: string) => {
    setSelectedStyles((prev) => {
      const next = new Set(prev);
      if (next.has(style)) {
        next.delete(style);
      } else {
        next.add(style);
      }
      return next;
    });
  }, []);

  // Toggle created by
  const toggleCreatedBy = useCallback((source: string) => {
    setSelectedCreatedBy((prev) => {
      const next = new Set(prev);
      if (next.has(source)) {
        next.delete(source);
      } else {
        // Single select for created by
        next.clear();
        next.add(source);
      }
      return next;
    });
  }, []);

  // Add tag
  const addTag = useCallback(() => {
    const tag = tagInput.trim();
    if (tag && !selectedTags.includes(tag)) {
      setSelectedTags((prev) => [...prev, tag]);
      setTagInput('');
    }
  }, [tagInput, selectedTags]);

// Remove tag
  const removeTag = useCallback((tag: string) => {
    setSelectedTags((prev) => prev.filter((t) => t !== tag));
  }, []);

  // Stats by intent type
  const intentStats = useMemo(() => {
    const result: Record<string, number> = {};
    for (const { key } of INTENT_TYPES) {
      result[key] = stats.byIntentType.get(key) ?? 0;
    }
    return result;
  }, [stats.byIntentType]);

  return (
    <div
      className={`rounded-lg border border-tmnl-border bg-tmnl-surface-1 ${className}`}
    >
      {/* Header */}
      <button
        className="flex w-full items-center justify-between px-3 py-2 text-sm font-medium text-tmnl-text-primary hover:bg-tmnl-surface-2 transition-colors rounded-t-lg"
        onClick={() => setIsExpanded(!isExpanded)}
        type="button"
      >
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-tmnl-accent-primary" />
          <span>Annotation Filters</span>
          {hasActiveFilter && (
            <span className="inline-flex items-center rounded-full bg-tmnl-accent-primary/20 px-2 py-0.5 text-xs text-tmnl-accent-primary">
              Active
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          {showStats && (
            <span className="text-xs text-tmnl-text-muted">
              {visibleCount}/{totalCount}
            </span>
          )}
          {isExpanded ? (
            <ChevronUp className="h-4 w-4 text-tmnl-text-muted" />
          ) : (
            <ChevronDown className="h-4 w-4 text-tmnl-text-muted" />
          )}
        </div>
      </button>

{/* Expanded content */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            animate={{ height: 'auto', opacity: 1 }}
            className="overflow-hidden"
            exit={{ height: 0, opacity: 0 }}
            initial={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
          >
            <div className="space-y-4 px-3 pb-3">
              {/* Visibility controls */}
              {showVisibilityControls && (
                <div className="flex items-center justify-between pt-2 border-t border-tmnl-border">
                  <span className="text-xs text-tmnl-text-muted">Global Visibility</span>
                  <button
                    className={`flex items-center gap-1.5 rounded-full px-2 py-1 text-xs transition-colors ${
                      globalVisible
                        ? 'bg-tmnl-accent-primary/20 text-tmnl-accent-primary'
                        : 'bg-tmnl-surface-2 text-tmnl-text-muted'
                    }`}
                    onClick={() => visibilityOps.toggleGlobal()}
                    type="button"
                  >
                    {globalVisible ? (
                      <>
                        <Eye className="h-3 w-3" />
                        <span>Visible</span>
                      </>
                    ) : (
                      <>
                        <EyeOff className="h-3 w-3" />
                        <span>Hidden</span>
                      </>
                    )}
                  </button>
                </div>
              )}

{/* Intent Type Filter */}
              <div className="space-y-2">
                <div className="flex items-center gap-1.5 text-xs text-tmnl-text-muted">
                  <Zap className="h-3 w-3" />
                  <span>Intent Type</span>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {INTENT_TYPES.map(({ key, label, icon }) => {
                    const count = intentStats[key];
                    const isSelected = selectedIntentTypes.has(key);
                    return (
                      <button
                        className={`inline-flex items-center gap-1 rounded-full px-2 py-1 text-xs transition-colors ${
                          isSelected
                            ? 'bg-tmnl-accent-primary text-tmnl-surface-0'
                            : 'bg-tmnl-surface-2 text-tmnl-text-secondary hover:bg-tmnl-surface-3'
                        }`}
                        disabled={count === 0}
                        key={key}
                        onClick={() => toggleIntentType(key)}
                        type="button"
                      >
                        <span>{icon}</span>
                        <span>{label}</span>
                        <span className="opacity-60">({count})</span>
                      </button>
                    );
                  })}
                </div>
              </div>

{/* Visual Style Filter */}
              <div className="space-y-2">
                <div className="flex items-center gap-1.5 text-xs text-tmnl-text-muted">
                  <Palette className="h-3 w-3" />
                  <span>Visual Style</span>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {VISUAL_STYLES.map(({ key, label, color }) => {
                    const count = stats.byVisualType.get(key) ?? 0;
                    const isSelected = selectedStyles.has(key);
                    return (
                      <button
                        className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-xs transition-colors ${
                          isSelected
                            ? 'bg-tmnl-accent-primary text-tmnl-surface-0'
                            : `${color} text-tmnl-text-secondary hover:brightness-110`
                        }`}
                        disabled={count === 0}
                        key={key}
                        onClick={() => toggleStyle(key)}
                        type="button"
                      >
                        <span>{label}</span>
                        <span className="opacity-60">({count})</span>
                      </button>
                    );
                  })}
                </div>
              </div>

{/* Created By Filter */}
              <div className="space-y-2">
                <div className="flex items-center gap-1.5 text-xs text-tmnl-text-muted">
                  <User className="h-3 w-3" />
                  <span>Created By</span>
                </div>
                <div className="flex gap-2">
                  {CREATED_BY.map(({ key, label, icon: Icon }) => {
                    const count = stats.byCreatedBy.get(key) ?? 0;
                    const isSelected = selectedCreatedBy.has(key);
                    return (
                      <button
                        className={`inline-flex items-center gap-1.5 rounded-md px-2 py-1.5 text-xs transition-colors ${
                          isSelected
                            ? 'bg-tmnl-accent-primary text-tmnl-surface-0'
                            : 'bg-tmnl-surface-2 text-tmnl-text-secondary hover:bg-tmnl-surface-3'
                        }`}
                        disabled={count === 0}
                        key={key}
                        onClick={() => toggleCreatedBy(key)}
                        type="button"
                      >
                        <Icon className="h-3.5 w-3.5" />
                        <span>{label}</span>
                        <span className="opacity-60">({count})</span>
                      </button>
                    );
                  })}
                </div>
              </div>

{/* Action buttons */}
              <div className="flex gap-2 pt-2 border-t border-tmnl-border">
                <button
                  className="flex-1 inline-flex items-center justify-center gap-1.5 rounded-md bg-tmnl-accent-primary px-3 py-1.5 text-xs font-medium text-tmnl-surface-0 hover:bg-tmnl-accent-primary/90 transition-colors"
                  onClick={applyFilter}
                  type="button"
                >
                  <Check className="h-3.5 w-3.5" />
                  <span>Apply Filter</span>
                </button>
                <button
                  className="inline-flex items-center justify-center gap-1.5 rounded-md bg-tmnl-surface-2 px-3 py-1.5 text-xs text-tmnl-text-secondary hover:bg-tmnl-surface-3 transition-colors"
                  onClick={clearFilter}
                  type="button"
                >
                  <X className="h-3.5 w-3.5" />
                  <span>Clear</span>
                </button>
              </div>

              {/* Hidden count */}
              {hiddenCount > 0 && (
                <div className="text-center text-xs text-tmnl-text-muted">
                  {hiddenCount} annotation{hiddenCount !== 1 ? 's' : ''} hidden by filter
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default FilterPanel;

/**
 * IntentMarkView
 *
 * React component rendered via TipTap's MarkView system.
 * Handles hover/click events to trigger the AnnotationPopover.
 *
 * @module editor/v3/extensions/annotations/components/IntentMarkView
 */

import { useCallback, useRef, useMemo } from 'react';
import { MarkViewContent, type MarkViewRendererProps } from '@tiptap/react';

import {
  annotationRegistry,
  activePopoverAtom,
  popoverContentAtom,
  hoveredAnnotationIdAtom,
} from '../atoms';
import type { AnnotationId, IntentPayload } from '../schemas';
import {
  generateVisualStyleCSSProperties,
  parseVisualStyle,
  DEFAULT_VISUAL_STYLE,
} from '../visual-style-generator';

// =============================================================================
// Intent Parser
// =============================================================================

/**
 * Safely parse intent JSON from data attribute
 */
function parseIntent(json: string | undefined | null): IntentPayload | null {
  if (!json) return null;
  try {
    const parsed = JSON.parse(json);
    if (parsed && typeof parsed._tag === 'string') {
      return parsed as IntentPayload;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Safely parse tags JSON from data attribute
 */
function parseTags(json: string | undefined | null): readonly string[] {
  if (!json) return [];
  try {
    const parsed = JSON.parse(json);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

// =============================================================================
// Types
// =============================================================================

// =============================================================================
// Types
// =============================================================================

/**
 * HTML attributes as they appear on the DOM element.
 * The extension maps `id` → `data-annotation-id`, etc.
 * HTMLAttributes uses the HTML names, not extension names.
 */
interface IntentMarkHTMLAttributes {
  'data-annotation-id'?: string | null;
  'data-visual-style'?: string;
  'data-intent'?: string | null;
  'data-tags'?: string;
  'data-created-at'?: string | null;
  'data-created-by'?: string;
  'data-references'?: string | null;
  class?: string;
  style?: string;
}

// =============================================================================
// Hover Debounce Config
// =============================================================================

const HOVER_DELAY_MS = 150; // Delay before showing popover on hover
// Note: We don't close on mouse leave - safePolygon in AnnotationPopover handles that

// =============================================================================
// Component
// =============================================================================

/**
 * Build popover content directly from intent data.
 * Used when marks aren't registered with AnnotationService.
 */
function buildPopoverContent(intentData: {
  intentType: string;
  intent: IntentPayload;
  visualType?: string;
  tags?: readonly string[];
}) {
  const { intentType, intent, tags } = intentData;

  const content: {
    title: string;
    description?: string;
    href?: string;
    actionLabel?: string;
    meta?: string;
  } = {
    title: intentType,
    meta: tags?.length ? tags.join(', ') : undefined,
  };

switch (intent._tag) {
    case 'Hyperlink':
      content.title = intent.label ?? 'Link';
      content.href = intent.href;
      content.actionLabel = 'Open Link';
      break;
    case 'Ultralink':
      content.title = intent.metadata?.title ?? 'Ultralink';
      content.description = intent.metadata?.description ?? `→ ${intent.target}`;
      break;
    case 'Popover':
      content.title = 'Popover';
      content.description =
        typeof intent.content === 'string' ? intent.content : JSON.stringify(intent.content);
      break;
    case 'Action':
      content.title = intent.actionName ?? 'Action';
      content.actionLabel = 'Execute';
      break;
    case 'Citation':
      content.title = 'Citation';
      content.description = intent.source ?? undefined;
      break;
    case 'Note':
      content.title = intent.noteType === 'comment' ? 'Comment' : 'Note';
      content.description = `Note: ${intent.targetNodeId}`;
      break;
  }

  return content;
}

export function IntentMarkView(props: MarkViewRendererProps) {
  const { HTMLAttributes } = props;
  const attrs = HTMLAttributes as unknown as IntentMarkHTMLAttributes;

  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const spanRef = useRef<HTMLSpanElement>(null);

  // Parse the annotation ID - use HTML attribute name (data-annotation-id)
  const annotationId = attrs['data-annotation-id'] as AnnotationId | null;

  // Parse intent and tags from data attributes - memoized for stability
  const intentData = useMemo(() => {
    const intent = parseIntent(attrs['data-intent']);
    if (!intent) return undefined;

    const visualStyle = parseVisualStyle(attrs['data-visual-style']);
    const tags = parseTags(attrs['data-tags']);

const visualStyle = parseVisualStyle(attrs['data-visual-style']);
    const tags = parseTags(attrs['data-tags']);

    return {
      intentType: intent._tag,
      intent,
      visualType: visualStyle?.type,
      tags,
    };
  }, [attrs['data-intent'], attrs['data-visual-style'], attrs['data-tags']]);

  // Handle mouse enter - show popover after delay
  const handleMouseEnter = useCallback(() => {
    if (!annotationId) return;

    // Set hover state immediately for CSS effects
    annotationRegistry.set(hoveredAnnotationIdAtom, annotationId);

    // Delay popover show for better UX
    hoverTimeoutRef.current = setTimeout(() => {
      if (!spanRef.current) return;

      const rect = spanRef.current.getBoundingClientRect();

      // Set atoms directly via registry - no Effect needed!
      annotationRegistry.set(activePopoverAtom, {
        annotationId,
        markId: annotationId,
        placement: 'top',
        trigger: 'hover',
        isPinned: false,
        anchorRect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
      });

      // Build and set content directly
      if (intentData) {
        annotationRegistry.set(popoverContentAtom, buildPopoverContent(intentData));
      }
    }, HOVER_DELAY_MS);
  }, [annotationId, intentData]);

  // Handle mouse leave - just cancel pending open, safePolygon handles closing
  const handleMouseLeave = useCallback(() => {
    // Clear any pending hover timeout (if we leave before popover opens)
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current);
      hoverTimeoutRef.current = null;
    }

    // Clear CSS hover state
    annotationRegistry.set(hoveredAnnotationIdAtom, null);

// Clear CSS hover state
    annotationRegistry.set(hoveredAnnotationIdAtom, null);

    // Note: We do NOT close the popover here!
    // safePolygon in AnnotationPopover handles closing via document mousemove
    // This allows user to move cursor from trigger to popover without closing
  }, []);

  // Handle click - toggle popover (pinned mode)
  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      if (!annotationId || !spanRef.current) return;

      // Prevent editor from handling click
      e.stopPropagation();

      const rect = spanRef.current.getBoundingClientRect();

      // Check if this popover is already open - toggle it
      const current = annotationRegistry.get(activePopoverAtom);
      if (current?.annotationId === annotationId) {
        // Close it
        annotationRegistry.set(activePopoverAtom, null);
        annotationRegistry.set(popoverContentAtom, null);
      } else {
        // Open it (pinned)
        annotationRegistry.set(activePopoverAtom, {
          annotationId,
          markId: annotationId,
          placement: 'top',
          trigger: 'click',
          isPinned: true,
          anchorRect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
        });

        if (intentData) {
          annotationRegistry.set(popoverContentAtom, buildPopoverContent(intentData));
        }
      }
    },
    [annotationId, intentData]
  );

  // Parse visual style for rendering - use centralized parser
  const visualStyle = parseVisualStyle(attrs['data-visual-style']) ?? DEFAULT_VISUAL_STYLE;

  // Build class names
  const classNames = ['intent-mark', `intent-mark--${visualStyle.type}`];
  if (visualStyle.effect && visualStyle.effect !== 'none') {
    classNames.push(`intent-mark--effect-${visualStyle.effect}`);
  }
  if (visualStyle.animated) {
    classNames.push('intent-mark--animated');
  }

// Get visual styles from centralized generator
  const visualStyles = generateVisualStyleCSSProperties(visualStyle);

  return (
    <span
      ref={spanRef}
      className={classNames.join(' ')}
      data-annotation-id={annotationId}
      data-visual-style={attrs['data-visual-style']}
      data-intent={attrs['data-intent']}
      data-tags={attrs['data-tags']}
      data-created-at={attrs['data-created-at']}
      data-created-by={attrs['data-created-by']}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={handleClick}
      style={{
        cursor: 'pointer',
        ...visualStyles,
      }}
    >
      <MarkViewContent />
    </span>
  );
}

export default IntentMarkView;

