  /** Whether popover is pinned */
  isPinned: boolean;

  /** Show popover for an annotation */
  show: (request: PopoverRequest) => void;

  /** Hide the active popover */
  hide: () => void;

  /** Toggle popover for an annotation */
  toggle: (request: PopoverRequest) => void;

  /** Pin the active popover */
  pin: () => void;

  /** Unpin the active popover */
  unpin: () => void;

/** Pin the active popover */
  pin: () => void;

  /** Unpin the active popover */
  unpin: () => void;

  /** Handle popover request from IntentExecutor */
  handlePopoverRequest: (request: PopoverRequest) => void;
}

// =============================================================================
// Hook Implementation
// =============================================================================

export function useAnnotationPopover(
  options: UseAnnotationPopoverOptions
): UseAnnotationPopoverReturn {
  const { editor, hideDelay = 200, showOnHover = true, showOnClick = true } = options;

  const isOpen = useAtomValue(isPopoverOpenAtom);
  const activePopover = useAtomValue(activePopoverAtom);

  const hideTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const currentMarkElementRef = useRef<HTMLElement | null>(null);

  // Clear hide timeout
  const clearHideTimeout = useCallback(() => {
    if (hideTimeoutRef.current) {
      clearTimeout(hideTimeoutRef.current);
      hideTimeoutRef.current = null;
    }
  }, []);

  // Get virtual anchor rect from position
  const getVirtualAnchor = useCallback((position: { x: number; y: number }) => {
    return {
      _tag: 'virtual' as const,
      getBoundingClientRect: () => ({
        x: position.x,
        y: position.y,
        width: 0,
        height: 0,
        top: position.y,
        right: position.x,
        bottom: position.y,
        left: position.x,
        toJSON: () => ({}),
      }),
    };
  }, []);

  // Get element anchor from mark ID
  const getElementAnchor = useCallback(
    (markId: AnnotationId) => {
      if (!editor) return null;

      const element = editor.view.dom.querySelector(
        `[data-annotation-id="${markId}"]`
      ) as HTMLElement | null;

      if (!element) return null;

      currentMarkElementRef.current = element;

const element = editor.view.dom.querySelector(
        `[data-annotation-id="${markId}"]`
      ) as HTMLElement | null;

      if (!element) return null;

      currentMarkElementRef.current = element;

      return {
        _tag: 'virtual' as const,
        getBoundingClientRect: () => element.getBoundingClientRect(),
      };
    },
    [editor]
  );

  // Show popover
  const show = useCallback(
    (request: PopoverRequest) => {
      clearHideTimeout();

      const anchor =
        request.position
          ? getVirtualAnchor(request.position)
          : getElementAnchor(request.markId);

      if (!anchor) return;

      popoverOps.show({
        annotationId: request.annotationId,
        markId: request.markId,
        anchor,
        placement: 'top',
        trigger: request.trigger,
      });
    },
    [clearHideTimeout, getVirtualAnchor, getElementAnchor]
  );

  // Hide popover with optional delay
  const hide = useCallback(() => {
    // Don't hide if pinned
    if (activePopover?.isPinned) return;

    clearHideTimeout();
    hideTimeoutRef.current = setTimeout(() => {
      popoverOps.hide();
    }, hideDelay);
  }, [activePopover?.isPinned, clearHideTimeout, hideDelay]);

  // Toggle popover
  const toggle = useCallback(
    (request: PopoverRequest) => {
      if (isOpen && activePopover?.annotationId === request.annotationId) {
        popoverOps.hide();
      } else {
        show(request);
      }
    },
    [isOpen, activePopover?.annotationId, show]
  );

  // Pin popover
  const pin = useCallback(() => {
    clearHideTimeout();
    popoverOps.pin();
  }, [clearHideTimeout]);

  // Unpin popover
  const unpin = useCallback(() => {
    popoverOps.unpin();
  }, []);

// Unpin popover
  const unpin = useCallback(() => {
    popoverOps.unpin();
  }, []);

  // Handle popover request from IntentExecutor
  const handlePopoverRequest = useCallback(
    (request: PopoverRequest) => {
      if (request.trigger === 'hover' && !showOnHover) return;
      if (request.trigger === 'click' && !showOnClick) return;

      if (request.trigger === 'click') {
        toggle(request);
      } else {
        show(request);
      }
    },
    [showOnHover, showOnClick, toggle, show]
  );

  // NOTE: Mouse enter/leave tracking is now handled by safePolygon in AnnotationPopover.
  // The safePolygon pattern uses document-level mousemove to create a safe traversal zone
  // between the trigger and popover, which is more reliable than element-level listeners.

  // Clean up on unmount
  useEffect(() => {
    return () => {
      clearHideTimeout();
    };
  }, [clearHideTimeout]);

  return {
    isOpen,
    activeAnnotationId: activePopover?.annotationId ?? null,
    isPinned: activePopover?.isPinned ?? false,
    show,
    hide,
    toggle,
    pin,
    unpin,
    handlePopoverRequest,
  };
}

export default useAnnotationPopover;

/**
 * useAnnotations Hook
 *
 * Combined hook that wires all annotation system components together:
 * - Intent execution (click/hover/keyboard on marks)
 * - Popover display (automatic wiring)
 * - Navigation handling
 *
 * This is the primary hook for integrating the annotation system.
 *
 * @example
 * ```tsx
 * function EditorWithAnnotations({ editor }) {
 *   const annotations = useAnnotations({
 *     editor,
 *     onNavigate: (req) => router.push(req.documentId),
 *   });
 *
 *   return (
 *     <>
 *       <EditorContent editor={editor} />
 *       <AnnotationPopover />
 *     </>
 *   );
 * }
 * ```
 *
 * @module editor/v3/extensions/annotations/hooks/useAnnotations
 */

import { useCallback, useMemo } from 'react';
import type { Editor } from '@tiptap/core';

import { useIntentExecution, type UseIntentExecutionReturn } from './useIntentExecution';
import { useAnnotationPopover, type UseAnnotationPopoverReturn } from './useAnnotationPopover';
import type { NavigationRequest, PopoverRequest } from '../services';
import type { AnnotationId } from '../schemas';

// =============================================================================
// Types
// =============================================================================

export interface UseAnnotationsOptions {
  /** TipTap editor instance */
  editor: Editor | null;

  /** Called when navigation is requested (ultralinks) */
  onNavigate?: (request: NavigationRequest) => void;

  /** Called when intent execution starts */
  onExecutionStart?: (markId: AnnotationId, intentType: string) => void;

  /** Called when intent execution completes */
  onExecutionComplete?: (markId: AnnotationId, success: boolean, error?: unknown) => void;

  /** Whether to show popovers on hover (default: true) */
  showPopoverOnHover?: boolean;

  /** Whether to show popovers on click (default: true) */
  showPopoverOnClick?: boolean;

  /** Hover delay before showing popover (ms, default: 300) */
  hoverDelay?: number;

/** Whether to show popovers on click (default: true) */
  showPopoverOnClick?: boolean;

  /** Hover delay before showing popover (ms, default: 300) */
  hoverDelay?: number;

  /** Delay before hiding popover on hover out (ms, default: 200) */
  hideDelay?: number;

  /** Whether to register built-in actions (default: true) */
  registerBuiltins?: boolean;
}

export interface UseAnnotationsReturn {
  /** Intent execution controls */
  intent: UseIntentExecutionReturn;

  /** Popover controls */
  popover: UseAnnotationPopoverReturn;

  /** Manually trigger intent execution for a mark */
  execute: (markId: AnnotationId, trigger: 'click' | 'hover' | 'keyboard') => Promise<void>;

  /** Show popover for an annotation */
  showPopover: (request: PopoverRequest) => void;

  /** Hide the active popover */
  hidePopover: () => void;

  /** Pin the active popover */
  pinPopover: () => void;

  /** Register a custom action */
  registerAction: UseIntentExecutionReturn['registerAction'];
}

// =============================================================================
// Hook Implementation
// =============================================================================

export function useAnnotations(options: UseAnnotationsOptions): UseAnnotationsReturn {
  const {
    editor,
    onNavigate,
    onExecutionStart,
    onExecutionComplete,
    showPopoverOnHover = true,
    showPopoverOnClick = true,
    hoverDelay = 300,
    hideDelay = 200,
    registerBuiltins = true,
  } = options;

  // Initialize popover hook first (we need handlePopoverRequest)
  const popover = useAnnotationPopover({
    editor,
    hideDelay,
    showOnHover: showPopoverOnHover,
    showOnClick: showPopoverOnClick,
  });

// Initialize popover hook first (we need handlePopoverRequest)
  const popover = useAnnotationPopover({
    editor,
    hideDelay,
    showOnHover: showPopoverOnHover,
    showOnClick: showPopoverOnClick,
  });

  // Wire intent execution to popover system
  const intent = useIntentExecution({
    editor,
    onPopoverRequest: popover.handlePopoverRequest,
    onNavigationRequest: onNavigate,
    onExecutionStart,
    onExecutionComplete,
    hoverDelay,
    registerBuiltins,
  });

  // Convenience methods
  const execute = useCallback(
    async (markId: AnnotationId, trigger: 'click' | 'hover' | 'keyboard') => {
      await intent.execute(markId, trigger);
    },
    [intent]
  );

  const showPopover = useCallback(
    (request: PopoverRequest) => {
      popover.show(request);
    },
    [popover]
  );

  const hidePopover = useCallback(() => {
    popover.hide();
  }, [popover]);

  const pinPopover = useCallback(() => {
    popover.pin();
  }, [popover]);

  return useMemo(
    () => ({
      intent,
      popover,
      execute,
      showPopover,
      hidePopover,
      pinPopover,
      registerAction: intent.registerAction,
    }),
    [intent, popover, execute, showPopover, hidePopover, pinPopover]
  );
}

export default useAnnotations;

/**
 * useIntentExecution Hook
 *
 * Wires IntentExecutor to TipTap editor events.
 * Handles click, hover, and keyboard activation of intent marks.
 *
 * @module editor/v3/extensions/annotations/hooks/useIntentExecution
 */

import { useCallback, useEffect, useRef } from 'react';
import { useAtomValue } from '@effect-atom/atom-react';
import { Effect, Layer } from 'effect';
import type { Editor } from '@tiptap/core';

import {
  IntentExecutor,
  IntentExecutorLive,
  IntentRegistry,
  IntentRegistryLive,
  registerBuiltinActions,
  type ExecutorHandlers,
  type PopoverRequest,
  type NavigationRequest,
} from '../services';
import { AnnotationService, AnnotationServiceLive } from '../services';
import { annotationRuntimeAtom, hoveredAnnotationIdAtom, selectionOps } from '../atoms';
import type { AnnotationId, IntentMark } from '../schemas';

// =============================================================================
// Types
// =============================================================================

export interface UseIntentExecutionOptions {
  /** TipTap editor instance */
  editor: Editor | null;

  /** Called when popover should be shown */
  onPopoverRequest?: (request: PopoverRequest) => void;

  /** Called when navigation is requested */
  onNavigationRequest?: (request: NavigationRequest) => void;

  /** Called when execution starts */
  onExecutionStart?: (markId: AnnotationId, intentType: string) => void;

  /** Called when execution completes */
  onExecutionComplete?: (markId: AnnotationId, success: boolean, error?: unknown) => void;

  /** Hover delay in ms before triggering hover intent */
  hoverDelay?: number;

  /** Whether to register built-in actions */
  registerBuiltins?: boolean;
}

export interface UseIntentExecutionReturn {
  /** Manually trigger intent execution for a mark */
  execute: (markId: AnnotationId, trigger: 'click' | 'hover' | 'keyboard') => Promise<void>;

  /** Cancel a running execution */
  cancel: (markId: AnnotationId) => Promise<boolean>;

/** Cancel a running execution */
  cancel: (markId: AnnotationId) => Promise<boolean>;

  /** Cancel all running executions */
  cancelAll: () => Promise<number>;

  /** Register a custom action */
  registerAction: (action: {
    key: string;
    name: string;
    description?: string;
    program: (ctx: { annotationId: AnnotationId; params: unknown }) => Effect.Effect<void>;
  }) => Promise<void>;
}

// =============================================================================
// Combined Layer
// =============================================================================

const IntentSystemLive = Layer.mergeAll(
  AnnotationServiceLive,
  IntentRegistryLive,
  IntentExecutorLive
);

// =============================================================================
// Hook Implementation
// =============================================================================

export function useIntentExecution(
  options: UseIntentExecutionOptions
): UseIntentExecutionReturn {
  const {
    editor,
    onPopoverRequest,
    onNavigationRequest,
    onExecutionStart,
    onExecutionComplete,
    hoverDelay = 300,
    registerBuiltins = true,
  } = options;

  // Track hover timeout
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hoveredIdRef = useRef<AnnotationId | null>(null);

  // Track initialization
  const initializedRef = useRef(false);

  // Initialize executor handlers and builtins
  useEffect(() => {
    if (initializedRef.current) return;
    initializedRef.current = true;

    const handlers: ExecutorHandlers = {
      onPopoverRequest,
      onNavigationRequest,
      onExecutionStart,
      onExecutionComplete: (markId, result) => {
        onExecutionComplete?.(markId, result.success, result.error);
      },
    };

    // Set handlers and register builtins
    const setup = Effect.gen(function* () {
      const executor = yield* IntentExecutor;
      yield* executor.setHandlers(handlers);

      if (registerBuiltins) {
        yield* registerBuiltinActions;
      }
    });

if (registerBuiltins) {
        yield* registerBuiltinActions;
      }
    });

    Effect.runPromise(Effect.provide(setup, IntentSystemLive)).catch(console.error);
  }, [onPopoverRequest, onNavigationRequest, onExecutionStart, onExecutionComplete, registerBuiltins]);

  // Handle mark click
  const handleMarkClick = useCallback(
    (markId: AnnotationId, event: MouseEvent) => {
      // Clear any hover timeout
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current);
        hoverTimeoutRef.current = null;
      }

      const executeClick = Effect.gen(function* () {
        const executor = yield* IntentExecutor;
        yield* executor.executeById(markId, 'click', event);
      });

      Effect.runPromise(Effect.provide(executeClick, IntentSystemLive)).catch(console.error);
    },
    []
  );

  // Handle mark hover enter
  const handleMarkHoverEnter = useCallback(
    (markId: AnnotationId, event: MouseEvent) => {
      // Update hovered state
      selectionOps.hover(markId);
      hoveredIdRef.current = markId;

      // Set timeout for hover intent
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current);
      }

      hoverTimeoutRef.current = setTimeout(() => {
        // Only execute if still hovering the same mark
        if (hoveredIdRef.current === markId) {
          const executeHover = Effect.gen(function* () {
            const executor = yield* IntentExecutor;
            const annotationService = yield* AnnotationService;

// Check if this mark has a hover-triggered intent
            const mark = yield* annotationService.findMark(markId);
            if (mark._tag === 'Some') {
              const intent = mark.value.intent;
              // Only auto-trigger for hover-friendly intents
              if (
                intent._tag === 'Popover' ||
                intent._tag === 'Note' ||
                (intent._tag === 'Popover' && intent.interaction === 'hover')
              ) {
                yield* executor.executeById(markId, 'hover', event);
              }
            }
          });

          Effect.runPromise(Effect.provide(executeHover, IntentSystemLive)).catch(console.error);
        }
      }, hoverDelay);
    },
    [hoverDelay]
  );

  // Handle mark hover leave
  const handleMarkHoverLeave = useCallback(
    (markId: AnnotationId) => {
      // Clear hover state
      if (hoveredIdRef.current === markId) {
        selectionOps.hover(null);
        hoveredIdRef.current = null;
      }

      // Clear hover timeout
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current);
        hoverTimeoutRef.current = null;
      }
    },
    []
  );

  // NOTE: Editor-level event listeners for hover/click have been DISABLED.
  // IntentMarkView now handles all hover/click events directly on the mark elements,
  // and AnnotationPopover uses safePolygon for hover-to-popover traversal.
  //
  // This hook's execute/cancel/registerAction APIs are still available for
  // programmatic intent execution.
  //
  // If you need editor-level event handling (e.g., for keyboard navigation),
  // add it here but DO NOT add mouseover/mouseout handlers - they conflict
  // with IntentMarkView's handlers and safePolygon.
  useEffect(() => {
    return () => {
      // Clean up timeout on unmount
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current);
      }
    };
  }, []);

// Public API
  const execute = useCallback(
    async (markId: AnnotationId, trigger: 'click' | 'hover' | 'keyboard') => {
      const executeIntent = Effect.gen(function* () {
        const executor = yield* IntentExecutor;
        yield* executor.executeById(markId, trigger);
      });

      await Effect.runPromise(Effect.provide(executeIntent, IntentSystemLive));
    },
    []
  );

  const cancel = useCallback(async (markId: AnnotationId) => {
    const cancelIntent = Effect.gen(function* () {
      const executor = yield* IntentExecutor;
      return yield* executor.cancel(markId);
    });

    return Effect.runPromise(Effect.provide(cancelIntent, IntentSystemLive));
  }, []);

  const cancelAll = useCallback(async () => {
    const cancelAllIntents = Effect.gen(function* () {
      const executor = yield* IntentExecutor;
      return yield* executor.cancelAll;
    });

    return Effect.runPromise(Effect.provide(cancelAllIntents, IntentSystemLive));
  }, []);

  const registerAction = useCallback(
    async (action: {
      key: string;
      name: string;
      description?: string;
      program: (ctx: { annotationId: AnnotationId; params: unknown }) => Effect.Effect<void>;
    }) => {
      const register = Effect.gen(function* () {
        const registry = yield* IntentRegistry;
        yield* registry.register({
          key: action.key,
          name: action.name,
          description: action.description,
          program: (ctx) => action.program({ annotationId: ctx.annotationId, params: ctx.params }),
        });
      });

      await Effect.runPromise(Effect.provide(register, IntentSystemLive));
    },
    []
  );

  return {
    execute,
    cancel,
    cancelAll,
    registerAction,
  };
}

export default useIntentExecution;

