/**
 * AnnotationNode Extension
 *
 * Creates hidden nodes for storing annotation content.
 * These nodes are not rendered but can be queried for popover display.
 */
export const AnnotationNodeExtension = Node.create<AnnotationNodeOptions>({
  name: 'annotationNode',

  // Not rendered in content flow
  group: 'block',

  // Can contain inline content (for rich text notes)
  content: 'inline*',

  // Marks allowed in content
  marks: '_',

  // Selectable for editing
  selectable: false,

  // Cannot be dragged
  draggable: false,

  // Atom: content is opaque to editor
  atom: true,

  // Priority
  priority: 100,

  addOptions() {
    return {
      HTMLAttributes: {},
      documentId: undefined,
      onCreate: undefined,
      onUpdate: undefined,
      onDelete: undefined,
    };
  },

  addAttributes() {
    return {
      // Unique identifier
      id: {
        default: null,
        parseHTML: (element) => element.getAttribute('data-annotation-node-id'),
        renderHTML: (attributes) => {
          if (!attributes.id) return {};
          return { 'data-annotation-node-id': attributes.id };
        },
      },

// Optional title
      title: {
        default: null,
        parseHTML: (element) => element.getAttribute('data-title'),
        renderHTML: (attributes) => {
          if (!attributes.title) return {};
          return { 'data-title': attributes.title };
        },
      },

      // Document ID
      documentId: {
        default: null,
        parseHTML: (element) => element.getAttribute('data-document-id'),
        renderHTML: (attributes) => {
          if (!attributes.documentId) return {};
          return { 'data-document-id': attributes.documentId };
        },
      },

      // Creation timestamp
      createdAt: {
        default: null,
        parseHTML: (element) => element.getAttribute('data-created-at'),
        renderHTML: (attributes) => {
          if (!attributes.createdAt) return {};
          return { 'data-created-at': attributes.createdAt };
        },
      },

      // Update timestamp
      updatedAt: {
        default: null,
        parseHTML: (element) => element.getAttribute('data-updated-at'),
        renderHTML: (attributes) => {
          if (!attributes.updatedAt) return {};
          return { 'data-updated-at': attributes.updatedAt };
        },
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'div[data-annotation-node-id]',
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    // Hidden node - renders as empty div with data attributes
    // Actual content is retrieved via service for popover display
    return [
      'div',
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        class: 'annotation-node',
        style: 'display: none;', // Hidden from visual display
        'aria-hidden': 'true',
      }),
      0, // Content placeholder
    ];
  },

addCommands() {
    return {
      insertAnnotationNode:
        (options) =>
        ({ commands, state }) => {
          const id = generateAnnotationId();
          const documentId =
            this.options.documentId || ('doc-default' as DocumentId);
          const now = new Date().toISOString();

          // Create the annotation node schema object
          const annotationNode = AnnotationNodeFactory.withContent(
            documentId,
            options.content,
            options.title
          );

          // Notify callback
          if (this.options.onCreate) {
            this.options.onCreate(annotationNode);
          }

          // Insert as hidden block at end of document
          return commands.insertContentAt(state.doc.content.size, {
            type: this.name,
            attrs: {
              id: annotationNode.id,
              title: options.title || null,
              documentId,
              createdAt: now,
              updatedAt: now,
            },
            content: [
              {
                type: 'text',
                text:
                  typeof options.content === 'string'
                    ? options.content
                    : JSON.stringify(options.content),
              },
            ],
          });
        },

      updateAnnotationNode:
        (id, updates) =>
        ({ tr, state, dispatch }) => {
          if (!dispatch) return false;

          let updated = false;

          // Find node with matching ID
          state.doc.descendants((node, pos) => {
            if (
              node.type.name === this.name &&
              node.attrs.id === id
            ) {
              const newAttrs = {
                ...node.attrs,
                updatedAt: new Date().toISOString(),
              };

              if (updates.title !== undefined) {
                newAttrs.title = updates.title;
              }

              tr.setNodeMarkup(pos, undefined, newAttrs);
              updated = true;

if (updates.title !== undefined) {
                newAttrs.title = updates.title;
              }

              tr.setNodeMarkup(pos, undefined, newAttrs);
              updated = true;

              // Notify callback
              if (this.options.onUpdate) {
                // Reconstruct schema object from node
                const schemaNode = decodeNodeAttrs({
                  id: node.attrs.id,
                  title: newAttrs.title,
                  content: JSON.stringify(updates.content ?? node.textContent),
                  documentId: node.attrs.documentId,
                  createdAt: node.attrs.createdAt,
                  updatedAt: newAttrs.updatedAt,
                });
                this.options.onUpdate(schemaNode);
              }

              return false; // Stop traversal
            }
          });

          return updated;
        },

      deleteAnnotationNode:
        (id) =>
        ({ tr, state, dispatch }) => {
          if (!dispatch) return false;

          let deleted = false;

          // Find and delete node with matching ID
          state.doc.descendants((node, pos) => {
            if (
              node.type.name === this.name &&
              node.attrs.id === id
            ) {
              tr.delete(pos, pos + node.nodeSize);
              deleted = true;

              // Notify callback
              if (this.options.onDelete) {
                this.options.onDelete(id);
              }

              return false; // Stop traversal
            }
          });

          return deleted;
        },

      getAnnotationNode:
        (id) =>
        ({ state }) => {
          let found: ProseMirrorNode | null = null;

          state.doc.descendants((node) => {
            if (
              node.type.name === this.name &&
              node.attrs.id === id
            ) {
              found = node;
              return false;
            }
          });

          return found as unknown as ReturnType;
        },
    };
  },

  // Add CSS for hidden nodes
  addGlobalAttributes() {
    return [];
  },
});

export default AnnotationNodeExtension;

/**
 * FilterSyncPlugin
 *
 * TipTap plugin that synchronizes annotation visibility atoms
 * with ProseMirror mark decorations.
 *
 * When visibleMarkIdsAtom changes:
 * 1. Updates data-hidden attribute on non-visible marks
 * 2. Triggers CSS transitions for smooth hide/show
 *
 * @module editor/v3/extensions/annotations/plugins/FilterSyncPlugin
 */

import { Plugin, PluginKey } from '@tiptap/pm/state';
import { Decoration, DecorationSet } from '@tiptap/pm/view';
import { Atom } from '@effect-atom/atom-react';

import { visibleMarkIdsAtom, marksAtom } from '../atoms';
import type { AnnotationId } from '../schemas';

// =============================================================================
// Plugin Key
// =============================================================================

export const filterSyncPluginKey = new PluginKey<FilterSyncPluginState>('annotationFilterSync');

// =============================================================================
// Plugin State
// =============================================================================

interface FilterSyncPluginState {
  visibleIds: Set<AnnotationId>;
  decorations: DecorationSet;
}

// =============================================================================
// Plugin Factory
// =============================================================================

export interface FilterSyncPluginOptions {
  /** Callback when visibility changes */
  onVisibilityChange?: (visible: Set<AnnotationId>, hidden: Set<AnnotationId>) => void;
}

export function createFilterSyncPlugin(options: FilterSyncPluginOptions = {}): Plugin {
  return new Plugin<FilterSyncPluginState>({
    key: filterSyncPluginKey,

    state: {
      init(_, state) {
        const visibleIds = Atom.get(visibleMarkIdsAtom);
        const marks = Atom.get(marksAtom);
        const decorations = buildDecorations(state.doc, marks, visibleIds);

        return {
          visibleIds,
          decorations,
        };
      },

      apply(tr, pluginState, _oldState, newState) {
        // Check if we need to update decorations
        const visibleIds = Atom.get(visibleMarkIdsAtom);
        const marks = Atom.get(marksAtom);

        // Compare sets
        const changed = !setsEqual(pluginState.visibleIds, visibleIds);

// Compare sets
        const changed = !setsEqual(pluginState.visibleIds, visibleIds);

        if (changed || tr.docChanged) {
          const decorations = buildDecorations(newState.doc, marks, visibleIds);

          // Notify callback
          if (changed && options.onVisibilityChange) {
            const hidden = new Set<AnnotationId>();
            for (const [id] of marks) {
              if (!visibleIds.has(id)) {
                hidden.add(id);
              }
            }
            options.onVisibilityChange(visibleIds, hidden);
          }

          return {
            visibleIds,
            decorations,
          };
        }

        // Map decorations through transaction if doc changed
        if (tr.docChanged) {
          return {
            ...pluginState,
            decorations: pluginState.decorations.map(tr.mapping, tr.doc),
          };
        }

        return pluginState;
      },
    },

    props: {
      decorations(state) {
        const pluginState = filterSyncPluginKey.getState(state);
        return pluginState?.decorations ?? DecorationSet.empty;
      },
    },

    view(editorView) {
      // Subscribe to atom changes and force update
      let unsubscribe: (() => void) | undefined;

      // Set up subscription after initial render
      queueMicrotask(() => {
        unsubscribe = Atom.subscribe(visibleMarkIdsAtom, () => {
          // Force plugin state update by dispatching empty transaction
          const { state, dispatch } = editorView;
          const tr = state.tr.setMeta(filterSyncPluginKey, { forceUpdate: true });
          dispatch(tr);
        });
      });

      return {
        destroy() {
          unsubscribe?.();
        },
      };
    },
  });
}

// =============================================================================
// Decoration Builder
// =============================================================================

function buildDecorations(
  doc: import('@tiptap/pm/model').Node,
  marks: ReadonlyMap<AnnotationId, unknown>,
  visibleIds: Set<AnnotationId>
): DecorationSet {
  const decorations: Decoration[] = [];

// Find all annotation marks in the document
  doc.descendants((node, pos) => {
    if (!node.isText) return;

    for (const mark of node.marks) {
      if (mark.type.name === 'intentMark') {
        const markId = mark.attrs.id as AnnotationId;
        const annotationId = mark.attrs.annotationId as AnnotationId;
        const isHidden = !visibleIds.has(markId) && !visibleIds.has(annotationId);

        if (isHidden) {
          // Add decoration to set data-hidden attribute
          decorations.push(
            Decoration.inline(pos, pos + node.nodeSize, {
              class: 'intent-mark--filtered-hidden',
              'data-filtered': 'true',
              'data-hidden': 'true',
            })
          );
        }
      }
    }

    return true;
  });

  return DecorationSet.create(doc, decorations);
}

// =============================================================================
// Utility
// =============================================================================

function setsEqual<T>(a: Set<T>, b: Set<T>): boolean {
  if (a.size !== b.size) return false;
  for (const item of a) {
    if (!b.has(item)) return false;
  }
  return true;
}

export default createFilterSyncPlugin;

