            cursor: 'pointer',
            // Opacity controlled by CSS for hover transitions
          }}
          title={showControls ? 'Hide layout controls' : 'Show layout controls'}
        >
          <Settings2 size={12} />
        </button>
      )}

VANTA_COLORS.text.tertiary : VANTA_COLORS.surface.border,
              cursor: canRemoveColumn ? 'pointer' : 'not-allowed',
            }}
            title="Remove column"
          >
            <Minus size={10} />
          </button>
          <button
            onClick={handleAddColumn}
            disabled={!canAddColumn}
            style={{
              display: 'flex',
