tr.setNodeMarkup(layoutPos, undefined, {
            ...attrs,
            widths: finalWidths,
          });

          dispatch(tr);
          return true;
        },
    };
  },

  addNodeView() {
    return ReactNodeViewRenderer(ColumnLayoutView);
  },
});

