 * Keyed by animation name for targeted stopping.
 */
const activeAnimations = new Map<string, JSAnimation>();

/**
 * Stop a specific animation by key.
 */
const stopAnimation = (key: string): void => {
  const anim = activeAnimations.get(key);
  if (anim) {
    anim.pause();
    activeAnimations.delete(key);
  }
};

/**
 * Track an animation for later cleanup.
 */
const trackAnimation = (key: string, anim: JSAnimation): void => {
  stopAnimation(key); // Stop existing first
  activeAnimations.set(key, anim);
};

// =============================================================================
// TRANSITION: DISPLAY → EDITING (blur + fade sequence)
// =============================================================================

/**
 * Animate name blur out before editing.
 * - Blur: 0 → 4px
 * - Translate: 0 → -4px
 * - Opacity: 1 → 0
 */
export const animateNameBlurOut = (
  nameRef: React.RefObject<HTMLSpanElement>,
  blockIdRef?: React.RefObject<HTMLSpanElement>
): Promise<void> => {
  return new Promise((resolve) => {
    if (nameRef.current) {
      animate(nameRef.current, {
        filter: ['blur(0px)', 'blur(4px)'],
        opacity: [1, 0],
        translateY: [0, -4],
        duration: TIMING.blurOut,
        easing: EASING.out,
        onComplete: () => resolve(),
      });
    } else {
      resolve();
    }

// Also blur out block ID
    if (blockIdRef?.current) {
      animate(blockIdRef.current, {
        filter: ['blur(0px)', 'blur(4px)'],
        opacity: [0.5, 0],
        translateY: [0, -4],
        duration: TIMING.blurOut,
        easing: EASING.out,
      });
    }
  });
};

/**
 * Animate input fade in after blur out.
 */
export const animateInputFadeIn = (
  inputRef: React.RefObject<HTMLInputElement>
): Promise<void> => {
  return new Promise((resolve) => {
    if (inputRef.current) {
      animate(inputRef.current, {
        opacity: [0, 1],
        duration: TIMING.inputFadeIn,
        easing: EASING.out,
        onComplete: () => resolve(),
      });
    } else {
      resolve();
    }
  });
};

/**
 * Animate from display to editing state.
 *
 * New sequence:
 * 1. Name + block ID blur out (100ms)
 * 2. Input fades in (50ms)
 * 3. Caret starts pulsing
 */
export const animateDisplayToEditing = (refs: AnimationRefs): Promise<void> => {
  return new Promise((resolve) => {
    const { prefixRef, caretRef, underlineRef } = refs;

    // 1. "@" prefix fades out
    if (prefixRef.current) {
      animate(prefixRef.current, {
        opacity: [COLORS.prefixOpacity, 0],
        duration: TIMING.prefixFadeOut,
        easing: EASING.out,
      });
    }

    // 2. Caret fades in (crossfade with prefix)
    if (caretRef.current) {
      animate(caretRef.current, {
        opacity: [0, 1],
        duration: TIMING.caretFadeIn,
        delay: TIMING.caretFadeInDelay,
        easing: EASING.out,
      });
    }

// 3. Underline intensifies
    if (underlineRef.current) {
      const anim = animate(underlineRef.current, {
        backgroundColor: [COLORS.underlineMuted, COLORS.underlineCyan],
        opacity: [0.3, 1],
        duration: TIMING.displayToEditing,
        easing: EASING.out,
        onComplete: () => resolve(),
      });
      trackAnimation('underline-intensify', anim);
    } else {
      resolve();
    }
  });
};

/**
 * Full display → editing transition with blur.
 * This is the new entry point that includes blur.
 */
export const animateDisplayToEditingWithBlur = async (
  refs: AnimationRefs,
  inputRef: React.RefObject<HTMLInputElement>
): Promise<void> => {
  // Phase 1: Blur out name + block ID
  await animateNameBlurOut(refs.nameRef, refs.blockIdRef);

  // Phase 2: Fade in input + start legacy animations
  await Promise.all([
    animateInputFadeIn(inputRef),
    animateDisplayToEditing(refs),
  ]);
};

// =============================================================================
// TRANSITION: EDITING → SUBMITTING (100ms)
// =============================================================================

/**
 * Animate from editing to submitting state.
 *
 * - Caret fades out (100ms)
 * - Text dims slightly to 80% opacity (100ms)
 * - Shimmer animation starts (CSS class)
 */
export const animateEditingToSubmitting = (refs: AnimationRefs): Promise<void> => {
  return new Promise((resolve) => {
    const { caretRef, nameRef, underlineRef } = refs;

    // 1. Caret fades out
    if (caretRef.current) {
      animate(caretRef.current, {
        opacity: [1, 0],
        duration: TIMING.editingToSubmitting,
        easing: EASING.out,
      });
    }

// 2. Text dims
    if (nameRef.current) {
      animate(nameRef.current, {
        opacity: [1, 0.8],
        duration: TIMING.editingToSubmitting,
        easing: EASING.out,
      });
    }

    // 3. Start shimmer (CSS handles the loop)
    startSubmittingShimmer(underlineRef);

    setTimeout(resolve, TIMING.editingToSubmitting);
  });
};

// =============================================================================
// STATE: SUBMITTING (Shimmer Loop)
// =============================================================================

/**
 * Start shimmer animation on underline.
 * Uses CSS class for infinite loop.
 */
export const startSubmittingShimmer = (
  underlineRef: React.RefObject<HTMLDivElement>
): void => {
  if (underlineRef.current) {
    underlineRef.current.classList.add('badge-shimmer-active');
  }
};

/**
 * Stop shimmer animation on underline.
 */
export const stopSubmittingShimmer = (
  underlineRef: React.RefObject<HTMLDivElement>
): void => {
  if (underlineRef.current) {
    underlineRef.current.classList.remove('badge-shimmer-active');
  }
};

// =============================================================================
// TRANSITION: SUBMITTING → SUCCESS (300ms sequence)
// =============================================================================

/**
 * Animate from submitting to success state.
 *
 * Sequence:
 * 1. Text collapses/fades (100ms)
 * 2. Checkmark scales up with spring bounce (150ms, delayed 100ms)
 * 3. Underline turns emerald
 */
export const animateSubmittingToSuccess = (refs: AnimationRefs): Promise<void> => {
  return new Promise((resolve) => {
    const { nameRef, checkmarkRef, underlineRef } = refs;

    // Stop shimmer first
    stopSubmittingShimmer(underlineRef);

// Stop shimmer first
    stopSubmittingShimmer(underlineRef);

    // 1. Text collapses/fades
    if (nameRef.current) {
      animate(nameRef.current, {
        opacity: [0.8, 0],
        scale: [1, 0.9],
        duration: 100,
        easing: EASING.in,
      });
    }

    // 2. Checkmark scales in with spring bounce
    if (checkmarkRef.current) {
      const anim = animate(checkmarkRef.current, {
        scale: [0, 1.1, 1],
        opacity: [0, 1],
        duration: TIMING.checkmarkScaleIn,
        delay: TIMING.checkmarkScaleInDelay,
        easing: EASING.spring,
        onComplete: () => resolve(),
      });
      trackAnimation('checkmark-in', anim);
    }

    // 3. Underline turns emerald
    if (underlineRef.current) {
      animate(underlineRef.current, {
        backgroundColor: [COLORS.underlineCyan, COLORS.underlineEmerald],
        duration: TIMING.submittingToSuccess,
        delay: TIMING.checkmarkScaleInDelay,
        easing: EASING.out,
      });
    }
  });
};

// =============================================================================
// TRANSITION: SUCCESS → DISPLAY (300ms)
// =============================================================================

/**
 * Animate from success back to display state.
 *
 * - Checkmark slides left + shrinks + fades (150ms)
 * - New "@name" slides in from right (150ms, delayed 100ms)
 * - Underline fades back to muted
 */
export const animateSuccessToDisplay = (refs: AnimationRefs): Promise<void> => {
  return new Promise((resolve) => {
    const { checkmarkRef, nameRef, prefixRef, underlineRef } = refs;

// 1. Checkmark slides out
    if (checkmarkRef.current) {
      animate(checkmarkRef.current, {
        translateX: [0, -GEOMETRY.slideDistance],
        scale: [1, 0.5],
        opacity: [1, 0],
        duration: TIMING.checkmarkSlideOut,
        easing: EASING.in,
      });
    }

    // 2. Prefix slides in from right
    if (prefixRef.current) {
      animate(prefixRef.current, {
        translateX: [GEOMETRY.slideDistance, 0],
        opacity: [0, COLORS.prefixOpacity],
        duration: TIMING.slideInDuration,
        delay: TIMING.slideInDelay,
        easing: EASING.out,
      });
    }

    // 3. Name slides in from right
    if (nameRef.current) {
      animate(nameRef.current, {
        translateX: [GEOMETRY.slideDistance, 0],
        opacity: [0, 1],
        scale: [0.9, 1],
        duration: TIMING.slideInDuration,
        delay: TIMING.slideInDelay,
        easing: EASING.out,
      });
    }

    // 4. Underline fades back to muted
    if (underlineRef.current) {
      const anim = animate(underlineRef.current, {
        backgroundColor: [COLORS.underlineEmerald, COLORS.underlineMuted],
        opacity: [1, 0.3],
        duration: TIMING.slideInDuration,
        delay: TIMING.slideInDelay,
        easing: EASING.out,
        onComplete: () => resolve(),
      });
      trackAnimation('underline-fade', anim);
    } else {
      setTimeout(resolve, TIMING.slideInDuration + TIMING.slideInDelay);
    }
  });
};

// =============================================================================
// ERROR INDICATION (during editing state)
// =============================================================================

// =============================================================================
// ERROR INDICATION (during editing state)
// =============================================================================

/**
 * Shake the badge to indicate validation error.
 * Called during editing when error appears. Does NOT change state.
 * Underline color managed by ErrorPopover visibility.
 */
export const animateErrorShake = (refs: AnimationRefs): Promise<void> => {
  return new Promise((resolve) => {
    const { badgeRef } = refs;

    if (badgeRef.current) {
      const amplitude = GEOMETRY.shakeAmplitude;
      const anim = animate(badgeRef.current, {
        translateX: [
          0,
          -amplitude,
          amplitude,
          -amplitude * 0.75,
          amplitude * 0.75,
          -amplitude * 0.5,
          amplitude * 0.5,
          0,
        ],
        duration: TIMING.errorShake,
        easing: EASING.out,
        onComplete: () => resolve(),
      });
      trackAnimation('error-shake', anim);
    } else {
      resolve();
    }
  });
};

/**
 * Transition underline to rose (error indication).
 * Called when error appears during editing.
 */
export const animateUnderlineToError = (
  underlineRef: React.RefObject<HTMLDivElement>
): void => {
  if (underlineRef.current) {
    animate(underlineRef.current, {
      backgroundColor: [COLORS.underlineCyan, COLORS.underlineRose],
      duration: 100,
      easing: EASING.out,
    });
  }
};

/**
 * Transition underline back to cyan (error cleared).
 * Called when error clears during editing.
 */
export const animateUnderlineFromError = (
  underlineRef: React.RefObject<HTMLDivElement>
): void => {
  if (underlineRef.current) {
    animate(underlineRef.current, {
      backgroundColor: [COLORS.underlineRose, COLORS.underlineCyan],
      duration: 100,
      easing: EASING.out,
    });
  }
};

// =============================================================================
// LEGACY: Error State Animations (kept for reference, unused)
// =============================================================================

/**
 * @deprecated Error is now context, not state. Use animateErrorShake instead.
 */
export const animateError = (refs: AnimationRefs): Promise<void> => {
  // Redirect to new implementation
  return animateErrorShake(refs);
};

/**
 * @deprecated Error→Editing transition no longer exists.
 * Errors show during editing, not as separate state.
 */
export const animateErrorToEditing = (_refs: AnimationRefs): Promise<void> => {
  // No-op: error is now shown during editing, not as separate state
  return Promise.resolve();
};

// =============================================================================
// CARET PULSE (Continuous during editing)
// =============================================================================

/**
 * Start caret pulse animation.
 * Continuous blink while in editing state.
 */
export const startCaretPulse = (
  caretRef: React.RefObject<HTMLDivElement>
): void => {
  if (!caretRef.current) return;

  // Use CSS class for pulse animation
  caretRef.current.classList.add('badge-caret-pulse');
};

/**
 * Stop caret pulse animation.
 */
export const stopCaretPulse = (
  caretRef: React.RefObject<HTMLDivElement>
): void => {
  if (!caretRef.current) return;

  caretRef.current.classList.remove('badge-caret-pulse');
};

// =============================================================================
// CLEANUP
// =============================================================================

/**
 * Clean up all active animations.
 * Call on unmount or state reset.
 */
export const cleanupAllAnimations = (): void => {
  activeAnimations.forEach((anim) => anim.pause());
  activeAnimations.clear();
};

/**
 * Reset element transforms.
 * Useful when canceling or resetting state.
 */
export const resetElementTransforms = (refs: AnimationRefs): void => {
  const elements = [
    refs.badgeRef.current,
    refs.nameRef.current,
    refs.prefixRef.current,
    refs.checkmarkRef.current,
    refs.errorRef.current,
  ];

elements.forEach((el) => {
    if (el) {
      el.style.transform = '';
      el.style.opacity = '';
    }
  });
};

/**
 * BlockNameBadge Atoms — XState → effect-atom Bridge
 *
 * Per-block actor factory with snapshot bridge pattern.
 * Unlike minibuffer (singleton), each block has its own actor instance.
 *
 * Architecture Notes:
 * - Error is now CONTEXT, not state — errors show during editing
 * - validationError: live feedback as user types (debounced)
 * - submissionError: shown after failed submit, cleared on next input
 *
 * @module editor/v3/extensions/blocks/BlockNameBadge/atoms
 */

import { Atom } from '@effect-atom/atom';
import { createActor, type SnapshotFrom, type ActorRefFrom } from 'xstate';
import {
  blockNameMachine,
  type BlockNameMachineContext,
  type BlockNameMachineEvent,
  defaultBlockNameMachineContext,
} from './machines/blockNameMachine';
import type { BlockId } from '../shared';
import type { BadgeState } from './types';

// =============================================================================
// Types
// =============================================================================

export type BlockNameActor = ActorRefFrom<typeof blockNameMachine>;
export type BlockNameSnapshot = SnapshotFrom<typeof blockNameMachine>;

export interface BlockNameAtoms {
  /** Root snapshot atom — single subscription point */
  snapshotAtom: Atom.Atom<BlockNameSnapshot>;

  /** Current state: display | editing | submitting | success */
  stateAtom: Atom.Atom<BadgeState>;

  /** Full context object */
  contextAtom: Atom.Atom<BlockNameMachineContext>;

  /** Current input value (during editing) */
  inputValueAtom: Atom.Atom<string>;

  /** Validation error (live feedback during editing) */
  validationErrorAtom: Atom.Atom<string | null>;

  /** Submission error (after failed rename) */
  submissionErrorAtom: Atom.Atom<string | null>;

  /** Combined error for display (validation OR submission) */
  errorAtom: Atom.Atom<string | null>;

  /** Current name from context */
  currentNameAtom: Atom.Atom<string | null>;

/** Combined error for display (validation OR submission) */
  errorAtom: Atom.Atom<string | null>;

  /** Current name from context */
  currentNameAtom: Atom.Atom<string | null>;

  /** Whether badge is editable (onRename defined) */
  isEditableAtom: Atom.Atom<boolean>;

  /** Whether we have any error to show */
  hasErrorAtom: Atom.Atom<boolean>;

  /** Whether validation is currently running */
  isValidatingAtom: Atom.Atom<boolean>;

  /** Operations to send events to actor */
  ops: BlockNameOps;

  /** Raw actor reference (for advanced use) */
  actor: BlockNameActor;
}

export interface BlockNameOps {
  /** Enter editing mode (double-click) */
  edit: () => void;

  /** Cancel editing, revert to display */
  cancel: () => void;

  /** Submit current input value */
  submit: () => void;

  /** Update input value during editing */
  inputChange: (value: string) => void;

  /** Sync name from external source */
  setName: (name: string | null) => void;

  /** Update onRename handler */
  setOnRename: (handler: ((name: string) => Promise<void>) | undefined) => void;

  /** Update onValidate handler (optional server-side validation) */
  setOnValidate: (handler: ((name: string) => Promise<string | null>) | undefined) => void;
}

// =============================================================================
// Actor Cache (Per-Block Instances)
// =============================================================================

/**
 * Cache of actor instances keyed by BlockId.
 * Each block gets its own independent state machine.
 */
const actorCache = new Map<BlockId, BlockNameActor>();

/**
 * Cache of atom bundles keyed by BlockId.
 * Prevents recreating atoms for the same block.
 */
const atomsCache = new Map<BlockId, BlockNameAtoms>();

// =============================================================================
// Factory Functions
// =============================================================================

/**
 * Cache of atom bundles keyed by BlockId.
 * Prevents recreating atoms for the same block.
 */
const atomsCache = new Map<BlockId, BlockNameAtoms>();

// =============================================================================
// Factory Functions
// =============================================================================

/**
 * Get or create an actor for a specific block.
 *
 * @param blockId - Unique block identifier
 * @param initialContext - Optional initial context override
 * @returns Actor reference
 */
export const getBlockNameActor = (
  blockId: BlockId,
  initialContext?: Partial<BlockNameMachineContext>
): BlockNameActor => {
  let actor = actorCache.get(blockId);

  // Check if cached actor exists AND is still running
  // (React strict mode / HMR can stop actors, leaving stale cache entries)
  if (actor) {
    const snapshot = actor.getSnapshot();
    if (snapshot.status === 'stopped') {
      // Actor was stopped, remove from cache and create new one
      actorCache.delete(blockId);
      atomsCache.delete(blockId);
      actor = undefined;
    }
  }

  if (!actor) {
    actor = createActor(blockNameMachine, {
      input: {
        blockId,
        ...defaultBlockNameMachineContext,
        ...initialContext,
      },
    });
    actor.start();
    actorCache.set(blockId, actor);
  }

  return actor;
};

/**
 * Extract top-level state from potentially nested state value.
 * XState v5 uses { parent: { child: {} } } for nested states.
 */
const extractTopLevelState = (stateValue: unknown): BadgeState => {
  if (typeof stateValue === 'string') {
    return stateValue as BadgeState;
  }
  if (typeof stateValue === 'object' && stateValue !== null) {
    // Get the first key (top-level state)
    const topLevel = Object.keys(stateValue)[0];
    return topLevel as BadgeState;
  }
  return 'display';
};

/**
 * Check if we're in the validating child state of editing.
 */
const isInValidatingState = (stateValue: unknown): boolean => {
  if (typeof stateValue === 'object' && stateValue !== null) {
    const editing = (stateValue as Record<string, unknown>).editing;
    if (typeof editing === 'string') {
      return editing === 'validating';
    }
  }
  return false;
};

/**
 * Create the atom bundle for a specific block.
 *
 * This is the main factory. Call this from your component to get
 * all the atoms and operations for a specific block.
 *
 * @example
 * ```tsx
 * const { stateAtom, inputValueAtom, ops } = createBlockNameAtoms(blockId);
 *
 * const state = useAtomValue(stateAtom);
 * const inputValue = useAtomValue(inputValueAtom);
 *
 * const handleDoubleClick = () => ops.edit();
 * ```
 */
export const createBlockNameAtoms = (
  blockId: BlockId,
  initialContext?: Partial<BlockNameMachineContext>
): BlockNameAtoms => {
  // Check cached bundle - but verify actor is still running
  // (React strict mode / HMR can stop actors, leaving stale cache entries)
  const cached = atomsCache.get(blockId);
  if (cached) {
    const snapshot = cached.actor.getSnapshot();
    if (snapshot.status !== 'stopped') {
      return cached; // Actor still running, safe to return
    }
    // Actor stopped - clear caches and recreate
    atomsCache.delete(blockId);
    actorCache.delete(blockId);
  }

  // Get or create actor
  const actor = getBlockNameActor(blockId, initialContext);

  // ─────────────────────────────────────────────────────────────
  // Bridge Atom (Single Subscription Point)
  // ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
  // Bridge Atom (Single Subscription Point)
  // ─────────────────────────────────────────────────────────────

  const snapshotAtom: Atom.Atom<BlockNameSnapshot> = Atom.make((get) => {
    const subscription = actor.subscribe((snapshot) => {
      get.setSelf(snapshot);
    });
    get.addFinalizer(() => subscription.unsubscribe());
    return actor.getSnapshot();
  });

  // ─────────────────────────────────────────────────────────────
  // Selector Atoms (Derived, Memoized)
  // ─────────────────────────────────────────────────────────────

  const stateAtom = Atom.make(
    (get) => extractTopLevelState(get(snapshotAtom).value)
  );

  const contextAtom = Atom.make(
    (get) => get(snapshotAtom).context
  );

  const inputValueAtom = Atom.make(
    (get) => get(snapshotAtom).context.inputValue
  );

  const validationErrorAtom = Atom.make(
    (get) => get(snapshotAtom).context.validationError
  );

  const submissionErrorAtom = Atom.make(
    (get) => get(snapshotAtom).context.submissionError
  );

  // Combined error for backwards compatibility with ErrorPopover
  const errorAtom = Atom.make((get) => {
    const ctx = get(snapshotAtom).context;
    // Prioritize submission error (more important) over validation error
    return ctx.submissionError ?? ctx.validationError ?? null;
  });

  const currentNameAtom = Atom.make(
    (get) => get(snapshotAtom).context.currentName
  );

  const isEditableAtom = Atom.make(
    (get) => get(snapshotAtom).context.onRename !== undefined
  );

  const hasErrorAtom = Atom.make((get) => {
    const ctx = get(snapshotAtom).context;
    return ctx.validationError !== null || ctx.submissionError !== null;
  });

const hasErrorAtom = Atom.make((get) => {
    const ctx = get(snapshotAtom).context;
    return ctx.validationError !== null || ctx.submissionError !== null;
  });

  const isValidatingAtom = Atom.make(
    (get) => isInValidatingState(get(snapshotAtom).value)
  );

  // ─────────────────────────────────────────────────────────────
  // Operations (Send Events to Actor)
  // ─────────────────────────────────────────────────────────────

  const ops: BlockNameOps = {
    edit: () => actor.send({ type: 'EDIT' }),

    cancel: () => actor.send({ type: 'CANCEL' }),

    submit: () => actor.send({ type: 'SUBMIT' }),

    inputChange: (value: string) =>
      actor.send({ type: 'INPUT_CHANGE', value }),

    setName: (name: string | null) =>
      actor.send({ type: 'SET_NAME', name }),

    setOnRename: (handler: ((name: string) => Promise<void>) | undefined) =>
      actor.send({ type: 'SET_ON_RENAME', handler }),

    setOnValidate: (handler: ((name: string) => Promise<string | null>) | undefined) =>
      actor.send({ type: 'SET_ON_VALIDATE', handler }),
  };

  // ─────────────────────────────────────────────────────────────
  // Bundle
  // ─────────────────────────────────────────────────────────────

  const bundle: BlockNameAtoms = {
    snapshotAtom,
    stateAtom,
    contextAtom,
    inputValueAtom,
    validationErrorAtom,
    submissionErrorAtom,
    errorAtom,
    currentNameAtom,
    isEditableAtom,
    hasErrorAtom,
    isValidatingAtom,
    ops,
    actor,
  };

  atomsCache.set(blockId, bundle);
  return bundle;
};

// =============================================================================
// Cleanup Utilities
// =============================================================================

atomsCache.set(blockId, bundle);
  return bundle;
};

// =============================================================================
// Cleanup Utilities
// =============================================================================

/**
 * Dispose the actor for a specific block.
 * Call this when the block is unmounted/removed.
 */
export const disposeBlockNameActor = (blockId: BlockId): void => {
  const actor = actorCache.get(blockId);
  if (actor) {
    actor.stop();
    actorCache.delete(blockId);
  }
  atomsCache.delete(blockId);
};

/**
 * Clear all cached actors and atoms.
 * Useful for testing or complete cleanup.
 */
export const clearAllBlockNameActors = (): void => {
  actorCache.forEach((actor) => actor.stop());
  actorCache.clear();
  atomsCache.clear();
};

// =============================================================================
// Accessor Utilities
// =============================================================================

/**
 * Get current snapshot synchronously for a block.
 * Prefer using selector atoms for reactive updates.
 */
export const getBlockNameSnapshot = (blockId: BlockId): BlockNameSnapshot | null => {
  const actor = actorCache.get(blockId);
  return actor?.getSnapshot() ?? null;
};

/**
 * Check if an actor exists for a block.
 */
export const hasBlockNameActor = (blockId: BlockId): boolean => {
  return actorCache.has(blockId);
};

// =============================================================================
// Hover State (Local UI State, not XState)
// =============================================================================

/**
 * Cache of hover atoms keyed by BlockId.
 * Hover is transient UI state, separate from state machine.
 */
const hoverAtomCache = new Map<BlockId, Atom.Atom<boolean>>();

/**
 * Get or create hover atom for a specific block.
 * Returns a writable atom for local hover state.
 */
export const getHoverAtom = (blockId: BlockId): Atom.Atom<boolean> => {
  let atom = hoverAtomCache.get(blockId);
  if (!atom) {
    atom = Atom.make(false);
    hoverAtomCache.set(blockId, atom);
  }
  return atom;
};

/**
 * Clear hover atom for a specific block.
 */
export const clearHoverAtom = (blockId: BlockId): void => {
  hoverAtomCache.delete(blockId);
};

/**
 * Clipboard Utilities
 *
 * Copy operations for block name and ID.
 * Uses navigator.clipboard API with fallback.
 *
 * @module editor/v3/extensions/blocks/BlockNameBadge/clipboard
 */

// =============================================================================
// Types
// =============================================================================

export interface CopyResult {
  success: boolean;
  error?: string;
}

// =============================================================================
// Copy Functions
// =============================================================================

/**
 * Copy text to clipboard using modern API with fallback.
 */
async function copyToClipboard(text: string): Promise<CopyResult> {
  // Try modern clipboard API first
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return { success: true };
    } catch (err) {
      // Fall through to fallback
      console.warn('Clipboard API failed, trying fallback:', err);
    }
  }

  // Fallback: execCommand (deprecated but widely supported)
  try {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.left = '-9999px';
    textArea.style.top = '-9999px';
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();

    const successful = document.execCommand('copy');
    document.body.removeChild(textArea);

    if (successful) {
      return { success: true };
    } else {
      return { success: false, error: 'execCommand failed' };
    }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Copy failed',
    };
  }
}

/**
 * Copy block name to clipboard.
 *
 * @param name - The block name to copy (without @ prefix)
 */
export async function copyBlockName(name: string | null): Promise<void> {
  if (!name) {
    throw new Error('No block name to copy');
  }

const result = await copyToClipboard(name);
  if (!result.success) {
    throw new Error(result.error ?? 'Failed to copy name');
  }
}

/**
 * Copy block ID to clipboard.
 *
 * @param blockId - The full block ID to copy
 */
export async function copyBlockId(blockId: string): Promise<void> {
  if (!blockId) {
    throw new Error('No block ID to copy');
  }

  const result = await copyToClipboard(blockId);
  if (!result.success) {
    throw new Error(result.error ?? 'Failed to copy ID');
  }
}

/**
 * Copy formatted block reference to clipboard.
 * Format: @name (blockId)
 *
 * @param name - The block name
 * @param blockId - The block ID
 */
export async function copyBlockReference(
  name: string | null,
  blockId: string
): Promise<void> {
  const displayName = name ?? 'untitled';
  const text = `@${displayName} (${blockId})`;

  const result = await copyToClipboard(text);
  if (!result.success) {
    throw new Error(result.error ?? 'Failed to copy reference');
  }
}

