    if (state.matches('submitting')) {
      animatePulse();
    }
  }, [state, animatePulse]);

  useEffect(() => {
    if (state.matches('success')) {
      animateSuccess();
      const timer = setTimeout(() => send({ type: 'RESET' }), 600);
      return () => clearTimeout(timer);
    }
  }, [state, animateSuccess, send]);

  useEffect(() => {
    if (state.matches('error')) {
