);

export const useEmbeddedBlock = () => {
  const ctx = useContext(EmbeddedBlockContext);
  if (!ctx) {
    throw new Error(
      'useEmbeddedBlock must be used within EmbeddedBlockWrapper'
    );
  }
  return ctx;
};

