interface ResizeHandleProps {
  onResize: (deltaY: number) => void;
  onResizeEnd: () => void;
  minHeight?: number;
  maxHeight?: number;
  disabled?: boolean;
}

interface ResizeHandleProps {
  onResize: (deltaY: number) => void;
  onResizeEnd: () => void;
  minHeight?: number;
  maxHeight?: number;
  disabled?: boolean;
}

function ResizeHandle({
  onResize,
  onResizeEnd,
  disabled = false,
}: ResizeHandleProps) {
  const [isDragging, setIsDragging] = useState(false);
  const startYRef = useRef(0);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (disabled) return;
      e.preventDefault();
      e.stopPropagation();
      setIsDragging(true);
      startYRef.current = e.clientY;
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    },
    [disabled]
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) return;
      e.preventDefault();
      e.stopPropagation();
      const deltaY = e.clientY - startYRef.current;
      startYRef.current = e.clientY;
      onResize(deltaY);
    },
    [isDragging, onResize]
  );

  const handlePointerUp = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) return;
      e.preventDefault();
      e.stopPropagation();
      setIsDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
      onResizeEnd();
    },
    [isDragging, onResizeEnd]
  );

  if (disabled) return null;

if (disabled) return null;

  return (
    <div
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      style={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        height: '12px',
        cursor: 'ns-resize',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: isDragging
          ? VANTA_COLORS.surface.hover
          : 'transparent',
        transition: isDragging
          ? 'none'
          : `background-color ${VANTA_ANIMATION.duration.fast}`,
        zIndex: 10,
      }}
      title="Drag to resize"
    >
      <div
        style={{
          width: '48px',
          height: '4px',
          borderRadius: '2px',
          backgroundColor: isDragging
            ? VANTA_COLORS.accent.cyan
            : VANTA_COLORS.surface.border,
          opacity: isDragging ? 1 : 0.6,
          transition: isDragging
            ? 'none'
            : `all ${VANTA_ANIMATION.duration.fast}`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <GripHorizontal
          size={10}
          style={{
            color: isDragging
              ? VANTA_COLORS.surface.elevated
              : VANTA_COLORS.text.muted,
          }}
        />
      </div>
    </div>
  );
}

