   */
  title?: string;

  /**
   * Icon to display next to the title.
   */
  icon?: React.ComponentType<{ size?: number; className?: string }>;

  /**
   * Callback when exiting focus mode.
   * Called before focusActions.exitFocus().
   */
  onExit?: () => void;
}

// =============================================================================
// Component
// =============================================================================

export function FocusOverlay({
  children,
  title = 'Focus Mode',
  icon: Icon,
  onExit,
}: FocusOverlayProps) {
  const isFocusMode = useAtomValue(isFocusModeAtom);
  const focusedBlockId = useAtomValue(focusedBlockIdAtom);

  // Inject keyframes on mount
  useEffect(() => {
    injectKeyframes();
  }, []);

  // Handle exit
  const handleExit = useCallback(() => {
    onExit?.();
    focusActions.exitFocus();
  }, [onExit]);

  // Handle backdrop click
  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
        handleExit();
      }
    },
    [handleExit]
  );

  // Handle Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isFocusMode) {
        e.preventDefault();
        e.stopPropagation();
        handleExit();
      }
    };

document.addEventListener('keydown', handleKeyDown, true);
    return () => document.removeEventListener('keydown', handleKeyDown, true);
  }, [isFocusMode, handleExit]);

  // Prevent body scroll when overlay is open
  useEffect(() => {
    if (isFocusMode) {
      const originalOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = originalOverflow;
      };
    }
  }, [isFocusMode]);

  // Don't render if not in focus mode
  if (!isFocusMode) {
    return null;
  }

  const overlay = (
    <div
      style={overlayStyle}
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="focus-overlay-title"
    >
      {/* Backdrop */}
      <div
        style={{
          ...backdropStyle,
          animation: 'focusBackdropEnter 200ms ease-out',
        }}
      />

      {/* Content container */}
      <div style={contentContainerStyle}>
        {/* Header */}
        <div style={headerStyle}>
          <span id="focus-overlay-title" style={titleStyle}>
            <Maximize2 size={14} />
            {Icon && <Icon size={14} />}
            {title}
            {focusedBlockId && (
              <span style={{ color: VANTA_COLORS.text.muted }}>
                — {focusedBlockId}
              </span>
            )}
          </span>

