/**
 * SQLite row shape for block_states table
 *
 * Used for encode/decode between BlockState and database rows.
 */
export const BlockStateRow = Schema.Struct({
  block_id: Schema.String,
  fold_state: Schema.String,
  settings_open: Schema.Number, // SQLite boolean as 0/1
  active_tab: Schema.String,
  node_attrs: Schema.String, // JSON stringified
  saved_at: Schema.String, // ISO string
});
export type BlockStateRow = typeof BlockStateRow.Type;

/**
 * Transform between BlockState and BlockStateRow
 */
export const BlockStateFromRow = Schema.transform(BlockStateRow, BlockState, {
  decode: (row) =>
    new BlockState({
      blockId: row.block_id as BlockId,
      foldState: row.fold_state as FoldState,
      settingsOpen: row.settings_open === 1,
      activeTab: row.active_tab,
      nodeAttrs: JSON.parse(row.node_attrs),
      savedAt: new Date(row.saved_at),
    }),
  encode: (state) => ({
    block_id: state.blockId,
    fold_state: state.foldState,
    settings_open: state.settingsOpen ? 1 : 0,
    active_tab: state.activeTab,
    node_attrs: JSON.stringify(state.nodeAttrs),
    saved_at: state.savedAt.toISOString(),
  }),
});

import { Effect, HashMap, Option, PubSub, Schema } from 'effect';
import {
  BlockId,
  BlockName,
  BlockRef,
  BlockType,
  EditorContext,
} from '../shared';
import {
  BlockRegistryError,
  BlockRegistryEvent,
  createBlockNameConflictError,
  createBlockNotFoundError,
  createInvalidBlockNameError,
} from './schemas';

interface BlockRegistryState {
  readonly blocks: HashMap.HashMap<BlockId, BlockRef>;
  readonly nameIndex: HashMap.HashMap<BlockName, BlockId>;
}

const emptyState: BlockRegistryState = {
  blocks: HashMap.empty(),
  nameIndex: HashMap.empty(),
};

export class BlockRegistry extends Effect.Service<BlockRegistry>()(
  'editor/BlockRegistry',
  {
    effect: Effect.gen(function* () {
      const documentId = yield* EditorContext;
      const eventHub = yield* PubSub.unbounded<BlockRegistryEvent>();

      let state: BlockRegistryState = emptyState;

      const publishEvent = (event: BlockRegistryEvent) =>
        Effect.flatMap(PubSub.publish(eventHub, event), () => Effect.void);

      const validateName = (name: string) =>
        Effect.gen(function* () {
          const result = Schema.decodeUnknownOption(BlockName)(name);
          if (Option.isNone(result)) {
            yield* Effect.fail(
              createInvalidBlockNameError(
                name,
                'Must start with lowercase letter, contain only lowercase letters, numbers, and dashes'
              )
            );
            throw new Error('unreachable');
          }
          return result.value;
        });

      const register = (id: BlockId, type: BlockType, name?: BlockName) =>
        Effect.gen(function* () {
          if (name) {
            const existing = HashMap.get(state.nameIndex, name);
            if (Option.isSome(existing)) {
              yield* Effect.fail(
                createBlockNameConflictError(name, existing.value)
              );
              throw new Error('unreachable');
            }
          }

const now = new Date();
          const block = new BlockRef({
            id,
            name: name ? Option.some(name) : Option.none(),
            type,
            documentId,
            registeredAt: now,
            namedAt: name ? Option.some(now) : Option.none(),
          });

          state = {
            blocks: HashMap.set(state.blocks, id, block),
            nameIndex: name
              ? HashMap.set(state.nameIndex, name, id)
              : state.nameIndex,
          };

          yield* publishEvent({
            _tag: 'BlockRegistered',
            blockId: id,
            blockType: type,
            documentId,
            timestamp: now,
          });

          return block;
        });

      const rename = (id: BlockId, newName: string) =>
        Effect.gen(function* () {
          const maybeBlock = HashMap.get(state.blocks, id);
          if (Option.isNone(maybeBlock)) {
            yield* Effect.fail(createBlockNotFoundError(id));
            throw new Error('unreachable');
          }

          const block = maybeBlock.value;
          const validatedName = yield* validateName(newName);

          const existingWithName = HashMap.get(state.nameIndex, validatedName);
          if (
            Option.isSome(existingWithName) &&
            existingWithName.value !== id
          ) {
            yield* Effect.fail(
              createBlockNameConflictError(
                validatedName,
                existingWithName.value
              )
            );
            throw new Error('unreachable');
          }

          const oldName = block.name;
          const now = new Date();
          const updated = new BlockRef({
            ...block,
            name: Option.some(validatedName),
            namedAt: Option.some(now),
          });

          let newNameIndex = state.nameIndex;
          if (Option.isSome(oldName)) {
            newNameIndex = HashMap.remove(newNameIndex, oldName.value);
          }
          newNameIndex = HashMap.set(newNameIndex, validatedName, id);

state = {
            blocks: HashMap.set(state.blocks, id, updated),
            nameIndex: newNameIndex,
          };

          yield* publishEvent({
            _tag: 'BlockRenamed',
            blockId: id,
            oldName: Option.getOrNull(oldName),
            newName: validatedName,
            timestamp: now,
          });

          return updated;
        });

      const unregister = (id: BlockId) =>
        Effect.gen(function* () {
          const maybeBlock = HashMap.get(state.blocks, id);
          if (Option.isNone(maybeBlock)) {
            yield* Effect.fail(createBlockNotFoundError(id));
            throw new Error('unreachable');
          }

          const block = maybeBlock.value;
          let newNameIndex = state.nameIndex;
          if (Option.isSome(block.name)) {
            newNameIndex = HashMap.remove(newNameIndex, block.name.value);
          }

          state = {
            blocks: HashMap.remove(state.blocks, id),
            nameIndex: newNameIndex,
          };

          yield* publishEvent({
            _tag: 'BlockUnregistered',
            blockId: id,
            timestamp: new Date(),
          });
        });

      const getById = (id: BlockId): Option.Option<BlockRef> =>
        HashMap.get(state.blocks, id);

      const getByName = (name: BlockName): Option.Option<BlockRef> => {
        const maybeId = HashMap.get(state.nameIndex, name);
        if (Option.isNone(maybeId)) return Option.none();
        return HashMap.get(state.blocks, maybeId.value);
      };

      const getAll = (): ReadonlyArray<BlockRef> =>
        Array.from(HashMap.values(state.blocks));

      const getAllNamed = (): ReadonlyArray<BlockRef> =>
        getAll().filter((block) => Option.isSome(block.name));

      const subscribeEvents = () => PubSub.subscribe(eventHub);

const getAllNamed = (): ReadonlyArray<BlockRef> =>
        getAll().filter((block) => Option.isSome(block.name));

      const subscribeEvents = () => PubSub.subscribe(eventHub);

      return {
        register,
        rename,
        unregister,
        getById,
        getByName,
        getAll,
        getAllNamed,
        subscribeEvents,
        documentId,
      } as const;
    }),
    dependencies: [],
  }
) {}

import {
  createContext,
  useContext,
  useMemo,
  useCallback,
  useRef,
  type ReactNode,
} from 'react';
import { useAtomValue } from '@effect-atom/atom-react';
import { Effect, ManagedRuntime } from 'effect';

import { currentDocumentIdAtom } from '../../../../atoms/documents';
import type { BlockId, BlockName, BlockType, BlockRef } from '../shared';
import { BlockRegistry } from './BlockRegistry';
import { createBlockRegistryLayer } from './atoms';

interface BlockRegistryOps {
  register: (
    id: BlockId,
    type: BlockType,
    name?: BlockName
  ) => Promise<BlockRef>;
  rename: (id: BlockId, newName: string) => Promise<BlockRef>;
  unregister: (id: BlockId) => Promise<void>;
  clearRenameError: () => void;
}

interface BlockRegistryContextValue {
  isAvailable: boolean;
  ops: BlockRegistryOps;
}

const BlockRegistryContext = createContext<BlockRegistryContextValue | null>(
  null
);

interface BlockRegistryProviderProps {
  children: ReactNode;
  /**
   * Optional document ID to use for the block registry.
   * If provided, overrides the global currentDocumentIdAtom.
   * This is necessary for panel-scoped registries in collaboration testbed.
   */
  documentId?: string;
}

export function BlockRegistryProvider({
  children,
  documentId: documentIdProp,
}: BlockRegistryProviderProps) {
  const documentIdFromAtom = useAtomValue(currentDocumentIdAtom);
  const documentId = documentIdProp ?? documentIdFromAtom;

  const runtimeRef = useRef<ManagedRuntime.ManagedRuntime<
    BlockRegistry,
    never
  > | null>(null);

  const runtime = useMemo(() => {
    if (!documentId) {
      runtimeRef.current = null;
      return null;
    }

const runtime = useMemo(() => {
    if (!documentId) {
      runtimeRef.current = null;
      return null;
    }

    const layer = createBlockRegistryLayer(documentId);
    const rt = ManagedRuntime.make(layer);
    runtimeRef.current = rt;
    return rt;
  }, [documentId]);

  const register = useCallback(
    async (
      id: BlockId,
      type: BlockType,
      name?: BlockName
    ): Promise<BlockRef> => {
      const rt = runtimeRef.current;
      if (!rt) throw new Error('BlockRegistry not available');

      return rt.runPromise(
        Effect.gen(function* () {
          const registry = yield* BlockRegistry;
          return yield* registry.register(id, type, name);
        })
      );
    },
    []
  );

  const rename = useCallback(
    async (id: BlockId, newName: string): Promise<BlockRef> => {
      const rt = runtimeRef.current;
      if (!rt) throw new Error('BlockRegistry not available');

      return rt.runPromise(
        Effect.gen(function* () {
          const registry = yield* BlockRegistry;
          return yield* registry.rename(id, newName);
        })
      );
    },
    []
  );

  const unregister = useCallback(async (id: BlockId): Promise<void> => {
    const rt = runtimeRef.current;
    if (!rt) throw new Error('BlockRegistry not available');

    return rt.runPromise(
      Effect.gen(function* () {
        const registry = yield* BlockRegistry;
        yield* registry.unregister(id);
      })
    );
  }, []);

  const clearRenameError = useCallback(() => {
    // Direct atom mutation - no Effect needed
  }, []);

const clearRenameError = useCallback(() => {
    // Direct atom mutation - no Effect needed
  }, []);

  const contextValue = useMemo<BlockRegistryContextValue>(
    () => ({
      isAvailable: !!documentId && !!runtime,
      ops: {
        register,
        rename,
        unregister,
        clearRenameError,
      },
    }),
    [documentId, runtime, register, rename, unregister, clearRenameError]
  );

  return (
    <BlockRegistryContext.Provider value={contextValue}>
      {children}
    </BlockRegistryContext.Provider>
  );
}

export function useBlockRegistry(): BlockRegistryContextValue {
  const ctx = useContext(BlockRegistryContext);
  if (!ctx) {
    throw new Error(
      'useBlockRegistry must be used within BlockRegistryProvider'
    );
  }
  return ctx;
}

export function useBlockRegistryOptional(): BlockRegistryContextValue | null {
  return useContext(BlockRegistryContext);
}

import { Atom } from '@effect-atom/atom';
import { Effect, Layer, Option } from 'effect';
import {
  BlockId,
  BlockName,
  BlockRef,
  BlockType,
  DocumentId,
  EditorContext,
} from '../shared';
import type { BlockRegistryError } from './schemas';
import { BlockRegistry } from './BlockRegistry';

export const blocksAtom = Atom.make<ReadonlyArray<BlockRef>>([]);
export const namedBlocksAtom = Atom.make<ReadonlyArray<BlockRef>>([]);

export const blockByIdAtom = Atom.family((_id: BlockId) =>
  Atom.make<Option.Option<BlockRef>>(Option.none())
);

export const blockByNameAtom = Atom.family((_name: BlockName) =>
  Atom.make<Option.Option<BlockRef>>(Option.none())
);

export const renameErrorAtom = Atom.make<Option.Option<BlockRegistryError>>(
  Option.none()
);

export const isRenamingAtom = Atom.make<Option.Option<BlockId>>(Option.none());

export const createBlockRegistryLayer = (documentId: string) =>
  Layer.provideMerge(
    BlockRegistry.Default,
    EditorContext.layer(documentId as DocumentId)
  );

export const createBlockRegistryRuntime = (documentId: string) =>
  Atom.runtime(
    createBlockRegistryLayer(documentId) as Layer.Layer<BlockRegistry>
  );

type BlockRegistryRuntime = ReturnType<typeof createBlockRegistryRuntime>;

interface RegisterInput {
  id: BlockId;
  type: BlockType;
  name?: BlockName;
}

interface RenameInput {
  id: BlockId;
  newName: string;
}

interface UnregisterInput {
  id: BlockId;
}

export const createBlockRegistryOps = (runtime: BlockRegistryRuntime) => ({
  register: runtime.fn<RegisterInput>()(({ id, type, name }, ctx) =>
    Effect.gen(function* () {
      const registry = yield* BlockRegistry;
      const block = yield* registry.register(id, type, name);

ctx.set(blocksAtom, registry.getAll());
      ctx.set(namedBlocksAtom, registry.getAllNamed());
      ctx.set(blockByIdAtom(id), Option.some(block));
      if (name) {
        ctx.set(blockByNameAtom(name), Option.some(block));
      }

      return block;
    })
  ),

  rename: runtime.fn<RenameInput>()(({ id, newName }, ctx) =>
    Effect.gen(function* () {
      ctx.set(isRenamingAtom, Option.some(id));
      ctx.set(renameErrorAtom, Option.none());

      const registry = yield* BlockRegistry;
      const result = yield* Effect.either(registry.rename(id, newName));

      if (result._tag === 'Left') {
        ctx.set(renameErrorAtom, Option.some(result.left));
        ctx.set(isRenamingAtom, Option.none());
        yield* Effect.fail(result.left);
        throw new Error('unreachable');
      }

      const block = result.right;
      ctx.set(blocksAtom, registry.getAll());
      ctx.set(namedBlocksAtom, registry.getAllNamed());
      ctx.set(blockByIdAtom(id), Option.some(block));
      if (Option.isSome(block.name)) {
        ctx.set(blockByNameAtom(block.name.value), Option.some(block));
      }
      ctx.set(isRenamingAtom, Option.none());

      return block;
    })
  ),

  unregister: runtime.fn<UnregisterInput>()(({ id }, ctx) =>
    Effect.gen(function* () {
      const registry = yield* BlockRegistry;
      const maybeBlock = registry.getById(id);

      yield* registry.unregister(id);

      ctx.set(blocksAtom, registry.getAll());
      ctx.set(namedBlocksAtom, registry.getAllNamed());
      ctx.set(blockByIdAtom(id), Option.none());

      if (Option.isSome(maybeBlock) && Option.isSome(maybeBlock.value.name)) {
        ctx.set(blockByNameAtom(maybeBlock.value.name.value), Option.none());
      }
    })
  ),

if (Option.isSome(maybeBlock) && Option.isSome(maybeBlock.value.name)) {
        ctx.set(blockByNameAtom(maybeBlock.value.name.value), Option.none());
      }
    })
  ),

  clearRenameError: runtime.fn<void>()((_, ctx) =>
    Effect.sync(() => {
      ctx.set(renameErrorAtom, Option.none());
    })
  ),
});

