  ) => Effect.Effect<PersistedBlock, SqlError>;

  /**
   * Find a block by ID
   */
  readonly findById: (
    blockId: BlockId
  ) => Effect.Effect<Option.Option<PersistedBlock>, SqlError>;

  /**
   * Find a block by name within a document
   */
  readonly findByName: (
    documentId: DocumentId,
