                  .insertContent({ type: this.name })
                  .command(({ tr, dispatch }) => {
                    if (dispatch && marks && this.options.keepMarks) {
                      tr.ensureMarks(marks);
                    }

                    return true;
                  })
                  .run();
              }),
          ]);
        },
    };
  },

