  name: 'orderedList',

  addOptions() {
    return {
      HTMLAttributes: {},
      itemTypeName: 'listItem',
      keepMarks: false,
      keepAttributes: false,
    };
  },

  group: 'block list',

  content() {
    return `${this.options.itemTypeName}+`;
  },

