    setIsLoading(false);
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => disposeScene3DBlockAtoms(blockId);
  }, [blockId]);

  // Handlers
  const togglePlay = useCallback(() => {
    setIsPlaying((prev) => !prev);
  }, [setIsPlaying]);

  const handleTimeScaleChange = useCallback(
