  streamId: string,
  options?: {
    replay?: boolean
    fromOffset?: string
    clearOnStart?: boolean
  }
): MaterializeOptions<StreamEntityPayload> {
  return {
    streamId,
    schema: StreamEntityPayload,
    toTraits: (payload) => {
      // Flatten: each entity in payload becomes separate entities
