  const wrapperRef = useRef<HTMLLabelElement>(null);
  const sheenRef = useRef<HTMLSpanElement>(null);
  const sparkleContainerRef = useRef<HTMLDivElement>(null);

  const [state, send] = useMachine(taskCheckboxMachine, {
