      const normalize = (
        markdown: string
      ): Effect.Effect<string, MarkdownParseError | MarkdownSerializeError> =>
        Effect.gen(function* () {
          const json = yield* parse(markdown);
          return yield* serialize(json);
        });

      // --- IS MARKDOWN ---
      const isMarkdown = (content: string): Effect.Effect<boolean, never> =>
