const getDirectoryContents = (dirPath: string): MockFile[] => {
  return MOCK_FILES.filter((f) => {
    if (f.path === dirPath) return false; // Exclude self
    const parent = f.path.substring(0, f.path.lastIndexOf('/')) || '/';
    return parent === dirPath;
  });
};

