// Helpers
// =============================================================================

/**
 * Parse a simple key string into a KeyChord.
 * Supports: ctrl, alt, shift, meta (cmd) modifiers.
 *
 * Examples:
 *   'ctrl+=' → { ctrl: true, key: '=' }
 *   'ctrl+shift+p' → { ctrl: true, shift: true, key: 'p' }
 */
function parseKeyString(keyStr: string): KeyChord {
  const parts = keyStr.toLowerCase().split('+');
  const key = parts.pop() ?? '';

  const chord: KeyChord = {
    ctrl: parts.includes('ctrl'),
    alt: parts.includes('alt'),
    shift: parts.includes('shift'),
    meta: parts.includes('meta') || parts.includes('cmd'),
    key: normalizeKey(key),
  };

  return chord;
}

/**
 * Normalize key name to match event.key format.
 */
function normalizeKey(key: string): string {
  switch (key) {
    case 'space':
      return ' ';
    case 'esc':
    case 'escape':
      return 'esc';
    case 'up':
      return 'up';
    case 'down':
      return 'down';
    case 'left':
      return 'left';
    case 'right':
      return 'right';
    case 'backspace':
      return 'backspace';
    case 'delete':
      return 'delete';
    case 'enter':
      return 'enter';
    case 'tab':
      return 'tab';
    default:
      return key;
  }
}

