/**
 * Result of a reconciliation operation
 */
export interface ReconcileResult {
  /** Number of nodes inserted */
  readonly inserted: number
  /** Number of nodes deleted */
  readonly deleted: number
  /** Number of nodes updated */
  readonly updated: number
  /** Duration in milliseconds */
  readonly durationMs: number
}

/**
 * Progressive reconciliation update (for streaming)
 */
export interface ReconcileUpdate extends ReconcileResult {
  /** Block that was reconciled */
  readonly block: JSONNode
  /** Running total of blocks processed */
  readonly totalBlocks: number
}

// =============================================================================
// Document JSON Types
// =============================================================================

/**
 * JSON representation of a ProseMirror node
 * Compatible with TipTap's getJSON/setContent
 */
export interface JSONNode {
  /** Node type name */
  readonly type: string
  /** Node attributes */
  readonly attrs?: Record<string, unknown>
  /** Child nodes (for non-leaf nodes) */
  readonly content?: readonly JSONNode[]
  /** Text content (for text nodes) */
  readonly text?: string
  /** Marks on text */
  readonly marks?: readonly JSONMark[]
}

/**
 * JSON representation of a ProseMirror mark
 */
export interface JSONMark {
  readonly type: string
  readonly attrs?: Record<string, unknown>
}

/**
 * Full document JSON
 */
export interface JSONDocument {
  readonly type: 'doc'
  readonly content: readonly JSONNode[]
}

// =============================================================================
// Block Types (for streaming)
// =============================================================================

/**
 * Token emitted from AI SDK stream
 */
export interface AIToken {
  /** Raw JSON string fragment */
  readonly raw: string
  /** Parsed partial object (if complete enough) */
  readonly partial?: Partial<JSONNode>
}

/**
 * Batched block ready for reconciliation
 */
export interface BlockBatch {
  /** Complete nodes in this batch */
  readonly nodes: readonly JSONNode[]
  /** Timestamp of batch creation */
  readonly timestamp: number
  /** Whether this is the final batch */
  readonly isFinal: boolean
}

// =============================================================================
// Reconciler Errors
// =============================================================================

/**
 * Error during reconciliation
 */
export class ReconcilerError extends Error {
  readonly _tag = 'ReconcilerError'

// =============================================================================
// Reconciler Errors
// =============================================================================

/**
 * Error during reconciliation
 */
export class ReconcilerError extends Error {
  readonly _tag = 'ReconcilerError'

  constructor(
    readonly operation: string,
    readonly cause: unknown,
    message?: string
  ) {
    super(message ?? `Reconciler error during ${operation}`)
    this.name = 'ReconcilerError'
  }
}

/**
 * Error during schema validation
 */
export class SchemaValidationError extends Error {
  readonly _tag = 'SchemaValidationError'

  constructor(
    readonly nodeType: string,
    readonly cause: unknown,
    message?: string
  ) {
    super(message ?? `Schema validation failed for node type: ${nodeType}`)
    this.name = 'SchemaValidationError'
  }
}

/**
 * Tool Schema Tests
 *
 * Unit tests for AI SDK tool parameter and result schemas.
 * Validates Effect.Schema encoding/decoding, refinements, and edge cases.
 */

import { describe, it, expect } from '@effect/vitest'
import { Effect, Schema } from 'effect'
import {
  InsertTextParams,
  ReplaceSelectionParams,
  FocusEditorParams,
  GetContentRangeParams,
  SetSelectionParams,
  EmptyParams,
  ToolSuccess,
  InsertTextToolResult,
  ReadSelectionResult,
  GetContextResult,
  ListEditorsToolResult,
  ContentRangeResult,
} from '../tools'

// -----------------------------------------------------------------------------
// Parameter Schema Tests
// -----------------------------------------------------------------------------

describe('Tool Parameter Schemas', () => {
  describe('InsertTextParams', () => {
    it.effect('decodes valid params with content only', () =>
      Effect.gen(function* () {
        const input = { content: 'Hello, world!' }
        const decoded = yield* Schema.decodeUnknown(InsertTextParams)(input)
        expect(decoded.content).toBe('Hello, world!')
        expect(decoded.moveCursor).toBeUndefined()
      })
    )

    it.effect('decodes valid params with moveCursor', () =>
      Effect.gen(function* () {
        const input = { content: 'text', moveCursor: false }
        const decoded = yield* Schema.decodeUnknown(InsertTextParams)(input)
        expect(decoded.content).toBe('text')
        expect(decoded.moveCursor).toBe(false)
      })
    )

    it.effect('encodes and decodes roundtrip', () =>
      Effect.gen(function* () {
        const original = { content: 'test content', moveCursor: true }
        const encoded = yield* Schema.encode(InsertTextParams)(original)
        const decoded = yield* Schema.decode(InsertTextParams)(encoded)
        expect(decoded).toEqual(original)
      })
    )

it.effect('rejects missing content', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(InsertTextParams)({}).pipe(
          Effect.either
        )
        expect(result._tag).toBe('Left')
      })
    )
  })

  describe('ReplaceSelectionParams', () => {
    it.effect('decodes valid params', () =>
      Effect.gen(function* () {
        const input = { content: 'replacement text' }
        const decoded = yield* Schema.decodeUnknown(ReplaceSelectionParams)(input)
        expect(decoded.content).toBe('replacement text')
      })
    )

    it.effect('accepts empty string content', () =>
      Effect.gen(function* () {
        const input = { content: '' }
        const decoded = yield* Schema.decodeUnknown(ReplaceSelectionParams)(input)
        expect(decoded.content).toBe('')
      })
    )
  })

  describe('FocusEditorParams', () => {
    it.effect('decodes valid editor ID', () =>
      Effect.gen(function* () {
        const input = { editorId: 'editor-panel-123' }
        const decoded = yield* Schema.decodeUnknown(FocusEditorParams)(input)
        expect(decoded.editorId).toBe('editor-panel-123')
      })
    )

    it.effect('rejects missing editorId', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(FocusEditorParams)({}).pipe(
          Effect.either
        )
        expect(result._tag).toBe('Left')
      })
    )
  })

  describe('GetContentRangeParams', () => {
    it.effect('decodes valid range', () =>
      Effect.gen(function* () {
        const input = { from: 0, to: 100 }
        const decoded = yield* Schema.decodeUnknown(GetContentRangeParams)(input)
        expect(decoded.from).toBe(0)
        expect(decoded.to).toBe(100)
      })
    )

it.effect('accepts same from and to (empty range)', () =>
      Effect.gen(function* () {
        const input = { from: 50, to: 50 }
        const decoded = yield* Schema.decodeUnknown(GetContentRangeParams)(input)
        expect(decoded.from).toBe(50)
        expect(decoded.to).toBe(50)
      })
    )

    it.effect('rejects negative from', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(GetContentRangeParams)({
          from: -1,
          to: 10,
        }).pipe(Effect.either)
        expect(result._tag).toBe('Left')
      })
    )

    it.effect('rejects negative to', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(GetContentRangeParams)({
          from: 0,
          to: -5,
        }).pipe(Effect.either)
        expect(result._tag).toBe('Left')
      })
    )

    it.effect('rejects non-integer from', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(GetContentRangeParams)({
          from: 0.5,
          to: 10,
        }).pipe(Effect.either)
        expect(result._tag).toBe('Left')
      })
    )
  })

  describe('SetSelectionParams', () => {
    it.effect('decodes valid selection range', () =>
      Effect.gen(function* () {
        const input = { from: 10, to: 20 }
        const decoded = yield* Schema.decodeUnknown(SetSelectionParams)(input)
        expect(decoded.from).toBe(10)
        expect(decoded.to).toBe(20)
      })
    )

it.effect('accepts zero positions', () =>
      Effect.gen(function* () {
        const input = { from: 0, to: 0 }
        const decoded = yield* Schema.decodeUnknown(SetSelectionParams)(input)
        expect(decoded.from).toBe(0)
        expect(decoded.to).toBe(0)
      })
    )
  })

  describe('EmptyParams', () => {
    it.effect('decodes empty object', () =>
      Effect.gen(function* () {
        const input = {}
        const decoded = yield* Schema.decodeUnknown(EmptyParams)(input)
        expect(decoded).toEqual({})
      })
    )

    it.effect('accepts object with extra properties', () =>
      Effect.gen(function* () {
        // Effect.Schema preserves extra properties by default (unlike Zod)
        // This is expected behavior - use Schema.Struct with { strict: true } to strip
        const input = { extra: 'preserved', another: 123 }
        const decoded = yield* Schema.decodeUnknown(EmptyParams)(input)
        // The decode succeeds - extra properties are preserved
        expect(decoded).toBeDefined()
      })
    )
  })
})

// -----------------------------------------------------------------------------
// Result Schema Tests
// -----------------------------------------------------------------------------

describe('Tool Result Schemas', () => {
  describe('ToolSuccess', () => {
    it.effect('decodes success true', () =>
      Effect.gen(function* () {
        const input = { success: true }
        const decoded = yield* Schema.decodeUnknown(ToolSuccess)(input)
        expect(decoded.success).toBe(true)
      })
    )

    it.effect('rejects success false', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(ToolSuccess)({
          success: false,
        }).pipe(Effect.either)
        expect(result._tag).toBe('Left')
      })
    )
  })

describe('InsertTextToolResult', () => {
    it.effect('decodes valid result', () =>
      Effect.gen(function* () {
        const input = { success: true, charsInserted: 10, newPosition: 25 }
        const decoded = yield* Schema.decodeUnknown(InsertTextToolResult)(input)
        expect(decoded.success).toBe(true)
        expect(decoded.charsInserted).toBe(10)
        expect(decoded.newPosition).toBe(25)
      })
    )

    it.effect('accepts zero charsInserted', () =>
      Effect.gen(function* () {
        const input = { success: true, charsInserted: 0, newPosition: 0 }
        const decoded = yield* Schema.decodeUnknown(InsertTextToolResult)(input)
        expect(decoded.charsInserted).toBe(0)
      })
    )

    it.effect('rejects negative charsInserted', () =>
      Effect.gen(function* () {
        const result = yield* Schema.decodeUnknown(InsertTextToolResult)({
          success: true,
          charsInserted: -1,
          newPosition: 0,
        }).pipe(Effect.either)
        expect(result._tag).toBe('Left')
      })
    )
  })

  describe('ReadSelectionResult', () => {
    it.effect('decodes result with selection', () =>
      Effect.gen(function* () {
        const input = {
          selection: { from: 0, to: 10, empty: false },
          text: 'selected text',
        }
        const decoded = yield* Schema.decodeUnknown(ReadSelectionResult)(input)
        expect(decoded.selection).toEqual({ from: 0, to: 10, empty: false })
        expect(decoded.text).toBe('selected text')
      })
    )

    it.effect('decodes result with null selection', () =>
      Effect.gen(function* () {
        const input = { selection: null, text: null }
        const decoded = yield* Schema.decodeUnknown(ReadSelectionResult)(input)
        expect(decoded.selection).toBeNull()
        expect(decoded.text).toBeNull()
      })
    )
  })

describe('GetContextResult', () => {
    it.effect('decodes full context', () =>
      Effect.gen(function* () {
        const input = {
          editorId: 'editor-1',
          title: 'Document Title',
          selection: { from: 5, to: 15, empty: false },
          selectedText: 'some text',
          surroundingContext: 'prefix some text suffix',
          wordCount: 100,
          cursorPosition: 5,
        }
        const decoded = yield* Schema.decodeUnknown(GetContextResult)(input)
        expect(decoded.editorId).toBe('editor-1')
        expect(decoded.title).toBe('Document Title')
        expect(decoded.wordCount).toBe(100)
      })
    )

    it.effect('decodes context with nulls', () =>
      Effect.gen(function* () {
        const input = {
          editorId: 'editor-1',
          title: null,
          selection: null,
          selectedText: null,
          surroundingContext: null,
          wordCount: 0,
          cursorPosition: 0,
        }
        const decoded = yield* Schema.decodeUnknown(GetContextResult)(input)
        expect(decoded.title).toBeNull()
        expect(decoded.selection).toBeNull()
      })
    )
  })

  describe('ListEditorsToolResult', () => {
    it.effect('decodes with editors', () =>
      Effect.gen(function* () {
        const input = {
          editors: ['editor-1', 'editor-2', 'editor-3'],
          focused: 'editor-2',
          count: 3,
        }
        const decoded = yield* Schema.decodeUnknown(ListEditorsToolResult)(input)
        expect(decoded.editors).toHaveLength(3)
        expect(decoded.focused).toBe('editor-2')
        expect(decoded.count).toBe(3)
      })
    )

it.effect('decodes with no focused editor', () =>
      Effect.gen(function* () {
        const input = {
          editors: [],
          focused: null,
          count: 0,
        }
        const decoded = yield* Schema.decodeUnknown(ListEditorsToolResult)(input)
        expect(decoded.editors).toHaveLength(0)
        expect(decoded.focused).toBeNull()
        expect(decoded.count).toBe(0)
      })
    )
  })

  describe('ContentRangeResult', () => {
    it.effect('decodes valid range result', () =>
      Effect.gen(function* () {
        const input = { content: 'extracted content', from: 10, to: 27 }
        const decoded = yield* Schema.decodeUnknown(ContentRangeResult)(input)
        expect(decoded.content).toBe('extracted content')
        expect(decoded.from).toBe(10)
        expect(decoded.to).toBe(27)
      })
    )

    it.effect('accepts empty content', () =>
      Effect.gen(function* () {
        const input = { content: '', from: 5, to: 5 }
        const decoded = yield* Schema.decodeUnknown(ContentRangeResult)(input)
        expect(decoded.content).toBe('')
      })
    )
  })
})

/**
 * Editor Schemas
 *
 * Effect.Schema definitions for editor identity, selection, and metadata.
 * These are the core types consumed by EditorOperations service.
 *
 * @module editor-ai/schemas/editor
 */

import { Schema } from 'effect'
import { AIKnowledge } from '../decorators'

// -----------------------------------------------------------------------------
// EditorId - Branded String
// -----------------------------------------------------------------------------

/**
 * Unique identifier for editor instances.
 * Format: "editor-{panelId}" or custom string.
 */
export const EditorId = AIKnowledge({
  category: 'editor',
  description: 'Branded ID for editor instances. Used to target specific editors.',
  examples: ['editor-panel-123', 'main-editor', 'drawer-editor'],
})(Schema.String.pipe(Schema.brand('EditorId')))

export type EditorId = typeof EditorId.Type

// -----------------------------------------------------------------------------
// Selection - Text Selection Range
// -----------------------------------------------------------------------------

/**
 * Represents a text selection range in the document.
 * Maps to TipTap/ProseMirror selection model.
 */
export const Selection = AIKnowledge({
  category: 'editor',
  description: 'Text selection range with from/to positions and empty flag.',
})(
  Schema.Struct({
    /** Start position (0-indexed character offset) */
    from: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
    /** End position (0-indexed character offset) */
    to: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
    /** True if selection is collapsed (cursor, no range) */
    empty: Schema.Boolean,
  })
)

export type Selection = typeof Selection.Type

// -----------------------------------------------------------------------------
// EditorMetadata - Document Context
// -----------------------------------------------------------------------------

export type Selection = typeof Selection.Type

// -----------------------------------------------------------------------------
// EditorMetadata - Document Context
// -----------------------------------------------------------------------------

/**
 * Metadata about an editor instance and its document.
 * Useful for AI context gathering.
 */
export const EditorMetadata = AIKnowledge({
  category: 'editor',
  description: 'Editor instance metadata including document info for AI context.',
})(
  Schema.Struct({
    /** Editor instance ID */
    id: EditorId,
    /** Document title (from first heading or filename) */
    title: Schema.NullOr(Schema.String),
    /** Y-Sweet or collaboration document ID */
    documentId: Schema.NullOr(Schema.String),
    /** Total word count */
    wordCount: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
    /** Character count */
    charCount: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
    /** Last modification timestamp */
    lastModified: Schema.DateFromSelf,
    /** Whether editor has unsaved changes */
    isDirty: Schema.Boolean,
  })
)

export type EditorMetadata = typeof EditorMetadata.Type

// -----------------------------------------------------------------------------
// StreamingState - Insertion Stream Status
// -----------------------------------------------------------------------------

/**
 * Status of an active streaming insertion session.
 */
export const StreamingState = Schema.Struct({
  /** Whether streaming is active */
  isStreaming: Schema.Boolean,
  /** Total characters inserted so far */
  charsInserted: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
  /** Number of chunks received */
  chunksReceived: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
  /** Start position of insertion */
  startPosition: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
  /** Current end position */
  currentPosition: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
})

export type StreamingState = typeof StreamingState.Type

// -----------------------------------------------------------------------------
// InsertionResult - Stream Completion
// -----------------------------------------------------------------------------

export type StreamingState = typeof StreamingState.Type

// -----------------------------------------------------------------------------
// InsertionResult - Stream Completion
// -----------------------------------------------------------------------------

/**
 * Result returned when a streaming insertion completes.
 */
export const InsertionResult = Schema.Struct({
  /** Total characters inserted */
  totalChars: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
  /** Total chunks processed */
  chunks: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
  /** Duration in milliseconds */
  durationMs: Schema.Number.pipe(Schema.nonNegative()),
  /** Final cursor position */
  finalPosition: Schema.Number.pipe(Schema.int(), Schema.nonNegative()),
})

export type InsertionResult = typeof InsertionResult.Type

/**
 * Error Schemas
 *
 * Tagged error types for EditorAI operations.
 * Uses Schema.TaggedError for Effect error channel.
 *
 * @module editor-ai/schemas/errors
 */

import { Schema } from 'effect'
import type { EditorId } from './editor'

// -----------------------------------------------------------------------------
// Editor Errors
// -----------------------------------------------------------------------------

/**
 * Editor with given ID was not found in registry.
 */
export class EditorNotFoundError extends Schema.TaggedError<EditorNotFoundError>()(
  'EditorNotFoundError',
  {
    editorId: Schema.String,
    message: Schema.String,
  }
) {}

/**
 * Factory for EditorNotFoundError.
 */
export const makeEditorNotFoundError = (editorId: EditorId): EditorNotFoundError =>
  new EditorNotFoundError({
    editorId: editorId as string,
    message: `Editor not found: ${editorId}`,
  })

/**
 * No editor is currently focused.
 */
export class NoEditorFocusedError extends Schema.TaggedError<NoEditorFocusedError>()(
  'NoEditorFocusedError',
  {
    message: Schema.String,
  }
) {}

/**
 * Factory for NoEditorFocusedError.
 */
export const makeNoEditorFocusedError = (): NoEditorFocusedError =>
  new NoEditorFocusedError({
    message: 'No editor is currently focused',
  })

/**
 * Editor operation failed.
 */
export class EditorOperationError extends Schema.TaggedError<EditorOperationError>()(
  'EditorOperationError',
  {
    operation: Schema.String,
    editorId: Schema.String,
    message: Schema.String,
    cause: Schema.optional(Schema.Unknown),
  }
) {}

/**
 * Factory for EditorOperationError.
 */
export const makeEditorOperationError = (
  operation: string,
  editorId: EditorId,
  message: string,
  cause?: unknown
): EditorOperationError =>
  new EditorOperationError({
    operation,
    editorId: editorId as string,
    message,
    cause,
  })

/**
 * Streaming insertion was aborted.
 */
export class StreamAbortedError extends Schema.TaggedError<StreamAbortedError>()(
  'StreamAbortedError',
  {
    editorId: Schema.String,
    chunksProcessed: Schema.Number,
    message: Schema.String,
  }
) {}

/**
 * Factory for StreamAbortedError.
 */
export const makeStreamAbortedError = (
  editorId: EditorId,
  chunksProcessed: number
): StreamAbortedError =>
  new StreamAbortedError({
    editorId: editorId as string,
    chunksProcessed,
    message: `Stream aborted after ${chunksProcessed} chunks`,
  })

/**
 * AI stream processing error.
 */
export class AIStreamError extends Schema.TaggedError<AIStreamError>()(
  'AIStreamError',
  {
    message: Schema.String,
    cause: Schema.optional(Schema.Unknown),
  }
) {}

/**
 * Factory for AIStreamError.
 */
export const makeAIStreamError = (error: unknown): AIStreamError =>
  new AIStreamError({
    message: error instanceof Error ? error.message : 'AI stream error',
    cause: error,
  })

// -----------------------------------------------------------------------------
// Union Types
// -----------------------------------------------------------------------------

/**
 * All editor-related errors.
 */
export type EditorError =
  | EditorNotFoundError
  | NoEditorFocusedError
  | EditorOperationError
  | StreamAbortedError
  | AIStreamError

/**
 * Knowledge Pipeline Schemas
 *
 * Effect.Schema definitions for AI codebase knowledge extraction.
 * Used by decorators, extraction scripts, and KnowledgeService.
 */

import { Schema } from 'effect'

// -----------------------------------------------------------------------------
// Schema Information
// -----------------------------------------------------------------------------

/**
 * Information about an extracted Schema definition.
 * Populated by @AIKnowledge decorator during build-time extraction.
 */
export const SchemaInfo = Schema.Struct({
  /** Schema variable name (e.g., "EditorId", "Selection") */
  name: Schema.String,

  /** Source file path relative to project root */
  file: Schema.String,

  /** TypeScript type signature */
  typeSignature: Schema.String,

  /** Category for grouping (e.g., "editor", "cursor", "block") */
  category: Schema.String,

  /** Human-readable description */
  description: Schema.String,

  /** Optional JSDoc comment from source */
  jsdoc: Schema.optional(Schema.String),

  /** Example usages */
  examples: Schema.optional(Schema.Array(Schema.String)),
})
export type SchemaInfo = typeof SchemaInfo.Type

// -----------------------------------------------------------------------------
// Service Information
// -----------------------------------------------------------------------------

/**
 * Method signature information for services.
 */
export const ServiceMethod = Schema.Struct({
  /** Method name */
  name: Schema.String,

  /** Full TypeScript signature */
  signature: Schema.String,

  /** Optional description */
  description: Schema.optional(Schema.String),
})
export type ServiceMethod = typeof ServiceMethod.Type

/**
 * Information about an extracted Effect.Service definition.
 * Populated by @AIService decorator during build-time extraction.
 */
export const ServiceInfo = Schema.Struct({
  /** Service class name (e.g., "EditorOperations", "EditorRegistry") */
  name: Schema.String,

  /** Source file path relative to project root */
  file: Schema.String,

  /** Context.Tag identifier (e.g., "tmnl/EditorOperations") */
  tag: Schema.String,

  /** Service description */
  description: Schema.String,

  /** Capabilities this service provides */
  capabilities: Schema.Array(Schema.String),

/** Service description */
  description: Schema.String,

  /** Capabilities this service provides */
  capabilities: Schema.Array(Schema.String),

  /** Public method signatures */
  methods: Schema.Array(ServiceMethod),

  /** Optional JSDoc comment from source */
  jsdoc: Schema.optional(Schema.String),
})
export type ServiceInfo = typeof ServiceInfo.Type

// -----------------------------------------------------------------------------
// Pattern Information
// -----------------------------------------------------------------------------

/**
 * Pattern category discriminator.
 */
export const PatternCategory = Schema.Literal(
  'effect',
  'react',
  'atom',
  'service',
  'schema',
  'animation',
  'layer'
)
export type PatternCategory = typeof PatternCategory.Type

/**
 * Information about a code pattern.
 * Can come from @AIPattern decorators or EDIN markdown files.
 */
export const PatternInfo = Schema.Struct({
  /** Pattern name (e.g., "Atom-as-State", "XState Hybrid") */
  name: Schema.String,

  /** Pattern category */
  category: PatternCategory,

  /** When to use this pattern */
  description: Schema.String,

  /** Example code snippet */
  example: Schema.String,

  /** Source file or EDIN document */
  source: Schema.String,

  /** Anti-patterns to avoid */
  antiPatterns: Schema.optional(Schema.Array(Schema.String)),
})
export type PatternInfo = typeof PatternInfo.Type

// -----------------------------------------------------------------------------
// Codebase Knowledge (Aggregate)
// -----------------------------------------------------------------------------

/**
 * Complete codebase knowledge for AI context injection.
 * Loaded by KnowledgeService from .ai-context/ artifacts.
