// -----------------------------------------------------------------------------

/**
 * Registry for tracking editor instances and focus state.
 */
export interface EditorRegistryShape {
  // ---------------------------------------------------------------------------
  // Registration
  // ---------------------------------------------------------------------------

  /**
   * Register an editor with the registry.
   * Called by withEditorAI HOC on mount.
   */
  readonly register: (
    id: EditorId,
    operations: EditorOperationsShape
  ) => Effect.Effect<void>

  /**
   * Unregister an editor from the registry.
   * Called by withEditorAI HOC on unmount.
   */
  readonly unregister: (id: EditorId) => Effect.Effect<void>

  // ---------------------------------------------------------------------------
  // Discovery
  // ---------------------------------------------------------------------------

  /**
   * Get editor operations by ID.
   * Fails with EditorNotFoundError if not registered.
   */
  readonly getEditor: (
    id: EditorId
  ) => Effect.Effect<EditorOperationsShape, EditorNotFoundError>

  /**
   * Get all registered editor IDs.
   */
  readonly getAllEditors: Effect.Effect<readonly EditorId[]>

  /**
   * Get editor count.
   */
  readonly getEditorCount: Effect.Effect<number>

  /**
   * Check if an editor is registered.
   */
  readonly hasEditor: (id: EditorId) => Effect.Effect<boolean>

  // ---------------------------------------------------------------------------
  // Focus Management
  // ---------------------------------------------------------------------------

  /**
   * Get currently focused editor ID.
   * Returns None if no editor is focused.
   */
  readonly getFocusedEditor: Effect.Effect<Option.Option<EditorId>>

/**
   * Get currently focused editor ID.
   * Returns None if no editor is focused.
   */
  readonly getFocusedEditor: Effect.Effect<Option.Option<EditorId>>

  /**
   * Set the focused editor.
   * Pass None to clear focus.
   */
  readonly setFocusedEditor: (
    id: Option.Option<EditorId>
  ) => Effect.Effect<void>

  /**
   * Get focused editor operations.
   * Fails if no editor is focused or focused editor not found.
   */
  readonly getFocusedOperations: Effect.Effect<
    EditorOperationsShape,
    EditorNotFoundError
  >
}

// -----------------------------------------------------------------------------
// EditorRegistry Service Tag
// -----------------------------------------------------------------------------

@AIService({
  description: 'Registry for tracking editor instances and focus state',
  capabilities: [
    'editor registration/unregistration',
    'editor discovery by ID',
    'focus state management',
    'list all editors',
  ],
})
export class EditorRegistry extends Context.Tag('tmnl/EditorRegistry')<
  EditorRegistry,
  EditorRegistryShape
>() {}

// -----------------------------------------------------------------------------
// Live Implementation
// -----------------------------------------------------------------------------

/**
 * Create EditorRegistry.Live layer.
 * Uses Effect.Do for better type inference.
 */
export const EditorRegistryLive: Layer.Layer<EditorRegistry> = Layer.effect(
  EditorRegistry,
  Effect.Do.pipe(
    Effect.bind('editorsRef', () =>
      Ref.make<HashMap.HashMap<EditorId, EditorOperationsShape>>(HashMap.empty())
    ),
    Effect.bind('focusedRef', () =>
      Ref.make<Option.Option<EditorId>>(Option.none())
    ),
    Effect.map(({ editorsRef, focusedRef }) =>
      EditorRegistry.of({
        // -----------------------------------------------------------------------
        // Registration
        // -----------------------------------------------------------------------

        register: (id, operations) =>
          Ref.update(editorsRef, HashMap.set(id, operations)).pipe(
            Effect.tap(() =>
              Effect.logDebug(`EditorRegistry: registered ${id}`)
            )
          ),

register: (id, operations) =>
          Ref.update(editorsRef, HashMap.set(id, operations)).pipe(
            Effect.tap(() =>
              Effect.logDebug(`EditorRegistry: registered ${id}`)
            )
          ),

        unregister: (id) =>
          Ref.update(editorsRef, HashMap.remove(id)).pipe(
            Effect.flatMap(() => Ref.get(focusedRef)),
            Effect.flatMap((focused) =>
              Option.isSome(focused) && focused.value === id
                ? Ref.set(focusedRef, Option.none())
                : Effect.void
            ),
            Effect.tap(() =>
              Effect.logDebug(`EditorRegistry: unregistered ${id}`)
            )
          ),

        // -----------------------------------------------------------------------
        // Discovery
        // -----------------------------------------------------------------------

        getEditor: (id) =>
          Ref.get(editorsRef).pipe(
            Effect.flatMap((editors) => {
              const maybeEditor = HashMap.get(editors, id)
              return Option.isSome(maybeEditor)
                ? Effect.succeed(maybeEditor.value)
                : Effect.fail(makeEditorNotFoundError(id))
            })
          ),

        getAllEditors: Ref.get(editorsRef).pipe(
          Effect.map((editors) => Array.from(HashMap.keys(editors)))
        ),

        getEditorCount: Ref.get(editorsRef).pipe(Effect.map(HashMap.size)),

        hasEditor: (id) =>
          Ref.get(editorsRef).pipe(Effect.map((e) => HashMap.has(e, id))),

        // -----------------------------------------------------------------------
        // Focus Management
        // -----------------------------------------------------------------------

        getFocusedEditor: Ref.get(focusedRef),

        setFocusedEditor: (id) =>
          Ref.set(focusedRef, id).pipe(
            Effect.tap(() =>
              Effect.logDebug(
                `EditorRegistry: focus set to ${Option.isSome(id) ? id.value : 'none'}`
              )
            )
          ),

getFocusedOperations: Ref.get(focusedRef).pipe(
          Effect.flatMap((focusedId) =>
            Option.isNone(focusedId)
              ? Effect.fail(makeEditorNotFoundError('(no editor focused)' as EditorId))
              : Ref.get(editorsRef).pipe(
                  Effect.flatMap((editors) => {
                    const maybeEditor = HashMap.get(editors, focusedId.value)
                    return Option.isSome(maybeEditor)
                      ? Effect.succeed(maybeEditor.value)
                      : Effect.fail(makeEditorNotFoundError(focusedId.value))
                  })
                )
          )
        ),
      })
    )
  )
)

/**
 * KnowledgeService
 *
 * Effect.Service for accessing extracted codebase knowledge at runtime.
 * Loads .ai-context/ artifacts generated by scripts/extract-ai-context.ts.
 *
 * Uses Effect.Do and Effect.flatMap patterns for proper TypeScript inference
 * (avoiding Effect.gen yield* which causes downlevelIteration issues).
 */

import { Context, Effect, Layer, Ref, Option } from 'effect'
import { Schema, ParseResult } from 'effect'
import type {
  CodebaseKnowledge,
  SchemaInfo,
  ServiceInfo,
  PatternInfo,
  PatternCategory,
} from '../schemas/knowledge'
import {
  CodebaseKnowledge as CodebaseKnowledgeSchema,
  SchemaInfo as SchemaInfoSchema,
  ServiceInfo as ServiceInfoSchema,
  PatternInfo as PatternInfoSchema,
} from '../schemas/knowledge'

// -----------------------------------------------------------------------------
// Search Result Type
// -----------------------------------------------------------------------------

export interface SearchResult {
  kind: 'schema' | 'service' | 'pattern'
  name: string
  description: string
  relevance: number
  item: SchemaInfo | ServiceInfo | PatternInfo
}

// -----------------------------------------------------------------------------
// Service Interface
// -----------------------------------------------------------------------------

export interface KnowledgeServiceShape {
  /**
   * Load complete codebase knowledge from .ai-context/ artifacts.
   * Caches the result after first load.
   */
  readonly loadContext: Effect.Effect<CodebaseKnowledge>

  /**
   * Get schemas, optionally filtered by namespace (file path contains).
   */
  readonly getSchemas: (
    namespace?: string
  ) => Effect.Effect<readonly SchemaInfo[]>

  /**
   * Get services, optionally filtered by tag prefix.
   */
  readonly getServices: (
    tagPrefix?: string
  ) => Effect.Effect<readonly ServiceInfo[]>

  /**
   * Get patterns, optionally filtered by category.
   */
  readonly getPatterns: (
    category?: PatternCategory
  ) => Effect.Effect<readonly PatternInfo[]>

/**
   * Get patterns, optionally filtered by category.
   */
  readonly getPatterns: (
    category?: PatternCategory
  ) => Effect.Effect<readonly PatternInfo[]>

  /**
   * Search across all knowledge types.
   * Uses simple substring matching (future: semantic embeddings).
   */
  readonly searchSimilar: (
    query: string,
    limit?: number
  ) => Effect.Effect<readonly SearchResult[]>

  /**
   * Force reload from disk (for refresh_codebase_knowledge tool).
   */
  readonly reload: Effect.Effect<void>
}

// -----------------------------------------------------------------------------
// Service Tag
// -----------------------------------------------------------------------------

export class KnowledgeService extends Context.Tag('tmnl/KnowledgeService')<
  KnowledgeService,
  KnowledgeServiceShape
>() {}

// -----------------------------------------------------------------------------
// Helper Functions (Pure)
// -----------------------------------------------------------------------------

/**
 * Simple relevance scoring based on substring matching.
 */
const scoreRelevance = (text: string, query: string): number => {
  const lowerText = text.toLowerCase()
  const lowerQuery = query.toLowerCase()
  const words = lowerQuery.split(/\s+/)

  let score = 0

  // Exact match bonus
  if (lowerText.includes(lowerQuery)) {
    score += 10
  }

  // Word match scoring
  for (const word of words) {
    if (word.length < 2) continue
    if (lowerText.includes(word)) {
      score += 2
    }
  }

  return score
}

/**
 * Search schemas for matches.
 */
const searchSchemas = (
  schemas: readonly SchemaInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const schema of schemas) {
    const text = `${schema.name} ${schema.description} ${schema.category}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'schema',
        name: schema.name,
        description: schema.description,
        relevance,
        item: schema,
      })
    }
  }
  return results
}

/**
 * Search services for matches.
 */
const searchServices = (
  services: readonly ServiceInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const service of services) {
    const text = `${service.name} ${service.description} ${service.capabilities.join(' ')}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'service',
        name: service.name,
        description: service.description,
        relevance,
        item: service,
      })
    }
  }
  return results
}

/**
 * Search patterns for matches.
 */
const searchPatterns = (
  patterns: readonly PatternInfo[],
  query: string
): SearchResult[] => {
  const results: SearchResult[] = []
  for (const pattern of patterns) {
    const text = `${pattern.name} ${pattern.description} ${pattern.category}`
    const relevance = scoreRelevance(text, query)
    if (relevance > 0) {
      results.push({
        kind: 'pattern',
        name: pattern.name,
        description: pattern.description,
        relevance,
        item: pattern,
      })
    }
  }
  return results
}

// -----------------------------------------------------------------------------
// Live Implementation
// -----------------------------------------------------------------------------

/**
 * Create the Live layer for KnowledgeService.
 *
 * @param contextPath - Path to .ai-context/ directory (relative to CWD)
 */
export const makeKnowledgeServiceLive = (
  contextPath: string = '.ai-context'
): Layer.Layer<KnowledgeService> =>
  Layer.effect(
    KnowledgeService,
    Effect.Do.pipe(
      // Create cache ref for loaded knowledge
      Effect.bind('cacheRef', () =>
        Ref.make<Option.Option<CodebaseKnowledge>>(Option.none())
      ),
      Effect.map(({ cacheRef }) => {
        // Load a single JSON artifact file
        const loadArtifact = <A, I>(
          filename: string,
          schema: Schema.Schema<A, I>
        ): Effect.Effect<A, Error | ParseResult.ParseError> => {
          const fullPath = `${contextPath}/${filename}`

return Effect.tryPromise({
            try: async () => {
              const fs = await import('node:fs/promises')
              return fs.readFile(fullPath, 'utf-8')
            },
            catch: (error) =>
              new Error(
                `Failed to read ${fullPath}: ${error instanceof Error ? error.message : String(error)}`
              ),
          }).pipe(
            Effect.flatMap((content) =>
              Effect.try({
                try: () => JSON.parse(content) as unknown,
                catch: (error) =>
                  new Error(
                    `Failed to parse ${fullPath}: ${error instanceof Error ? error.message : String(error)}`
                  ),
              })
            ),
            Effect.flatMap((json) => Schema.decodeUnknown(schema)(json))
          )
        }

        // Load all artifacts into CodebaseKnowledge
        const loadAllArtifacts = (): Effect.Effect<CodebaseKnowledge> =>
          Effect.all({
            schemas: loadArtifact(
              'schemas.json',
              Schema.Array(SchemaInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly SchemaInfo[] => [])),

            services: loadArtifact(
              'services.json',
              Schema.Array(ServiceInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly ServiceInfo[] => [])),

            patterns: loadArtifact(
              'patterns.json',
              Schema.Array(PatternInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly PatternInfo[] => [])),

patterns: loadArtifact(
              'patterns.json',
              Schema.Array(PatternInfoSchema)
            ).pipe(Effect.orElseSucceed((): readonly PatternInfo[] => [])),

            versionInfo: loadArtifact(
              'version.json',
              Schema.Struct({
                extractedAt: Schema.String,
                version: Schema.String,
              })
            ).pipe(
              Effect.orElseSucceed(() => ({
                extractedAt: new Date().toISOString(),
                version: '0.0.0',
              }))
            ),
          }).pipe(
            Effect.map(
              ({ schemas, services, patterns, versionInfo }): CodebaseKnowledge => ({
                schemas: Array.from(schemas),
                services: Array.from(services),
                patterns: Array.from(patterns),
                extractedAt: new Date(versionInfo.extractedAt),
                version: versionInfo.version,
              })
            )
          )

        // Load context (with caching)
        const loadContext: Effect.Effect<CodebaseKnowledge> = Ref.get(
          cacheRef
        ).pipe(
          Effect.flatMap((cached) => {
            if (Option.isSome(cached)) {
              return Effect.succeed(cached.value)
            }
            return loadAllArtifacts().pipe(
              Effect.tap((knowledge) =>
                Ref.set(cacheRef, Option.some(knowledge))
              )
            )
          })
        )

        return KnowledgeService.of({
          loadContext,

          getSchemas: (namespace) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!namespace) {
                  return ctx.schemas
                }
                return ctx.schemas.filter((s) =>
                  s.file.toLowerCase().includes(namespace.toLowerCase())
                )
              })
            ),

          getServices: (tagPrefix) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!tagPrefix) {
                  return ctx.services
                }
                return ctx.services.filter((s) =>
                  s.tag.toLowerCase().startsWith(tagPrefix.toLowerCase())
                )
              })
            ),

getPatterns: (category) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                if (!category) {
                  return ctx.patterns
                }
                return ctx.patterns.filter((p) => p.category === category)
              })
            ),

          searchSimilar: (query, limit = 10) =>
            loadContext.pipe(
              Effect.map((ctx) => {
                const schemaResults = searchSchemas(ctx.schemas, query)
                const serviceResults = searchServices(ctx.services, query)
                const patternResults = searchPatterns(ctx.patterns, query)

                const allResults = [
                  ...schemaResults,
                  ...serviceResults,
                  ...patternResults,
                ]

                return allResults
                  .sort((a, b) => b.relevance - a.relevance)
                  .slice(0, limit)
              })
            ),

          reload: Ref.set(cacheRef, Option.none()).pipe(
            Effect.flatMap(() => loadContext),
            Effect.asVoid
          ),
        })
      })
    )
  )

// Default layer with standard path
export const KnowledgeServiceLive = makeKnowledgeServiceLive()

/**
 * ReconcilerService
 *
 * Effect.Service wrapper for the document reconciler.
 * Bridges AI-generated structured documents to ProseMirror editors.
 *
 * Features:
 * - One-shot document reconciliation
 * - Streaming document reconciliation (token batching)
 * - Document diffing and minimal mutations
 *
 * @module editor-ai/services/ReconcilerService
 */

import { Context, Effect, Layer, Ref } from 'effect'
import type { EditorView } from '@tiptap/pm/view'
import type {
  JSONDocument,
  JSONNode,
  ReconcileResult,
  StreamingConfig,
  StreamingStats,
  MergeResult,
  MergeStats,
} from '../reconciler'
import {
  mergeIntoEditor,
  mergeDocuments,
  createStreamingReconciler,
  processAIStream,
  pmNodeToJSON,
  decodeDocument,
} from '../reconciler'
import type { TransformOptions } from '../reconciler'
import { AIService } from '../decorators'

// =============================================================================
// Types
// =============================================================================

/**
 * Document reconciliation result with detailed stats.
 */
export interface ReconciliationResult {
  readonly success: boolean
  readonly stats: MergeStats
  readonly applied: boolean
  readonly durationMs: number
}

/**
 * Streaming reconciliation handle for controlled document streaming.
 */
export interface DocumentStreamHandle {
  /** Push a JSON token from the AI stream */
  readonly pushToken: (token: string) => Effect.Effect<void>

  /** Push a complete block (already parsed) */
  readonly pushBlock: (block: JSONNode) => Effect.Effect<void>

  /** Signal end of stream and flush remaining */
  readonly complete: Effect.Effect<ReconcileResult>

  /** Cancel processing */
  readonly cancel: Effect.Effect<void>

  /** Get current streaming stats */
  readonly getStats: Effect.Effect<StreamingStats>
}

// =============================================================================
// ReconcilerService Shape
// =============================================================================

/**
 * Service interface for document reconciliation.
 */
export interface ReconcilerServiceShape {
  // ---------------------------------------------------------------------------
  // One-shot Operations
  // ---------------------------------------------------------------------------

// =============================================================================
// ReconcilerService Shape
// =============================================================================

/**
 * Service interface for document reconciliation.
 */
export interface ReconcilerServiceShape {
  // ---------------------------------------------------------------------------
  // One-shot Operations
  // ---------------------------------------------------------------------------

  /**
   * Reconcile a complete JSONDocument into an editor.
   * Computes minimal diff and applies atomic transaction.
   */
  readonly reconcileDocument: (
    view: EditorView,
    document: JSONDocument,
    options?: TransformOptions
  ) => Effect.Effect<ReconciliationResult>

  /**
   * Compute merge operations without applying.
   * Useful for preview or validation.
   */
  readonly computeMerge: (
    view: EditorView,
    document: JSONDocument
  ) => Effect.Effect<MergeResult>

  /**
   * Validate a JSONDocument against the schema.
   */
  readonly validateDocument: (
    document: unknown
  ) => Effect.Effect<JSONDocument, Error>

  // ---------------------------------------------------------------------------
  // Streaming Operations
  // ---------------------------------------------------------------------------

  /**
   * Create a streaming document handle for controlled reconciliation.
   * Use when you need fine-grained control over streaming.
   */
  readonly createDocumentStream: (
    view: EditorView,
    config?: Partial<StreamingConfig>
  ) => Effect.Effect<DocumentStreamHandle>

  /**
   * Process an AI text stream through the reconciler.
   * Convenience method for AI SDK integration.
   */
  readonly processStream: (
    view: EditorView,
    textStream: AsyncIterable<string>,
    config?: Partial<StreamingConfig>
  ) => Effect.Effect<ReconcileResult>

  // ---------------------------------------------------------------------------
  // Utilities
  // ---------------------------------------------------------------------------

  /**
   * Convert current editor document to JSONDocument.
   * Useful for diffing or serialization.
   */
  readonly getDocumentJSON: (view: EditorView) => Effect.Effect<JSONDocument>

/**
   * Convert current editor document to JSONDocument.
   * Useful for diffing or serialization.
   */
  readonly getDocumentJSON: (view: EditorView) => Effect.Effect<JSONDocument>

  /**
   * Check if current document matches target document.
   * Returns true if no merge operations needed.
   */
  readonly isDocumentEqual: (
    view: EditorView,
    target: JSONDocument
  ) => Effect.Effect<boolean>
}

// =============================================================================
// ReconcilerService Tag
// =============================================================================

@AIService({
  description: 'Document reconciler for AI-generated structured content',
  capabilities: [
    'reconcile JSONDocument into ProseMirror',
    'compute minimal diff (LCS algorithm)',
    'stream document blocks with batching',
    'validate against Effect.Schema',
  ],
})
export class ReconcilerService extends Context.Tag('tmnl/ReconcilerService')<
  ReconcilerService,
  ReconcilerServiceShape
>() {}

// =============================================================================
// Live Implementation
// =============================================================================

/**
 * Create ReconcilerService.Live layer.
 */
export const ReconcilerServiceLive: Layer.Layer<ReconcilerService> = Layer.succeed(
  ReconcilerService,
  ReconcilerService.of({
    // -------------------------------------------------------------------------
    // One-shot Operations
    // -------------------------------------------------------------------------

    reconcileDocument: (view, document, options = {}) =>
      Effect.gen(function* () {
        const startTime = Date.now()

        // Apply reconciliation
        const result = mergeIntoEditor(view, document, options)

        const durationMs = Date.now() - startTime

// Apply reconciliation
        const result = mergeIntoEditor(view, document, options)

        const durationMs = Date.now() - startTime

        return {
          success: true,
          stats: result.stats,
          applied: result.applied,
          durationMs,
        }
      }).pipe(
        Effect.withSpan('ReconcilerService.reconcileDocument', {
          attributes: {
            blockCount: document.content?.length ?? 0,
          },
        }),
        Effect.catchAll((error) =>
          Effect.succeed({
            success: false,
            stats: { inserted: 0, deleted: 0, updated: 0, moved: 0, unchanged: 0 },
            applied: false,
            durationMs: 0,
          } satisfies ReconciliationResult)
        )
      ),

    computeMerge: (view, document) =>
      Effect.sync(() => {
        const currentDoc = pmNodeToJSON(view.state.doc) as JSONDocument
        return mergeDocuments(currentDoc, document)
      }).pipe(Effect.withSpan('ReconcilerService.computeMerge')),

    validateDocument: (document) =>
      decodeDocument(document).pipe(
        Effect.mapError((parseError) =>
          new Error(`Invalid document: ${parseError.message}`)
        ),
        Effect.withSpan('ReconcilerService.validateDocument')
      ),

    // -------------------------------------------------------------------------
    // Streaming Operations
    // -------------------------------------------------------------------------

    createDocumentStream: (view, config = {}) =>
      Ref.make(false).pipe(
        Effect.map((cancelledRef) => {
          const handle = createStreamingReconciler(view, config)

          const streamHandle: DocumentStreamHandle = {
            pushToken: (token) =>
              Ref.get(cancelledRef).pipe(
                Effect.flatMap((cancelled) => {
                  if (!cancelled) {
                    handle.pushToken(token)
                  }
                  return Effect.void
                })
              ),

pushBlock: (block) =>
              Ref.get(cancelledRef).pipe(
                Effect.flatMap((cancelled) => {
                  if (!cancelled) {
                    handle.pushToken(JSON.stringify(block))
                  }
                  return Effect.void
                })
              ),

            complete: Effect.promise(() => handle.complete()),

            cancel: Ref.set(cancelledRef, true).pipe(
              Effect.tap(() => Effect.sync(() => handle.cancel()))
            ),

            getStats: Effect.sync(() => handle.getStats()),
          }

          return streamHandle
        }),
        Effect.withSpan('ReconcilerService.createDocumentStream')
      ),

    processStream: (view, textStream, config = {}) =>
      processAIStream(view, textStream, config).pipe(
        Effect.withSpan('ReconcilerService.processStream')
      ),

    // -------------------------------------------------------------------------
    // Utilities
    // -------------------------------------------------------------------------

    getDocumentJSON: (view) =>
      Effect.sync(() => pmNodeToJSON(view.state.doc) as JSONDocument).pipe(
        Effect.withSpan('ReconcilerService.getDocumentJSON')
      ),

    isDocumentEqual: (view, target) =>
      Effect.gen(function* () {
        const currentDoc = pmNodeToJSON(view.state.doc) as JSONDocument
        const mergeResult = mergeDocuments(currentDoc, target)

        // Equal if no operations needed (all NOOPs)
        return mergeResult.ops.every((op) => op.type === 'NOOP')
      }).pipe(Effect.withSpan('ReconcilerService.isDocumentEqual')),
  })
)

const createMockContext = (
  editors: Map<EditorId, EditorOperationsShape> = new Map(),
  focusedId: EditorId | null = null
): EditorAIContextValue => ({
  getFocusedEditor: () =>
    focusedId ? editors.get(focusedId) ?? null : null,
  getEditor: (id: EditorId) => editors.get(id) ?? null,
  getAllEditorIds: () => Array.from(editors.keys()),
  getFocusedEditorId: () => focusedId,
  setFocusedEditor: vi.fn(),
  registerEditor: vi.fn(),
  unregisterEditor: vi.fn(),
})

