import { memo, useCallback, type MouseEvent } from 'react'
import {
  Folder,
  File,
  FileText,
  FileCode,
  FileImage,
  FileVideo,
  FileAudio,
  FileArchive,
  FileCog,
  FileJson,
  Link2,
} from 'lucide-react'

import { DARK_SIDE } from '../../tokens'
import type { FileEntry } from '../../schemas'

// =============================================================================
// Types
// =============================================================================

export interface IconTileProps {
  /** File entry */
  entry: FileEntry
  /** Is selected */
  isSelected?: boolean
  /** Is focused */
  isFocused?: boolean
  /** Icon size */
  iconSize?: 'sm' | 'md' | 'lg'
  /** Called on click */
  onClick?: (e: MouseEvent) => void
  /** Called on double-click */
  onDoubleClick?: () => void
  /** Additional CSS class */
  className?: string
}

// =============================================================================
// Icon Size Mapping
// =============================================================================

const ICON_SIZES = {
  sm: { icon: 32, tile: 80 },
  md: { icon: 48, tile: 100 },
  lg: { icon: 64, tile: 120 },
} as const

// =============================================================================
// File Type to Icon Mapping
// =============================================================================

function getFileIcon(entry: FileEntry, size: number) {
  if (entry.type === 'directory') {
    return <Folder size={size} color={DARK_SIDE.colors.fileType.directory} />
  }

  if (entry.type === 'symlink') {
    return <Link2 size={size} color={DARK_SIDE.colors.fileType.symlink} />
  }

  // Map by extension
  const ext = entry.extension?.toLowerCase()

// Archives
    case 'zip':
    case 'tar':
    case 'gz':
    case 'rar':
    case '7z':
    case 'bz2':
      return <FileArchive size={size} color={DARK_SIDE.colors.accent.amber} />

    // Config files
    case 'yml':
    case 'yaml':
    case 'toml':
    case 'ini':
    case 'env':
    case 'conf':
    case 'cfg':
      return <FileCog size={size} color={DARK_SIDE.colors.text.tertiary} />

    default:
      return <File size={size} color={DARK_SIDE.colors.fileType.file} />
  }
}

// =============================================================================
// Component
// =============================================================================

export const IconTile = memo(function IconTile({
  entry,
  isSelected = false,
  isFocused = false,
  iconSize = 'md',
  onClick,
  onDoubleClick,
  className = '',
}: IconTileProps) {
  const sizes = ICON_SIZES[iconSize]

  const handleClick = useCallback(
    (e: MouseEvent) => {
      onClick?.(e)
    },
    [onClick]
  )

  const handleDoubleClick = useCallback(() => {
    onDoubleClick?.()
  }, [onDoubleClick])

  // Determine colors based on state
  const bgColor = isSelected
    ? DARK_SIDE.colors.surfaceSelected
    : 'transparent'
  const borderColor = isFocused
    ? DARK_SIDE.colors.accent.green
    : isSelected
      ? DARK_SIDE.colors.accent.greenMuted
      : 'transparent'
  const textColor = entry.hidden
    ? DARK_SIDE.colors.text.tertiary
    : DARK_SIDE.colors.text.primary

return (
    <div
      className={`icon-tile ${className}`}
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        width: sizes.tile,
        height: sizes.tile + 24, // Extra space for text
        padding: DARK_SIDE.spacing['2'],
        background: bgColor,
        border: `1px solid ${borderColor}`,
        cursor: 'pointer',
        transition: `all ${DARK_SIDE.animation.duration.fast} ${DARK_SIDE.animation.easing.easeOut}`,
        boxShadow: isFocused ? DARK_SIDE.shadows.glow.green : 'none',
      }}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
      onMouseEnter={(e) => {
        if (!isSelected) {
          e.currentTarget.style.background = DARK_SIDE.colors.surfaceHover
          e.currentTarget.style.borderColor = DARK_SIDE.colors.border.default
        }
      }}
      onMouseLeave={(e) => {
        if (!isSelected) {
          e.currentTarget.style.background = 'transparent'
          e.currentTarget.style.borderColor = 'transparent'
        }
      }}
      data-file-id={entry.id}
      data-file-type={entry.type}
    >
      {/* Icon */}
      <div
        style={{
          marginBottom: DARK_SIDE.spacing['2'],
          opacity: entry.hidden ? 0.5 : 1,
        }}
      >
        {getFileIcon(entry, sizes.icon)}
      </div>

      {/* Name */}
      <div
        style={{
          width: '100%',
          textAlign: 'center',
          fontSize: DARK_SIDE.typography.size.xs,
          fontFamily: DARK_SIDE.typography.family.mono,
          color: textColor,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
          lineHeight: DARK_SIDE.typography.lineHeight.tight,
        }}
        title={entry.name}
      >
        {entry.name}
      </div>
    </div>
  )
})

/**
 * IconView Component
 *
 * Level 3: Grid of file/folder icons.
 *
 * @module file-browser/components/Content
 */

import { memo, useCallback, useRef, useEffect, type KeyboardEvent } from 'react'

import { useFileBrowserContext } from '../FileBrowser/context'
import { DARK_SIDE } from '../../tokens'
import { IconTile } from './IconTile'

// =============================================================================
// Types
// =============================================================================

export type IconSize = 'sm' | 'md' | 'lg'

export interface IconViewProps {
  /** Icon size */
  iconSize?: IconSize
  /** Gap between icons */
  gap?: number
  /** Additional CSS class */
  className?: string
}

// =============================================================================
// Component
// =============================================================================

const IconViewRoot = memo(function IconView({
  iconSize = 'md',
  gap = 8,
  className = '',
}: IconViewProps) {
  const {
    entries,
    selectedFiles,
    focusedFile,
    isLoading,
    select,
    toggleSelect,
    rangeSelect,
    navigate,
  } = useFileBrowserContext()

  const containerRef = useRef<HTMLDivElement>(null)

  // Scroll focused item into view
  useEffect(() => {
    if (focusedFile && containerRef.current) {
      const focusedElement = containerRef.current.querySelector(
        `[data-file-id="${focusedFile}"]`
      )
      if (focusedElement) {
        focusedElement.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
      }
    }
  }, [focusedFile])

  // Handle keyboard navigation
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (entries.length === 0) return

      const currentIndex = focusedFile
        ? entries.findIndex((entry) => entry.id === focusedFile)
        : -1

      // Calculate columns based on container width
      const container = containerRef.current
      if (!container) return

if (nextIndex !== currentIndex && nextIndex >= 0) {
        select(entries[nextIndex].id)
      }
    },
    [entries, focusedFile, select, navigate, iconSize, gap]
  )

  // Handle tile click
  const handleTileClick = useCallback(
    (entryId: string, e: React.MouseEvent) => {
      if (e.shiftKey) {
        rangeSelect(entryId)
      } else if (e.ctrlKey || e.metaKey) {
        toggleSelect(entryId)
      } else {
        select(entryId)
      }
    },
    [select, toggleSelect, rangeSelect]
  )

  // Handle tile double-click
  const handleTileDoubleClick = useCallback(
    (entry: (typeof entries)[0]) => {
      if (entry.type === 'directory') {
        navigate(entry.path)
      }
    },
    [navigate]
  )

  // Loading state
  if (isLoading && entries.length === 0) {
    return (
      <div
        className={`icon-view icon-view--loading ${className}`}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flex: 1,
          color: DARK_SIDE.colors.text.muted,
          fontFamily: DARK_SIDE.typography.family.mono,
          fontSize: DARK_SIDE.typography.size.sm,
        }}
      >
        <span style={{ color: DARK_SIDE.colors.accent.green }}>SCANNING...</span>
      </div>
    )
  }

  // Empty state
  if (entries.length === 0) {
    return (
      <div
        className={`icon-view icon-view--empty ${className}`}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flex: 1,
          color: DARK_SIDE.colors.text.muted,
          fontFamily: DARK_SIDE.typography.family.mono,
          fontSize: DARK_SIDE.typography.size.sm,
        }}
      >
        DIRECTORY_EMPTY
      </div>
    )
  }

return (
    <div
      ref={containerRef}
      className={`icon-view ${className}`}
      style={{
        flex: 1,
        padding: DARK_SIDE.spacing['4'],
        overflowY: 'auto',
        overflowX: 'hidden',
        background: DARK_SIDE.colors.surface,
      }}
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="grid"
      aria-label="File grid"
    >
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: `${gap}px`,
        }}
      >
        {entries.map((entry) => (
          <IconTile
            key={entry.id}
            entry={entry}
            isSelected={selectedFiles.has(entry.id)}
            isFocused={focusedFile === entry.id}
            iconSize={iconSize}
            onClick={(e) => handleTileClick(entry.id, e)}
            onDoubleClick={() => handleTileDoubleClick(entry)}
          />
        ))}
      </div>

      {/* Scrollbar styles */}
      <style>{`
        .icon-view::-webkit-scrollbar {
          width: 6px;
        }
        .icon-view::-webkit-scrollbar-track {
          background: ${DARK_SIDE.colors.surfaceAlt};
        }
        .icon-view::-webkit-scrollbar-thumb {
          background: ${DARK_SIDE.colors.border.default};
        }
        .icon-view::-webkit-scrollbar-thumb:hover {
          background: ${DARK_SIDE.colors.accent.green};
          box-shadow: 0 0 5px ${DARK_SIDE.colors.accent.greenGlow};
        }
      `}</style>
    </div>
  )
})

// =============================================================================
// Compound Export
// =============================================================================

export const IconView = Object.assign(IconViewRoot, {
  Tile: IconTile,
})

/**
 * ListHeader Component
 *
 * Level 3: Column headers for list view with sorting.
 *
 * @module file-browser/components/Content
 */

import { memo, useCallback } from 'react'
import { ChevronUp, ChevronDown } from 'lucide-react'

import { useFileBrowserContext } from '../FileBrowser/context'
import { DARK_SIDE } from '../../tokens'
import type { SortOrder } from '../../schemas'

// =============================================================================
// Types
// =============================================================================

export interface ListHeaderProps {
  /** Additional CSS class */
  className?: string
}

type SortField = SortOrder['field']

interface ColumnDef {
  field: SortField
  label: string
  width: string
  align?: 'left' | 'right' | 'center'
}

// =============================================================================
// Column Definitions
// =============================================================================

const COLUMNS: readonly ColumnDef[] = [
  { field: 'name', label: 'NAME', width: '3fr', align: 'left' },
  { field: 'size', label: 'SIZE', width: '100px', align: 'right' },
  { field: 'type', label: 'TYPE', width: '80px', align: 'left' },
  { field: 'modifiedAt', label: 'MODIFIED', width: '140px', align: 'right' },
]

// =============================================================================
// Component
// =============================================================================

export const ListHeader = memo(function ListHeader({ className = '' }: ListHeaderProps) {
  const { sortOrder, setSortOrder } = useFileBrowserContext()

  const handleSort = useCallback(
    (field: SortField) => {
      setSortOrder({
        field,
        direction:
          sortOrder.field === field
            ? sortOrder.direction === 'asc'
              ? 'desc'
              : 'asc'
            : 'asc',
      })
    },
    [sortOrder, setSortOrder]
  )

