              textTransform: 'uppercase',
            }}
          >
            TAGS
          </label>
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: DARK_SIDE.spacing['1'],
              padding: DARK_SIDE.spacing['1'],
              borderBottom: `1px solid ${DARK_SIDE.colors.border.default}`,
              minHeight: '26px',
            }}
          >
            {(meta.tags || []).map((tag) => (
              <span
                key={tag}
                style={{
                  display: 'flex',
