                  onClick={() => handleRemoveTag(tag)}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.color = DARK_SIDE.colors.accent.red
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.color = 'inherit'
