    marginBottom: DARK_SIDE.spacing['1'],
    textTransform: 'uppercase',
    letterSpacing: DARK_SIDE.typography.letterSpacing.wide,
    transition: `color ${DARK_SIDE.animation.duration.fast} ${DARK_SIDE.animation.easing.easeOut}`,
  }

  return (
