  signature: Schema.NullOr(Schema.String),
  /** Confidence 0-1 */
  confidence: Schema.Number,
  /** Detected MIME type from magic bytes */
  detectedMimeType: Schema.NullOr(Schema.String),
  /** First N bytes as hex string */
