export interface FloatingPanelProps {
  /** Panel ID - must already be registered in stx */
  id: string
  /** Panel title for display */
  title: string
  /** Children to render inside panel */
  children: ReactNode
  /** Callback when close button clicked */
  onClose?: () => void
  /** Callback when dock/undock toggled */
  onToggleMode?: () => void
  /** Additional className for panel */
  className?: string
}

// =============================================================================
// Component
// =============================================================================

/**
 * A draggable, resizable floating panel with window chrome.
 *
 * IMPORTANT: Panel must be registered in stx BEFORE rendering.
 * This component is a pure consumer - it does NOT self-register.
 *
 * @example
 * ```tsx
 * // Register first, then render
 * useEffect(() => {
 *   registerPanel({ id: 'settings', title: 'Settings', ... })
 *   return () => unregisterPanel('settings')
 * }, [])
 *
 * // Only render when panel exists
 * const panel = getPanel('settings')
 * if (!panel) return null
 *
 * return (
 *   <FloatingPanelProvider>
 *     <FloatingPanel id="settings" title="Settings">
 *       <SettingsContent />
 *     </FloatingPanel>
 *   </FloatingPanelProvider>
 * )
 * ```
 */
export function FloatingPanel({
  id,
  title,
  onClose,
  onToggleMode,
  children,
  className = '',
}: FloatingPanelProps) {
  const context = useFloatingPanelContext()
  const stx = getFloatingStx()

  // Animation state for maximize/restore transition (Apple-style subtle)
  const [isAnimating, setIsAnimating] = useState(false)
  const [animationPhase, setAnimationPhase] = useState<'idle' | 'lift' | 'settle'>('idle')

// Subscribe to this panel's state from stx
  // NOTE: We select the full Map and extract panel to ensure safe initialization
  const panelsMap = useSelector(stx.data.panels, (p) => p)
  const panel = panelsMap?.get(id)

  // Get motion blur style from centralized drag orchestrator
  const blurStyle = useElementBlurStyle(id)

  // @dnd-kit draggable (transform only - drag state comes from stx)
  // Disable dragging when maximized
  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
  } = useDraggable({ id, disabled: panel?.isMaximized })

  // Panel must exist in stx - if not, don't render
  // Caller is responsible for registering before rendering
  if (!panel) {
    return null
  }

  // Don't render if panel is hidden
  if (panel.visibility === 'hidden') {
    return null
  }

  // Transform style from @dnd-kit (only when not maximized)
  const transformStyle = !panel.isMaximized && transform
    ? CSS.Transform.toString(transform)
    : undefined

  // Direction-aware motion blur from centralized drag orchestrator
  // Uses velocity tracking from @/lib/drag which is updated in FloatingPanelProvider.handleDragMove
  const motionBlur = panel.isDragging ? blurStyle.blurAmount : 0
  const motionStretch = panel.isDragging ? blurStyle.transform : undefined

  // Apple-style animation: subtle scale lift during transition
  const animationScale = animationPhase === 'lift' ? 0.98 : 1.0

  // Handle close
  const handleClose = () => {
    context.closePanel(id)
    onClose?.()
  }

  // Handle minimize
  const handleMinimize = () => {
    context.setVisibility(id, panel.visibility === 'minimized' ? 'visible' : 'minimized')
  }

// Handle minimize
  const handleMinimize = () => {
    context.setVisibility(id, panel.visibility === 'minimized' ? 'visible' : 'minimized')
  }

  // Handle dock/undock toggle
  const handleToggleMode = () => {
    context.toggleMode(id)
    onToggleMode?.()
  }

  // Handle maximize with animation (Apple-style: lift → expand → settle)
  const handleMaximize = () => {
    if (panel.isMaximized || isAnimating) return

    setIsAnimating(true)
    setAnimationPhase('lift')

    // Phase 1: Lift (subtle scale down, 80ms)
    setTimeout(() => {
      setAnimationPhase('settle')
      maximizePanel(id)

      // Phase 2: Settle (smooth expansion, 200ms)
      setTimeout(() => {
        setAnimationPhase('idle')
        setIsAnimating(false)
      }, 200)
    }, 80)
  }

  // Handle restore with animation (Apple-style: lift → contract → settle)
  const handleRestore = () => {
    if (!panel.isMaximized || isAnimating) return

    setIsAnimating(true)
    setAnimationPhase('lift')

    // Phase 1: Lift (subtle scale down, 80ms)
    setTimeout(() => {
      setAnimationPhase('settle')
      restorePanel(id)

      // Phase 2: Settle (smooth contraction, 200ms)
      setTimeout(() => {
        setAnimationPhase('idle')
        setIsAnimating(false)
      }, 200)
    }, 80)
  }

  // Handle double-click title bar to maximize
  const handleTitleDoubleClick = () => {
    if (panel.isMaximized) {
      handleRestore()
    } else {
      handleMaximize()
    }
  }

  // Handle click to bring to front
  const handlePanelClick = () => {
    context.bringToFront(id)
  }

// Handle click to bring to front
  const handlePanelClick = () => {
    context.bringToFront(id)
  }

  // Handle resize end
  const handleResizeEnd = (dimensions: Dimensions, position: Position) => {
    context.updateDimensions(id, dimensions)
    context.updatePosition(id, position)
  }

  // Apple-style: subtle shadow elevation during lift phase
  const liftShadow = animationPhase === 'lift'
    ? '0 12px 40px rgba(0, 0, 0, 0.6)'
    : panel.isDragging
      ? '0 8px 32px rgba(0, 0, 0, 0.7)'
      : '0 4px 24px rgba(0, 0, 0, 0.5)'

  return (
    <div
      ref={setNodeRef}
      className={`fixed ${panel.isMaximized ? '' : 'rounded'} ${className}`}
      style={{
        left: panel.position.x,
        top: panel.position.y,
        // EXPLICIT width + height — panel dimensions are authoritative, not content
        width: panel.dimensions.width,
        height: panel.dimensions.height,
        minWidth: panel.isMaximized ? undefined : (panel.constraints?.minWidth ?? 200),
        minHeight: panel.isMaximized ? undefined : (panel.constraints?.minHeight ?? 100),
        zIndex: panel.isMaximized ? 99999 : panel.zIndex,
        // Apple-style: combine drag transform with animation scale + motion stretch
        transform: [
          transformStyle,
          animationScale !== 1.0 ? `scale(${animationScale})` : '',
          motionStretch,
        ].filter(Boolean).join(' ') || undefined,
        backgroundColor: COLORS.neutral[950],
        opacity: 1,
        border: panel.isMaximized ? 'none' : `1px solid ${COLORS.neutral[800]}`,
        // Apple-style shadow: elevated during lift, normal otherwise
        boxShadow: panel.isMaximized ?

'none' : `1px solid ${COLORS.neutral[800]}`,
        // Apple-style shadow: elevated during lift, normal otherwise
        boxShadow: panel.isMaximized ? 'none' : liftShadow,
        // Subtle motion blur during fast drag (no harsh filters)
        filter: motionBlur > 0 ? `blur(${motionBlur}px)` : undefined,
        // Apple-style smooth transitions
        // NOTE: No transform transition when idle — prevents elastic snap-back on drag end
        transition: isAnimating
          ? 'left 0.25s cubic-bezier(0.4, 0, 0.2, 1), top 0.25s cubic-bezier(0.4, 0, 0.2, 1), width 0.25s cubic-bezier(0.4, 0, 0.2, 1), height 0.25s cubic-bezier(0.4, 0, 0.2, 1), transform 0.08s ease-out, box-shadow 0.15s ease-out'
          : panel.isDragging
            ?

'none'
            : 'box-shadow 0.2s ease-out',
        // Flex column layout for proper height distribution
        display: 'flex',
        flexDirection: 'column',
      }}
      onClick={handlePanelClick}
      {...attributes}
    >
      {/* Title Bar - fixed height, no shrink */}
      <div
        className="flex items-center justify-between px-2 py-1.5 border-b select-none"
        style={{
          backgroundColor: COLORS.neutral[900],
          borderColor: COLORS.neutral[800],
          flexShrink: 0,
        }}
        onDoubleClick={handleTitleDoubleClick}
      >
        {/* Drag Handle + Title */}
        <div
          ref={setActivatorNodeRef}
          className="flex items-center gap-2 cursor-grab active:cursor-grabbing flex-1"
          {...listeners}
        >
          <span style={{ color: COLORS.neutral[600] }}>
            <GripIcon />
          </span>
          <span
            className="font-mono truncate"
            style={{
              fontSize: 'var(--tmnl-text-xs, 12px)',
              color: COLORS.neutral[400],
            }}
          >
            {title}
          </span>
        </div>

        {/* Window Controls */}
        <div className="flex items-center gap-1">
          {/* Dock/Undock toggle */}
          <button
            onClick={(e) => {
              e.stopPropagation()
              handleToggleMode()
            }}
            className="p-1 rounded transition-colors hover:bg-white/10"
            style={{ color: COLORS.neutral[500] }}
            aria-label={panel.mode === 'floating' ? 'Dock panel' : 'Undock panel'}
            title={panel.mode === 'floating' ? 'Dock panel' : 'Float panel'}
          >
            {panel.mode === 'floating' ? <DockIcon /> : <UndockIcon />}
          </button>

{/* Maximize/Restore toggle */}
          <button
            onClick={(e) => {
              e.stopPropagation()
              if (panel.isMaximized) {
                handleRestore()
              } else {
                handleMaximize()
              }
            }}
            className="p-1 rounded transition-colors hover:bg-white/10"
            style={{ color: COLORS.neutral[500] }}
            aria-label={panel.isMaximized ? 'Restore panel' : 'Maximize panel'}
            title={panel.isMaximized ? 'Restore' : 'Maximize'}
          >
            {panel.isMaximized ? <RestoreIcon /> : <MaximizeIcon />}
          </button>

          {panel.minimizable && (
            <button
              onClick={(e) => {
                e.stopPropagation()
                handleMinimize()
              }}
              className="p-1 rounded transition-colors hover:bg-white/10"
              style={{ color: COLORS.neutral[500] }}
              aria-label="Minimize"
            >
              <MinimizeIcon />
            </button>
          )}

          {panel.closable && (
            <button
              onClick={(e) => {
                e.stopPropagation()
                handleClose()
              }}
              className="p-1 rounded transition-colors hover:bg-red-500/20 hover:text-red-400"
              style={{ color: COLORS.neutral[500] }}
              aria-label="Close"
            >
              <CloseIcon />
            </button>
          )}
        </div>
      </div>

{/* Content (collapsed when minimized) - fills remaining space */}
      {panel.visibility !== 'minimized' && (
        <FloatingDimensionProvider
          panelId={id}
          dimensions={panel.dimensions}
          isResizing={panel.isResizing}
        >
          {/* Content container with relative positioning for drawer slot */}
          <div
            className="overflow-auto relative"
            style={{
              // flex: 1 fills remaining height, min-height: 0 allows shrinking below content size
              flex: 1,
              minHeight: 0,
              minWidth: 0,
            }}
          >
            {children}
            {/* Per-panel drawer slot - renders drawer overlays scoped to this panel */}
            <PanelSlot panelId={id} />
          </div>
        </FloatingDimensionProvider>
      )}

      {/* Resize Handles - wrapped in absolute container for proper positioning */}
      {panel.resizable && panel.visibility !== 'minimized' && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            pointerEvents: 'none',
          }}
        >
          <ResizeHandles
            panelId={id}
            dimensions={panel.dimensions}
            position={panel.position}
            onResizeEnd={handleResizeEnd}
          />
        </div>
      )}
    </div>
  )
}

export default FloatingPanel

// =============================================================================
// Storage Key
// =============================================================================

const STORAGE_KEY = 'tmnl-floating-panels'

// =============================================================================
// Context
// =============================================================================

interface FloatingPanelContextValue {
  /** Register a new panel */
  registerPanel: (config: PanelConfig) => void
  /** Unregister a panel */
  unregisterPanel: (id: string) => void
  /** Update panel position */
  updatePosition: (id: string, position: Position) => void
  /** Update panel dimensions */
  updateDimensions: (id: string, dimensions: Dimensions) => void
  /** Bring panel to front */
  bringToFront: (id: string) => void
  /** Send panel to back */
  sendToBack: (id: string) => void
  /** Close panel */
  closePanel: (id: string) => void
  /** Toggle panel mode (floating/docked) */
  toggleMode: (id: string) => void
  /** Get panel by ID */
  getPanel: (id: string) => PanelState | undefined
  /** Set panel visibility */
  setVisibility: (id: string, visibility: PanelVisibility) => void
}

const FloatingPanelContext = createContext<FloatingPanelContextValue | null>(null)

// =============================================================================
// Provider Props
// =============================================================================

export interface FloatingPanelProviderProps {
  children: ReactNode
  /** Disable persistence (panels reset on refresh) */
  disablePersistence?: boolean
  /** Callback when a non-panel drag starts (for sortables) */
  onSortableDragStart?: (event: DragStartEvent) => void
  /** Callback when a non-panel drag ends (for sortables) */
  onSortableDragEnd?: (event: DragEndEvent) => void
}

// =============================================================================
// Provider
// =============================================================================

export function FloatingPanelProvider({
  children,
  disablePersistence = false,
  onSortableDragStart,
  onSortableDragEnd,
}: FloatingPanelProviderProps) {
  const stx = getFloatingStx()

export function FloatingPanelProvider({
  children,
  disablePersistence = false,
  onSortableDragStart,
  onSortableDragEnd,
}: FloatingPanelProviderProps) {
  const stx = getFloatingStx()

  // Sensors with activation constraints (mouse + touch only)
  // KeyboardSensor removed: was intercepting Enter from input elements
  const sensors = useSensors(
    useSensor(MouseSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5,
      },
    })
  )

  // =============================================================================
  // Restore from persistence on mount
  // =============================================================================

  useEffect(() => {
    if (disablePersistence) return

    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      if (stored) {
        const storage = JSON.parse(stored) as PanelStorage
        restorePersistedState(storage)
      }
    } catch {
      // Ignore parse errors
    }
  }, [disablePersistence])

  // =============================================================================
  // Persist on changes
  // =============================================================================

  useEffect(() => {
    if (disablePersistence) return

    const disposer = stx.subscribe(() => {
      const panels = stx.data.panels.get()
      const zOrder = stx.data.zOrder.get()

      const storage: PanelStorage = {
        panels: {},
        order: zOrder,
        version: 1,
      }

      panels.forEach((panel, id) => {
        storage.panels[id] = {
          position: panel.position,
          dimensions: panel.dimensions,
          visibility: panel.visibility,
          mode: panel.mode,
        }
      })

      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(storage))
      } catch {
        // Storage full or unavailable
      }
    })

    return disposer
  }, [disablePersistence, stx])

  // =============================================================================
  // Actions (wrapped for context)
  // =============================================================================

return disposer
  }, [disablePersistence, stx])

  // =============================================================================
  // Actions (wrapped for context)
  // =============================================================================

  const registerPanel = useCallback((config: PanelConfig) => {
    stxRegisterPanel(config)
  }, [])

  const unregisterPanel = useCallback((id: string) => {
    stxUnregisterPanel(id)
  }, [])

  const updatePosition = useCallback((id: string, position: Position) => {
    updatePanelPosition(id, position)
  }, [])

  const updateDimensions = useCallback((id: string, dimensions: Dimensions) => {
    updatePanelDimensions(id, dimensions)
  }, [])

  const bringToFront = useCallback((id: string) => {
    bringPanelToFront(id)
  }, [])

  const sendToBack = useCallback((id: string) => {
    sendPanelToBack(id)
  }, [])

  const closePanel = useCallback((id: string) => {
    stxClosePanel(id)
  }, [])

  const toggleMode = useCallback((id: string) => {
    togglePanelMode(id)
  }, [])

  const getPanel = useCallback((id: string) => {
    return stxGetPanel(id)
  }, [])

  const setVisibility = useCallback((id: string, visibility: PanelVisibility) => {
    setPanelVisibility(id, visibility)
  }, [])

  // =============================================================================
  // Drag Handlers
  // =============================================================================

  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      const id = event.active.id as string
      const panel = stxGetPanel(id)

      if (panel) {
        // PANEL DRAG: bring to front, set dragging state, start velocity tracking via orchestrator
        bringPanelToFront(id)
        setDragging(id, true)

if (panel) {
        // PANEL DRAG: bring to front, set dragging state, start velocity tracking via orchestrator
        bringPanelToFront(id)
        setDragging(id, true)

        // Start drag orchestrator for centralized velocity tracking
        // Use activator event coordinates if available, else fall back to panel position
        const activatorEvent = event.activatorEvent as PointerEvent | undefined
        const startX = activatorEvent?.clientX ?? panel.position.x
        const startY = activatorEvent?.clientY ?? panel.position.y
        orchestratorStartDrag('floating', id, [id], { x: startX, y: startY })

        stx.send?.({ type: 'START_DRAG', panelId: id, position: { x: 0, y: 0 } })
      } else {
        // SORTABLE DRAG: delegate to callback
        onSortableDragStart?.(event)
      }
    },
    [stx, onSortableDragStart]
  )

  const handleDragMove = useCallback(
    (event: DragMoveEvent) => {
      const id = event.active.id as string
      const panel = stxGetPanel(id)

      if (panel) {
        // PANEL DRAG: update drag orchestrator for velocity tracking
        const activatorEvent = event.activatorEvent as PointerEvent | undefined
        if (activatorEvent) {
          // Calculate current position from delta + initial
          const currentX = activatorEvent.clientX + event.delta.x
          const currentY = activatorEvent.clientY + event.delta.y
          orchestratorUpdatePosition({ x: currentX, y: currentY })
        }
      }
      // Note: No sortable drag move callback - @dnd-kit handles it internally
    },
    []
  )

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const id = event.active.id as string
      const panel = stxGetPanel(id)

const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const id = event.active.id as string
      const panel = stxGetPanel(id)

      if (panel) {
        // PANEL DRAG: update position, clear dragging state, end drag orchestrator
        const { delta } = event
        let newPosition: Position = {
          x: panel.position.x + delta.x,
          y: panel.position.y + delta.y,
        }

        // Clamp position within bounds (if bounds provider exists)
        const bounds = getBounds()
        if (bounds) {
          newPosition = clampPosition(newPosition, panel.dimensions, bounds)
        }

        updatePanelPosition(id, newPosition)
        setDragging(id, false)

        // End drag orchestrator
        orchestratorEndDrag()

        stx.send?.({ type: 'END_DRAG' })
      } else {
        // SORTABLE DRAG: delegate to callback
        onSortableDragEnd?.(event)
      }
    },
    [stx, onSortableDragEnd]
  )

  // =============================================================================
  // Context Value
  // =============================================================================

  const contextValue = useMemo<FloatingPanelContextValue>(
    () => ({
      registerPanel,
      unregisterPanel,
      updatePosition,
      updateDimensions,
      bringToFront,
      sendToBack,
      closePanel,
      toggleMode,
      getPanel,
      setVisibility,
    }),
    [
      registerPanel,
      unregisterPanel,
      updatePosition,
      updateDimensions,
      bringToFront,
      sendToBack,
      closePanel,
      toggleMode,
      getPanel,
      setVisibility,
    ]
  )

  return (
    <FloatingPanelContext.Provider value={contextValue}>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragEnd={handleDragEnd}
      >
        {children}
      </DndContext>
    </FloatingPanelContext.Provider>
  )
}

