interface ResizeHandlesProps {
  panelId: string
  dimensions: Dimensions
  position: Position
  disabled?: boolean
  onResizeStart?: (edge: ResizeEdge) => void
  onResizeEnd?: (dimensions: Dimensions, position: Position) => void
