interface ResizeState {
  panelId: string
  edge: ResizeEdge
  initialDimensions: Dimensions
  initialPosition: Position
  initialPointer: Position
}

// =============================================================================
// Edge/Corner Configuration
// =============================================================================

interface HandleConfig {
  edge: ResizeEdge
  cursor: string
  style: React.CSSProperties
}

// Apple-style: generous hitboxes, corners get priority
const EDGE_THICKNESS = 6      // Edge handle thickness
const CORNER_SIZE = 16        // Corner hit area (larger for precision)
const EDGE_INSET = 4          // How far edge extends into panel

const HANDLES: HandleConfig[] = [
  // Edges - thin but generous hit area
  {
    edge: 'n',
    cursor: 'ns-resize',
    style: {
      top: -EDGE_INSET,
      left: CORNER_SIZE,
      right: CORNER_SIZE,
      height: EDGE_THICKNESS + EDGE_INSET,
    },
  },
  {
    edge: 's',
    cursor: 'ns-resize',

right: CORNER_SIZE,
      height: EDGE_THICKNESS + EDGE_INSET,
    },
  },
  {
    edge: 's',
    cursor: 'ns-resize',
    style: {
      bottom: -EDGE_INSET,
      left: CORNER_SIZE,
      right: CORNER_SIZE,
      height: EDGE_THICKNESS + EDGE_INSET,
    },
  },
  {
    edge: 'e',
    cursor: 'ew-resize',
    style: {
      right: -EDGE_INSET,
      top: CORNER_SIZE,
      bottom: CORNER_SIZE,
      width: EDGE_THICKNESS + EDGE_INSET,
    },
  },
  {
    edge: 'w',
    cursor: 'ew-resize',
    style: {
      left: -EDGE_INSET,
      top: CORNER_SIZE,
      bottom: CORNER_SIZE,
      width: EDGE_THICKNESS + EDGE_INSET,
    },
  },
  // Corners - larger hit area, higher z-index for priority
  {
    edge: 'nw',
    cursor: 'nwse-resize',
    style: {
      top: -EDGE_INSET,
      left: -EDGE_INSET,
      width: CORNER_SIZE + EDGE_INSET,
      height: CORNER_SIZE + EDGE_INSET,
    },
  },
  {
    edge: 'ne',
    cursor: 'nesw-resize',
    style: {
      top: -EDGE_INSET,
      right: -EDGE_INSET,
      width: CORNER_SIZE + EDGE_INSET,
      height: CORNER_SIZE + EDGE_INSET,
    },
  },
  {
    edge: 'sw',
    cursor: 'nesw-resize',
    style: {
      bottom: -EDGE_INSET,
      left: -EDGE_INSET,
      width: CORNER_SIZE + EDGE_INSET,

cursor: 'nesw-resize',
    style: {
      bottom: -EDGE_INSET,
      left: -EDGE_INSET,
      width: CORNER_SIZE + EDGE_INSET,
      height: CORNER_SIZE + EDGE_INSET,
    },
  },
  {
    edge: 'se',
    cursor: 'nwse-resize',
    style: {
      bottom: -EDGE_INSET,
      right: -EDGE_INSET,
      width: CORNER_SIZE + EDGE_INSET,
      height: CORNER_SIZE + EDGE_INSET,
    },
  },
