// =============================================================================
// Resize Calculation
// =============================================================================

function calculateResize(
  state: ResizeState,
  currentPointer: Position,
  sensitivity: number
): { dimensions: Dimensions; position: Position } {
  const deltaX = (currentPointer.x - state.initialPointer.x) * sensitivity
  const deltaY = (currentPointer.y - state.initialPointer.y) * sensitivity

  let width = state.initialDimensions.width
  let height = state.initialDimensions.height
  let x = state.initialPosition.x
  let y = state.initialPosition.y

  // Handle horizontal resize
  if (state.edge.includes('e')) {
    width = state.initialDimensions.width + deltaX
  }
  if (state.edge.includes('w')) {
    const newWidth = state.initialDimensions.width - deltaX
    if (newWidth >= 100) {
      width = newWidth
      x = state.initialPosition.x + deltaX
    }
  }

  // Handle vertical resize
  if (state.edge.includes('s')) {
    height = state.initialDimensions.height + deltaY
  }
  if (state.edge.includes('n')) {
    const newHeight = state.initialDimensions.height - deltaY
    if (newHeight >= 100) {
      height = newHeight
      y = state.initialPosition.y + deltaY
    }
  }

return {
    dimensions: { width: Math.max(100, width), height: Math.max(100, height) },
    position: { x, y },
  }
}

// =============================================================================
// Component
// =============================================================================

export function ResizeHandles({
  panelId,
  dimensions,
  position,
  disabled = false,
  onResizeStart,
  onResizeEnd,
}: ResizeHandlesProps) {
  const resizeStateRef = useRef<ResizeState | null>(null)
  const currentPositionRef = useRef(position)
  const currentDimensionsRef = useRef(dimensions)

  // Keep refs in sync
  useEffect(() => {
    if (!resizeStateRef.current) {
      currentPositionRef.current = position
      currentDimensionsRef.current = dimensions
    }
  }, [position, dimensions])

  // Global modifier key tracking (ignore input elements to prevent interference)
  useEffect(() => {
    const handleKeyChange = (e: KeyboardEvent) => {
      // Ignore keyboard events from input elements (search, text fields, etc.)
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return
      }

      updateModifierKeys({
        shift: e.shiftKey,
        ctrl: e.ctrlKey,
        alt: e.altKey,
      })
    }

    window.addEventListener('keydown', handleKeyChange)
    window.addEventListener('keyup', handleKeyChange)

    return () => {
      window.removeEventListener('keydown', handleKeyChange)
      window.removeEventListener('keyup', handleKeyChange)
    }
  }, [])

  const handlePointerDown = useCallback(
    (e: React.PointerEvent, edge: ResizeEdge) => {
      if (disabled) return

      e.preventDefault()
      e.stopPropagation()

      // Bring to front on resize start
      bringPanelToFront(panelId)

      // Capture pointer
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)

e.preventDefault()
      e.stopPropagation()

      // Bring to front on resize start
      bringPanelToFront(panelId)

      // Capture pointer
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)

      // Initialize resize state
      resizeStateRef.current = {
        panelId,
        edge,
        initialDimensions: currentDimensionsRef.current,
        initialPosition: currentPositionRef.current,
        initialPointer: { x: e.clientX, y: e.clientY },
      }

      setResizing(panelId, true)
      onResizeStart?.(edge)
    },
    [panelId, disabled, onResizeStart]
  )

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      const state = resizeStateRef.current
      if (!state) return

      // Get sensitivity from stx modifier keys directly
      const stx = getFloatingStx()
      const mods = stx.data.modifierKeys.get()
      const sensitivity = (mods.ctrl && mods.shift) ? 0.01 : mods.shift ? 0.1 : 1.0

      const currentPointer = { x: e.clientX, y: e.clientY }
      let result = calculateResize(state, currentPointer, sensitivity)

      // Clamp within bounds (if bounds provider exists)
      const bounds = getBounds()
      if (bounds) {
        const clamped = clampResize(
          result.position,
          result.dimensions,
          { width: 100, height: 100 }, // min dimensions
          bounds
        )
        result = { dimensions: clamped.dimensions, position: clamped.position }
      }

      // Update via stx
      updatePanelDimensions(panelId, result.dimensions)
      updatePanelPosition(panelId, result.position)

      // Track current values
      currentDimensionsRef.current = result.dimensions
      currentPositionRef.current = result.position
    },
    [panelId]
  )

  const handlePointerUp = useCallback(
    (e: React.PointerEvent) => {
      const state = resizeStateRef.current
      if (!state) return

const handlePointerUp = useCallback(
    (e: React.PointerEvent) => {
      const state = resizeStateRef.current
      if (!state) return

      // Release pointer capture
      ;(e.target as HTMLElement).releasePointerCapture(e.pointerId)

      setResizing(panelId, false)
      onResizeEnd?.(currentDimensionsRef.current, currentPositionRef.current)

      resizeStateRef.current = null
    },
    [panelId, onResizeEnd]
  )

  if (disabled) return null

  // Corners get higher z-index for priority targeting
  const isCorner = (edge: ResizeEdge) => edge.length === 2

  return (
    <>
      {HANDLES.map((handle) => (
        <div
          key={handle.edge}
          data-resize-handle={handle.edge}
          onPointerDown={(e) => handlePointerDown(e, handle.edge)}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          style={{
            position: 'absolute',
            cursor: handle.cursor,
            // Corners get higher z-index for easier targeting
            zIndex: isCorner(handle.edge) ? 12 : 10,
            // Touch-friendly: ensure minimum touch target
            touchAction: 'none',
            // Re-enable pointer events (wrapper has none)
            pointerEvents: 'auto',
            // Debug: uncomment to visualize handles
            // backgroundColor: isCorner(handle.edge) ? 'rgba(0, 255, 0, 0.3)' : 'rgba(255, 0, 0, 0.2)',
            ...handle.style,
          }}
        />
      ))}
    </>
  )
}

export default ResizeHandles

// =============================================================================
// Effects
// =============================================================================

const floatingEffects = {
  /**
   * Persist panel state to localStorage
   */
  persist: Effect.gen(function* () {
    // This will be called with stx instance via closure
    yield* Effect.sync(() => {
      const stx = getFloatingStx()
      const panels = stx.data.panels.get()
      const zOrder = stx.data.zOrder.get()

      const storage: PanelStorage = {
        panels: {},
        order: zOrder,
        version: 1,
      }

      panels.forEach((panel, id) => {
        storage.panels[id] = {
          position: panel.position,
          dimensions: panel.dimensions,
          visibility: panel.visibility,
          mode: panel.mode,
        }
      })

      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(storage))
      } catch {
        // Storage might be full or unavailable
      }
    })
  }),

  /**
   * Restore panel state from localStorage
   */
  restore: Effect.gen(function* () {
    yield* Effect.sync(() => {
      try {
        const stored = localStorage.getItem(STORAGE_KEY)
        if (!stored) return null

        const storage = JSON.parse(stored) as PanelStorage
        return storage
      } catch {
        return null
      }
    })
  }),

  /**
   * Spawn a floating panel from modal detach
   */
  spawnFromModal: (visitorId: string, visitorData: unknown, position?: Position) =>
    Effect.gen(function* () {
      const stx = getFloatingStx()
      const panelId = `modal-${visitorId}-${Date.now()}`

      const centerX = (typeof window !== 'undefined' ? window.innerWidth : 800) / 2 - DEFAULT_WIDTH / 2
      const centerY = (typeof window !== 'undefined' ? window.innerHeight : 600) / 2 - DEFAULT_HEIGHT / 2

const panel: PanelState = {
        id: panelId,
        title: visitorId,
        mode: 'floating',
        position: position ?? { x: centerX, y: centerY },
        dimensions: { width: DEFAULT_WIDTH, height: DEFAULT_HEIGHT },
        constraints: { minWidth: 200, minHeight: 150 },
        zIndex: stx.data.baseZIndex.get() + stx.data.zOrder.get().length,
        visibility: 'visible',
        isDragging: false,
        isResizing: false,
        isMaximized: false,
        preMaximizePosition: undefined,
        preMaximizeDimensions: undefined,
        closable: true,
        minimizable: true,
        resizable: true,
        visitorId,
        visitorData,
      }

      // Add to stx data
      yield* Effect.sync(() => {
        const panels = new Map(stx.data.panels.get())
        panels.set(panelId, panel)
        stx.data.panels.set(panels)
        stx.data.zOrder.set([...stx.data.zOrder.get(), panelId])
      })

      return panelId
    }),

  /**
   * Animate panel open (placeholder for GSAP/anime.js)
   */
  animateOpen: (panelId: string) =>
    Effect.gen(function* () {
      // TODO: Implement with GSAP or anime.js
      yield* Effect.sleep('50 millis')
      return panelId
    }),

  /**
   * Animate panel close (placeholder for GSAP/anime.js)
   */
  animateClose: (panelId: string) =>
    Effect.gen(function* () {
      // TODO: Implement with GSAP or anime.js
      yield* Effect.sleep('50 millis')
      return panelId
    }),
}

// =============================================================================
// Computed Values
// =============================================================================

const floatingComputed = {
  /**
   * Panels sorted by z-index (ascending)
   */
  sortedPanels: (get: { data: FloatingStxData }) => {
    const panels = get.data.panels
    const zOrder = get.data.zOrder

// Map over zOrder to get panels in correct order
    return zOrder
      .map((id: string) => panels.get(id))
      .filter((p): p is PanelState => p !== undefined)
  },

  /**
   * Top panel (highest z-index)
   */
  topPanel: (get: { data: FloatingStxData }) => {
    const zOrder = get.data.zOrder
    return zOrder[zOrder.length - 1] ?? null
  },

  /**
   * Currently active panel data
   */
  activePanelData: (get: { data: FloatingStxData }) => {
    const activeId = get.data.activePanel
    if (!activeId) return null
    return get.data.panels.get(activeId) ?? null
  },

  /**
   * Resize sensitivity based on modifier keys
   * - Normal: 1.0
   * - Shift: 0.1 (fine)
   * - Ctrl+Shift: 0.01 (ultra-fine)
   */
  resizeSensitivity: (get: { data: FloatingStxData }) => {
    // Access observable value via .get() pattern (Legend-State)
    const mods = typeof get.data.modifierKeys.get === 'function'
      ? get.data.modifierKeys.get()
      : get.data.modifierKeys
    if (mods.ctrl && mods.shift) return 0.01
    if (mods.shift) return 0.1
    return 1.0
  },

  /**
   * Visible panels only
   */
  visiblePanels: (get: { data: FloatingStxData }) => {
    const panels = get.data.panels
    const zOrder = get.data.zOrder

    return zOrder
      .map((id: string) => panels.get(id))
      .filter((p): p is PanelState => p !== undefined && p.visibility === 'visible')
  },

return zOrder
      .map((id: string) => panels.get(id))
      .filter((p): p is PanelState => p !== undefined && p.visibility === 'visible')
  },

  /**
   * Motion blur style based on drag velocity
   * Returns CSS properties for blur and directional stretch
   */
  motionBlurStyle: (get: { data: FloatingStxData }) => {
    const velocity = typeof get.data.dragVelocity.get === 'function'
      ? get.data.dragVelocity.get()
      : get.data.dragVelocity
    const draggingPanel = typeof get.data.draggingPanel.get === 'function'
      ? get.data.draggingPanel.get()
      : get.data.draggingPanel

    const isActive = draggingPanel !== null && velocity.magnitude > 2

    if (!isActive) {
      return {
        filter: undefined as string | undefined,
        transform: undefined as string | undefined,
        transition: 'filter 0.15s ease-out, transform 0.15s ease-out',
        isActive: false,
        blurAmount: 0,
      }
    }

    // Calculate blur amount (capped at 6px)
    const blurAmount = Math.min(velocity.magnitude * 0.08, 6)

    // Directional stretch for motion smear
    let stretchTransform: string | undefined = undefined
    if (velocity.magnitude > 4) {
      const stretchFactor = Math.min(1 + velocity.magnitude * 0.001, 1.03)
      const angleDeg = (velocity.angle * 180) / Math.PI
      stretchTransform = `rotate(${angleDeg}deg) scaleX(${stretchFactor}) rotate(${-angleDeg}deg)`
    }

    return {
      filter: blurAmount > 0.5 ? `blur(${blurAmount.toFixed(1)}px)` : undefined,
      transform: stretchTransform,
      transition: 'none',
      isActive: true,
      blurAmount,
    }
  },
}

