/**
 * usePanelPersistence Hook
 *
 * localStorage persistence for floating panel positions and z-index order.
 *
 * @pattern localStorage + debounced writes
 * @module
 */

import { useCallback, useRef } from 'react'
import type {
  PanelStorage,
  PanelPosition,
  PersistedPanelState,
  UsePanelPersistenceReturn,
} from '../types'

// =============================================================================
// Constants
// =============================================================================

const STORAGE_KEY = 'tmnl-floating-panels'
const DEBOUNCE_MS = 250

// =============================================================================
// Helpers
// =============================================================================

/**
 * Safely parse JSON from localStorage
 */
function parseStorage(raw: string | null): PanelStorage | null {
  if (!raw) return null

  try {
    const parsed = JSON.parse(raw)
    // Basic shape validation
    if (
      typeof parsed === 'object' &&
      parsed !== null &&
      typeof parsed.panels === 'object' &&
      Array.isArray(parsed.order)
    ) {
      return parsed as PanelStorage
    }
  } catch {
    // Invalid JSON — ignore
  }

  return null
}

/**
 * Safely write to localStorage
 */
function writeStorage(storage: PanelStorage): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(storage))
  } catch {
    // Storage quota exceeded or unavailable — fail silently
  }
}

/**
 * Create empty storage object
 */
function emptyStorage(): PanelStorage {
  return {
    panels: {},
    order: [],
  }
}

// =============================================================================
// Hook
// =============================================================================

/**
 * Create empty storage object
 */
function emptyStorage(): PanelStorage {
  return {
    panels: {},
    order: [],
  }
}

// =============================================================================
// Hook
// =============================================================================

/**
 * Hook for persisting floating panel positions to localStorage.
 *
 * @param persistKey Optional custom storage key (defaults to 'tmnl-floating-panels')
 *
 * @example
 * ```tsx
 * const persistence = usePanelPersistence()
 *
 * // On mount, restore positions
 * useEffect(() => {
 *   const stored = persistence.load()
 *   if (stored) {
 *     // Apply stored positions to panels
 *   }
 * }, [])
 *
 * // On drag end, persist position
 * const handleDragEnd = (id: string, position: PanelPosition) => {
 *   persistence.updatePosition(id, position)
 * }
 * ```
 */
export function usePanelPersistence(
  persistKey: string = STORAGE_KEY
): UsePanelPersistenceReturn {
  // Debounce timer ref
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Cached storage ref for debounced writes
  const pendingStorageRef = useRef<PanelStorage | null>(null)

  /**
   * Flush pending storage write immediately
   */
  const flush = useCallback(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current)
      debounceRef.current = null
    }
    if (pendingStorageRef.current) {
      writeStorage(pendingStorageRef.current)
      pendingStorageRef.current = null
    }
  }, [])

  /**
   * Schedule a debounced write
   */
  const scheduleWrite = useCallback(
    (storage: PanelStorage) => {
      pendingStorageRef.current = storage

      if (debounceRef.current) {
        clearTimeout(debounceRef.current)
      }

      debounceRef.current = setTimeout(() => {
        flush()
      }, DEBOUNCE_MS)
    },
    [flush]
  )

  /**
   * Load persisted state from storage
   */
  const load = useCallback((): PanelStorage | null => {
    if (typeof window === 'undefined') return null

/**
   * Load persisted state from storage
   */
  const load = useCallback((): PanelStorage | null => {
    if (typeof window === 'undefined') return null

    const raw = localStorage.getItem(persistKey)
    return parseStorage(raw)
  }, [persistKey])

  /**
   * Save full state to storage
   */
  const save = useCallback(
    (storage: PanelStorage): void => {
      scheduleWrite(storage)
    },
    [scheduleWrite]
  )

  /**
   * Update single panel position (merge with existing)
   */
  const updatePosition = useCallback(
    (id: string, position: PanelPosition): void => {
      const current = load() ?? emptyStorage()

      const existingPanel = current.panels[id] ?? {
        position: { x: 0, y: 0 },
        visibility: 'visible' as const,
      }

      current.panels[id] = {
        ...existingPanel,
        position,
      }

      scheduleWrite(current)
    },
    [load, scheduleWrite]
  )

  /**
   * Update panel order (z-index stacking)
   */
  const updateOrder = useCallback(
    (order: string[]): void => {
      const current = load() ?? emptyStorage()
      current.order = order
      scheduleWrite(current)
    },
    [load, scheduleWrite]
  )

  /**
   * Clear all persisted state
   */
  const clear = useCallback((): void => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current)
      debounceRef.current = null
    }
    pendingStorageRef.current = null

    try {
      localStorage.removeItem(persistKey)
    } catch {
      // Fail silently
    }
  }, [persistKey])

  return {
    load,
    save,
    updatePosition,
    updateOrder,
    clear,
  }
}

export default usePanelPersistence

/**
 * useResize Hook
 *
 * Pointer event handling for panel resize operations.
 * Integrates with stx for sensitivity based on modifier keys.
 *
 * @pattern Pointer capture + stx integration
 * @module
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  getFloatingStx,
  updatePanelDimensions,
  setResizing,
  updateModifierKeys,
} from '../floating-stx'
import type { ResizeEdge, Dimensions, Position, UseResizeReturn } from '../types'

// =============================================================================
// Resize Calculation
// =============================================================================

interface ResizeState {
  initialDimensions: Dimensions
  initialPosition: Position
  initialPointer: Position
  edge: ResizeEdge
}

/**
 * Calculate new dimensions based on edge being dragged
 */
function calculateNewDimensions(
  state: ResizeState,
  currentPointer: Position,
  sensitivity: number
): { dimensions: Dimensions; position: Position } {
  const deltaX = (currentPointer.x - state.initialPointer.x) * sensitivity
  const deltaY = (currentPointer.y - state.initialPointer.y) * sensitivity

  let width = state.initialDimensions.width
  let height = state.initialDimensions.height
  let x = state.initialPosition.x
  let y = state.initialPosition.y

  // Handle horizontal resize
  if (state.edge.includes('e')) {
    width = state.initialDimensions.width + deltaX
  }
  if (state.edge.includes('w')) {
    width = state.initialDimensions.width - deltaX
    x = state.initialPosition.x + deltaX
  }

  // Handle vertical resize
  if (state.edge.includes('s')) {
    height = state.initialDimensions.height + deltaY
  }
  if (state.edge.includes('n')) {
    height = state.initialDimensions.height - deltaY
    y = state.initialPosition.y + deltaY
  }

  return {
    dimensions: { width: Math.max(100, width), height: Math.max(100, height) },
    position: { x, y },
  }
}

// =============================================================================
// Hook
// =============================================================================

return {
    dimensions: { width: Math.max(100, width), height: Math.max(100, height) },
    position: { x, y },
  }
}

// =============================================================================
// Hook
// =============================================================================

export interface UseResizeOptions {
  /** Panel ID */
  panelId: string
  /** Initial dimensions */
  initialDimensions: Dimensions
  /** Initial position */
  initialPosition: Position
  /** Callback when resize completes */
  onResizeEnd?: (dimensions: Dimensions, position: Position) => void
}

export function useResize({
  panelId,
  initialDimensions,
  initialPosition,
  onResizeEnd,
}: UseResizeOptions): UseResizeReturn {
  const [isResizing, setIsResizingState] = useState(false)
  const [resizeEdge, setResizeEdge] = useState<ResizeEdge | null>(null)

  const resizeStateRef = useRef<ResizeState | null>(null)
  const currentPositionRef = useRef(initialPosition)

  // Update refs when props change
  useEffect(() => {
    if (!isResizing) {
      currentPositionRef.current = initialPosition
    }
  }, [initialPosition, isResizing])

  // Global modifier key tracking (ignore input elements to prevent interference)
  useEffect(() => {
    const handleKeyChange = (e: KeyboardEvent) => {
      // Ignore keyboard events from input elements (search, text fields, etc.)
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return
      }

      updateModifierKeys({
        shift: e.shiftKey,
        ctrl: e.ctrlKey,
        alt: e.altKey,
      })
    }

    window.addEventListener('keydown', handleKeyChange)
    window.addEventListener('keyup', handleKeyChange)

    return () => {
      window.removeEventListener('keydown', handleKeyChange)
      window.removeEventListener('keyup', handleKeyChange)
    }
  }, [])

return () => {
      window.removeEventListener('keydown', handleKeyChange)
      window.removeEventListener('keyup', handleKeyChange)
    }
  }, [])

  const startResize = useCallback(
    (edge: ResizeEdge) => {
      setResizeEdge(edge)
      setIsResizingState(true)
      setResizing(panelId, true)
    },
    [panelId]
  )

  const handlePointerMove = useCallback(
    (e: PointerEvent) => {
      if (!isResizing || !resizeStateRef.current) return

      const stx = getFloatingStx()
      const sensitivity = stx.computed.resizeSensitivity

      const currentPointer = { x: e.clientX, y: e.clientY }
      const result = calculateNewDimensions(
        resizeStateRef.current,
        currentPointer,
        sensitivity
      )

      // Update dimensions via stx
      updatePanelDimensions(panelId, result.dimensions)

      // Store new position
      currentPositionRef.current = result.position
    },
    [isResizing, panelId]
  )

  const handlePointerUp = useCallback(() => {
    if (!isResizing) return

    const stx = getFloatingStx()
    const panel = stx.data.panels.get().get(panelId)

    setIsResizingState(false)
    setResizeEdge(null)
    setResizing(panelId, false)
    resizeStateRef.current = null

    if (panel && onResizeEnd) {
      onResizeEnd(panel.dimensions, currentPositionRef.current)
    }
  }, [isResizing, panelId, onResizeEnd])

  // Initialize resize state when starting
  const handlePointerDown = useCallback(
    (e: PointerEvent, edge: ResizeEdge) => {
      e.preventDefault()
      e.stopPropagation()

      // Capture pointer for smooth resize
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)

      resizeStateRef.current = {
        initialDimensions,
        initialPosition: currentPositionRef.current,
        initialPointer: { x: e.clientX, y: e.clientY },
        edge,
      }

resizeStateRef.current = {
        initialDimensions,
        initialPosition: currentPositionRef.current,
        initialPointer: { x: e.clientX, y: e.clientY },
        edge,
      }

      startResize(edge)
    },
    [initialDimensions, startResize]
  )

  return {
    startResize,
    isResizing,
    resizeEdge,
    handlePointerMove,
    handlePointerUp,
    // Expose for direct binding
    createHandlers: (edge: ResizeEdge) => ({
      onPointerDown: (e: React.PointerEvent) => handlePointerDown(e.nativeEvent, edge),
    }),
  }
}

// Extend the return type
declare module '../types' {
  interface UseResizeReturn {
    createHandlers: (edge: ResizeEdge) => {
      onPointerDown: (e: React.PointerEvent) => void
    }
  }
}

