  ctrl: 'Control',
  control: 'Control',
  alt: 'Alt',
  option: 'Alt',
  opt: 'Alt',
  shift: 'Shift',
  meta: 'Meta',
  cmd: 'Meta',
  command: 'Meta',
  win: 'Meta',
  windows: 'Meta',
  super: 'Meta',

  // Arrows
  up: 'ArrowUp',
  down: 'ArrowDown',
  left: 'ArrowLeft',
  right: 'ArrowRight',
  arrowup: 'ArrowUp',
  arrowdown: 'ArrowDown',
  arrowleft: 'ArrowLeft',
  arrowright: 'ArrowRight',

  // Space
  space: ' ',
  spc: ' ',

  // Tab
  tab: 'Tab',

  // Backspace/Delete
  backspace: 'Backspace',
  bs: 'Backspace',
  delete: 'Delete',
  del: 'Delete',

  // Home/End/PageUp/PageDown
  home: 'Home',
  end: 'End',
  pageup: 'PageUp',
  pgup: 'PageUp',
  pagedown: 'PageDown',
  pgdn: 'PageDown',

// Insert
  insert: 'Insert',
  ins: 'Insert',

  // Punctuation/Symbols
  plus: '+',
  minus: '-',
  comma: ',',
  period: '.',
  dot: '.',
  slash: '/',
  backslash: '\\',
  semicolon: ';',
  quote: "'",
  backtick: '`',
  tilde: '~',
  equal: '=',
  equals: '=',
  bracket: '[',
  openbracket: '[',
  closebracket: ']',
}

/** Modifier key identifiers */
const MODIFIER_KEYS = new Set(['ctrl', 'control', 'alt', 'option', 'opt', 'shift', 'meta', 'cmd', 'command', 'win', 'windows', 'super'])

// ─────────────────────────────────────────────────────────────────────────────
// Implementation
// ─────────────────────────────────────────────────────────────────────────────

