    if (/^f\d{1,2}$/.test(lower)) {
      return 'F' + lower.slice(1)
    }

    // Single letters stay lowercase
    if (key.length === 1) {
      return key.toLowerCase()
    }

    // CamelCase keys (ArrowUp, etc.) stay as-is
    return key
  }

