/**
 * TMNL Indices Builder - Types
 *
 * Multi-source search composition inspired by Emacs Consult.
 * Sources are DATA definitions; search mechanics handled by src/lib/search.
 *
 * @see assets/documents/IDEA-MILL.org IDEA-0005 for research
 */

import type { Effect, Stream } from "effect"

// ─────────────────────────────────────────────────────────────────────────────
// Base Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Searchable item shape - all sources must produce items extending this
 */
export interface SearchItem {
  readonly id: string
  readonly _source?: string // Injected by builder for narrowing
}

/**
 * Preview data for candidate preview (optional)
 */
export interface PreviewData {
  readonly type: "route" | "content" | "component"
  readonly route?: string
  readonly content?: string
  readonly component?: React.ComponentType
}

// ─────────────────────────────────────────────────────────────────────────────
// Source Definition
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Search source - candidate generator with metadata
 *
 * Inspired by Consult's source plist pattern:
 * - :name → name
 * - :narrow → narrowKey
 * - :category → category
 * - :items → items (sync)
 * - :async → items (stream)
 * - :action → action
 * - :state → preview
 *
 * @example
 * ```ts
 * const testbedSource: SearchSource<TestbedSearchItem> = {
 *   id: 'testbeds',
 *   name: 'Testbeds',
 *   narrowKey: 't',
 *   category: 'navigation',
 *   icon: '◈',
 *   items: () => Effect.succeed(getSearchableTestbeds()),
 *   action: (item) => Effect.sync(() => navigate(item.route)),
 * }
 * ```
 */
export interface SearchSource<T extends SearchItem> {
  /** Unique source identifier */
  readonly id: string

  /** Display name for group headers */
  readonly name: string

/** Display name for group headers */
  readonly name: string

  /** Narrowing key - press key + space to filter to this source only */
  readonly narrowKey?: string

  /** Category for styling/actions (like Consult's completion category) */
  readonly category: string

  /** Icon for source (displayed in group headers) */
  readonly icon?: string

  /** Face/accent color for candidates from this source */
  readonly accent?: string

  /** Hidden by default? User must explicitly widen to see */
  readonly hidden?: boolean

  /** Enable predicate - source excluded if returns false */
  readonly enabled?: () => boolean

  /**
   * Candidate generator
   *
   * Sync: Returns Effect that resolves to item array
   * Async: Returns Stream that yields items progressively
   */
  readonly items: () => Effect.Effect<readonly T[]> | Stream.Stream<T>

  /**
   * Action to execute when item is selected
   * Called after selection, not during preview
   */
  readonly action: (item: T) => Effect.Effect<void>

  /**
   * Preview function for live preview during selection
   * Optional - not all sources support preview
   */
  readonly preview?: (item: T) => Effect.Effect<PreviewData>
}

// ─────────────────────────────────────────────────────────────────────────────
// Builder Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Narrowing state
 */
export interface NarrowState {
  /** Currently active narrow key, or null for all sources */
  readonly activeKey: string | null

  /** Map of narrowKey → sourceId for quick lookup */
  readonly keyToSource: ReadonlyMap<string, string>
}

/**
 * Merged item with source metadata injected
 */
export type MergedItem<T extends SearchItem> = T & {
  readonly _source: string
  readonly _sourceName: string
  readonly _sourceIcon?: string
  readonly _sourceAccent?: string
}

/**
 * Indices builder configuration
 */
export interface IndicesConfig {
  /** Debounce time for async sources (ms) */
  readonly debounceMs?: number

  /** Max concurrent async source fetches */
  readonly concurrency?: number

  /** Include hidden sources? */
  readonly includeHidden?: boolean
}

/**
 * Indices builder result - what consumers receive
 */
export interface IndicesResult<T extends SearchItem> {
  /** Merged stream of all items from all sources */
  readonly stream: Stream.Stream<MergedItem<T>>

  /** Narrow to a single source */
  readonly narrow: (key: string) => void

  /** Widen to all sources */
  readonly widen: () => void

  /** Get source by narrow key */
  readonly getSourceByKey: (key: string) => SearchSource<T> | undefined

  /** All registered sources */
  readonly sources: readonly SearchSource<T>[]

  /** Current narrow state */
  readonly narrowState: NarrowState
}

// ─────────────────────────────────────────────────────────────────────────────
// Source Registry Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Source registration - sources can be added dynamically
 */
export interface SourceRegistry<T extends SearchItem> {
  /** Register a new source */
  readonly register: (source: SearchSource<T>) => void

  /** Unregister a source by ID */
  readonly unregister: (sourceId: string) => void

  /** Get all registered sources */
  readonly getSources: () => readonly SearchSource<T>[]

  /** Get source by ID */
  readonly getSource: (sourceId: string) => SearchSource<T> | undefined

  /** Get source by narrow key */
  readonly getSourceByKey: (key: string) => SearchSource<T> | undefined
}

export * from './types';
export * from './services/InstrumentationService';
export * from './utils/pipeable';

import { Effect, Context, Layer, Ref } from 'effect';
import type {
  InstrumentationConfigShape,
  CapturedSpan,
  SpanAttributes,
  SpanKind,
  SpanStatus,
} from '../types';

export class InstrumentationConfig extends Context.Tag(
  'tmnl/instrumentation/Config'
)<InstrumentationConfig, InstrumentationConfigShape>() {
  static Default = Layer.succeed(this, {
    serviceName: 'tmnl',
    enableTracing: true,
    enableMetrics: false,
    sampleRate: 1.0,
  });

  static Custom = (config: InstrumentationConfigShape) =>
    Layer.succeed(this, config);
}

export class InstrumentationService extends Effect.Service<InstrumentationService>()(
  'tmnl/instrumentation/InstrumentationService',
  {
    effect: Effect.gen(function* () {
      const config = yield* InstrumentationConfig;
      const capturedSpans = yield* Ref.make<readonly CapturedSpan[]>([]);
      const activeSpans = yield* Ref.make<Map<string, CapturedSpan>>(new Map());

      const captureSpan = (span: CapturedSpan) =>
        Effect.gen(function* () {
          if (!config.enableTracing) return;

          yield* Ref.update(capturedSpans, (spans) => [...spans, span]);
          yield* Effect.logDebug('Span captured', {
            spanId: span.spanId,
            name: span.name,
            duration:
              span.endTime && span.startTime
                ? span.endTime.getTime() - span.startTime.getTime()
                : undefined,
          });
        });

      const startSpan = (
        name: string,
        kind: SpanKind,
        attributes: SpanAttributes
      ) =>
        Effect.gen(function* () {
          const spanId = crypto.randomUUID();
          const traceId = crypto.randomUUID();

          const span: CapturedSpan = {
            spanId,
            traceId,
            name,
            kind,
            startTime: new Date(),
            status: 'unset',
            attributes,
            events: [],
            serviceName: config.serviceName,
          };

yield* Ref.update(activeSpans, (spans) =>
            new Map(spans).set(spanId, span)
          );

          return spanId;
        });

      const endSpan = (spanId: string, status: SpanStatus) =>
        Effect.gen(function* () {
          const spans = yield* Ref.get(activeSpans);
          const span = spans.get(spanId);

          if (!span) {
            yield* Effect.logWarning('Attempted to end non-existent span', {
              spanId,
            });
            return;
          }

          const completedSpan: CapturedSpan = {
            ...span,
            endTime: new Date(),
            status,
          };

          yield* captureSpan(completedSpan);
          yield* Ref.update(activeSpans, (s) => {
            const updated = new Map(s);
            updated.delete(spanId);
            return updated;
          });
        });

      const getCapturedSpans = () => Ref.get(capturedSpans);

      const clearCapturedSpans = () => Ref.set(capturedSpans, []);

      return {
        captureSpan,
        startSpan,
        endSpan,
        getCapturedSpans,
        clearCapturedSpans,
      } as const;
    }),
    dependencies: [InstrumentationConfig.Default],
  }
) {}

/**
 * @module instrumentation/v1/types
 * @description Core types for Effect-based instrumentation and telemetry
 *
 * DESIGN PRINCIPLES:
 * - OpenTelemetry-compliant span attributes
 * - AI-friendly structured data (LLM-queryable)
 * - NATS KV/ObjectStore persistence backend
 * - Minimal performance overhead
 */

import { Schema } from 'effect';

/**
 * Span attribute value types (OpenTelemetry-compliant)
 */
export type SpanAttributeValue =
  | string
  | number
  | boolean
  | string[]
  | number[]
  | boolean[];

/**
 * Span attributes (OpenTelemetry semantic conventions)
 */
export interface SpanAttributes {
  readonly [key: string]: SpanAttributeValue;
}

/**
 * Span event (point-in-time occurrence during span)
 */
export const SpanEvent = Schema.Struct({
  name: Schema.NonEmptyString,
  timestamp: Schema.DateFromSelf,
  attributes: Schema.optional(
    Schema.Record({ key: Schema.String, value: Schema.Unknown })
  ),
});
export interface SpanEvent extends Schema.Schema.Type<typeof SpanEvent> {}

/**
 * Span status (follows OpenTelemetry spec)
 */
export const SpanStatus = Schema.Literal('unset', 'ok', 'error');
export type SpanStatus = Schema.Schema.Type<typeof SpanStatus>;

/**
 * Span kind (follows OpenTelemetry spec)
 */
export const SpanKind = Schema.Literal(
  'internal', // Default - internal operation
  'server', // Server-side request handler
  'client', // Client-side request
  'producer', // Message producer
  'consumer' // Message consumer
);
export type SpanKind = Schema.Schema.Type<typeof SpanKind>;

/**
 * Captured span data (persisted to NATS)
 */
export const CapturedSpan = Schema.Struct({
  spanId: Schema.NonEmptyString,
  traceId: Schema.NonEmptyString,
  parentSpanId: Schema.optional(Schema.NonEmptyString),
  name: Schema.NonEmptyString,
  kind: SpanKind,
  startTime: Schema.DateFromSelf,
  endTime: Schema.optional(Schema.DateFromSelf),
  status: SpanStatus,
  attributes: Schema.Record({ key: Schema.String, value: Schema.Unknown }),
  events: Schema.Array(SpanEvent),
  serviceName: Schema.NonEmptyString,
});
export interface CapturedSpan extends Schema.Schema.Type<typeof CapturedSpan> {}

/**
 * Trace context (propagated across service boundaries)
 */
export const TraceContext = Schema.Struct({
  traceId: Schema.NonEmptyString,
  spanId: Schema.NonEmptyString,
  traceFlags: Schema.Number, // Bitmask (0x01 = sampled)
});
export interface TraceContext extends Schema.Schema.Type<typeof TraceContext> {}

export interface InstrumentationConfigShape {
  readonly serviceName: string;
  readonly enableTracing: boolean;
  readonly enableMetrics: boolean;
  readonly sampleRate: number;
  readonly natsUrl?: string;
  readonly otlpEndpoint?: string;
}

/**
 * Span options for withSpan pipe operator
 */
export interface SpanOptions {
  readonly name: string;
  readonly kind?: SpanKind;
  readonly attributes?: SpanAttributes;
  readonly captureStack?: boolean;
}

/**
 * Persisted trace query
 */
export interface TraceQuery {
  readonly traceId?: string;
  readonly serviceName?: string;
  readonly minDuration?: number;
  readonly startTime?: Date;
  readonly endTime?: Date;
  readonly attributes?: Record<string, SpanAttributeValue>;
  readonly limit?: number;
}

/**
 * NATS storage keys (KV bucket organization)
 */
export const NATS_STORAGE = {
  KV_BUCKET: 'tmnl-traces', // Span metadata
  OBJ_BUCKET: 'tmnl-trace-data', // Large payloads
  STREAM: 'TRACES', // JetStream for live feed
} as const;

/**
 * Pipeable utilities for Effect instrumentation
 *
 * @module instrumentation/v1/utils/pipeable
 */

import { Effect, Cause } from 'effect';
import { InstrumentationService } from '../services/InstrumentationService';
import type { SpanAttributes, SpanKind } from '../types';

/**
 * Wraps an Effect with automatic span creation and capture
 */
export const withInstrumentedSpan = <A, E, R>(
  name: string,
  options?: {
    kind?: SpanKind;
    attributes?: SpanAttributes;
  }
) => {
  return (
    effect: Effect.Effect<A, E, R>
  ): Effect.Effect<A, E, R | InstrumentationService> =>
    Effect.gen(function* () {
      const service = yield* InstrumentationService;

      const spanId = yield* service.startSpan(
        name,
        options?.kind ?? 'internal',
        options?.attributes ?? {}
      );

      try {
        const result = yield* effect;
        yield* service.endSpan(spanId, 'ok');
        return result;
      } catch (error) {
        yield* service.endSpan(spanId, 'error');
        return yield* Effect.fail(error as E);
      }
    });
};

/**
 * Tap into an Effect to trace intermediate values
 */
export const tapTrace = <A>(
  eventName: string,
  extractAttributes?: (value: A) => SpanAttributes
) => {
  return <E, R>(
    effect: Effect.Effect<A, E, R>
  ): Effect.Effect<A, E, R | InstrumentationService> =>
    Effect.gen(function* () {
      const service = yield* InstrumentationService;
      const value = yield* effect;

      const attributes = extractAttributes?.(value) ?? {};
      const spanId = yield* service.startSpan(
        eventName,
        'internal',
        attributes
      );
      yield* service.endSpan(spanId, 'ok');

      return value;
    });
};

return value;
    });
};

/**
 * Capture errors with full Cause information
 */
export const captureError = <E>(
  eventName: string,
  extractAttributes?: (cause: Cause.Cause<E>) => SpanAttributes
) => {
  return <A, R>(
    effect: Effect.Effect<A, E, R>
  ): Effect.Effect<A, E, R | InstrumentationService> =>
    effect.pipe(
      Effect.tapErrorCause((cause) =>
        Effect.gen(function* () {
          const service = yield* InstrumentationService;
          const attributes = extractAttributes?.(cause) ?? {};

          const spanId = yield* service.startSpan(eventName, 'internal', {
            ...attributes,
            'error.cause': Cause.pretty(cause),
          });

          yield* service.endSpan(spanId, 'error');
        })
      )
    );
};

/**
 * Create a traced function from a regular function
 */
export const traced = <Args extends readonly unknown[], A>(
  name: string,
  fn: (...args: Args) => A,
  options?: {
    kind?: SpanKind;
    attributes?: (...args: Args) => SpanAttributes;
  }
) => {
  return (...args: Args): Effect.Effect<A, never, InstrumentationService> =>
    Effect.gen(function* () {
      const service = yield* InstrumentationService;

      const spanId = yield* service.startSpan(
        name,
        options?.kind ?? 'internal',
        options?.attributes?.(...args) ?? {}
      );

      try {
        const result = fn(...args);
        yield* service.endSpan(spanId, 'ok');
        return result;
      } catch (error) {
        yield* service.endSpan(spanId, 'error');
        throw error;
      }
    });
};

/**
 * Time an Effect execution
 */
export const timed = (spanName: string) => {
  return <A, E, R>(
    effect: Effect.Effect<A, E, R>
  ): Effect.Effect<A, E, R | InstrumentationService> =>
    Effect.gen(function* () {
      const service = yield* InstrumentationService;
      const spanId = yield* service.startSpan(spanName, 'internal', {});

      try {
        const result = yield* effect;
        yield* service.endSpan(spanId, 'ok');
        return result;
      } catch (error) {
        yield* service.endSpan(spanId, 'error');
        return yield* Effect.fail(error as E);
      }
    });
};

/**
 * Batch multiple spans together (useful for parallel operations)
 */
export const batchSpans = <
  T extends Record<string, Effect.Effect<any, any, any>>
>(
  parentSpanName: string,
  operations: T
): Effect.Effect<
  { [K in keyof T]: T[K] extends Effect.Effect<infer A, any, any> ? A : never },
  T[keyof T] extends Effect.Effect<any, infer E, any> ? E : never,
  | (T[keyof T] extends Effect.Effect<any, any, infer R> ? R : never)
  | InstrumentationService
> =>
  Effect.gen(function* () {
    const service = yield* InstrumentationService;

    const parentSpanId = yield* service.startSpan(parentSpanName, 'internal', {
