const runEffect = <A, E>(effect: Effect.Effect<A, E, KoriWorld>) =>
  runtime.runPromise(effect)

const runScopedEffect = <A, E>(
  effect: Effect.Effect<A, E, KoriWorld | Scope.Scope>
) =>
  runtime.runPromise(pipe(effect, Effect.scoped))

