 * const IsEnemy = defineTagTrait("IsEnemy")
 * ```
 */
export function defineTagTrait<Tag extends string>(
  tag: Tag
): Schema.TaggedStruct<Tag, {}> {
  return Schema.TaggedStruct(tag, {})
}

