/**
 * KORI Merge Service
 *
 * Defu-based deep merging wrapped as Effect operations.
 * Enables trait composition with schema-aware merge semantics.
 *
 * @module
 */

import { Context, Effect, Layer, pipe } from "effect"
import { defu, defuFn, defuArrayFn, createDefu } from "defu"
import type { TraitId } from "../schemas/trait"
import { TraitValidationFailed, SchemaTransformError } from "../errors"

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Custom merger function signature.
 * Returns true if merge was handled, false to use default behavior.
 */
export type MergerFn = (
  obj: Record<string, unknown>,
  key: string,
  value: unknown
) => boolean

/**
 * Merge strategy for trait composition.
 */
export type MergeStrategy = "default" | "fn" | "arrayFn" | "custom"

/**
 * Merge configuration.
 */
export interface MergeConfig {
  readonly strategy: MergeStrategy
  readonly customMerger?: MergerFn
}

/**
 * Trait merge result with metadata.
 */
export interface MergeResult<T> {
  readonly merged: T
  readonly sourceTraitIds: ReadonlyArray<TraitId>
  readonly strategy: MergeStrategy
}

// ─────────────────────────────────────────────────────────────────────────────
// Service Interface
// ─────────────────────────────────────────────────────────────────────────────

/**
 * KORI Merge operations.
 */
export interface KoriMergeOps {
  /**
   * Deep merge objects with leftmost priority.
   * Uses defu default strategy.
   */
  readonly merge: <T extends Record<string, unknown>>(
    target: Partial<T>,
    ...sources: ReadonlyArray<Partial<T>>
  ) => Effect.Effect<T>

/**
   * Merge with function value handling.
   * Functions in target are called with corresponding default value.
   */
  readonly mergeFn: <T extends Record<string, unknown>>(
    target: Partial<T>,
    defaults: Partial<T>
  ) => Effect.Effect<T>

  /**
   * Merge with array-only function handling.
   * Functions are called only when default value is an array.
   */
  readonly mergeArrayFn: <T extends Record<string, unknown>>(
    target: Partial<T>,
    defaults: Partial<T>
  ) => Effect.Effect<T>

  /**
   * Create a custom merger for specialized merge behavior.
   */
  readonly createMerger: (
    merger: MergerFn
  ) => <T extends Record<string, unknown>>(
    target: Partial<T>,
    ...sources: ReadonlyArray<Partial<T>>
  ) => Effect.Effect<T>

  /**
   * Merge trait data with schema validation.
   * Validates result against trait schema.
   */
  readonly mergeTraits: <T extends Record<string, unknown>>(
    traitId: TraitId,
    target: Partial<T>,
    ...sources: ReadonlyArray<Partial<T>>
  ) => Effect.Effect<MergeResult<T>, TraitValidationFailed>

  /**
   * Compose multiple traits into a combined data structure.
   * Useful for entity composition from trait defaults.
   */
  readonly composeTrait: <T extends Record<string, unknown>>(
    traitIds: ReadonlyArray<TraitId>,
    data: ReadonlyArray<Partial<T>>,
    config?: MergeConfig
  ) => Effect.Effect<MergeResult<T>, SchemaTransformError>
}

// ─────────────────────────────────────────────────────────────────────────────
// Service Tag
// ─────────────────────────────────────────────────────────────────────────────

/**
 * KORI Merge service tag.
 */
export class KoriMerge extends Context.Tag("kori/Merge")<
  KoriMerge,
  KoriMergeOps
>() {}

// ─────────────────────────────────────────────────────────────────────────────
// Implementation
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Implementation
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create KORI Merge operations.
 */
export const makeKoriMerge: Effect.Effect<KoriMergeOps> = Effect.sync(() => {
  const ops: KoriMergeOps = {
    merge: <T extends Record<string, unknown>>(
      target: Partial<T>,
      ...sources: ReadonlyArray<Partial<T>>
    ) =>
      Effect.sync(() => defu(target, ...sources) as T),

    mergeFn: <T extends Record<string, unknown>>(
      target: Partial<T>,
      defaults: Partial<T>
    ) =>
      Effect.sync(() => defuFn(target, defaults) as T),

    mergeArrayFn: <T extends Record<string, unknown>>(
      target: Partial<T>,
      defaults: Partial<T>
    ) =>
      Effect.sync(() => defuArrayFn(target, defaults) as T),

    createMerger:
      (merger: MergerFn) =>
      <T extends Record<string, unknown>>(
        target: Partial<T>,
        ...sources: ReadonlyArray<Partial<T>>
      ) =>
        Effect.sync(() => {
          const customDefu = createDefu(merger)
          return customDefu(target, ...sources) as T
        }),

    mergeTraits: <T extends Record<string, unknown>>(
      traitId: TraitId,
      target: Partial<T>,
      ...sources: ReadonlyArray<Partial<T>>
    ) =>
      pipe(
        Effect.sync(() => defu(target, ...sources) as T),
        Effect.map((merged): MergeResult<T> => ({
          merged,
          sourceTraitIds: [traitId],
          strategy: "default" as const,
        }))
        // Note: Schema validation would be added here using the trait registry
        // For now, we trust the input types
      ),

composeTrait: <T extends Record<string, unknown>>(
      traitIds: ReadonlyArray<TraitId>,
      data: ReadonlyArray<Partial<T>>,
      config: MergeConfig = { strategy: "default" }
    ) =>
      Effect.sync(() => {
        let merged: T

        switch (config.strategy) {
          case "fn":
            if (data.length >= 2) {
              merged = defuFn(data[0], data[1]) as T
              for (let i = 2; i < data.length; i++) {
                merged = defuFn(merged, data[i] as Partial<T>) as T
              }
            } else {
              merged = (data[0] ?? {}) as T
            }
            break

          case "arrayFn":
            if (data.length >= 2) {
              merged = defuArrayFn(data[0], data[1]) as T
              for (let i = 2; i < data.length; i++) {
                merged = defuArrayFn(merged, data[i] as Partial<T>) as T
              }
            } else {
              merged = (data[0] ?? {}) as T
            }
            break

          case "custom":
            if (config.customMerger) {
              const customDefu = createDefu(config.customMerger)
              // Reduce from right to left to match defu's leftmost priority
              merged = data.reduceRight<T>(
                (acc, curr) => customDefu(curr, acc) as unknown as T,
                {} as T
              )
            } else {
              merged = data.reduceRight<T>(
                (acc, curr) => defu(curr, acc) as unknown as T,
                {} as T
              )
            }
            break

          case "default":
          default:
            merged = data.reduceRight<T>(
              (acc, curr) => defu(curr, acc) as unknown as T,
              {} as T
            )
        }

        return {
          merged,
          sourceTraitIds: traitIds,
          strategy: config.strategy,
        }
      }),
  }

return {
          merged,
          sourceTraitIds: traitIds,
          strategy: config.strategy,
        }
      }),
  }

  return ops
})

/**
 * Default KORI Merge layer.
 */
export const KoriMergeLive = Layer.effect(KoriMerge, makeKoriMerge)

// ─────────────────────────────────────────────────────────────────────────────
// Utility Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a merger that sums numeric values.
 */
export const sumMerger: MergerFn = (obj, key, value) => {
  if (typeof obj[key] === "number" && typeof value === "number") {
    obj[key] = (obj[key] as number) + value
    return true
  }
  return false
}

/**
 * Create a merger that concatenates arrays.
 */
export const concatMerger: MergerFn = (obj, key, value) => {
  if (Array.isArray(obj[key]) && Array.isArray(value)) {
    obj[key] = [...(obj[key] as unknown[]), ...value]
    return true
  }
  return false
}

/**
 * Create a merger that takes the max of numeric values.
 */
export const maxMerger: MergerFn = (obj, key, value) => {
  if (typeof obj[key] === "number" && typeof value === "number") {
    obj[key] = Math.max(obj[key] as number, value)
    return true
  }
  return false
}

/**
 * Create a merger that takes the min of numeric values.
 */
export const minMerger: MergerFn = (obj, key, value) => {
  if (typeof obj[key] === "number" && typeof value === "number") {
    obj[key] = Math.min(obj[key] as number, value)
    return true
  }
  return false
}

/**
 * Compose multiple mergers into one.
 * First merger that returns true wins.
 */
export const composeMergers = (...mergers: MergerFn[]): MergerFn => {
  return (obj, key, value) => {
    for (const merger of mergers) {
      if (merger(obj, key, value)) {
        return true
      }
    }
    return false
  }
}

/**
 * Kori Storage Service
 *
 * Opaque wrapper around NATS KV that provides a clean, Kori-specific API.
 * All NATS machinery is hidden — consumers work with EntitySpecs and streams.
 *
 * Pattern: Facade over NatsKVService with domain-specific operations.
 *
 * @module kori/services/storage
 */

import { Effect, Context, Layer, Stream, Schema, Data } from 'effect'
import type { ParseResult } from 'effect'

import { NatsKVService, NatsKVError } from '@/lib/nats'
import {
  EntitySpec,
  type EntityTypeId,
  ENTITY_SPEC_BUCKET,
  SPEC_WATCH_PATTERN,
  specKey,
} from '../schemas/entity-spec'

// =============================================================================
// Kori-Specific Errors
// =============================================================================

/**
 * Base error for Kori storage operations.
 */
export class KoriStorageError extends Data.TaggedError('KoriStorageError')<{
  readonly message: string
  readonly cause?: unknown
}> {}

/**
 * Entity spec not found.
 */
export class KoriSpecNotFoundError extends Data.TaggedError('KoriSpecNotFoundError')<{
  readonly entityTypeId: string
}> {}

/**
 * Storage connection error.
 */
export class KoriConnectionError extends Data.TaggedError('KoriConnectionError')<{
  readonly message: string
  readonly cause?: unknown
}> {}

/**
 * Union of all Kori storage errors.
 */
export type KoriError = KoriStorageError | KoriSpecNotFoundError | KoriConnectionError

// =============================================================================
// Change Events
// =============================================================================

/**
 * Spec change event from watch stream.
 */
export interface SpecChangeEvent {
  readonly type: 'put' | 'delete'
  readonly entityTypeId: EntityTypeId
  readonly spec: EntitySpec | null
  readonly revision: number
}

// =============================================================================
// Service Shape
// =============================================================================

// =============================================================================
// Service Shape
// =============================================================================

/**
 * KoriStorageService shape — clean API for entity spec persistence.
 */
export interface KoriStorageServiceShape {
  /**
   * Get an EntitySpec by type ID.
   * Returns null if not found (no error thrown).
   */
  readonly getSpec: (
    entityTypeId: EntityTypeId
  ) => Effect.Effect<EntitySpec | null, KoriStorageError>

  /**
   * Get an EntitySpec, failing if not found.
   */
  readonly requireSpec: (
    entityTypeId: EntityTypeId
  ) => Effect.Effect<EntitySpec, KoriStorageError | KoriSpecNotFoundError>

  /**
   * Save an EntitySpec (create or update).
   */
  readonly saveSpec: (
    spec: EntitySpec
  ) => Effect.Effect<void, KoriStorageError>

  /**
   * Delete an EntitySpec.
   */
  readonly deleteSpec: (
    entityTypeId: EntityTypeId
  ) => Effect.Effect<void, KoriStorageError>

  /**
   * List all EntitySpec type IDs.
   */
  readonly listSpecIds: () => Effect.Effect<ReadonlyArray<string>, KoriStorageError>

  /**
   * Watch for spec changes.
   * Returns a stream of change events.
   */
  readonly watchSpecs: () => Stream.Stream<SpecChangeEvent, KoriStorageError>

  /**
   * Check if storage is connected and ready.
   */
  readonly isReady: () => Effect.Effect<boolean, never>
}

// =============================================================================
// Service Tag
// =============================================================================

/**
 * KoriStorageService tag for dependency injection.
 */
export class KoriStorageService extends Context.Tag('kori/KoriStorageService')<
  KoriStorageService,
  KoriStorageServiceShape
>() {}

// =============================================================================
// Error Mapping
// =============================================================================

// =============================================================================
// Error Mapping
// =============================================================================

/**
 * Map NATS errors to Kori errors.
 */
const mapNatsError = (error: NatsKVError | ParseResult.ParseError): KoriStorageError =>
  new KoriStorageError({
    message: error instanceof NatsKVError ? error.message : 'Schema parse error',
    cause: error,
  })

// =============================================================================
// Service Implementation
// =============================================================================

/**
 * Live implementation of KoriStorageService.
 * Internally uses NatsKVService but exposes only Kori-specific operations.
 */
export const KoriStorageServiceLive = Layer.effect(
  KoriStorageService,
  Effect.gen(function* () {
    const nats = yield* NatsKVService

    // Lazily initialize bucket
    let bucketPromise: Promise<unknown> | null = null
    const ensureBucket = Effect.gen(function* () {
      if (!bucketPromise) {
        bucketPromise = Effect.runPromise(
          nats.getOrCreateBucket(ENTITY_SPEC_BUCKET, {
            history: 10,
            maxAgeSeconds: 0,
          })
        )
      }
      return yield* Effect.promise(() => bucketPromise as Promise<unknown>)
    }).pipe(
      Effect.mapError((err) => new KoriStorageError({
        message: 'Failed to initialize storage bucket',
        cause: err,
      }))
    )

    const service: KoriStorageServiceShape = {
      getSpec: (entityTypeId) =>
        Effect.gen(function* () {
          const bucket = yield* ensureBucket
          return yield* nats.get(bucket as any, specKey(entityTypeId), EntitySpec)
        }).pipe(
          Effect.mapError(mapNatsError)
        ),

      requireSpec: (entityTypeId) =>
        Effect.gen(function* () {
          const spec = yield* service.getSpec(entityTypeId)
          if (!spec) {
            return yield* Effect.fail(new KoriSpecNotFoundError({ entityTypeId: entityTypeId as string }))
          }
          return spec
        }),

saveSpec: (spec) =>
        Effect.gen(function* () {
          const bucket = yield* ensureBucket
          yield* nats.put(bucket as any, specKey(spec.entityTypeId), spec, EntitySpec)
        }).pipe(
          Effect.mapError(mapNatsError)
        ),

      deleteSpec: (entityTypeId) =>
        Effect.gen(function* () {
          const bucket = yield* ensureBucket
          yield* nats.delete(bucket as any, specKey(entityTypeId))
        }).pipe(
          Effect.mapError(mapNatsError)
        ),

      listSpecIds: () =>
        Effect.gen(function* () {
          const bucket = yield* ensureBucket
          const keys = yield* nats.list(bucket as any, SPEC_WATCH_PATTERN)
          // Strip 'spec.' prefix from keys
          return keys.map((key) => key.replace(/^spec\./, ''))
        }).pipe(
          Effect.mapError(mapNatsError)
        ),

      watchSpecs: () =>
        Stream.unwrap(
          Effect.gen(function* () {
            const bucket = yield* ensureBucket
            return nats.watch(bucket as any, SPEC_WATCH_PATTERN, EntitySpec, {
              includeHistory: false,
            }).pipe(
              Stream.map((event): SpecChangeEvent => ({
                type: event.operation,
                entityTypeId: event.key.replace(/^spec\./, '') as EntityTypeId,
                spec: event.value,
                revision: event.revision,
              })),
              Stream.mapError(mapNatsError)
            )
          }).pipe(
            Effect.mapError(mapNatsError)
          )
        ),

      isReady: () =>
        Effect.gen(function* () {
          try {
            yield* ensureBucket
            return true
          } catch {
            return false
          }
        }).pipe(
          Effect.catchAll(() => Effect.succeed(false))
        ),
    }

    return service
  })
)

// =============================================================================
// Convenience Layers
// =============================================================================

/**
 * Full layer with NatsKVService dependency.
 */
export const KoriStorageServiceLayer = KoriStorageServiceLive

return service
  })
)

