const providers = new Map<ProviderId, CompletionProvider>()

/**
 * The provider registry singleton.
 */
export const providerRegistry: ProviderRegistry = {
  register: <T>(provider: CompletionProvider<T>) => {
    providers.set(provider.id, provider as CompletionProvider)
  },

  unregister: (id: ProviderId) => {
    providers.delete(id)
  },

  get: (id: ProviderId) => providers.get(id),

  list: () => Array.from(providers.values()),

  has: (id: ProviderId) => providers.has(id),
}

/**
 * Helper to create a branded ProviderId.
 */
export function createProviderId(id: string): ProviderId {
  return id as ProviderId
}

/**
   * Optional: Transform input before completion.
   * Useful for stripping prefixes, normalizing, etc.
   *
   * @param input - Raw input text
   * @returns Transformed input for completion
   */
  readonly transformInput?: (input: string) => string

  /**
   * Optional: Validate input before accepting.
   * Return false to prevent submission.
   *
   * @param input - Final input text
   * @returns Effect yielding validation result
   */
  readonly validate?: (input: string) => Effect.Effect<boolean>

  /**
   * Optional: Custom keyboard handler.
   * Return true to indicate the key was handled.
   *
   * @param event - Keyboard event
   * @returns Whether the event was handled
   */
  readonly onKeyDown?: (event: KeyboardEvent) => boolean
}

