export function MinibufferContent() {
  const mode = useAtomValue(modeAtom)
  const input = useAtomValue(inputAtom)
  const prompt = useAtomValue(promptAtom)
  const completions = useAtomValue(completionsAtom)
  const selectedIndex = useAtomValue(selectedIndexAtom)
  const providerId = useAtomValue(providerIdAtom)
  const whichKeyEntries = useAtomValue(whichKeyEntriesAtom)
  const whichKeyPrefix = useAtomValue(whichKeyPrefixAtom)

  const inputRef = useRef<HTMLInputElement>(null)

  // Inject CSS on mount
  useEffect(() => {
    injectStyles()
  }, [])

  // Focus input on mount and when mode changes to active
  useEffect(() => {
    if (mode !== "idle") {
      // Small delay to ensure DOM is ready
      requestAnimationFrame(() => {
        inputRef.current?.focus()
      })
    }
  }, [mode])

  // Fetch completions when input changes (command mode only)
  useEffect(() => {
    if (mode !== "command" || !providerId) return

    // Debounce would be nice, but keep it simple for now
    const fetchCompletions = async () => {
      const effect = getCompletions(providerId, input)
      const results = await Effect.runPromise(effect)
      ops.loadCompletions(results)
    }

    fetchCompletions()
  }, [mode, providerId, input])

  // Handle input change
  const handleInputChange = useCallback((value: string) => {
    ops.updateInput(value)
  }, [])

fetchCompletions()
  }, [mode, providerId, input])

  // Handle input change
  const handleInputChange = useCallback((value: string) => {
    ops.updateInput(value)
  }, [])

  // Handle item selection (click or Enter)
  const handleSelect = useCallback((value: string) => {
    const completion = completions.find(c => c.value === value)
    if (completion && providerId) {
      ops.selectCompletion(completion)
      // Execute the provider's onSelect handler (this is what was missing!)
      Effect.runPromise(executeSelection(providerId, completion))
    }
  }, [completions, providerId])

  // Handle selection change from cmdk (keyboard navigation)
  const handleValueChange = useCallback((value: string) => {
    const idx = completions.findIndex(c => c.value === value)
    if (idx !== -1 && idx !== selectedIndex) {
      ops.selectIndex(idx)
    }
  }, [completions, selectedIndex])

  // Keyboard handler — let Escape bubble to global handler
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    // Escape: let it bubble to close the drawer
    if (e.key === "Escape") {
      return
    }

    // y-or-n mode: handle y/n keys
    if (mode === "yOrN") {
      if (e.key === "y" || e.key === "Y") {
        e.preventDefault()
        ops.confirm()
      } else if (e.key === "n" || e.key === "N") {
        e.preventDefault()
        ops.deny()
      }
      return
    }

    // which-key mode: handle key selection
    if (mode === "whichKey") {
      const entry = whichKeyEntries.find(e => e.key === e.key.toLowerCase())
      if (entry) {
        e.preventDefault()
        ops.whichKeySelect(e.key)
      }
      return
    }
  }, [mode, whichKeyEntries])

// Group completions by category
  const groupedCompletions = useMemo(() => {
    return completions.reduce((acc, c) => {
      const cat = c.category ?? "Commands"
      if (!acc[cat]) acc[cat] = []
      acc[cat].push(c)
      return acc
    }, {} as Record<string, Completion[]>)
  }, [completions])

  // Get selected value for cmdk controlled state
  const selectedValue = completions[selectedIndex]?.value ?? ""

  // ─────────────────────────────────────────────────────────────
  // Render by mode
  // ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
  // Render by mode
  // ─────────────────────────────────────────────────────────────

  // y-or-n mode
  if (mode === "yOrN") {
    return (
      <div style={styles.root}>
        <div style={styles.inputWrapper}>
          <Terminal style={styles.promptIcon} />
          <span style={styles.promptText}>{prompt}</span>
        </div>
        <div style={styles.yOrNWrapper}>
          <button
            style={styles.yOrNButton}
            onClick={() => ops.confirm()}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = TOKENS.bg.itemSelected
              e.currentTarget.style.color = TOKENS.fg.primary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = "transparent"
              e.currentTarget.style.color = TOKENS.fg.secondary
            }}
          >
            <Check size={14} />
            <span>Yes</span>
            <kbd style={styles.kbd}>y</kbd>
          </button>
          <button
            style={styles.yOrNButton}
            onClick={() => ops.deny()}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = TOKENS.bg.itemSelected
              e.currentTarget.style.color = TOKENS.fg.primary
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = "transparent"
              e.currentTarget.style.color = TOKENS.fg.secondary
            }}
          >
            <X size={14} />
            <span>No</span>
            <kbd style={styles.kbd}>n</kbd>
          </button>
        </div>
      </div>
    )
  }

// which-key mode
  if (mode === "whichKey") {
    return (
      <div style={styles.root}>
        <div style={styles.inputWrapper}>
          <Terminal style={styles.promptIcon} />
          <span style={styles.promptText}>{whichKeyPrefix}</span>
        </div>
        <div style={styles.whichKeyGrid}>
          {whichKeyEntries.map((entry) => (
            <div
              key={entry.key}
              style={styles.whichKeyEntry}
              onClick={() => ops.whichKeySelect(entry.key)}
              onMouseEnter={(e) => {
                e.currentTarget.style.backgroundColor = TOKENS.bg.itemSelected
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = "transparent"
              }}
            >
              <span style={styles.whichKeyKey}>{entry.key}</span>
              <span style={styles.whichKeyLabel}>{entry.label}</span>
              {entry.isPrefix && (
                <span style={styles.whichKeyPrefix}>+</span>
              )}
            </div>
          ))}
        </div>
      </div>
    )
  }

  // prompt mode (simple text input, no completions)
  if (mode === "prompt") {
    return (
      <div style={styles.root} onKeyDown={handleKeyDown}>
        <div style={styles.inputWrapper}>
          <Terminal style={styles.promptIcon} />
          <span style={styles.promptText}>{prompt}</span>
          <input
            ref={inputRef}
            value={input}
            onChange={(e) => handleInputChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                ops.submit()
              }
            }}
            style={styles.input}
            placeholder="Type here..."
            autoFocus
          />
        </div>
      </div>
    )
  }

// command mode (M-x style with completions)
  return (
    <CommandPrimitive
      style={styles.root}
      value={selectedValue}
      onValueChange={handleValueChange}
      onKeyDown={handleKeyDown}
      shouldFilter={false} // We do our own filtering via FlexSearch
      loop
    >
      {/* Input */}
      <div style={styles.inputWrapper}>
        <Terminal style={styles.promptIcon} />
        <span style={styles.promptText}>{prompt}</span>
        <CommandPrimitive.Input
          ref={inputRef}
          value={input}
          onValueChange={handleInputChange}
          style={styles.input}
          placeholder="Type to search..."
        />
      </div>

      {/* Completion List */}
      <CommandPrimitive.List style={styles.list}>
        <CommandPrimitive.Empty style={styles.empty}>
          No commands found
        </CommandPrimitive.Empty>

        {Object.entries(groupedCompletions).map(([category, items], groupIdx) => (
          <CommandPrimitive.Group key={category} value={category}>
            <div
              style={{
                ...styles.groupHeading,
                ...(groupIdx === 0 ? styles.groupHeadingFirst : {}),
              }}
            >
              {category}
            </div>
            {items.map((completion) => (
              <CommandPrimitive.Item
                key={completion.value}
                value={completion.value}
                onSelect={handleSelect}
                style={styles.item}
              >
                <span style={styles.itemLabel}>{completion.label}</span>
                {completion.description && (
                  <span style={styles.itemDescription} title={completion.description}>
                    {completion.description}
                  </span>
                )}
              </CommandPrimitive.Item>
            ))}
          </CommandPrimitive.Group>
        ))}
      </CommandPrimitive.List>
    </CommandPrimitive>
  )
}

export default MinibufferContent

/**
 * Minibuffer v2 — React Context
 *
 * Global singleton actor using createActorContext.
 * Components use useMinibufferActor() to send events,
 * useMinibufferSelector() to subscribe to state slices.
 *
 * @module
 */

import { createActorContext } from "@xstate/react"
import { minibufferMachine } from "./machine"
import type { MinibufferSnapshot, Completion } from "./machine"

// ─────────────────────────────────────────────────────────────
// Actor Context (Singleton)
// ─────────────────────────────────────────────────────────────

/**
 * Global minibuffer actor context.
 *
 * Wrap your app with <MinibufferProvider> to enable minibuffer functionality.
 * Use hooks below to interact with the minibuffer.
 */
export const MinibufferReactContext = createActorContext(minibufferMachine)

/**
 * Provider component. Place at app root.
 *
 * @example
 * ```tsx
 * function App() {
 *   return (
 *     <MinibufferProvider>
 *       <YourApp />
 *     </MinibufferProvider>
 *   )
 * }
 * ```
 */
export const MinibufferProvider = MinibufferReactContext.Provider

// ─────────────────────────────────────────────────────────────
// Hooks
// ─────────────────────────────────────────────────────────────

/**
 * Get the minibuffer actor reference.
 * Use this to send events to the minibuffer.
 *
 * @example
 * ```tsx
 * function CommandPaletteTrigger() {
 *   const actor = useMinibufferActor()
 *
 *   const openCommandPalette = () => {
 *     actor.send({
 *       type: 'OPEN_COMMAND',
 *       providerId: COMMAND_PROVIDER_ID,
 *       prompt: 'M-x '
 *     })
 *   }
 *
 *   return <button onClick={openCommandPalette}>M-x</button>
 * }
 * ```
 */
export function useMinibufferActor() {
  return MinibufferReactContext.useActorRef()
}

/**
 * Subscribe to a slice of minibuffer state.
 * Only re-renders when selected value changes.
 *
 * @example
 * ```tsx
 * function CompletionsList() {
 *   const completions = useMinibufferSelector(s => s.context.completions)
 *   const selectedIndex = useMinibufferSelector(s => s.context.selectedIndex)
 *
 *   return (
 *     <ul>
 *       {completions.map((c, i) => (
 *         <li key={c.value} data-selected={i === selectedIndex}>
 *           {c.label}
 *         </li>
 *       ))}
 *     </ul>
 *   )
 * }
 * ```
 */
export function useMinibufferSelector<T>(
  selector: (snapshot: MinibufferSnapshot) => T,
  compare?: (a: T, b: T) => boolean
) {
  return MinibufferReactContext.useSelector(selector, compare)
}

/**
 * Get both actor reference and full snapshot.
 * Use sparingly — prefer useMinibufferSelector for performance.
 */
export function useMinibuffer() {
  const actorRef = MinibufferReactContext.useActorRef()
  const snapshot = MinibufferReactContext.useSelector((s) => s)
  return [snapshot, actorRef.send, actorRef] as const
}

