/**
 * Minibuffer v2 — Provider Registry
 *
 * Completion providers for command mode.
 * Providers supply completions based on input query.
 *
 * @module
 */

import { Effect } from "effect"
import type { ProviderId, Completion } from "./machine"
import type { LucideIcon } from "lucide-react"

// ============================================================================
// TYPES
// ============================================================================

/**
 * Completion provider interface.
 * Providers supply completions for a given query.
 */
export interface CompletionProvider<T = unknown> {
  readonly id: ProviderId
  readonly label: string
  readonly icon?: LucideIcon
  readonly placeholder?: string

  /**
   * Generate completions for query.
   * Returns Effect that resolves to array of completions.
   */
  complete: (query: string) => Effect.Effect<readonly Completion[], unknown, unknown>

  /**
   * Called when user selects a completion.
   */
  onSelect?: (completion: Completion) => Effect.Effect<void, unknown, unknown>

  /**
   * Transform input before passing to complete().
   * E.g., strip "M-x " prefix.
   */
  transformInput?: (input: string) => string
}

/**
 * Provider registry interface.
 */
export interface ProviderRegistry {
  register: (provider: CompletionProvider) => void
  unregister: (id: ProviderId) => void
  get: (id: ProviderId) => CompletionProvider | undefined
  getAll: () => ReadonlyArray<CompletionProvider>
}

// ============================================================================
// FACTORY
// ============================================================================

/**
 * Create a branded ProviderId from a string.
 */
export function createProviderId(id: string): ProviderId {
  return id as ProviderId
}

/**
 * Well-known provider ID for the command palette (M-x).
 */
export const COMMAND_PROVIDER_ID = createProviderId("commands")

// ============================================================================
// REGISTRY SINGLETON
// ============================================================================

const providers = new Map<ProviderId, CompletionProvider>()

// ============================================================================
// REGISTRY SINGLETON
// ============================================================================

const providers = new Map<ProviderId, CompletionProvider>()

/**
 * Global provider registry.
 * Providers register here; minibuffer looks them up by ID.
 */
export const providerRegistry: ProviderRegistry = {
  register(provider: CompletionProvider): void {
    providers.set(provider.id, provider)
  },

  unregister(id: ProviderId): void {
    providers.delete(id)
  },

  get(id: ProviderId): CompletionProvider | undefined {
    return providers.get(id)
  },

  getAll(): ReadonlyArray<CompletionProvider> {
    return Array.from(providers.values())
  },
}

/**
 * Get completions from a provider.
 * Handles input transformation and error recovery.
 */
export const getCompletions = (
  providerId: ProviderId,
  query: string
): Effect.Effect<readonly Completion[], never, never> =>
  Effect.gen(function* () {
    const provider = providerRegistry.get(providerId)
    if (!provider) {
      yield* Effect.logWarning(`Provider not found: ${providerId}`)
      return []
    }

    const transformedQuery = provider.transformInput
      ? provider.transformInput(query)
      : query

    const completions = yield* provider.complete(transformedQuery).pipe(
      Effect.catchAll((error) => {
        Effect.logWarning(`Provider ${providerId} failed: ${error}`)
        return Effect.succeed([] as const)
      })
    )

    return completions
  })

/**
 * Execute provider's onSelect handler.
 */
export const executeSelection = (
  providerId: ProviderId,
  completion: Completion
): Effect.Effect<void, never, never> =>
  Effect.gen(function* () {
    const provider = providerRegistry.get(providerId)
    if (!provider?.onSelect) return

    yield* provider.onSelect(completion).pipe(
      Effect.catchAll((error) => {
        Effect.logWarning(`Provider ${providerId} onSelect failed: ${error}`)
        return Effect.void
      })
    )
  })

// React hook
export { useMotionBlur } from './useMotionBlur'
export type { UseMotionBlurOptions } from './useMotionBlur'

/**
 * Motion Tracker
 *
 * Tracks drag velocity for direction-aware motion blur.
 * Uses exponential moving average (EMA) for smooth velocity.
 *
 * @pattern Pure functions + mutable state tracker
 * @module
 */

import type {
  Vector2D,
  VelocityState,
  MotionBlurConfig,
  MotionBlurStyle,
  MotionTracker,
} from './types'

// =============================================================================
// Constants
// =============================================================================

const DEFAULT_CONFIG: Required<MotionBlurConfig> = {
  intensity: 0.08,
  maxBlur: 6,
  smoothingFactor: 0.3,
  threshold: 2,
  enableStretch: true,
  maxStretch: 1.03,
}

const INITIAL_STATE: VelocityState = {
  velocity: { x: 0, y: 0 },
  smoothedVelocity: { x: 0, y: 0 },
  lastPosition: { x: 0, y: 0 },
  lastTimestamp: 0,
  isDragging: false,
}

// =============================================================================
// Vector Math Utilities
// =============================================================================

/**
 * Calculate vector magnitude
 */
export function vectorMagnitude(v: Vector2D): number {
  return Math.sqrt(v.x ** 2 + v.y ** 2)
}

/**
 * Calculate vector angle in radians
 */
export function vectorAngle(v: Vector2D): number {
  return Math.atan2(v.y, v.x)
}

/**
 * Normalize vector to unit length
 */
export function normalizeVector(v: Vector2D): Vector2D {
  const mag = vectorMagnitude(v)
  if (mag === 0) return { x: 0, y: 0 }
  return { x: v.x / mag, y: v.y / mag }
}

/**
 * Exponential moving average for smoothing
 */
export function ema(current: number, previous: number, factor: number): number {
  return factor * current + (1 - factor) * previous
}

// =============================================================================
// Motion Blur Style Computation
// =============================================================================

// =============================================================================
// Motion Blur Style Computation
// =============================================================================

/**
 * Compute motion blur CSS style from velocity state
 */
export function computeMotionBlurStyle(
  state: VelocityState,
  config: Required<MotionBlurConfig>
): MotionBlurStyle {
  const velocity = state.smoothedVelocity
  const magnitude = vectorMagnitude(velocity)
  const angle = vectorAngle(velocity)

  // Check if velocity exceeds threshold
  const isActive = state.isDragging && magnitude > config.threshold

  if (!isActive) {
    return {
      filter: undefined,
      transform: undefined,
      transition: 'filter 0.15s ease-out, transform 0.15s ease-out',
      isActive: false,
      blurAmount: 0,
      velocityMagnitude: magnitude,
      velocityAngle: angle,
    }
  }

  // Calculate blur amount (clamped)
  const blurAmount = Math.min(magnitude * config.intensity, config.maxBlur)

  // Calculate directional stretch
  let stretchTransform: string | undefined = undefined
  if (config.enableStretch && magnitude > config.threshold * 2) {
    // Stretch in direction of motion
    const stretchFactor = Math.min(
      1 + (magnitude * 0.001),
      config.maxStretch
    )
    const angleDeg = (angle * 180) / Math.PI

    // Apply directional scale via rotation → scale → rotation back
    // This creates a "smear" effect in the direction of motion
    stretchTransform = [
      `rotate(${angleDeg}deg)`,
      `scaleX(${stretchFactor})`,
      `rotate(${-angleDeg}deg)`,
    ].join(' ')
  }

  return {
    filter: blurAmount > 0.5 ? `blur(${blurAmount.toFixed(1)}px)` : undefined,
    transform: stretchTransform,
    transition: 'none', // Disable transition during active motion
    isActive: true,
    blurAmount,
    velocityMagnitude: magnitude,
    velocityAngle: angle,
  }
}

// =============================================================================
// Motion Tracker Factory
// =============================================================================

// =============================================================================
// Motion Tracker Factory
// =============================================================================

/**
 * Create a motion tracker instance
 *
 * @example
 * ```ts
 * const tracker = createMotionTracker()
 *
 * // On drag start
 * tracker.startTracking(e.clientX, e.clientY)
 *
 * // On drag move
 * tracker.updatePosition(e.clientX, e.clientY)
 * const style = tracker.getBlurStyle()
 *
 * // On drag end
 * tracker.stopTracking()
 * ```
 */
export function createMotionTracker(): MotionTracker {
  let state: VelocityState = { ...INITIAL_STATE }

  const updatePosition = (x: number, y: number): void => {
    const now = performance.now()
    const dt = now - state.lastTimestamp

    // Avoid division by zero and skip if too fast (< 1ms)
    if (dt < 1) return

    // Calculate instantaneous velocity
    const velocity: Vector2D = {
      x: (x - state.lastPosition.x) / (dt / 16.67), // Normalize to ~60fps
      y: (y - state.lastPosition.y) / (dt / 16.67),
    }

    // Apply EMA smoothing
    const smoothedVelocity: Vector2D = {
      x: ema(velocity.x, state.smoothedVelocity.x, DEFAULT_CONFIG.smoothingFactor),
      y: ema(velocity.y, state.smoothedVelocity.y, DEFAULT_CONFIG.smoothingFactor),
    }

    state = {
      ...state,
      velocity,
      smoothedVelocity,
      lastPosition: { x, y },
      lastTimestamp: now,
    }
  }

  const startTracking = (x: number, y: number): void => {
    state = {
      velocity: { x: 0, y: 0 },
      smoothedVelocity: { x: 0, y: 0 },
      lastPosition: { x, y },
      lastTimestamp: performance.now(),
      isDragging: true,
    }
  }

const stopTracking = (): void => {
    state = {
      ...state,
      isDragging: false,
      velocity: { x: 0, y: 0 },
      smoothedVelocity: { x: 0, y: 0 },
    }
  }

  const getState = (): VelocityState => ({ ...state })

  const getBlurStyle = (config?: Partial<MotionBlurConfig>): MotionBlurStyle => {
    const mergedConfig = { ...DEFAULT_CONFIG, ...config }
    return computeMotionBlurStyle(state, mergedConfig)
  }

  const reset = (): void => {
    state = { ...INITIAL_STATE }
  }

  return {
    updatePosition,
    startTracking,
    stopTracking,
    getState,
    getBlurStyle,
    reset,
  }
}

// =============================================================================
// Singleton Tracker Registry
// =============================================================================

const trackerRegistry = new Map<string, MotionTracker>()

/**
 * Get or create a motion tracker by ID
 * Useful for tracking multiple draggable elements
 */
export function getMotionTracker(id: string): MotionTracker {
  let tracker = trackerRegistry.get(id)
  if (!tracker) {
    tracker = createMotionTracker()
    trackerRegistry.set(id, tracker)
  }
  return tracker
}

/**
 * Remove a motion tracker by ID
 */
export function removeMotionTracker(id: string): void {
  trackerRegistry.delete(id)
}

/**
 * Clear all motion trackers
 */
export function clearMotionTrackers(): void {
  trackerRegistry.clear()
}

/**
 * Motion Blur Types
 *
 * Schema-based types for direction-aware motion blur system.
 * Tracks velocity vectors for blur intensity and direction.
 *
 * @pattern Effect Schema
 * @module
 */

import { Schema } from 'effect'

// =============================================================================
// Vector Types
// =============================================================================

export const Vector2D = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
})
export type Vector2D = typeof Vector2D.Type

// =============================================================================
// Velocity State
// =============================================================================

export const VelocityState = Schema.Struct({
  /** Current velocity vector (px/frame) */
  velocity: Vector2D,
  /** Smoothed velocity (EMA) for stable blur */
  smoothedVelocity: Vector2D,
  /** Last position for delta calculation */
  lastPosition: Vector2D,
  /** Timestamp of last update */
  lastTimestamp: Schema.Number,
  /** Whether actively dragging */
  isDragging: Schema.Boolean,
})
export type VelocityState = typeof VelocityState.Type

// =============================================================================
// Motion Blur Configuration
// =============================================================================

export const MotionBlurConfig = Schema.Struct({
  /** Blur intensity multiplier (default: 0.08) */
  intensity: Schema.optionalWith(Schema.Number, { default: () => 0.08 }),
  /** Maximum blur in pixels (default: 6) */
  maxBlur: Schema.optionalWith(Schema.Number, { default: () => 6 }),
  /** Velocity smoothing factor 0-1 (default: 0.3, lower = smoother) */
  smoothingFactor: Schema.optionalWith(Schema.Number, { default: () => 0.3 }),
  /** Minimum velocity threshold to apply blur (default: 2) */
  threshold: Schema.optionalWith(Schema.Number, { default: () => 2 }),
  /** Enable directional stretch effect (default: true) */
  enableStretch: Schema.optionalWith(Schema.Boolean, { default: () => true }),
  /** Maximum stretch factor (default: 1.03) */
  maxStretch: Schema.optionalWith(Schema.Number, { default: () => 1.03 }),
})
export type MotionBlurConfig = typeof MotionBlurConfig.Type

// =============================================================================
// Motion Blur Style Output
// =============================================================================

export interface MotionBlurStyle {
  /** CSS filter property (blur) */
  filter: string | undefined
  /** CSS transform for directional stretch */
  transform: string | undefined
  /** CSS transition (disabled during motion) */
  transition: string | undefined
  /** Whether blur is active */
  isActive: boolean
  /** Blur amount in pixels */
  blurAmount: number
  /** Velocity magnitude */
  velocityMagnitude: number
  /** Velocity angle in radians */
  velocityAngle: number
}

// =============================================================================
// Motion Tracker Interface
// =============================================================================

export interface MotionTracker {
  /** Update position and recalculate velocity */
  updatePosition: (x: number, y: number) => void
  /** Start tracking (on drag start) */
  startTracking: (x: number, y: number) => void
  /** Stop tracking (on drag end) */
  stopTracking: () => void
  /** Get current velocity state */
  getState: () => VelocityState
  /** Get computed motion blur style */
  getBlurStyle: (config?: Partial<MotionBlurConfig>) => MotionBlurStyle
  /** Reset state */
  reset: () => void
}

// =============================================================================
// Hook Return Type
// =============================================================================

export interface UseMotionBlurReturn {
  /** Motion blur CSS styles to spread on element */
  style: MotionBlurStyle
  /** Start tracking motion */
  startTracking: (x: number, y: number) => void
  /** Update position during drag */
  updatePosition: (x: number, y: number) => void
  /** Stop tracking motion */
  stopTracking: () => void
  /** Current velocity state */
  velocityState: VelocityState
  /** Whether currently tracking */
  isTracking: boolean
}

/**
 * useMotionBlur Hook
 *
 * React hook for consuming direction-aware motion blur.
 * Integrates with pointer events for velocity tracking.
 *
 * @pattern React hook + motion tracker
 * @module
 */

import { useRef, useState, useCallback, useEffect } from 'react'
import type {
  UseMotionBlurReturn,
  VelocityState,
  MotionBlurConfig,
  MotionBlurStyle,
} from './types'
import {
  createMotionTracker,
  type MotionTracker,
} from './motion-tracker'

// =============================================================================
// Default Style (no blur)
// =============================================================================

const NO_BLUR_STYLE: MotionBlurStyle = {
  filter: undefined,
  transform: undefined,
  transition: 'filter 0.15s ease-out, transform 0.15s ease-out',
  isActive: false,
  blurAmount: 0,
  velocityMagnitude: 0,
  velocityAngle: 0,
}

const INITIAL_VELOCITY_STATE: VelocityState = {
  velocity: { x: 0, y: 0 },
  smoothedVelocity: { x: 0, y: 0 },
  lastPosition: { x: 0, y: 0 },
  lastTimestamp: 0,
  isDragging: false,
}

// =============================================================================
// Hook
// =============================================================================

export interface UseMotionBlurOptions {
  /** Motion blur configuration */
  config?: Partial<MotionBlurConfig>
  /** Whether to track motion (disable for performance) */
  enabled?: boolean
}

// =============================================================================
// Hook
// =============================================================================

export interface UseMotionBlurOptions {
  /** Motion blur configuration */
  config?: Partial<MotionBlurConfig>
  /** Whether to track motion (disable for performance) */
  enabled?: boolean
}

/**
 * Hook for direction-aware motion blur
 *
 * @example
 * ```tsx
 * function DraggableCard({ id }) {
 *   const { style, startTracking, updatePosition, stopTracking } = useMotionBlur()
 *
 *   const handleDragStart = (e) => {
 *     startTracking(e.clientX, e.clientY)
 *   }
 *
 *   const handleDrag = (e) => {
 *     updatePosition(e.clientX, e.clientY)
 *   }
 *
 *   const handleDragEnd = () => {
 *     stopTracking()
 *   }
 *
 *   return (
 *     <div
 *       style={{
 *         filter: style.filter,
 *         transform: style.transform,
 *         transition: style.transition,
 *       }}
 *       onPointerDown={handleDragStart}
 *       onPointerMove={handleDrag}
 *       onPointerUp={handleDragEnd}
 *     >
 *       Content
 *     </div>
 *   )
 * }
 * ```
 */
export function useMotionBlur(options: UseMotionBlurOptions = {}): UseMotionBlurReturn {
  const { config, enabled = true } = options

  // Create stable tracker reference
  const trackerRef = useRef<MotionTracker | null>(null)
  if (!trackerRef.current) {
    trackerRef.current = createMotionTracker()
  }

  // State for React re-renders
  const [style, setStyle] = useState<MotionBlurStyle>(NO_BLUR_STYLE)
  const [velocityState, setVelocityState] = useState<VelocityState>(INITIAL_VELOCITY_STATE)
  const [isTracking, setIsTracking] = useState(false)

  // Animation frame ref for smooth updates
  const rafRef = useRef<number | null>(null)

  // Update loop during tracking
  const updateLoop = useCallback(() => {
    const tracker = trackerRef.current
    if (!tracker) return

// Update loop during tracking
  const updateLoop = useCallback(() => {
    const tracker = trackerRef.current
    if (!tracker) return

    const state = tracker.getState()
    const blurStyle = tracker.getBlurStyle(config)

    setVelocityState(state)
    setStyle(blurStyle)

    if (state.isDragging) {
      rafRef.current = requestAnimationFrame(updateLoop)
    }
  }, [config])

  // Start tracking
  const startTracking = useCallback((x: number, y: number) => {
    if (!enabled) return

    const tracker = trackerRef.current
    if (!tracker) return

    tracker.startTracking(x, y)
    setIsTracking(true)

    // Start update loop
    rafRef.current = requestAnimationFrame(updateLoop)
  }, [enabled, updateLoop])

  // Update position
  const updatePosition = useCallback((x: number, y: number) => {
    if (!enabled) return

    const tracker = trackerRef.current
    if (!tracker) return

    tracker.updatePosition(x, y)
  }, [enabled])

  // Stop tracking
  const stopTracking = useCallback(() => {
    const tracker = trackerRef.current
    if (!tracker) return

    tracker.stopTracking()
    setIsTracking(false)

    // Cancel animation frame
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current)
      rafRef.current = null
    }

    // Final state update (blur off)
    setVelocityState(tracker.getState())
    setStyle(tracker.getBlurStyle(config))
  }, [config])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [])

  return {
    style,
    startTracking,
    updatePosition,
    stopTracking,
    velocityState,
    isTracking,
  }
}

export default useMotionBlur

/**
 * NatsKVService
 *
 * Effect.Service wrapping NATS JetStream KV for reactive key-value storage.
 * Provides get/put/delete/watch/list operations with Schema-based encoding.
 *
 * NOTE: This is a general-purpose NATS KV wrapper. Domain-specific services
 * (e.g., DocumentRegistryService) should import and use this service.
 *
 * @module nats/NatsKVService
 */

import { Effect, Layer, Context, Stream, Schema, ParseResult } from 'effect';
// Use nats.ws for browser-compatible WebSocket transport
// The 'nats' package uses Node.js APIs (dns, fs) that don't work in browsers
import {
  connect,
  type NatsConnection,
  type KV,
  type KvWatchOptions,
} from 'nats.ws';

// =============================================================================
// Types
// =============================================================================

/**
 * KV entry with typed value after Schema decode.
 */
export interface TypedKvEntry<T> {
  readonly key: string;
  readonly value: T;
  readonly revision: number;
  readonly created: Date;
  readonly operation: 'PUT' | 'DEL' | 'PURGE';
}

/**
 * KV watch event — emitted when a key changes.
 */
export interface KvWatchEvent<T> {
  readonly key: string;
  readonly value: T | null; // null on delete
  readonly revision: number;
  readonly operation: 'PUT' | 'DEL' | 'PURGE';
}

/**
 * Configuration for NATS connection.
 */
export interface NatsConfig {
  readonly servers: string | string[];
  readonly name?: string;
}

// =============================================================================
// Errors
// =============================================================================

export class NatsConnectionError extends Error {
  readonly _tag = 'NatsConnectionError';
  constructor(message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'NatsConnectionError';
  }
}

export class NatsKVError extends Error {
  readonly _tag = 'NatsKVError';
  constructor(message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'NatsKVError';
  }
}

export class NatsKVError extends Error {
  readonly _tag = 'NatsKVError';
  constructor(message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'NatsKVError';
  }
}

export class NatsKVNotFoundError extends Error {
  readonly _tag = 'NatsKVNotFoundError';
  constructor(readonly bucket: string, readonly key: string) {
    super(`Key not found: ${bucket}/${key}`);
    this.name = 'NatsKVNotFoundError';
  }
}

// =============================================================================
// Configuration Tag
// =============================================================================

export class NatsConfigTag extends Context.Tag('tmnl/nats/NatsConfig')<
  NatsConfigTag,
  NatsConfig
>() {
  static readonly Default = Layer.succeed(this, {
    // Use WebSocket protocol for browser compatibility (nats.ws)
    // Connect to port 9222 where NATS WebSocket is configured
    // (see docker/nats/nats-server.conf)
    servers: 'ws://localhost:9222',
    name: 'tmnl-client',
  });

  static readonly Custom = (config: NatsConfig) => Layer.succeed(this, config);
}

// =============================================================================
// Service Interface
// =============================================================================

export interface NatsKVServiceShape {
  /**
   * Get the underlying NATS connection.
   * Use for advanced operations not covered by this service.
   */
  readonly getConnection: () => Effect.Effect<
    NatsConnection,
    NatsConnectionError
  >;

  /**
   * Get or create a KV bucket.
   * Creates the bucket if it doesn't exist.
   */
  readonly getOrCreateBucket: (
    name: string,
    options?: { history?: number; ttl?: number }
  ) => Effect.Effect<KV, NatsKVError>;

/**
   * Get a value from a bucket with Schema decode.
   * Returns null if key doesn't exist.
   */
  readonly get: <A, I>(
    bucket: KV,
    key: string,
    schema: Schema.Schema<A, I>
  ) => Effect.Effect<A | null, NatsKVError | ParseResult.ParseError>;

  /**
   * Put a value into a bucket with Schema encode.
   * Returns the revision number.
   */
  readonly put: <A, I>(
    bucket: KV,
    key: string,
    value: A,
    schema: Schema.Schema<A, I>
  ) => Effect.Effect<number, NatsKVError | ParseResult.ParseError>;

  /**
   * Delete a key from a bucket.
   */
  readonly delete: (
    bucket: KV,
    key: string
  ) => Effect.Effect<void, NatsKVError>;

  /**
   * Purge a key (remove all history).
   */
  readonly purge: (bucket: KV, key: string) => Effect.Effect<void, NatsKVError>;

  /**
   * Watch for changes on keys matching a pattern.
   * Returns a Stream that emits KvWatchEvent for each change.
   *
   * @param bucket - The KV bucket to watch
   * @param keyPattern - Key pattern to watch (supports wildcards: *, >)
   * @param schema - Schema to decode values
   * @param options - Watch options (includeHistory, etc.)
   */
  readonly watch: <A, I>(
    bucket: KV,
    keyPattern: string,
    schema: Schema.Schema<A, I>,
    options?: KvWatchOptions
  ) => Stream.Stream<KvWatchEvent<A>, NatsKVError | ParseResult.ParseError>;

  /**
   * List all keys in a bucket.
   */
  readonly keys: (bucket: KV) => Effect.Effect<readonly string[], NatsKVError>;

/**
   * List all keys in a bucket.
   */
  readonly keys: (bucket: KV) => Effect.Effect<readonly string[], NatsKVError>;

  /**
   * List all entries in a bucket with Schema decode.
   */
  readonly list: <A, I>(
    bucket: KV,
    schema: Schema.Schema<A, I>
  ) => Effect.Effect<
    readonly TypedKvEntry<A>[],
    NatsKVError | ParseResult.ParseError
  >;

  /**
   * Close the NATS connection.
   */
  readonly close: () => Effect.Effect<void, never>;
}

// =============================================================================
// Service Implementation
// =============================================================================

export class NatsKVService extends Effect.Service<NatsKVService>()(
  'tmnl/nats/NatsKVService',
  {
    // Use scoped effect for proper resource management
    // Connection is acquired once and reused across all operations
    scoped: Effect.gen(function* () {
      const config = yield* NatsConfigTag;

      console.log('[NatsKVService] Acquiring NATS connection...', {
        servers: config.servers,
        name: config.name,
      });

      // Acquire connection with proper cleanup
      const nc = yield* Effect.acquireRelease(
        Effect.tryPromise({
          try: async () => {
            console.log('[NatsKVService] Connecting to NATS...');
            const conn = await connect({
              servers: config.servers,
              name: config.name,
            });
            console.log('[NatsKVService] NATS connection established!');
            return conn;
          },
          catch: (err) => {
            console.error('[NatsKVService] NATS connection FAILED:', err);
            return new NatsConnectionError(
              `Failed to connect to NATS: ${err}`,
              err
            );
          },
        }),
        (conn) =>
          Effect.sync(() => {
            console.log('[NatsKVService] Releasing NATS connection...');
            conn.drain().catch(() => {});
            conn.close().catch(() => {});
          })
      );

      const getConnection = () => Effect.succeed(nc);

const getConnection = () => Effect.succeed(nc);

      const getOrCreateBucket = (
        name: string,
        options?: { history?: number; ttl?: number }
      ): Effect.Effect<KV, NatsKVError> =>
        Effect.gen(function* () {
          // Get JetStream client (connection already established)
          const js = nc.jetstream();

          return yield* Effect.tryPromise({
            try: async () => {
              // js.views.kv() creates bucket if it doesn't exist when opts provided
              return await js.views.kv(name, {
                history: options?.history ?? 5,
                ttl: options?.ttl,
              });
            },
            catch: (err) =>
              new NatsKVError(
                `Failed to get/create bucket '${name}': ${err}`,
                err
              ),
          });
        });

      const get = <A, I>(
        bucket: KV,
        key: string,
        schema: Schema.Schema<A, I>
      ): Effect.Effect<A | null, NatsKVError | ParseResult.ParseError> =>
        Effect.gen(function* () {
          const entry = yield* Effect.tryPromise({
            try: async () => {
              try {
                return await bucket.get(key);
              } catch {
                return null;
              }
            },
            catch: (err) =>
              new NatsKVError(`Failed to get key '${key}': ${err}`, err),
          });

          if (
            !entry ||
            entry.operation === 'DEL' ||
            entry.operation === 'PURGE'
          ) {
            return null;
          }

          const jsonStr = new TextDecoder().decode(entry.value);
          const parsed = JSON.parse(jsonStr);
          return yield* Schema.decodeUnknown(schema)(parsed);
        });

const jsonStr = new TextDecoder().decode(entry.value);
          const parsed = JSON.parse(jsonStr);
          return yield* Schema.decodeUnknown(schema)(parsed);
        });

      const put = <A, I>(
        bucket: KV,
        key: string,
        value: A,
        schema: Schema.Schema<A, I>
      ): Effect.Effect<number, NatsKVError | ParseResult.ParseError> =>
        Effect.gen(function* () {
          const encoded = yield* Schema.encode(schema)(value);
          const jsonStr = JSON.stringify(encoded);
          const bytes = new TextEncoder().encode(jsonStr);

          const revision = yield* Effect.tryPromise({
            try: () => bucket.put(key, bytes),
            catch: (err) =>
              new NatsKVError(`Failed to put key '${key}': ${err}`, err),
          });

          return revision;
        });

      const del = (bucket: KV, key: string): Effect.Effect<void, NatsKVError> =>
        Effect.tryPromise({
          try: () => bucket.delete(key),
          catch: (err) =>
            new NatsKVError(`Failed to delete key '${key}': ${err}`, err),
        });

      const purge = (
        bucket: KV,
        key: string
      ): Effect.Effect<void, NatsKVError> =>
        Effect.tryPromise({
          try: () => bucket.purge(key),
          catch: (err) =>
            new NatsKVError(`Failed to purge key '${key}': ${err}`, err),
        });

      const watch = <A, I>(
        bucket: KV,
        keyPattern: string,
        schema: Schema.Schema<A, I>,
        options?: KvWatchOptions
      ): Stream.Stream<KvWatchEvent<A>, NatsKVError | ParseResult.ParseError> =>
        Stream.async<KvWatchEvent<A>, NatsKVError | ParseResult.ParseError>(
          (emit) => {
            let cancelled = false;

const run = async () => {
              try {
                const watcher = await bucket.watch({
                  key: keyPattern,
                  ...options,
                });

                for await (const entry of watcher) {
                  if (cancelled) break;

                  try {
                    let value: A | null = null;
                    if (entry.operation === 'PUT' && entry.value) {
                      const jsonStr = new TextDecoder().decode(entry.value);
                      const parsed = JSON.parse(jsonStr);
                      const decoded = await Effect.runPromise(
                        Schema.decodeUnknown(schema)(parsed)
                      );
                      value = decoded;
                    }

                    emit.single({
                      key: entry.key,
                      value,
                      revision: entry.revision,
                      operation: entry.operation as 'PUT' | 'DEL' | 'PURGE',
                    });
                  } catch (err) {
                    // Schema decode error — emit as error
                    emit.fail(err as ParseResult.ParseError);
                    return;
                  }
                }

                emit.end();
              } catch (err) {
                emit.fail(
                  new NatsKVError(
                    `Watch failed for pattern '${keyPattern}': ${err}`,
                    err
                  )
                );
              }
            };

            run();

            return Effect.sync(() => {
              cancelled = true;
            });
          }
        );

      const keys = (
        bucket: KV
      ): Effect.Effect<readonly string[], NatsKVError> =>
        Effect.tryPromise({
          try: async () => {
            const result: string[] = [];
            const keysIter = await bucket.keys();
            for await (const key of keysIter) {
              result.push(key);
            }
            return result;
          },
          catch: (err) => new NatsKVError(`Failed to list keys: ${err}`, err),
        });

const list = <A, I>(
        bucket: KV,
        schema: Schema.Schema<A, I>
      ): Effect.Effect<
        readonly TypedKvEntry<A>[],
        NatsKVError | ParseResult.ParseError
      > =>
        Effect.gen(function* () {
          const allKeys = yield* keys(bucket);
          const entries: TypedKvEntry<A>[] = [];

          for (const key of allKeys) {
            const value = yield* get(bucket, key, schema);
            if (value !== null) {
              // Get full entry for metadata
              const rawEntry = yield* Effect.tryPromise({
                try: () => bucket.get(key),
                catch: (err) =>
                  new NatsKVError(`Failed to get entry '${key}': ${err}`, err),
              });

              if (rawEntry && rawEntry.operation === 'PUT') {
                entries.push({
                  key,
                  value,
                  revision: rawEntry.revision,
                  created: new Date(rawEntry.created.getTime()),
                  operation: rawEntry.operation as 'PUT' | 'DEL' | 'PURGE',
                });
              }
            }
          }

          return entries;
        });

      // Close is now handled by scope cleanup (acquireRelease)
      // This method is kept for API compatibility but is a no-op
      const close = (): Effect.Effect<void, never> =>
        Effect.logDebug(
          'NatsKVService.close() called - cleanup handled by scope'
        );

      return {
        getConnection,
        getOrCreateBucket,
        get,
        put,
        delete: del,
        purge,
        watch,
        keys,
        list,
        close,
      } satisfies NatsKVServiceShape;
    }),
    dependencies: [NatsConfigTag.Default],
  }
) {}

// =============================================================================
// Layer Exports
// =============================================================================

export const NatsKVServiceLive = NatsKVService.Default;

export const NatsKVServiceCustom = (config: NatsConfig) =>
  NatsKVService.Default.pipe(Layer.provide(NatsConfigTag.Custom(config)));

