let serverAvailable = false;

async function checkNatsHealth(): Promise<boolean> {
  try {
    const { connect } = await import('nats');
    const nc = await connect({ servers: NATS_SERVERS });
    await nc.close();
    return true;
  } catch {
    return false;
  }
}

