/**
 * NATS Library
 *
 * General-purpose NATS integration with Effect.
 * Provides NatsKVService for JetStream KV operations.
 *
 * ## Usage
 *
 * ```typescript
 * // Namespace import (preferred)
 * import { Nats } from '@/lib/nats'
 *
 * const svc = yield* Nats.KV
 * const bucket = yield* svc.getOrCreateBucket('documents')
 *
 * // Or direct imports
 * import { NatsKVService, NatsConfig } from '@/lib/nats'
 * ```
 *
 * @module nats
 */

import {
  // Service
  NatsKVService,
  NatsKVServiceLive,
  NatsKVServiceCustom,
  // Config
  NatsConfigTag,
  // Errors
  NatsConnectionError,
  NatsKVError,
  NatsKVNotFoundError,
} from './NatsKVService';

// Re-export types
export type {
  NatsKVServiceShape,
  NatsConfig,
  TypedKvEntry,
  KvWatchEvent,
} from './NatsKVService';

// Re-export KV types from nats.ws package (browser-compatible)
export type { KV, KvWatchOptions } from 'nats.ws';

// =============================================================================
// Direct Exports (for granular imports)
// =============================================================================

export {
  NatsKVService,
  NatsKVServiceLive,
  NatsKVServiceCustom,
  NatsConfigTag,
  NatsConnectionError,
  NatsKVError,
  NatsKVNotFoundError,
};

