  /**
   * Create a container. Mutates state synchronously.
   */
  create: (containerId: ContainerId) => {
    overlayRegistry.update(containersStateAtom, (current) =>
      createContainer(current, containerId)
    )
  },

  /**
   * Destroy a container and its ports.
   */
