// ─────────────────────────────────────────────────────────────
// React Provider (uses overlayRegistry)
// ─────────────────────────────────────────────────────────────

/**
 * Provider that injects the shared overlayRegistry into React context.
 * Wrap your app (or overlay-using subtree) with this provider to ensure
 * React components and imperative operations share the same registry.
 *
 * @example
 * ```tsx
 * function App() {
 *   return (
 *     <OverlayRegistryProvider>
 *       <MyOverlayComponents />
 *     </OverlayRegistryProvider>
 *   )
 * }
 * ```
 */
export function OverlayRegistryProvider({ children }: { children: React.ReactNode }) {
  return React.createElement(RegistryContext.Provider, { value: overlayRegistry }, children)
}

/**
 * Overlay State Atoms
 *
 * Core mutable atoms that own overlay system state.
 * Services and hooks operate on these atoms directly.
 *
 * Architecture:
 * - Atoms ARE the source of truth (not Effect.Ref)
 * - Services are stateless — they read/write atoms
 * - Components subscribe to atoms → automatic reactivity
 */

import { Atom } from "@effect-atom/atom-react"
import {
  type ContainerId,
  type OverlayId,
  type ContainerState,
  type OverlayInstance,
  type OverlayState,
  ContainerState as ContainerStateClass,
  OverlayInstance as OverlayInstanceClass,
} from "../schemas"

// ─────────────────────────────────────────────────────────────
// Core State Atom
// ─────────────────────────────────────────────────────────────

/**
 * The single source of truth for all container state.
 * Map of ContainerId → ContainerState
 *
 * NOTE: Uses keepAlive to persist across registry instances.
 */
export const containersStateAtom = Atom.keepAlive(
  Atom.make<Map<ContainerId, ContainerState>>(new Map())
)

// ─────────────────────────────────────────────────────────────
// Derived Atoms
// ─────────────────────────────────────────────────────────────

/**
 * List of all container IDs.
 */
export const containerIdsAtom = Atom.make((get) => {
  const containers = get(containersStateAtom)
  return Array.from(containers.keys())
})

/**
 * Atom family for individual container state.
 */
export const containerAtom = Atom.family((containerId: ContainerId) =>
  Atom.make((get) => {
    const containers = get(containersStateAtom)
    return containers.get(containerId) ?? null
  })
)

/**
 * Atom family for active overlays in a container (LIFO order).
 */
export const activeOverlaysAtom = Atom.family((containerId: ContainerId) =>
  Atom.make((get) => {
    const container = get(containerAtom(containerId))
    if (!container) return []
    return container.activeOverlays.filter((o) => o.state === "active")
  })
)

/**
 * Atom family for checking if container exists.
 */
export const containerExistsAtom = Atom.family((containerId: ContainerId) =>
  Atom.make((get) => {
    const containers = get(containersStateAtom)
    return containers.has(containerId)
  })
)

/**
 * Atom family for checking if an overlay is active.
 */
export const isOverlayActiveAtom = Atom.family(
  ({ containerId, overlayId }: { containerId: ContainerId; overlayId: OverlayId }) =>
    Atom.make((get) => {
      const overlays = get(activeOverlaysAtom(containerId))
      return overlays.some((o) => o.id === overlayId)
    })
)

// ─────────────────────────────────────────────────────────────
// Mutation Functions (pure, return new state)
// ─────────────────────────────────────────────────────────────

/**
 * Create a new container.
 */
export const createContainer = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId
): Map<ContainerId, ContainerState> => {
  if (containers.has(containerId)) return containers // idempotent
  const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      id: containerId,
      activeOverlays: [],
      registeredOverlays: [],
      enabled: true,
    })
  )
  return next
}

/**
 * Destroy a container.
 */
export const destroyContainer = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId
): Map<ContainerId, ContainerState> => {
  if (!containers.has(containerId)) return containers
  const next = new Map(containers)
  next.delete(containerId)
  return next
}

/**
 * Register an overlay in a container.
 */
export const registerOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId,
  name: string,
  visualPriority: number = 0
): Map<ContainerId, ContainerState> => {
  // Auto-create container if needed
  let updated = containers.has(containerId)
    ? containers
    : createContainer(containers, containerId)

  const container = updated.get(containerId)!
  if (container.registeredOverlays.includes(overlayId)) return updated

  const next = new Map(updated)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      registeredOverlays: [...container.registeredOverlays, overlayId],
    })
  )
  return next
}

/**
 * Unregister an overlay from a container.
 */
export const unregisterOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId
): Map<ContainerId, ContainerState> => {
  const container = containers.get(containerId)
  if (!container) return containers

  const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      registeredOverlays: container.registeredOverlays.filter((id) => id !== overlayId),
      activeOverlays: container.activeOverlays.filter((o) => o.id !== overlayId),
    })
  )
  return next
}

/**
 * Enable (activate) an overlay.
 */
export const enableOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId,
  name?: string,
  visualPriority: number = 0
): Map<ContainerId, ContainerState> => {
  // Auto-create container if needed
  let updated = containers.has(containerId)
    ? containers
    : createContainer(containers, containerId)

  const container = updated.get(containerId)!

const container = updated.get(containerId)!

  // Check if already active
  const existingIdx = container.activeOverlays.findIndex((o) => o.id === overlayId)
  if (existingIdx >= 0 && container.activeOverlays[existingIdx].state === "active") {
    return updated
  }

  const next = new Map(updated)

  if (existingIdx >= 0) {
    // Already in list, update state and move to top (LIFO)
    const overlay = container.activeOverlays[existingIdx]
    const withoutOverlay = container.activeOverlays.filter((_, i) => i !== existingIdx)
    const updatedOverlay = new OverlayInstanceClass({
      ...overlay,
      state: "active" as OverlayState,
      activatedAt: Date.now(),
      stackPosition: withoutOverlay.length,
    })
    next.set(
      containerId,
      new ContainerStateClass({
        ...container,
        activeOverlays: [...withoutOverlay, updatedOverlay],
      })
    )
  } else {
    // New overlay instance
    const newOverlay = new OverlayInstanceClass({
      id: overlayId,
      name: name ?? (overlayId as string),
      state: "active" as OverlayState,
      activatedAt: Date.now(),
      visualPriority,
      stackPosition: container.activeOverlays.length,
    })
    next.set(
      containerId,
      new ContainerStateClass({
        ...container,
        activeOverlays: [...container.activeOverlays, newOverlay],
      })
    )
  }

  return next
}

/**
 * Disable (deactivate) an overlay.
 */
export const disableOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId
): Map<ContainerId, ContainerState> => {
  const container = containers.get(containerId)
  if (!container) return containers

  const idx = container.activeOverlays.findIndex((o) => o.id === overlayId)
  if (idx < 0) return containers

const idx = container.activeOverlays.findIndex((o) => o.id === overlayId)
  if (idx < 0) return containers

  const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      activeOverlays: container.activeOverlays.filter((_, i) => i !== idx),
    })
  )
  return next
}

/**
 * Toggle an overlay's active state.
 */
export const toggleOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId
): Map<ContainerId, ContainerState> => {
  const container = containers.get(containerId)
  const isActive = container?.activeOverlays.some(
    (o) => o.id === overlayId && o.state === "active"
  )

  return isActive
    ? disableOverlay(containers, containerId, overlayId)
    : enableOverlay(containers, containerId, overlayId)
}

/**
 * Suspend an overlay.
 */
export const suspendOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId
): Map<ContainerId, ContainerState> => {
  const container = containers.get(containerId)
  if (!container) return containers

  const idx = container.activeOverlays.findIndex((o) => o.id === overlayId)
  if (idx < 0) return containers

  const overlay = container.activeOverlays[idx]
  if (overlay.state !== "active") return containers

  const updatedOverlay = new OverlayInstanceClass({
    ...overlay,
    state: "suspended" as OverlayState,
  })

  const newOverlays = [...container.activeOverlays]
  newOverlays[idx] = updatedOverlay

  const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      activeOverlays: newOverlays,
    })
  )
  return next
}

const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      activeOverlays: newOverlays,
    })
  )
  return next
}

/**
 * Resume a suspended overlay.
 */
export const resumeOverlay = (
  containers: Map<ContainerId, ContainerState>,
  containerId: ContainerId,
  overlayId: OverlayId
): Map<ContainerId, ContainerState> => {
  const container = containers.get(containerId)
  if (!container) return containers

  const idx = container.activeOverlays.findIndex((o) => o.id === overlayId)
  if (idx < 0) return containers

  const overlay = container.activeOverlays[idx]
  if (overlay.state !== "suspended") return containers

  const updatedOverlay = new OverlayInstanceClass({
    ...overlay,
    state: "active" as OverlayState,
  })

  const newOverlays = [...container.activeOverlays]
  newOverlays[idx] = updatedOverlay

  const next = new Map(containers)
  next.set(
    containerId,
    new ContainerStateClass({
      ...container,
      activeOverlays: newOverlays,
    })
  )
  return next
}

/**
 * Suppression Atoms
 *
 * Manages overlay suppression state for programmatic show/hide control.
 * Supports both type-level and instance-level suppression.
 *
 * Usage:
 * - Type-level: useSuppressOverlay("modal") suppresses ALL modals
 * - Instance-level: useSuppressOverlay("modal:settings") suppresses specific instance
 *
 * @module
 */

import { Atom } from "@effect-atom/atom-react"
import {
  type SuppressionKey,
  type VisualOverlayId,
  type VisualOverlayType,
  typeSuppressionKey,
  instanceSuppressionKey,
  parseSuppressionKey,
} from "../schemas/visual"

// ─────────────────────────────────────────────────────────────
// Core State Atom
// ─────────────────────────────────────────────────────────────

/**
 * Set of active suppression keys.
 * Format: "type" (e.g., "modal") or "type:instance" (e.g., "modal:settings")
 *
 * NOTE: Uses keepAlive to persist across registry instances.
 */
export const suppressionsAtom = Atom.keepAlive(
  Atom.make<Set<SuppressionKey>>(new Set())
)

// ─────────────────────────────────────────────────────────────
// Derived Atoms
// ─────────────────────────────────────────────────────────────

/**
 * Check if an overlay should be suppressed.
 * Returns true if EITHER type-level OR instance-level suppression is active.
 *
 * @example
 * // Checks both "modal" and "modal:settings"
 * get(isSuppressedAtom({ type: "modal", id: "settings" }))
 */
export const isSuppressedAtom = Atom.family(
  ({ type, id }: { type: VisualOverlayType; id: VisualOverlayId }) =>
    Atom.make((get) => {
      const suppressions = get(suppressionsAtom)
      const tKey = typeSuppressionKey(type)
      const iKey = instanceSuppressionKey(type, id as string)
      return suppressions.has(tKey) || suppressions.has(iKey)
    })
)

/**
 * Check if ALL overlays of a type are suppressed.
 *
 * @example
 * get(isTypeSuppressedAtom("modal")) // true if "modal" key is in suppressions
 */
export const isTypeSuppressedAtom = Atom.family((type: VisualOverlayType) =>
  Atom.make((get) => {
    const suppressions = get(suppressionsAtom)
    return suppressions.has(typeSuppressionKey(type))
  })
)

/**
 * Get all active suppression keys.
 */
export const activeSuppressionKeysAtom = Atom.make((get) => {
  const suppressions = get(suppressionsAtom)
  return Array.from(suppressions)
})

/**
 * Get suppression count.
 */
export const suppressionCountAtom = Atom.make((get) => {
  const suppressions = get(suppressionsAtom)
  return suppressions.size
})

// ─────────────────────────────────────────────────────────────
// Mutation Functions (pure, return new state)
// ─────────────────────────────────────────────────────────────

/**
 * Add a suppression key.
 * Idempotent - adding an existing key returns same state.
 */
export const addSuppression = (
  suppressions: Set<SuppressionKey>,
  key: SuppressionKey,
): Set<SuppressionKey> => {
  if (suppressions.has(key)) return suppressions
  const next = new Set(suppressions)
  next.add(key)
  return next
}

/**
 * Remove a suppression key.
 * Idempotent - removing a non-existent key returns same state.
 */
export const removeSuppression = (
  suppressions: Set<SuppressionKey>,
  key: SuppressionKey,
): Set<SuppressionKey> => {
  if (!suppressions.has(key)) return suppressions
  const next = new Set(suppressions)
  next.delete(key)
  return next
}

/**
 * Toggle a suppression key.
 */
export const toggleSuppression = (
  suppressions: Set<SuppressionKey>,
  key: SuppressionKey,
): Set<SuppressionKey> => {
  if (suppressions.has(key)) {
    return removeSuppression(suppressions, key)
  }
  return addSuppression(suppressions, key)
}

/**
 * Clear all suppressions.
 */
export const clearAllSuppressions = (
  _suppressions: Set<SuppressionKey>,
): Set<SuppressionKey> => {
  return new Set()
}

/**
 * Clear all suppressions for a specific type.
 * Removes both type-level and all instance-level suppressions.
 */
export const clearTypeSuppressions = (
  suppressions: Set<SuppressionKey>,
  type: VisualOverlayType,
): Set<SuppressionKey> => {
  const next = new Set<SuppressionKey>()
  for (const key of suppressions) {
    const parsed = parseSuppressionKey(key)
    if (parsed.type !== type) {
      next.add(key)
    }
  }
  return next
}

// ─────────────────────────────────────────────────────────────
// Re-export helpers for convenience
// ─────────────────────────────────────────────────────────────

export { typeSuppressionKey, instanceSuppressionKey, parseSuppressionKey }

/**
 * Visual Overlay Atoms
 *
 * Core state atoms for the visual overlay orchestration layer.
 * Atoms ARE the source of truth — no Effect.Ref needed.
 *
 * Architecture:
 * - visualOverlaysAtom: Map<id, instance> — all overlay instances
 * - zOrderByTypeAtom: Map<type, id[]> — stacking order per type
 * - slotsAtom: Map<slotId, registration> — registered slots
 * - Content stored in separate registry (ReactNode not serializable)
 *
 * @module
 */

import { Atom } from "@effect-atom/atom-react"
import type { ReactNode } from "react"
import {
  type VisualOverlayId,
  type VisualOverlayType,
  type VisualOverlayConfig,
  type VisualOverlayInstance,
  type SlotId,
  type OverlayAnimationState,
  type SlotRegistration,
  VisualOverlayInstance as VisualOverlayInstanceClass,
  SlotRegistration as SlotRegistrationClass,
} from "../schemas/visual"
import { calculateZIndex, GLOBAL_SLOT_ID } from "../visual/constants"

// ─────────────────────────────────────────────────────────────
// Content Registry (non-serializable, in-memory)
// ─────────────────────────────────────────────────────────────

/**
 * In-memory registry for ReactNode content.
 * Keyed by contentKey from VisualOverlayInstance.
 * Separate from atoms because ReactNode isn't serializable.
 */
const contentRegistry = new Map<string, ReactNode>()

/**
 * Register content for an overlay.
 */
export const registerContent = (key: string, content: ReactNode): void => {
  contentRegistry.set(key, content)
}

/**
 * Get content for an overlay.
 */
export const getContent = (key: string): ReactNode | undefined => {
  return contentRegistry.get(key)
}

/**
 * Unregister content for an overlay.
 */
export const unregisterContent = (key: string): void => {
  contentRegistry.delete(key)
}

/**
 * Check if content exists.
 */
export const hasContent = (key: string): boolean => {
  return contentRegistry.has(key)
}

/**
 * Check if content exists.
 */
export const hasContent = (key: string): boolean => {
  return contentRegistry.has(key)
}

// ─────────────────────────────────────────────────────────────
// Drawer Slot Content Registry (injection pattern)
// ─────────────────────────────────────────────────────────────

/**
 * Pre-registered slot content for drawers.
 * Components can register content for a drawer ID before it opens.
 * When drawer opens, it checks this registry first.
 */
const drawerSlotRegistry = new Map<string, ReactNode>()

/**
 * Register slot content for a drawer ID.
 * Call from any component to inject content into a specific drawer.
 */
export const registerDrawerSlot = (drawerId: string, content: ReactNode): void => {
  drawerSlotRegistry.set(drawerId, content)
}

/**
 * Unregister slot content for a drawer ID.
 */
export const unregisterDrawerSlot = (drawerId: string): void => {
  drawerSlotRegistry.delete(drawerId)
}

/**
 * Get registered slot content for a drawer ID.
 */
export const getDrawerSlotContent = (drawerId: string): ReactNode | undefined => {
  return drawerSlotRegistry.get(drawerId)
}

/**
 * Check if slot content is registered for a drawer ID.
 */
export const hasDrawerSlotContent = (drawerId: string): boolean => {
  return drawerSlotRegistry.has(drawerId)
}

// ─────────────────────────────────────────────────────────────
// Core State Atoms
// ─────────────────────────────────────────────────────────────

/**
 * All visual overlay instances, keyed by ID.
 * This is the single source of truth for overlay state.
 */
export const visualOverlaysAtom = Atom.keepAlive(
  Atom.make<Map<VisualOverlayId, VisualOverlayInstance>>(new Map())
)

/**
 * Z-order per overlay type (last element = top).
 * Tracks stacking order within each type tier.
 */
export const zOrderByTypeAtom = Atom.keepAlive(
  Atom.make<Map<VisualOverlayType, VisualOverlayId[]>>(
    new Map([
      ["drawer", []],
      ["modal", []],
      ["toast", []],
      ["command-palette", []],
      ["top-bar", []],
      ["sidebar", []],
    ])
  )
)

/**
 * Registered slots for overlay rendering.
 */
export const slotsAtom = Atom.keepAlive(
  Atom.make<Map<SlotId, SlotRegistration>>(new Map())
)

// ─────────────────────────────────────────────────────────────
// Derived Atoms
// ─────────────────────────────────────────────────────────────

/**
 * All visible overlay IDs (entering or visible animation state).
 */
export const visibleOverlayIdsAtom = Atom.make((get) => {
  const overlays = get(visualOverlaysAtom)
  return Array.from(overlays.values())
    .filter((o) => o.isVisible)
    .map((o) => o.id)
})

/**
 * Overlays by type, in z-order (last = top).
 */
export const overlaysByTypeAtom = Atom.family((type: VisualOverlayType) =>
  Atom.make((get) => {
    const overlays = get(visualOverlaysAtom)
    const zOrder = get(zOrderByTypeAtom).get(type) ?? []
    return zOrder
      .map((id) => overlays.get(id))
      .filter((o): o is VisualOverlayInstance => o !== undefined && !o.hasExited)
  })
)

/**
 * Overlays by slot (for slot-scoped types like drawer, sidebar).
 */
export const overlaysBySlotAtom = Atom.family((slotId: SlotId) =>
  Atom.make((get) => {
    const overlays = get(visualOverlaysAtom)
    return Array.from(overlays.values())
      .filter((o) => {
        if (o.hasExited) return false
        const config = o.config
        if (config._tag === "DrawerConfig" || config._tag === "SidebarConfig") {
          return config.slot === slotId
        }
        return false
      })
      .sort((a, b) => a.zIndex - b.zIndex)
  })
)

/**
 * Check if any blocking overlay is open (modal or command palette).
 */
export const hasBlockingOverlayAtom = Atom.make((get) => {
  const modals = get(overlaysByTypeAtom("modal"))
  const palettes = get(overlaysByTypeAtom("command-palette"))
  return modals.some((m) => m.isVisible) || palettes.some((p) => p.isVisible)
})

/**
 * Top (frontmost) overlay of a type.
 */
export const topOverlayByTypeAtom = Atom.family((type: VisualOverlayType) =>
  Atom.make((get) => {
    const overlays = get(overlaysByTypeAtom(type))
    const visible = overlays.filter((o) => o.isVisible)
    return visible[visible.length - 1] ?? null
  })
)

/**
 * Get overlay instance by ID.
 */
export const overlayAtom = Atom.family((id: VisualOverlayId) =>
  Atom.make((get) => {
    const overlays = get(visualOverlaysAtom)
    return overlays.get(id) ?? null
  })
)

/**
 * Count of visible overlays by type.
 */
export const overlayCountByTypeAtom = Atom.family((type: VisualOverlayType) =>
  Atom.make((get) => {
    const overlays = get(overlaysByTypeAtom(type))
    return overlays.filter((o) => o.isVisible).length
  })
)

/**
 * Total count of all visible overlays.
 */
export const totalVisibleOverlayCountAtom = Atom.make((get) => {
  return get(visibleOverlayIdsAtom).length
})

/**
 * Get all registered slot IDs.
 */
export const slotIdsAtom = Atom.make((get) => {
  const slots = get(slotsAtom)
  return Array.from(slots.keys())
})

// ─────────────────────────────────────────────────────────────
// Mutation Functions (pure, return new state)
// ─────────────────────────────────────────────────────────────

/**
 * Get overlay type from config tag.
 */
function getTypeFromConfig(config: VisualOverlayConfig): VisualOverlayType {
  switch (config._tag) {
    case "DrawerConfig": return "drawer"
    case "ModalConfig": return "modal"
    case "ToastConfig": return "toast"
    case "CommandPaletteConfig": return "command-palette"
    case "TopBarConfig": return "top-bar"
    case "SidebarConfig": return "sidebar"
  }
}

/**
 * Open a new visual overlay.
 * Creates instance, adds to overlays map, and updates z-order.
 */
export const openOverlay = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>,
  id: VisualOverlayId,
  type: VisualOverlayType,
  config: VisualOverlayConfig,
  contentKey: string,
): {
  overlays: Map<VisualOverlayId, VisualOverlayInstance>
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>
} => {
  // Get current z-order for type
  const currentOrder = zOrders.get(type) ?? []
  const stackPosition = currentOrder.length
  const zIndex = calculateZIndex(type, stackPosition, config.zIndexOffset ?? 0)

  // Create instance
  const instance = new VisualOverlayInstanceClass({
    id,
    type,
    config,
    animationState: "entering",
    zIndex,
    openedAt: Date.now(),
    contentKey,
  })

// Create instance
  const instance = new VisualOverlayInstanceClass({
    id,
    type,
    config,
    animationState: "entering",
    zIndex,
    openedAt: Date.now(),
    contentKey,
  })

  // Update overlays map
  const nextOverlays = new Map(overlays)
  nextOverlays.set(id, instance)

  // Update z-order
  const nextZOrders = new Map(zOrders)
  nextZOrders.set(type, [...currentOrder, id])

  return { overlays: nextOverlays, zOrders: nextZOrders }
}

/**
 * Close a visual overlay (start exit animation).
 * Sets animation state to "exiting".
 */
export const closeOverlay = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  id: VisualOverlayId,
): Map<VisualOverlayId, VisualOverlayInstance> => {
  const instance = overlays.get(id)
  if (!instance || instance.isExiting || instance.hasExited) {
    return overlays
  }

  const next = new Map(overlays)
  next.set(id, new VisualOverlayInstanceClass({
    ...instance,
    animationState: "exiting",
  }))
  return next
}

/**
 * Remove overlay from state (after exit animation completes).
 * Also cleans up content registry.
 */
export const removeOverlay = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>,
  id: VisualOverlayId,
): {
  overlays: Map<VisualOverlayId, VisualOverlayInstance>
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>
} => {
  const instance = overlays.get(id)
  if (!instance) return { overlays, zOrders }

  // Remove from overlays
  const nextOverlays = new Map(overlays)
  nextOverlays.delete(id)

// Remove from overlays
  const nextOverlays = new Map(overlays)
  nextOverlays.delete(id)

  // Remove from z-order
  const nextZOrders = new Map(zOrders)
  const currentOrder = nextZOrders.get(instance.type) ?? []
  nextZOrders.set(instance.type, currentOrder.filter((i) => i !== id))

  // Clean up content
  unregisterContent(instance.contentKey)

  return { overlays: nextOverlays, zOrders: nextZOrders }
}

/**
 * Update animation state.
 */
export const setAnimationState = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  id: VisualOverlayId,
  state: OverlayAnimationState,
): Map<VisualOverlayId, VisualOverlayInstance> => {
  const instance = overlays.get(id)
  if (!instance) return overlays

  const next = new Map(overlays)
  next.set(id, new VisualOverlayInstanceClass({
    ...instance,
    animationState: state,
  }))
  return next
}

/**
 * Bring overlay to front of its type stack.
 * Recalculates z-indices for affected overlays.
 */
export const bringToFront = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>,
  id: VisualOverlayId,
): {
  overlays: Map<VisualOverlayId, VisualOverlayInstance>
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>
} => {
  const instance = overlays.get(id)
  if (!instance) return { overlays, zOrders }

  const currentOrder = zOrders.get(instance.type) ?? []
  const idx = currentOrder.indexOf(id)
  if (idx === currentOrder.length - 1) {
    // Already on top
    return { overlays, zOrders }
  }

  // Reorder: move to end
  const newOrder = [...currentOrder.filter((i) => i !== id), id]
  const nextZOrders = new Map(zOrders)
  nextZOrders.set(instance.type, newOrder)

// Recalculate z-indices for this type
  const nextOverlays = new Map(overlays)
  newOrder.forEach((overlayId, position) => {
    const overlay = nextOverlays.get(overlayId)
    if (overlay) {
      const newZ = calculateZIndex(instance.type, position, overlay.config.zIndexOffset ?? 0)
      if (overlay.zIndex !== newZ) {
        nextOverlays.set(overlayId, new VisualOverlayInstanceClass({
          ...overlay,
          zIndex: newZ,
        }))
      }
    }
  })

  return { overlays: nextOverlays, zOrders: nextZOrders }
}

/**
 * Send overlay to back of its type stack.
 */
export const sendToBack = (
  overlays: Map<VisualOverlayId, VisualOverlayInstance>,
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>,
  id: VisualOverlayId,
): {
  overlays: Map<VisualOverlayId, VisualOverlayInstance>
  zOrders: Map<VisualOverlayType, VisualOverlayId[]>
} => {
  const instance = overlays.get(id)
  if (!instance) return { overlays, zOrders }

  const currentOrder = zOrders.get(instance.type) ?? []
  const idx = currentOrder.indexOf(id)
  if (idx === 0) {
    // Already at back
    return { overlays, zOrders }
  }

  // Reorder: move to front
  const newOrder = [id, ...currentOrder.filter((i) => i !== id)]
  const nextZOrders = new Map(zOrders)
  nextZOrders.set(instance.type, newOrder)

// Recalculate z-indices for this type
  const nextOverlays = new Map(overlays)
  newOrder.forEach((overlayId, position) => {
    const overlay = nextOverlays.get(overlayId)
    if (overlay) {
      const newZ = calculateZIndex(instance.type, position, overlay.config.zIndexOffset ?? 0)
      if (overlay.zIndex !== newZ) {
        nextOverlays.set(overlayId, new VisualOverlayInstanceClass({
          ...overlay,
          zIndex: newZ,
        }))
      }
    }
  })

  return { overlays: nextOverlays, zOrders: nextZOrders }
}

// ─────────────────────────────────────────────────────────────
// Slot Mutations
// ─────────────────────────────────────────────────────────────

/**
 * Register a slot for overlay rendering.
 */
export const registerSlot = (
  slots: Map<SlotId, SlotRegistration>,
  id: SlotId,
  containerId: string,
  bounds?: { x: number; y: number; width: number; height: number },
): Map<SlotId, SlotRegistration> => {
  const next = new Map(slots)
  next.set(id, new SlotRegistrationClass({
    id,
    containerId,
    bounds,
  }))
  return next
}

/**
 * Unregister a slot.
 */
export const unregisterSlot = (
  slots: Map<SlotId, SlotRegistration>,
  id: SlotId,
): Map<SlotId, SlotRegistration> => {
  if (!slots.has(id)) return slots
  const next = new Map(slots)
  next.delete(id)
  return next
}

/**
 * Update slot bounds (for panel slots on resize).
 */
export const updateSlotBounds = (
  slots: Map<SlotId, SlotRegistration>,
  id: SlotId,
  bounds: { x: number; y: number; width: number; height: number },
): Map<SlotId, SlotRegistration> => {
  const slot = slots.get(id)
  if (!slot) return slots

const next = new Map(slots)
  next.set(id, new SlotRegistrationClass({
    ...slot,
    bounds,
  }))
  return next
}

/**
 * Container Events
 *
 * EventGroup for container lifecycle operations.
 */

import { EventGroup } from "@effect/experimental"
import { Schema } from "effect"
import { ContainerId } from "../schemas"

// ─────────────────────────────────────────────────────────────
// Container Events
// ─────────────────────────────────────────────────────────────

export const ContainerEvents = EventGroup.empty
  .add({
    tag: "ContainerCreated",
    primaryKey: (p) => p.containerId,
    payload: Schema.Struct({
      containerId: ContainerId,
      timestamp: Schema.Number,
    }),
  })
  .add({
    tag: "ContainerDestroyed",
    primaryKey: (p) => p.containerId,
    payload: Schema.Struct({
      containerId: ContainerId,
    }),
  })

// ─────────────────────────────────────────────────────────────
// Event Types (for external consumers)
// ─────────────────────────────────────────────────────────────

export type ContainerCreatedPayload = {
  readonly containerId: ContainerId
  readonly timestamp: number
}

export type ContainerDestroyedPayload = {
  readonly containerId: ContainerId
}

/**
 * EventLog Handlers
 *
 * Event handlers that update Ref-based services when events are processed.
 * Each handler receives { payload, entry, conflicts } and calls existing service methods.
 */

import { EventLog } from "@effect/experimental"
import * as Effect from "effect/Effect"
import { OverlayRegistry } from "../services/OverlayRegistry"
import { PortHub } from "../services/PortHub"
import { ContainerEvents } from "./container"
import { OverlayEvents } from "./overlay"
import { PortEvents } from "./port"

// ─────────────────────────────────────────────────────────────
// Container Handlers
// ─────────────────────────────────────────────────────────────

/**
 * Handlers for ContainerEvents.
 * Returns a Layer providing the handler registrations.
 */
export const ContainerHandlersLive = EventLog.group(ContainerEvents, (handlers) =>
  handlers
    .handle("ContainerCreated", ({ payload }) =>
      Effect.gen(function* () {
        const registry = yield* OverlayRegistry
        yield* registry.createContainer(payload.containerId)
      })
    )
    .handle("ContainerDestroyed", ({ payload }) =>
      Effect.gen(function* () {
        const registry = yield* OverlayRegistry
        const hub = yield* PortHub
        // Clean up ports first, then container
        yield* hub.destroyContainerPorts(payload.containerId)
        yield* registry.destroyContainer(payload.containerId)
      })
    )
)

// ─────────────────────────────────────────────────────────────
// Overlay Handlers
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Overlay Handlers
// ─────────────────────────────────────────────────────────────

/**
 * Handlers for OverlayEvents.
 * Lifecycle transitions (register, enable, disable, suspend, resume).
 */
export const OverlayHandlersLive = EventLog.group(OverlayEvents, (handlers) =>
  handlers
    .handle("OverlayRegistered", ({ payload }) =>
      Effect.gen(function* () {
        const registry = yield* OverlayRegistry
        yield* registry.register(
          payload.containerId,
          payload.overlayId,
          payload.name,
          payload.visualPriority
        )
      })
    )
    .handle("OverlayUnregistered", ({ payload }) =>
      Effect.gen(function* () {
        const registry = yield* OverlayRegistry
        yield* registry.unregister(payload.containerId, payload.overlayId)
      })
    )
    .handle("OverlayEnabled", ({ payload }) =>
      Effect.gen(function* () {
        const registry = yield* OverlayRegistry
        yield* registry.enable(payload.containerId, payload.overlayId)
      })
    )
    .handle("OverlayDisabled", ({ payload }) =>
      Effect.gen(function* () {
