 *   handlers: {
 *     PointerDown: (event, ctx) => Effect.succeed("handled"),
 *   },
 * })
 *
 * function DragFeature({ containerId }: { containerId: ContainerId }) {
 *   const { isActive, toggle } = useOverlay({
 *     containerId,
 *     overlay: DragOverlay,
 *     autoEnable: true,
 *   })
 *
 *   return (
 *     <button onClick={toggle}>
 *       Drag Mode: {isActive ? "ON" : "OFF"}
 *     </button>
 *   )
 * }
 * ```
 */
export function useOverlay(options: UseOverlayOptions): UseOverlayResult {
  const { containerId, autoRegister = true, autoEnable = false } = options

  // Normalize to Overlay instance
  const overlay = useMemo(() => {
    return options.overlay instanceof Overlay
      ? options.overlay
      : new Overlay(options.overlay)
  }, [options.overlay])

  const overlayId = overlay.id

  // ─── State (direct values from pure atoms) ───

  const instance = useAtomValue(
    overlayInstanceAtom({ containerId, overlayId })
  ) as Option.Option<OverlayInstance>

  const isActive = useAtomValue(
    isOverlayActiveAtom({ containerId, overlayId })
  ) as boolean

  // ─── Operations (direct calls, not atoms) ───

  const enable = useCallback(() => {
    overlayOps.enable({ containerId, overlayId })
  }, [containerId, overlayId])

  const disable = useCallback(() => {
    overlayOps.disable({ containerId, overlayId })
  }, [containerId, overlayId])

  const toggle = useCallback(() => {
    overlayOps.toggle({ containerId, overlayId })
  }, [containerId, overlayId])

const toggle = useCallback(() => {
    overlayOps.toggle({ containerId, overlayId })
  }, [containerId, overlayId])

  const suspend = useCallback(() => {
    overlayOps.suspend({ containerId, overlayId })
  }, [containerId, overlayId])

  const resume = useCallback(() => {
    overlayOps.resume({ containerId, overlayId })
  }, [containerId, overlayId])

  // ─── Registration Lifecycle (via shared atom runtime) ───

  const doRegister = useAtomSet(overlayOps.register)
  const doUnregister = useAtomSet(overlayOps.unregister)
  const registeredRef = useRef(false)

  useEffect(() => {
    if (!autoRegister) return

    // Register through the shared atom runtime
    doRegister({
      containerId,
      overlayId,
      name: overlay.name,
      visualPriority: overlay.visualPriority,
      handlers: overlay.getWrappedHandlers(containerId),
    })
    registeredRef.current = true

    // Auto-enable if requested
    if (autoEnable) {
      overlayOps.enable({ containerId, overlayId })
    }

    return () => {
      // Unregister through the shared atom runtime
      if (registeredRef.current) {
        doUnregister({ containerId, overlayId })
        registeredRef.current = false
      }
    }
  }, [autoRegister, autoEnable, overlay, containerId, overlayId, doRegister, doUnregister])

  return {
    overlayId,
    instance,
    isActive,
    enable,
    disable,
    toggle,
    suspend,
    resume,
  }
}

/**
 * useOverlayContainer Hook
 *
 * Creates and manages an overlay container.
 * Containers scope overlays and ports to a specific region.
 *
 * Architecture:
 * - Uses atom-based state (no Effect.Ref)
 * - Automatic reactivity via effect-atom subscriptions
 * - Synchronous create/destroy operations
 */

import { useEffect, useCallback } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import { type ContainerId, type OverlayInstance } from "../schemas"
import {
  containerAtom,
  activeOverlaysAtom,
  containerExistsAtom,
  containerOps,
  overlayOps,
} from "../atoms"

export interface UseOverlayContainerOptions {
  /** Container ID (will be created if doesn't exist) */
  containerId: ContainerId
  /** Auto-create container on mount (default: true) */
  autoCreate?: boolean
  /** Auto-destroy container on unmount (default: true) */
  autoDestroy?: boolean
}

export interface UseOverlayContainerResult {
  /** Container ID */
  containerId: ContainerId
  /** Whether container exists */
  exists: boolean
  /** Active overlays in LIFO order */
  activeOverlays: ReadonlyArray<OverlayInstance>
  /** Enable an overlay */
  enable: (overlayId: string) => void
  /** Disable an overlay */
  disable: (overlayId: string) => void
  /** Toggle an overlay */
  toggle: (overlayId: string) => void
  /** Manually create the container */
  create: () => void
  /** Manually destroy the container */
  destroy: () => void
}

/**
 * Hook to create and manage an overlay container.
 *
 * @example
 * ```tsx
 * function Canvas() {
 *   const container = useOverlayContainer({
 *     containerId: "main-canvas" as ContainerId,
 *   })
 *
 *   return (
 *     <div data-container-id={container.containerId}>
 *       {container.activeOverlays.map(overlay => (
 *         <span key={overlay.id}>{overlay.name}</span>
 *       ))}
 *     </div>
 *   )
 * }
 * ```
 */
export function useOverlayContainer(
  options: UseOverlayContainerOptions
): UseOverlayContainerResult {
  const { containerId, autoCreate = true, autoDestroy = true } = options

  // ─── Reactive State (from atoms) ───

  const exists = useAtomValue(containerExistsAtom(containerId))
  const activeOverlays = useAtomValue(activeOverlaysAtom(containerId))

  // ─── Operations (synchronous, direct atom mutations) ───

  const create = useCallback(() => {
    containerOps.create(containerId)
  }, [containerId])

  const destroy = useCallback(() => {
    containerOps.destroy(containerId)
  }, [containerId])

  const enable = useCallback(
    (overlayId: string) => {
      overlayOps.enable({ containerId, overlayId: overlayId as any })
    },
    [containerId]
  )

  const disable = useCallback(
    (overlayId: string) => {
      overlayOps.disable({ containerId, overlayId: overlayId as any })
    },
    [containerId]
  )

  const toggle = useCallback(
    (overlayId: string) => {
      overlayOps.toggle({ containerId, overlayId: overlayId as any })
    },
    [containerId]
  )

  // ─── Lifecycle ───

  useEffect(() => {
    if (autoCreate) {
      create()
    }

    return () => {
      if (autoDestroy) {
        destroy()
      }
    }
  }, [autoCreate, autoDestroy, create, destroy])

return () => {
      if (autoDestroy) {
        destroy()
      }
    }
  }, [autoCreate, autoDestroy, create, destroy])

  return {
    containerId,
    exists,
    activeOverlays,
    enable,
    disable,
    toggle,
    create,
    destroy,
  }
}

/**
 * usePort Hook
 *
 * Subscribe to and publish on typed ports.
 */

import { useEffect, useState, useCallback, useRef } from "react"
import { useAtomValue, useAtomSet } from "@effect-atom/atom-react"
import * as Result from "@effect-atom/atom/Result"
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import * as Stream from "effect/Stream"
import * as Fiber from "effect/Fiber"
import * as Runtime from "effect/Runtime"
import * as Scope from "effect/Scope"
import { type ContainerId, type PortId } from "../schemas"
import { PortHub } from "../services"
import { portOps, overlayRuntimeAtom } from "../atoms"

export interface UsePortOptions<T> {
  /** Container ID */
  containerId: ContainerId
  /** Port ID */
  portId: PortId
  /** Initial value before first message */
  initialValue?: T
  /** Subscribe to stream updates (default: true) */
  subscribe?: boolean
}

export interface UsePortResult<T> {
  /** Current port value */
  value: T | undefined
  /** Latest value as Option */
  latest: Option.Option<T>
  /** Whether port has received any messages */
  hasValue: boolean
  /** Publish a message to the port */
  publish: (payload: T) => void
  /** Clear the port (destroy and recreate) */
  clear: () => void
}

/**
 * Hook to subscribe to and publish on a typed port.
 *
 * @example
 * ```tsx
 * interface DragState {
 *   dragging: boolean
 *   position: { x: number; y: number }
 * }
 *
 * function DragIndicator({ containerId }: { containerId: ContainerId }) {
 *   const { value, publish } = usePort<DragState>({
 *     containerId,
 *     portId: "drag:state" as PortId,
 *     initialValue: { dragging: false, position: { x: 0, y: 0 } },
 *   })
 *
 *   return (
 *     <div>
 *       {value?.dragging && (
 *         <div style={{ left: value.position.x, top: value.position.y }}>
 *           Dragging...
 *         </div>
 *       )}
 *     </div>
 *   )
 * }
 * ```
 */
// DIAGNOSTIC: Track render count per port
const renderCounts = new Map<string, number>()

export function usePort<T>(options: UsePortOptions<T>): UsePortResult<T> {
  const { containerId, portId, initialValue, subscribe = true } = options

  // DIAGNOSTIC: Log every render
  const key = `${containerId}:${portId}`
  const count = (renderCounts.get(key) ?? 0) + 1
  renderCounts.set(key, count)
  console.log(`[DIAG:usePort] RENDER #${count} for ${key}`)

  // ─── State ───

  const [streamValue, setStreamValue] = useState<T | undefined>(initialValue)
  const fiberRef = useRef<Fiber.RuntimeFiber<void, never> | null>(null)

  // DIAGNOSTIC: Log before useAtomValue
  console.log(`[DIAG:usePort] ${key} - about to call useAtomValue(overlayRuntimeAtom)`)

  // Get the shared runtime from the atom
  const runtimeResult = useAtomValue(overlayRuntimeAtom)

// Get the shared runtime from the atom
  const runtimeResult = useAtomValue(overlayRuntimeAtom)

  // DIAGNOSTIC: Log after useAtomValue
  console.log(`[DIAG:usePort] ${key} - runtimeResult.isSuccess=${Result.isSuccess(runtimeResult)}`)

  // Stabilize runtime reference to prevent useEffect re-runs
  // The runtime itself is stable once created; only the Result wrapper changes
  const runtimeRef = useRef<Runtime.Runtime<PortHub> | null>(null)

  // Track if runtime has been captured (for deps stability)
  const hasRuntime = Result.isSuccess(runtimeResult)
  if (hasRuntime && !runtimeRef.current) {
    runtimeRef.current = runtimeResult.value
    console.log(`[DIAG:usePort] ${key} - captured runtime to ref`)
  }

  // NOTE: We intentionally DO NOT use portAtom here.
  // The portAtom uses overlayRuntimeAtom.atom(Effect) which re-executes
  // on every read, returning a new Option object and causing infinite re-renders.
  // Stream subscription (below) handles all updates; atom read is redundant.

  const hasValue = streamValue !== undefined
  const latest = hasValue ? Option.some(streamValue as T) : Option.none<T>()
  const value = streamValue ?? initialValue

  // ─── Subscription ───

  useEffect(() => {
    if (!subscribe) return

    // Wait for runtime to be available (using stable ref)
    const runtime = runtimeRef.current
    if (!runtime) return

    // Subscribe to stream updates using the SHARED runtime
    // This ensures we use the same PortHub instance as the atoms
    const subscribeEffect = Effect.gen(function* () {
      const hub = yield* PortHub
      yield* Effect.log(`[usePort] subscribing ${containerId}:${portId} via SHARED runtime`)
      const stream = yield* hub.subscribe<T>(containerId, portId)

// Run stream and update state
      yield* Stream.runForEach(stream, (payload) =>
        Effect.sync(() => {
          console.log(`[usePort] ${containerId}:${portId} received:`, payload)
          setStreamValue(payload)
        })
      )
    }).pipe(Effect.scoped)

    // Run in background fiber using the SHARED runtime
    const fiber = Runtime.runFork(runtime)(subscribeEffect)
    fiberRef.current = fiber

    return () => {
      // Interrupt fiber on cleanup
      if (fiberRef.current) {
        Effect.runPromise(Fiber.interrupt(fiberRef.current))
        fiberRef.current = null
      }
    }
    // hasRuntime transitions false→true once, triggering subscription start
    // runtimeRef.current is intentionally NOT in deps - only hasRuntime matters
  }, [containerId, portId, subscribe, hasRuntime])

  // ─── Operations (fn atoms consumed via useAtomSet) ───

  const doPublish = useAtomSet(portOps.publish)
  const doDestroy = useAtomSet(portOps.destroy)

  const publish = useCallback(
    (payload: T) => {
      doPublish({ containerId, portId: portId as string, payload })
    },
    [containerId, portId, doPublish]
  )

  const clear = useCallback(() => {
    doDestroy({ containerId, portId: portId as string })
    setStreamValue(initialValue)
  }, [containerId, portId, initialValue, doDestroy])

  return {
    value,
    latest,
    hasValue,
    publish,
    clear,
  }
}

return {
    value,
    latest,
    hasValue,
    publish,
    clear,
  }
}

/**
 * Hook to publish to a port without subscribing.
 *
 * @example
 * ```tsx
 * function PublishButton({ containerId }: { containerId: ContainerId }) {
 *   const publish = usePublish<{ action: string }>(containerId, "actions" as PortId)
 *
 *   return (
 *     <button onClick={() => publish({ action: "clicked" })}>
 *       Publish Action
 *     </button>
 *   )
 * }
 * ```
 */
export function usePublish<T>(
  containerId: ContainerId,
  portId: PortId
): (payload: T) => void {
  const doPublish = useAtomSet(portOps.publish)

  return useCallback(
    (payload: T) => {
      doPublish({ containerId, portId: portId as string, payload })
    },
    [containerId, portId, doPublish]
  )
}

