}

/** Anchor point for positioning */
export type Anchor =
  | "top-left"
  | "top-center"
  | "top-right"
  | "center-left"
  | "center"
  | "center-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right"

/** Extended faceplate state with position */
export interface FaceplateStateExtended extends FaceplateState {
  /** Position where faceplate should appear */
