export class OverlayRegistry extends Context.Tag("tmnl/overlays/OverlayRegistry")<
  OverlayRegistry,
  OverlayRegistryOps
>() {
  /**
   * Default implementation using Effect.Ref for state
   */
  static Default = Layer.effect(
    OverlayRegistry,
    Effect.gen(function* () {
      // State: Map of ContainerId -> ContainerState
      const containersRef = yield* Ref.make<Map<ContainerId, ContainerState>>(new Map())

      // ─── Helpers ───

// ─── Helpers ───

      /** Ensure container exists, creating it if necessary */
      const ensureContainer = (id: ContainerId): Effect.Effect<void> =>
        Ref.update(containersRef, (map) => {
          if (map.has(id)) return map
          const next = new Map(map)
          next.set(
            id,
            new ContainerState({
              id,
              activeOverlays: [],
              registeredOverlays: [],
              enabled: true,
            })
          )
          return next
        })

      const updateContainer = (
        id: ContainerId,
        fn: (state: ContainerState) => ContainerState
      ): Effect.Effect<void> =>
        Ref.update(containersRef, (map) => {
          const current = map.get(id)
          if (!current) return map
          const next = new Map(map)
          next.set(id, fn(current))
          return next
        })

      /** Get container, auto-creating if it doesn't exist */
      const getContainerOrCreate = (id: ContainerId): Effect.Effect<ContainerState> =>
        Effect.gen(function* () {
          yield* ensureContainer(id)
          const map = yield* Ref.get(containersRef)
          // Safe to assert non-null after ensureContainer
          return map.get(id)!
        })

      // ─── Implementation ───

      return OverlayRegistry.of({
        // Container Management
        createContainer: (id) =>
          Ref.update(containersRef, (map) => {
            if (map.has(id)) return map // idempotent
            const next = new Map(map)
            next.set(
              id,
              new ContainerState({
                id,
                activeOverlays: [],
                registeredOverlays: [],
                enabled: true,
              })
            )
            return next
          }),

        destroyContainer: (id) =>
          Ref.update(containersRef, (map) => {
            const next = new Map(map)
            next.delete(id)
            return next
          }),

destroyContainer: (id) =>
          Ref.update(containersRef, (map) => {
            const next = new Map(map)
            next.delete(id)
            return next
          }),

        getContainer: (id) =>
          Effect.map(Ref.get(containersRef), (map) => Option.fromNullable(map.get(id))),

        listContainers: () =>
          Effect.map(Ref.get(containersRef), (map) => Array.fromIterable(map.keys())),

        // Overlay Registration
        register: (containerId, overlayId, name, visualPriority = 0) =>
          Effect.gen(function* () {
            // Auto-create container if it doesn't exist
            yield* ensureContainer(containerId)
            yield* updateContainer(containerId, (state) => {
              // Check if already registered
              if (state.registeredOverlays.includes(overlayId)) {
                return state
              }
              return new ContainerState({
                ...state,
                registeredOverlays: [...state.registeredOverlays, overlayId],
              })
            })
          }),

        unregister: (containerId, overlayId) =>
          updateContainer(containerId, (state) => {
            return new ContainerState({
              ...state,
              registeredOverlays: state.registeredOverlays.filter((id) => id !== overlayId),
              activeOverlays: state.activeOverlays.filter((o) => o.id !== overlayId),
            })
          }),

        // Overlay Lifecycle
        enable: (containerId, overlayId) =>
          Effect.gen(function* () {
            // Auto-create container if it doesn't exist
            const container = yield* getContainerOrCreate(containerId)

            // Check if already active
            const existing = container.activeOverlays.find((o) => o.id === overlayId)
            if (existing?.state === "active") return

            yield* updateContainer(containerId, (state) => {
              const existingIdx = state.activeOverlays.findIndex((o) => o.id === overlayId)

yield* updateContainer(containerId, (state) => {
              const existingIdx = state.activeOverlays.findIndex((o) => o.id === overlayId)

              if (existingIdx >= 0) {
                // Already in list, just update state and move to top (LIFO)
                const overlay = state.activeOverlays[existingIdx]
                const withoutOverlay = state.activeOverlays.filter((_, i) => i !== existingIdx)
                const updatedOverlay = new OverlayInstance({
                  ...overlay,
                  state: "active" as OverlayState,
                  activatedAt: Date.now(),
                  stackPosition: withoutOverlay.length,
                })
                return new ContainerState({
                  ...state,
                  activeOverlays: [...withoutOverlay, updatedOverlay],
                })
              }

              // Not in list, create new instance
              // Need to find overlay info from registration
              const newOverlay = new OverlayInstance({
                id: overlayId,
                name: overlayId as string, // Will be replaced with actual name from Overlay class
                state: "active" as OverlayState,
                activatedAt: Date.now(),
                visualPriority: 0,
                stackPosition: state.activeOverlays.length,
              })

              return new ContainerState({
                ...state,
                activeOverlays: [...state.activeOverlays, newOverlay],
              })
            })
          }),

        disable: (containerId, overlayId) =>
          updateContainer(containerId, (state) => {
            const idx = state.activeOverlays.findIndex((o) => o.id === overlayId)
            if (idx < 0) return state

            const overlay = state.activeOverlays[idx]
            const updatedOverlay = new OverlayInstance({
              ...overlay,
              state: "inactive" as OverlayState,
              activatedAt: null,
            })

            // Remove from active list (inactive overlays are not in the stack)
            return new ContainerState({
              ...state,
              activeOverlays: state.activeOverlays.filter((_, i) => i !== idx),
            })
          }),

// Remove from active list (inactive overlays are not in the stack)
            return new ContainerState({
              ...state,
              activeOverlays: state.activeOverlays.filter((_, i) => i !== idx),
            })
          }),

        toggle: (containerId, overlayId) =>
          Effect.gen(function* () {
            const isCurrentlyActive = yield* OverlayRegistry.pipe(
              Effect.flatMap((r) => r.isActive(containerId, overlayId))
            )
            if (isCurrentlyActive) {
              yield* OverlayRegistry.pipe(Effect.flatMap((r) => r.disable(containerId, overlayId)))
            } else {
              yield* OverlayRegistry.pipe(Effect.flatMap((r) => r.enable(containerId, overlayId)))
            }
          }),

        suspend: (containerId, overlayId) =>
          updateContainer(containerId, (state) => {
            const idx = state.activeOverlays.findIndex((o) => o.id === overlayId)
            if (idx < 0) return state

            const overlay = state.activeOverlays[idx]
            if (overlay.state !== "active") return state

            const updatedOverlay = new OverlayInstance({
              ...overlay,
              state: "suspended" as OverlayState,
            })

            const newOverlays = [...state.activeOverlays]
            newOverlays[idx] = updatedOverlay

            return new ContainerState({
              ...state,
              activeOverlays: newOverlays,
            })
          }),

        resume: (containerId, overlayId) =>
          updateContainer(containerId, (state) => {
            const idx = state.activeOverlays.findIndex((o) => o.id === overlayId)
            if (idx < 0) return state

            const overlay = state.activeOverlays[idx]
            if (overlay.state !== "suspended") return state

            const updatedOverlay = new OverlayInstance({
              ...overlay,
              state: "active" as OverlayState,
            })

            const newOverlays = [...state.activeOverlays]
            newOverlays[idx] = updatedOverlay

const updatedOverlay = new OverlayInstance({
              ...overlay,
              state: "active" as OverlayState,
            })

            const newOverlays = [...state.activeOverlays]
            newOverlays[idx] = updatedOverlay

            return new ContainerState({
              ...state,
              activeOverlays: newOverlays,
            })
          }),

        // Query
        getActiveOverlays: (containerId) =>
          Effect.map(Ref.get(containersRef), (map) => {
            const container = map.get(containerId)
            if (!container) return []
            return container.activeOverlays.filter((o) => o.state === "active")
          }),

        isActive: (containerId, overlayId) =>
          Effect.map(Ref.get(containersRef), (map) => {
            const container = map.get(containerId)
            if (!container) return false
            return container.activeOverlays.some(
              (o) => o.id === overlayId && o.state === "active"
            )
          }),

        getOverlay: (containerId, overlayId) =>
          Effect.map(Ref.get(containersRef), (map) => {
            const container = map.get(containerId)
            if (!container) return Option.none()
            return Option.fromNullable(
              container.activeOverlays.find((o) => o.id === overlayId)
            )
          }),
      })
    })
  )
}

/**
 * PortHub Service
 *
 * Typed pub/sub ports for overlay-to-overlay communication.
 * Each container has isolated port namespaces.
 */

import * as Context from "effect/Context"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Ref from "effect/Ref"
import * as PubSub from "effect/PubSub"
import * as Stream from "effect/Stream"
import * as Queue from "effect/Queue"
import * as Option from "effect/Option"
import * as Schema from "effect/Schema"
import type { Scope } from "effect/Scope"
import { type ContainerId, type PortId } from "../schemas"

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

/** Port message envelope */
export interface PortMessage<T = unknown> {
  readonly portId: PortId
  readonly containerId: ContainerId
  readonly payload: T
  readonly timestamp: number
}

/** Internal port state */
interface PortState {
  readonly pubsub: PubSub.PubSub<PortMessage>
  readonly latest: Ref.Ref<Option.Option<PortMessage>>
}

/** Composite key for port lookup */
type PortKey = `${ContainerId}:${PortId}`

const makePortKey = (containerId: ContainerId, portId: PortId): PortKey =>
  `${containerId}:${portId}` as PortKey

// ─────────────────────────────────────────────────────────────
// Service Interface
// ─────────────────────────────────────────────────────────────

/** Operations provided by PortHub */
export interface PortHubOps {
  /**
   * Publish a message to a port.
   * Creates the port if it doesn't exist.
   */
  readonly publish: <T>(
    containerId: ContainerId,
    portId: PortId,
    payload: T
  ) => Effect.Effect<void>

/**
   * Subscribe to a port, receiving a Stream of messages.
   * The stream will emit all messages published after subscription.
   */
  readonly subscribe: <T>(
    containerId: ContainerId,
    portId: PortId
  ) => Effect.Effect<Stream.Stream<T>, never, Scope>

  /**
   * Read the latest value from a port (sync access).
   * Returns None if no message has been published.
   */
  readonly read: <T>(
    containerId: ContainerId,
    portId: PortId
  ) => Effect.Effect<Option.Option<T>>

  /**
   * Read the latest value, failing if no message exists.
   */
  readonly readOrFail: <T>(
    containerId: ContainerId,
    portId: PortId
  ) => Effect.Effect<T, Error>

  /**
   * Check if a port exists.
   */
  readonly hasPort: (
    containerId: ContainerId,
    portId: PortId
  ) => Effect.Effect<boolean>

  /**
   * List all ports in a container.
   */
  readonly listPorts: (containerId: ContainerId) => Effect.Effect<ReadonlyArray<PortId>>

  /**
   * Destroy a port (cleanup).
   */
  readonly destroyPort: (
    containerId: ContainerId,
    portId: PortId
  ) => Effect.Effect<void>

  /**
   * Destroy all ports in a container.
   */
  readonly destroyContainerPorts: (containerId: ContainerId) => Effect.Effect<void>
}

// ─────────────────────────────────────────────────────────────
// Service Tag
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Service Tag
// ─────────────────────────────────────────────────────────────

export class PortHub extends Context.Tag("tmnl/overlays/PortHub")<
  PortHub,
  PortHubOps
>() {
  /**
   * Default implementation using PubSub per port
   */
  static Default = Layer.effect(
    PortHub,
    Effect.gen(function* () {
      // State: Map of PortKey -> PortState
      const portsRef = yield* Ref.make<Map<PortKey, PortState>>(new Map())

      // ─── Helpers ───

      const getOrCreatePort = (
        containerId: ContainerId,
        portId: PortId
      ): Effect.Effect<PortState> =>
        Effect.gen(function* () {
          const key = makePortKey(containerId, portId)
          const ports = yield* Ref.get(portsRef)
          const existing = ports.get(key)

          if (existing) {
            return existing
          }

          // Create new port
          const pubsub = yield* PubSub.unbounded<PortMessage>()
          const latest = yield* Ref.make<Option.Option<PortMessage>>(Option.none())

          const state: PortState = { pubsub, latest }

          yield* Ref.update(portsRef, (map) => {
            const next = new Map(map)
            next.set(key, state)
            return next
          })

          return state
        })

      const getPort = (
        containerId: ContainerId,
        portId: PortId
      ): Effect.Effect<Option.Option<PortState>> =>
        Effect.map(Ref.get(portsRef), (map) =>
          Option.fromNullable(map.get(makePortKey(containerId, portId)))
        )

      // ─── Implementation ───

      return PortHub.of({
        publish: (containerId, portId, payload) =>
          Effect.gen(function* () {
            const port = yield* getOrCreatePort(containerId, portId)

return PortHub.of({
        publish: (containerId, portId, payload) =>
          Effect.gen(function* () {
            const port = yield* getOrCreatePort(containerId, portId)

            const message: PortMessage = {
              portId,
              containerId,
              payload,
              timestamp: Date.now(),
            }

            // Update latest value
            yield* Ref.set(port.latest, Option.some(message))

            // TRACE: Log publish
            yield* Effect.log(`[PORT:PUB] ${containerId}:${portId} payload=${JSON.stringify(payload).slice(0, 100)}`)

            // Publish to subscribers
            yield* PubSub.publish(port.pubsub, message)
          }),

        subscribe: (containerId, portId) =>
          Effect.gen(function* () {
            const port = yield* getOrCreatePort(containerId, portId)

            // TRACE: Log subscription
            yield* Effect.log(`[PORT:SUB] ${containerId}:${portId} subscribed`)

            // Create a subscription queue
            const queue = yield* PubSub.subscribe(port.pubsub)

            // Convert queue to stream, extracting payload
            return Stream.fromQueue(queue).pipe(
              Stream.map((msg) => msg.payload as any)
            )
          }),

        read: (containerId, portId) =>
          Effect.gen(function* () {
            const portOpt = yield* getPort(containerId, portId)

            if (Option.isNone(portOpt)) {
              return Option.none()
            }

            const latest = yield* Ref.get(portOpt.value.latest)
            return Option.map(latest, (msg) => msg.payload as any)
          }),

        readOrFail: (containerId, portId) =>
          Effect.gen(function* () {
            const valueOpt = yield* PortHub.pipe(
              Effect.flatMap((hub) => hub.read(containerId, portId))
            )

            if (Option.isNone(valueOpt)) {
              return yield* Effect.fail(
                new Error(`No value in port: ${containerId}:${portId}`)
              )
            }

if (Option.isNone(valueOpt)) {
              return yield* Effect.fail(
                new Error(`No value in port: ${containerId}:${portId}`)
              )
            }

            return valueOpt.value
          }),

        hasPort: (containerId, portId) =>
          Effect.map(Ref.get(portsRef), (map) =>
            map.has(makePortKey(containerId, portId))
          ),

        listPorts: (containerId) =>
          Effect.map(Ref.get(portsRef), (map) => {
            const prefix = `${containerId}:`
            const ports: PortId[] = []

            for (const key of map.keys()) {
              if (key.startsWith(prefix)) {
                ports.push(key.slice(prefix.length) as PortId)
              }
            }

            return ports
          }),

        destroyPort: (containerId, portId) =>
          Effect.gen(function* () {
            const key = makePortKey(containerId, portId)
            const ports = yield* Ref.get(portsRef)
            const port = ports.get(key)

            if (port) {
              // Shutdown the pubsub
              yield* PubSub.shutdown(port.pubsub)

              // Remove from map
              yield* Ref.update(portsRef, (map) => {
                const next = new Map(map)
                next.delete(key)
                return next
              })
            }
          }),

        destroyContainerPorts: (containerId) =>
          Effect.gen(function* () {
            const ports = yield* Ref.get(portsRef)
            const prefix = `${containerId}:`

            // Find all ports for this container
            const toRemove: PortKey[] = []
            for (const [key, port] of ports.entries()) {
              if (key.startsWith(prefix)) {
                toRemove.push(key)
                yield* PubSub.shutdown(port.pubsub)
              }
            }

// Remove from map
            yield* Ref.update(portsRef, (map) => {
              const next = new Map(map)
              for (const key of toRemove) {
                next.delete(key)
              }
              return next
            })
          }),
      })
    })
  )
}

