 * - CommandPalette = specific use case (M-x with CommandProvider)
 *
 * @example
 * ```tsx
 * const palette = useCommandPalette()
 *
 * // Open command palette
 * <button onClick={palette.open}>Commands</button>
 *
 * // Or toggle
 * <button onClick={palette.toggle}>CMD</button>
 * ```
