  const isMounted = useCallback(
    (id: VisualOverlayId): boolean => {
      const overlay = overlays.get(id)
      return overlay !== undefined && overlay.isVisible
    },
    [overlays]
  )

  return useMemo(
    () => ({
      mount,
      unmount,
      isMounted,
