/**
 * Drawer Renderer Types
 *
 * Shared types for the directional drawer renderer system.
 *
 * @module
 */

import type { Transition, Variants } from "framer-motion"
import type { CSSProperties, ReactNode } from "react"
import type { VisualOverlayId, DrawerConfig, OverlaySide } from "../../../schemas/visual"

// ─────────────────────────────────────────────────────────────
// Base Props
// ─────────────────────────────────────────────────────────────

export interface DrawerRendererProps {
  /** Overlay ID */
  id: VisualOverlayId
  /** Callback when close requested (backdrop click, escape) */
  onCloseRequest?: () => void
}

// ─────────────────────────────────────────────────────────────
// Directional Configuration
// ─────────────────────────────────────────────────────────────

/**
 * Directional drawer configuration.
 * Each side (left, right, top, bottom) provides its own:
 * - Animation variants (how it enters/exits)
 * - Container styles (positioning, sizing)
 * - Spring config (optional override)
 */
export interface DirectionalDrawerConfig {
  /** Framer-motion variants for enter/exit */
  variants: Variants
  /** Container positioning styles */
  containerStyles: (config: DrawerConfig) => CSSProperties
  /** Optional spring config override */
  springConfig?: Transition
}

/**
 * Registry of directional configs keyed by side.
 */
export type DirectionalConfigRegistry = Record<OverlaySide, DirectionalDrawerConfig>

// ─────────────────────────────────────────────────────────────
// Hook Return Type
// ─────────────────────────────────────────────────────────────

export interface UseDrawerRendererReturn {
  /** Should render anything? */
  shouldRender: boolean
  /** Drawer config (if available) */
  config: DrawerConfig | null
  /** Content to render */
  content: ReactNode
  /** Is visible (entering or visible state) */
  isVisible: boolean
  /** Handle animation complete */
  handleAnimationComplete: (definition: string) => void
  /** Handle backdrop click */
  handleBackdropClick: () => void
}

/**
 * useDrawerRenderer Hook
 *
 * Base hook for drawer rendering logic. Encapsulates:
 * - Overlay state subscription
 * - Escape key handling
 * - Animation state transitions
 * - Backdrop click handling
 *
 * Directional renderers compose this hook with their specific
 * animation variants and positioning styles.
 *
 * @module
 */

import { useEffect, useCallback } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import { useVisualOverlaySafe } from "../../providers"
import {
  overlayAtom,
  getContent,
  isSuppressedAtom,
} from "../../../atoms"
import type { VisualOverlayId, DrawerConfig } from "../../../schemas/visual"
import type { UseDrawerRendererReturn } from "./types"

// ─────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────

export function useDrawerRenderer(
  id: VisualOverlayId,
  onCloseRequest?: () => void
): UseDrawerRendererReturn {
  const ctx = useVisualOverlaySafe()
  const overlay = useAtomValue(overlayAtom(id))
  const isSuppressed = useAtomValue(isSuppressedAtom({ type: "drawer", id }))

  // ─── Escape Key Handler ─────────────────────────────────────
  useEffect(() => {
    if (!overlay || !overlay.isVisible) return

    const config = overlay.config as DrawerConfig
    if (!config.closeOnEscape) return

    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault()
        onCloseRequest?.()
      }
    }

    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [overlay, onCloseRequest])

  // ─── Animation Complete Handler ─────────────────────────────
  const handleAnimationComplete = useCallback(
    (definition: string) => {
      if (!ctx || !overlay) return

// ─── Animation Complete Handler ─────────────────────────────
  const handleAnimationComplete = useCallback(
    (definition: string) => {
      if (!ctx || !overlay) return

      if (definition === "visible" && overlay.animationState === "entering") {
        ctx.setAnimationState(id, "visible")
      }
      if (definition === "hidden" && overlay.animationState === "exiting") {
        ctx.setAnimationState(id, "exited")
      }
    },
    [ctx, overlay, id]
  )

  // ─── Backdrop Click Handler ─────────────────────────────────
  const handleBackdropClick = useCallback(() => {
    if (!overlay) return
    const config = overlay.config as DrawerConfig
    if (config.closeOnOverlayClick) {
      onCloseRequest?.()
    }
  }, [overlay, onCloseRequest])

  // ─── Early Returns ──────────────────────────────────────────
  if (!overlay || isSuppressed) {
    return {
      shouldRender: false,
      config: null,
      content: null,
      isVisible: false,
      handleAnimationComplete,
      handleBackdropClick,
    }
  }

  const config = overlay.config as DrawerConfig
  const content = getContent(overlay.contentKey)
  const isVisible =
    overlay.animationState === "visible" ||
    overlay.animationState === "entering"

  return {
    shouldRender: true,
    config,
    content,
    isVisible,
    handleAnimationComplete,
    handleBackdropClick,
  }
}

/**
 * Global Slot Component
 *
 * Full-viewport slot for global overlays (drawer, modal, toast, command-palette).
 * Mount at app root to enable visual overlay rendering.
 *
 * Uses proper renderers for each overlay type:
 * - DrawerRenderer for drawers (slide animations, backdrop)
 * - ModalRenderer for modals (centered, backdrop)
 * - etc.
 *
 * @module
 */

import { useRef, useEffect } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import { useVisualOverlaySafe } from "../providers"
import { overlaysByTypeAtom } from "../../atoms"
import { GLOBAL_SLOT_ID } from "../constants"
import { DrawerRenderer } from "../renderers/DrawerRenderer"
import { ModalRenderer } from "../renderers/ModalRenderer"
import { ToastRenderer } from "../renderers/ToastRenderer"
import { CommandPaletteRenderer } from "../renderers/CommandPaletteRenderer"
import { SidebarRenderer } from "../renderers/SidebarRenderer"
import type { VisualOverlayInstance, VisualOverlayType } from "../../schemas/visual"

// ─────────────────────────────────────────────────────────────
// Styles
// ─────────────────────────────────────────────────────────────

const containerStyles: React.CSSProperties = {
  position: "fixed",
  inset: 0,
  pointerEvents: "none",
  zIndex: 1000, // Above content, below overlays
}

// ─────────────────────────────────────────────────────────────
// Type Layer (renders all overlays of a type using proper renderer)
// ─────────────────────────────────────────────────────────────

interface TypeLayerProps {
  type: VisualOverlayType
  onCloseRequest?: (id: string) => void
}

function TypeLayer({ type, onCloseRequest }: TypeLayerProps) {
  const overlays = useAtomValue(overlaysByTypeAtom(type))

  if (overlays.length === 0) return null

function TypeLayer({ type, onCloseRequest }: TypeLayerProps) {
  const overlays = useAtomValue(overlaysByTypeAtom(type))

  if (overlays.length === 0) return null

  return (
    <>
      {overlays.map((overlay) => {
        // Use the appropriate renderer for each type
        switch (type) {
          case "drawer":
            return (
              <DrawerRenderer
                key={overlay.id}
                id={overlay.id}
                onCloseRequest={() => onCloseRequest?.(overlay.id)}
              />
            )
          case "modal":
            return (
              <ModalRenderer
                key={overlay.id}
                id={overlay.id}
                onCloseRequest={() => onCloseRequest?.(overlay.id)}
              />
            )
          case "toast":
            return (
              <ToastRenderer
                key={overlay.id}
                id={overlay.id}
                onDismiss={() => onCloseRequest?.(overlay.id)}
              />
            )
          case "command-palette":
            return (
              <CommandPaletteRenderer
                key={overlay.id}
                id={overlay.id}
                onCloseRequest={() => onCloseRequest?.(overlay.id)}
              />
            )
          case "sidebar":
            return (
              <SidebarRenderer
                key={overlay.id}
                id={overlay.id}
              />
            )
          default:
            // Fallback: render nothing for unhandled types
            return null
        }
      })}
    </>
  )
}

// ─────────────────────────────────────────────────────────────
// Global Slot Component
// ─────────────────────────────────────────────────────────────

export interface GlobalSlotProps {
  /** Custom container ID for testing */
  containerId?: string
}

/**
 * GlobalSlot
 *
 * Renders all global-only overlay types using proper renderers.
 * Position at app root, outside router but inside VisualOverlayProvider.
 */
export function GlobalSlot({ containerId = "tmnl-global-slot" }: GlobalSlotProps) {
  const ctx = useVisualOverlaySafe()
  const containerRef = useRef<HTMLDivElement>(null)

// Register slot on mount
  useEffect(() => {
    if (!ctx || !containerRef.current) return

    ctx.registerSlot(GLOBAL_SLOT_ID, containerId)

    return () => {
      ctx.unregisterSlot(GLOBAL_SLOT_ID)
    }
  }, [ctx, containerId])

  // Close request handler
  const handleCloseRequest = (id: string) => {
    ctx?.close(id as any)
  }

  // GlobalSlot is ALWAYS pointer-events: none
  // Individual renderers handle their own pointer-events
  // This allows clicks to pass through to content behind

  return (
    <div
      ref={containerRef}
      id={containerId}
      style={containerStyles}
      data-overlay-slot="global"
    >
      {/* Render each global overlay type in z-order (low to high) */}
      <TypeLayer type="sidebar" onCloseRequest={handleCloseRequest} />
      <TypeLayer type="drawer" onCloseRequest={handleCloseRequest} />
      <TypeLayer type="toast" onCloseRequest={handleCloseRequest} />
      <TypeLayer type="modal" onCloseRequest={handleCloseRequest} />
      <TypeLayer type="command-palette" onCloseRequest={handleCloseRequest} />
    </div>
  )
}

export default GlobalSlot

/**
 * Panel Slot Component
 *
 * Panel-scoped slot for drawer and sidebar overlays.
 * Use to render overlays within a specific panel's bounds.
 *
 * @example
 * ```tsx
 * function EditorPanel() {
 *   return (
 *     <div className="relative h-full">
 *       <PanelSlot slotId="editor-panel" />
 *       <Editor />
 *     </div>
 *   )
 * }
 *
 * // Then open drawer scoped to this panel:
 * drawer.open({ slot: "editor-panel", side: "right" }, <PropertiesPanel />)
 * ```
 *
 * @module
 */

import { useRef, useEffect, useCallback } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import { useVisualOverlaySafe } from "../providers"
import {
  overlayRegistry,
  overlaysBySlotAtom,
  getContent,
} from "../../atoms"
import { isReservedSlotId } from "../constants"
import type { SlotId, VisualOverlayInstance } from "../../schemas/visual"

// ─────────────────────────────────────────────────────────────
// Styles
// ─────────────────────────────────────────────────────────────

const containerStyles: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  pointerEvents: "none",
  overflow: "hidden",
}

const overlayWrapperStyles = (zIndex: number, pointerEvents: boolean): React.CSSProperties => ({
  position: "absolute",
  inset: 0,
  zIndex,
  pointerEvents: pointerEvents ? "auto" : "none",
})

// ─────────────────────────────────────────────────────────────
// Overlay Wrapper
// ─────────────────────────────────────────────────────────────

interface OverlayWrapperProps {
  overlay: VisualOverlayInstance
  onAnimationEnd?: (id: string, state: "visible" | "exited") => void
}

function OverlayWrapper({ overlay, onAnimationEnd }: OverlayWrapperProps) {
  const content = getContent(overlay.contentKey)

function OverlayWrapper({ overlay, onAnimationEnd }: OverlayWrapperProps) {
  const content = getContent(overlay.contentKey)

  useEffect(() => {
    if (overlay.animationState === "entering") {
      const timer = setTimeout(() => {
        onAnimationEnd?.(overlay.id, "visible")
      }, 50)
      return () => clearTimeout(timer)
    }
  }, [overlay.animationState, overlay.id, onAnimationEnd])

  if (!content) return null

  return (
    <div
      style={overlayWrapperStyles(overlay.zIndex, overlay.isVisible)}
      data-overlay-id={overlay.id}
      data-overlay-type={overlay.type}
      data-overlay-state={overlay.animationState}
    >
      {content}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────
// Panel Slot Component
// ─────────────────────────────────────────────────────────────

export interface PanelSlotProps {
  /** Unique slot identifier (cannot be "global") */
  slotId: SlotId
  /** Container ID for the panel */
  containerId?: string
  /** CSS class for the slot container */
  className?: string
}

/**
 * PanelSlot
 *
 * Renders overlays scoped to a specific panel (drawer, sidebar).
 * Tracks panel bounds via ResizeObserver for proper positioning.
 */
export function PanelSlot({
  slotId,
  containerId,
  className,
}: PanelSlotProps) {
  const ctx = useVisualOverlaySafe()
  const containerRef = useRef<HTMLDivElement>(null)

  // Validate slot ID
  if (isReservedSlotId(slotId)) {
    console.warn(`PanelSlot: "${slotId}" is a reserved slot ID. Use a different ID.`)
    return null
  }

  // Get overlays for this slot
  const overlays = useAtomValue(overlaysBySlotAtom(slotId), {
    registry: overlayRegistry,
  })

  // Update bounds on resize
  const updateBounds = useCallback(() => {
    if (!ctx || !containerRef.current) return

// Update bounds on resize
  const updateBounds = useCallback(() => {
    if (!ctx || !containerRef.current) return

    const rect = containerRef.current.getBoundingClientRect()
    ctx.updateSlotBounds(slotId, {
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
    })
  }, [ctx, slotId])

  // Register slot and observe resize
  useEffect(() => {
    if (!ctx || !containerRef.current) return

    const container = containerRef.current
    const rect = container.getBoundingClientRect()

    // Register with initial bounds
    ctx.registerSlot(slotId, containerId ?? `panel-${slotId}`, {
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
    })

    // Observe resize
    const observer = new ResizeObserver(updateBounds)
    observer.observe(container)

    return () => {
      observer.disconnect()
      ctx.unregisterSlot(slotId)
    }
  }, [ctx, slotId, containerId, updateBounds])

  // Animation end handler
  const handleAnimationEnd = (id: string, state: "visible" | "exited") => {
    if (!ctx) return
    ctx.setAnimationState(id as any, state)
  }

  const hasVisibleOverlays = overlays.some((o) => o.isVisible)

  return (
    <div
      ref={containerRef}
      className={className}
      style={{
        ...containerStyles,
        pointerEvents: hasVisibleOverlays ? "auto" : "none",
      }}
      data-overlay-slot={slotId}
    >
      {overlays.map((overlay) => (
        <OverlayWrapper
          key={overlay.id}
          overlay={overlay}
          onAnimationEnd={handleAnimationEnd}
        />
      ))}
    </div>
  )
}

