  /**
   * Check if a specific index exists
   */
  readonly hasIndex: (name: string) => Effect.Effect<boolean, RagError>;

  /**
   * Format search results as context for LLM injection
   */
  readonly formatContext: (response: SearchResponse) => string;
}

