/**
 * Grid column configuration stored in Schema annotations
 */
export interface GridColumnAnnotation {
  /** Column width in pixels */
  width?: number
  /** Minimum width */
  minWidth?: number
  /** Maximum width */
  maxWidth?: number
  /** Pin to left or right */
  pinned?: 'left' | 'right' | null
