  columnGroup?: string
  /** Suppress auto-sizing */
  suppressSizeToFit?: boolean
  /** Sort direction */
  sort?: 'asc' | 'desc' | null
  /** Editable */
  editable?: boolean
}

// Annotation symbol for type safety
const GridAnnotationId: unique symbol = Symbol.for('@gbg/grid')

