      })

      expect(result.current.isActive).toBe(true)

      unmount()

      expect(removeEventListenerSpy).toHaveBeenCalled()
    })
  })
})

/**
 * ScreensaverOverlay Component
 *
 * Fullscreen overlay that renders the ASCII art screensaver.
 * Handles fade-in/fade-out transitions.
 *
 * @module
 */

import { useEffect, useState, Suspense } from "react"
import { AsciiScene } from "@/components/splash/aberration"
import { DebugScope } from "@/lib/debug"

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface ScreensaverOverlayProps {
  /** Whether the screensaver is active */
  isActive: boolean
  /** Fade-in duration in ms */
  fadeInDuration?: number
  /** Fade-out duration in ms */
  fadeOutDuration?: number
  /** Called when fade-out completes */
  onFadeOutComplete?: () => void
  /** Enable debug logging via DebugScope */
  debug?: boolean
}

// ─────────────────────────────────────────────────────────────────────────────
// Loading Fallback
// ─────────────────────────────────────────────────────────────────────────────

function LoadingFallback() {
  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        backgroundColor: "#0a0a0a",
        color: "#3a3a3a",
        fontFamily: "monospace",
        fontSize: "14px",
      }}
    >
      INITIALIZING...
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export function ScreensaverOverlay({
  isActive,
  fadeInDuration = 500,
  fadeOutDuration = 300,
  onFadeOutComplete,
  debug = false,
}: ScreensaverOverlayProps) {
  // Track whether we should render (for fade-out animation)
  const [shouldRender, setShouldRender] = useState(false)
  const [opacity, setOpacity] = useState(0)

useEffect(() => {
    if (isActive) {
      // Start rendering, then fade in
      setShouldRender(true)
      // Small delay to ensure DOM is ready
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setOpacity(1)
        })
      })
    } else if (shouldRender) {
      // Fade out, then stop rendering
      setOpacity(0)
      const timer = setTimeout(() => {
        setShouldRender(false)
        onFadeOutComplete?.()
      }, fadeOutDuration)
      return () => clearTimeout(timer)
    }
  }, [isActive, shouldRender, fadeOutDuration, onFadeOutComplete])

  if (!shouldRender) return null

  return (
    <>
      <DebugScope
        debug={debug}
        name="ScreensaverOverlay"
        watch={{ isActive, opacity, shouldRender }}
      />
      <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 9999,
        opacity,
        transition: `opacity ${isActive ? fadeInDuration : fadeOutDuration}ms ease-in-out`,
        pointerEvents: isActive ? "auto" : "none",
        cursor: "none", // Hide cursor during screensaver
      }}
      aria-hidden="true"
      data-screensaver
    >
      <Suspense fallback={<LoadingFallback />}>
        <AsciiScene />
      </Suspense>

      {/* Subtle hint to dismiss */}
      <div
        style={{
          position: "absolute",
          bottom: 24,
          left: "50%",
          transform: "translateX(-50%)",
          color: "rgba(255, 255, 255, 0.2)",
          fontFamily: "monospace",
          fontSize: "12px",
          letterSpacing: "0.1em",
          textTransform: "uppercase",
          pointerEvents: "none",
          userSelect: "none",
        }}
      >
        Press any key to dismiss
      </div>
    </div>
    </>
  )
}

/**
 * useIdleDetection Hook
 *
 * Detects user inactivity and triggers callback after timeout.
 * Resets on any user input (mouse, keyboard, touch, scroll).
 *
 * @module
 */

import { useState, useEffect, useCallback, useRef } from "react"

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface IdleDetectionOptions {
  /** Idle timeout in milliseconds (default: 60000 = 1 minute) */
  timeout?: number
  /** Events to track for activity (default: all standard input events) */
  events?: string[]
  /** Whether detection is enabled (default: true) */
  enabled?: boolean
  /** Callback when idle state is entered */
  onIdle?: () => void
  /** Callback when activity resumes */
  onActive?: () => void
}

export interface IdleDetectionState {
  /** Whether user is currently idle */
  isIdle: boolean
  /** Time remaining until idle (ms) */
  timeRemaining: number
  /** Last activity timestamp */
  lastActivity: number
  /** Reset the idle timer manually */
  reset: () => void
}

// ─────────────────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────────────────

const DEFAULT_TIMEOUT = 60_000 // 1 minute

const DEFAULT_EVENTS = [
  "mousemove",
  "mousedown",
  "keydown",
  "touchstart",
  "scroll",
  "wheel",
]

// ─────────────────────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────────────────────

export function useIdleDetection(options: IdleDetectionOptions = {}): IdleDetectionState {
  const {
    timeout = DEFAULT_TIMEOUT,
    events = DEFAULT_EVENTS,
    enabled = true,
    onIdle,
    onActive,
  } = options

export function useIdleDetection(options: IdleDetectionOptions = {}): IdleDetectionState {
  const {
    timeout = DEFAULT_TIMEOUT,
    events = DEFAULT_EVENTS,
    enabled = true,
    onIdle,
    onActive,
  } = options

  const [isIdle, setIsIdle] = useState(false)
  const [lastActivity, setLastActivity] = useState(Date.now())
  const [timeRemaining, setTimeRemaining] = useState(timeout)

  const timeoutRef = useRef<NodeJS.Timeout | null>(null)
  const intervalRef = useRef<NodeJS.Timeout | null>(null)
  const onIdleRef = useRef(onIdle)
  const onActiveRef = useRef(onActive)

  // Keep callback refs fresh
  onIdleRef.current = onIdle
  onActiveRef.current = onActive

  const reset = useCallback(() => {
    const now = Date.now()
    setLastActivity(now)
    setTimeRemaining(timeout)

    // If was idle, trigger onActive
    setIsIdle((prev) => {
      if (prev) {
        onActiveRef.current?.()
      }
      return false
    })

    // Clear and restart timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }

    if (enabled) {
      timeoutRef.current = setTimeout(() => {
        setIsIdle(true)
        setTimeRemaining(0)
        onIdleRef.current?.()
      }, timeout)
    }
  }, [timeout, enabled])

  // Activity handler
  const handleActivity = useCallback(() => {
    reset()
  }, [reset])

  // Set up event listeners
  useEffect(() => {
    if (!enabled) {
      // Clear timers when disabled
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
      if (intervalRef.current) clearInterval(intervalRef.current)
      setIsIdle(false)
      return
    }

    // Initial timeout
    timeoutRef.current = setTimeout(() => {
      setIsIdle(true)
      setTimeRemaining(0)
      onIdleRef.current?.()
    }, timeout)

// Initial timeout
    timeoutRef.current = setTimeout(() => {
      setIsIdle(true)
      setTimeRemaining(0)
      onIdleRef.current?.()
    }, timeout)

    // Update time remaining every second
    intervalRef.current = setInterval(() => {
      setTimeRemaining((prev) => Math.max(0, prev - 1000))
    }, 1000)

    // Add event listeners
    events.forEach((event) => {
      window.addEventListener(event, handleActivity, { passive: true })
    })

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
      if (intervalRef.current) clearInterval(intervalRef.current)
      events.forEach((event) => {
        window.removeEventListener(event, handleActivity)
      })
    }
  }, [timeout, events, enabled, handleActivity])

  return {
    isIdle,
    timeRemaining,
    lastActivity,
    reset,
  }
}

/**
 * useScreensaver Hook
 *
 * Combines idle detection with screensaver overlay state.
 * Provides show/hide controls and configuration.
 *
 * Uses overlayRegistry directly for atom access (not RegistryContext)
 * because commands write to the global singleton registry.
 *
 * @module
 */

import { useState, useCallback, useEffect, useSyncExternalStore } from "react"
import { useIdleDetection } from "./useIdleDetection"
import { forceScreensaverAtom, screensaverEnabledAtom } from "../atoms"
import { overlayRegistry } from "@/lib/overlays/atoms"

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface ScreensaverConfig {
  /** Idle timeout before screensaver activates (ms). Default: 60000 (1 min) */
  idleTimeout?: number
  /** Whether screensaver is enabled. Default: true */
  enabled?: boolean
  /** Fade-in duration (ms). Default: 500 */
  fadeInDuration?: number
  /** Fade-out duration (ms). Default: 300 */
  fadeOutDuration?: number
}

export interface UseScreensaverReturn {
  /** Whether screensaver is currently visible */
  isActive: boolean
  /** Whether screensaver is enabled */
  isEnabled: boolean
  /** Time remaining until activation (ms) */
  timeRemaining: number
  /** Manually show screensaver */
  show: () => void
  /** Dismiss screensaver */
  dismiss: () => void
  /** Toggle enabled state */
  toggleEnabled: () => void
  /** Update configuration */
  configure: (config: Partial<ScreensaverConfig>) => void
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────────────────────

export function useScreensaver(initialConfig: ScreensaverConfig = {}): UseScreensaverReturn {
  const [config, setConfig] = useState<ScreensaverConfig>({
    idleTimeout: 60_000,
    enabled: true,
    fadeInDuration: 500,
    fadeOutDuration: 300,
    ...initialConfig,
  })

  const [isActive, setIsActive] = useState(false)

  // Subscribe to global atoms via overlayRegistry directly
  // (Commands write to overlayRegistry, not RegistryContext)
  const forceScreensaver = useSyncExternalStore(
    (callback) => overlayRegistry.subscribe(forceScreensaverAtom, callback),
    () => overlayRegistry.get(forceScreensaverAtom)
  )
  const globalEnabled = useSyncExternalStore(
    (callback) => overlayRegistry.subscribe(screensaverEnabledAtom, callback),
    () => overlayRegistry.get(screensaverEnabledAtom)
  )

  const { isIdle, timeRemaining, reset } = useIdleDetection({
    timeout: config.idleTimeout,
    enabled: config.enabled && globalEnabled,
    onIdle: () => setIsActive(true),
    onActive: () => {}, // We handle dismiss separately for fade-out
  })

  // Watch forceScreensaverAtom for external triggers (e.g., from commands)
  useEffect(() => {
    if (forceScreensaver) {
      setIsActive(true)
    }
  }, [forceScreensaver])

  // Dismiss handler - called on any input when screensaver is active
  const dismiss = useCallback(() => {
    if (isActive) {
      setIsActive(false)
      overlayRegistry.set(forceScreensaverAtom, false) // Reset force atom
      reset()
    }
  }, [isActive, reset])

  // Manual show
  const show = useCallback(() => {
    setIsActive(true)
  }, [])

// Manual show
  const show = useCallback(() => {
    setIsActive(true)
  }, [])

  // Toggle enabled
  const toggleEnabled = useCallback(() => {
    setConfig((prev) => ({ ...prev, enabled: !prev.enabled }))
  }, [])

  // Update config
  const configure = useCallback((updates: Partial<ScreensaverConfig>) => {
    setConfig((prev) => ({ ...prev, ...updates }))
  }, [])

  // Listen for dismiss events when active
  useEffect(() => {
    if (!isActive) return

    const handleDismiss = () => dismiss()

    // Dismiss on any of these events
    const dismissEvents = ["mousedown", "keydown", "touchstart"]
    dismissEvents.forEach((event) => {
      window.addEventListener(event, handleDismiss, { once: true })
    })

    return () => {
      dismissEvents.forEach((event) => {
        window.removeEventListener(event, handleDismiss)
      })
    }
  }, [isActive, dismiss])

  return {
    isActive,
    isEnabled: config.enabled ?? true,
    timeRemaining,
    show,
    dismiss,
    toggleEnabled,
    configure,
  }
}

/**
 * TMNL Search — FlexSearch Driver
 *
 * Stream-first search implementation using FlexSearch Document index.
 * Optimized for 5000+ item collections with progressive result emission.
 */

import { Effect, Ref, Stream } from 'effect'
import { Document, Charset } from 'flexsearch'
import type {
  SearchServiceImpl,
  SearchResult,
  SearchOptions,
  SearchStats,
  SearchError,
  IndexConfig,
  Indexable,
  FieldConfig,
} from '../types'

// ─────────────────────────────────────────────────────────────────────────────
// FlexSearch State
// ─────────────────────────────────────────────────────────────────────────────

interface FlexSearchState<T extends Indexable> {
  index: Document<T> | null
  config: IndexConfig<T> | null
  items: Map<string | number, T>
  itemCount: number
  lastUpdated: number
}

// ─────────────────────────────────────────────────────────────────────────────
// Driver Factory
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a FlexSearch-backed search service with Stream emission
 */
export const createFlexSearchDriver = <T extends Indexable>(): Effect.Effect<
  SearchServiceImpl<T>,
  never,
  never
> =>
  Effect.gen(function* () {
    // Internal state
    const stateRef = yield* Ref.make<FlexSearchState<T>>({
      index: null,
      config: null,
      items: new Map(),
      itemCount: 0,
      lastUpdated: 0,
    })

    // ─────────────────────────────────────────────────────────────────────────
    // Helpers
    // ─────────────────────────────────────────────────────────────────────────

    const getIndex = (): Effect.Effect<Document<T>, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        if (!state.index) {
          return yield* Effect.fail({
            _tag: 'IndexNotReady' as const,
            message: 'Index not initialized. Call index() first.',
          })
        }
        return state.index
      })

const getItems = (): Effect.Effect<Map<string | number, T>, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        return state.items
      })

    const normalizeFieldConfig = (
      field: keyof T | FieldConfig
    ): { field: string; tokenize: string; weight: number } => {
      if (typeof field === 'string') {
        return { field: field as string, tokenize: 'forward', weight: 1 }
      }
      return {
        field: field.field,
        tokenize: field.tokenize ?? 'forward',
        weight: field.weight ?? 1,
      }
    }

    /**
     * Map FlexSearch results to SearchResult format
     */
    const mapFlexSearchResults = (
      results: unknown,
      items: Map<string | number, T>
    ): SearchResult<T>[] => {
      if (!Array.isArray(results)) return []

      const seen = new Set<string | number>()
      const mapped: SearchResult<T>[] = []

      for (const fieldResult of results) {
        const fr = fieldResult as {
          field: string
          result: Array<{ id: string | number; doc?: T } | string | number>
        }
        if (!fr.result) continue

        for (let i = 0; i < fr.result.length; i++) {
          const entry = fr.result[i]
          const id =
            typeof entry === 'object' && entry !== null
              ? (entry as { id: string | number }).id
              : entry
          const doc =
            typeof entry === 'object' && entry !== null
              ? (entry as { doc?: T }).doc
              : undefined

          if (seen.has(id)) continue
          seen.add(id)

          const item = doc ?? items.get(id)
          if (!item) continue

          // Score based on position (higher position = better match)
          const score = 1 - i / Math.max(fr.result.length, 1)

const item = doc ?? items.get(id)
          if (!item) continue

          // Score based on position (higher position = better match)
          const score = 1 - i / Math.max(fr.result.length, 1)

          mapped.push({
            item,
            score,
            matches: [{ field: fr.field }],
          })
        }
      }

      // Sort by score descending
      return mapped.sort((a, b) => b.score - a.score)
    }

    /**
     * Execute FlexSearch and return results as Effect
     */
    const executeSearch = (
      query: string,
      options?: SearchOptions
    ): Effect.Effect<SearchResult<T>[], SearchError> =>
      Effect.gen(function* () {
        if (!query.trim()) {
          return []
        }

        const flexIndex = yield* getIndex()
        const items = yield* getItems()

        // Build search options
        const searchOpts: Record<string, unknown> = {
          query,
          limit: options?.limit ?? 100,
          enrich: true,
          suggest: options?.suggest ?? false,
        }

        // Field filtering
        if (options?.fields && options.fields.length > 0) {
          searchOpts.index = options.fields
        }

        const results = flexIndex.search(searchOpts)
        let mapped = mapFlexSearchResults(results, items)

        // Apply boost weights
        if (options?.boost) {
          mapped = mapped.map((r) => {
            let boostMultiplier = 1
            for (const match of r.matches ?? []) {
              const boost = options.boost?.[match.field]
              if (boost) boostMultiplier *= boost
            }
            return { ...r, score: r.score * boostMultiplier }
          })
          mapped = [...mapped].sort((a, b) => b.score - a.score)
        }

        // Apply limit
        if (options?.limit) {
          mapped = mapped.slice(0, options.limit)
        }

        return mapped
      })

// Apply limit
        if (options?.limit) {
          mapped = mapped.slice(0, options.limit)
        }

        return mapped
      })

    // ─────────────────────────────────────────────────────────────────────────
    // Mutations (Effect - one-shot)
    // ─────────────────────────────────────────────────────────────────────────

    const index = (
      inputItems: readonly T[],
      config: IndexConfig<T>
    ): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const fields = config.fields.map(normalizeFieldConfig)
        const idField = (config.idField as string) ?? 'id'

        // Build FlexSearch document descriptor
        const documentDescriptor = {
          id: idField,
          store: config.store ?? true,
          index: fields.map((f) => ({
            field: f.field,
            tokenize: f.tokenize as 'strict' | 'forward' | 'reverse' | 'full',
            encoder: Charset.LatinBalance,
          })),
        }

        const flexIndex = new Document<T>({
          // @ts-expect-error - FlexSearch types are incomplete
          fastupdate: true,
          document: documentDescriptor,
        })

        // Build lookup map
        const itemMap = new Map<string | number, T>()

        // Index all items
        for (const item of inputItems) {
          const id = item[idField as keyof T] as string | number
          itemMap.set(id, item)
          flexIndex.add(item)
        }

        yield* Ref.set(stateRef, {
          index: flexIndex,
          config,
          items: itemMap,
          itemCount: inputItems.length,
          lastUpdated: Date.now(),
        })
      }).pipe(
        Effect.catchAll((error) =>
          Effect.fail({
            _tag: 'IndexError' as const,
            message: 'Failed to create index',
            cause: error,
          })
        )
      )

const add = (item: T): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const flexIndex = yield* getIndex()
        const state = yield* Ref.get(stateRef)
        const idField = (state.config?.idField as string) ?? 'id'
        const id = item[idField as keyof T] as string | number

        flexIndex.add(item)
        state.items.set(id, item)

        yield* Ref.update(stateRef, (s) => ({
          ...s,
          itemCount: s.itemCount + 1,
          lastUpdated: Date.now(),
        }))
      })

    const update = (item: T): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const flexIndex = yield* getIndex()
        const state = yield* Ref.get(stateRef)
        const idField = (state.config?.idField as string) ?? 'id'
        const id = item[idField as keyof T] as string | number

        flexIndex.update(item)
        state.items.set(id, item)

        yield* Ref.update(stateRef, (s) => ({
          ...s,
          lastUpdated: Date.now(),
        }))
      })

    const remove = (id: string | number): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const flexIndex = yield* getIndex()
        const state = yield* Ref.get(stateRef)

        flexIndex.remove(id)
        state.items.delete(id)

        yield* Ref.update(stateRef, (s) => ({
          ...s,
          itemCount: Math.max(0, s.itemCount - 1),
          lastUpdated: Date.now(),
        }))
      })

    // ─────────────────────────────────────────────────────────────────────────
    // Queries (Stream - progressive, cancellable)
    // ─────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────
    // Queries (Stream - progressive, cancellable)
    // ─────────────────────────────────────────────────────────────────────────

    const search = (
      query: string,
      options?: SearchOptions
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      Stream.unwrap(
        Effect.gen(function* () {
          const results = yield* executeSearch(query, options)
          const chunkSize = options?.chunkSize ?? 10

          // Emit results progressively in chunks
          return Stream.fromIterable(results).pipe(
            // Group into chunks for batched UI updates
            Stream.grouped(chunkSize),
            // Flatten chunks back to individual results
            Stream.flatMap((chunk) => Stream.fromIterable(chunk))
          )
        })
      )

    const prefix = (
      query: string,
      options?: Omit<SearchOptions, 'strategy'>
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      // FlexSearch with forward tokenizer naturally supports prefix
      search(query, { ...options, strategy: 'prefix' })

    const fuzzy = (
      query: string,
      options?: Omit<SearchOptions, 'strategy'>
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      // FlexSearch suggest mode provides fuzzy-like behavior
      search(query, { ...options, suggest: true, strategy: 'fuzzy' })

    // ─────────────────────────────────────────────────────────────────────────
    // Admin (Effect - one-shot)
    // ─────────────────────────────────────────────────────────────────────────

    const stats = (): Effect.Effect<SearchStats, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        const config = state.config

        return {
          itemCount: state.itemCount,
          fieldCount: config?.fields.length ?? 0,
          lastUpdated: state.lastUpdated || undefined,
          // Memory estimation: ~1KB per item for moderate-sized documents
          memoryUsage: state.itemCount * 1024,
        }
      })

/**
 * TMNL Search — Linear Driver
 *
 * Simple .includes() based search for testing and fallback.
 * Stream-first with progressive emission.
 */

import { Effect, Ref, Stream } from 'effect'
import type {
  SearchServiceImpl,
  SearchResult,
  SearchOptions,
  SearchStats,
  SearchError,
  IndexConfig,
  Indexable,
  FieldConfig,
} from '../types'

// ─────────────────────────────────────────────────────────────────────────────
// Linear Search State
// ─────────────────────────────────────────────────────────────────────────────

interface LinearState<T extends Indexable> {
  items: T[]
  config: IndexConfig<T> | null
  lastUpdated: number
}

// ─────────────────────────────────────────────────────────────────────────────
// Driver Factory
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a simple linear search driver (for testing/fallback)
 */
export const createLinearDriver = <T extends Indexable>(): Effect.Effect<
  SearchServiceImpl<T>,
  never,
  never
> =>
  Effect.gen(function* () {
    const stateRef = yield* Ref.make<LinearState<T>>({
      items: [],
      config: null,
      lastUpdated: 0,
    })

    // ─────────────────────────────────────────────────────────────────────────
    // Helpers
    // ─────────────────────────────────────────────────────────────────────────

    const getFields = (config: IndexConfig<T> | null): string[] => {
      if (!config) return []
      return config.fields.map((f) =>
        typeof f === 'string' ? (f as string) : (f as FieldConfig).field
      )
    }

    const getFieldValue = (item: T, field: string): string => {
      const value = item[field as keyof T]
      if (value === null || value === undefined) return ''
      if (typeof value === 'string') return value
      if (typeof value === 'number') return String(value)
      return String(value)
    }

const scoreMatch = (
      item: T,
      query: string,
      fields: string[],
      options?: SearchOptions
    ): SearchResult<T> | null => {
      const lowerQuery = query.toLowerCase()
      const matches: { field: string }[] = []
      let totalScore = 0
      let matchCount = 0

      for (const field of fields) {
        const value = getFieldValue(item, field).toLowerCase()

        if (value.includes(lowerQuery)) {
          matches.push({ field })
          matchCount++

          // Score based on match quality
          let fieldScore = 0.5 // Base score for substring match

          // Exact match bonus
          if (value === lowerQuery) {
            fieldScore = 1.0
          }
          // Starts with bonus
          else if (value.startsWith(lowerQuery)) {
            fieldScore = 0.8
          }
          // Word boundary bonus
          else if (
            value.includes(` ${lowerQuery}`) ||
            value.startsWith(lowerQuery)
          ) {
            fieldScore = 0.7
          }

          // Apply boost if specified
          const boost = options?.boost?.[field] ?? 1
          totalScore += fieldScore * boost
        }
      }

      if (matchCount === 0) return null

      // Normalize score to 0-1
      const normalizedScore = Math.min(1, totalScore / matchCount)

      return {
        item,
        score: normalizedScore,
        matches,
      }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Mutations (Effect - one-shot)
    // ─────────────────────────────────────────────────────────────────────────

    const index = (
      items: readonly T[],
      config: IndexConfig<T>
    ): Effect.Effect<void, SearchError> =>
      Ref.set(stateRef, {
        items: [...items],
        config,
        lastUpdated: Date.now(),
      })

const add = (item: T): Effect.Effect<void, SearchError> =>
      Ref.update(stateRef, (s) => ({
        ...s,
        items: [...s.items, item],
        lastUpdated: Date.now(),
      }))

    const update = (item: T): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        const idField = (state.config?.idField as string) ?? 'id'
        const id = item[idField as keyof T]

        yield* Ref.update(stateRef, (s) => ({
          ...s,
          items: s.items.map((i) =>
            i[idField as keyof T] === id ? item : i
          ),
          lastUpdated: Date.now(),
        }))
      })

    const remove = (id: string | number): Effect.Effect<void, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        const idField = (state.config?.idField as string) ?? 'id'

        yield* Ref.update(stateRef, (s) => ({
          ...s,
          items: s.items.filter((i) => i[idField as keyof T] !== id),
          lastUpdated: Date.now(),
        }))
      })

    // ─────────────────────────────────────────────────────────────────────────
    // Queries (Stream - progressive, cancellable)
    // ─────────────────────────────────────────────────────────────────────────

    const search = (
      query: string,
      options?: SearchOptions
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      Stream.unwrap(
        Effect.gen(function* () {
          if (!query.trim()) {
            return Stream.empty
          }

          const state = yield* Ref.get(stateRef)
          const fields =
            options?.fields?.map(String) ?? getFields(state.config)
          const limit = options?.limit ?? 50
          const chunkSize = options?.chunkSize ?? 10

          // Score and filter items
          const results: SearchResult<T>[] = []

// Score and filter items
          const results: SearchResult<T>[] = []

          for (const item of state.items) {
            const result = scoreMatch(item, query, fields, options)
            if (result) {
              results.push(result)
            }
            if (results.length >= limit) break
          }

          // Sort by score
          results.sort((a, b) => b.score - a.score)

          // Emit progressively
          return Stream.fromIterable(results).pipe(
            Stream.grouped(chunkSize),
            Stream.flatMap((chunk) => Stream.fromIterable(chunk))
          )
        })
      )

    const prefix = (
      query: string,
      options?: Omit<SearchOptions, 'strategy'>
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      // For linear driver, prefix is same as search (startsWith is scored higher)
      search(query, { ...options, strategy: 'prefix' })

    const fuzzy = (
      query: string,
      options?: Omit<SearchOptions, 'strategy'>
    ): Stream.Stream<SearchResult<T>, SearchError> =>
      // Linear driver doesn't do true fuzzy, just includes
      search(query, { ...options, strategy: 'fuzzy' })

    // ─────────────────────────────────────────────────────────────────────────
    // Admin (Effect - one-shot)
    // ─────────────────────────────────────────────────────────────────────────

    const stats = (): Effect.Effect<SearchStats, SearchError> =>
      Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        return {
          itemCount: state.items.length,
          fieldCount: getFields(state.config).length,
          lastUpdated: state.lastUpdated || undefined,
          memoryUsage: state.items.length * 512, // Rough estimate
        }
      })

    const clear = (): Effect.Effect<void, SearchError> =>
      Ref.set(stateRef, {
        items: [],
        config: null,
        lastUpdated: Date.now(),
      })

