/**
 * TMNL Search — Scored Operators
 *
 * Stream operators for score-based filtering and boosting.
 */

import { Stream } from 'effect'
import type { SearchResult } from '../types'

// ─────────────────────────────────────────────────────────────────────────────
// Score Filters
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Filter results with score above threshold
 */
export const withMinScore = <T, E>(threshold: number) =>
  Stream.filter<SearchResult<T>, E>((r) => r.score >= threshold)

/**
 * Filter results with score below threshold
 */
export const withMaxScore = <T, E>(threshold: number) =>
  Stream.filter<SearchResult<T>, E>((r) => r.score < threshold)

/**
 * Filter results within score range
 */
export const withScoreRange = <T, E>(min: number, max: number) =>
  Stream.filter<SearchResult<T>, E>((r) => r.score >= min && r.score <= max)

// ─────────────────────────────────────────────────────────────────────────────
// Boost Operators
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Boost score when a specific field matched
 */
export const withFieldBoost = <T, E>(field: string, multiplier: number) =>
  Stream.map<SearchResult<T>, SearchResult<T>, E>((r) => {
    const hasFieldMatch = r.matches?.some((m) => m.field === field) ?? false
    if (!hasFieldMatch) return r
    return {
      ...r,
      score: Math.min(1, r.score * multiplier),
    }
  })

/**
 * Boost score based on multiple field weights
 */
export const withBoosts = <T, E>(boosts: Record<string, number>) =>
  Stream.map<SearchResult<T>, SearchResult<T>, E>((r) => {
    let multiplier = 1
    for (const match of r.matches ?? []) {
      const boost = boosts[match.field]
      if (boost) multiplier *= boost
    }
    return {
      ...r,
      score: Math.min(1, r.score * multiplier),
    }
  })

/**
 * Apply score decay based on index position
 * Useful for time-based sorting where newer items should rank higher
 */
export const withPositionDecay = <T, E>(decayFactor: number = 0.01) =>
  Stream.mapAccum<SearchResult<T>, number, SearchResult<T>, E>(0, (index, r) => [
    index + 1,
    {
      ...r,
      score: r.score * Math.exp(-decayFactor * index),
      index,
    },
  ])

// ─────────────────────────────────────────────────────────────────────────────
// Match Filters
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Filter results that matched a specific field
 */
export const withFieldMatch = <T, E>(field: string) =>
  Stream.filter<SearchResult<T>, E>(
    (r) => r.matches?.some((m) => m.field === field) ?? false
  )

/**
 * Filter results that matched any of the specified fields
 */
export const withAnyFieldMatch = <T, E>(fields: string[]) =>
  Stream.filter<SearchResult<T>, E>(
    (r) => r.matches?.some((m) => fields.includes(m.field)) ?? false
  )

/**
 * Filter results that matched all specified fields
 */
export const withAllFieldMatches = <T, E>(fields: string[]) =>
  Stream.filter<SearchResult<T>, E>((r) => {
    const matchedFields = new Set(r.matches?.map((m) => m.field) ?? [])
    return fields.every((f) => matchedFields.has(f))
  })

/**
 * Filter results that have any matches
 */
export const withMatches = <T, E>() =>
  Stream.filter<SearchResult<T>, E>((r) => (r.matches?.length ?? 0) > 0)

// ─────────────────────────────────────────────────────────────────────────────
// Sorting (Collect + Sort + Re-emit)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Sort results by score (descending) after collecting
 * Note: This breaks streaming for sorting, use sparingly
 */
export const sortedByScore = <T, E>() =>
  (stream: Stream.Stream<SearchResult<T>, E>): Stream.Stream<SearchResult<T>, E> =>
    Stream.unwrap(
      Stream.runCollect(stream).pipe(
        Stream.map((chunk) => {
          const sorted = [...chunk].sort((a, b) => b.score - a.score)
          return Stream.fromIterable(sorted)
        })
      )
    )

/**
 * TMNL Search — Traced Operators
 *
 * Effect.withSpan wrappers for observability.
 * Enables tracing via OpenTelemetry or console logging.
 */

import { Effect, Stream } from 'effect'
import type {
  SearchServiceImpl,
  SearchResult,
  SearchOptions,
  SearchError,
  Indexable,
  IndexConfig,
} from '../types'

// ─────────────────────────────────────────────────────────────────────────────
// Stream Tracing
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Wrap a stream with tracing spans
 * Each chunk emission creates a span
 */
export const tracedStream = <T, E>(
  name: string,
  attributes?: Record<string, unknown>
) =>
  (stream: Stream.Stream<T, E>): Stream.Stream<T, E> =>
    Stream.unwrap(
      Effect.gen(function* () {
        yield* Effect.logDebug(`[${name}] Stream started`, attributes)
        let count = 0

        return stream.pipe(
          Stream.tap((item) =>
            Effect.gen(function* () {
              count++
              if (count % 10 === 0) {
                yield* Effect.logDebug(`[${name}] Emitted ${count} items`)
              }
            })
          ),
          Stream.ensuring(
            Effect.logDebug(`[${name}] Stream completed: ${count} items`)
          )
        )
      })
    )

/**
 * Add timing to stream consumption
 */
export const timedStream = <T, E>(name: string) =>
  (stream: Stream.Stream<T, E>): Stream.Stream<T, E> =>
    Stream.unwrap(
      Effect.gen(function* () {
        const startTime = Date.now()

        return stream.pipe(
          Stream.ensuring(
            Effect.sync(() => {
              const elapsed = Date.now() - startTime
              console.debug(`[${name}] Completed in ${elapsed}ms`)
            })
          )
        )
      })
    )

// ─────────────────────────────────────────────────────────────────────────────
// Service Wrapper
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Service Wrapper
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Wrap a SearchService with tracing spans on all operations
 */
export const createTracedDriver = <T extends Indexable>(
  inner: SearchServiceImpl<T>,
  serviceName: string = 'SearchService'
): SearchServiceImpl<T> => ({
  // ─────────────────────────────────────────────────────────────────────────
  // Mutations (with Effect.withSpan)
  // ─────────────────────────────────────────────────────────────────────────

  index: (items: readonly T[], config: IndexConfig<T>) =>
    inner.index(items, config).pipe(
      Effect.withSpan(`${serviceName}.index`, {
        attributes: {
          itemCount: items.length,
          fields: config.fields.length,
        },
      }),
      Effect.tap(() =>
        Effect.logInfo(`[${serviceName}] Indexed ${items.length} items`)
      )
    ),

  add: (item: T) =>
    inner.add(item).pipe(
      Effect.withSpan(`${serviceName}.add`, {
        attributes: { itemId: item.id },
      })
    ),

  update: (item: T) =>
    inner.update(item).pipe(
      Effect.withSpan(`${serviceName}.update`, {
        attributes: { itemId: item.id },
      })
    ),

  remove: (id: string | number) =>
    inner.remove(id).pipe(
      Effect.withSpan(`${serviceName}.remove`, {
        attributes: { itemId: id },
      })
    ),

  // ─────────────────────────────────────────────────────────────────────────
  // Queries (with Stream tracing)
  // ─────────────────────────────────────────────────────────────────────────

  search: (query: string, options?: SearchOptions) =>
    inner.search(query, options).pipe(
      tracedStream(`${serviceName}.search`, {
        query,
        limit: options?.limit,
        strategy: options?.strategy,
      })
    ),

prefix: (query: string, options?: Omit<SearchOptions, 'strategy'>) =>
    inner.prefix(query, options).pipe(
      tracedStream(`${serviceName}.prefix`, {
        query,
        limit: options?.limit,
      })
    ),

  fuzzy: (query: string, options?: Omit<SearchOptions, 'strategy'>) =>
    inner.fuzzy(query, options).pipe(
      tracedStream(`${serviceName}.fuzzy`, {
        query,
        limit: options?.limit,
      })
    ),

  // ─────────────────────────────────────────────────────────────────────────
  // Admin (with Effect.withSpan)
  // ─────────────────────────────────────────────────────────────────────────

  stats: () =>
    inner.stats().pipe(
      Effect.withSpan(`${serviceName}.stats`),
      Effect.tap((stats) =>
        Effect.logDebug(`[${serviceName}] Stats`, { stats })
      )
    ),

  clear: () =>
    inner.clear().pipe(
      Effect.withSpan(`${serviceName}.clear`),
      Effect.tap(() => Effect.logInfo(`[${serviceName}] Index cleared`))
    ),
})

// ─────────────────────────────────────────────────────────────────────────────
// Utility: Console Tracing (for development)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Simple console-based tracing for development
 */
export const consoleTracedStream = <T extends { score?: number }, E>(
  label: string
) =>
  (stream: Stream.Stream<T, E>): Stream.Stream<T, E> => {
    let count = 0
    const startTime = Date.now()

return stream.pipe(
      Stream.tap((item) =>
        Effect.sync(() => {
          count++
          if (count <= 3) {
            console.log(`[${label}] Result ${count}:`, {
              score: item.score,
              item: item,
            })
          }
        })
      ),
      Stream.ensuring(
        Effect.sync(() => {
          const elapsed = Date.now() - startTime
          console.log(
            `[${label}] Complete: ${count} results in ${elapsed}ms`
          )
        })
      )
    )
  }

const runParse = (input: string): ParsedQuery =>
  Effect.runSync(parseQuery(input))

