/**
 * Query Executor
 *
 * Executes ParsedQuery against a SearchServiceImpl driver.
 * Uses hybrid approach: driver handles fuzzy/prefix/fields, post-filter for regex/exclusions.
 *
 * @example
 * ```typescript
 * const parsed = yield* parseQuery('category:grid "add row" limit:10')
 * const results = yield* executeQuery(driver, parsed)
 * ```
 *
 * @module
 */

import { Effect, Stream, Chunk } from "effect"
import type { SearchServiceImpl, SearchResult, SearchOptions, SearchError, Indexable } from "../types"
import type { ParsedQuery, FieldOperator } from "./schemas"
import { isEmpty } from "./schemas"

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

/**
 * Searchable item shape - must have these optional fields for filtering.
 */
export interface SearchableItem extends Indexable {
  readonly name: string
  readonly description?: string
  readonly category?: string
  readonly scope?: string
  readonly keys?: string
}

/**
 * Map field names from DSL to item properties.
 */
const fieldToProperty = (field: FieldOperator["field"]): keyof SearchableItem => {
  switch (field) {
    case "desc":
      return "description"
    default:
      return field
  }
}

// ─────────────────────────────────────────────────────────────
// Executor
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Executor
// ─────────────────────────────────────────────────────────────

/**
 * Execute a ParsedQuery against a search driver.
 *
 * Hybrid approach:
 * 1. Driver handles: fuzzy/prefix/exact search, field boosting
 * 2. Post-filter handles: regex, exclusions, phrases, case sensitivity
 * 3. Post-sort handles: sort:score, sort:name (collects all results)
 *
 * @param driver - The search service implementation
 * @param query - Parsed query structure
 * @returns Array of search results (sorted if requested)
 */
export const executeQuery = <T extends SearchableItem>(
  driver: SearchServiceImpl<T>,
  query: ParsedQuery
): Effect.Effect<readonly SearchResult<T>[], SearchError> =>
  Effect.gen(function* () {
    // Handle empty query - return empty results
    if (isEmpty(query)) {
      return []
    }

    // Build SearchOptions from query params
    const options: SearchOptions = {
      limit: query.sort ? undefined : query.limit, // Don't limit if sorting (need all for sort)
      strategy: query.matchMode ?? "fuzzy",
    }

    let results: readonly SearchResult<T>[]

    // If we have operators but no free text, get ALL items first then filter
    // FlexSearch doesn't return all items for empty queries
    if (!query.text.trim() && (query.fieldOperators.length > 0 || query.regexOperators.length > 0 || query.phraseOperators.length > 0)) {
      // Use prefix search with empty string to get all items
      // This is a workaround since FlexSearch search("") returns nothing
      const stats = yield* driver.stats()
      results = yield* driver.search("", { ...options, limit: stats.itemCount + 100 }).pipe(
        Stream.runCollect,
        Effect.map(Chunk.toReadonlyArray)
      )

// If still empty, try fuzzy with common patterns
      if (results.length === 0) {
        // Get all by searching for common characters
        const allResults = yield* driver.prefix("", { limit: 1000 }).pipe(
          Stream.runCollect,
          Effect.map(Chunk.toReadonlyArray)
        )
        results = allResults
      }
    } else {
      // Normal search with text
      results = yield* driver.search(query.text, options).pipe(
        Stream.runCollect,
        Effect.map(Chunk.toReadonlyArray)
      )
    }

    // Post-filter: Field operators (include)
    const includes = query.fieldOperators.filter((op) => !op.exclude)
    for (const op of includes) {
      const prop = fieldToProperty(op.field)
      const lowerValue = op.value.toLowerCase()
      results = results.filter((r) => {
        const fieldValue = (r.item as Record<string, unknown>)[prop]
        if (typeof fieldValue !== "string") return false
        return fieldValue.toLowerCase().includes(lowerValue)
      })
    }

    // Post-filter: Field operators (exclude)
    const excludes = query.fieldOperators.filter((op) => op.exclude)
    for (const op of excludes) {
      const prop = fieldToProperty(op.field)
      const lowerValue = op.value.toLowerCase()
      results = results.filter((r) => {
        const fieldValue = (r.item as Record<string, unknown>)[prop]
        if (typeof fieldValue !== "string") return true // Keep if field doesn't exist
        return !fieldValue.toLowerCase().includes(lowerValue)
      })
    }

    // Post-filter: Regex operators
    for (const op of query.regexOperators) {
      const flags = query.caseSensitive ? "" : "i"
      let regex: RegExp
      try {
        regex = new RegExp(op.pattern, flags)
      } catch {
        // Invalid regex - skip this filter
        continue
      }
      results = results.filter((r) => {
        const item = r.item
        return regex.test(item.name) || regex.test(item.description ?? "")
      })
    }

// Post-filter: Phrase operators
    for (const op of query.phraseOperators) {
      const phrase = query.caseSensitive ? op.phrase : op.phrase.toLowerCase()
      results = results.filter((r) => {
        const item = r.item
        const name = query.caseSensitive ? item.name : item.name.toLowerCase()
        const desc = query.caseSensitive
          ? (item.description ?? "")
          : (item.description ?? "").toLowerCase()
        return name.includes(phrase) || desc.includes(phrase)
      })
    }

    // Sort if requested (breaks streaming, but acceptable)
    if (query.sort === "score") {
      results = [...results].sort((a, b) => b.score - a.score)
    } else if (query.sort === "name") {
      results = [...results].sort((a, b) => a.item.name.localeCompare(b.item.name))
    }

    // Apply final limit (after sorting)
    if (query.limit !== undefined) {
      results = results.slice(0, query.limit)
    }

    return results
  })

/**
 * Execute a query and return as a Stream (for progressive emission).
 *
 * Note: If sort is specified, all results are collected before emission.
 */
export const executeQueryStream = <T extends SearchableItem>(
  driver: SearchServiceImpl<T>,
  query: ParsedQuery
): Stream.Stream<SearchResult<T>, SearchError> =>
  Stream.fromEffect(executeQuery(driver, query)).pipe(Stream.flatMap(Stream.fromIterable))

// ─────────────────────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────────────────────

/**
 * Apply all QueryDSL filters to a pre-loaded array of items.
 * Use this when you have operators but no free text search.
 *
 * @param items - Array of items to filter
 * @param query - Parsed query with operators
 * @returns Filtered and optionally sorted items as SearchResults
 */
export const applyFilters = <T extends SearchableItem>(
  items: readonly T[],
  query: ParsedQuery
): readonly SearchResult<T>[] => {
  // Convert items to SearchResults with score=1
  let results: SearchResult<T>[] = items.map((item) => ({
    item,
    score: 1,
  }))

  // Apply field operators (include)
  const includes = query.fieldOperators.filter((op) => !op.exclude)
  for (const op of includes) {
    const prop = fieldToProperty(op.field)
    const lowerValue = op.value.toLowerCase()
    results = results.filter((r) => {
      const fieldValue = (r.item as Record<string, unknown>)[prop]
      if (typeof fieldValue !== "string") return false
      return fieldValue.toLowerCase().includes(lowerValue)
    })
  }

  // Apply field operators (exclude)
  const excludes = query.fieldOperators.filter((op) => op.exclude)
  for (const op of excludes) {
    const prop = fieldToProperty(op.field)
    const lowerValue = op.value.toLowerCase()
    results = results.filter((r) => {
      const fieldValue = (r.item as Record<string, unknown>)[prop]
      if (typeof fieldValue !== "string") return true
      return !fieldValue.toLowerCase().includes(lowerValue)
    })
  }

// Apply regex operators
  for (const op of query.regexOperators) {
    const flags = query.caseSensitive ? "" : "i"
    let regex: RegExp
    try {
      regex = new RegExp(op.pattern, flags)
    } catch {
      continue
    }
    results = results.filter((r) => {
      const item = r.item
      return regex.test(item.name) || regex.test(item.description ?? "")
    })
  }

  // Apply phrase operators
  for (const op of query.phraseOperators) {
    const phrase = query.caseSensitive ? op.phrase : op.phrase.toLowerCase()
    results = results.filter((r) => {
      const item = r.item
      const name = query.caseSensitive ? item.name : item.name.toLowerCase()
      const desc = query.caseSensitive
        ? (item.description ?? "")
        : (item.description ?? "").toLowerCase()
      return name.includes(phrase) || desc.includes(phrase)
    })
  }

  // Sort if requested
  if (query.sort === "score") {
    results = [...results].sort((a, b) => b.score - a.score)
  } else if (query.sort === "name") {
    results = [...results].sort((a, b) => a.item.name.localeCompare(b.item.name))
  }

  // Apply limit
  if (query.limit !== undefined) {
    results = results.slice(0, query.limit)
  }

  return results
}

/**
 * Check if a parsed query has operators but no free text.
 */
export const hasOperatorsOnly = (query: ParsedQuery): boolean =>
  !query.text.trim() &&
  (query.fieldOperators.length > 0 ||
    query.regexOperators.length > 0 ||
    query.phraseOperators.length > 0)

/**
 * Apply a single field filter to results.
 */
export const applyFieldFilter = <T extends SearchableItem>(
  results: readonly SearchResult<T>[],
  op: FieldOperator
): readonly SearchResult<T>[] => {
  const prop = fieldToProperty(op.field)
  const lowerValue = op.value.toLowerCase()

return results.filter((r) => {
    const fieldValue = (r.item as Record<string, unknown>)[prop]
    if (typeof fieldValue !== "string") return op.exclude // Keep if exclude and no field
    const matches = fieldValue.toLowerCase().includes(lowerValue)
    return op.exclude ? !matches : matches
  })
}

/**
 * Apply a regex filter to results.
 */
export const applyRegexFilter = <T extends SearchableItem>(
  results: readonly SearchResult<T>[],
  pattern: string,
  caseSensitive = false
): readonly SearchResult<T>[] => {
  const flags = caseSensitive ? "" : "i"
  let regex: RegExp
  try {
    regex = new RegExp(pattern, flags)
  } catch {
    return results // Invalid regex - return unchanged
  }

  return results.filter((r) => {
    const item = r.item
    return regex.test(item.name) || regex.test(item.description ?? "")
  })
}

/**
 * Apply a phrase filter to results.
 */
export const applyPhraseFilter = <T extends SearchableItem>(
  results: readonly SearchResult<T>[],
  phrase: string,
  caseSensitive = false
): readonly SearchResult<T>[] => {
  const p = caseSensitive ? phrase : phrase.toLowerCase()

  return results.filter((r) => {
    const item = r.item
    const name = caseSensitive ? item.name : item.name.toLowerCase()
    const desc = caseSensitive ? (item.description ?? "") : (item.description ?? "").toLowerCase()
    return name.includes(p) || desc.includes(p)
  })
}

export {
  parseQuery,
  isValidRegex,
  validateRegexPatterns,
  formatQuery,
} from "./parser"

// ─────────────────────────────────────────────────────────────
// Executor
// ─────────────────────────────────────────────────────────────

export {
  type SearchableItem,
  executeQuery,
  executeQueryStream,
  applyFilters,
  hasOperatorsOnly,
  applyFieldFilter,
  applyRegexFilter,
  applyPhraseFilter,
} from "./executor"

// ─────────────────────────────────────────────────────────────
// Stream Operators
// ─────────────────────────────────────────────────────────────

export {
  // Field operators
  withFieldMatch,
  withCategory,
  withScope,

  // Regex operators
  withRegexFilter,
  withRegexFieldFilter,

  // Phrase operators
  withPhraseMatch,
  withPhraseFieldMatch,

  // Sort operators
  sortedBy,
  sortedByScore,
  sortedByName,

  // Composite operators
  withFieldOperators,
} from "./operators"

/**
 * Filter results by scope.
 */
export const withScope = <T extends SearchableItem>(scope: string, exclude = false) =>
  withFieldMatch<T>("scope", scope, exclude)

// ─────────────────────────────────────────────────────────────
// Regex Operators
// ─────────────────────────────────────────────────────────────

/**
 * Filter results by regex pattern.
 *
 * Matches against name and description fields.
 * Invalid patterns are silently ignored (pass-through).
 */
export const withRegexFilter = <T extends SearchableItem>(
  pattern: string,
  caseSensitive = false
) => {
  let regex: RegExp | null = null
  try {
    regex = new RegExp(pattern, caseSensitive ? "" : "i")
  } catch {
    // Invalid regex - will pass through all results
  }

  return Stream.filter<SearchResult<T>, SearchError>((r) => {
    // Invalid regex - pass through all
    if (!regex) return true
    const item = r.item
    return regex.test(item.name) || regex.test(item.description ?? "")
  })
}

/**
 * Filter results by regex pattern on a specific field.
 */
export const withRegexFieldFilter = <T extends SearchableItem>(
  field: FieldOperator["field"],
  pattern: string,
  caseSensitive = false
) => {
  let regex: RegExp | null = null
  try {
    regex = new RegExp(pattern, caseSensitive ? "" : "i")
  } catch {
    // Invalid regex - will pass through all results
  }

  const prop = fieldToProperty(field)

  return Stream.filter<SearchResult<T>, SearchError>((r) => {
    // Invalid regex - pass through all
    if (!regex) return true
    const fieldValue = (r.item as Record<string, unknown>)[prop]
    if (typeof fieldValue !== "string") return false
    return regex.test(fieldValue)
  })
}

// ─────────────────────────────────────────────────────────────
// Phrase Operators
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Phrase Operators
// ─────────────────────────────────────────────────────────────

/**
 * Filter results by exact phrase match.
 *
 * Matches against name and description fields.
 */
export const withPhraseMatch = <T extends SearchableItem>(
  phrase: string,
  caseSensitive = false
) =>
  Stream.filter<SearchResult<T>, SearchError>((r) => {
    const item = r.item
    const p = caseSensitive ? phrase : phrase.toLowerCase()
    const name = caseSensitive ? item.name : item.name.toLowerCase()
    const desc = caseSensitive ? (item.description ?? "") : (item.description ?? "").toLowerCase()
    return name.includes(p) || desc.includes(p)
  })

/**
 * Filter results by exact phrase match on a specific field.
 */
export const withPhraseFieldMatch = <T extends SearchableItem>(
  field: FieldOperator["field"],
  phrase: string,
  caseSensitive = false
) => {
  const prop = fieldToProperty(field)

  return Stream.filter<SearchResult<T>, SearchError>((r) => {
    const fieldValue = (r.item as Record<string, unknown>)[prop]
    if (typeof fieldValue !== "string") return false
    const p = caseSensitive ? phrase : phrase.toLowerCase()
    const fv = caseSensitive ? fieldValue : fieldValue.toLowerCase()
    return fv.includes(p)
  })
}

// ─────────────────────────────────────────────────────────────
// Sort Operators
// ─────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────
// Sort Operators
// ─────────────────────────────────────────────────────────────

/**
 * Collect all results and sort by field.
 *
 * Note: This breaks streaming - all results are collected before emission.
 */
export const sortedBy = <T extends SearchableItem>(
  field: SortField
): (<E>(stream: Stream.Stream<SearchResult<T>, E>) => Stream.Stream<SearchResult<T>, E>) =>
  <E>(stream: Stream.Stream<SearchResult<T>, E>) =>
    stream.pipe(
      Stream.runCollect,
      Effect.map((chunk) => {
        const arr = Chunk.toReadonlyArray(chunk)
        const sorted =
          field === "score"
            ? [...arr].sort((a, b) => b.score - a.score)
            : [...arr].sort((a, b) => a.item.name.localeCompare(b.item.name))
        return sorted
      }),
      Stream.fromEffect,
      Stream.flatMap(Stream.fromIterable)
    )

/**
 * Sort results by score (highest first).
 */
export const sortedByScore = <T extends SearchableItem>() => sortedBy<T>("score")

/**
 * Sort results by name (alphabetical).
 */
export const sortedByName = <T extends SearchableItem>() => sortedBy<T>("name")

// ─────────────────────────────────────────────────────────────
// Composite Operators
// ─────────────────────────────────────────────────────────────

/**
 * Apply all operators from a FieldOperator array.
 */
export const withFieldOperators = <T extends SearchableItem>(
  ops: readonly FieldOperator[]
): (<E>(stream: Stream.Stream<SearchResult<T>, E>) => Stream.Stream<SearchResult<T>, E>) =>
  <E>(stream: Stream.Stream<SearchResult<T>, E>) =>
    ops.reduce(
      (s, op) => s.pipe(withFieldMatch<T>(op.field, op.value, op.exclude)),
      stream
    )

/**
 * Query Parser
 *
 * Parses raw query strings into structured ParsedQuery objects.
 * Extracts operators, phrases, regex patterns, and search params.
 *
 * @example
 * ```typescript
 * const parsed = yield* parseQuery('category:grid -scope:debug "add row" limit:10')
 * // {
 * //   text: "",
 * //   fieldOperators: [
 * //     { _tag: "FieldOperator", field: "category", value: "grid", exclude: false },
 * //     { _tag: "FieldOperator", field: "scope", value: "debug", exclude: true },
 * //   ],
 * //   phraseOperators: [{ _tag: "PhraseOperator", phrase: "add row" }],
 * //   regexOperators: [],
 * //   limit: 10,
 * // }
 * ```
 *
 * @module
 */

import { Effect } from "effect"
import type {
  ParsedQuery,
  FieldOperator,
  RegexOperator,
  PhraseOperator,
  FieldName,
  MatchMode,
  SortField,
} from "./schemas"

// ─────────────────────────────────────────────────────────────
// Token Patterns
// ─────────────────────────────────────────────────────────────

/** Quoted phrases: "exact phrase" */
const QUOTED_PATTERN = /"([^"]+)"/g

/** Regex operator: regex:pattern */
const REGEX_PATTERN = /regex:(\S+)/g

/** Field operators: field:value or -field:value */
const FIELD_PATTERN = /(-?)(category|scope|name|desc|keys):(\S+)/g

/** Case sensitivity: case:sensitive or case:insensitive */
const CASE_PATTERN = /case:(sensitive|insensitive)/g

/** Match mode: exact:, prefix:, fuzzy: followed by optional text */
const MATCH_MODE_PATTERN = /(exact|prefix|fuzzy):(\S*)/g

/** Limit: limit:N */
const LIMIT_PATTERN = /limit:(\d+)/g

/** Sort: sort:score or sort:name */
const SORT_PATTERN = /sort:(score|name)/g

/** Limit: limit:N */
const LIMIT_PATTERN = /limit:(\d+)/g

/** Sort: sort:score or sort:name */
const SORT_PATTERN = /sort:(score|name)/g

// ─────────────────────────────────────────────────────────────
// Valid Field Names
// ─────────────────────────────────────────────────────────────

const VALID_FIELDS = new Set<string>(["category", "scope", "name", "desc", "keys"])

const isValidField = (field: string): field is FieldName => VALID_FIELDS.has(field)

// ─────────────────────────────────────────────────────────────
// Parser
// ─────────────────────────────────────────────────────────────

/**
 * Parse a raw query string into a structured ParsedQuery.
 *
 * Extraction order matters:
 * 1. Quoted phrases (to prevent splitting on spaces inside quotes)
 * 2. Regex patterns
 * 3. Field operators
 * 4. Search params (case, match mode, limit, sort)
 * 5. Remaining text is free-form search
 */
export const parseQuery = (input: string): Effect.Effect<ParsedQuery> =>
  Effect.sync(() => {
    let text = input
    const fieldOps: FieldOperator[] = []
    const regexOps: RegexOperator[] = []
    const phraseOps: PhraseOperator[] = []
    let matchMode: MatchMode | undefined
    let caseSensitive: boolean | undefined
    let limit: number | undefined
    let sort: SortField | undefined

    // 1. Extract quoted phrases FIRST (preserve spaces inside quotes)
    for (const match of input.matchAll(QUOTED_PATTERN)) {
      phraseOps.push({
        _tag: "PhraseOperator",
        phrase: match[1],
      })
      text = text.replace(match[0], " ")
    }

    // 2. Extract regex operators
    for (const match of text.matchAll(REGEX_PATTERN)) {
      regexOps.push({
        _tag: "RegexOperator",
        pattern: match[1],
      })
      text = text.replace(match[0], " ")
    }

// 3. Extract field operators (including exclusions with -)
    for (const match of text.matchAll(FIELD_PATTERN)) {
      const [full, exclude, field, value] = match
      if (isValidField(field)) {
        fieldOps.push({
          _tag: "FieldOperator",
          field,
          value,
          exclude: exclude === "-",
        })
        text = text.replace(full, " ")
      }
    }

    // 4. Extract case sensitivity
    for (const match of text.matchAll(CASE_PATTERN)) {
      caseSensitive = match[1] === "sensitive"
      text = text.replace(match[0], " ")
    }

    // 5. Extract match mode (may have attached text like "exact:save")
    for (const match of text.matchAll(MATCH_MODE_PATTERN)) {
      matchMode = match[1] as MatchMode
      // If there's text after the colon, keep it as search text
      if (match[2]) {
        text = text.replace(match[0], ` ${match[2]} `)
      } else {
        text = text.replace(match[0], " ")
      }
    }

    // 6. Extract limit
    for (const match of text.matchAll(LIMIT_PATTERN)) {
      limit = parseInt(match[1], 10)
      text = text.replace(match[0], " ")
    }

    // 7. Extract sort
    for (const match of text.matchAll(SORT_PATTERN)) {
      sort = match[1] as SortField
      text = text.replace(match[0], " ")
    }

    // 8. Clean up remaining text
    text = text
      .replace(/\s+/g, " ")  // Collapse whitespace
      .trim()

    return {
      text,
      fieldOperators: fieldOps,
      regexOperators: regexOps,
      phraseOperators: phraseOps,
      matchMode,
      caseSensitive,
      limit,
      sort,
    }
  })

return {
      text,
      fieldOperators: fieldOps,
      regexOperators: regexOps,
      phraseOperators: phraseOps,
      matchMode,
      caseSensitive,
      limit,
      sort,
    }
  })

/**
 * Validate a regex pattern without throwing.
 * Returns true if the pattern is valid.
 */
export const isValidRegex = (pattern: string): boolean => {
  try {
    new RegExp(pattern)
    return true
  } catch {
    return false
  }
}

/**
 * Validate all regex patterns in a parsed query.
 * Returns array of invalid patterns (empty if all valid).
 */
export const validateRegexPatterns = (
  query: ParsedQuery
): Effect.Effect<readonly string[]> =>
  Effect.sync(() =>
    query.regexOperators
      .filter((op) => !isValidRegex(op.pattern))
      .map((op) => op.pattern)
  )

/**
 * Format a ParsedQuery back to a string (for debugging/display).
 */
export const formatQuery = (query: ParsedQuery): string => {
  const parts: string[] = []

  // Field operators
  for (const op of query.fieldOperators) {
    const prefix = op.exclude ? "-" : ""
    parts.push(`${prefix}${op.field}:${op.value}`)
  }

  // Regex operators
  for (const op of query.regexOperators) {
    parts.push(`regex:${op.pattern}`)
  }

  // Phrase operators
  for (const op of query.phraseOperators) {
    parts.push(`"${op.phrase}"`)
  }

  // Params
  if (query.matchMode) {
    parts.push(`${query.matchMode}:`)
  }
  if (query.caseSensitive !== undefined) {
    parts.push(`case:${query.caseSensitive ? "sensitive" : "insensitive"}`)
  }
  if (query.limit !== undefined) {
    parts.push(`limit:${query.limit}`)
  }
  if (query.sort !== undefined) {
    parts.push(`sort:${query.sort}`)
  }

  // Free text
  if (query.text) {
    parts.push(query.text)
  }

  return parts.join(" ")
}

/**
 * QueryDSL Schemas
 *
 * Effect Schema definitions for the query DSL system.
 * Supports field operators, regex, phrases, and search params.
 *
 * @module
 */

import { Schema } from "effect"

// ─────────────────────────────────────────────────────────────
