/**
 * Frustum Selection Utilities
 *
 * 3D selection via camera frustum projection.
 * Converts 2D marquee rect to a frustum and tests entity intersections.
 *
 * @example
 * ```tsx
 * import { createFrustumCollisionDetector } from '@/lib/selection'
 *
 * // In R3F component
 * const { camera, size } = useThree()
 * const entities = useEntities()
 *
 * const detector = createFrustumCollisionDetector(camera, size, entities)
 *
 * <SelectionMarquee
 *   containerRef={canvasRef}
 *   mode="3d"
 *   collisionDetector={detector}
 * />
 * ```
 *
 * @module
 */

import * as THREE from "three"
import type { Rect } from "./types"
import type { CollisionDetector } from "./SelectionMarquee"

// =============================================================================
// Types
// =============================================================================

export interface Entity3D {
  id: string
  position: THREE.Vector3 | { x: number; y: number; z: number }
}

export interface ViewportSize {
  width: number
  height: number
}

// =============================================================================
// Frustum Selection
// =============================================================================

/**
 * Convert 2D marquee rect to normalized device coordinates (NDC).
 * NDC ranges from -1 to 1 in both axes.
 */
function rectToNDC(
  rect: Rect,
  containerWidth: number,
  containerHeight: number
): { minX: number; maxX: number; minY: number; maxY: number } {
  // Convert from container coordinates to NDC
  // X: left edge is -1, right edge is +1
  // Y: top edge is +1, bottom edge is -1 (flipped for WebGL)
  const minX = (rect.x / containerWidth) * 2 - 1
  const maxX = ((rect.x + rect.width) / containerWidth) * 2 - 1
  const maxY = -(rect.y / containerHeight) * 2 + 1
  const minY = -((rect.y + rect.height) / containerHeight) * 2 + 1

return { minX, maxX, minY, maxY }
}

/**
 * Create a frustum from the camera that corresponds to the 2D marquee rect.
 * This is the key insight: we create a sub-frustum of the camera frustum
 * that matches the marquee selection area.
 */
function createSelectionFrustum(
  camera: THREE.Camera,
  ndc: { minX: number; maxX: number; minY: number; maxY: number }
): THREE.Frustum {
  const frustum = new THREE.Frustum()

  // For perspective cameras, we construct planes from the camera through the marquee corners
  if (camera instanceof THREE.PerspectiveCamera) {
    const nearPlane = camera.near
    const farPlane = camera.far

    // Get camera matrices
    const projectionMatrix = camera.projectionMatrix.clone()
    const viewMatrix = camera.matrixWorldInverse.clone()
    const viewProjectionMatrix = projectionMatrix.multiply(viewMatrix)

    // Create frustum from view-projection matrix
    // But we need to modify it to only include the marquee region
    // For simplicity, we'll use point-in-frustum approach instead

    frustum.setFromProjectionMatrix(camera.projectionMatrix.clone().multiply(camera.matrixWorldInverse))
  } else {
    // For orthographic cameras
    frustum.setFromProjectionMatrix(camera.projectionMatrix.clone().multiply(camera.matrixWorldInverse))
  }

  return frustum
}

/**
 * Check if a 3D point projects into the 2D marquee rect.
 * This is more accurate than frustum testing for marquee selection.
 */
function isPointInMarquee(
  point: THREE.Vector3,
  camera: THREE.Camera,
  ndc: { minX: number; maxX: number; minY: number; maxY: number }
): boolean {
  // Project point to NDC
  const projected = point.clone().project(camera)

// Check if projected point is within NDC bounds of marquee
  // Also check Z to ensure point is in front of camera
  return (
    projected.x >= ndc.minX &&
    projected.x <= ndc.maxX &&
    projected.y >= ndc.minY &&
    projected.y <= ndc.maxY &&
    projected.z >= -1 &&
    projected.z <= 1
  )
}

/**
 * Create a collision detector for 3D entities.
 *
 * @param camera Three.js camera
 * @param viewportSize Viewport dimensions
 * @param entities Array of entities with id and position
 * @returns CollisionDetector function for SelectionMarquee
 */
export function createFrustumCollisionDetector(
  camera: THREE.Camera,
  viewportSize: ViewportSize,
  entities: readonly Entity3D[]
): CollisionDetector {
  return (rect: Rect, _container: HTMLElement): string[] => {
    const { width, height } = viewportSize

    // Convert marquee rect to NDC
    const ndc = rectToNDC(rect, width, height)

    // Test each entity
    const selected: string[] = []

    for (const entity of entities) {
      const pos = entity.position
      const point = pos instanceof THREE.Vector3
        ? pos
        : new THREE.Vector3(pos.x, pos.y, pos.z)

      if (isPointInMarquee(point, camera, ndc)) {
        selected.push(entity.id)
      }
    }

    return selected
  }
}

/**
 * Hook-friendly version that memoizes the detector.
 * Use with useMemo in React components.
 */
export function useFrustumCollisionDetector(
  camera: THREE.Camera | null,
  viewportSize: ViewportSize,
  entities: readonly Entity3D[]
): CollisionDetector | undefined {
  if (!camera) return undefined
  return createFrustumCollisionDetector(camera, viewportSize, entities)
}

export default createFrustumCollisionDetector

/**
 * Modifier Keys Stream
 *
 * Effect Stream-based tracking of modifier key state with backpressure.
 * Exposes state via effect-atom for React consumption.
 *
 * @module
 */

import { Effect, Stream, Queue, Fiber, Scope } from "effect"
import { Atom } from "@effect-atom/atom"

// =============================================================================
// Types
// =============================================================================

export interface ModifierState {
  readonly alt: boolean
  readonly shift: boolean
  readonly ctrl: boolean
  readonly meta: boolean
}

const INITIAL_STATE: ModifierState = {
  alt: false,
  shift: false,
  ctrl: false,
  meta: false,
}

// =============================================================================
// Atoms
// =============================================================================

/** Current modifier key state */
export const modifierState$ = Atom.make<ModifierState>(INITIAL_STATE)

/** Convenience selector for Alt key */
export const altPressed$ = Atom.make((get) => get(modifierState$).alt)

// =============================================================================
// Stream Setup
// =============================================================================

type KeyEvent = { type: "down" | "up"; event: KeyboardEvent }

/**
 * Create a bounded queue for keyboard events with backpressure.
 * Dropping strategy prevents memory buildup if consumer is slow.
 */
const createKeyEventQueue = Effect.gen(function* () {
  return yield* Queue.dropping<KeyEvent>(16)
})

/**
 * Stream keyboard events into the queue.
 * Uses Effect.async for proper resource management.
 */
const subscribeToKeyEvents = (queue: Queue.Queue<KeyEvent>) =>
  Effect.async<never, never, never>((resume) => {
    const onKeyDown = (e: KeyboardEvent) => {
      Effect.runSync(Queue.offer(queue, { type: "down", event: e }))
    }
    const onKeyUp = (e: KeyboardEvent) => {
      Effect.runSync(Queue.offer(queue, { type: "up", event: e }))
    }

    window.addEventListener("keydown", onKeyDown)
    window.addEventListener("keyup", onKeyUp)

window.addEventListener("keydown", onKeyDown)
    window.addEventListener("keyup", onKeyUp)

    // Cleanup on fiber interruption
    return Effect.sync(() => {
      window.removeEventListener("keydown", onKeyDown)
      window.removeEventListener("keyup", onKeyUp)
    })
  })

/**
 * Process keyboard events and update modifier state atom.
 */
const processKeyEvents = (queue: Queue.Queue<KeyEvent>) =>
  Stream.fromQueue(queue).pipe(
    Stream.tap((keyEvent) =>
      Effect.sync(() => {
        const e = keyEvent.event
        Atom.set(modifierState$, {
          alt: e.altKey,
          shift: e.shiftKey,
          ctrl: e.ctrlKey,
          meta: e.metaKey,
        })
      })
    ),
    Stream.runDrain
  )

// =============================================================================
// Lifecycle
// =============================================================================

let runningFiber: Fiber.RuntimeFiber<never, never> | null = null

/**
 * Start the modifier key tracking stream.
 * Idempotent - safe to call multiple times.
 */
export const startModifierTracking = Effect.gen(function* () {
  if (runningFiber) return // Already running

  const queue = yield* createKeyEventQueue

  // Fork the event subscription (runs forever until interrupted)
  const subFiber = yield* Effect.fork(subscribeToKeyEvents(queue))

  // Fork the event processor
  const procFiber = yield* Effect.fork(processKeyEvents(queue))

  // Combine fibers for unified interruption
  runningFiber = yield* Effect.fork(
    Effect.all([Fiber.join(subFiber), Fiber.join(procFiber)], {
      concurrency: 2,
    })
  )
})

/**
 * Stop the modifier key tracking stream.
 */
export const stopModifierTracking = Effect.gen(function* () {
  if (!runningFiber) return

  yield* Fiber.interrupt(runningFiber)
  runningFiber = null
  Atom.set(modifierState$, INITIAL_STATE)
})

/**
 * Run the tracking stream. Call once at app init.
 */
export const runModifierTracking = () => {
  Effect.runFork(startModifierTracking)
}

/**
 * Selection State Management
 *
 * Atom-based state for marquee selection and grouping.
 * Uses Legend-State atoms directly (no Effect services needed).
 *
 * @pattern Atom-as-State (direct atom manipulation, React subscribes)
 * @module
 */

import { observable } from '@legendapp/state'
import type {
  SelectionState,
  SelectionEvent,
  Position,
  Rect,
  GroupState,
  SelectionMode,
} from './types'

// =============================================================================
// Initial State
// =============================================================================

const initialState: SelectionState = {
  selectedIds: new Set(),
  marqueeRect: null,
  isSelecting: false,
  modifiers: { shift: false, ctrl: false, alt: false },
  groups: new Map(),
  itemToGroup: new Map(),
}

// =============================================================================
// Observable State (Singleton)
// =============================================================================

export const selectionState$ = observable<SelectionState>({
  ...initialState,
  // Legend-State needs plain objects, convert Sets/Maps on access
})

// Backing stores (actual Sets/Maps)
let _selectedIds = new Set<string>()
let _groups = new Map<string, GroupState>()
let _itemToGroup = new Map<string, string>()

// =============================================================================
// Selectors (Read)
// =============================================================================

export function getSelectedIds(): Set<string> {
  return new Set(_selectedIds)
}

export function isSelected(id: string): boolean {
  return _selectedIds.has(id)
}

export function getMarqueeRect(): Rect | null {
  return selectionState$.marqueeRect.get()
}

export function isSelecting(): boolean {
  return selectionState$.isSelecting.get()
}

export function getModifiers() {
  return selectionState$.modifiers.get()
}

export function getGroup(groupId: string): GroupState | undefined {
  return _groups.get(groupId)
}

export function getItemGroup(itemId: string): string | undefined {
  return _itemToGroup.get(itemId)
}

export function getGroup(groupId: string): GroupState | undefined {
  return _groups.get(groupId)
}

export function getItemGroup(itemId: string): string | undefined {
  return _itemToGroup.get(itemId)
}

export function getGroupForItem(itemId: string): GroupState | undefined {
  const groupId = _itemToGroup.get(itemId)
  return groupId ? _groups.get(groupId) : undefined
}

export function getSelectedCount(): number {
  return _selectedIds.size
}

export function hasSelection(): boolean {
  return _selectedIds.size > 0
}

// =============================================================================
// Actions (Write)
// =============================================================================

let marqueeStart: Position | null = null

export function startMarquee(position: Position, mode: SelectionMode = 'replace'): void {
  marqueeStart = position
  selectionState$.isSelecting.set(true)
  selectionState$.marqueeRect.set({
    x: position.x,
    y: position.y,
    width: 0,
    height: 0,
  })

  // If replace mode, clear existing selection
  if (mode === 'replace' && !selectionState$.modifiers.get().shift) {
    _selectedIds.clear()
    notifySelectionChange()
  }
}

export function updateMarquee(position: Position): void {
  if (!marqueeStart) return

  const x = Math.min(marqueeStart.x, position.x)
  const y = Math.min(marqueeStart.y, position.y)
  const width = Math.abs(position.x - marqueeStart.x)
  const height = Math.abs(position.y - marqueeStart.y)

  selectionState$.marqueeRect.set({ x, y, width, height })
}

export function endMarquee(itemsInRect: string[]): void {
  const mode = selectionState$.modifiers.get().shift ? 'add' : 'replace'

  if (mode === 'replace') {
    _selectedIds.clear()
  }

if (mode === 'replace') {
    _selectedIds.clear()
  }

  // Add items in rect to selection
  for (const id of itemsInRect) {
    _selectedIds.add(id)
    // If item is in a group, select entire group
    const groupId = _itemToGroup.get(id)
    if (groupId) {
      const group = _groups.get(groupId)
      if (group) {
        for (const memberId of group.memberIds) {
          _selectedIds.add(memberId)
        }
      }
    }
  }

  marqueeStart = null
  selectionState$.isSelecting.set(false)
  selectionState$.marqueeRect.set(null)
  notifySelectionChange()
}

export function cancelMarquee(): void {
  marqueeStart = null
  selectionState$.isSelecting.set(false)
  selectionState$.marqueeRect.set(null)
}

export function selectItem(id: string, mode: SelectionMode = 'replace'): void {
  if (mode === 'replace') {
    _selectedIds.clear()
    _selectedIds.add(id)
  } else if (mode === 'add') {
    _selectedIds.add(id)
  } else if (mode === 'toggle') {
    if (_selectedIds.has(id)) {
      _selectedIds.delete(id)
    } else {
      _selectedIds.add(id)
    }
  }

  // If item is in a group, select entire group
  const groupId = _itemToGroup.get(id)
  if (groupId && mode !== 'toggle') {
    const group = _groups.get(groupId)
    if (group) {
      for (const memberId of group.memberIds) {
        _selectedIds.add(memberId)
      }
    }
  }

  notifySelectionChange()
}

export function selectItems(ids: string[], mode: SelectionMode = 'replace'): void {
  if (mode === 'replace') {
    _selectedIds.clear()
  }

notifySelectionChange()
}

export function selectItems(ids: string[], mode: SelectionMode = 'replace'): void {
  if (mode === 'replace') {
    _selectedIds.clear()
  }

  for (const id of ids) {
    if (mode === 'toggle') {
      if (_selectedIds.has(id)) {
        _selectedIds.delete(id)
      } else {
        _selectedIds.add(id)
      }
    } else {
      _selectedIds.add(id)
    }
  }

  notifySelectionChange()
}

export function deselectItem(id: string): void {
  _selectedIds.delete(id)
  notifySelectionChange()
}

export function deselectAll(): void {
  _selectedIds.clear()
  notifySelectionChange()
}

export function selectAll(ids: string[]): void {
  _selectedIds.clear()
  for (const id of ids) {
    _selectedIds.add(id)
  }
  notifySelectionChange()
}

export function updateModifiers(modifiers: { shift: boolean; ctrl: boolean; alt: boolean }): void {
  selectionState$.modifiers.set(modifiers)
}

// =============================================================================
// Grouping
// =============================================================================

let groupCounter = 0

export function groupSelected(): string | null {
  if (_selectedIds.size < 2) return null

  const groupId = `group-${++groupCounter}-${Date.now()}`
  const memberIds = Array.from(_selectedIds)

  // Remove members from existing groups
  for (const memberId of memberIds) {
    const existingGroupId = _itemToGroup.get(memberId)
    if (existingGroupId) {
      const existingGroup = _groups.get(existingGroupId)
      if (existingGroup) {
        existingGroup.memberIds = existingGroup.memberIds.filter((id) => id !== memberId)
        if (existingGroup.memberIds.length < 2) {
          // Dissolve group with less than 2 members
          for (const id of existingGroup.memberIds) {
            _itemToGroup.delete(id)
          }
          _groups.delete(existingGroupId)
        }
      }
    }
  }

// Create new group
  const group: GroupState = {
    id: groupId,
    memberIds,
    createdAt: Date.now(),
  }

  _groups.set(groupId, group)
  for (const memberId of memberIds) {
    _itemToGroup.set(memberId, groupId)
  }

  notifyGroupChange()
  return groupId
}

export function ungroupSelected(): void {
  const groupsToDissolve = new Set<string>()

  for (const selectedId of _selectedIds) {
    const groupId = _itemToGroup.get(selectedId)
    if (groupId) {
      groupsToDissolve.add(groupId)
    }
  }

  for (const groupId of groupsToDissolve) {
    const group = _groups.get(groupId)
    if (group) {
      for (const memberId of group.memberIds) {
        _itemToGroup.delete(memberId)
      }
      _groups.delete(groupId)
    }
  }

  notifyGroupChange()
}

// =============================================================================
// Change Notifications (for React subscriptions)
// =============================================================================

type SelectionListener = (selectedIds: Set<string>) => void
type GroupListener = (groups: Map<string, GroupState>) => void

const selectionListeners = new Set<SelectionListener>()
const groupListeners = new Set<GroupListener>()

export function subscribeToSelection(listener: SelectionListener): () => void {
  selectionListeners.add(listener)
  // Immediately notify with current state
  listener(new Set(_selectedIds))
  return () => selectionListeners.delete(listener)
}

export function subscribeToGroups(listener: GroupListener): () => void {
  groupListeners.add(listener)
  listener(new Map(_groups))
  return () => groupListeners.delete(listener)
}

function notifySelectionChange(): void {
  const snapshot = new Set(_selectedIds)
  for (const listener of selectionListeners) {
    listener(snapshot)
  }
}

function notifyGroupChange(): void {
  const snapshot = new Map(_groups)
  for (const listener of groupListeners) {
    listener(snapshot)
  }
}

// =============================================================================
// Reset
// =============================================================================

function notifyGroupChange(): void {
  const snapshot = new Map(_groups)
  for (const listener of groupListeners) {
    listener(snapshot)
  }
}

// =============================================================================
// Reset
// =============================================================================

export function resetSelection(): void {
  _selectedIds.clear()
  _groups.clear()
  _itemToGroup.clear()
  marqueeStart = null
  selectionState$.set(initialState)
  notifySelectionChange()
  notifyGroupChange()
}

/**
 * Selection System Types
 *
 * Marquee selection + grouping for card-based UI.
 *
 * @module
 */

import { Schema } from 'effect'

// =============================================================================
// Schemas
// =============================================================================

export const Position = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
})
export type Position = typeof Position.Type

export const Rect = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
  width: Schema.Number,
  height: Schema.Number,
})
export type Rect = typeof Rect.Type

export const SelectionMode = Schema.Literal('replace', 'add', 'toggle')
export type SelectionMode = typeof SelectionMode.Type

export const GroupState = Schema.Struct({
  id: Schema.String,
  memberIds: Schema.Array(Schema.String),
  createdAt: Schema.Number,
})
export type GroupState = typeof GroupState.Type

// =============================================================================
// State
// =============================================================================

export interface SelectionState {
  /** Currently selected item IDs */
  selectedIds: Set<string>
  /** Active marquee rectangle (null when not dragging) */
  marqueeRect: Rect | null
  /** Is marquee drag in progress */
  isSelecting: boolean
  /** Modifier key state */
  modifiers: {
    shift: boolean
    ctrl: boolean
    alt: boolean
  }
  /** Groups of items */
  groups: Map<string, GroupState>
  /** Map of itemId -> groupId for fast lookup */
  itemToGroup: Map<string, string>
}

// =============================================================================
// Events
// =============================================================================

// =============================================================================
// Events
// =============================================================================

export type SelectionEvent =
  | { type: 'START_MARQUEE'; position: Position; mode: SelectionMode }
  | { type: 'UPDATE_MARQUEE'; position: Position }
  | { type: 'END_MARQUEE'; itemsInRect: string[] }
  | { type: 'CANCEL_MARQUEE' }
  | { type: 'SELECT_ITEM'; id: string; mode: SelectionMode }
  | { type: 'SELECT_ITEMS'; ids: string[]; mode: SelectionMode }
  | { type: 'DESELECT_ITEM'; id: string }
  | { type: 'DESELECT_ALL' }
  | { type: 'SELECT_ALL'; ids: string[] }
  | { type: 'GROUP_SELECTED' }
  | { type: 'UNGROUP_SELECTED' }
  | { type: 'DELETE_SELECTED' }
  | { type: 'UPDATE_MODIFIERS'; modifiers: { shift: boolean; ctrl: boolean; alt: boolean } }

// =============================================================================
// Selectable Item Interface
// =============================================================================

export interface SelectableItem {
  id: string
  getBounds: () => DOMRect | null
}

// =============================================================================
// Config
// =============================================================================

export interface SelectionConfig {
  /** Minimum drag distance before marquee activates (px) */
  activationDistance?: number
  /** Color for selection ring */
  selectionColor?: 'cyan' | 'orange' | 'violet' | 'green'
  /** Enable grouping feature */
  enableGrouping?: boolean
  /** Custom hotkeys */
  hotkeys?: {
    selectAll?: string      // default: 'ctrl+a'
    deselectAll?: string    // default: 'escape'
    group?: string          // default: 'shift+g'
    ungroup?: string        // default: 'shift+u'
    delete?: string         // default: 'delete' or 'backspace'
  }
}

// =============================================================================
// Hook
// =============================================================================

export interface UseSelectionReturn {
  /** Set of currently selected IDs */
  selectedIds: Set<string>
  /** Number of selected items */
  selectedCount: number
  /** Whether any items are selected */
  hasSelection: boolean
  /** Check if specific item is selected */
  isSelected: (id: string) => boolean
  /** Select a single item */
  select: (id: string, mode?: SelectionMode) => void
  /** Select multiple items */
  selectMany: (ids: string[], mode?: SelectionMode) => void
  /** Deselect a single item */
  deselect: (id: string) => void
  /** Deselect all items */
  deselectAll: () => void
  /** Select all provided items */
  selectAll: (ids: string[]) => void
  /** Toggle selection of an item */
  toggle: (id: string) => void
  /** Group currently selected items */
  group: () => string | null
  /** Ungroup currently selected items */
  ungroup: () => void
  /** Get group ID for an item */
  getItemGroup: (id: string) => string | undefined
  /** Get group by ID */
  getGroup: (groupId: string) => GroupState | undefined
  /** All groups */
  groups: Map<string, GroupState>
}

export function useSelection(): UseSelectionReturn {
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => getSelectedIds())
  const [groups, setGroups] = useState<Map<string, GroupState>>(() => new Map())

  // Subscribe to selection changes
  useEffect(() => {
    const unsubSelection = subscribeToSelection(setSelectedIds)
    const unsubGroups = subscribeToGroups(setGroups)
    return () => {
      unsubSelection()
      unsubGroups()
    }
  }, [])

  // Memoized operations
  const select = useCallback((id: string, mode: SelectionMode = 'replace') => {
    selectItem(id, mode)
  }, [])

// Memoized operations
  const select = useCallback((id: string, mode: SelectionMode = 'replace') => {
    selectItem(id, mode)
  }, [])

  const selectMany = useCallback((ids: string[], mode: SelectionMode = 'replace') => {
    selectItems(ids, mode)
  }, [])

  const deselect = useCallback((id: string) => {
    deselectItem(id)
  }, [])

  const toggle = useCallback((id: string) => {
    selectItem(id, 'toggle')
  }, [])

  const group = useCallback(() => {
    return groupSelected()
  }, [])

  const ungroup = useCallback(() => {
    ungroupSelected()
  }, [])

  const isSelected = useCallback((id: string) => {
    return selectedIds.has(id)
  }, [selectedIds])

  return {
    selectedIds,
    selectedCount: selectedIds.size,
    hasSelection: selectedIds.size > 0,
    isSelected,
    select,
    selectMany,
    deselect,
    deselectAll,
    selectAll,
    toggle,
    group,
    ungroup,
    getItemGroup,
    getGroup,
    groups,
  }
}

// =============================================================================
// Selectable Wrapper Hook
// =============================================================================

// =============================================================================
// Selectable Wrapper Hook
// =============================================================================

/**
 * Hook for making an item selectable.
 * Returns props to spread on the element.
 *
 * @example
 * ```tsx
 * function Card({ id }) {
 *   const { selectableProps, isSelected } = useSelectable(id)
 *
 *   return (
 *     <div {...selectableProps} className={isSelected ? 'selected' : ''}>
 *       Content
 *     </div>
 *   )
 * }
 * ```
 */
export interface UseSelectableReturn {
  /** Props to spread on the selectable element */
  selectableProps: {
    'data-selectable': true
    'data-selectable-id': string
    onClick: (e: React.MouseEvent) => void
  }
  /** Whether this item is selected */
  isSelected: boolean
  /** Select this item */
  select: (mode?: SelectionMode) => void
  /** Deselect this item */
  deselect: () => void
  /** Toggle this item's selection */
  toggle: () => void
}

export function useSelectable(id: string): UseSelectableReturn {
  const [isSelected, setIsSelected] = useState(() => checkIsSelected(id))

  // Subscribe to selection changes
  useEffect(() => {
    return subscribeToSelection((selectedIds) => {
      setIsSelected(selectedIds.has(id))
    })
  }, [id])

  const select = useCallback(
    (mode: SelectionMode = 'replace') => {
      selectItem(id, mode)
    },
    [id]
  )

  const deselect = useCallback(() => {
    deselectItem(id)
  }, [id])

  const toggle = useCallback(() => {
    selectItem(id, 'toggle')
  }, [id])

  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation()
      const mode: SelectionMode = e.shiftKey ? 'add' : e.ctrlKey || e.metaKey ? 'toggle' : 'replace'
      selectItem(id, mode)
    },
    [id]
  )

return {
    selectableProps: {
      'data-selectable': true,
      'data-selectable-id': id,
      onClick: handleClick,
    },
    isSelected,
    select,
    deselect,
    toggle,
  }
}

export default useSelection

/**
 * Session Persistence Atoms
 *
 * effect-atom integration for reactive session state in React.
 * Provides runtime atoms and operation atoms for session persistence.
 *
 * @module lib/session/atoms
 */

import { Atom } from "@effect-atom/atom"
import { Effect } from "effect"
import { SessionPersistence } from "./service"
import { RouteState, PanelConfig, AppState, type SessionId } from "./schemas"

// =============================================================================
// Runtime Atom
// =============================================================================

/**
 * Session runtime atom - provides Effect runtime for all session operations
 */
export const sessionRuntimeAtom = Atom.runtime(SessionPersistence.Live)

// =============================================================================
// Initialization Atom
// =============================================================================

/**
 * Initialization state - tracks whether tables have been created
 */
export const sessionInitializedAtom = Atom.make(false)

/**
 * Initialize session persistence (call once on app start)
 */
export const initializeSession = sessionRuntimeAtom.fn(() =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    yield* service.initialize
    Atom.set(sessionInitializedAtom, true)
  })
)

// =============================================================================
// Route State Atoms
// =============================================================================

/**
 * Current route state cache
 */
export const currentRouteStateAtom = Atom.make<RouteState | null>(null)

/**
 * Load route state for a given path
 */
export const loadRouteState = sessionRuntimeAtom.fn((path: string) =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    const state = yield* service.loadRoute(path)
    if (state) {
      Atom.set(currentRouteStateAtom, state)
    }
    return state
  })
)

/**
 * Save route state (updates cache and persists)
 */
export const saveRouteState = sessionRuntimeAtom.fn((state: RouteState) =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    yield* service.saveRoute(state)
    Atom.set(currentRouteStateAtom, state)
  })
)

/**
 * Quick save current scroll position for a path
 */
export const saveCurrentScroll = sessionRuntimeAtom.fn(
  (params: { path: string; scrollX: number; scrollY: number }) =>
    Effect.gen(function* () {
      const service = yield* SessionPersistence
      const state = new RouteState({
        id: `route-${params.path.replace(/\//g, "-")}` as SessionId,
        route_path: params.path,
        scroll_x: params.scrollX,
        scroll_y: params.scrollY,
        timestamp: Date.now(),
      })
      yield* service.saveRoute(state)
      Atom.set(currentRouteStateAtom, state)
    })
)

// =============================================================================
// Panel Config Atoms
// =============================================================================

/**
 * All panel configurations cache
 */
export const panelConfigsAtom = Atom.make<readonly PanelConfig[]>([])

/**
 * Load all panel configurations
 */
export const loadAllPanels = sessionRuntimeAtom.fn(() =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    const panels = yield* service.loadAllPanels()
    Atom.set(panelConfigsAtom, panels)
    return panels
  })
)

/**
 * Save panel configuration
 */
export const savePanelConfig = sessionRuntimeAtom.fn((config: PanelConfig) =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    yield* service.savePanel(config)
    // Update cache
    Atom.update(panelConfigsAtom, (panels) => {
      const filtered = panels.filter((p) => p.panel_id !== config.panel_id)
      return [...filtered, config].sort((a, b) => a.z_index - b.z_index)
    })
  })
)

/**
 * Get panel config by ID (derived atom)
 */
export const panelConfigAtom = Atom.family((panelId: string) =>
  Atom.make((get) => {
    const panels = get(panelConfigsAtom)
    return panels.find((p) => p.panel_id === panelId) ?? null
  })
)

// =============================================================================
// App State Atoms
// =============================================================================

// =============================================================================
// App State Atoms
// =============================================================================

/**
 * App state cache (keyed by app_key)
 */
export const appStatesAtom = Atom.make<Map<string, AppState>>(new Map())

/**
 * Load app state for a given key
 */
export const loadAppState = sessionRuntimeAtom.fn((appKey: string) =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    const state = yield* service.loadAppState(appKey)
    if (state) {
      Atom.update(appStatesAtom, (map) => {
        const newMap = new Map(map)
        newMap.set(appKey, state)
        return newMap
      })
    }
    return state
  })
)

/**
 * Save app state
 */
export const saveAppState = sessionRuntimeAtom.fn((state: AppState) =>
  Effect.gen(function* () {
    const service = yield* SessionPersistence
    yield* service.saveAppState(state)
    Atom.update(appStatesAtom, (map) => {
      const newMap = new Map(map)
      newMap.set(state.app_key, state)
      return newMap
    })
  })
)

/**
 * Convenience: Save typed state for an app key
 */
export const saveTypedAppState = sessionRuntimeAtom.fn(
  <T>(params: { appKey: string; state: T }) =>
    Effect.gen(function* () {
      const service = yield* SessionPersistence
      const appState = AppState.create(params.appKey, params.state)
      yield* service.saveAppState(appState)
      Atom.update(appStatesAtom, (map) => {
        const newMap = new Map(map)
        newMap.set(params.appKey, appState)
        return newMap
      })
    })
)

/**
