/**
 * SidebarItem
 *
 * Icon button with Apple-grade micro-interactions.
 *
 * Animation Philosophy (Apple HIG):
 * - Spring physics for organic feel
 * - Layered feedback: hover → press → release → active
 * - Haptic-visual sync: quick micro-movements that feel tactile
 * - Breathing pulse for active state attention
 *
 * @module sidebar/components
 */

import { memo, useCallback, useMemo, useRef, useEffect } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import { animate } from "animejs"
import * as Option from "effect/Option"
import * as icons from "lucide-react"
import type { LucideIcon } from "lucide-react"

import type { SidebarItemConfig } from "../schemas"
import { sidebarActiveIdAtom } from "../atoms"

// ─────────────────────────────────────────────────────────────
// Animation Constants (Apple-inspired spring physics)
// ─────────────────────────────────────────────────────────────

/** Spring-like easing for organic feel */
const SPRING_OUT = "spring(1, 80, 10, 0)" // mass, stiffness, damping, velocity

/** Quick snap for press feedback */
const PRESS_DURATION = 100
const PRESS_SCALE = 0.92

/** Release spring with overshoot */
const RELEASE_DURATION = 400

/** Hover lift */
const HOVER_DURATION = 200
const HOVER_LIFT = -2 // px

/** Active indicator */
const INDICATOR_DURATION = 300

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

export interface SidebarItemProps {
  /** Item configuration */
  item: SidebarItemConfig
  /** Click handler (called after action execution) */
  onClick?: (item: SidebarItemConfig) => void
  /** Whether item is being dragged */
  isDragging?: boolean
  /** Whether Ctrl is held (for drag mode indication) */
  isCtrlHeld?: boolean
}

// ─────────────────────────────────────────────────────────────
// Icon Resolution
// ─────────────────────────────────────────────────────────────

function resolveIcon(config: SidebarItemConfig["icon"]): LucideIcon | null {
  if (config.type === "lucide") {
    const pascalName = config.value
      .split("-")
      .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
      .join("")

    const Icon = (icons as Record<string, LucideIcon>)[pascalName]
    return Icon ?? icons.HelpCircle
  }

  return icons.HelpCircle
}

// ─────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────

export const SidebarItem = memo(function SidebarItem({
  item,
  onClick,
  isDragging = false,
  isCtrlHeld = false,
}: SidebarItemProps) {
  // State
  const activeIdOption = useAtomValue(sidebarActiveIdAtom)
  const isActive = useMemo(
    () => Option.isSome(activeIdOption) && activeIdOption.value === item.id,
    [activeIdOption, item.id]
  )

  // Refs for animation targets
  const buttonRef = useRef<HTMLButtonElement>(null)
  const iconRef = useRef<HTMLSpanElement>(null)
  const indicatorRef = useRef<HTMLSpanElement>(null)
  const wasActive = useRef(isActive)
  const isPressed = useRef(false)

  // Icon setup
  const Icon = useMemo(() => resolveIcon(item.icon), [item.icon])
  const iconSize = item.icon.size ?? 20

  // ─── Hover Animation ─────────────────────────────────────────
  const handleMouseEnter = useCallback(() => {
    if (item.disabled) return
    if (!buttonRef.current || !iconRef.current) return

    // Lift button slightly
    animate(buttonRef.current, {
      translateY: HOVER_LIFT,
      duration: HOVER_DURATION,
      easing: "easeOutCubic",
    })

// Lift button slightly
    animate(buttonRef.current, {
      translateY: HOVER_LIFT,
      duration: HOVER_DURATION,
      easing: "easeOutCubic",
    })

    // Brighten icon
    animate(iconRef.current, {
      scale: 1.08,
      duration: HOVER_DURATION,
      easing: "easeOutCubic",
    })
  }, [item.disabled])

  const handleMouseLeave = useCallback(() => {
    if (item.disabled) return
    if (isPressed.current) return // Don't reset if still pressed
    if (!buttonRef.current || !iconRef.current) return

    // Return to rest
    animate(buttonRef.current, {
      translateY: 0,
      duration: HOVER_DURATION,
      easing: "easeOutCubic",
    })

    animate(iconRef.current, {
      scale: 1,
      duration: HOVER_DURATION,
      easing: "easeOutCubic",
    })
  }, [item.disabled])

  // ─── Press Animation ─────────────────────────────────────────
  const handleMouseDown = useCallback(() => {
    if (item.disabled || !buttonRef.current || !iconRef.current) return
    isPressed.current = true

    // Quick scale down (haptic feel)
    animate(buttonRef.current, {
      scale: PRESS_SCALE,
      translateY: 0, // Cancel hover lift
      duration: PRESS_DURATION,
      easing: "easeOutQuad",
    })

    // Icon squish
    animate(iconRef.current, {
      scale: 0.9,
      duration: PRESS_DURATION,
      easing: "easeOutQuad",
    })
  }, [item.disabled])

  const handleMouseUp = useCallback(() => {
    if (item.disabled || !buttonRef.current || !iconRef.current) return
    isPressed.current = false

const handleMouseUp = useCallback(() => {
    if (item.disabled || !buttonRef.current || !iconRef.current) return
    isPressed.current = false

    // Spring back with overshoot
    animate(buttonRef.current, {
      scale: [PRESS_SCALE, 1.02, 1], // overshoot then settle
      translateY: 0,
      duration: RELEASE_DURATION,
      easing: SPRING_OUT,
    })

    // Icon bounce back
    animate(iconRef.current, {
      scale: [0.9, 1.12, 1], // bounce overshoot
      duration: RELEASE_DURATION,
      easing: SPRING_OUT,
    })
  }, [item.disabled])

  // ─── Click Handler ───────────────────────────────────────────
  const handleClick = useCallback(() => {
    if (item.disabled) return
    onClick?.(item)
  }, [item, onClick])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault()
        handleClick()
      }
    },
    [handleClick]
  )

  // ─── Active State Animation ──────────────────────────────────
  useEffect(() => {
    if (wasActive.current === isActive) return
    wasActive.current = isActive

    if (!indicatorRef.current || !iconRef.current) return

    if (isActive) {
      // Indicator slides in from left with spring
      animate(indicatorRef.current, {
        scaleY: [0, 1.15, 1], // overshoot
        opacity: [0, 1],
        duration: INDICATOR_DURATION,
        easing: SPRING_OUT,
      })

// Icon pop on activation
      animate(iconRef.current, {
        scale: [1, 1.15, 1],
        duration: 300,
        easing: SPRING_OUT,
      })
    } else {
      // Indicator slides out
      animate(indicatorRef.current, {
        scaleY: [1, 0],
        opacity: [1, 0],
        duration: 150,
        easing: "easeInQuad",
      })
    }
  }, [isActive])

  // ─── Styles ──────────────────────────────────────────────────
  const baseClasses = [
    "relative flex items-center justify-center",
    "w-10 h-10 rounded-lg",
    "focus:outline-none focus-visible:ring-2 focus-visible:ring-white/20",
    "will-change-transform", // GPU acceleration hint
  ]

  const stateClasses = item.disabled
    ? ["opacity-40 cursor-not-allowed"]
    : isActive
      ? ["text-white"]
      : ["text-neutral-500 hover:text-neutral-200"]

  const dragClasses = isDragging
    ? ["opacity-50"]
    : isCtrlHeld && item.group === "plugin"
      ? ["cursor-grab"]
      : []

const dragClasses = isDragging
    ? ["opacity-50"]
    : isCtrlHeld && item.group === "plugin"
      ? ["cursor-grab"]
      : []

  return (
    <div
      className="relative flex items-center justify-center"
      data-sidebar-item-id={item.id}
      data-sidebar-group={item.group}
    >
      <button
        ref={buttonRef}
        type="button"
        className={[...baseClasses, ...stateClasses, ...dragClasses].join(" ")}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        disabled={item.disabled}
        aria-label={item.label}
        aria-pressed={isActive}
        title={item.label}
        style={{ transform: "translateY(0) scale(1)" }}
      >
        {/* Hover background */}
        <span
          className="absolute inset-0 rounded-lg bg-white/0 hover:bg-white/5 transition-colors duration-150 pointer-events-none"
          aria-hidden="true"
        />

        {/* Icon container */}
        <span
          ref={iconRef}
          className="relative z-10"
          style={{ transform: "scale(1)" }}
        >
          {Icon && <Icon size={iconSize} strokeWidth={1.5} />}
        </span>

        {/* Active indicator - white bar */}
        <span
          ref={indicatorRef}
          className="absolute left-0 top-1/2 w-[3px] h-5 rounded-r-full pointer-events-none bg-white"
          style={{
            transform: "translateY(-50%) scaleY(0)",
            transformOrigin: "center",
            opacity: 0,
          }}
          aria-hidden="true"
        />

{/* Keyboard shortcut badge */}
        {item.shortcut && !isDragging && (
          <span
            className="absolute -bottom-0.5 -right-0.5 px-1 font-label text-neutral-600 bg-neutral-900/90 rounded border border-neutral-800"
            style={{ fontSize: "var(--tmnl-text-xs, 12px)" }}
            aria-hidden="true"
          >
            {item.shortcut}
          </span>
        )}
      </button>
    </div>
  )
})

/**
 * SidebarTooltip
 *
 * Tooltip component for sidebar items.
 * Shows label and optional keyboard shortcut.
 *
 * @module sidebar/components
 */

import { memo, useState, useRef, useEffect } from "react"
import { createPortal } from "react-dom"

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

export interface SidebarTooltipProps {
  /** Label text */
  label: string
  /** Optional keyboard shortcut */
  shortcut?: string
  /** Trigger element ref */
  triggerRef: React.RefObject<HTMLElement>
  /** Whether tooltip is visible */
  isVisible: boolean
  /** Position relative to trigger */
  position?: "right" | "bottom"
  /** Delay before showing (ms) */
  delay?: number
}

// ─────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────

/**
 * Tooltip for sidebar items.
 *
 * Positioned to the right of the trigger by default.
 * Uses portal to render at document root for proper z-index.
 */
export const SidebarTooltip = memo(function SidebarTooltip({
  label,
  shortcut,
  triggerRef,
  isVisible,
  position = "right",
  delay = 200,
}: SidebarTooltipProps) {
  const [coords, setCoords] = useState({ top: 0, left: 0 })
  const [shouldShow, setShouldShow] = useState(false)
  const timeoutRef = useRef<NodeJS.Timeout | null>(null)

  // Handle delayed show
  useEffect(() => {
    if (isVisible) {
      timeoutRef.current = setTimeout(() => {
        setShouldShow(true)
      }, delay)
    } else {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
      setShouldShow(false)
    }

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [isVisible, delay])

  // Calculate position
  useEffect(() => {
    if (!shouldShow || !triggerRef.current) return

// Calculate position
  useEffect(() => {
    if (!shouldShow || !triggerRef.current) return

    const rect = triggerRef.current.getBoundingClientRect()

    if (position === "right") {
      setCoords({
        top: rect.top + rect.height / 2,
        left: rect.right + 8,
      })
    } else {
      setCoords({
        top: rect.bottom + 8,
        left: rect.left + rect.width / 2,
      })
    }
  }, [shouldShow, triggerRef, position])

  if (!shouldShow) return null

  const tooltipContent = (
    <div
      className={`
        fixed z-50
        px-2 py-1
        bg-neutral-800 border border-neutral-700
        rounded shadow-lg
        text-xs text-neutral-200
        whitespace-nowrap
        pointer-events-none
        animate-in fade-in-0 zoom-in-95
        duration-150
      `}
      style={{
        top: coords.top,
        left: coords.left,
        transform:
          position === "right"
            ? "translateY(-50%)"
            : "translateX(-50%)",
      }}
      role="tooltip"
    >
      <span>{label}</span>
      {shortcut && (
        <span className="ml-2 px-1 py-0.5 bg-neutral-900 rounded text-neutral-500 font-mono">
          {shortcut}
        </span>
      )}
    </div>
  )

  // Render in portal
  return createPortal(tooltipContent, document.body)
})

// ─────────────────────────────────────────────────────────────
// Hook for tooltip state
// ─────────────────────────────────────────────────────────────

/**
 * Hook for managing tooltip visibility.
 */
export function useTooltipState() {
  const [isVisible, setIsVisible] = useState(false)

  const show = () => setIsVisible(true)
  const hide = () => setIsVisible(false)

  return { isVisible, show, hide }
}

/**
 * useSidebar
 *
 * Consumer hook for sidebar state and operations.
 *
 * @module sidebar/hooks
 */

import { useMemo, useCallback } from "react"
import { useAtomValue } from "@effect-atom/atom-react"
import * as Option from "effect/Option"

import type { SidebarItemId } from "../schemas"
import {
  sidebarCollapsedAtom,
  sidebarActiveIdAtom,
  sortedSidebarItemsAtom,
  setActiveId,
  clearActiveId,
  toggleCollapsed,
  setCollapsed,
} from "../atoms"

/**
 * Hook return type for useSidebar.
 */
export interface UseSidebarReturn {
  /** Whether sidebar is collapsed */
  isCollapsed: boolean
  /** Currently active item ID (or null) */
  activeId: SidebarItemId | null
  /** Core items (sorted) */
  coreItems: ReturnType<typeof useAtomValue<typeof sortedSidebarItemsAtom>>["core"]
  /** Plugin items (sorted by user order) */
  pluginItems: ReturnType<typeof useAtomValue<typeof sortedSidebarItemsAtom>>["plugins"]
  /** Set active item by ID */
  setActive: (id: SidebarItemId | null) => void
  /** Clear active item */
  clearActive: () => void
  /** Toggle collapsed state */
  toggle: () => void
  /** Set collapsed state */
  setCollapsed: (collapsed: boolean) => void
}

/**
 * Consumer hook for sidebar state and operations.
 *
 * @example
 * ```tsx
 * function MyComponent() {
 *   const { isCollapsed, activeId, toggle } = useSidebar()
 *
 *   return (
 *     <div>
 *       <p>Collapsed: {isCollapsed ? 'Yes' : 'No'}</p>
 *       <p>Active: {activeId ?? 'None'}</p>
 *       <button onClick={toggle}>Toggle</button>
 *     </div>
 *   )
 * }
 * ```
 */
export function useSidebar(): UseSidebarReturn {
  // Subscribe to state (registry provided via OverlayRegistryProvider context)
  const isCollapsed = useAtomValue(sidebarCollapsedAtom)
  const activeIdOption = useAtomValue(sidebarActiveIdAtom)
  const { core, plugins } = useAtomValue(sortedSidebarItemsAtom)

  // Derive active ID
  const activeId = useMemo(
    () => (Option.isSome(activeIdOption) ? activeIdOption.value : null),
    [activeIdOption]
  )

  // Memoized operations
  const setActive = useCallback((id: SidebarItemId | null) => {
    setActiveId(id)
  }, [])

  const clearActive = useCallback(() => {
    clearActiveId()
  }, [])

  const toggle = useCallback(() => {
    toggleCollapsed()
  }, [])

  const setCollapsedState = useCallback((collapsed: boolean) => {
    setCollapsed(collapsed)
  }, [])

  return {
    isCollapsed,
    activeId,
    coreItems: core,
    pluginItems: plugins,
    setActive,
    clearActive,
    toggle,
    setCollapsed: setCollapsedState,
  }
}

/**
 * useSidebarDrag
 *
 * Hook for Ctrl+drag reordering of plugin sidebar items.
 *
 * @module sidebar/hooks
 */

import { useState, useCallback, useRef, useEffect } from "react"
import { useAtomValue } from "@effect-atom/atom-react"

import type { SidebarItemId, SidebarItemConfig } from "../schemas"
import {
  pluginItemsAtom,
  movePlugin,
} from "../atoms"

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

export interface DragState {
  /** Whether drag is active */
  isDragging: boolean
  /** ID of item being dragged */
  draggedId: SidebarItemId | null
  /** Current drop target index */
  dropIndex: number | null
  /** Drag start position */
  startY: number
  /** Current drag position */
  currentY: number
}

export interface UseSidebarDragReturn {
  /** Current drag state */
  dragState: DragState
  /** Whether Ctrl key is held */
  isCtrlHeld: boolean
  /** Start dragging an item */
  startDrag: (id: SidebarItemId, startY: number) => void
  /** Update drag position */
  updateDrag: (currentY: number) => void
  /** End drag and commit reorder */
  endDrag: () => void
  /** Cancel drag without committing */
  cancelDrag: () => void
  /** Get props for a draggable item */
  getDragProps: (item: SidebarItemConfig) => DragItemProps
}

export interface DragItemProps {
  onPointerDown: (e: React.PointerEvent) => void
  "data-dragging": boolean
  "data-drop-target": boolean
  style: React.CSSProperties
}

// ─────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────

const ITEM_HEIGHT = 40 // px - matches SidebarItem height
const DRAG_THRESHOLD = 5 // px - minimum movement to start drag

const ITEM_HEIGHT = 40 // px - matches SidebarItem height
const DRAG_THRESHOLD = 5 // px - minimum movement to start drag

// ─────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────

/**
 * Hook for managing Ctrl+drag reordering of plugin items.
 *
 * @example
 * ```tsx
 * function PluginSection() {
 *   const { dragState, isCtrlHeld, getDragProps } = useSidebarDrag()
 *   const plugins = useAtomValue(pluginItemsAtom)
 *
 *   return (
 *     <div>
 *       {plugins.map((item, index) => (
 *         <SidebarItem
 *           key={item.id}
 *           item={item}
 *           {...getDragProps(item)}
 *         />
 *       ))}
 *       {dragState.isDragging && <SidebarDragOverlay {...dragState} />}
 *     </div>
 *   )
 * }
 * ```
 */
export function useSidebarDrag(): UseSidebarDragReturn {
  // Plugin items for calculating drop index (registry via OverlayRegistryProvider)
  const plugins = useAtomValue(pluginItemsAtom)

  // Ctrl key state
  const [isCtrlHeld, setIsCtrlHeld] = useState(false)

  // Drag state
  const [dragState, setDragState] = useState<DragState>({
    isDragging: false,
    draggedId: null,
    dropIndex: null,
    startY: 0,
    currentY: 0,
  })

  // Refs for drag tracking
  const pendingDragRef = useRef<{
    id: SidebarItemId
    startY: number
    triggered: boolean
  } | null>(null)

// Refs for drag tracking
  const pendingDragRef = useRef<{
    id: SidebarItemId
    startY: number
    triggered: boolean
  } | null>(null)

  // Ctrl key tracking
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Control") setIsCtrlHeld(true)
    }
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.key === "Control") {
        setIsCtrlHeld(false)
        // Cancel any active drag when Ctrl is released
        if (dragState.isDragging) {
          cancelDrag()
        }
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    window.addEventListener("keyup", handleKeyUp)
    return () => {
      window.removeEventListener("keydown", handleKeyDown)
      window.removeEventListener("keyup", handleKeyUp)
    }
  }, [dragState.isDragging])

  // Start drag
  const startDrag = useCallback((id: SidebarItemId, startY: number) => {
    pendingDragRef.current = { id, startY, triggered: false }
  }, [])

  // Update drag position
  const updateDrag = useCallback(
    (currentY: number) => {
      // Check for pending drag that hasn't triggered yet
      if (pendingDragRef.current && !pendingDragRef.current.triggered) {
        const delta = Math.abs(currentY - pendingDragRef.current.startY)
        if (delta >= DRAG_THRESHOLD) {
          // Trigger drag
          pendingDragRef.current.triggered = true
          setDragState({
            isDragging: true,
            draggedId: pendingDragRef.current.id,
            dropIndex: null,
            startY: pendingDragRef.current.startY,
            currentY,
          })
        }
        return
      }

      // Update active drag
      if (dragState.isDragging && dragState.draggedId) {
        // Calculate drop index based on Y position
        const draggedIndex = plugins.findIndex((p) => p.id === dragState.draggedId)
        if (draggedIndex === -1) return

const deltaY = currentY - dragState.startY
        const indexDelta = Math.round(deltaY / ITEM_HEIGHT)
        const newIndex = Math.max(
          0,
          Math.min(plugins.length - 1, draggedIndex + indexDelta)
        )

        setDragState((prev) => ({
          ...prev,
          currentY,
          dropIndex: newIndex !== draggedIndex ? newIndex : null,
        }))
      }
    },
    [dragState.isDragging, dragState.draggedId, dragState.startY, plugins]
  )

  // End drag and commit
  const endDrag = useCallback(() => {
    if (dragState.isDragging && dragState.draggedId && dragState.dropIndex !== null) {
      movePlugin(dragState.draggedId, dragState.dropIndex)
    }

    pendingDragRef.current = null
    setDragState({
      isDragging: false,
      draggedId: null,
      dropIndex: null,
      startY: 0,
      currentY: 0,
    })
  }, [dragState])

  // Cancel drag
  const cancelDrag = useCallback(() => {
    pendingDragRef.current = null
    setDragState({
      isDragging: false,
      draggedId: null,
      dropIndex: null,
      startY: 0,
      currentY: 0,
    })
  }, [])

  // Get drag props for an item
  const getDragProps = useCallback(
    (item: SidebarItemConfig): DragItemProps => {
      const isPluginItem = item.group === "plugin"
      const isDragging = dragState.draggedId === item.id
      const itemIndex = plugins.findIndex((p) => p.id === item.id)
      const isDropTarget = dragState.dropIndex === itemIndex && !isDragging

      return {
        onPointerDown: (e: React.PointerEvent) => {
          if (!isCtrlHeld || !isPluginItem) return
          e.preventDefault()
          startDrag(item.id, e.clientY)

return {
        onPointerDown: (e: React.PointerEvent) => {
          if (!isCtrlHeld || !isPluginItem) return
          e.preventDefault()
          startDrag(item.id, e.clientY)

          // Set up pointer capture for drag tracking
          const target = e.currentTarget as HTMLElement
          target.setPointerCapture(e.pointerId)

          const handleMove = (moveEvent: PointerEvent) => {
            updateDrag(moveEvent.clientY)
          }

          const handleUp = () => {
            target.releasePointerCapture(e.pointerId)
            target.removeEventListener("pointermove", handleMove)
            target.removeEventListener("pointerup", handleUp)
            target.removeEventListener("pointercancel", handleUp)
            endDrag()
          }

          target.addEventListener("pointermove", handleMove)
          target.addEventListener("pointerup", handleUp)
          target.addEventListener("pointercancel", handleUp)
        },
        "data-dragging": isDragging,
        "data-drop-target": isDropTarget,
        style: {
          cursor: isCtrlHeld && isPluginItem ? "grab" : undefined,
          opacity: isDragging ? 0.5 : 1,
          transform: isDragging
            ? `translateY(${dragState.currentY - dragState.startY}px)`
            : undefined,
          transition: isDragging ? "none" : "transform 150ms ease-out",
        },
      }
    },
    [isCtrlHeld, dragState, plugins, startDrag, updateDrag, endDrag]
  )

  return {
    dragState,
    isCtrlHeld,
    startDrag,
    updateDrag,
    endDrag,
    cancelDrag,
    getDragProps,
  }
}

/**
 * useSidebarItem
 *
 * Hook for registering plugin sidebar items.
 * Items are automatically unregistered on unmount.
 *
 * @module sidebar/hooks
 */

import { useEffect, useRef } from "react"

import type { SidebarItemConfig, SidebarItemId } from "../schemas"
import { registerItem, unregisterItem } from "../atoms"

/**
 * Options for useSidebarItem.
 */
export interface UseSidebarItemOptions {
  /** Item configuration */
  item: SidebarItemConfig
  /** Whether registration is enabled (default: true) */
  enabled?: boolean
}

/**
 * Hook for registering a plugin sidebar item.
 *
 * The item is registered on mount and unregistered on unmount.
 * Use this hook in plugin components that need sidebar presence.
 *
 * @example
 * ```tsx
 * function MyPluginPanel() {
 *   useSidebarItem({
 *     item: {
 *       id: "my-plugin" as SidebarItemId,
 *       label: "My Plugin",
 *       icon: { type: "lucide", value: "puzzle" },
 *       group: "plugin",
 *       action: { _tag: "DrawerAction", drawerId: "my-plugin", side: "right" },
 *     },
 *   })
 *
 *   return <div>Plugin content</div>
 * }
 * ```
 */
export function useSidebarItem({ item, enabled = true }: UseSidebarItemOptions): void {
  // Track registered ID for cleanup
  const registeredIdRef = useRef<SidebarItemId | null>(null)

  useEffect(() => {
    if (!enabled) {
      // If disabled and previously registered, unregister
      if (registeredIdRef.current !== null) {
        unregisterItem(registeredIdRef.current)
        registeredIdRef.current = null
      }
      return
    }

    // Register item
    registerItem(item)
    registeredIdRef.current = item.id

// Register item
    registerItem(item)
    registeredIdRef.current = item.id

    // Cleanup on unmount or when item changes
    return () => {
      if (registeredIdRef.current !== null) {
        unregisterItem(registeredIdRef.current)
        registeredIdRef.current = null
      }
    }
  }, [item, enabled])
}

/**
 * Hook for registering multiple plugin sidebar items.
 *
 * @example
 * ```tsx
 * function MyPluginSuite() {
 *   useSidebarItems({
 *     items: [
 *       { id: "plugin-a" as SidebarItemId, ... },
 *       { id: "plugin-b" as SidebarItemId, ... },
 *     ],
 *   })
 *
 *   return <div>Plugin suite</div>
 * }
 * ```
 */
export function useSidebarItems({
  items,
  enabled = true,
}: {
  items: SidebarItemConfig[]
  enabled?: boolean
}): void {
  const registeredIdsRef = useRef<SidebarItemId[]>([])

  useEffect(() => {
    if (!enabled) {
      // Unregister all if disabled
      for (const id of registeredIdsRef.current) {
        unregisterItem(id)
      }
      registeredIdsRef.current = []
      return
    }

    // Register all items
    for (const item of items) {
      registerItem(item)
    }
    registeredIdsRef.current = items.map((i) => i.id)

    // Cleanup on unmount
    return () => {
      for (const id of registeredIdsRef.current) {
        unregisterItem(id)
      }
      registeredIdsRef.current = []
    }
  }, [items, enabled])
}

/**
