interface ValueDisplayProps {
  value: number
  displayValue: string
  isEditing: boolean
  editValue: string
  onEditChange: (value: string) => void
  onValueClick: () => void
  onEditKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void
  onEditBlur: () => void
  inputRef: React.RefObject<HTMLInputElement>
  config: { precision: number; unit: string }
}

function ValueDisplay({
  displayValue,
  isEditing,
  editValue,
  onEditChange,
  onValueClick,
  onEditKeyDown,
  onEditBlur,
  inputRef,
  config,
}: ValueDisplayProps) {
  if (isEditing) {
    return (
      <input
        ref={inputRef}
        type="text"
        value={editValue}
        onChange={(e) => onEditChange(e.target.value)}
        onKeyDown={onEditKeyDown}
        onBlur={onEditBlur}
        className="w-16 px-2 py-1 bg-neutral-900 border border-cyan-600 rounded text-sm font-stats text-cyan-300 text-right focus:outline-none"
        onClick={(e) => e.stopPropagation()}
      />
    )
  }

  return (
    <div
      onClick={(e) => {
        e.stopPropagation()
        onValueClick()
      }}
      className="min-w-[4rem] px-2 py-1 text-sm font-stats text-neutral-300 text-right hover:text-cyan-400 hover:bg-neutral-800/50 rounded cursor-text transition-colors"
    >
      {displayValue}
    </div>
  )
}

