/**
 * Slider V2 Atoms
 *
 * Effect-atom based state management for slider instances.
 */

import { Atom } from '@effect-atom/atom'
import type { SliderState, SliderConfig, SliderEvent, ModifierKeys } from '../types'
import { DEFAULT_MODIFIERS, initialSliderState } from '../types'

// =============================================================================
// SLIDER STATE REDUCER
// =============================================================================

/**
 * Pure reducer for slider state transitions
 */
export function sliderReducer(
  state: SliderState,
  event: SliderEvent,
  config: SliderConfig
): SliderState {
  switch (event.type) {
    case 'DRAG_START':
      return {
        ...state,
        isDragging: true,
        modifiers: event.modifiers,
      }

    case 'DRAG_MOVE': {
      // Clamp value to bounds
      const range = config.max - config.min
      const normalizedPosition = Math.max(0, Math.min(1, event.position))
      const rawValue = config.min + normalizedPosition * range

      // Apply step if configured
      let value = rawValue
      if (config.step && config.step > 0) {
        value = Math.round(rawValue / config.step) * config.step
      }

      // Clamp to bounds
      value = Math.max(config.min, Math.min(config.max, value))
      const normalizedValue = (value - config.min) / range

      return {
        ...state,
        value,
        normalizedValue,
        visualPosition: normalizedPosition, // Visual can extend during overshoot
        modifiers: event.modifiers,
      }
    }

    case 'DRAG_END':
      return {
        ...state,
        isDragging: false,
        modifiers: DEFAULT_MODIFIERS,
      }

    case 'SET_VALUE': {
      const range = config.max - config.min
      const value = Math.max(config.min, Math.min(config.max, event.value))
      const normalizedValue = (value - config.min) / range

      return {
        ...state,
        value,
        normalizedValue,
        visualPosition: normalizedValue,
      }
    }

return {
        ...state,
        value,
        normalizedValue,
        visualPosition: normalizedValue,
      }
    }

    case 'ANIMATE_START':
      return {
        ...state,
        isAnimating: true,
      }

    case 'ANIMATE_END':
      return {
        ...state,
        isAnimating: false,
      }

    case 'RESET':
      return initialSliderState(config)

    default:
      return state
  }
}

// =============================================================================
// SLIDER STATE FAMILY
// =============================================================================

/**
 * Create a slider state atom family for multiple slider instances
 */
export function createSliderStateFamily() {
  const family = new Map<string, Atom.Atom<SliderState>>()

  return {
    /**
     * Get or create a slider state atom for the given ID
     */
    get: (sliderId: string, config: SliderConfig): Atom.Atom<SliderState> => {
      let atom = family.get(sliderId)
      if (!atom) {
        atom = Atom.make(initialSliderState(config))
        family.set(sliderId, atom)
      }
      return atom
    },

    /**
     * Clear a slider state from the family
     */
    clear: (sliderId: string): void => {
      family.delete(sliderId)
    },

    /**
     * Clear all slider states
     */
    clearAll: (): void => {
      family.clear()
    },

    /**
     * Get all slider IDs
     */
    ids: (): string[] => Array.from(family.keys()),
  }
}

/**
 * Global slider state family instance
 */
export const sliderStateFamily = createSliderStateFamily()

// =============================================================================
// MODIFIER KEYS HELPERS
// =============================================================================

/**
 * Extract modifier keys from a pointer/keyboard event
 */
export function extractModifiers(
  event: PointerEvent | KeyboardEvent | MouseEvent
): ModifierKeys {
  return {
    shift: event.shiftKey,
    ctrl: event.ctrlKey,
    alt: event.altKey,
    meta: event.metaKey,
  }
}

/**
 * Check if any modifier is active
 */
export function hasActiveModifier(modifiers: ModifierKeys): boolean {
  return modifiers.shift || modifiers.ctrl || modifiers.alt || modifiers.meta
}

/**
 * Slider V2 Component
 *
 * Minimal slider with trait-based composition.
 * Matches V1 visual style but keeps trait injection capability.
 */

import { useEffect } from 'react'
import { TraitProvider, useInject } from '@/lib/traits'
import { cn } from '@/lib/utils'
import { useSlider, type UseSliderOptions } from '../hooks/useSlider'
import type { SliderConfig, GlowSlot, SnapSlot, CurveSlot, OvershootSlot, PrecisionSlot } from '../types'
import { GlowTrait, SnapTrait, CurveTrait, OvershootTrait, PrecisionTrait } from '../traits'

// =============================================================================
// TYPES
// =============================================================================

export interface SliderProps extends UseSliderOptions {
  /** Unique identifier for this slider instance */
  id: string

  /** Slider configuration */
  config: SliderConfig

  /** Optional class name */
  className?: string

  // Trait injections (optional - can also be injected externally)
  glow?: Partial<GlowSlot>
  snap?: Partial<SnapSlot>
  curve?: Partial<CurveSlot>
  overshoot?: Partial<OvershootSlot>
  precision?: Partial<PrecisionSlot>
}

// =============================================================================
// SLIDER DEFAULTS
// =============================================================================

const SLIDER_DEFAULTS = {
  glow: GlowTrait.defaultSlot!,
  snap: SnapTrait.defaultSlot!,
  curve: CurveTrait.defaultSlot!,
  overshoot: OvershootTrait.defaultSlot!,
  precision: PrecisionTrait.defaultSlot!,
}

// =============================================================================
// INNER SLIDER (inside TraitProvider)
// =============================================================================

function SliderInner({
  id,
  config,
  className,
  glow,
  snap,
  curve,
  overshoot,
  precision,
  ...options
}: SliderProps) {
  const { inject } = useInject()

function SliderInner({
  id,
  config,
  className,
  glow,
  snap,
  curve,
  overshoot,
  precision,
  ...options
}: SliderProps) {
  const { inject } = useInject()

  // Inject trait slots on mount
  useEffect(() => {
    inject(GlowTrait, id, { ...SLIDER_DEFAULTS.glow, ...glow })
    inject(SnapTrait, id, { ...SLIDER_DEFAULTS.snap, ...snap })
    inject(CurveTrait, id, { ...SLIDER_DEFAULTS.curve, ...curve })
    inject(OvershootTrait, id, { ...SLIDER_DEFAULTS.overshoot, ...overshoot })
    inject(PrecisionTrait, id, { ...SLIDER_DEFAULTS.precision, ...precision })
  }, [inject, id, glow, snap, curve, overshoot, precision])

  // Use slider hook
  const slider = useSlider(id, config, options)

  return (
    <div
      data-slider-id={id}
      className={cn(
        'relative select-none touch-none',
        slider.className,
        className
      )}
      style={slider.style}
    >
      {/* Track */}
      <div
        ref={slider.trackRef}
        className={cn(
          'relative h-2 bg-neutral-700 rounded-full cursor-pointer',
          slider.isDragging && 'cursor-grabbing'
        )}
        {...slider.handlers}
      >
        {/* Fill */}
        <div
          ref={slider.fillRef}
          className="absolute inset-y-0 left-0 bg-cyan-500 rounded-full pointer-events-none"
          style={{
            width: `${slider.normalizedValue * 100}%`,
            transition: slider.isDragging ? 'none' : 'width 75ms ease-out',
          }}
        />

{/* Thumb */}
        <div
          ref={slider.thumbRef}
          className={cn(
            'absolute top-1/2 w-4 h-4 -translate-y-1/2 -translate-x-1/2',
            'bg-white rounded-full shadow-lg pointer-events-none',
            'transition-transform duration-75',
            slider.isDragging && 'scale-125',
            !slider.isDragging && 'scale-100'
          )}
          style={{
            left: `${slider.normalizedValue * 100}%`,
          }}
        />
      </div>
    </div>
  )
}

// =============================================================================
// SLIDER (with TraitProvider wrapper)
// =============================================================================

export function Slider(props: SliderProps) {
  return (
    <TraitProvider>
      <SliderInner {...props} />
    </TraitProvider>
  )
}

export default Slider

/**
 * EmanationEffect
 *
 * Soft clamp glow burst at boundary or snap points.
 * Creates temporary glow ring that expands and fades.
 */

import { Effect } from 'effect'
import { animate } from 'animejs'
import { TIMING, EASING, GLOW_COLORS } from '../types'
import type { GlowSlot } from '../types'

/**
 * Create an emanation (glow burst) Effect program
 *
 * @param containerElement - The container to append the glow ring to
 * @param position - Position of the emanation (x, y relative to container)
 * @param color - Glow color from palette
 * @param duration - Emanation duration in ms
 * @returns Effect that completes when animation finishes and cleans up
 */
export const createEmanationEffect = (
  containerElement: HTMLElement,
  position: { x: number; y: number },
  color: GlowSlot['color'] = 'cyan',
  duration: number = TIMING.emanation
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:emanation')(
    Effect.async<void, Error>((resume) => {
      try {
        // Create the glow ring element
        const ring = document.createElement('div')
        ring.className = 'slider-emanation-ring'
        ring.style.cssText = `
          position: absolute;
          left: ${position.x}px;
          top: ${position.y}px;
          width: 0;
          height: 0;
          border-radius: 50%;
          pointer-events: none;
          transform: translate(-50%, -50%);
          box-shadow: 0 0 0 0 ${GLOW_COLORS[color]};
          background: transparent;
        `

        containerElement.appendChild(ring)

containerElement.appendChild(ring)

        // Animate: expand and fade
        const anim = animate(ring, {
          width: ['0px', '40px'],
          height: ['0px', '40px'],
          boxShadow: [
            `0 0 0 0 ${GLOW_COLORS[color]}`,
            `0 0 20px 10px transparent`,
          ],
          opacity: [1, 0],
          duration: duration * 2, // Expand + fade takes longer
          easing: EASING.glow,
        })

        // Cleanup on completion
        anim.then(() => {
          ring.remove()
          resume(Effect.succeed(undefined))
        })

        // Return cleanup (fiber cancellation)
        return Effect.sync(() => {
          anim.pause()
          ring.remove()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Emanation animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

/**
 * Create a boundary emanation at either end of the slider
 *
 * @param trackElement - The track element
 * @param boundary - Which boundary ('min' or 'max')
 * @param color - Glow color
 * @returns Effect that completes when animation finishes
 */
export const createBoundaryEmanationEffect = (
  trackElement: HTMLElement,
  boundary: 'min' | 'max',
  color: GlowSlot['color'] = 'cyan'
): Effect.Effect<void, Error> => {
  const rect = trackElement.getBoundingClientRect()
  const position = {
    x: boundary === 'min' ? 0 : rect.width,
    y: rect.height / 2,
  }

  return createEmanationEffect(trackElement, position, color)
}

return createEmanationEffect(trackElement, position, color)
}

/**
 * Create emanation at a snap point
 *
 * @param trackElement - The track element
 * @param normalizedPosition - Snap point position (0-1)
 * @param color - Glow color
 * @returns Effect that completes when animation finishes
 */
export const createSnapEmanationEffect = (
  trackElement: HTMLElement,
  normalizedPosition: number,
  color: GlowSlot['color'] = 'cyan'
): Effect.Effect<void, Error> => {
  const rect = trackElement.getBoundingClientRect()
  const position = {
    x: normalizedPosition * rect.width,
    y: rect.height / 2,
  }

  return createEmanationEffect(trackElement, position, color)
}

/**
 * OvershootEffect
 *
 * 15% elastic overshoot with rubber-band return.
 * Two-phase animation: fast extension, then tactical settle.
 */

import { Effect } from 'effect'
import { animate, createTimeline } from 'animejs'
import { TIMING, EASING } from '../types'

/**
 * Create an overshoot animation Effect program
 *
 * @param thumbElement - The thumb DOM element to animate
 * @param boundaryPosition - The boundary position (0 or 1 normalized → pixel value)
 * @param overshootTarget - The overshoot target position (extends past boundary)
 * @param settleMs - Rubber-band settle duration
 * @param easing - Easing for settle phase
 * @returns Effect that completes when animation finishes
 */
export const createOvershootEffect = (
  thumbElement: HTMLElement,
  boundaryPosition: number,
  overshootTarget: number,
  settleMs: number = TIMING.settle,
  easing: string = EASING.settleBack
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:overshoot')(
    Effect.async<void, Error>((resume) => {
      try {
        const timeline = createTimeline({
          autoplay: true,
        })

        // Phase 1: Fast extension to overshoot (30ms)
        timeline.add(thumbElement, {
          translateX: overshootTarget,
          duration: TIMING.overshootExtend,
          easing: EASING.extend,
        })

        // Phase 2: Rubber-band back to boundary
        timeline.add(thumbElement, {
          translateX: boundaryPosition,
          duration: settleMs,
          easing,
        })

        // Resume on completion
        timeline.then(() => resume(Effect.succeed(undefined)))

        // Return cleanup (fiber cancellation)
        return Effect.sync(() => {
          timeline.pause()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Overshoot animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

/**
 * Create an overshoot animation for both thumb and fill
 *
 * @param thumbElement - The thumb DOM element
 * @param fillElement - The fill bar DOM element
 * @param boundaryPosition - Boundary position in pixels
 * @param overshootTarget - Overshoot target in pixels
 * @param boundaryWidth - Boundary width as percentage string
 * @param overshootWidth - Overshoot width as percentage string
 * @param settleMs - Rubber-band settle duration
 * @returns Effect that completes when animation finishes
 */
export const createDualOvershootEffect = (
  thumbElement: HTMLElement,
  fillElement: HTMLElement,
  boundaryPosition: number,
  overshootTarget: number,
  boundaryWidth: string,
  overshootWidth: string,
  settleMs: number = TIMING.settle
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:dual-overshoot')(
    Effect.async<void, Error>((resume) => {
      try {
        const timeline = createTimeline({
          autoplay: true,
        })

        // Phase 1: Fast extension
        timeline.add(thumbElement, {
          translateX: overshootTarget,
          duration: TIMING.overshootExtend,
          easing: EASING.extend,
        }, 0)

        timeline.add(fillElement, {
          width: overshootWidth,
          duration: TIMING.overshootExtend,
          easing: EASING.extend,
        }, 0)

        // Phase 2: Rubber-band back
        timeline.add(thumbElement, {
          translateX: boundaryPosition,
          duration: settleMs,
          easing: EASING.settleBack,
        })

        timeline.add(fillElement, {
          width: boundaryWidth,
          duration: settleMs,
          easing: EASING.settleBack,
        }, '<') // Sync with previous

        timeline.then(() => resume(Effect.succeed(undefined)))

timeline.then(() => resume(Effect.succeed(undefined)))

        return Effect.sync(() => {
          timeline.pause()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Dual overshoot animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

/**
 * SettleEffect
 *
 * Tactical 50-80ms follow-through on release with kinetic thumb animation.
 * Combines position settle + scale "pop" for tactile feedback.
 */

import { Effect } from 'effect'
import { animate } from 'animejs'
import { TIMING, EASING } from '../types'

/**
 * Create a settle animation Effect program (position only)
 *
 * @param thumbElement - The thumb DOM element to animate
 * @param targetX - Target X position (in pixels or %)
 * @param settleMs - Duration in milliseconds
 * @param easing - Easing function name
 * @returns Effect that completes when animation finishes
 */
export const createSettleEffect = (
  thumbElement: HTMLElement,
  targetX: number,
  settleMs: number = TIMING.settle,
  easing: string = EASING.settleBack
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:settle')(
    Effect.async<void, Error>((resume) => {
      try {
        const anim = animate(thumbElement, {
          translateX: targetX,
          duration: settleMs,
          easing,
        })

        // Resume on completion
        anim.then(() => resume(Effect.succeed(undefined)))

        // Return cleanup (fiber cancellation)
        return Effect.sync(() => {
          anim.pause()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Settle animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

/**
 * Create a kinetic thumb settle effect with scale "pop"
 *
 * Combines:
 * - Scale pop animation (1.0 -> 1.15 -> 1.0, 150ms, easeOutBack)
 * - Position settle animation (65ms settle to target)
 *
 * Both animations run in parallel.
 *
 * @param thumbElement - The thumb DOM element to animate
 * @param targetX - Target X position (in pixels or %)
 * @param settleMs - Duration for position animation (default: 65ms)
 * @param popMs - Duration for scale pop (default: 150ms)
 * @returns Effect that completes when both animations finish
 */
export const createThumbSettleEffect = (
  thumbElement: HTMLElement,
  targetX: number,
  settleMs: number = TIMING.settle,
  popMs: number = 150
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:thumb-settle')(
    Effect.async<void, Error>((resume) => {
      try {
        // Scale pop animation (1 -> 1.15 -> 1)
        const scaleAnim = animate(thumbElement, {
          scale: [1, 1.15, 1],
          duration: popMs,
          easing: 'easeOutBack',
        })

        // Position settle animation
        const positionAnim = animate(thumbElement, {
          translateX: targetX,
          duration: settleMs,
          easing: EASING.settleBack,
        })

        // Wait for both animations to complete
        Promise.all([scaleAnim, positionAnim]).then(() => {
          resume(Effect.succeed(undefined))
        })

        // Return cleanup (fiber cancellation)
        return Effect.sync(() => {
          scaleAnim.pause()
          positionAnim.pause()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Thumb settle animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

/**
 * Create a settle animation for the fill bar
 *
 * @param fillElement - The fill bar DOM element
 * @param targetWidth - Target width as percentage string (e.g., "75%")
 * @param settleMs - Duration in milliseconds
 * @param easing - Easing function name
 * @returns Effect that completes when animation finishes
 */
export const createFillSettleEffect = (
  fillElement: HTMLElement,
  targetWidth: string,
  settleMs: number = TIMING.settle,
  easing: string = EASING.settleBack
): Effect.Effect<void, Error> =>
  Effect.withSpan('slider:fill-settle')(
    Effect.async<void, Error>((resume) => {
      try {
        const anim = animate(fillElement, {
          width: targetWidth,
          duration: settleMs,
          easing,
        })

        anim.then(() => resume(Effect.succeed(undefined)))

        return Effect.sync(() => {
          anim.pause()
        })
      } catch (error) {
        resume(Effect.fail(new Error(`Fill settle animation failed: ${error}`)))
        return Effect.void
      }
    })
  )

