/** Union of all channel commands */
export const ChannelCommand = Schema.Union(
  OpenChannel,
  CloseChannel,
  ConnectInlet,
  DisconnectInlet,
  SubscribeOutlet,
  UnsubscribeOutlet,
  ResetCircuitBreaker
