/** Union of all channel events */
export const ChannelEvent = Schema.Union(
  ChannelOpened,
  ChannelClosed,
  ChannelFaulted,
  InletConnected,
  InletDisconnected,
  OutletSubscribed,
  OutletUnsubscribed,
  CircuitBreakerTripped,
  CircuitBreakerReset,
  TimeoutOccurred,
  BackpressureEngaged
)
export type ChannelEvent = typeof ChannelEvent.Type

// ============================================================================
// BIDIRECTIONAL — Request/Response patterns (NATS-style)
// ============================================================================

/**
 * Request envelope with correlation.
 * Use ChannelRequest.make(payloadSchema) to create typed variants.
 */
export const ChannelRequest = <A, I, R>(payloadSchema: Schema.Schema<A, I, R>) =>
  Schema.TaggedStruct("ChannelRequest", {
    correlationId: CorrelationId,
    channelId: ChannelId,
    payload: payloadSchema,
    replyTo: Schema.optional(OutletId),
    timestamp: Schema.Number,
    ttl: Schema.optional(Schema.Number), // Time-to-live in ms
  })

/**
 * Response envelope with correlation.
 * Use ChannelResponse.make(payloadSchema) to create typed variants.
 */
export const ChannelResponse = <A, I, R>(payloadSchema: Schema.Schema<A, I, R>) =>
  Schema.TaggedStruct("ChannelResponse", {
    correlationId: CorrelationId,
    channelId: ChannelId,
    payload: payloadSchema,
    /** Whether this is the final response (for streaming responses) */
    final: Schema.Boolean,
    timestamp: Schema.Number,
  })

/** Acknowledgment for reliable delivery */
export class ChannelAck extends Schema.TaggedClass<ChannelAck>()("ChannelAck", {
  correlationId: CorrelationId,
  channelId: ChannelId,
  timestamp: Schema.Number,
}) {}

/** Negative acknowledgment */
export class ChannelNack extends Schema.TaggedClass<ChannelNack>()("ChannelNack", {
  correlationId: CorrelationId,
  channelId: ChannelId,
  reason: Schema.String,
  timestamp: Schema.Number,
}) {}

// ============================================================================
// CHANNEL STATE — Complete channel representation
// ============================================================================

export class ChannelTopology extends Schema.TaggedClass<ChannelTopology>()("ChannelTopology", {
  inlets: Schema.Array(Inlet),
  outlets: Schema.Array(Outlet),
  junctions: Schema.Array(Junction),
  wires: Schema.Array(Wire),
}) {}

export class ChannelMetrics extends Schema.TaggedClass<ChannelMetrics>()("ChannelMetrics", {
  messagesIn: Schema.Number,
  messagesOut: Schema.Number,
  bytesIn: Schema.Number,
  bytesOut: Schema.Number,
  errors: Schema.Number,
  latencyMs: Schema.Number, // Average latency
  uptime: Schema.Number, // Milliseconds since open
}) {}

/** Complete channel state */
export class ChannelState extends Schema.TaggedClass<ChannelState>()("ChannelState", {
  id: ChannelId,
  name: Schema.String,
  status: ChannelStatus,
  topology: ChannelTopology,
  protocol: ChannelProtocol,
  metrics: ChannelMetrics,
  createdAt: Schema.Number,
  openedAt: Schema.optional(Schema.Number),
  closedAt: Schema.optional(Schema.Number),
}) {}

// ============================================================================
// CHANNEL CONFIG — Builder input
// ============================================================================

export class ChannelConfig extends Schema.TaggedClass<ChannelConfig>()("ChannelConfig", {
  id: Schema.String, // Will be branded on creation
  name: Schema.String,
  description: Schema.optional(Schema.String),
  protocol: Schema.optional(ChannelProtocol),
}) {}

/** Junction builder configuration */
export interface JunctionBuilderConfig {
  readonly name?: string
  readonly kind: JunctionKind
  readonly config?: unknown
}

/** Wire endpoints can be inlet, junction, or outlet IDs */
export type WireEndpoint = string

// ============================================================================
// INTERNAL STATE
// ============================================================================

interface BuilderState {
  readonly id: string
  readonly name: string
  readonly description?: string
  readonly inlets: Map<string, Inlet>
  readonly outlets: Map<string, Outlet>
  readonly junctions: Map<string, Junction>
  readonly wires: Wire[]
  readonly timeout?: TimeoutConfig
  readonly circuitBreaker?: CircuitBreakerConfig
  readonly backpressure?: BackpressureConfig
  readonly retry?: RetryConfig
}

// ============================================================================
// CHANNEL BUILDER
// ============================================================================

/**
 * ChannelBuilder — Immutable builder for Channel topologies.
 *
 * Each method returns a new builder instance, allowing for
 * method chaining without mutation.
 */
export class ChannelBuilder {
  private readonly state: BuilderState

  private constructor(state: BuilderState) {
    this.state = state
  }

  // ══════════════════════════════════════════════════════════════════════════
  // FACTORY
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Create a new ChannelBuilder with the given ID.
   */
  static create(id: string): ChannelBuilder {
    return new ChannelBuilder({
      id,
      name: id,
      inlets: new Map(),
      outlets: new Map(),
      junctions: new Map(),
      wires: [],
    })
  }

// ══════════════════════════════════════════════════════════════════════════
  // METADATA
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Set the channel name.
   */
  name(name: string): ChannelBuilder {
    return new ChannelBuilder({ ...this.state, name })
  }

  /**
   * Set the channel description.
   */
  description(description: string): ChannelBuilder {
    return new ChannelBuilder({ ...this.state, description })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // TOPOLOGY — INLETS
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Add an inlet to the channel.
   *
   * @param localId - Local identifier for this inlet (used in wiring)
   * @param config - Inlet configuration
   */
  inlet(localId: string, config?: InletBuilderConfig): ChannelBuilder {
    const channelId = this.state.id as ChannelId
    const inletId = `${this.state.id}:inlet:${localId}` as InletId

    const inlet = new Inlet({
      id: inletId,
      name: config?.name ?? localId,
      channelId,
      schema: config?.schema,
      connected: false,
      sourceId: undefined,
    })

    const inlets = new Map(this.state.inlets)
    inlets.set(localId, inlet)

    return new ChannelBuilder({ ...this.state, inlets })
  }

const inlets = new Map(this.state.inlets)
    inlets.set(localId, inlet)

    return new ChannelBuilder({ ...this.state, inlets })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // TOPOLOGY — OUTLETS
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Add an outlet to the channel.
   *
   * @param localId - Local identifier for this outlet (used in wiring)
   * @param config - Outlet configuration
   */
  outlet(localId: string, config?: OutletBuilderConfig): ChannelBuilder {
    const channelId = this.state.id as ChannelId
    const outletId = `${this.state.id}:outlet:${localId}` as OutletId

    const outlet = new Outlet({
      id: outletId,
      name: config?.name ?? localId,
      channelId,
      broadcast: config?.broadcast ?? false,
      maxLag: config?.maxLag ?? 16,
      subscriberCount: 0,
    })

    const outlets = new Map(this.state.outlets)
    outlets.set(localId, outlet)

    return new ChannelBuilder({ ...this.state, outlets })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // TOPOLOGY — JUNCTIONS
  // ══════════════════════════════════════════════════════════════════════════

/**
   * Add a junction to the channel.
   *
   * @param localId - Local identifier for this junction (used in wiring)
   * @param config - Junction configuration (must include kind)
   */
  junction(localId: string, config: JunctionBuilderConfig): ChannelBuilder {
    const channelId = this.state.id as ChannelId
    const junctionId = `${this.state.id}:junction:${localId}` as JunctionId

    const junction = new Junction({
      id: junctionId,
      name: config.name ?? localId,
      channelId,
      kind: config.kind,
      config: config.config,
    })

    const junctions = new Map(this.state.junctions)
    junctions.set(localId, junction)

    return new ChannelBuilder({ ...this.state, junctions })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // TOPOLOGY — WIRES
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Wire two components together.
   *
   * @param from - Source local ID (inlet or junction)
   * @param to - Target local ID (junction or outlet)
   */
  wire(from: WireEndpoint, to: WireEndpoint): ChannelBuilder {
    const channelId = this.state.id as ChannelId
    const wireId = `${this.state.id}:wire:${nanoid(8)}` as WireId

    // Resolve the actual IDs
    const fromId = this.resolveEndpoint(from, "from")
    const toId = this.resolveEndpoint(to, "to")

    const wire = new Wire({
      id: wireId,
      channelId,
      from: fromId,
      to: toId,
      active: true,
    })

const wire = new Wire({
      id: wireId,
      channelId,
      from: fromId,
      to: toId,
      active: true,
    })

    return new ChannelBuilder({
      ...this.state,
      wires: [...this.state.wires, wire],
    })
  }

  private resolveEndpoint(
    localId: string,
    direction: "from" | "to"
  ): InletId | JunctionId | OutletId {
    // Check inlets (only valid for "from")
    if (direction === "from" && this.state.inlets.has(localId)) {
      return this.state.inlets.get(localId)!.id
    }

    // Check junctions (valid for both)
    if (this.state.junctions.has(localId)) {
      return this.state.junctions.get(localId)!.id
    }

    // Check outlets (only valid for "to")
    if (direction === "to" && this.state.outlets.has(localId)) {
      return this.state.outlets.get(localId)!.id
    }

    // Return as-is (assume it's a pre-built ID)
    return localId as InletId | JunctionId | OutletId
  }

  // ══════════════════════════════════════════════════════════════════════════
  // PROTOCOL — TIMEOUT
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Configure timeout behavior.
   *
   * @param duration - Timeout duration (e.g., "5 seconds")
   * @param behavior - What to do on timeout: "fail", "warn", or "skip"
   */
  timeout(duration: string, behavior: TimeoutBehavior = "fail"): ChannelBuilder {
    const timeout = new TimeoutConfig({
      duration,
      behavior,
    })

return new ChannelBuilder({ ...this.state, timeout })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // PROTOCOL — CIRCUIT BREAKER
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Configure circuit breaker.
   *
   * @param threshold - Number of failures before opening
   * @param resetAfter - Duration to wait before half-open (e.g., "30 seconds")
   */
  circuitBreaker(threshold: number, resetAfter: string): ChannelBuilder {
    const circuitBreaker = new CircuitBreakerConfig({
      threshold,
      resetAfter,
      state: "closed" as CircuitState,
      failureCount: 0,
    })

    return new ChannelBuilder({ ...this.state, circuitBreaker })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // PROTOCOL — BACKPRESSURE
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Configure backpressure handling.
   *
   * @param strategy - "block", "drop-oldest", "drop-newest", or "error"
   * @param capacity - Buffer capacity before strategy kicks in
   */
  backpressure(strategy: BackpressureStrategy, capacity: number): ChannelBuilder {
    const backpressure = new BackpressureConfig({
      strategy,
      capacity,
    })

    return new ChannelBuilder({ ...this.state, backpressure })
  }

return new ChannelBuilder({ ...this.state, backpressure })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // PROTOCOL — RETRY
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Configure retry behavior.
   *
   * @param times - Number of retry attempts
   * @param backoff - Backoff strategy: "fixed", "exponential", or "fibonacci"
   * @param initialDelay - Initial delay between retries (e.g., "100 millis")
   * @param maxDelay - Maximum delay (optional)
   */
  retry(
    times: number,
    backoff: "fixed" | "exponential" | "fibonacci" = "exponential",
    initialDelay: string = "100 millis",
    maxDelay?: string
  ): ChannelBuilder {
    const retry = new RetryConfig({
      times,
      backoff,
      initialDelay,
      maxDelay,
    })

    return new ChannelBuilder({ ...this.state, retry })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // BUILD
  // ══════════════════════════════════════════════════════════════════════════

/**
   * Build the ChannelState from the accumulated configuration.
   *
   * Returns an Effect that:
   * 1. Validates the topology (all wires connect valid endpoints)
   * 2. Creates the protocol configuration
   * 3. Initializes metrics
   * 4. Returns the complete ChannelState
   */
  build(): Effect.Effect<ChannelState, ChannelBuilderError> {
    const self = this
    return Effect.gen(function* () {
      // Validate topology
      yield* self.validateTopology()

      // Build protocol
      const protocol = new ChannelProtocol({
        timeout: self.state.timeout,
        circuitBreaker: self.state.circuitBreaker,
        backpressure: self.state.backpressure,
        retry: self.state.retry,
      })

      // Build topology
      const topology = new ChannelTopology({
        inlets: Array.from(self.state.inlets.values()),
        outlets: Array.from(self.state.outlets.values()),
        junctions: Array.from(self.state.junctions.values()),
        wires: self.state.wires,
      })

      // Initialize metrics
      const metrics = new ChannelMetrics({
        messagesIn: 0,
        messagesOut: 0,
        bytesIn: 0,
        bytesOut: 0,
        errors: 0,
        latencyMs: 0,
        uptime: 0,
      })

      // Build state
      const channelState = new ChannelState({
        id: self.state.id as ChannelId,
        name: self.state.name,
        status: "idle",
        topology,
        protocol,
        metrics,
        createdAt: Date.now(),
        openedAt: undefined,
        closedAt: undefined,
      })

      return channelState
    })
  }

  /**
   * Build the ChannelConfig (lighter weight, for registration).
   */
  buildConfig(): ChannelConfig {
    const protocol = new ChannelProtocol({
      timeout: this.state.timeout,
      circuitBreaker: this.state.circuitBreaker,
      backpressure: this.state.backpressure,
      retry: this.state.retry,
    })

return new ChannelConfig({
      id: this.state.id,
      name: this.state.name,
      description: this.state.description,
      protocol,
    })
  }

  // ══════════════════════════════════════════════════════════════════════════
  // VALIDATION
  // ══════════════════════════════════════════════════════════════════════════

  private validateTopology(): Effect.Effect<void, ChannelBuilderError> {
    const self = this
    return Effect.gen(function* () {
      // Validate all wires connect to existing components
      for (const wire of self.state.wires) {
        const fromExists =
          self.isValidFromEndpoint(wire.from as string) ||
          self.isJunction(wire.from as string)
        const toExists =
          self.isValidToEndpoint(wire.to as string) ||
          self.isJunction(wire.to as string)

        if (!fromExists) {
          yield* Effect.fail(
            new ChannelBuilderError({
              message: `Wire source "${wire.from}" does not exist`,
              code: "INVALID_WIRE_SOURCE",
            })
          )
        }

        if (!toExists) {
          yield* Effect.fail(
            new ChannelBuilderError({
              message: `Wire target "${wire.to}" does not exist`,
              code: "INVALID_WIRE_TARGET",
            })
          )
        }
      }

      // Validate at least one inlet
      if (self.state.inlets.size === 0) {
        yield* Effect.fail(
          new ChannelBuilderError({
            message: "Channel must have at least one inlet",
            code: "NO_INLETS",
          })
        )
      }

// Validate at least one outlet
      if (self.state.outlets.size === 0) {
        yield* Effect.fail(
          new ChannelBuilderError({
            message: "Channel must have at least one outlet",
            code: "NO_OUTLETS",
          })
        )
      }
    })
  }

  private isValidFromEndpoint(id: string): boolean {
    // From can be inlet or junction
    for (const inlet of this.state.inlets.values()) {
      if (inlet.id === id) return true
    }
    return false
  }

  private isValidToEndpoint(id: string): boolean {
    // To can be outlet or junction
    for (const outlet of this.state.outlets.values()) {
      if (outlet.id === id) return true
    }
    return false
  }

  private isJunction(id: string): boolean {
    for (const junction of this.state.junctions.values()) {
      if (junction.id === id) return true
    }
    return false
  }

  // ══════════════════════════════════════════════════════════════════════════
  // INSPECTION
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Get a summary of the current builder state.
   */
  inspect(): BuilderInspection {
    return {
      id: this.state.id,
      name: this.state.name,
      inletCount: this.state.inlets.size,
      outletCount: this.state.outlets.size,
      junctionCount: this.state.junctions.size,
      wireCount: this.state.wires.length,
      hasTimeout: !!this.state.timeout,
      hasCircuitBreaker: !!this.state.circuitBreaker,
      hasBackpressure: !!this.state.backpressure,
      hasRetry: !!this.state.retry,
    }
  }
}

// ============================================================================
// ERROR TYPE
// ============================================================================

export class ChannelBuilderError extends Schema.TaggedError<ChannelBuilderError>()(
  "ChannelBuilderError",
  {
    message: Schema.String,
    code: Schema.Literal(
      "INVALID_WIRE_SOURCE",
      "INVALID_WIRE_TARGET",
      "NO_INLETS",
      "NO_OUTLETS",
      "DUPLICATE_ID",
      "INVALID_CONFIG"
    ),
  }
) {}

// ============================================================================
// INSPECTION TYPE
// ============================================================================

export interface BuilderInspection {
  readonly id: string
  readonly name: string
  readonly inletCount: number
  readonly outletCount: number
  readonly junctionCount: number
  readonly wireCount: number
  readonly hasTimeout: boolean
  readonly hasCircuitBreaker: boolean
  readonly hasBackpressure: boolean
  readonly hasRetry: boolean
}

const makeInstance = (state: ChannelState): ChannelInstance => ({
  state,
  fibers: HashMap.empty(),
  subscriptions: HashMap.empty(),
})

// ============================================================================
// CHANNEL SERVICE INTERFACE
// ============================================================================

export interface ChannelServiceShape {
  // ── Registration ───────────────────────────────────────────────────────────

  /**
   * Register a channel from builder.
   */
  readonly register: (
    builder: ChannelBuilder
  ) => Effect.Effect<ChannelId, ChannelBuilderError>

  /**
   * Register a pre-built ChannelState.
   */
  readonly registerState: (state: ChannelState) => Effect.Effect<ChannelId>

  /**
   * Unregister a channel.
   */
  readonly unregister: (id: ChannelId) => Effect.Effect<void>

  // ── Retrieval ──────────────────────────────────────────────────────────────

  /**
   * Get a channel by ID.
   */
  readonly get: (id: ChannelId) => Effect.Effect<Option.Option<ChannelInstance>>

  /**
   * Get channel state by ID.
   */
  readonly getState: (id: ChannelId) => Effect.Effect<Option.Option<ChannelState>>

  /**
   * List all registered channel IDs.
   */
  readonly listIds: () => Effect.Effect<ReadonlyArray<ChannelId>>

  /**
   * Get status of all channels.
   */
  readonly getStatuses: () => Effect.Effect<HashMap.HashMap<ChannelId, ChannelStatus>>

  // ── Lifecycle ──────────────────────────────────────────────────────────────

  /**
   * Open a channel (transition to "open" state).
   */
  readonly open: (id: ChannelId) => Effect.Effect<void, ChannelServiceError>

  /**
   * Close a channel (transition to "closed" state).
   */
  readonly close: (id: ChannelId, reason?: string) => Effect.Effect<void>

  /**
   * Close all channels.
   */
  readonly closeAll: () => Effect.Effect<void>

/**
   * Event channel for observation.
   */
  readonly events: PubSub.PubSub<ChannelEvent>

  /**
   * Subscribe to events.
   */
  readonly subscribeEvents: () => Effect.Effect<Queue.Dequeue<ChannelEvent>, never, Scope.Scope>

  // ── Metrics ────────────────────────────────────────────────────────────────

  /**
   * Get metrics for a channel.
   */
  readonly getMetrics: (id: ChannelId) => Effect.Effect<Option.Option<ChannelMetrics>>

  /**
   * Update metrics (internal, but exposed for custom integrations).
   */
  readonly updateMetrics: (
    id: ChannelId,
    update: (m: ChannelMetrics) => ChannelMetrics
  ) => Effect.Effect<void>
}

// ============================================================================
// SERVICE TAG
// ============================================================================

export class ChannelService extends Context.Tag("tmnl/streams/ChannelService")<
  ChannelService,
  ChannelServiceShape
>() {}

// ============================================================================
// ERROR TYPE
// ============================================================================

import { Schema } from "effect"

export class ChannelServiceError extends Schema.TaggedError<ChannelServiceError>()(
  "ChannelServiceError",
  {
    message: Schema.String,
    code: Schema.Literal(
      "CHANNEL_NOT_FOUND",
      "INLET_NOT_FOUND",
      "OUTLET_NOT_FOUND",
      "ALREADY_OPEN",
      "NOT_OPEN",
      "ALREADY_CONNECTED",
      "BUILD_FAILED"
    ),
    channelId: Schema.optional(Schema.String),
  }
) {}

// ============================================================================
// IMPLEMENTATION
// ============================================================================

const makeChannelService = Effect.gen(function* () {
  // Internal state
  const registry = yield* Ref.make<HashMap.HashMap<ChannelId, ChannelInstance>>(
    HashMap.empty()
  )
  const commandPubSub = yield* PubSub.unbounded<ChannelCommand>()
  const eventPubSub = yield* PubSub.unbounded<ChannelEvent>()

  // Outlet PubSubs for broadcasting
  const outletPubSubs = yield* Ref.make<
    HashMap.HashMap<string, PubSub.PubSub<unknown>>
  >(HashMap.empty())

// Outlet PubSubs for broadcasting
  const outletPubSubs = yield* Ref.make<
    HashMap.HashMap<string, PubSub.PubSub<unknown>>
  >(HashMap.empty())

  // ── Helpers ────────────────────────────────────────────────────────────────

  const emit = (event: ChannelEvent) => PubSub.publish(eventPubSub, event)

  const getEntry = (id: ChannelId) =>
    pipe(
      Ref.get(registry),
      Effect.map((map) => HashMap.get(map, id))
    )

  const updateEntry = (
    id: ChannelId,
    fn: (instance: ChannelInstance) => ChannelInstance
  ) =>
    Ref.update(registry, (map) => {
      const entry = HashMap.get(map, id)
      if (Option.isSome(entry)) {
        return HashMap.set(map, id, fn(entry.value))
      }
      return map
    })

  const updateState = (id: ChannelId, fn: (state: ChannelState) => ChannelState) =>
    updateEntry(id, (instance) => ({
      ...instance,
      state: fn(instance.state),
    }))

  const getOrCreateOutletPubSub = (outletKey: string) =>
    Effect.gen(function* () {
      const pubsubs = yield* Ref.get(outletPubSubs)
      const existing = HashMap.get(pubsubs, outletKey)
      if (Option.isSome(existing)) {
        return existing.value
      }
      const newPubSub = yield* PubSub.unbounded<unknown>()
      yield* Ref.update(outletPubSubs, (map) => HashMap.set(map, outletKey, newPubSub))
      return newPubSub
    })

  // ── Command Processor ──────────────────────────────────────────────────────

// ── Command Processor ──────────────────────────────────────────────────────

  const commandProcessor = pipe(
    Stream.fromPubSub(commandPubSub),
    Stream.tap((cmd) =>
      Console.log(`[ChannelService] Command received: ${cmd._tag}`)
    ),
    Stream.mapEffect((cmd) => {
      switch (cmd._tag) {
        case "OpenChannel":
          return service.open(cmd.id)
        case "CloseChannel":
          return service.close(cmd.id, cmd.reason)
        case "ConnectInlet":
          // For command-based connection, we'd need the stream/feed reference
          // This is handled via direct method calls
          return Console.log(
            `[ChannelService] ConnectInlet via command requires direct method call`
          )
        case "DisconnectInlet":
          return service.disconnectInlet(cmd.channelId, cmd.inletId)
        case "SubscribeOutlet":
          return Console.log(
            `[ChannelService] SubscribeOutlet via command requires direct method call`
          )
        case "UnsubscribeOutlet":
          return Console.log(
            `[ChannelService] UnsubscribeOutlet via command not yet implemented`
          )
        case "ResetCircuitBreaker":
          return Console.log(
            `[ChannelService] ResetCircuitBreaker not yet implemented`
          )
      }
    }),
    Stream.runDrain,
    Effect.fork
  )

  yield* commandProcessor
  yield* Console.log("[ChannelService] Command processor started")

  // ── Service Implementation ─────────────────────────────────────────────────

  const service: ChannelServiceShape = {
    // Registration
    register: (builder: ChannelBuilder) =>
      Effect.gen(function* () {
        const state = yield* builder.build()
        const instance = makeInstance(state)

        yield* Ref.update(registry, (map) => HashMap.set(map, state.id, instance))
        yield* Console.log(`[ChannelService] Registered channel: ${state.id}`)

        return state.id
      }),

yield* Ref.update(registry, (map) => HashMap.set(map, state.id, instance))
        yield* Console.log(`[ChannelService] Registered channel: ${state.id}`)

        return state.id
      }),

    registerState: (state: ChannelState) =>
      Effect.gen(function* () {
        const instance = makeInstance(state)
        yield* Ref.update(registry, (map) => HashMap.set(map, state.id, instance))
        yield* Console.log(`[ChannelService] Registered channel state: ${state.id}`)
        return state.id
      }),

    unregister: (id: ChannelId) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(id)
        if (Option.isSome(entry)) {
          // Close if open
          if (entry.value.state.status === "open") {
            yield* service.close(id)
          }
          yield* Ref.update(registry, (map) => HashMap.remove(map, id))
          yield* Console.log(`[ChannelService] Unregistered channel: ${id}`)
        }
      }),

    // Retrieval
    get: (id: ChannelId) => getEntry(id),

    getState: (id: ChannelId) =>
      pipe(
        getEntry(id),
        Effect.map((opt) => Option.map(opt, (e) => e.state))
      ),

    listIds: () =>
      pipe(
        Ref.get(registry),
        Effect.map((map) => Array.from(HashMap.keys(map)))
      ),

    getStatuses: () =>
      pipe(
        Ref.get(registry),
        Effect.map((map) =>
          pipe(
            HashMap.map(map, (instance) => instance.state.status),
            (m) => m as HashMap.HashMap<ChannelId, ChannelStatus>
          )
        )
      ),

// Lifecycle
    open: (id: ChannelId) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(id)
        if (Option.isNone(entry)) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Channel not found: ${id}`,
              code: "CHANNEL_NOT_FOUND",
              channelId: id,
            })
          )
          return
        }

        const instance = entry.value
        if (instance.state.status === "open") {
          yield* Console.log(`[ChannelService] Channel already open: ${id}`)
          return
        }

        yield* updateState(id, (state) =>
          new ChannelState({
            id: state.id,
            name: state.name,
            status: "open",
            topology: new ChannelTopology({ ...state.topology }),
            protocol: new ChannelProtocol({ ...state.protocol }),
            metrics: new ChannelMetrics({ ...state.metrics }),
            createdAt: state.createdAt,
            openedAt: Date.now(),
            closedAt: state.closedAt,
          })
        )

        yield* emit(
          new ChannelOpened({
            channelId: id,
            timestamp: Date.now(),
          })
        )
        yield* Console.log(`[ChannelService] Opened channel: ${id}`)
      }),

    close: (id: ChannelId, reason?: string) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(id)
        if (Option.isNone(entry)) return

        const instance = entry.value

        // Interrupt all fibers
        const fibers = Array.from(HashMap.values(instance.fibers))
        yield* Effect.all(
          fibers.map((f) => Fiber.interrupt(f)),
          { concurrency: "unbounded" }
        )

// Interrupt all fibers
        const fibers = Array.from(HashMap.values(instance.fibers))
        yield* Effect.all(
          fibers.map((f) => Fiber.interrupt(f)),
          { concurrency: "unbounded" }
        )

        yield* updateState(id, (state) =>
          new ChannelState({
            id: state.id,
            name: state.name,
            status: "closed",
            topology: new ChannelTopology({ ...state.topology }),
            protocol: new ChannelProtocol({ ...state.protocol }),
            metrics: new ChannelMetrics({ ...state.metrics }),
            createdAt: state.createdAt,
            openedAt: state.openedAt,
            closedAt: Date.now(),
          })
        )

        // Clear fibers
        yield* updateEntry(id, (inst) => ({
          ...inst,
          fibers: HashMap.empty(),
        }))

        yield* emit(
          new ChannelClosed({
            channelId: id,
            reason,
            timestamp: Date.now(),
          })
        )
        yield* Console.log(`[ChannelService] Closed channel: ${id}`)
      }),

    closeAll: () =>
      Effect.gen(function* () {
        const ids = yield* service.listIds()
        yield* Console.log(`[ChannelService] Closing all channels (${ids.length})...`)
        yield* Effect.all(
          ids.map((id) => service.close(id)),
          { concurrency: "unbounded" }
        )
      }),

    // Inlet Operations
    connectFeed: <A, E, R>(
      channelId: ChannelId,
      inletId: InletId,
      feed: Feed<A, E, R>
    ) =>
      service.connectStream(channelId, inletId, feed.stream, feed.id) as Effect.Effect<
        void,
        ChannelServiceError
      >,

connectStream: <A, E, R>(
      channelId: ChannelId,
      inletId: InletId,
      stream: Stream.Stream<A, E, R>,
      sourceId?: string
    ) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(channelId)
        if (Option.isNone(entry)) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Channel not found: ${channelId}`,
              code: "CHANNEL_NOT_FOUND",
              channelId,
            })
          )
          return
        }

        const instance = entry.value
        const inlet = instance.state.topology.inlets.find((i) => i.id === inletId)
        if (!inlet) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Inlet not found: ${inletId}`,
              code: "INLET_NOT_FOUND",
              channelId,
            })
          )
          return
        }

        if (inlet.connected) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Inlet already connected: ${inletId}`,
              code: "ALREADY_CONNECTED",
              channelId,
            })
          )
          return
        }

        const finalSourceId = sourceId ?? `stream:${nanoid(8)}`

        // Find connected outlets and broadcast to them
        const wires = instance.state.topology.wires.filter(
          (w) => w.from === inletId && w.active
        )

        // For each wire, get the outlet and push to its pubsub
        const fiber = yield* pipe(
          stream,
          Stream.tap((item) =>
            Effect.gen(function* () {
              // Update metrics
              yield* service.updateMetrics(channelId, (m) =>
                new ChannelMetrics({
                  ...m,
                  messagesIn: m.messagesIn + 1,
                })
              )

// Route to connected outlets
              for (const wire of wires) {
                const outletKey = `${channelId}:${wire.to}`
                const pubsub = yield* getOrCreateOutletPubSub(outletKey)
                yield* PubSub.publish(pubsub, item)
              }
            })
          ),
          Stream.runDrain,
          Effect.fork
        )

        // Update inlet state
        yield* updateState(channelId, (state) => {
          const updatedInlets = state.topology.inlets.map((i) =>
            i.id === inletId
              ? new Inlet({ ...i, connected: true, sourceId: finalSourceId })
              : i
          )
          return new ChannelState({
            ...state,
            topology: new ChannelTopology({
              ...state.topology,
              inlets: updatedInlets,
            }),
          })
        })

        // Store fiber reference
        yield* updateEntry(channelId, (inst) => ({
          ...inst,
          fibers: HashMap.set(inst.fibers, inletId, fiber as Fiber.RuntimeFiber<void, unknown>),
        }))

        yield* emit(
          new InletConnected({
            channelId,
            inletId,
            sourceId: finalSourceId,
            timestamp: Date.now(),
          })
        )

        yield* Console.log(
          `[ChannelService] Connected stream to inlet ${inletId} on channel ${channelId}`
        )
      }) as Effect.Effect<void, ChannelServiceError, R>,

    disconnectInlet: (channelId: ChannelId, inletId: InletId) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(channelId)
        if (Option.isNone(entry)) return

        const instance = entry.value
        const fiber = HashMap.get(instance.fibers, inletId)
        if (Option.isSome(fiber)) {
          yield* Fiber.interrupt(fiber.value)
        }

const instance = entry.value
        const fiber = HashMap.get(instance.fibers, inletId)
        if (Option.isSome(fiber)) {
          yield* Fiber.interrupt(fiber.value)
        }

        // Update inlet state
        yield* updateState(channelId, (state) => {
          const updatedInlets = state.topology.inlets.map((i) =>
            i.id === inletId
              ? new Inlet({ ...i, connected: false, sourceId: undefined })
              : i
          )
          return new ChannelState({
            ...state,
            topology: new ChannelTopology({
              ...state.topology,
              inlets: updatedInlets,
            }),
          })
        })

        // Remove fiber reference
        yield* updateEntry(channelId, (inst) => ({
          ...inst,
          fibers: HashMap.remove(inst.fibers, inletId),
        }))

        yield* emit(
          new InletDisconnected({
            channelId,
            inletId,
            timestamp: Date.now(),
          })
        )

        yield* Console.log(
          `[ChannelService] Disconnected inlet ${inletId} on channel ${channelId}`
        )
      }),

    // Outlet Operations
    subscribeOutlet: (
      channelId: ChannelId,
      outletId: OutletId,
      subscriberId?: string
    ) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(channelId)
        if (Option.isNone(entry)) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Channel not found: ${channelId}`,
              code: "CHANNEL_NOT_FOUND",
              channelId,
            })
          )
          // This won't execute, but TypeScript needs it
          return yield* Queue.unbounded<unknown>()
        }

const instance = entry.value
        const outlet = instance.state.topology.outlets.find((o) => o.id === outletId)
        if (!outlet) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Outlet not found: ${outletId}`,
              code: "OUTLET_NOT_FOUND",
              channelId,
            })
          )
          return yield* Queue.unbounded<unknown>()
        }

        const finalSubscriberId = subscriberId ?? `sub:${nanoid(8)}`
        const outletKey = `${channelId}:${outletId}`
        const pubsub = yield* getOrCreateOutletPubSub(outletKey)
        const queue = yield* PubSub.subscribe(pubsub)

        // Update outlet subscriber count
        yield* updateState(channelId, (state) => {
          const updatedOutlets = state.topology.outlets.map((o) =>
            o.id === outletId
              ? new Outlet({ ...o, subscriberCount: o.subscriberCount + 1 })
              : o
          )
          return new ChannelState({
            ...state,
            topology: new ChannelTopology({
              ...state.topology,
              outlets: updatedOutlets,
            }),
          })
        })

        yield* emit(
          new OutletSubscribed({
            channelId,
            outletId,
            subscriberId: finalSubscriberId,
            timestamp: Date.now(),
          })
        )

        yield* Console.log(
          `[ChannelService] Subscribed to outlet ${outletId} on channel ${channelId}`
        )

        return queue
      }),

    getOutletStream: (channelId: ChannelId, outletId: OutletId) =>
      Effect.gen(function* () {
        const entry = yield* getEntry(channelId)
        if (Option.isNone(entry)) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Channel not found: ${channelId}`,
              code: "CHANNEL_NOT_FOUND",
              channelId,
            })
          )
          return Stream.empty as Stream.Stream<unknown, unknown, unknown>
        }

const outlet = entry.value.state.topology.outlets.find(
          (o) => o.id === outletId
        )
        if (!outlet) {
          yield* Effect.fail(
            new ChannelServiceError({
              message: `Outlet not found: ${outletId}`,
              code: "OUTLET_NOT_FOUND",
              channelId,
            })
          )
          return Stream.empty as Stream.Stream<unknown, unknown, unknown>
        }

        const outletKey = `${channelId}:${outletId}`
        const pubsub = yield* getOrCreateOutletPubSub(outletKey)

        return Stream.fromPubSub(pubsub)
      }),

    // Event Bus
    commands: commandPubSub,
    events: eventPubSub,
    subscribeEvents: () => PubSub.subscribe(eventPubSub),

    // Metrics
    getMetrics: (id: ChannelId) =>
      pipe(
        getEntry(id),
        Effect.map((opt) => Option.map(opt, (e) => e.state.metrics))
      ),

    updateMetrics: (
      id: ChannelId,
      update: (m: ChannelMetrics) => Partial<ChannelMetrics>
    ) =>
      updateState(id, (state) =>
        new ChannelState({
          id: state.id,
          name: state.name,
          status: state.status,
          topology: new ChannelTopology({ ...state.topology }),
          protocol: new ChannelProtocol({ ...state.protocol }),
          metrics: new ChannelMetrics({ ...state.metrics, ...update(state.metrics) }),
          createdAt: state.createdAt,
          openedAt: state.openedAt,
          closedAt: state.closedAt,
        })
      ),
  }

  return service
})

