/**
 * Create a simple feed from a producer effect.
 */
export const makeFeed = <A, E = never, R = never>(
  id: string,
  producer: Effect.Effect<A, E, R>,
  options?: Partial<Omit<FeedConfig<A, E, R>, "id" | "producer">>
): Feed<A, E, R> =>
  Feed.make({
    id,
    name: options?.name ?? id,
    producer,
    ...options,
  })

