/**
 * OPC-UA PubSub JSON Payload Generator
 *
 * Generates OPC Foundation Part 14 compliant JSON payloads.
 * Reference: https://reference.opcfoundation.org/Core/Part14/v104/docs/7.2.3
 *
 * Example output:
 * ```json
 * {
 *   "MessageId": "9279c0b3-da88-45a4-af74-451cebf82db0",
 *   "MessageType": "ua-data",
 *   "PublisherId": "Publisher-001",
 *   "Messages": [{
 *     "DataSetWriterId": 101,
 *     "SequenceNumber": 1,
 *     "Timestamp": "2024-01-15T10:30:00.000Z",
 *     "Payload": { ... }
 *   }]
 * }
 * ```
 *
 * @module
 */

import type { PayloadGenerator, PayloadTier } from '../types'
import { PAYLOAD_SIZE_TARGETS } from '../types'

// ============================================================================
// OPC-UA TYPES
// ============================================================================

/** OPC-UA DataSet field with variant value */
interface OpcUaField {
  /** Field name (NodeId-like) */
  Name: string
  /** Value with type information */
  Value: {
    Type: number  // OPC-UA Built-in Type ID
    Body: unknown // Actual value
  }
  /** Source timestamp */
  SourceTimestamp?: string
  /** Server timestamp */
  ServerTimestamp?: string
  /** Status code (0 = Good) */
  StatusCode?: number
}

/** OPC-UA DataSetMessage */
interface OpcUaDataSetMessage {
  /** Writer identifier */
  DataSetWriterId: number
  /** Sequence number for ordering */
  SequenceNumber: number
  /** Message timestamp */
  Timestamp: string
  /** Status (0 = Good) */
  Status?: number
  /** Field data */
  Payload: Record<string, OpcUaField>
}

/** OPC-UA NetworkMessage (JSON encoding) */
interface OpcUaNetworkMessage {
  /** Unique message identifier */
  MessageId: string
  /** Message type discriminator */
  MessageType: 'ua-data' | 'ua-metadata' | 'ua-event'
  /** Publisher identifier */
  PublisherId: string
  /** Optional writer group */
  WriterGroupId?: number
  /** DataSet messages */
  Messages: OpcUaDataSetMessage[]
}

// ============================================================================
// FIELD DEFINITIONS
// ============================================================================

/** OPC-UA Built-in Type IDs */
const OPC_UA_TYPES = {
  Boolean: 1,
  SByte: 2,
  Byte: 3,
  Int16: 4,
  UInt16: 5,
  Int32: 6,
  UInt32: 7,
  Int64: 8,
  UInt64: 9,
  Float: 10,
  Double: 11,
  String: 12,
  DateTime: 13,
  ByteString: 15,
} as const

/** Simulated PLC/SCADA field definitions */
const FIELD_DEFINITIONS = [
  { name: 'Temperature_PV', type: OPC_UA_TYPES.Double, range: [15, 85] as const, unit: '°C' },
  { name: 'Temperature_SP', type: OPC_UA_TYPES.Double, range: [20, 80] as const, unit: '°C' },
  { name: 'Pressure_PV', type: OPC_UA_TYPES.Double, range: [0, 10] as const, unit: 'bar' },
  { name: 'Pressure_SP', type: OPC_UA_TYPES.Double, range: [0, 10] as const, unit: 'bar' },
  { name: 'FlowRate_PV', type: OPC_UA_TYPES.Double, range: [0, 500] as const, unit: 'L/min' },
  { name: 'Level_PV', type: OPC_UA_TYPES.Double,

type: OPC_UA_TYPES.Double, range: [-10, 10] as const, unit: 'mm/s' },
  { name: 'Vibration_Y', type: OPC_UA_TYPES.Double, range: [-10, 10] as const, unit: 'mm/s' },
  { name: 'Vibration_Z', type: OPC_UA_TYPES.Double, range: [-10, 10] as const, unit: 'mm/s' },
] as const

/** Tier configuration */
const TIER_CONFIG = {
  small: { dataSetCount: 1, fieldsPerSet: 4 },   // ~500 bytes
  medium: { dataSetCount: 3, fieldsPerSet: 8 },  // ~3 kB
  large: { dataSetCount: 8, fieldsPerSet: 16 },  // ~20 kB
} as const

// ============================================================================
// GENERATOR IMPLEMENTATION
// ============================================================================

/**
 * Generate a random value for a field.
 */
const randomFieldValue = (
  type: number,
  range: readonly [number, number]
): unknown => {
  const [min, max] = range

  if (type === OPC_UA_TYPES.Boolean) {
    return Math.random() > 0.5
  }

  if (type === OPC_UA_TYPES.UInt32 || type === OPC_UA_TYPES.Int32) {
    return Math.floor(min + Math.random() * (max - min))
  }

  // Default: Double/Float
  return Math.round((min + Math.random() * (max - min)) * 100) / 100
}

/**
 * Generate payload for a single DataSet.
 */
const generateDataSetPayload = (
  fieldsCount: number,
  dataSetIndex: number
): Record<string, OpcUaField> => {
  const payload: Record<string, OpcUaField> = {}
  const timestamp = new Date().toISOString()

for (let i = 0; i < fieldsCount; i++) {
    const fieldDef = FIELD_DEFINITIONS[(dataSetIndex * 4 + i) % FIELD_DEFINITIONS.length]
    const fieldName = `${fieldDef.name}_${dataSetIndex}`

    payload[fieldName] = {
      Name: fieldName,
      Value: {
        Type: fieldDef.type,
        Body: randomFieldValue(fieldDef.type, fieldDef.range),
      },
      SourceTimestamp: timestamp,
      StatusCode: 0, // Good
    }
  }

  return payload
}

/**
 * OPC-UA PubSub JSON payload generator.
 *
 * Produces Part 14 compliant network messages with
 * realistic SCADA/PLC data.
 */
export const opcuaGenerator: PayloadGenerator = {
  id: 'opcua',
  name: 'OPC-UA PubSub',
  description: 'Industrial automation — SCADA, PLCs, manufacturing',

  generate(tier: PayloadTier, eventIndex: number): OpcUaNetworkMessage {
    const config = TIER_CONFIG[tier]
    const timestamp = new Date().toISOString()
    const publisherId = `Publisher-${(eventIndex % 100).toString().padStart(3, '0')}`

    const messages: OpcUaDataSetMessage[] = Array.from(
      { length: config.dataSetCount },
      (_, i) => ({
        DataSetWriterId: 100 + i,
        SequenceNumber: eventIndex,
        Timestamp: timestamp,
        Status: 0, // Good
        Payload: generateDataSetPayload(config.fieldsPerSet, i),
      })
    )

    return {
      MessageId: crypto.randomUUID(),
      MessageType: 'ua-data',
      PublisherId: publisherId,
      WriterGroupId: 1,
      Messages: messages,
    }
  },

  estimateSizeBytes(tier: PayloadTier): number {
    return PAYLOAD_SIZE_TARGETS[tier]
  },
}

export type { OpcUaNetworkMessage, OpcUaDataSetMessage, OpcUaField }

/**
 * Prometheus Metrics Payload Generator
 *
 * Generates Prometheus exposition format style JSON payloads.
 * For stress testing observability pipelines.
 *
 * Example output:
 * ```json
 * {
 *   "metrics": [
 *     {
 *       "name": "tmnl_http_requests_total",
 *       "type": "counter",
 *       "help": "Total HTTP requests",
 *       "labels": { "method": "GET", "status": "200" },
 *       "value": 1234,
 *       "timestamp": 1702000000000
 *     }
 *   ]
 * }
 * ```
 *
 * @module
 */

import type { PayloadGenerator, PayloadTier } from '../types'
import { PAYLOAD_SIZE_TARGETS } from '../types'

// ============================================================================
// PROMETHEUS TYPES
// ============================================================================

/** Prometheus metric types */
type MetricType = 'counter' | 'gauge' | 'histogram' | 'summary'

/** Single metric entry */
interface PrometheusMetric {
  /** Metric name (snake_case) */
  name: string
  /** Metric type */
  type: MetricType
  /** Help text */
  help: string
  /** Label key-value pairs */
  labels: Record<string, string>
  /** Metric value */
  value: number
  /** Unix timestamp in milliseconds */
  timestamp: number
  /** For histograms: bucket boundaries */
  buckets?: Array<{ le: number; count: number }>
  /** For summaries: quantiles */
  quantiles?: Array<{ quantile: number; value: number }>
}

/** Prometheus metrics payload */
interface PrometheusPayload {
  metrics: PrometheusMetric[]
}

// ============================================================================
// METRIC DEFINITIONS
// ============================================================================

/** Label pools for realistic cardinality */
const LABEL_POOLS = {
  method: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'],
  status: ['200', '201', '204', '301', '302', '400', '401', '403', '404', '500', '502', '503'],
  path: ['/api/v1/users', '/api/v1/orders', '/api/v1/products', '/health', '/metrics', '/graphql'],
  instance: ['app-001', 'app-002', 'app-003', 'app-004'],
  job: ['api-server', 'worker', 'scheduler', 'gateway'],
  cpu: ['0', '1', '2', '3', '4', '5', '6', '7'],
  device: ['sda', 'sdb', 'nvme0n1'],
  interface: ['eth0', 'eth1', 'lo'],
  container: ['api', 'worker', 'redis', 'postgres', 'nginx'],
  namespace: ['default', 'production', 'staging', 'monitoring'],
  pod: ['api-deployment-abc123', 'worker-deployment-def456', 'redis-0'],
} as const

/** Tier configuration */
const TIER_CONFIG = {
  small: { metricCount: 5, labelCardinality: 2 },   // ~500 bytes
  medium: { metricCount: 20, labelCardinality: 5 }, // ~3 kB
  large: { metricCount: 100, labelCardinality: 10 }, // ~20 kB
} as const

// ============================================================================
// GENERATOR IMPLEMENTATION
// ============================================================================

/**
 * Generate labels for a metric.
 */
const generateLabels = (
  cardinality: number,
  metricIndex: number,
  eventIndex: number
): Record<string, string> => {
  const labels: Record<string, string> = {}
  const labelKeys = Object.keys(LABEL_POOLS) as Array<keyof typeof LABEL_POOLS>

for (let i = 0; i < cardinality; i++) {
    const key = labelKeys[(metricIndex + i) % labelKeys.length]
    const pool = LABEL_POOLS[key]
    const value = pool[(eventIndex + i) % pool.length]
    labels[key] = value
  }

  return labels
}

/**
 * Generate histogram buckets.
 */
const generateBuckets = (): Array<{ le: number; count: number }> => {
  const boundaries = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10]
  let cumulative = 0

  return boundaries.map((le) => {
    cumulative += Math.floor(Math.random() * 100)
    return { le, count: cumulative }
  })
}

/**
 * Generate summary quantiles.
 */
const generateQuantiles = (): Array<{ quantile: number; value: number }> => {
  const quantiles = [0.5, 0.9, 0.95, 0.99]
  let prev = 0

  return quantiles.map((quantile) => {
    prev = prev + Math.random() * 0.1
    return { quantile, value: Math.round(prev * 1000) / 1000 }
  })
}

return quantiles.map((quantile) => {
    prev = prev + Math.random() * 0.1
    return { quantile, value: Math.round(prev * 1000) / 1000 }
  })
}

/**
 * Generate a metric value based on type.
 */
const generateValue = (type: MetricType, metricIndex: number): number => {
  switch (type) {
    case 'counter':
      // Counters are cumulative, simulate high values
      return Math.floor(Math.random() * 1000000) + metricIndex * 1000
    case 'gauge':
      // Gauges fluctuate
      return Math.round(Math.random() * 10000 * 100) / 100
    case 'histogram':
    case 'summary':
      // Sum of observations
      return Math.round(Math.random() * 1000 * 1000) / 1000
    default:
      return Math.random() * 1000
  }
}

/**
 * Prometheus metrics payload generator.
 *
 * Produces realistic infrastructure monitoring metrics
 * with configurable cardinality.
 */
export const prometheusGenerator: PayloadGenerator = {
  id: 'prometheus',
  name: 'Prometheus Metrics',
  description: 'Observability — infrastructure monitoring, APM',

  generate(tier: PayloadTier, eventIndex: number): PrometheusPayload {
    const config = TIER_CONFIG[tier]
    const timestamp = Date.now()

    const metrics: PrometheusMetric[] = Array.from(
      { length: config.metricCount },
      (_, i) => {
        const name = `tmnl_${METRIC_NAMES[i % METRIC_NAMES.length]}`
        const type = METRIC_TYPES[i % METRIC_TYPES.length]

        const metric: PrometheusMetric = {
          name,
          type,
          help: `Mock metric: ${name}`,
          labels: generateLabels(config.labelCardinality, i, eventIndex),
          value: generateValue(type, i),
          timestamp,
        }

// Add histogram buckets for histogram types
        if (type === 'histogram') {
          metric.buckets = generateBuckets()
        }

        // Add quantiles for summary types (alternate between histogram and summary)
        if (type === 'summary' || (type === 'histogram' && i % 3 === 0)) {
          metric.quantiles = generateQuantiles()
        }

        return metric
      }
    )

    return { metrics }
  },

  estimateSizeBytes(tier: PayloadTier): number {
    return PAYLOAD_SIZE_TARGETS[tier]
  },
}

