 *       })
 *     }
 *   }
 * })
 * ```
 */
export function batchLegendState<TContext, TEvent>(
  updater: (context: TContext, event: TEvent) => void
) {
  return ({ context, event }: { context: TContext; event: TEvent }) => {
    batch(() => {
      updater(context, event)
    })
  }
}

