/**
 * Create a reactive bridge that sends events to an XState actor
 * whenever Legend-State observables change.
 *
 * @example
 * ```typescript
 * const actor = createActor(machine)
 * actor.start()
 *
 * const dispose = bridgeToActor(
 *   () => ({
