// Convenience Factories
// =============================================================================

// =============================================================================
// Convenience Factories
// =============================================================================

/**
 * Create a stx instance with just data (no machine, no effects)
 * Alias for simple Legend-State usage
 */
export function stxData<TData extends object>(data: TData) {
  return stx({ data })
}

/**
 * Create a stx instance with machine + data
 */
export function stxMachine<
  TMachine extends AnyStateMachine,
  TData extends object = object,
>(machine: TMachine, data: TData) {
  return stx({ machine, data })
}

/**
 * Create a stx instance with machine + data + automatic context sync
 * Machine context and Legend-State data stay in sync automatically.
 */
export function stxSynced<
  TMachine extends AnyStateMachine,
  TData extends object,
>(
  machine: TMachine,
  data: TData,
  options?: {
    /** Fields to sync (default: all matching keys) */
    syncFields?: (keyof TData)[]
    /** Debounce data → machine sync (ms) */
    debounce?: number
  }
) {
  const syncFields = options?.syncFields ?? (Object.keys(data) as (keyof TData)[])

  return stx({
    machine,
    data,
    bindings: {
      dataToMachine: {
        selector: (d) => {
          const result: Partial<TData> = {}
          for (const field of syncFields) {
            result[field] = (d as Record<string, { get: () => unknown }>)[field as string]?.get?.() as TData[typeof field]
          }
          return result
        },
        toEvent: (values) => ({ type: 'DATA_SYNC', ...(values as object) }) as EventFromLogic<TMachine>,
        debounce: options?.debounce,
      },
      machineToData: {
        selector: (snapshot) => (snapshot as { context: unknown }).context as Partial<TData>,
        fields: syncFields as (keyof TData)[],
      },
    },
  })
}

/**
 * Unified State Types
 *
 * TypeScript types for the tri-library composition:
 * - XState (shape/logic)
 * - Legend-State (hydration/data)
 * - effect-atom (Effect bridge)
 *
 * @module
 */

import type { Effect, Stream } from 'effect'
import type { Observable, ObservableObject } from '@legendapp/state'
import type {
  AnyStateMachine,
  Actor,
  ActorRefFrom,
  SnapshotFrom,
  EventFromLogic,
} from 'xstate'
import { Atom } from '@effect-atom/atom'
import { type Result } from '@effect-atom/atom/Result'

// Re-export Result type for convenience
export type { Result }

// =============================================================================
// Core State Configuration
// =============================================================================

/**
 * Configuration for the unified stx({}) factory
 */
export interface StxConfig<
  TMachine extends AnyStateMachine | undefined = undefined,
  TData extends object = object,
  TEffects extends EffectsConfig = EffectsConfig,
  TComputed extends ComputedConfig<TData, TMachine> = ComputedConfig<TData, TMachine>,
> {
  /** XState machine definition (optional - for logic/shape) */
  readonly machine?: TMachine

  /** Initial data shape (Legend-State observable) */
  readonly data: TData

  /** Effect-TS effects (async operations) */
  readonly effects?: TEffects

  /** Computed/derived values */
  readonly computed?: TComputed

  /** Persistence configuration */
  readonly persist?: PersistConfig

  /** Schema validation */
  readonly schema?: unknown // Schema.Schema<TData> - loose for now
}

// =============================================================================
// Effects Configuration
// =============================================================================

/**
 * Map of named Effect-TS effects
 */
export type EffectsConfig = Record<
  string,
  Effect.Effect<unknown, unknown, unknown> | ((...args: any[]) => Effect.Effect<unknown, unknown, unknown>)
>

/**
 * Extract the return type of an effect
 */
export type EffectResult<T> = T extends Effect.Effect<infer A, infer E, any>
  ? Result<A, E>
  : T extends (...args: any[]) => Effect.Effect<infer A, infer E, any>
  ? Result<A, E>
  : never

// =============================================================================
// Computed Configuration
// =============================================================================

/**
 * Getter context for computed values
 */
export interface StxGetter<TData extends object, TMachine extends AnyStateMachine | undefined> {
  /** Access data fields (Legend-State) */
  readonly data: ObservableObject<TData>

  /** Access machine state (XState) - only if machine defined */
  readonly machine: TMachine extends AnyStateMachine
    ? {
        matches: (state: string) => boolean
        snapshot: SnapshotFrom<TMachine>
        context: SnapshotFrom<TMachine>['context']
      }
    : undefined
}

/**
 * Map of computed value factories
 */
export type ComputedConfig<
  TData extends object,
  TMachine extends AnyStateMachine | undefined,
> = Record<string, (get: StxGetter<TData, TMachine>) => unknown>

// =============================================================================
// Persistence Configuration
// =============================================================================

export interface PersistConfig {
  /** Unique key for storage */
  readonly name: string

  /** Storage plugin ('localStorage' | 'indexedDB' | 'mmkv') */
  readonly plugin?: 'localStorage' | 'indexedDB' | 'mmkv'

  /** Fields to persist (default: all) */
  readonly include?: string[]

  /** Fields to exclude from persistence */
  readonly exclude?: string[]

  /** Debounce writes (ms) */
  readonly debounce?: number
}

// =============================================================================
// Unified State Instance
// =============================================================================

/**
 * The unified state instance returned by stx({})
 */
export interface Stx<
  TMachine extends AnyStateMachine | undefined,
  TData extends object,
  TEffects extends EffectsConfig,
  TComputed extends ComputedConfig<TData, TMachine>,
> {
  /** Legend-State observable for data */
  readonly data: ObservableObject<TData>

/** XState actor reference (if machine provided) */
  readonly actor: TMachine extends AnyStateMachine ? ActorRefFrom<TMachine> : undefined

  /** Send events to machine (if machine provided) */
  readonly send: TMachine extends AnyStateMachine
    ? (event: EventFromLogic<TMachine>) => void
    : undefined

  /** Effect runners */
  readonly effects: {
    [K in keyof TEffects]: TEffects[K] extends (...args: infer Args) => Effect.Effect<infer A, infer E, any>
      ? (...args: Args) => Promise<Result<A, E>>
      : TEffects[K] extends Effect.Effect<infer A, infer E, any>
      ? () => Promise<Result<A, E>>
      : never
  }

  /** Computed values as atoms */
  readonly computed: {
    [K in keyof TComputed]: Atom.Atom<ReturnType<TComputed[K]>>
  }

  /** Subscribe to all state changes */
  readonly subscribe: (callback: () => void) => () => void

  /** Reset to initial state */
  readonly reset: () => void

  /** Dispose all resources */
  readonly dispose: () => void
}

// =============================================================================
// Hook Return Types
// =============================================================================

/**
 * Return type for useStxValue hook
 */
export type UseStxValueReturn<T> = T

/**
 * Return type for useStxSend hook
 */
export type UseStxSendReturn<TMachine extends AnyStateMachine> = (
  event: EventFromLogic<TMachine>
) => void

/**
 * Return type for useStxMachine hook
 */
export type UseStxMachineReturn<TMachine extends AnyStateMachine> = [
  SnapshotFrom<TMachine>,
  (event: EventFromLogic<TMachine>) => void,
  ActorRefFrom<TMachine>,
]

/**
 * Return type for useStxEffect hook
 */
export type UseStxEffectReturn<TEffects extends EffectsConfig> = <K extends keyof TEffects>(
  name: K,
  ...args: TEffects[K] extends (...args: infer Args) => any ? Args : []
) => Promise<EffectResult<TEffects[K]>>

// =============================================================================
// Stream/Progressive State
// =============================================================================

/**
 * Configuration for stream-based progressive state
 */
export interface StreamStxConfig<A, E> {
  /** The stream source */
  readonly stream: Stream.Stream<A, E>

  /** Initial value before stream emits */
  readonly initial?: A

  /** Buffer strategy */
  readonly buffer?: 'latest' | 'all' | { size: number }

  /** Backpressure handling */
  readonly backpressure?: 'drop' | 'buffer' | 'error'
}

/**
 * Progressive state instance
 */
export interface StxStream<A, E> {
  /** Current value atom */
  readonly value: Atom.Atom<Result<A, E>>

  /** All buffered values (if buffer: 'all') */
  readonly buffer: Atom.Atom<readonly A[]>

  /** Stream status */
  readonly status: Atom.Atom<'idle' | 'streaming' | 'complete' | 'error'>

  /** Pause streaming */
  readonly pause: () => void

  /** Resume streaming */
  readonly resume: () => void

  /** Reset to initial */
  readonly reset: () => void
}

// =============================================================================
// Utility Types
// =============================================================================

/**
 * Extract data type from a unified state
 */
export type DataOf<S> = S extends Stx<any, infer D, any, any> ? D : never

/**
 * Extract machine type from a unified state
 */
export type MachineOf<S> = S extends Stx<infer M, any, any, any> ? M : never

/**
 * Extract effects type from a unified state
 */
export type EffectsOf<S> = S extends Stx<any, any, infer E, any> ? E : never

/**
 * TableService
 *
 * Effect.Service for TmnlDataGrid variant configuration.
 * Manages presets, per-grid overrides, and layered inheritance.
 *
 * @example
 * ```tsx
 * // In atoms/index.ts
 * export const tableServiceRuntime = Atom.runtime(TableService.Default)
 *
 * // Usage via atoms
 * const presets = useAtomValue(presetsAtom)
 * const createPreset = useAtomValue(createPresetOp)
 * ```
 *
 * @module
 */

import { Context, Effect, Layer, Ref, Option } from 'effect'
import { nanoid } from 'nanoid'
import type {
  PresetId,
  GridId,
  Preset,
  GridOverride,
  TableServiceState,
} from './types'
import { initialState, CURRENT_VERSION } from './types'
import type { GridVariant, GridVariantPartial } from '@/lib/data-grid/schemas/variant'
import { DEFAULT_VARIANT } from '@/lib/data-grid/variants'
import {
  deepMerge,
  loadPersistedState,
  savePersistedState,
  createDebouncedPersist,
} from './persistence'

// =============================================================================
// SERVICE INTERFACE
// =============================================================================

export interface TableServiceShape {
  // ---------------------------------------------------------------------------
  // Preset CRUD
  // ---------------------------------------------------------------------------

  /** Get all presets */
  readonly getPresets: Effect.Effect<ReadonlyArray<Preset>>

  /** Get preset by ID */
  readonly getPreset: (id: PresetId) => Effect.Effect<Option.Option<Preset>>

  /** Create a new preset from current variant */
  readonly createPreset: (
    name: string,
    variant: GridVariant
  ) => Effect.Effect<Preset>

  /** Update an existing preset */
  readonly updatePreset: (
    id: PresetId,
    partial: Partial<Pick<Preset, 'name'> & { variant: Partial<GridVariant> }>
  ) => Effect.Effect<Option.Option<Preset>>

  /** Delete a preset (fails for built-in) */
  readonly deletePreset: (id: PresetId) => Effect.Effect<boolean>

/** Delete a preset (fails for built-in) */
  readonly deletePreset: (id: PresetId) => Effect.Effect<boolean>

  // ---------------------------------------------------------------------------
  // Active Preset
  // ---------------------------------------------------------------------------

  /** Get the active preset ID (null = default variant) */
  readonly getActivePresetId: Effect.Effect<PresetId | null>

  /** Set the active preset */
  readonly setActivePreset: (id: PresetId | null) => Effect.Effect<void>

  /** Get the resolved active variant (preset or default) */
  readonly getActiveVariant: Effect.Effect<GridVariant>

  // ---------------------------------------------------------------------------
  // Grid Overrides (Layered Inheritance)
  // ---------------------------------------------------------------------------

  /** Get variant for a specific grid with layered resolution */
  readonly getVariantForGrid: (gridId: GridId) => Effect.Effect<GridVariant>

  /** Set grid-specific override */
  readonly setGridOverride: (
    gridId: GridId,
    overrides: GridVariantPartial
  ) => Effect.Effect<void>

  /** Clear grid-specific override */
  readonly clearGridOverride: (gridId: GridId) => Effect.Effect<void>

  /** Get all grid overrides */
  readonly getGridOverrides: Effect.Effect<Record<string, GridOverride>>

  // ---------------------------------------------------------------------------
  // Persistence
  // ---------------------------------------------------------------------------

  /** Force persist current state */
  readonly persist: Effect.Effect<void>

  /** Restore state from storage */
  readonly restore: Effect.Effect<void>

  // ---------------------------------------------------------------------------
  // Internal State Access
  // ---------------------------------------------------------------------------

  /** Get full service state (for atoms) */
  readonly getState: Effect.Effect<TableServiceState>
}

// =============================================================================
// SERVICE TAG
// =============================================================================

// ---------------------------------------------------------------------------
  // Internal State Access
  // ---------------------------------------------------------------------------

  /** Get full service state (for atoms) */
  readonly getState: Effect.Effect<TableServiceState>
}

// =============================================================================
// SERVICE TAG
// =============================================================================

export class TableService extends Context.Tag('tmnl/TableService')<
  TableService,
  TableServiceShape
>() {
  /**
   * Default service layer with localStorage persistence.
   */
  static Default = Layer.effect(
    TableService,
    Effect.gen(function* () {
      // Internal state ref
      const stateRef = yield* Ref.make<TableServiceState>(initialState)

      // Debounced persist (500ms delay)
      const debouncedPersist = createDebouncedPersist(500)

      // Auto-persist on state change
      const persistOnChange = () => {
        Effect.runPromise(Ref.get(stateRef)).then(debouncedPersist)
      }

      // -----------------------------------------------------------------------
      // Preset CRUD
      // -----------------------------------------------------------------------

      const getPresets: TableServiceShape['getPresets'] = Effect.gen(
        function* () {
          const state = yield* Ref.get(stateRef)
          return state.presets
        }
      )

      const getPreset: TableServiceShape['getPreset'] = (id) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)
          const preset = state.presets.find((p) => p.id === id)
          return preset ? Option.some(preset) : Option.none()
        })

      const createPreset: TableServiceShape['createPreset'] = (name, variant) =>
        Effect.gen(function* () {
          const now = new Date()
          const preset: Preset = {
            id: nanoid(8) as PresetId,
            name: name as typeof name & { readonly NonEmptyString: unique symbol },
            variant,
            createdAt: now,
            updatedAt: now,
            isBuiltIn: false,
          }

          yield* Ref.update(stateRef, (state) => ({
            ...state,
            presets: [...state.presets, preset],
          }))

yield* Ref.update(stateRef, (state) => ({
            ...state,
            presets: [...state.presets, preset],
          }))

          persistOnChange()
          return preset
        })

      const updatePreset: TableServiceShape['updatePreset'] = (id, partial) =>
        Effect.gen(function* () {
          let updated: Preset | null = null

          yield* Ref.update(stateRef, (state) => {
            const index = state.presets.findIndex((p) => p.id === id)
            if (index === -1) return state

            const existing = state.presets[index]
            updated = {
              ...existing,
              name: partial.name
                ? (partial.name as typeof existing.name)
                : existing.name,
              variant: partial.variant
                ? deepMerge(existing.variant, partial.variant as Partial<GridVariant>)
                : existing.variant,
              updatedAt: new Date(),
            }

            const newPresets = [...state.presets]
            newPresets[index] = updated
            return { ...state, presets: newPresets }
          })

          if (updated) persistOnChange()
          return updated ? Option.some(updated) : Option.none()
        })

      const deletePreset: TableServiceShape['deletePreset'] = (id) =>
        Effect.gen(function* () {
          let deleted = false

          yield* Ref.update(stateRef, (state) => {
            const preset = state.presets.find((p) => p.id === id)
            if (!preset || preset.isBuiltIn) return state

            deleted = true
            return {
              ...state,
              presets: state.presets.filter((p) => p.id !== id),
              // Clear active if deleted
              activePresetId:
                state.activePresetId === id ? null : state.activePresetId,
            }
          })

          if (deleted) persistOnChange()
          return deleted
        })

      // -----------------------------------------------------------------------
      // Active Preset
      // -----------------------------------------------------------------------

if (deleted) persistOnChange()
          return deleted
        })

      // -----------------------------------------------------------------------
      // Active Preset
      // -----------------------------------------------------------------------

      const getActivePresetId: TableServiceShape['getActivePresetId'] =
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)
          return state.activePresetId
        })

      const setActivePreset: TableServiceShape['setActivePreset'] = (id) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (state) => ({
            ...state,
            activePresetId: id,
          }))
          persistOnChange()
        })

      const getActiveVariant: TableServiceShape['getActiveVariant'] = Effect.gen(
        function* () {
          const state = yield* Ref.get(stateRef)

          if (state.activePresetId === null) {
            return DEFAULT_VARIANT
          }

          const preset = state.presets.find(
            (p) => p.id === state.activePresetId
          )
          return preset?.variant ?? DEFAULT_VARIANT
        }
      )

      // -----------------------------------------------------------------------
      // Grid Overrides (Layered Inheritance)
      // -----------------------------------------------------------------------

      const getVariantForGrid: TableServiceShape['getVariantForGrid'] = (
        gridId
      ) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)

          // Layer 1: Start with default or active preset
          const base = yield* getActiveVariant

          // Layer 2: Apply grid-specific overrides
          const override = state.gridOverrides[gridId]
          if (!override) return base

          // Deep merge override on top of base
          return deepMerge(base, override.overrides as Partial<GridVariant>)
        })

      const setGridOverride: TableServiceShape['setGridOverride'] = (
        gridId,
        overrides
      ) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)

const setGridOverride: TableServiceShape['setGridOverride'] = (
        gridId,
        overrides
      ) =>
        Effect.gen(function* () {
          const state = yield* Ref.get(stateRef)

          const gridOverride: GridOverride = {
            gridId,
            basePresetId: state.activePresetId ?? undefined,
            overrides,
            updatedAt: new Date(),
          }

          yield* Ref.update(stateRef, (s) => ({
            ...s,
            gridOverrides: {
              ...s.gridOverrides,
              [gridId]: gridOverride,
            },
          }))

          persistOnChange()
        })

      const clearGridOverride: TableServiceShape['clearGridOverride'] = (
        gridId
      ) =>
        Effect.gen(function* () {
          yield* Ref.update(stateRef, (state) => {
            const { [gridId]: _, ...rest } = state.gridOverrides
            return { ...state, gridOverrides: rest }
          })
          persistOnChange()
        })

      const getGridOverrides: TableServiceShape['getGridOverrides'] = Effect.gen(
        function* () {
          const state = yield* Ref.get(stateRef)
          return state.gridOverrides
        }
      )

      // -----------------------------------------------------------------------
      // Persistence
      // -----------------------------------------------------------------------

      const persist: TableServiceShape['persist'] = Effect.gen(function* () {
        const state = yield* Ref.get(stateRef)
        yield* savePersistedState(state)
      })

      const restore: TableServiceShape['restore'] = Effect.gen(function* () {
        const loaded = yield* loadPersistedState

        if (Option.isSome(loaded)) {
          yield* Ref.set(stateRef, loaded.value)
        }
      })

      // -----------------------------------------------------------------------
      // State Access
      // -----------------------------------------------------------------------

      const getState: TableServiceShape['getState'] = Ref.get(stateRef)

      // -----------------------------------------------------------------------
      // Auto-restore on init
      // -----------------------------------------------------------------------
      yield* restore

const getState: TableServiceShape['getState'] = Ref.get(stateRef)

      // -----------------------------------------------------------------------
      // Auto-restore on init
      // -----------------------------------------------------------------------
      yield* restore

      // -----------------------------------------------------------------------
      // Return service shape
      // -----------------------------------------------------------------------
      return {
        getPresets,
        getPreset,
        createPreset,
        updatePreset,
        deletePreset,
        getActivePresetId,
        setActivePreset,
        getActiveVariant,
        getVariantForGrid,
        setGridOverride,
        clearGridOverride,
        getGridOverrides,
        persist,
        restore,
        getState,
      } satisfies TableServiceShape
    })
  )
}

/**
 * TableService Atoms (Materialized Views)
 *
 * These atoms represent the **materialized views** that TableService publishes.
 * Components subscribe to these atoms; TableService updates them during operations.
 *
 * Pattern:
 * - Atoms declared at module level (singleton, writable)
 * - Operation atoms use FnContext.set() to publish updates
 * - Components call useAtomValue() to subscribe
 * - Multiple components share the same view (same atom)
 *
 * @module
 */

import { Atom } from '@effect-atom/atom-react'
import * as Effect from 'effect/Effect'
import * as Option from 'effect/Option'

import { TableService } from '../TableService'
import { DEFAULT_VARIANT } from '@/lib/data-grid/variants'
import type { Preset, GridId, PresetId, TableServiceState } from '../types'
import type { GridVariant, GridVariantPartial } from '@/lib/data-grid/schemas/variant'

// =============================================================================
// Materialized View Atoms (Module-Level Singletons)
// =============================================================================

/**
 * All presets (built-in + user-created)
 */
export const presetsAtom = Atom.make<readonly Preset[]>([])

/**
 * Currently active preset ID (null = default variant)
 */
export const activePresetIdAtom = Atom.make<PresetId | null>(null)

/**
 * Resolved active variant (preset variant or default)
 */
export const activeVariantAtom = Atom.make<GridVariant>(DEFAULT_VARIANT)

/**
 * Per-grid overrides keyed by GridId
 */
export const gridOverridesAtom = Atom.make<Record<string, { overrides: GridVariantPartial }>>({})

/**
 * Service ready state
 */
export const isReadyAtom = Atom.make<boolean>(false)

// =============================================================================
// Derived Atoms
// =============================================================================

/**
 * Count of user-created (non-built-in) presets
 */
export const userPresetCountAtom = Atom.make((get) => {
  const presets = get(presetsAtom)
  return presets.filter((p) => !p.isBuiltIn).length
})

/**
 * Active preset instance (resolved from ID)
 */
export const activePresetAtom = Atom.make((get) => {
  const presetId = get(activePresetIdAtom)
  const presets = get(presetsAtom)

  if (presetId === null) return null
  return presets.find((p) => p.id === presetId) ?? null
})

/**
 * Whether a preset is currently active (vs using default)
 */
export const hasActivePresetAtom = Atom.make((get) => {
  return get(activePresetIdAtom) !== null
})

// =============================================================================
// Runtime Atom (For Effect Operations)
// =============================================================================

/**
 * TableService Runtime Atom
 *
 * Provides Effect runtime for operations that need TableService.
 * Used by operation atoms to execute Effects.
 */
export const tableServiceRuntimeAtom = Atom.runtime(TableService.Default)

// =============================================================================
// Sync State Helper
// =============================================================================

/**
 * Sync service state to atoms.
 * Called by operations to keep atoms in sync with service state.
 */
const syncState = (ctx: { set: <T>(atom: Atom.Writable<T>, value: T) => void }) =>
  Effect.gen(function* () {
    const service = yield* TableService
    const state = yield* service.getState

    ctx.set(presetsAtom, state.presets)
    ctx.set(activePresetIdAtom, state.activePresetId)
    ctx.set(gridOverridesAtom, state.gridOverrides as Record<string, { overrides: GridVariantPartial }>)

    // Resolve active variant
    const activeVariant = yield* service.getActiveVariant
    ctx.set(activeVariantAtom, activeVariant)
  })

// =============================================================================
// Operation Atoms (Mutations via Effect)
// =============================================================================

/**
 * Preset Operations
 */
export const presetOps = {
  /**
   * Initialize service and sync state to atoms
   */
  init: tableServiceRuntimeAtom.fn()((_, ctx) =>
    Effect.gen(function* () {
      yield* syncState(ctx)
      ctx.set(isReadyAtom, true)
    })
  ),

/**
   * Create a new preset
   */
  create: tableServiceRuntimeAtom.fn<{ name: string; variant: GridVariant }>()(
    ({ name, variant }, ctx) =>
      Effect.gen(function* () {
        const service = yield* TableService
        const preset = yield* service.createPreset(name, variant)
        yield* syncState(ctx)
        return preset
      })
  ),

  /**
   * Update an existing preset
   */
  update: tableServiceRuntimeAtom.fn<{
    id: PresetId
    partial: Partial<Pick<Preset, 'name'> & { variant: Partial<GridVariant> }>
  }>()(({ id, partial }, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      const result = yield* service.updatePreset(id, partial)
      yield* syncState(ctx)
      return Option.getOrNull(result)
    })
  ),

  /**
   * Delete a preset
   */
  delete: tableServiceRuntimeAtom.fn<PresetId>()((id, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      const deleted = yield* service.deletePreset(id)
      yield* syncState(ctx)
      return deleted
    })
  ),

  /**
   * Set active preset
   */
  setActive: tableServiceRuntimeAtom.fn<PresetId | null>()((id, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      yield* service.setActivePreset(id)
      yield* syncState(ctx)
    })
  ),
}

/**
 * Grid Override Operations
 */
export const gridOps = {
  /**
   * Get variant for a specific grid (with layered resolution)
   */
  getVariant: tableServiceRuntimeAtom.fn<GridId>()((gridId, _ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      return yield* service.getVariantForGrid(gridId)
    })
  ),

/**
   * Set grid-specific override
   */
  setOverride: tableServiceRuntimeAtom.fn<{
    gridId: GridId
    overrides: GridVariantPartial
  }>()(({ gridId, overrides }, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      yield* service.setGridOverride(gridId, overrides)
      yield* syncState(ctx)
    })
  ),

  /**
   * Clear grid-specific override
   */
  clearOverride: tableServiceRuntimeAtom.fn<GridId>()((gridId, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      yield* service.clearGridOverride(gridId)
      yield* syncState(ctx)
    })
  ),
}

/**
 * Persistence Operations
 */
export const persistOps = {
  /**
   * Force persist current state
   */
  persist: tableServiceRuntimeAtom.fn()((_, _ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      yield* service.persist
    })
  ),

  /**
   * Restore state from storage
   */
  restore: tableServiceRuntimeAtom.fn()((_, ctx) =>
    Effect.gen(function* () {
      const service = yield* TableService
      yield* service.restore
      yield* syncState(ctx)
    })
  ),
}

// Derived state
  readonly userPresetCount: number
  readonly hasActivePreset: boolean

  // Preset operations
  readonly createPreset: (name: string, variant: GridVariant) => Promise<Preset>
  readonly updatePreset: (
    id: PresetId,
    partial: Partial<Pick<Preset, 'name'> & { variant: Partial<GridVariant> }>
  ) => Promise<Preset | null>
  readonly deletePreset: (id: PresetId) => Promise<boolean>
  readonly setActivePreset: (id: PresetId | null) => Promise<void>

  // Grid operations
  readonly getVariantForGrid: (gridId: GridId) => Promise<GridVariant>
  readonly setGridOverride: (
    gridId: GridId,
    overrides: GridVariantPartial
  ) => Promise<void>
  readonly clearGridOverride: (gridId: GridId) => Promise<void>

  // Persistence
  readonly persist: () => Promise<void>
  readonly restore: () => Promise<void>
}

// =============================================================================
// Hook Implementation
// =============================================================================

/**
 * useTableService - Main hook for TableService integration
 *
 * Provides reactive access to variant presets and operations.
 * All state updates are automatic via effect-atom subscriptions.
 *
 * Auto-initializes on first mount.
 */
export function useTableService(): UseTableServiceResult {
  // ---------------------------------------------------------------------------
  // Atom Subscriptions
  // ---------------------------------------------------------------------------

  const presets = useAtomValue(presetsAtom)
  const activePresetId = useAtomValue(activePresetIdAtom)
  const activeVariant = useAtomValue(activeVariantAtom)
  const gridOverrides = useAtomValue(gridOverridesAtom)
  const isReady = useAtomValue(isReadyAtom)

  // Derived atoms
  const userPresetCount = useAtomValue(userPresetCountAtom)
  const activePreset = useAtomValue(activePresetAtom)
  const hasActivePreset = useAtomValue(hasActivePresetAtom)

  // ---------------------------------------------------------------------------
  // Operation Setters
  // ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
  // Operation Setters
  // ---------------------------------------------------------------------------

  const doInit = useAtomSet(presetOps.init, { mode: 'promise' })
  const doCreate = useAtomSet(presetOps.create, { mode: 'promise' })
  const doUpdate = useAtomSet(presetOps.update, { mode: 'promise' })
  const doDelete = useAtomSet(presetOps.delete, { mode: 'promise' })
  const doSetActive = useAtomSet(presetOps.setActive, { mode: 'promise' })

  const doGetVariant = useAtomSet(gridOps.getVariant, { mode: 'promise' })
  const doSetOverride = useAtomSet(gridOps.setOverride, { mode: 'promise' })
  const doClearOverride = useAtomSet(gridOps.clearOverride, { mode: 'promise' })

  const doPersist = useAtomSet(persistOps.persist, { mode: 'promise' })
  const doRestore = useAtomSet(persistOps.restore, { mode: 'promise' })

  // ---------------------------------------------------------------------------
  // Auto-Initialize
  // ---------------------------------------------------------------------------

  useEffect(() => {
    if (!isReady) {
      doInit(undefined).catch(console.error)
    }
  }, [isReady, doInit])

  // ---------------------------------------------------------------------------
  // Wrapped Operations
  // ---------------------------------------------------------------------------

  const createPreset = useCallback(
    async (name: string, variant: GridVariant): Promise<Preset> => {
      return (await doCreate({ name, variant })) as Preset
    },
    [doCreate]
  )

  const updatePreset = useCallback(
    async (
      id: PresetId,
      partial: Partial<Pick<Preset, 'name'> & { variant: Partial<GridVariant> }>
    ): Promise<Preset | null> => {
      return (await doUpdate({ id, partial })) as Preset | null
    },
    [doUpdate]
  )

const deletePreset = useCallback(
    async (id: PresetId): Promise<boolean> => {
      return (await doDelete(id)) as boolean
    },
    [doDelete]
  )

  const setActivePreset = useCallback(
    async (id: PresetId | null): Promise<void> => {
      await doSetActive(id)
    },
    [doSetActive]
  )

  const getVariantForGrid = useCallback(
    async (gridId: GridId): Promise<GridVariant> => {
      return (await doGetVariant(gridId)) as GridVariant
    },
    [doGetVariant]
  )

  const setGridOverride = useCallback(
    async (gridId: GridId, overrides: GridVariantPartial): Promise<void> => {
      await doSetOverride({ gridId, overrides })
    },
    [doSetOverride]
  )

  const clearGridOverride = useCallback(
    async (gridId: GridId): Promise<void> => {
      await doClearOverride(gridId)
    },
    [doClearOverride]
  )

  const persist = useCallback(async (): Promise<void> => {
    await doPersist(undefined)
  }, [doPersist])

  const restore = useCallback(async (): Promise<void> => {
    await doRestore(undefined)
  }, [doRestore])

  // ---------------------------------------------------------------------------
  // Return Interface
  // ---------------------------------------------------------------------------

  return {
    // State
    presets,
    activePresetId,
    activeVariant,
    activePreset,
    gridOverrides,
    isReady,

    // Derived
    userPresetCount,
    hasActivePreset,

    // Preset operations
    createPreset,
    updatePreset,
    deletePreset,
    setActivePreset,

    // Grid operations
    getVariantForGrid,
    setGridOverride,
    clearGridOverride,

    // Persistence
    persist,
    restore,
  }
}

/**
 * TableService Persistence
 *
 * localStorage helpers with versioned schemas and migration support.
 *
 * @module
 */

import { Effect, Schema, Option } from 'effect'
import {
  TableServiceState,
  PersistedState,
  STORAGE_KEY,
  CURRENT_VERSION,
  initialState,
} from './types'

// =============================================================================
// PERSISTENCE ERRORS
// =============================================================================

export class PersistenceError {
  readonly _tag = 'PersistenceError'
  constructor(
    readonly reason: 'parse' | 'validation' | 'storage' | 'migration',
    readonly message: string,
    readonly cause?: unknown
  ) {}
}

// =============================================================================
// DEEP MERGE UTILITY
// =============================================================================

/**
 * Deep merge two objects, with source taking precedence.
 * Handles nested objects, preserves arrays (doesn't merge them).
 */
export function deepMerge<T extends object>(target: T, source: Partial<T>): T {
  const result = { ...target }

  for (const key of Object.keys(source) as Array<keyof T>) {
    const sourceValue = source[key]
    const targetValue = target[key]

    if (sourceValue === undefined) {
      continue
    }

    if (
      sourceValue !== null &&
      typeof sourceValue === 'object' &&
      !Array.isArray(sourceValue) &&
      targetValue !== null &&
      typeof targetValue === 'object' &&
      !Array.isArray(targetValue)
    ) {
      // Recursively merge nested objects
      result[key] = deepMerge(targetValue as object, sourceValue as object) as T[keyof T]
    } else {
      // Overwrite with source value
      result[key] = sourceValue as T[keyof T]
    }
  }

  return result
}

// =============================================================================
// LOAD FROM STORAGE
// =============================================================================

return result
}

// =============================================================================
// LOAD FROM STORAGE
// =============================================================================

/**
 * Load persisted state from localStorage.
 * Returns Option.none if no stored state or parse/validation fails.
 */
export const loadPersistedState = Effect.gen(function* () {
  // Read raw JSON
  const raw = yield* Effect.try({
    try: () => {
      const stored = localStorage.getItem(STORAGE_KEY)
      if (!stored) return null
      return JSON.parse(stored)
    },
    catch: (error) =>
      new PersistenceError('parse', 'Failed to parse stored state', error),
  })

  if (raw === null) {
    return Option.none<TableServiceState>()
  }

  // Validate envelope
  const envelope = yield* Effect.tryPromise({
    try: () => Schema.decodeUnknownPromise(PersistedState)(raw),
    catch: (error) =>
      new PersistenceError('validation', 'Invalid stored state schema', error),
  })

  // Check version and migrate if needed
  const migratedState = yield* migrateState(envelope.state, envelope.version)

  return Option.some(migratedState)
}).pipe(
  Effect.catchAll((error) => {
    // Log error but don't fail - just return empty state
    console.warn('[TableService] Persistence load failed:', error)
    return Effect.succeed(Option.none<TableServiceState>())
  })
)

// =============================================================================
// SAVE TO STORAGE
// =============================================================================

/**
 * Save state to localStorage with envelope.
 */
export const savePersistedState = (state: TableServiceState) =>
  Effect.gen(function* () {
    const envelope: PersistedState = {
      version: CURRENT_VERSION,
      state,
      lastPersistedAt: new Date(),
    }

    // Encode to JSON-safe format
    const encoded = yield* Effect.tryPromise({
      try: () => Schema.encodePromise(PersistedState)(envelope),
      catch: (error) =>
        new PersistenceError('validation', 'Failed to encode state', error),
    })

// Write to localStorage
    yield* Effect.try({
      try: () => localStorage.setItem(STORAGE_KEY, JSON.stringify(encoded)),
      catch: (error) =>
        new PersistenceError('storage', 'Failed to write to localStorage', error),
    })
  }).pipe(
    Effect.catchAll((error) => {
      console.error('[TableService] Persistence save failed:', error)
      return Effect.void
    })
  )

// =============================================================================
// MIGRATION
// =============================================================================

/**
 * Migrate state from older versions to current.
 * Add migration steps as schema evolves.
 */
const migrateState = (
  state: TableServiceState,
  fromVersion: number
): Effect.Effect<TableServiceState, PersistenceError> =>
  Effect.gen(function* () {
    let current = state
    let version = fromVersion

    // Migration chain (add cases as needed)
    while (version < CURRENT_VERSION) {
      switch (version) {
        case 0:
          // Example: v0 → v1 migration
          current = { ...current, version: 1 }
          version = 1
          break
        default:
          // Unknown version, reset to initial
          yield* Effect.logWarning(
            `Unknown version ${version}, resetting to initial state`
          )
          return { ...initialState, version: CURRENT_VERSION }
      }
    }

    return current
  })

// =============================================================================
// DEBOUNCED PERSIST
// =============================================================================

/**
 * Create a debounced persist function.
 * Returns a function that schedules persistence after delay.
 */
export function createDebouncedPersist(delayMs: number = 500) {
  let timeoutId: ReturnType<typeof setTimeout> | null = null

  return (state: TableServiceState) => {
    if (timeoutId) {
      clearTimeout(timeoutId)
    }

    timeoutId = setTimeout(() => {
      Effect.runPromise(savePersistedState(state)).catch(console.error)
      timeoutId = null
    }, delayMs)
  }
}

/**
 * TableService Schema Types
 *
 * Effect Schema definitions for variant preset management.
 * Enables runtime validation, localStorage serialization, and type inference.
 *
 * @module
 */

import { Schema } from 'effect'
import { GridVariant, GridVariantPartial } from '@/lib/data-grid/schemas/variant'

// =============================================================================
// BRANDED IDS
// =============================================================================

/**
 * Branded preset identifier for type safety.
 */
export const PresetId = Schema.String.pipe(
  Schema.minLength(1),
  Schema.brand('PresetId')
)
export type PresetId = typeof PresetId.Type

/**
 * Branded grid instance identifier.
 */
export const GridId = Schema.String.pipe(
  Schema.minLength(1),
  Schema.brand('GridId')
)
export type GridId = typeof GridId.Type

// =============================================================================
// PRESET
// =============================================================================

/**
 * A saved variant preset with metadata.
 */
export const Preset = Schema.Struct({
  /** Unique preset identifier */
  id: PresetId,
  /** Human-readable name */
  name: Schema.NonEmptyString,
  /** The variant configuration */
  variant: GridVariant,
  /** Creation timestamp */
  createdAt: Schema.DateFromSelf,
  /** Last update timestamp */
  updatedAt: Schema.DateFromSelf,
  /** Whether this is a built-in preset (non-deletable) */
  isBuiltIn: Schema.optional(Schema.Boolean),
})
export type Preset = typeof Preset.Type

// =============================================================================
// GRID OVERRIDE
// =============================================================================

/**
 * Per-grid variant overrides for layered inheritance.
 *
 * Resolution order: gridOverride > activePreset > defaultVariant
 */
export const GridOverride = Schema.Struct({
  /** The grid instance this override applies to */
  gridId: GridId,
  /** Base preset to inherit from (optional) */
  basePresetId: Schema.optional(PresetId),
  /** Partial overrides applied on top of base */
  overrides: GridVariantPartial,
  /** Last update timestamp */
  updatedAt: Schema.DateFromSelf,
})
export type GridOverride = typeof GridOverride.Type

// =============================================================================
// SERVICE STATE
// =============================================================================

// =============================================================================
// SERVICE STATE
// =============================================================================

/**
 * Complete TableService state for persistence.
 */
export const TableServiceState = Schema.Struct({
  /** All saved presets (built-in + user-created) */
  presets: Schema.Array(Preset),
  /** Per-grid overrides keyed by GridId */
  gridOverrides: Schema.Record({
    key: Schema.String,
    value: GridOverride,
  }),
  /** Currently active global preset (null = use default) */
  activePresetId: Schema.NullOr(PresetId),
  /** Schema version for migration */
  version: Schema.Number,
})
export type TableServiceState = typeof TableServiceState.Type

// =============================================================================
// PERSISTENCE ENVELOPE
// =============================================================================

/**
 * localStorage envelope with version for migration.
 */
export const PersistedState = Schema.Struct({
  version: Schema.Number,
  state: TableServiceState,
  lastPersistedAt: Schema.DateFromSelf,
})
export type PersistedState = typeof PersistedState.Type

// =============================================================================
// CONSTANTS
// =============================================================================

export const CURRENT_VERSION = 1
export const STORAGE_KEY = 'tmnl:table-service:state'

// =============================================================================
// INITIAL STATE
// =============================================================================

export const initialState: TableServiceState = {
  presets: [],
  gridOverrides: {},
  activePresetId: null,
  version: CURRENT_VERSION,
}

/**
 * Telegram Agent Atoms
 *
 * Following cursor architecture patterns:
 * - Module-level atoms (stable references)
 * - stx pattern: XState actor → snapshotAtom → derived atoms
 * - Synchronous operations via registry.set()
 * - Atom-as-State doctrine (no Effect.Ref in services)
 */

import { Atom, Registry } from '@effect-atom/atom';
import {
  telegramActor,
  getTelegramState,
  isTelegramConnected,
  getTelegramError,
  getChatStatus,
  type TelegramMachineSnapshot,
} from '../machines/telegram-machine';
import type { TelegramMessage, TelegramChatState, BotStatus } from '../schemas/message';

// ============================================================================
// Registry (Module-Level Singleton)
// ============================================================================

export const telegramRegistry = Registry.make();

// ============================================================================
// XState Bridge (stx pattern)
// ============================================================================

/**
 * Bridge atom: XState snapshot → effect-atom
 * This is the SINGLE source of truth for machine state
 */
export const telegramSnapshotAtom = Atom.make<TelegramMachineSnapshot>(
  telegramActor.getSnapshot()
);

// Subscribe XState → Atom (runs once at module load)
telegramActor.subscribe((snapshot) => {
  telegramRegistry.set(telegramSnapshotAtom, snapshot);
});

// Start the actor
telegramActor.start();

// ============================================================================
// Derived Atoms (from snapshot)
// ============================================================================

/**
 * Current machine state as string
 */
export const connectionStateAtom = Atom.make((get) =>
  getTelegramState(get(telegramSnapshotAtom))
);

/**
 * Boolean: is bot connected?
 */
export const isConnectedAtom = Atom.make((get) =>
  isTelegramConnected(get(telegramSnapshotAtom))
);

/**
 * Current error message (if any)
 */
export const errorMessageAtom = Atom.make((get) =>
  getTelegramError(get(telegramSnapshotAtom))
);

/**
 * Active chat IDs from machine context
 */
export const activeChatIdsAtom = Atom.make((get) =>
  get(telegramSnapshotAtom).context.activeChatIds
);

// ============================================================================
// Message State Atoms
// ============================================================================

/**
 * Active chat IDs from machine context
 */
export const activeChatIdsAtom = Atom.make((get) =>
  get(telegramSnapshotAtom).context.activeChatIds
);

// ============================================================================
// Message State Atoms
// ============================================================================

/**
 * All messages by chatId
 * Structure: Record<chatId, TelegramMessage[]>
 */
export const messagesByChatAtom = Atom.make<Record<number, TelegramMessage[]>>({});

/**
 * Chat state by chatId
 * Structure: Record<chatId, TelegramChatState>
 */
export const chatStatesByChatAtom = Atom.make<Record<number, TelegramChatState>>({});

/**
 * Bot status per chat
 */
export const botStatusByChatAtom = Atom.make<Record<number, BotStatus>>({});

// ============================================================================
// Utility Atoms (for specific chats)
// ============================================================================

/**
 * Get messages for a specific chat
 */
export const messagesForChatAtom = (chatId: number) =>
  Atom.make((get) => get(messagesByChatAtom)[chatId] ?? []);

/**
 * Get bot status for a specific chat
 */
export const botStatusForChatAtom = (chatId: number) =>
  Atom.make((get) => get(botStatusByChatAtom)[chatId] ?? ('idle' as BotStatus));

/**
 * Get chat status from XState
 */
export const chatStatusFromMachineAtom = (chatId: number) =>
  Atom.make((get) => getChatStatus(get(telegramSnapshotAtom), chatId));

// ============================================================================
// Operations (Synchronous Registry Mutations)
// ============================================================================

export const telegramOps = {
  /**
   * Add a message to a chat
   */
  addMessage: (message: TelegramMessage) => {
    const current = telegramRegistry.get(messagesByChatAtom);
    const chatMessages = current[message.chatId] ?? [];
    telegramRegistry.set(messagesByChatAtom, {
      ...current,
      [message.chatId]: [...chatMessages, message],
    });
  },

/**
   * Clear messages for a chat
   */
  clearChat: (chatId: number) => {
    const current = telegramRegistry.get(messagesByChatAtom);
    telegramRegistry.set(messagesByChatAtom, {
      ...current,
      [chatId]: [],
    });
  },

  /**
   * Set bot status for a chat
   */
  setBotStatus: (chatId: number, status: BotStatus) => {
    const current = telegramRegistry.get(botStatusByChatAtom);
    telegramRegistry.set(botStatusByChatAtom, {
      ...current,
      [chatId]: status,
    });
  },

  /**
   * Update chat state
   */
  updateChatState: (chatId: number, state: Partial<TelegramChatState>) => {
    const current = telegramRegistry.get(chatStatesByChatAtom);
    const existing = current[chatId] ?? {
      chatId,
      messages: [],
      lastActivity: Date.now(),
    };
    telegramRegistry.set(chatStatesByChatAtom, {
      ...current,
      [chatId]: { ...existing, ...state, lastActivity: Date.now() },
    });
  },
};

