  /**
   * Send typing indicator ("bot is typing...")
   */
  readonly sendTypingAction: (chatId: number) => Effect.Effect<void, Error>;

  /**
   * Register a message handler
   */
  readonly onMessage: (
    handler: (msg: Message) => Effect.Effect<void, Error>
  ) => Effect.Effect<void, Error>;

  /**
   * Register a command handler (e.g., /start, /help)
   */
  readonly onCommand: (
    command: string,
    handler: (msg: Message, args: string[]) => Effect.Effect<void, Error>
  ) => Effect.Effect<void, Error>;

  /**
   * Get bot info
   */
  readonly getMe: Effect.Effect<TelegramBot.User, Error>;

  /**
   * Check if bot is currently polling
   */
  readonly isPolling: Effect.Effect<boolean, Error>;
}

// ============================================================================
// Service Tag
// ============================================================================

/**
   * Check if bot is currently polling
   */
  readonly isPolling: Effect.Effect<boolean, Error>;
}

// ============================================================================
// Service Tag
// ============================================================================

export class TelegramAgent extends Context.Tag('tmnl/telegram/TelegramAgent')<
  TelegramAgent,
  TelegramAgentShape
>() {}

// ============================================================================
// Configuration
// ============================================================================

export interface TelegramAgentConfig {
  readonly token: string;
  readonly polling?: boolean;
}

export class TelegramAgentConfigTag extends Context.Tag('tmnl/telegram/TelegramAgentConfig')<
  TelegramAgentConfigTag,
  TelegramAgentConfig
>() {}

// ============================================================================
// Live Implementation
// ============================================================================

export const TelegramAgentLive = Layer.effect(
  TelegramAgent,
  Effect.gen(function* () {
    const config = yield* TelegramAgentConfigTag;

    // node-telegram-bot-api is CommonJS, use require
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const TelegramBotClass = require('node-telegram-bot-api') as typeof TelegramBot;
    const bot: TelegramBot = new TelegramBotClass(config.token, {
      polling: false, // We'll start manually
    });

    // Track handlers for cleanup
    const messageHandlers: Array<(msg: Message) => void> = [];

    return {
      start: Effect.tryPromise({
        try: async () => {
          await bot.startPolling();
        },
        catch: (e) => new Error(`Failed to start polling: ${e}`),
      }),

      stop: Effect.tryPromise({
        try: async () => {
          await bot.stopPolling();
        },
        catch: (e) => new Error(`Failed to stop polling: ${e}`),
      }),

      sendMessage: (chatId, text, options) =>
        Effect.tryPromise({
          try: async () => {
            return await bot.sendMessage(chatId, text, {
              parse_mode: options?.parseMode,
            });
          },
          catch: (e) => new Error(`Failed to send message: ${e}`),
        }),

sendTypingAction: (chatId) =>
        Effect.tryPromise({
          try: async () => {
            await bot.sendChatAction(chatId, 'typing');
          },
          catch: (e) => new Error(`Failed to send typing action: ${e}`),
        }),

      onMessage: (handler) =>
        Effect.sync(() => {
          const wrappedHandler = (msg: Message) => {
            // Run the Effect handler (fire and forget for simplicity)
            Effect.runPromise(handler(msg)).catch(console.error);
          };
          messageHandlers.push(wrappedHandler);
          bot.on('message', wrappedHandler);
        }),

      onCommand: (command, handler) =>
        Effect.sync(() => {
          bot.onText(new RegExp(`^/${command}(?:\\s+(.*))?$`), (msg, match) => {
            const args = match?.[1]?.split(/\s+/).filter(Boolean) ?? [];
            Effect.runPromise(handler(msg, args)).catch(console.error);
          });
        }),

      getMe: Effect.tryPromise({
        try: async () => {
          return await bot.getMe();
        },
        catch: (e) => new Error(`Failed to get bot info: ${e}`),
      }),

      isPolling: Effect.sync(() => bot.isPolling()),
    };
  })
);

// ============================================================================
// Default Layer (uses environment variable)
// ============================================================================

export const TelegramAgentConfigFromEnv = Layer.effect(
  TelegramAgentConfigTag,
  Effect.sync(() => ({
    token: process.env.TELEGRAM_BOT_TOKEN ?? '',
    polling: true,
  }))
);

export const TelegramAgentDefault = TelegramAgentLive.pipe(
  Layer.provide(TelegramAgentConfigFromEnv)
);

/**
 * GhosttyTerminal - React wrapper for ghostty-web
 *
 * Provides a React component that wraps the ghostty-web Terminal
 * with proper lifecycle management, ref API, and TMNL integration.
 *
 * @example
 * ```tsx
 * import { GhosttyTerminal } from '@/lib/terminal';
 *
 * function MyTerminal() {
 *   const termRef = useRef<GhosttyTerminalRef>(null);
 *
 *   const handleData = (data: string) => {
 *     // Send to PTY backend
 *     pty.write(data);
 *   };
 *
 *   useEffect(() => {
 *     // Write incoming data
 *     pty.onData((data) => termRef.current?.write(data));
 *   }, []);
 *
 *   return (
 *     <GhosttyTerminal
 *       ref={termRef}
 *       onData={handleData}
 *       fontSize={14}
 *       autoFit
 *     />
 *   );
 * }
 * ```
 */

import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import { init, Terminal, FitAddon } from 'ghostty-web';
import type { ITerminalOptions, ITheme } from 'ghostty-web';
import { tmnlTerminalTheme } from './theme';

// ============================================================================
// Types
// ============================================================================

// ============================================================================
// Types
// ============================================================================

/**
 * Imperative handle exposed via ref
 */
export interface GhosttyTerminalRef {
  /** Write data to terminal */
  write: (data: string | Uint8Array) => void;
  /** Write data and add newline */
  writeln: (data: string) => void;
  /** Clear terminal screen */
  clear: () => void;
  /** Reset terminal state */
  reset: () => void;
  /** Resize terminal to specific dimensions */
  resize: (cols: number, rows: number) => void;
  /** Focus the terminal */
  focus: () => void;
  /** Blur the terminal */
  blur: () => void;
  /** Get current dimensions */
  getDimensions: () => { cols: number; rows: number };
  /** Get selection text */
  getSelection: () => string;
  /** Check if terminal has selection */
  hasSelection: () => boolean;
  /** Clear selection */
  clearSelection: () => void;
  /** Select all text */
  selectAll: () => void;
  /** Scroll to bottom */
  scrollToBottom: () => void;
  /** Scroll to top */
  scrollToTop: () => void;
  /** Get underlying Terminal instance (for advanced usage) */
  getTerminal: () => Terminal | null;
}

/**
 * Props for GhosttyTerminal component
 */
export interface GhosttyTerminalProps {
  /** Initial columns (default: 80) */
  cols?: number;
  /** Initial rows (default: 24) */
  rows?: number;
  /** Font size in pixels (default: 14) */
  fontSize?: number;
  /** Font family (default: monospace) */
  fontFamily?: string;
  /** Scrollback buffer size (default: 10000) */
  scrollback?: number;
  /** Enable cursor blinking (default: false) */
  cursorBlink?: boolean;
  /** Cursor style (default: 'block') */
  cursorStyle?: 'block' | 'underline' | 'bar';
  /** Theme configuration */
  theme?: ITheme;
  /** Auto-fit to container size (default: true) */
  autoFit?: boolean;
  /** Disable keyboard input (default: false) */
  disableStdin?: boolean;

  // Event callbacks
  /** Called when user types or pastes */
  onData?: (data: string) => void;
  /** Called when terminal is resized */
  onResize?: (cols: number, rows: number) => void;
  /** Called when terminal title changes (via escape sequence) */
  onTitleChange?: (title: string) => void;
  /** Called when bell character received */
  onBell?: () => void;
  /** Called when selection changes */
  onSelectionChange?: () => void;
  /** Called when terminal is ready */
  onReady?: (terminal: Terminal) => void;

  /** Additional className for container */
  className?: string;
  /** Additional style for container */
  style?: React.CSSProperties;
}

// ============================================================================
// WASM Initialization
// ============================================================================

// Track global init state
let wasmInitPromise: Promise<void> | null = null;
let wasmInitialized = false;

/**
 * Ensure WASM is initialized (idempotent)
 */
async function ensureWasmInit(): Promise<void> {
  if (wasmInitialized) return;

/**
 * Ensure WASM is initialized (idempotent)
 */
async function ensureWasmInit(): Promise<void> {
  if (wasmInitialized) return;

  if (!wasmInitPromise) {
    wasmInitPromise = init().then(() => {
      wasmInitialized = true;
    });
  }

  return wasmInitPromise;
}

// ============================================================================
// Component
// ============================================================================

export const GhosttyTerminal = forwardRef<GhosttyTerminalRef, GhosttyTerminalProps>(
  function GhosttyTerminal(props, ref) {
    const {
      cols = 80,
      rows = 24,
      fontSize = 14,
      fontFamily = "'JetBrains Mono', 'Fira Code', 'SF Mono', Menlo, monospace",
      scrollback = 10000,
      cursorBlink = false,
      cursorStyle = 'block',
      theme = tmnlTerminalTheme,
      autoFit = true,
      disableStdin = false,
      onData,
      onResize,
      onTitleChange,
      onBell,
      onSelectionChange,
      onReady,
      className,
      style,
    } = props;

    // Refs
    const containerRef = useRef<HTMLDivElement>(null);
    const terminalRef = useRef<Terminal | null>(null);
    const fitAddonRef = useRef<FitAddon | null>(null);

    // Callback refs to avoid stale closures - these always point to current props
    const onDataRef = useRef(onData);
    const onResizeRef = useRef(onResize);
    const onTitleChangeRef = useRef(onTitleChange);
    const onBellRef = useRef(onBell);
    const onSelectionChangeRef = useRef(onSelectionChange);

    // State
    const [isReady, setIsReady] = useState(false);
    const [error, setError] = useState<Error | null>(null);

    // Keep callback refs in sync with props (avoids stale closures)
    useEffect(() => {
      onDataRef.current = onData;
    }, [onData]);

    useEffect(() => {
      onResizeRef.current = onResize;
    }, [onResize]);

useEffect(() => {
      onResizeRef.current = onResize;
    }, [onResize]);

    useEffect(() => {
      onTitleChangeRef.current = onTitleChange;
    }, [onTitleChange]);

    useEffect(() => {
      onBellRef.current = onBell;
    }, [onBell]);

    useEffect(() => {
      onSelectionChangeRef.current = onSelectionChange;
    }, [onSelectionChange]);

    // Expose imperative API via ref
    useImperativeHandle(ref, () => ({
      write: (data: string | Uint8Array) => {
        terminalRef.current?.write(data);
      },
      writeln: (data: string) => {
        terminalRef.current?.writeln(data);
      },
      clear: () => {
        terminalRef.current?.clear();
      },
      reset: () => {
        terminalRef.current?.reset();
      },
      resize: (cols: number, rows: number) => {
        terminalRef.current?.resize(cols, rows);
      },
      focus: () => {
        terminalRef.current?.focus();
      },
      blur: () => {
        terminalRef.current?.blur();
      },
      getDimensions: () => {
        const term = terminalRef.current;
        return {
          cols: term?.cols ?? cols,
          rows: term?.rows ?? rows,
        };
      },
      getSelection: () => {
        return terminalRef.current?.getSelection() ?? '';
      },
      hasSelection: () => {
        return terminalRef.current?.hasSelection() ?? false;
      },
      clearSelection: () => {
        terminalRef.current?.clearSelection();
      },
      selectAll: () => {
        terminalRef.current?.selectAll();
      },
      scrollToBottom: () => {
        terminalRef.current?.scrollToBottom();
      },
      scrollToTop: () => {
        terminalRef.current?.scrollToTop();
      },
      getTerminal: () => terminalRef.current,
    }));

    // Initialize terminal
    useEffect(() => {
      if (!containerRef.current) return;

      let disposed = false;
      const container = containerRef.current;

// Initialize terminal
    useEffect(() => {
      if (!containerRef.current) return;

      let disposed = false;
      const container = containerRef.current;

      async function initTerminal() {
        try {
          // Ensure WASM is loaded
          await ensureWasmInit();

          if (disposed) return;

          // Create terminal options
          const options: ITerminalOptions = {
            cols,
            rows,
            fontSize,
            fontFamily,
            scrollback,
            cursorBlink,
            cursorStyle,
            theme,
            disableStdin,
            allowTransparency: true,
          };

          // Create terminal instance
          const term = new Terminal(options);
          terminalRef.current = term;

          // Create and load FitAddon
          const fitAddon = new FitAddon();
          fitAddonRef.current = fitAddon;
          term.loadAddon(fitAddon);

          // Wire up event handlers via refs (avoids stale closures when props change)
          term.onData((data) => {
            onDataRef.current?.(data);
          });

          term.onResize(({ cols, rows }) => {
            onResizeRef.current?.(cols, rows);
          });

          term.onTitleChange((title) => {
            onTitleChangeRef.current?.(title);
          });

          term.onBell(() => {
            onBellRef.current?.();
          });

          term.onSelectionChange(() => {
            onSelectionChangeRef.current?.();
          });

          // Open terminal in container
          term.open(container);

          // Setup auto-fit with FitAddon's built-in ResizeObserver (debounced)
          if (autoFit) {
            // Use FitAddon's observeResize() - handles ResizeObserver + debouncing
            fitAddon.observeResize();

            // Initial fit after container has dimensions
            requestAnimationFrame(() => {
              if (!disposed && fitAddonRef.current) {
                fitAddonRef.current.fit();
              }
            });
          }

          setIsReady(true);

// Initial fit after container has dimensions
            requestAnimationFrame(() => {
              if (!disposed && fitAddonRef.current) {
                fitAddonRef.current.fit();
              }
            });
          }

          setIsReady(true);

          // Notify ready callback
          if (onReady) {
            onReady(term);
          }
        } catch (err) {
          console.error('[GhosttyTerminal] Initialization failed:', err);
          setError(err instanceof Error ? err : new Error(String(err)));
        }
      }

      initTerminal();

      // Cleanup
      return () => {
        disposed = true;

        // FitAddon.dispose() handles its own ResizeObserver cleanup
        if (fitAddonRef.current) {
          fitAddonRef.current.dispose();
          fitAddonRef.current = null;
        }

        if (terminalRef.current) {
          terminalRef.current.dispose();
          terminalRef.current = null;
        }
      };
    }, []); // Only run once on mount

    // Update font size at runtime
    useEffect(() => {
      if (terminalRef.current && isReady) {
        terminalRef.current.options.fontSize = fontSize;
        if (autoFit && fitAddonRef.current) {
          // Delay fit to next frame so terminal can recalculate glyph metrics
          requestAnimationFrame(() => {
            fitAddonRef.current?.fit();
          });
        }
      }
    }, [fontSize, isReady, autoFit]);

    // Update font family at runtime
    useEffect(() => {
      if (terminalRef.current && isReady) {
        terminalRef.current.options.fontFamily = fontFamily;
        if (autoFit && fitAddonRef.current) {
          // Delay fit to next frame so terminal can recalculate glyph metrics
          requestAnimationFrame(() => {
            fitAddonRef.current?.fit();
          });
        }
      }
    }, [fontFamily, isReady, autoFit]);

// Update cursor settings at runtime
    useEffect(() => {
      if (terminalRef.current && isReady) {
        terminalRef.current.options.cursorBlink = cursorBlink;
        terminalRef.current.options.cursorStyle = cursorStyle;
      }
    }, [cursorBlink, cursorStyle, isReady]);

    // Update disableStdin at runtime
    useEffect(() => {
      if (terminalRef.current && isReady) {
        terminalRef.current.options.disableStdin = disableStdin;
      }
    }, [disableStdin, isReady]);

    // Error state
    if (error) {
      return (
        <div
          className={className}
          style={{
            ...style,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: '#0a0a0c',
            color: '#ff5555',
            fontFamily: 'monospace',
            fontSize: 'var(--tmnl-text-sm, 14px)',
            padding: '20px',
          }}
        >
          <div>
            <div style={{ marginBottom: '8px', fontWeight: 'bold' }}>
              Terminal initialization failed
            </div>
            <div style={{ opacity: 0.7 }}>{error.message}</div>
          </div>
        </div>
      );
    }

    return (
      <div
        ref={containerRef}
        className={className}
        style={{
          width: '100%',
          height: '100%',
          overflow: 'hidden',
          background: theme?.background ?? '#0a0a0c',
          ...style,
        }}
        data-terminal-ready={isReady}
      />
    );
  }
);

// ============================================================================
// Context
// ============================================================================

interface TerminalContextValue {
  termRef: RefObject<GhosttyTerminalRef | null>
  isReady: boolean
  setIsReady: (ready: boolean) => void
  dimensions: { cols: number; rows: number }
  setDimensions: (dims: { cols: number; rows: number }) => void
  zoom: number
  setZoom: (zoom: number) => void
  fontSize: number
  fontFamily: string
  mode: 'local' | 'remote'
  setMode: (mode: 'local' | 'remote') => void
  connection: ReturnType<typeof useTerminalConnection> | null
  sessionInfo: TerminalSessionInfo | null
  setSessionInfo: (info: TerminalSessionInfo | null) => void
}

const TerminalContext = createContext<TerminalContextValue | null>(null)

function useTerminalContext() {
  const ctx = useContext(TerminalContext)
  if (!ctx) {
    throw new Error('Terminal components must be used within Terminal.Root')
  }
  return ctx
}

// ============================================================================
// Root Component
// ============================================================================

interface TerminalRootProps {
  children: ReactNode
  /** Width of terminal container (CSS value) */
  width?: string | number
  /** Height of terminal container (CSS value) */
  height?: string | number
  /** Initial zoom level (default: 1.0) */
  initialZoom?: number
  /** Custom font family (default: Nerd Font stack) */
  fontFamily?: string
  /** Enable PTY/SSH connection (default: false = local echo) */
  enableConnection?: boolean
  /** Connection options when enableConnection is true */
  connectionOptions?: UseTerminalConnectionOptions
  /** Additional className */
  className?: string
}

function TerminalRoot({
  children,
  width = '100%',
  height = '100%',
  initialZoom = 1.0,
  fontFamily = NERD_FONT_FAMILY,
  enableConnection = false,
  connectionOptions,
  className,
}: TerminalRootProps) {
  const termRef = useRef<GhosttyTerminalRef | null>(null)
  const containerRef = useRef<HTMLDivElement | null>(null)
  const [isReady, setIsReady] = useState(false)
  const [dimensions, setDimensions] = useState({ cols: 0, rows: 0 })
  const [zoom, setZoom] = useState(initialZoom)
  const [mode, setMode] = useState<'local' | 'remote'>(enableConnection ? 'remote' : 'local')
  const [sessionInfo, setSessionInfo] = useState<TerminalSessionInfo | null>(null)

  // Compute actual font size from zoom
  const fontSize = Math.round(BASE_FONT_SIZE * zoom)

  // Terminal-scoped hotkeys (Ctrl+=/-, Ctrl+0)
  useTerminalHotkeys({
    zoom,
    setZoom,
    minZoom: MIN_ZOOM,
    maxZoom: MAX_ZOOM,
    zoomStep: ZOOM_STEP,
    enabled: isReady,
    containerRef,
  })

  // Optional connection hook
  const connection = enableConnection
    ? useTerminalConnection({
        ...connectionOptions,
        autoConnect: connectionOptions?.autoConnect ?? false,
        onReady: (session) => {
          setSessionInfo(session)
          connectionOptions?.onReady?.(session)
        },
      })
    : null

  const contextValue: TerminalContextValue = {
    termRef,
    isReady,
    setIsReady,
    dimensions,
    setDimensions,
    zoom,
    setZoom,
    fontSize,
    fontFamily,
    mode,
    setMode,
    connection,
    sessionInfo,
    setSessionInfo,
  }

return (
    <TerminalContext.Provider value={contextValue}>
      <div
        ref={containerRef}
        className={className}
        tabIndex={-1}
        style={{
          width: typeof width === 'number' ? `${width}px` : width,
          height: typeof height === 'number' ? `${height}px` : height,
          display: 'flex',
          flexDirection: 'column',
          background: '#0a0a0c',
          overflow: 'hidden',
          outline: 'none',
        }}
      >
        {children}
      </div>
    </TerminalContext.Provider>
  )
}

// ============================================================================
// Controls Component
// ============================================================================

interface TerminalControlsProps {
  /** Show zoom controls (default: true) */
  showZoom?: boolean
  /** Show mode toggle (default: true) */
  showModeToggle?: boolean
  /** Custom actions to render */
  actions?: ReactNode
  /** Additional className */
  className?: string
}

function TerminalControls({
  showZoom = true,
  showModeToggle = true,
  actions,
  className,
}: TerminalControlsProps) {
  const ctx = useTerminalContext()

  const zoomIn = useCallback(() => {
    ctx.setZoom(Math.min(MAX_ZOOM, ctx.zoom + ZOOM_STEP))
  }, [ctx])

  const zoomOut = useCallback(() => {
    ctx.setZoom(Math.max(MIN_ZOOM, ctx.zoom - ZOOM_STEP))
  }, [ctx])

  const resetZoom = useCallback(() => {
    ctx.setZoom(1.0)
  }, [ctx])

  const toggleMode = useCallback(() => {
    const newMode = ctx.mode === 'local' ? 'remote' : 'local'
    ctx.setMode(newMode)
    if (ctx.connection) {
      if (newMode === 'remote') {
        ctx.connection.connect()
        ctx.connection.attachTerminal(ctx.termRef)
      } else {
        ctx.connection.disconnect()
      }
    }
  }, [ctx])

return (
    <div
      className={className}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '8px 12px',
        borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
        gap: '12px',
        flexShrink: 0,
      }}
    >
      {/* Left: Status */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <TerminalIcon size={14} style={{ color: 'rgba(255,255,255,0.5)' }} />
        <span
          className="font-label uppercase tracking-[0.15em]"
          style={{
            fontSize: TMNL_FONT_SIZE.xs,
            color: 'rgba(255,255,255,0.7)',
          }}
        >
          Terminal
        </span>
        {ctx.dimensions.cols > 0 && (
          <span
            className="font-stats tracking-[0.08em]"
            style={{
              fontSize: TMNL_FONT_SIZE.xs,
              color: 'rgba(255,255,255,0.4)',
            }}
          >
            {ctx.dimensions.cols}×{ctx.dimensions.rows}
          </span>
        )}
      </div>

{/* Center: Mode Toggle */}
      {showModeToggle && ctx.connection && (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
            background: 'rgba(255,255,255,0.05)',
            borderRadius: '4px',
            padding: '2px',
          }}
        >
          <button
            onClick={() => ctx.mode !== 'local' && toggleMode()}
            className="font-label uppercase tracking-[0.1em]"
            style={{
              padding: '4px 8px',
              fontSize: TMNL_FONT_SIZE.xs,
              background: ctx.mode === 'local' ? 'rgba(255,255,255,0.15)' : 'transparent',
              color: ctx.mode === 'local' ? '#fff' : 'rgba(255,255,255,0.5)',
              border: 'none',
              borderRadius: '3px',
              cursor: 'pointer',
            }}
          >
            Local
          </button>
          <button
            onClick={() => ctx.mode !== 'remote' && toggleMode()}
            className="font-label uppercase tracking-[0.1em]"
            style={{
              padding: '4px 8px',
              fontSize: TMNL_FONT_SIZE.xs,
              background: ctx.mode === 'remote' ? 'rgba(34,211,238,0.2)' : 'transparent',
              color: ctx.mode === 'remote' ? '#22d3ee' : 'rgba(255,255,255,0.5)',
              border: 'none',
              borderRadius: '3px',
              cursor: 'pointer',
            }}
          >
            Remote
          </button>
        </div>
      )}

'not-allowed' : 'pointer',
                opacity: ctx.zoom >= MAX_ZOOM ? 0.3 : 1,
                color: '#fff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
              title="Zoom in"
            >
              <ZoomIn size={14} />
            </button>
          </>
        )}
        {actions}
      </div>
    </div>
  )
}

// ============================================================================
// Screen Component
// ============================================================================

interface TerminalScreenProps extends Omit<GhosttyTerminalProps, 'fontSize' | 'fontFamily' | 'ref'> {
  /** Handle local echo when not connected */
  localEcho?: boolean
}

const TerminalScreen = forwardRef<GhosttyTerminalRef, TerminalScreenProps>(
  function TerminalScreen(
    { onData, onResize, onReady, localEcho = true, ...props },
    forwardedRef
  ) {
    const ctx = useTerminalContext()

    // Unified ref: sync forwarded ref to context ref
    // This ensures ctx.termRef.current is always populated for internal operations
    const setRefs = useCallback(
      (instance: GhosttyTerminalRef | null) => {
        // Always update context ref
        ;(ctx.termRef as React.MutableRefObject<GhosttyTerminalRef | null>).current = instance
        // Also update forwarded ref if provided
        if (typeof forwardedRef === 'function') {
          forwardedRef(instance)
        } else if (forwardedRef) {
          ;(forwardedRef as React.MutableRefObject<GhosttyTerminalRef | null>).current = instance
        }
      },
      [ctx.termRef, forwardedRef]
    )

const handleData = useCallback(
      (data: string) => {
        if (ctx.mode === 'remote' && ctx.connection) {
          ctx.connection.write(data)
        } else if (localEcho && ctx.termRef.current) {
          // Local echo mode
          if (data === '\r') {
            ctx.termRef.current.write('\r\n')
            ctx.termRef.current.write('\x1b[1;35m❯\x1b[0m ')
          } else if (data === '\x7f') {
            ctx.termRef.current.write('\b \b')
          } else {
            ctx.termRef.current.write(data)
          }
        }
        onData?.(data)
      },
      [ctx, localEcho, onData]
    )

    const handleResize = useCallback(
      (cols: number, rows: number) => {
        ctx.setDimensions({ cols, rows })
        if (ctx.mode === 'remote' && ctx.connection?.connected) {
          ctx.connection.resize(cols, rows)
        }
        onResize?.(cols, rows)
      },
      [ctx, onResize]
    )

    const handleReady = useCallback(
      (terminal: import('ghostty-web').Terminal) => {
        ctx.setIsReady(true)
        ctx.termRef.current?.focus()
        if (localEcho && ctx.mode === 'local') {
          ctx.termRef.current?.write('\x1b[1;35m❯\x1b[0m ')
        }
        onReady?.(terminal)
      },
      [ctx, localEcho, onReady]
    )

    return (
      <div style={{ flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}>
        <GhosttyTerminal
          ref={setRefs}
          fontSize={ctx.fontSize}
          fontFamily={ctx.fontFamily}
          onData={handleData}
          onResize={handleResize}
          onReady={handleReady}
          autoFit
          {...props}
          style={{ position: 'absolute', inset: 0, ...props.style }}
        />
      </div>
    )
  }
)

