/**
 * PtyBackend — Local PTY terminal backend using bun-pty
 *
 * Implements TerminalBackend using @zenyr/bun-pty.
 * Spawns local shell processes with full PTY support.
 */

import { Effect, Layer, Stream, Scope, Deferred } from 'effect'
import { spawn as bunPtySpawn } from '@zenyr/bun-pty'
import { nanoid } from 'nanoid'
import {
  TerminalBackend,
  type TerminalBackendShape,
  type TerminalHandle,
  type TerminalExit,
  TerminalConnectError,
  TerminalWriteError,
  TerminalResizeError,
  TerminalStreamError,
} from './TerminalBackend'
import { PtyConfig } from './schemas'

// ─────────────────────────────────────────────────────────────────────────────
// PTY Backend Implementation
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Get default shell with zsh preference.
 * Uses $SHELL env var, falls back to zsh, then bash.
 */
function getDefaultShell(): string {
  if (process.platform === 'win32') {
    return 'powershell.exe'
  }
  // User's configured shell is best
  const userShell = process.env.SHELL
  if (userShell) {
    return userShell
  }
  // Default: prefer zsh
  return 'zsh'
}

const makePtyBackend = Effect.gen(function* () {
  const connect = (config: typeof PtyConfig.Type): Effect.Effect<
    TerminalHandle,
    TerminalConnectError,
    Scope.Scope
  > =>
    Effect.gen(function* () {
      const id = nanoid(12)
      const shell = config.shell ?? getDefaultShell()
      const args = config.args ?? []
      const cols = config.cols ?? 80
      const rows = config.rows ?? 24

// Spawn PTY
      const pty = yield* Effect.try({
        try: () =>
          bunPtySpawn(shell, args, {
            name: config.term ?? 'xterm-256color',
            cols,
            rows,
            cwd: config.cwd,
            env: config.env as Record<string, string> | undefined,
          }),
        catch: (e) =>
          new TerminalConnectError({
            reason: 'BackendError',
            message: `Failed to spawn PTY: ${e instanceof Error ? e.message : String(e)}`,
            cause: e,
          }),
      })

      // Create deferred for exit tracking
      const exitDeferred = yield* Deferred.make<TerminalExit>()

      // Create output stream using Stream.asyncPush
      const outputStream = Stream.asyncPush<string, TerminalStreamError>((emit) =>
        Effect.acquireRelease(
          Effect.sync(() => {
            // Register onData callback
            const dataDisposable = pty.onData((data) => {
              emit.single(data)
            })

            // Register onExit callback
            const exitDisposable = pty.onExit((event) => {
              Effect.runSync(
                Deferred.succeed(exitDeferred, {
                  exitCode: event.exitCode,
                  signal: event.signal,
                  reason: 'exit' as const,
                })
              )
              emit.end()
            })

            return { dataDisposable, exitDisposable }
          }),
          ({ dataDisposable, exitDisposable }) =>
            Effect.sync(() => {
              dataDisposable.dispose()
              exitDisposable.dispose()
            })
        )
      )

      // Register cleanup on scope finalization
      yield* Effect.addFinalizer(() =>
        Effect.sync(() => {
          try {
            pty.kill()
          } catch {
            // Already dead, ignore
          }
        })
      )

      // Build handle
      const handle: TerminalHandle = {
        id,
        backend: 'pty',
        cols: pty.cols,
        rows: pty.rows,
        pid: pty.pid,

// Build handle
      const handle: TerminalHandle = {
        id,
        backend: 'pty',
        cols: pty.cols,
        rows: pty.rows,
        pid: pty.pid,

        write: (data: string) =>
          Effect.try({
            try: () => {
              pty.write(data)
            },
            catch: (e) =>
              new TerminalWriteError({
                message: 'Failed to write to PTY',
                cause: e,
              }),
          }),

        resize: (newCols: number, newRows: number) =>
          Effect.try({
            try: () => {
              pty.resize(newCols, newRows)
            },
            catch: (e) =>
              new TerminalResizeError({
                message: 'Failed to resize PTY',
                cause: e,
              }),
          }),

        close: (signal?: string) =>
          Effect.sync(() => {
            pty.kill(signal)
          }),

        output: outputStream,

        exited: Deferred.await(exitDeferred),
      }

      return handle
    })

  return {
    connect: (config) => {
      // Validate config is PTY type (or treat as default PTY if no _tag)
      if (!('host' in config)) {
        return connect(config as typeof PtyConfig.Type)
      }
      return Effect.fail(
        new TerminalConnectError({
          reason: 'InvalidConfig',
          message: 'Expected PtyConfig but received SshConfig',
        })
      )
    },
    type: 'pty' as const,
  } satisfies TerminalBackendShape
})

// ─────────────────────────────────────────────────────────────────────────────
// Layer Export
// ─────────────────────────────────────────────────────────────────────────────

export const PtyBackendLive = Layer.effect(TerminalBackend, makePtyBackend)

/**
 * SshBackend — SSH terminal backend using ssh2
 *
 * Implements TerminalBackend using the ssh2 library.
 * Provides full SSH functionality: shell, resize, keepalive.
 */

import { Context, Effect, Layer, Stream, Scope, Deferred } from 'effect'
import { Client, type ClientChannel, type ConnectConfig } from 'ssh2'
import { nanoid } from 'nanoid'
import {
  TerminalBackend,
  type TerminalBackendShape,
  type TerminalHandle,
  type TerminalExit,
  TerminalConnectError,
  TerminalWriteError,
  TerminalResizeError,
  TerminalStreamError,
} from './TerminalBackend'
import { SshConfig, type SshAuthMethod } from './schemas'

// ─────────────────────────────────────────────────────────────────────────────
// SSH Backend Implementation
// ─────────────────────────────────────────────────────────────────────────────

const makeSshBackend = Effect.gen(function* () {
  const connect = (config: typeof SshConfig.Type): Effect.Effect<
    TerminalHandle,
    TerminalConnectError,
    Scope.Scope
  > =>
    Effect.gen(function* () {
      const id = nanoid(12)
      const cols = config.cols ?? 80
      const rows = config.rows ?? 24

      // Build ssh2 connection config
      const connectConfig = buildConnectConfig(config)

      // Create SSH client
      const client = new Client()

      // Create deferred for exit tracking
      const exitDeferred = yield* Deferred.make<TerminalExit>()

      // Connect to SSH server
      const channel = yield* Effect.async<ClientChannel, TerminalConnectError>((resume) => {
        let resolved = false

        const cleanup = () => {
          client.removeAllListeners()
        }

        client.on('ready', () => {
          // Request interactive shell with PTY
          client.shell(
            {
              cols,
              rows,
              term: config.term ?? 'xterm-256color',
            },
            (err, stream) => {
              if (resolved) return
              resolved = true

if (err) {
                cleanup()
                resume(
                  Effect.fail(
                    new TerminalConnectError({
                      reason: 'ConnectionFailed',
                      message: `Failed to open shell: ${err.message}`,
                      cause: err,
                    })
                  )
                )
                return
              }

              resume(Effect.succeed(stream))
            }
          )
        })

        client.on('error', (err) => {
          if (resolved) return
          resolved = true
          cleanup()

          const reason = err.message.includes('auth')
            ? 'AuthFailed'
            : err.message.includes('timeout')
              ? 'Timeout'
              : 'ConnectionFailed'

          resume(
            Effect.fail(
              new TerminalConnectError({
                reason,
                message: err.message,
                cause: err,
              })
            )
          )
        })

        client.on('timeout', () => {
          if (resolved) return
          resolved = true
          cleanup()
          resume(
            Effect.fail(
              new TerminalConnectError({
                reason: 'Timeout',
                message: 'SSH connection timed out',
              })
            )
          )
        })

        // Initiate connection
        client.connect(connectConfig)
      })

      // Wire up channel close to exit deferred
      channel.on('close', () => {
        Effect.runSync(
          Deferred.succeed(exitDeferred, {
            exitCode: 0,
            reason: 'disconnect' as const,
          })
        )
      })

      channel.on('exit', (code: number, signal?: string) => {
        Effect.runSync(
          Deferred.succeed(exitDeferred, {
            exitCode: code ?? 0,
            signal,
            reason: 'exit' as const,
          })
        )
      })

      // Create output stream using Stream.async
      const outputStream = Stream.async<string, TerminalStreamError>((emit) => {
        channel.on('data', (data: Buffer) => {
          emit.single(data.toString('utf-8'))
        })

channel.stderr.on('data', (data: Buffer) => {
          // Merge stderr into stdout stream
          emit.single(data.toString('utf-8'))
        })

        channel.on('close', () => {
          emit.end()
        })

        channel.on('error', (err: Error) => {
          emit.fail(
            new TerminalStreamError({
              message: err.message,
              cause: err,
            })
          )
        })
      })

      // Register cleanup on scope finalization
      yield* Effect.addFinalizer(() =>
        Effect.sync(() => {
          try {
            channel.close()
            client.end()
          } catch {
            // Already closed, ignore
          }
        })
      )

      // Track current dimensions (mutable for resize)
      let currentCols = cols
      let currentRows = rows

      // Build handle
      const handle: TerminalHandle = {
        id,
        backend: 'ssh',
        cols: currentCols,
        rows: currentRows,
        pid: undefined, // SSH doesn't expose remote PID

        write: (data: string) =>
          Effect.try({
            try: () => {
              channel.write(data)
            },
            catch: (e) =>
              new TerminalWriteError({
                message: 'Failed to write to SSH channel',
                cause: e,
              }),
          }),

        resize: (newCols: number, newRows: number) =>
          Effect.try({
            try: () => {
              channel.setWindow(newRows, newCols, 480, 640)
              currentCols = newCols
              currentRows = newRows
            },
            catch: (e) =>
              new TerminalResizeError({
                message: 'Failed to resize SSH channel',
                cause: e,
              }),
          }),

        close: () =>
          Effect.sync(() => {
            channel.close()
            client.end()
          }),

        output: outputStream,

        exited: Deferred.await(exitDeferred),
      }

      return handle
    })

close: () =>
          Effect.sync(() => {
            channel.close()
            client.end()
          }),

        output: outputStream,

        exited: Deferred.await(exitDeferred),
      }

      return handle
    })

  return {
    connect: (config) => {
      // Validate config is SSH type
      if ('host' in config && 'username' in config) {
        return connect(config as typeof SshConfig.Type)
      }
      return Effect.fail(
        new TerminalConnectError({
          reason: 'InvalidConfig',
          message: 'Expected SshConfig but received different config type',
        })
      )
    },
    type: 'ssh' as const,
  } satisfies TerminalBackendShape
})

// ─────────────────────────────────────────────────────────────────────────────
// Helper: Build ssh2 ConnectConfig from our SshConfig
// ─────────────────────────────────────────────────────────────────────────────

function buildConnectConfig(config: typeof SshConfig.Type): ConnectConfig {
  const base: ConnectConfig = {
    host: config.host,
    port: config.port ?? 22,
    username: config.username,
    keepaliveInterval: config.keepaliveInterval ?? 10000,
    keepaliveCountMax: config.keepaliveCountMax ?? 3,
    readyTimeout: config.readyTimeout ?? 20000,
  }

  // Add auth based on method
  const auth = config.auth
  switch (auth._tag) {
    case 'PrivateKey':
      return {
        ...base,
        privateKey: auth.privateKey,
        passphrase: auth.passphrase,
      }

    case 'Password':
      return {
        ...base,
        password: auth.password,
      }

    case 'Agent':
      return {
        ...base,
        agent: auth.agentSocket ?? process.env.SSH_AUTH_SOCK,
      }
  }
}

