const GLOW_COLORS: Record<NonNullable<ClickableAffordanceSlot['glow']>, string> = {
  orange: 'rgba(251, 146, 60, 0.6)',   // orange-400
  cyan: 'rgba(34, 211, 238, 0.6)',     // cyan-400
  violet: 'rgba(167, 139, 250, 0.6)',  // violet-400
  green: 'rgba(74, 222, 128, 0.6)',    // green-400
  red: 'rgba(248, 113, 113, 0.6)',     // red-400
  amber: 'rgba(251, 191, 36, 0.6)',    // amber-400
}

const GLOW_BORDERS: Record<NonNullable<ClickableAffordanceSlot['glow']>, string> = {
  orange: 'border-orange-500/50',
  cyan: 'border-cyan-500/50',
  violet: 'border-violet-500/50',
  green: 'border-green-500/50',
  red: 'border-red-500/50',
  amber: 'border-amber-500/50',
}

// =============================================================================
// TOOLTIP COMPONENT
// =============================================================================

function Tooltip({ text, visible }: { text: string; visible: boolean }) {
  if (!visible || !text) return null

// =============================================================================
// TOOLTIP COMPONENT
// =============================================================================

function Tooltip({ text, visible }: { text: string; visible: boolean }) {
  if (!visible || !text) return null

  return (
    <div
      className="absolute z-50 px-2 py-1 text-xs font-mono bg-neutral-900 border border-neutral-700 rounded shadow-lg whitespace-nowrap pointer-events-none"
      style={{
        bottom: '100%',
        left: '50%',
        transform: 'translateX(-50%)',
        marginBottom: '4px',
      }}
    >
      {text}
      {/* Arrow */}
      <div
        className="absolute w-2 h-2 bg-neutral-900 border-r border-b border-neutral-700 rotate-45"
        style={{
          bottom: '-5px',
          left: '50%',
          transform: 'translateX(-50%)',
        }}
      />
    </div>
  )
}

// =============================================================================
// GLOW RING COMPONENT
// =============================================================================

function GlowRing({
  color,
  pulse,
}: {
  color: NonNullable<ClickableAffordanceSlot['glow']>
  pulse?: boolean
}) {
  const glowColor = GLOW_COLORS[color]
  const borderClass = GLOW_BORDERS[color]

  return (
    <div
      className={`absolute inset-0 rounded border ${borderClass} pointer-events-none ${pulse ? 'animate-pulse' : ''}`}
      style={{
        boxShadow: `0 0 8px 2px ${glowColor}, inset 0 0 4px 1px ${glowColor}`,
      }}
    />
  )
}

// =============================================================================
// BADGE COMPONENT
// =============================================================================

function Badge({ text, color }: { text: string; color?: ClickableAffordanceSlot['glow'] }) {
  const bgClass = color ? `bg-${color}-900/50` : 'bg-neutral-800'
  const textClass = color ? `text-${color}-400` : 'text-neutral-400'

return (
    <span
      className={`absolute -top-1 -right-1 px-1 py-0.5 font-mono uppercase rounded ${bgClass} ${textClass} pointer-events-none`}
      style={{ fontSize: 'var(--tmnl-text-xs, 12px)' }}
    >
      {text}
    </span>
  )
}

// =============================================================================
// AFFORDANCE WRAPPER
// =============================================================================

function AffordanceWrapper({
  slot,
  targetId,
}: {
  slot: ClickableAffordanceSlot
  targetId: string
}) {
  const [isHovered, setIsHovered] = useState(false)

  return (
    <>
      {/* Hover detector (invisible overlay) */}
      <div
        className="absolute inset-0 z-10"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        style={{ cursor: slot.cursor ?? 'pointer' }}
      />

      {/* Glow ring */}
      {slot.glow && <GlowRing color={slot.glow} pulse={slot.pulse} />}

      {/* Tooltip */}
      {slot.tooltip && <Tooltip text={slot.tooltip} visible={isHovered} />}

      {/* Badge */}
      {slot.badge && <Badge text={slot.badge} color={slot.glow} />}
    </>
  )
}

// =============================================================================
// TRAIT DEFINITION
// =============================================================================

export const ClickableAffordance = createTrait<ClickableAffordanceSlot>({
  id: 'clickable-affordance',

  render: (slot, targetId) => <AffordanceWrapper slot={slot} targetId={targetId} />,

  style: (slot): CSSProperties => ({
    position: 'relative',
    cursor: slot.cursor ?? 'pointer',
  }),

  className: (slot) => {
    const classes: string[] = []
    if (slot.glow) {
      classes.push('hover:brightness-110', 'transition-all', 'duration-150')
    }
    return classes.join(' ')
  },
})

/**
 * Trait System Types
 *
 * A trait-based injection system for React components.
 * Components declare traits they implement, external code injects slots.
 */

import type { ReactNode, CSSProperties } from 'react'

// =============================================================================
// CORE TYPES
// =============================================================================

/**
 * Trait definition - the contract for an injection point
 *
 * @template TSlot - The shape of data that can be injected
 */
export interface Trait<TSlot> {
  /** Unique identifier for this trait type */
  readonly id: string

  /** Render the injected slot into JSX */
  render: (slot: TSlot, targetId: string) => ReactNode

  /** Optional: merge styles onto the host element */
  style?: (slot: TSlot) => CSSProperties

  /** Optional: merge className onto the host element */
  className?: (slot: TSlot) => string

  /** Optional: default slot value if none injected */
  defaultSlot?: TSlot
}

/**
 * Injection record - maps targetId to slot value
 */
export type TraitInjections<TSlot> = Map<string, TSlot>

/**
 * Registry - maps traitId to its injections
 */
export type TraitRegistry = Map<string, TraitInjections<unknown>>

// =============================================================================
// PROVIDER TYPES
// =============================================================================

export interface TraitProviderProps {
  children: ReactNode
}

export interface TraitContextValue {
  /** Get injections for a trait */
  getInjections: <TSlot>(trait: Trait<TSlot>) => TraitInjections<TSlot>

  /** Inject a slot into a target */
  inject: <TSlot>(trait: Trait<TSlot>, targetId: string, slot: TSlot) => void

  /** Clear an injection */
  clear: <TSlot>(trait: Trait<TSlot>, targetId: string) => void

  /** Clear all injections for a trait */
  clearAll: <TSlot>(trait: Trait<TSlot>) => void
}

// =============================================================================
// HOOK TYPES
// =============================================================================

export interface UseTraitResult<TSlot> {
  /** The injected slot, or null if none */
  slot: TSlot | null

// =============================================================================
// HOOK TYPES
// =============================================================================

export interface UseTraitResult<TSlot> {
  /** The injected slot, or null if none */
  slot: TSlot | null

  /** Rendered JSX from the trait's render function */
  rendered: ReactNode

  /** Styles to merge onto host element */
  style: CSSProperties

  /** ClassName to merge onto host element */
  className: string

  /** Whether this target has an active injection */
  isInjected: boolean
}

// =============================================================================
// BUILT-IN SLOT TYPES
// =============================================================================

/**
 * ClickableAffordance slot - makes elements obviously interactive
 */
export interface ClickableAffordanceSlot {
  /** Tooltip text on hover */
  tooltip?: string

  /** Glow ring color */
  glow?: 'orange' | 'cyan' | 'violet' | 'green' | 'red' | 'amber'

  /** Cursor style */
  cursor?: 'pointer' | 'grab' | 'cell' | 'zoom-in' | 'help'

  /** Pulsing animation */
  pulse?: boolean

  /** Badge text (small indicator) */
  badge?: string
}

/**
 * TooltipSlot - simple tooltip injection
 */
export interface TooltipSlot {
  content: ReactNode
  side?: 'top' | 'right' | 'bottom' | 'left'
  delay?: number
}

/**
 * PortalTargetSlot - named portal destination
 */
export interface PortalTargetSlot {
  content: ReactNode
  priority?: number
}

/**
 * useTrait Hook
 *
 * Components use this to declare they implement a trait and receive injections.
 * Supports single trait or array of traits (mixin composition).
 */

import { useMemo, type CSSProperties, type ReactNode } from 'react'
import type { Trait, UseTraitResult } from './types'
import { useTraitContextOptional } from './context'

// =============================================================================
// INTERNAL HELPERS
// =============================================================================

function resolveTraitResult<TSlot>(
  trait: Trait<TSlot>,
  targetId: string,
  ctx: ReturnType<typeof useTraitContextOptional>
): UseTraitResult<TSlot> {
  // No provider = no injections
  if (!ctx) {
    return {
      slot: trait.defaultSlot ?? null,
      rendered: trait.defaultSlot ? trait.render(trait.defaultSlot, targetId) : null,
      style: trait.defaultSlot && trait.style ? trait.style(trait.defaultSlot) : {},
      className: trait.defaultSlot && trait.className ? trait.className(trait.defaultSlot) : '',
      isInjected: false,
    }
  }

  const injections = ctx.getInjections(trait)
  const slot = injections.get(targetId) ?? trait.defaultSlot ?? null

  if (!slot) {
    return {
      slot: null,
      rendered: null,
      style: {},
      className: '',
      isInjected: false,
    }
  }

  return {
    slot,
    rendered: trait.render(slot, targetId),
    style: trait.style?.(slot) ?? {},
    className: trait.className?.(slot) ?? '',
    isInjected: injections.has(targetId),
  }
}

// =============================================================================
// MULTI-TRAIT RESULT TYPE
// =============================================================================

/**
 * Result when consuming multiple traits
 * Keyed by trait ID, with merged rendered/style/className at top level
 */
export interface UseTraitsResult<TTraits extends readonly Trait<unknown>[]> {
  /** Individual results keyed by trait ID */
  traits: { [K in TTraits[number]['id']]: UseTraitResult<unknown> }

  /** All rendered JSX stacked in order */
  rendered: ReactNode

/** All rendered JSX stacked in order */
  rendered: ReactNode

  /** All styles merged (later traits override earlier) */
  style: CSSProperties

  /** All classNames joined */
  className: string

  /** True if ANY trait has an active injection */
  isInjected: boolean
}

// =============================================================================
// SINGLE TRAIT HOOK
// =============================================================================

/**
 * Consume a single trait injection
 *
 * @param trait - The trait definition to consume
 * @param targetId - Unique identifier for this target
 * @returns Slot data, rendered JSX, styles, and className
 *
 * @example
 * function DmgBadge({ id }: { id: string }) {
 *   const { rendered, style, isInjected } = useTrait(ClickableAffordance, id)
 *
 *   return (
 *     <span style={style} className={isInjected ? 'injected' : ''}>
 *       DMG
 *       {rendered}
 *     </span>
 *   )
 * }
 */
export function useTrait<TSlot>(
  trait: Trait<TSlot>,
  targetId: string
): UseTraitResult<TSlot> {
  const ctx = useTraitContextOptional()
  return useMemo(() => resolveTraitResult(trait, targetId, ctx), [ctx, trait, targetId])
}

// =============================================================================
// MULTI-TRAIT HOOK
// =============================================================================

// =============================================================================
// MULTI-TRAIT HOOK
// =============================================================================

/**
 * Consume multiple traits (mixin composition)
 *
 * @param traits - Array of trait definitions to consume
 * @param targetId - Unique identifier for this target
 * @returns Keyed results plus merged rendered/style/className
 *
 * @example
 * function InteractiveCard({ id }: { id: string }) {
 *   const { traits, rendered, style, className } = useTraits(
 *     [ClickableAffordance, TooltipTrait, DraggableTrait],
 *     id
 *   )
 *
 *   // Access individual trait results
 *   const clickable = traits['clickable-affordance']
 *   const tooltip = traits['tooltip']
 *
 *   return (
 *     <div style={style} className={className}>
 *       Content
 *       {rendered}  // All trait renders stacked
 *     </div>
 *   )
 * }
 */
export function useTraits<TTraits extends readonly Trait<unknown>[]>(
  traits: TTraits,
  targetId: string
): UseTraitsResult<TTraits> {
  const ctx = useTraitContextOptional()

  return useMemo(() => {
    const results: Record<string, UseTraitResult<unknown>> = {}
    const renderedParts: ReactNode[] = []
    let mergedStyle: CSSProperties = {}
    const classNames: string[] = []
    let anyInjected = false

    // Process traits in order (later overrides earlier for styles)
    for (const trait of traits) {
      const result = resolveTraitResult(trait, targetId, ctx)
      results[trait.id] = result

      if (result.rendered) {
        renderedParts.push(result.rendered)
      }

      mergedStyle = { ...mergedStyle, ...result.style }

      if (result.className) {
        classNames.push(result.className)
      }

      if (result.isInjected) {
        anyInjected = true
      }
    }

mergedStyle = { ...mergedStyle, ...result.style }

      if (result.className) {
        classNames.push(result.className)
      }

      if (result.isInjected) {
        anyInjected = true
      }
    }

    return {
      traits: results as UseTraitsResult<TTraits>['traits'],
      rendered: renderedParts.length > 0 ? <>{renderedParts}</> : null,
      style: mergedStyle,
      className: classNames.join(' '),
      isInjected: anyInjected,
    }
  }, [ctx, traits, targetId])
}

/**
 * Check if any injections exist for a trait (useful for conditional rendering)
 */
export function useHasInjection<TSlot>(
  trait: Trait<TSlot>,
  targetId: string
): boolean {
  const ctx = useTraitContextOptional()

  return useMemo(() => {
    if (!ctx) return false
    const injections = ctx.getInjections(trait)
    return injections.has(targetId)
  }, [ctx, trait, targetId])
}

/**
 * Get all active injections for a trait (useful for debugging/devtools)
 */
export function useTraitInjections<TSlot>(
  trait: Trait<TSlot>
): Map<string, TSlot> {
  const ctx = useTraitContextOptional()

  return useMemo(() => {
    if (!ctx) return new Map()
    return ctx.getInjections(trait)
  }, [ctx, trait])
}

