/**
 * TMNL Variables — Persistence Layer
 *
 * localStorage adapter for persisting user customizations.
 * Uses Effect for error handling.
 */

import { Effect, Data, Schema } from 'effect'
import { Atom } from '@effect-atom/atom'
import { userValuesAtom, setUserValue, removeUserValue } from './atoms'
import type { ValueSource } from './types'

// ─────────────────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────────────────

const STORAGE_KEY = 'tmnl:variables:user'

// ─────────────────────────────────────────────────────────────────────────────
// Error Types
// ─────────────────────────────────────────────────────────────────────────────

/** Error reading from storage */
export class StorageReadError extends Data.TaggedError('StorageReadError')<{
  readonly cause: unknown
}> {}

/** Error writing to storage */
export class StorageWriteError extends Data.TaggedError('StorageWriteError')<{
  readonly cause: unknown
}> {}

/** Error parsing stored data */
export class StorageParseError extends Data.TaggedError('StorageParseError')<{
  readonly cause: unknown
}> {}

// ─────────────────────────────────────────────────────────────────────────────
// Storage Schema
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Schema for persisted variable values.
 */
const PersistedValue = Schema.Struct({
  value: Schema.Unknown,
  updatedAt: Schema.String, // ISO date string
})

const PersistedVariables = Schema.Record({
  key: Schema.String,
  value: PersistedValue,
})

// ─────────────────────────────────────────────────────────────────────────────
// Load from Storage
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Load persisted variables from localStorage.
 */
export const loadPersistedVariables = Effect.gen(function* () {
  // Read from localStorage
  const raw = yield* Effect.try({
    try: () => localStorage.getItem(STORAGE_KEY),
    catch: (cause) => new StorageReadError({ cause }),
  })

if (!raw) {
    // No persisted data
    return
  }

  // Parse JSON
  const parsed = yield* Effect.try({
    try: () => JSON.parse(raw),
    catch: (cause) => new StorageParseError({ cause }),
  })

  // Validate against schema
  const decoded = yield* Schema.decodeUnknown(PersistedVariables)(parsed).pipe(
    Effect.mapError((cause) => new StorageParseError({ cause }))
  )

  // Restore values to userValuesAtom
  for (const [variableId, stored] of Object.entries(decoded)) {
    setUserValue(variableId, stored.value)
  }

  yield* Effect.log(`Loaded ${Object.keys(decoded).length} persisted variables`)
})

/**
 * Synchronous load for initialization.
 * Catches errors and logs them.
 */
export function loadPersistedVariablesSync(): void {
  Effect.runSync(
    loadPersistedVariables.pipe(
      Effect.catchAll((err) =>
        Effect.logWarning('Failed to load persisted variables', err)
      )
    )
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Save to Storage
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Save current user values to localStorage.
 */
export const savePersistedVariables = Effect.gen(function* () {
  const userValues = Atom.get(userValuesAtom)

  // Convert to persistable format
  const toSave: Record<string, { value: unknown; updatedAt: string }> = {}
  for (const [variableId, stored] of userValues) {
    toSave[variableId] = {
      value: stored.value,
      updatedAt: stored.updatedAt.toISOString(),
    }
  }

  // Serialize and write
  yield* Effect.try({
    try: () => {
      const json = JSON.stringify(toSave, null, 2)
      localStorage.setItem(STORAGE_KEY, json)
    },
    catch: (cause) => new StorageWriteError({ cause }),
  })

  yield* Effect.log(`Saved ${Object.keys(toSave).length} variables to storage`)
})

yield* Effect.log(`Saved ${Object.keys(toSave).length} variables to storage`)
})

/**
 * Synchronous save.
 * Catches errors and logs them.
 */
export function savePersistedVariablesSync(): void {
  Effect.runSync(
    savePersistedVariables.pipe(
      Effect.catchAll((err) =>
        Effect.logWarning('Failed to save persisted variables', err)
      )
    )
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Clear Storage
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Clear all persisted variables.
 */
export const clearPersistedVariables = Effect.gen(function* () {
  yield* Effect.try({
    try: () => localStorage.removeItem(STORAGE_KEY),
    catch: (cause) => new StorageWriteError({ cause }),
  })

  // Also clear the atom
  Atom.set(userValuesAtom, new Map())

  yield* Effect.log('Cleared all persisted variables')
})

/**
 * Synchronous clear.
 */
export function clearPersistedVariablesSync(): void {
  Effect.runSync(
    clearPersistedVariables.pipe(
      Effect.catchAll((err) =>
        Effect.logWarning('Failed to clear persisted variables', err)
      )
    )
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Auto-Save Hook
// ─────────────────────────────────────────────────────────────────────────────

let saveTimeout: ReturnType<typeof setTimeout> | null = null

/**
 * Subscribe to userValuesAtom and auto-save on changes.
 * Debounced to avoid excessive writes.
 */
export function setupAutoSave(debounceMs = 1000): () => void {
  const unsubscribe = Atom.subscribe(userValuesAtom, () => {
    // Clear existing timeout
    if (saveTimeout) {
      clearTimeout(saveTimeout)
    }

    // Schedule save
    saveTimeout = setTimeout(() => {
      savePersistedVariablesSync()
      saveTimeout = null
    }, debounceMs)
  })

// Schedule save
    saveTimeout = setTimeout(() => {
      savePersistedVariablesSync()
      saveTimeout = null
    }, debounceMs)
  })

  return () => {
    unsubscribe()
    if (saveTimeout) {
      clearTimeout(saveTimeout)
      // Save immediately on cleanup
      savePersistedVariablesSync()
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// React Hook for Persistence
// ─────────────────────────────────────────────────────────────────────────────

import { useEffect } from 'react'

/**
 * React hook that sets up variable persistence.
 * Call once at app root.
 *
 * @example
 * ```tsx
 * function App() {
 *   useVariablePersistence()
 *   return <YourApp />
 * }
 * ```
 */
export function useVariablePersistence(options?: { debounceMs?: number }): void {
  useEffect(() => {
    // Load on mount
    loadPersistedVariablesSync()

    // Setup auto-save
    const cleanup = setupAutoSave(options?.debounceMs ?? 1000)

    // Save on unmount
    return () => {
      cleanup()
    }
  }, [options?.debounceMs])
}

/**
   * Create an editor-local binding for a variable.
   * Future sets in this editor will be local.
   */
  readonly makeLocal: (
    variableId: string
  ) => Effect.Effect<void, VariableNotFoundError>

  /**
   * Remove the current scope's override (revert to next level).
   */
  readonly reset: (
    variableId: string
  ) => Effect.Effect<void, VariableNotFoundError>

  /**
   * Get metadata about a variable.
   */
  readonly describe: (
    variableId: string
  ) => Effect.Effect<VariableMetadata, VariableNotFoundError>

  /**
   * List all registered variables.
   */
  readonly list: (group?: string) => Effect.Effect<readonly VariableMetadata[]>

  /**
   * Get all variable groups.
   */
  readonly groups: () => Effect.Effect<readonly string[]>
}

// ─────────────────────────────────────────────────────────────────────────────
// Service Tag
// ─────────────────────────────────────────────────────────────────────────────

/**
 * VariableService — Effect.Service for variable operations.
 */
export class VariableService extends Context.Tag('tmnl/variables/VariableService')<
  VariableService,
  VariableServiceImpl
>() {
  /**
   * Default implementation.
   */
  static Default = Layer.succeed(
    this,
    VariableService.of({
      // ───────────────────────────────────────────────────────────────────────
      // get
      // ───────────────────────────────────────────────────────────────────────
      get: <A>(variableId: string) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }

          const resolved = resolveValue(variableId, definition.default, definition.scope)

          return {
            value: resolved.value as A,
            source: resolved.source,
            isModified: resolved.source !== 'default',
          } as ResolvedValue<A>
        }),

return {
            value: resolved.value as A,
            source: resolved.source,
            isModified: resolved.source !== 'default',
          } as ResolvedValue<A>
        }),

      // ───────────────────────────────────────────────────────────────────────
      // set
      // ───────────────────────────────────────────────────────────────────────
      set: <A>(variableId: string, value: A) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }

          // Validate against schema
          const decodeResult = Schema.decodeUnknownEither(definition.schema)(value)
          if (decodeResult._tag === 'Left') {
            return yield* Effect.fail(
              new VariableValidationError({
                variableId,
                value,
                cause: decodeResult.left,
              })
            )
          }

          // Get old value for change event
          const oldResolved = resolveValue(variableId, definition.default, definition.scope)
          const oldValue = oldResolved.value

          // Call custom setter if defined
          if (definition.setter) {
            yield* (definition.setter as (v: unknown) => Effect.Effect<void, VariableSetterError>)(
              value
            )
          }

          // Determine where to store based on scope and current context
          const scope = definition.scope
          const editorId = Atom.get(currentEditorIdAtom)
          const workspaceId = Atom.get(currentWorkspaceIdAtom)

          let source: ValueSource = 'user'

          if (scope === 'editor' && editorId) {
            // Store in editor-local
            setEditorValue(editorId, variableId, value)
            source = 'editor'
          } else if (scope === 'workspace' && workspaceId) {
            // Store in workspace
            setWorkspaceValue(workspaceId, variableId, value)
            source = 'workspace'
          } else {
            // Store as user customization
            setUserValue(variableId, value)
            source = 'user'
          }

// Emit change event
          emitVariableChange({
            variableId,
            oldValue,
            newValue: value,
            source,
            timestamp: new Date(),
          })
        }),

      // ───────────────────────────────────────────────────────────────────────
      // setDefault
      // ───────────────────────────────────────────────────────────────────────
      setDefault: <A>(variableId: string, value: A) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }

          // Validate against schema
          const decodeResult = Schema.decodeUnknownEither(definition.schema)(value)
          if (decodeResult._tag === 'Left') {
            return yield* Effect.fail(
              new VariableValidationError({
                variableId,
                value,
                cause: decodeResult.left,
              })
            )
          }

          // Get old value for change event
          const userValues = Atom.get(userValuesAtom)
          const oldStored = userValues.get(variableId)
          const oldValue = oldStored?.value ?? definition.default

          // Call custom setter if defined
          if (definition.setter) {
            yield* (definition.setter as (v: unknown) => Effect.Effect<void, VariableSetterError>)(
              value
            )
          }

          // Store as user customization (global level)
          setUserValue(variableId, value)

          // Emit change event
          emitVariableChange({
            variableId,
            oldValue,
            newValue: value,
            source: 'user',
            timestamp: new Date(),
          })
        }),

      // ───────────────────────────────────────────────────────────────────────
      // makeLocal
      // ───────────────────────────────────────────────────────────────────────
      makeLocal: (variableId: string) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }

const editorId = Atom.get(currentEditorIdAtom)
          if (!editorId) {
            // No editor context — nothing to do
            return
          }

          // Copy current value to editor-local
          const resolved = resolveValue(variableId, definition.default, definition.scope)
          setEditorValue(editorId, variableId, resolved.value)
        }),

      // ───────────────────────────────────────────────────────────────────────
      // reset
      // ───────────────────────────────────────────────────────────────────────
      reset: (variableId: string) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }

          const editorId = Atom.get(currentEditorIdAtom)
          const workspaceId = Atom.get(currentWorkspaceIdAtom)

          // Get old value for change event
          const oldResolved = resolveValue(variableId, definition.default, definition.scope)
          const oldValue = oldResolved.value
          const oldSource = oldResolved.source

          // Remove from most specific scope first
          if (oldSource === 'editor' && editorId) {
            removeEditorValue(editorId, variableId)
          } else if (oldSource === 'workspace' && workspaceId) {
            removeWorkspaceValue(workspaceId, variableId)
          } else if (oldSource === 'user') {
            removeUserValue(variableId)
          }

          // Get new value after reset
          const newResolved = resolveValue(variableId, definition.default, definition.scope)

          // Call setter with new value if defined
          if (definition.setter) {
            yield* (definition.setter as (v: unknown) => Effect.Effect<void, VariableSetterError>)(
              newResolved.value
            ).pipe(Effect.catchAll(() => Effect.void))
          }

          // Emit change event
          emitVariableChange({
            variableId,
            oldValue,
            newValue: newResolved.value,
            source: newResolved.source,
            timestamp: new Date(),
          })
        }),

// Emit change event
          emitVariableChange({
            variableId,
            oldValue,
            newValue: newResolved.value,
            source: newResolved.source,
            timestamp: new Date(),
          })
        }),

      // ───────────────────────────────────────────────────────────────────────
      // describe
      // ───────────────────────────────────────────────────────────────────────
      describe: (variableId: string) =>
        Effect.gen(function* () {
          const definition = getVariableDefinition(variableId)
          if (!definition) {
            return yield* Effect.fail(new VariableNotFoundError({ variableId }))
          }
          return getVariableMetadata(definition)
        }),

      // ───────────────────────────────────────────────────────────────────────
      // list
      // ───────────────────────────────────────────────────────────────────────
      list: (group?: string) =>
        Effect.sync(() => {
          if (group) {
            return getVariableMetadataByGroup(group)
          }
          return getAllVariableMetadata()
        }),

      // ───────────────────────────────────────────────────────────────────────
      // groups
      // ───────────────────────────────────────────────────────────────────────
      groups: () => Effect.sync(() => getVariableGroups()),
    })
  )
}

/**
 * TMNL Variables — Type Definitions
 *
 * Effect Schema-based type system for the variables system.
 * Follows Emacs defvar/defcustom patterns with modern type safety.
 */

import { Schema, Effect, Data } from 'effect'

// ─────────────────────────────────────────────────────────────────────────────
// Branded Identifiers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Variable identifier — branded string for type safety.
 *
 * No regex validation — trust the developer at definition time.
 * Unknown IDs at access time return Option.none(), not errors.
 *
 * The brand provides compile-time safety without runtime gatekeeping.
 */
export const VariableId = Schema.String.pipe(
  Schema.nonEmptyString(),
  Schema.brand('VariableId')
)
export type VariableId = typeof VariableId.Type

/**
 * Workspace identifier — for workspace-scoped variables.
 */
export const WorkspaceId = Schema.String.pipe(Schema.brand('WorkspaceId'))
export type WorkspaceId = typeof WorkspaceId.Type

/**
 * Editor identifier — for editor-scoped (buffer-local) variables.
 */
export const EditorId = Schema.String.pipe(Schema.brand('EditorId'))
export type EditorId = typeof EditorId.Type

// ─────────────────────────────────────────────────────────────────────────────
// Variable Scope
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Variable scope determines where values can be overridden.
 *
 * - global: Single value across entire application
 * - workspace: Can have different values per workspace
 * - editor: Can have different values per editor (buffer-local)
 */
export const VariableScope = Schema.Literal('global', 'workspace', 'editor')
export type VariableScope = typeof VariableScope.Type

// ─────────────────────────────────────────────────────────────────────────────
// Variable Groups
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Variable Groups
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Standard variable groups for organization.
 * Extensible — custom groups are allowed.
 */
export const StandardVariableGroup = Schema.Literal(
  'editor',
  'appearance',
  'keybindings',
  'extensions',
  'debug',
  'system'
)
export type StandardVariableGroup = typeof StandardVariableGroup.Type

/**
 * Variable group — either standard or custom string.
 */
export const VariableGroup = Schema.Union(
  StandardVariableGroup,
  Schema.String.pipe(Schema.minLength(1))
)
export type VariableGroup = typeof VariableGroup.Type

// ─────────────────────────────────────────────────────────────────────────────
// Error Types
// ─────────────────────────────────────────────────────────────────────────────

/** Variable not found */
export class VariableNotFoundError extends Data.TaggedError('VariableNotFoundError')<{
  readonly variableId: string
}> {}

/** Variable validation failed */
export class VariableValidationError extends Data.TaggedError('VariableValidationError')<{
  readonly variableId: string
  readonly value: unknown
  readonly cause: unknown
}> {}

/** Variable setter failed */
export class VariableSetterError extends Data.TaggedError('VariableSetterError')<{
  readonly variableId: string
  readonly cause: unknown
}> {}

/** Variable already registered */
export class VariableAlreadyExistsError extends Data.TaggedError('VariableAlreadyExistsError')<{
  readonly variableId: string
}> {}

/** Union of all variable errors */
export type VariableError =
  | VariableNotFoundError
  | VariableValidationError
  | VariableSetterError
  | VariableAlreadyExistsError

// ─────────────────────────────────────────────────────────────────────────────
// Variable Definition
// ─────────────────────────────────────────────────────────────────────────────

/**
   * Show in settings UI.
   * If true, this is a user-facing option (like defcustom).
   * If false, this is an internal variable (like defvar).
   */
  readonly customize: boolean
}

// ─────────────────────────────────────────────────────────────────────────────
// Variable Metadata (for introspection)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Variable metadata — runtime-inspectable information about a variable.
 * Used by settings UI, documentation, etc.
 */
export const VariableMetadata = Schema.Struct({
  /** Variable identifier */
  id: Schema.String,

  /** Human-readable description */
  description: Schema.String,

  /** Category group */
  group: Schema.String,

  /** Scope type */
  scope: VariableScope,

  /** Safe for file-local binding */
  safe: Schema.Boolean,

  /** Show in settings UI */
  customize: Schema.Boolean,

  /** Schema type description (for UI hints) */
  typeDescription: Schema.String,

  /** Whether variable has a custom setter */
  hasSetter: Schema.Boolean,
})
export type VariableMetadata = typeof VariableMetadata.Type

// ─────────────────────────────────────────────────────────────────────────────
// Variable Value with Source
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Value source — where the current value came from.
 */
export const ValueSource = Schema.Literal(
  'default', // From variable definition
  'user', // User customization (persisted)
  'workspace', // Workspace-specific override
  'editor', // Editor-local override
  'file' // File-local variable (future)
)
export type ValueSource = typeof ValueSource.Type

/**
 * Resolved variable value with provenance.
 */
export interface ResolvedValue<A> {
  /** The current value */
  readonly value: A

  /** Where this value came from */
  readonly source: ValueSource

  /** Whether value differs from default */
  readonly isModified: boolean
}

/** Where this value came from */
  readonly source: ValueSource

  /** Whether value differs from default */
  readonly isModified: boolean
}

// ─────────────────────────────────────────────────────────────────────────────
// Variable Change Event
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Variable change event — emitted when a variable's value changes.
 */
export const VariableChangeEvent = Schema.Struct({
  /** Variable that changed */
  variableId: Schema.String,

  /** Previous value */
  oldValue: Schema.Unknown,

  /** New value */
  newValue: Schema.Unknown,

  /** Source of the change */
  source: ValueSource,

  /** Timestamp */
  timestamp: Schema.DateFromSelf,
})
export type VariableChangeEvent = typeof VariableChangeEvent.Type

/**
 * TMNL Variables v2 — Variable Module
 *
 * Public API for defining and working with variables.
 * Analogous to Effect's Config module.
 *
 * @example
 * ```typescript
 * import { Variable } from '@/lib/variables/v2'
 *
 * // Define a variable (registered at load time)
 * const tabWidth = Variable.define({
 *   id: 'editor.tabWidth',
 *   schema: Schema.Number.pipe(Schema.int(), Schema.between(1, 16)),
 *   default: 4,
 *   description: 'Number of spaces per tab',
 * })
 *
 * // Access by string ID at runtime (no import needed)
 * const value = yield* Variable.get('editor.tabWidth')
 * // → Option.some(4)
 *
 * // With type assertion
 * const typed = yield* Variable.getAs('editor.tabWidth', Schema.Number)
 * // → Option.some(4) with type number
 * ```
 */

import { Effect, Option, Schema, pipe } from 'effect';
import { Atom } from '@effect-atom/atom';
import * as internal from './internal/core';
import * as scope from './internal/scope';

// Note: Atom import is used for bridge atoms at the bottom of this file

// ─────────────────────────────────────────────────────────────────────────────
// Re-exports
// ─────────────────────────────────────────────────────────────────────────────

export {
  /** Variable TypeId symbol */
  VariableTypeId,
  /** Variable definition type */
  type VariableDef,
  /** Check if value is a VariableDef */
  isVariableDef,
  /** Variable errors */
  VariableMissingError,
  VariableValidationError,
  VariableOrError,
  type VariableError,
} from './internal/core';

export {
  /** Value source type */
  type ValueSource,
  /** Resolved value with provenance */
  type ResolvedValue,
  /** Workspace ID type */
  type WorkspaceId,
  /** Editor ID type */
  type EditorId,
} from './internal/scope';

// ─────────────────────────────────────────────────────────────────────────────
// Define API
// ─────────────────────────────────────────────────────────────────────────────

export interface DefineOptions<A> {
  /** Unique variable identifier (e.g., "editor.tabWidth") */
  readonly id: string;
  /**
   * Explicit group for categorization.
   * If omitted, inferred from ID (first segment before dot, or entire ID if no dots).
   */
  readonly group?: string;
  /** Effect Schema for value validation (supports Literal, String, Number, etc.) */
  readonly schema: Schema.Schema<any, any, never>;
  /**
   * Default value, OR a function that computes from lower scope.
   *
   * @example
   * ```typescript
   * // Static default
   * default: 4
   *
   * // Computed default (defuFn style)
   * default: (lower) => lower * 2
   * ```
   */
  readonly default: A | ((lower: A) => A);
  /** Human-readable description */
  readonly description: string;
}

/**
 * Define a variable with schema validation.
 * Automatically registered in the global registry.
 *
 * @example
 * ```typescript
 * const fontSize = Variable.define({
 *   id: 'editor.fontSize',
 *   schema: Schema.Number.pipe(Schema.between(8, 72)),
 *   default: 14,
 *   description: 'Font size in pixels',
 * })
 *
 * // With computed default
 * const lineHeight = Variable.define({
 *   id: 'editor.lineHeight',
 *   schema: Schema.Number,
 *   default: (fontSize) => fontSize * 1.5, // Based on lower scope
 *   description: 'Line height in pixels',
 * })
 * ```
 */
export const define = <A>(
  options: DefineOptions<A>
): internal.VariableDef<A> => {
  const def = internal.makeVariableDef(options);
  return internal.registerVariable(def);
};

// ─────────────────────────────────────────────────────────────────────────────
// Runtime Access API — The Key Feature
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Get a variable by string ID.
 * Returns Option.none() if not found.
 *
 * THIS IS THE RUNTIME ACCESS PATTERN — no import of the variable definition needed.
 *
 * @example
 * ```typescript
 * // In config.ts (loaded at startup)
 * Variable.define({ id: 'editor.tabWidth', ... })
 *
 * // Anywhere else (no import needed)
 * const tabWidth = yield* Variable.get('editor.tabWidth')
 * // → Option.some(4)
 * ```
 */
export const get = (id: string): Effect.Effect<Option.Option<unknown>> => {
  const provider = scope.createScopeChain();
  return internal.loadById(provider, id);
};

/**
 * Get a variable by string ID with type assertion.
 * Returns Option.none() if not found or wrong type.
 *
 * @example
 * ```typescript
 * const tabWidth = yield* Variable.getAs('editor.tabWidth', Schema.Number)
 * // → Option.some(4) with type number
 * ```
 */
export const getAs = <A>(
  id: string,
  schema: Schema.Schema<A, unknown>
): Effect.Effect<Option.Option<A>> => {
  const provider = scope.createScopeChain();
  return internal.loadByIdAs(provider, id, schema);
};

/**
 * Get a variable by string ID, throwing if not found.
 * Use Option-based `get()` for graceful handling.
 *
 * @example
 * ```typescript
 * const tabWidth = yield* Variable.getOrDie('editor.tabWidth')
 * ```
 */
export const getOrDie = (
  id: string
): Effect.Effect<unknown, internal.VariableError> =>
  pipe(
    Effect.sync(() => internal.getVariableDefinition(id)),
    Effect.flatMap(
      Option.match({
        onNone: () =>
          Effect.fail(
            new internal.VariableMissingError({
              variableId: id,
              path: ['registry'],
            })
          ),
        onSome: (def) => {
          const provider = scope.createScopeChain();
          return provider.load(def);
        },
      })
    )
  );

/**
 * Get a variable with full resolution info (value + source + isModified).
 *
 * @example
 * ```typescript
 * const resolved = yield* Variable.resolve('editor.tabWidth')
 * // → { value: 4, source: 'user', isModified: true }
 * ```
 */
export const resolve = (
  id: string
): Effect.Effect<Option.Option<scope.ResolvedValue<unknown>>> =>
  pipe(
    Effect.sync(() => internal.getVariableDefinition(id)),
    Effect.flatMap(
      Option.match({
        onNone: () => Effect.succeed(Option.none()),
        onSome: (def) =>
          pipe(
            scope.loadWithSource(def),
            Effect.map(Option.some),
            Effect.catchAll(() => Effect.succeed(Option.none()))
          ),
      })
    )
  );

// ─────────────────────────────────────────────────────────────────────────────
// Mutation API
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// Mutation API
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Set a variable value in the user scope.
 * Validates against the variable's schema.
 *
 * @example
 * ```typescript
 * yield* Variable.set('editor.tabWidth', 2)
 * ```
 */
export const set = (
  id: string,
  value: unknown
): Effect.Effect<void, internal.VariableError> => {
  const maybeDef = internal.getVariableDefinition(id);
  if (Option.isNone(maybeDef)) {
    return Effect.fail(
      new internal.VariableMissingError({
        variableId: id,
        path: ['registry'],
      })
    );
  }
  const def = maybeDef.value;

  // Validate against schema
  const decoded = Schema.decodeUnknownEither(def.schema)(value);
  if (decoded._tag === 'Left') {
    return Effect.fail(
      new internal.VariableValidationError({
        variableId: id,
        value,
        cause: decoded.left,
      })
    );
  }
  // Store in user scope
  scope.setUserValue(id, decoded.right);
  return Effect.void;
};

/**
 * Reset a variable to its default value (remove user customization).
 *
 * @example
 * ```typescript
 * yield* Variable.reset('editor.tabWidth')
 * ```
 */
export const reset = (id: string): Effect.Effect<void> =>
  Effect.sync(() => scope.removeUserValue(id));

/**
 * Make a variable buffer-local (editor-scoped).
 * Copies current value to editor scope.
 *
 * @example
 * ```typescript
 * yield* Variable.makeLocal('editor.tabWidth')
 * ```
 */
export const makeLocal = (
  id: string
): Effect.Effect<void, internal.VariableError> =>
  pipe(
    get(id),
    Effect.flatMap((maybeValue) => {
      if (Option.isNone(maybeValue)) {
        return Effect.fail(
          new internal.VariableMissingError({
            variableId: id,
            path: ['registry'],
          })
        );
      }
      const value = maybeValue.value;
      // Use registry for synchronous access
      const editorId = scope.variablesRegistry.get(scope.currentEditorAtom);
      if (editorId) {
        scope.setEditorValue(editorId, id, value);
      }
      return Effect.void;
    })
  );

// ─────────────────────────────────────────────────────────────────────────────
// Introspection API
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Get metadata for a variable definition.
 *
 * @example
 * ```typescript
 * const meta = Variable.describe('editor.tabWidth')
 * // → Option.some({ id: 'editor.tabWidth', description: '...', ... })
 * ```
 */
export const describe = (
  id: string
): Option.Option<{
  readonly id: string;
  readonly description: string;
  readonly hasComputedDefault: boolean;
}> =>
  pipe(
    internal.getVariableDefinition(id),
    Option.map((def) => ({
      id: def.id,
      description: def.description,
      hasComputedDefault: typeof def.default === 'function',
    }))
  );

/**
 * List all registered variable IDs.
 *
 * @example
 * ```typescript
 * const ids = Variable.list()
 * // → ['editor.tabWidth', 'editor.fontSize', ...]
 * ```
 */
export const list = (): ReadonlyArray<string> =>
  Array.from(internal.getAllVariableDefinitions().keys());

/**
 * List variables by group.
 * Uses explicit group field from definitions, not ID parsing.
 *
 * @example
 * ```typescript
 * const editorVars = Variable.listByGroup('editor')
 * // → ['editor.tabWidth', 'editor.fontSize', ...]
 * ```
 */
export const listByGroup = (group: string): ReadonlyArray<string> => {
  const allDefs = internal.getAllVariableDefinitions();
  const result: string[] = [];
  for (const [id, def] of allDefs) {
    if (def.group === group) {
      result.push(id);
    }
  }
  return result;
};

/**
 * Get unique groups from all registered variables.
 * Uses explicit group field from definitions, not ID parsing.
 *
 * @example
 * ```typescript
 * const groups = Variable.groups()
 * // → ['editor', 'appearance', 'keybindings']
 * ```
 */
export const groups = (): ReadonlyArray<string> => {
  const allDefs = internal.getAllVariableDefinitions();
  const allGroups = new Set<string>();
  for (const def of allDefs.values()) {
    allGroups.add(def.group);
  }
  return Array.from(allGroups).sort();
};

